/**
 * The fleet card (docs/social.html, "The fleet card"): one fleet, player's or your own, as the social
 * window's right column. Built from what is already in hand, filled in as more arrives: the server's board
 * line (numbers, the fourteen days, the goods it moves most, its vehicles as saved), who is signed in and
 * where (net/remote.ts), their HQ from the deed registry, the friends list, and the card record the server
 * keeps for the social window (their profile: motto, showcase, pinned metrics, what to show), asked for
 * once and kept for ten minutes.
 *
 * Two hero stills (render/heroStage.ts): their HQ, when its island is in memory, and the showcase vehicle
 * turning on the plinth. Stills are drawn after the card is on the page, one a redraw, and cached per key.
 *
 * Your own card has an Edit view in place of the social buttons: how others see you (shared/social.ts).
 */
import { esc, money } from '../game/cargoHud';
import { METRICS } from '../game/metrics';
import { lastSeen } from '../game/standings';
import { defOf } from '../game/fleet';
import { CARGO } from '../game/cargoTypes';
import { badgeUrl } from '../render/fleetBadges';
import { hero } from '../render/heroStage';
import type { HeroSpec } from '../game/missions/model';
import type { Parts } from '../game/parts';
import type { RemoteSeen } from './remote';
import type { OnlineExtra } from './online';
import type { Welcome, CellDoc } from '../../shared/protocol';
import type { BoardRow, ClientMsg, FriendRow, Pid, ServerMsg, Who } from '../../shared/protocol';
import { BACKDROPS, MOTTO_MAX, PINS_MAX, PRONOUNS_MAX, TITLE_INFO, shows, type Backdrop, type Profile, type TitleId } from '../../shared/social';
import type { Neighbours } from './neighbours';

const KIND_ICON = { land: '🚗', water: '⛵', air: '🚁', rail: '🚂' } as const;
const BACKDROP_LABEL: Record<Backdrop, string> = { county: 'Golden plinth', dusk: 'Dusk', night: 'Night with lamps', harbour: 'Harbour blue', high: 'High country', plain: 'Plain' };
/** Minutes a card record is kept before it is asked for again, and seconds between asks for the same one. */
const KEEP_MIN = 10, ASK_S = 5;
const BARS = '▁▂▃▄▅▆▇█';

export interface MyFleet {
  brand: { name: string; primary: number; accent: number; logo: string } | null;
  units: { uid: number; model: string; name: string; parts?: Parts }[];
  /** The unit at the wheel, by uid. */
  ridden: number | null;
  hq: { key: string; name: string; grade: number } | null;
  /** The doors the fleet holds, for the showcase building (phase 4). */
  deeds: { key: string; name: string }[];
}

export interface FleetCardHost {
  rows(): BoardRow[];
  me(): Pid | null;
  crewId(): string | null;
  /** Who somebody is, as the server has named them (null: never heard of). */
  who(pid: Pid): Who | null;
  /** The cell they are in while signed in, else null. */
  cellOf(pid: Pid): string | null;
  /** The cell the player is in, "cx,cz". */
  here(): string;
  /** Their vehicles out on the map, theirs first; null when they aren't signed in. */
  fleetOf(pid: Pid): RemoteSeen[] | null;
  /** Their HQ's lot and name, when the server has told of one. */
  hqOf(pid: Pid): { key: string; name: string } | null;
  /** A building as the hero stage draws it, when its island is in memory; else null. */
  buildingSpec(key: string): HeroSpec | null;
  friends(): FriendRow[];
  post(m: ClientMsg): void;
  friend(pid: Pid, on: boolean): void;
  follow(pid: Pid, name: string): void;
  followUnit(pid: Pid, uid: number | null): void;
  viewHq(key: string, name: string): void;
  whisper(name: string): void;
  say(title: string, body: string): void;
  modelName(id: string): string;
  /** My own fleet, for my card and the showcase choices. */
  mine(): MyFleet;
  /** My own numbers live (game/metrics.ts), with net worth by day newest first. */
  myMetrics(): { v: Record<string, number>; hist: number[] };
  myGoods(): [string, number][];
  myGilded(): boolean;
  /** Where another player's vehicle is, in words. */
  whereIs(r: RemoteSeen): string;
  /** The dealings ledger (net/neighbours.ts): the pair with this player, and its bars and towns. */
  neighbours(): Neighbours | null;
  /** Open the Neighbours tab on this player (Compare). */
  compare(pid: string): void;
  /** My livery, for my side of the bars. */
  myPrimary(): number;
  /** Phase 4: the titles a player wears this week and leads as it stands (net/titles.ts); a door's name by its lot key. */
  titlesOf(pid: Pid): { worn: TitleId[]; leading: TitleId[] };
  deedName(key: string): string | null;
  /** Phase 3 (docs/social.html): their thread in the Inbox; are they in my fleet; may I invite; have I muted them. */
  message(pid: Pid): void;
  sameFleet(pid: Pid): boolean;
  mayInvite(): boolean;
  muted(pid: Pid): boolean;
}

interface CardRecord { profile: Profile; founded: number; crew?: { id: Pid; name: string; online: boolean }[]; top?: { id: Pid; name: string }[]; fh?: number; hearted?: boolean; whereOk?: boolean; at: number }

export class FleetCard implements OnlineExtra {
  private cards = new Map<Pid, CardRecord>();
  private asked = new Map<Pid, number>();
  private stills = new Map<string, string>();
  private specs = new Map<string, { spec: HeroSpec; tint: number }>();
  /** My own card is being edited. */
  private editing = false;
  /** The window redraws when a card record comes in. */
  onData: () => void = () => {};

  constructor(private host: FleetCardHost) {}

  // ---- the online session (OnlineExtra) ----
  welcome(_w: Welcome): void { this.cards.clear(); this.asked.clear(); this.editing = false; }
  cell(_k: string, _doc: CellDoc): void { /* nothing per cell */ }
  got(m: ServerMsg): boolean {
    if (m.t !== 'card') return false;
    this.cards.set(m.id, { profile: m.profile ?? {}, founded: m.founded, crew: m.crew, top: m.top, fh: m.fh, hearted: m.hearted, whereOk: m.whereOk, at: performance.now() });
    this.onData();
    return true;
  }
  ready(): void { /* asked for when a card is shown */ }
  frame(): void { /* nothing per frame */ }
  forget(): void { /* nothing per cell */ }
  reset(): void { this.cards.clear(); this.asked.clear(); this.stills.clear(); this.editing = false; }

  /** The card record, asking the server when there is none or it is old. */
  private record(pid: Pid): CardRecord | null {
    const had = this.cards.get(pid) ?? null;
    const now = performance.now();
    if ((!had || now - had.at > KEEP_MIN * 60000) && now - (this.asked.get(pid) ?? -1e9) > ASK_S * 1000) {
      this.asked.set(pid, now);
      this.host.post({ t: 'card', id: pid });
    }
    return had;
  }

  /** My own profile as last heard (the Edit view starts from it). */
  myProfile(): Profile { const me = this.host.me(); return (me && this.cards.get(me)?.profile) || {}; }

  /** The row for a player, or a stand-in from who they are when their game has never saved. */
  private rowOf(pid: Pid): BoardRow | null {
    const row = this.host.rows().find((r) => r.id === pid);
    if (row) return row;
    const who = this.host.who(pid);
    if (!who) return null;
    return { id: pid, name: who.brand?.name ?? who.name, by: who.name, cpu: false, worth: 0, units: 0, towns: 0, primary: who.brand?.primary ?? 0xe2412f, accent: who.brand?.accent ?? 0xffffff, logo: who.brand?.logo ?? '', online: !!this.host.cellOf(pid) };
  }

  private away(c: string): string {
    const here = this.host.here().split(',').map(Number);
    const [cx, cz] = c.split(',').map(Number);
    const dx = cx - here[0], dz = cz - here[1];
    const n = Math.max(Math.abs(dx), Math.abs(dz));
    if (n === 0) return 'in this county';
    const compass = ['east', 'south-east', 'south', 'south-west', 'west', 'north-west', 'north', 'north-east'][((Math.round(Math.atan2(dz, dx) / (Math.PI / 4)) % 8) + 8) % 8];
    return `${n} ${n === 1 ? 'county' : 'counties'} ${compass}`;
  }

  /** A still's placeholder: drawn after the card is on the page (afterRender), cached by key. */
  private still(key: string, spec: HeroSpec | null, tint: number, plate: string, caption: string): string {
    let img: string;
    if (!spec) img = `<div class="fc-plate">${plate}</div>`;
    else {
      this.specs.set(key, { spec, tint });
      const src = this.stills.get(key);
      img = `<img class="fc-still" alt="" data-still="${esc(key)}"${src ? ` src="${src}"` : ''}>`;
    }
    return `<figure class="fc-stage">${img}<figcaption>${caption}</figcaption></figure>`;
  }

  /** Stills not yet drawn in these elements: one a redraw, so a card is readable before its pictures are. */
  afterRender(...roots: HTMLElement[]): void {
    for (const root of roots) {
      const img = root.querySelector<HTMLImageElement>('img[data-still]:not([src])');
      if (!img) continue;
      const key = img.dataset.still!;
      const s = this.specs.get(key);
      if (!s) continue;
      let url = '';
      try { url = hero.still(s.spec, s.tint, 420, 300); } catch { url = ''; }
      if (url) { this.stills.set(key, url); img.src = url; }
      else img.replaceWith(Object.assign(document.createElement('div'), { className: 'fc-plate', textContent: 'Can’t be drawn here' }));
      // the next one on the next redraw
      setTimeout(() => this.onData(), 60);
      return;
    }
  }

  private tiles(v: Record<string, number | undefined>, hist: number[], hearts: number | undefined, pins: string[]): string {
    const tile = (label: string, value: string, sub = '', cls = '') => `<div class="fc-tile${cls}"><small>${esc(label)}</small><b>${value}</b>${sub ? `<span>${sub}</span>` : ''}</div>`;
    const spark = (() => {
      const xs = hist.slice(0, 14).reverse();
      if (xs.length < 2) return '';
      const lo = Math.min(...xs), hi = Math.max(...xs);
      return `<i class="fc-spark">${xs.map((q) => BARS[hi > lo ? Math.min(7, Math.floor(((q - lo) / (hi - lo)) * 7.99)) : 3]).join('')}</i>`;
    })();
    const n = (k: string) => v[k] === undefined ? '—' : (v[k] as number).toLocaleString('en-US');
    let out = tile('Net worth', v.worth === undefined ? '—' : money(v.worth), spark)
      + tile('Vehicles', n('units')) + tile('Properties', n('doors')) + tile('Territory', n('held'), 'towns held')
      + tile('Deliveries', n('deliveries')) + tile('Hearts', `<span class="hrt">♥ ${(hearts ?? 0).toLocaleString('en-US')}</span>`, 'on their works');
    for (const k of pins) {
      const m = METRICS.find((q) => q.key === k);
      if (!m) continue;
      out += tile(`★ ${m.label}`, v[k] === undefined ? '—' : m.money ? money(v[k]!) : (v[k] as number).toLocaleString('en-US'), '', ' pin');
    }
    return `<div class="fc-tiles">${out}</div>`;
  }

  private goodsHtml(goods: [string, number][] | undefined): string {
    if (!goods?.length) return '';
    const top = Math.max(1, ...goods.map((g) => g[1]));
    return `<section class="fc-sec"><h4>Moves most</h4><ul class="fc-goods">${goods.slice(0, 5).map(([name, n]) => {
      const t = CARGO.find((c) => c.name === name);
      return `<li><span class="ic">${t?.icon ?? '📦'}</span><span class="what"><b>${esc(name)}</b><small>${n.toLocaleString('en-US')} load${n === 1 ? '' : 's'}</small></span><span class="bar"><i style="width:${((n / top) * 100).toFixed(1)}%"></i></span></li>`;
    }).join('')}</ul></section>`;
  }

  /** Their vehicles: out on the map while they are signed in, else as their game last saved them. */
  private fleetHtml(pid: Pid, row: BoardRow, name: string): string {
    const out = this.host.fleetOf(pid);
    if (out) {
      if (!out.length) return `<section class="fc-sec"><h4>Their fleet</h4><p class="none">Nothing of theirs is out on the map just now.</p></section>`;
      const rows = out.map((r) => {
        const what = r.uid === null ? 'at the wheel' : r.parked ? 'parked' : r.known && Math.abs(r.v) > 0.05 ? 'on the move' : r.known ? 'stopped' : 'out on the map';
        const where = r.known ? this.host.whereIs(r) : '';
        return `<li><span class="ic">${KIND_ICON[r.def.kind]}</span><span class="what"><b>${esc(r.def.name)}</b><small>${esc(what)}${where ? ` · ${esc(where)}` : ''}</small></span>`
          + `<button type="button" class="link" data-fcfollow="${esc(pid)}|${r.uid === null ? 'own' : r.uid}">🎥 Follow</button></li>`;
      }).join('');
      return `<section class="fc-sec"><h4>Their fleet <small>${out.length} out</small></h4><ul class="fc-list">${rows}</ul></section>`;
    }
    const saved = row.fleet ?? [];
    if (!saved.length) return '';
    const rows = saved.map((u) => `<li><span class="ic">${KIND_ICON[defOf(u.m).kind]}</span><span class="what"><b>${esc(this.host.modelName(u.m))}</b><small>${esc(u.n || 'parked')}</small></span></li>`).join('');
    return `<section class="fc-sec"><h4>Their fleet <small>as ${esc(name)} last saved it${row.units > saved.length ? ` · ${row.units} in all` : ''}</small></h4><ul class="fc-list">${rows}</ul></section>`;
  }

  /** The vehicle on the right-hand stage: the one they chose, else the one at the wheel, else the first saved. */
  private showcaseOf(pid: Pid, profile: Profile | undefined, row: BoardRow, out: RemoteSeen[] | null): { model: string; parts?: Parts; why: string } | null {
    const pick = profile?.showcase;
    if (pick) {
      const live = out?.find((r) => r.uid === pick.uid || (r.uid === null && pick.uid === -1));
      return { model: live?.def.id ?? pick.model, parts: live?.parts, why: 'their showcase' };
    }
    const own = out?.find((r) => r.uid === null) ?? out?.[0];
    if (own) return { model: own.def.id, parts: own.parts, why: own.uid === null ? 'at the wheel now' : 'out now' };
    if (row.fleet?.length) return { model: row.fleet[0].m, why: 'in their fleet' };
    return null;
  }

  /** Another player's card. */
  html(pid: Pid): string {
    const me = this.host.me();
    if (pid === me) return this.myHtml();
    const row = this.rowOf(pid);
    if (!row) return '<p class="none">Nobody by that name is on this server.</p>';
    const rec = this.record(pid);
    const profile = rec?.profile;
    const who = this.host.who(pid);
    const online = !!this.host.cellOf(pid) || !!row.online;
    const cell = this.host.cellOf(pid);
    const livery = { logo: row.logo, primary: row.primary, accent: row.accent };
    const hq = this.host.hqOf(pid) ?? row.hq ?? null;
    const shield = `<img class="shield" src="${badgeUrl(livery, 'shield')}" alt="">`;
    const gilded = !!row.v?.gilded;
    const people = rec?.crew?.length ? rec.crew : [{ id: pid, name: row.by ?? who?.name ?? 'a player', online }];
    const names = people.map((p) => `<b data-pid="${esc(p.id)}">${esc(p.name)}</b>${p.online ? ' <i class="on"></i>' : ''}`).join(', ');
    // where they are, unless they keep it to friends (and you aren't one) or to themselves
    const hideWhere = rec?.whereOk === false;
    const where = online && cell ? (hideWhere ? 'signed in' : `signed in · ${this.away(cell)}${cell === this.host.here() ? ' · hears you' : ''}`) : esc(lastSeen(row));
    const friend = this.host.friends().find((f) => f.id === pid);
    const motto = profile?.motto ? `<i class="fc-motto">“${esc(profile.motto)}”</i>` : '';
    const pron = profile?.pronouns ? ` <small class="fc-pron">${esc(profile.pronouns)}</small>` : '';
    const head = `<header class="fc-head">${shield}<div><h3${gilded ? ' class="gilded"' : ''}>${esc(row.name)}${gilded ? ' <small class="gilded-title" title="Every page of the Passport filled">👑 Gilded</small>' : ''}</h3>`
      + `<div class="fc-who">${names}${pron} · ${where}</div>${motto}${this.titlesLine(pid)}</div></header>`;
    const name = row.by ?? who?.name ?? row.name;
    const btn = (act: string, label: string, extra = '', cls = '') => `<button type="button" class="fc-btn${cls}" data-fcact="${act}" data-pid="${esc(pid)}"${extra}>${label}</button>`;
    // the order (the user, 5 Nov 2026): Follow first as the card's main button, then View HQ, Friend (and Message),
    // Compare, Ask to join, Invite, the heart; Mute is a small link at the foot of the card
    const acts = `<div class="fc-acts">`
      + (online ? btn('follow', '🎥 Follow', ` data-name="${esc(name)}"`, ' cta') : '')
      + (hq ? btn('hq', '🏢 View HQ', ` data-key="${esc(hq.key)}" data-name="${esc(hq.name)}"`) : '')
      + (friend ? btn('unfriend', 'Friend ✓', '', ' on') : btn('friend', friend === undefined && this.host.friends().length >= 100 ? 'Friends full' : '+ Friend'))
      + btn('message', '💬 Message', ` data-name="${esc(name)}"`)
      + btn('compare', '⇄ Compare')
      + (this.host.sameFleet(pid) ? '' : btn('ask', '🤝 Ask to join') + (this.host.mayInvite() ? btn('invite', '✉ Invite to my fleet') : ''))
      + (this.host.sameFleet(pid) ? '' : btn(rec?.hearted ? 'unheart' : 'heart', `${rec?.hearted ? '♥' : '♡'} ${rec?.fh ?? 0}`, ` title="${rec?.hearted ? 'Take your heart off their fleet' : 'Leave a heart on their whole fleet'}"`, rec?.hearted ? ' hearted' : ''))
      + `</div>`;
    const mute = this.host.muted(pid)
      ? `<button type="button" class="fc-mute" data-fcact="unmute" data-pid="${esc(pid)}">Unmute</button>`
      : `<button type="button" class="fc-mute" data-fcact="mute" data-pid="${esc(pid)}">Mute</button>`;
    const out = this.host.fleetOf(pid);
    const hqStage = this.buildingStage(profile, hq, row.primary);
    const sc = this.showcaseOf(pid, profile, row, out);
    const scStage = this.still(sc ? `v:${sc.model}:${sc.parts ? JSON.stringify(sc.parts) : ''}:${row.primary}` : 'v:none', sc ? { kind: 'vehicle', model: sc.model, parts: sc.parts } : null, row.primary, '<b>Nothing to show yet</b>', sc ? `${esc(this.host.modelName(sc.model))} · ${esc(sc.why)}` : 'Showcase');
    const v = { ...(row.v ?? {}), worth: row.worth, units: row.units, held: row.towns } as Record<string, number | undefined>;
    const tiles = this.tiles(v, row.hist ?? [], row.hearts, profile?.pins ?? []);
    const fleet = shows(profile, 'fleet') ? this.fleetHtml(pid, row, name) : '';
    const goods = shows(profile, 'goods') ? this.goodsHtml(row.goods) : '';
    const between = this.betweenHtml(pid, row);
    const top = shows(profile, 'neighbours') ? this.topHtml(rec?.top, me) : '';
    const founded = rec?.founded ? `Fleet founded ${new Date(rec.founded).toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' })}` : '';
    const foot = `<footer class="fc-foot">${founded}${founded && row.seen ? ' · ' : ''}${row.v ? 'Numbers as their game last saved them.' : 'Their full numbers show once their game next saves.'} · ${mute}</footer>`;
    return `<div class="fcard">${head}${acts}<div class="fc-stages ${this.backdrop(profile)}">${hqStage}${scStage}</div>${tiles}${between}${fleet}${goods}${top}${foot}</div>`;
  }

  /** The titles a player wears this week, and those they lead as it stands. */
  private titlesLine(pid: Pid): string {
    const t = this.host.titlesOf(pid);
    const worn = t.worn.map((id) => `<span class="fc-title" title="${esc(TITLE_INFO[id].what)}, last week">${TITLE_INFO[id].icon} ${esc(TITLE_INFO[id].name)}</span>`).join('');
    const lead = t.leading.filter((id) => !t.worn.includes(id)).map((id) => `<span class="fc-title lead" title="${esc(TITLE_INFO[id].what)}: leading this week">${TITLE_INFO[id].icon} leading ${esc(TITLE_INFO[id].name)}</span>`).join('');
    return worn || lead ? `<div class="fc-titles">${worn}${lead}</div>` : '';
  }

  /** The stages' ground and sky, as the card's owner chose it. */
  private backdrop(p: Profile | undefined): string { return `bd-${p?.backdrop ?? 'county'}`; }

  /** The left-hand stage: the building the owner chose to show, else their HQ. */
  private buildingStage(p: Profile | undefined, hq: { key: string; name: string } | null, tint: number): string {
    const key = p?.building ?? null;
    const name = key ? this.host.deedName(key) : null;
    if (key && name) {
      const spec = this.host.buildingSpec(key);
      return this.still(`hq:${key}`, spec, tint, `<b>${esc(name)}</b><small>far away: its county isn’t loaded</small>`, `Showcase · ${esc(name)}`);
    }
    const spec = hq ? this.host.buildingSpec(hq.key) : null;
    return this.still(`hq:${hq?.key ?? ''}`, spec, tint, hq ? `<b>${esc(hq.name)}</b><small>far away: its county isn’t loaded</small>` : '<b>No HQ yet</b>', hq ? `HQ · ${esc(hq.name)}` : 'No HQ yet');
  }

  /** You and them (net/neighbours.ts): what each of you has done for the other, all time; the towns you share; the head to head. */
  private betweenHtml(pid: Pid, row: BoardRow): string {
    const n = this.host.neighbours();
    if (!n) return '';
    const p = n.pairOf(pid);
    if (!p) return `<section class="fc-sec"><h4>You and them</h4><p class="none">Asking the server…</p></section>`;
    const any = Object.keys(p.o).length || Object.keys(p.i).length;
    const bars = any ? n.bars(p.o, p.i, this.host.myPrimary(), row.primary) : '<p class="none">You haven’t crossed paths yet. Rent at their doors, a crossing of something they built, a heart or a few minutes driving beside them all count.</p>';
    return `<section class="fc-sec"><h4>You and them <small>all time</small></h4>${bars}</section>${n.townsHtml(p.towns)}${n.scorecard(pid)}`;
  }

  /** The fleets they deal with most: each a door to its own card; you, if you are one. */
  private topHtml(top: { id: Pid; name: string }[] | undefined, me: Pid | null): string {
    if (!top?.length) return '';
    return `<section class="fc-sec"><h4>Deals most with</h4><p class="fc-top">${top.map((t) => (t.id === me ? '<b class="you">you</b>' : `<b data-pid="${esc(t.id)}">${esc(t.name)}</b>`)).join(' · ')}</p></section>`;
  }

  /** My own card, as others see it, with the Edit view in place of the social buttons. */
  myHtml(): string {
    const me = this.host.me();
    const mine = this.host.mine();
    const rec = me ? this.record(me) : null;
    const profile = rec?.profile ?? {};
    const m = this.host.myMetrics();
    const b = mine.brand;
    const livery = { logo: b?.logo ?? '', primary: b?.primary ?? 0xe2412f, accent: b?.accent ?? 0xffffff };
    const shield = `<img class="shield" src="${badgeUrl({ ...livery, ...(mine.hq ? { stars: mine.hq.grade } : {}) }, 'shield')}" alt="">`;
    const who = me ? this.host.who(me) : null;
    const gilded = this.host.myGilded();
    const crew = rec?.crew?.length ? rec.crew : null;
    const names = crew ? crew.map((p) => `<b>${esc(p.name)}</b>${p.online ? ' <i class="on"></i>' : ''}`).join(', ') : `<b>${esc(who?.name ?? 'You')}</b>`;
    const motto = profile.motto ? `<i class="fc-motto">“${esc(profile.motto)}”</i>` : '<i class="fc-motto none">No motto yet</i>';
    const pron = profile.pronouns ? ` <small class="fc-pron">${esc(profile.pronouns)}</small>` : '';
    const head = `<header class="fc-head">${shield}<div><h3${gilded ? ' class="gilded"' : ''}>${esc(b?.name ?? 'Your fleet')}${gilded ? ' <small class="gilded-title">👑 Gilded</small>' : ''}</h3>`
      + `<div class="fc-who">${names}${pron} · <span class="you">this is you, as others see you</span></div>${motto}${me ? this.titlesLine(me) : ''}</div></header>`;
    if (this.editing) return `<div class="fcard mine">${head}${this.editHtml(profile, mine)}</div>`;
    const acts = `<div class="fc-acts"><button type="button" class="fc-btn" data-fcact="edit">✎ Edit how others see you</button></div>`;
    const hqStage = this.buildingStage(profile, mine.hq, livery.primary);
    const pick = profile.showcase ? mine.units.find((u) => u.uid === profile.showcase!.uid) : null;
    const sc = pick ?? mine.units.find((u) => u.uid === mine.ridden) ?? mine.units[0] ?? null;
    const why = pick ? 'your showcase' : sc && sc.uid === mine.ridden ? 'at the wheel now' : sc ? 'in your fleet' : '';
    const scStage = this.still(sc ? `v:${sc.model}:${sc.parts ? JSON.stringify(sc.parts) : ''}:${livery.primary}` : 'v:none', sc ? { kind: 'vehicle', model: sc.model, parts: sc.parts } : null, livery.primary, '<b>Nothing to show yet</b>', sc ? `${esc(this.host.modelName(sc.model))} · ${why}` : 'Showcase');
    const row = me ? this.host.rows().find((r) => r.id === me) : undefined;
    const tiles = this.tiles(m.v, m.hist, row?.hearts, profile.pins ?? []);
    const units = mine.units;
    const fleet = shows(profile, 'fleet') && units.length ? `<section class="fc-sec"><h4>Your fleet <small>${units.length}</small></h4><ul class="fc-list">${units.slice(0, 12).map((u) => `<li><span class="ic">${KIND_ICON[defOf(u.model).kind]}</span><span class="what"><b>${esc(this.host.modelName(u.model))}</b><small>${esc(u.name)}</small></span></li>`).join('')}</ul></section>` : '';
    const goods = shows(profile, 'goods') ? this.goodsHtml(this.host.myGoods()) : '';
    const hidden = [!shows(profile, 'fleet') ? 'your vehicles' : '', !shows(profile, 'goods') ? 'the goods you move' : ''].filter(Boolean);
    const foot = `<footer class="fc-foot">${rec?.founded ? `Fleet founded ${new Date(rec.founded).toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' })} · ` : ''}${hidden.length ? `Hidden from others: ${hidden.join(' and ')}.` : 'Others see your numbers as your game last saved them.'}</footer>`;
    return `<div class="fcard mine">${head}${acts}<div class="fc-stages ${this.backdrop(profile)}">${hqStage}${scStage}</div>${tiles}${fleet}${goods}${foot}</div>`;
  }

  private editHtml(p: Profile, mine: MyFleet): string {
    const opt = (v: string, label: string, on: boolean) => `<option value="${esc(v)}"${on ? ' selected' : ''}>${esc(label)}</option>`;
    const units = mine.units.map((u) => opt(String(u.uid), `${this.host.modelName(u.model)} · ${u.name}`, p.showcase?.uid === u.uid)).join('');
    const pins = Array.from({ length: PINS_MAX }, (_, i) => `<select name="pin${i}">${opt('', 'none', !p.pins?.[i])}${METRICS.map((m) => opt(m.key, m.label, p.pins?.[i] === m.key)).join('')}</select>`).join('');
    const check = (k: 'goods' | 'fleet' | 'neighbours', label: string) => `<label class="fc-check"><input type="checkbox" name="show-${k}"${shows(p, k) ? ' checked' : ''}> ${label}</label>`;
    return `<form class="fc-edit" onsubmit="return false">
      <label>Motto <small>${MOTTO_MAX} characters, under your fleet’s name</small><input type="text" name="motto" maxlength="${MOTTO_MAX}" value="${esc(p.motto ?? '')}" placeholder="Anything, anywhere, by Tuesday." spellcheck="false" autocomplete="off"></label>
      <label>Pronouns <small>optional, after your name</small><input type="text" name="pronouns" maxlength="${PRONOUNS_MAX}" value="${esc(p.pronouns ?? '')}" placeholder="they/them" spellcheck="false" autocomplete="off"></label>
      <label>Showcase vehicle <small>turning on your card</small><select name="showcase">${opt('', 'The one at the wheel', !p.showcase)}${units}</select></label>
      <label>Pinned metrics <small>up to ${PINS_MAX} extra tiles, starred</small><span class="fc-pins">${pins}</span></label>
      <div class="fc-checks">${check('fleet', 'Show my vehicles')}${check('goods', 'Show the goods I move most')}${check('neighbours', 'Show who I deal with most')}</div>
      <label>Showcase building <small>on the left-hand stage</small><select name="building">${opt('', 'Your HQ', !p.building)}${mine.deeds.map((d) => opt(d.key, d.name, p.building === d.key)).join('')}</select></label>
      <label>Backdrop <small>the stages’ ground and sky</small><select name="backdrop">${BACKDROPS.map((b) => opt(b, BACKDROP_LABEL[b], (p.backdrop ?? 'county') === b)).join('')}</select></label>
      <label>Where you are <small>the county and compass on your card and in Fleets</small><select name="where">${opt('shown', 'Shown to everyone', (p.where ?? 'shown') === 'shown')}${opt('friends', 'Only to friends', p.where === 'friends')}${opt('hidden', 'Hidden', p.where === 'hidden')}</select></label>
      <label>Notes from <small>who may leave you notes; a muted player never can</small><select name="messages">${opt('anyone', 'Anyone', (p.messages ?? 'anyone') === 'anyone')}${opt('known', 'Friends and neighbours', p.messages === 'known')}${opt('nobody', 'Nobody', p.messages === 'nobody')}</select></label>
      <div class="fc-acts"><button type="button" class="fc-btn on" data-fcact="save">Save</button><button type="button" class="fc-btn" data-fcact="cancel">Cancel</button></div>
    </form>`;
  }

  /** A press inside a card: true if it was the card's. */
  press(target: HTMLElement): boolean {
    const f = target.closest('[data-fcfollow]') as HTMLElement | null;
    if (f) {
      const [pid, u] = f.dataset.fcfollow!.split('|');
      this.host.followUnit(pid, u === 'own' ? null : Number(u));
      return true;
    }
    const b = target.closest('[data-fcact]') as HTMLElement | null;
    if (!b) return false;
    const act = b.dataset.fcact!, pid = b.dataset.pid ?? '', name = b.dataset.name ?? '';
    const who = pid ? this.host.who(pid)?.name ?? name : '';
    if (act === 'friend') { this.host.friend(pid, true); this.host.say('Friend added', `${who || 'They'} are in your Friends now`); }
    else if (act === 'unfriend') { this.host.friend(pid, false); this.host.say('Friend removed', who || 'Removed'); }
    else if (act === 'follow') { if (!this.host.cellOf(pid)) { this.host.say(who || 'They', 'Not signed in just now'); return true; } this.host.follow(pid, name || who); }
    else if (act === 'hq' && b.dataset.key) this.host.viewHq(b.dataset.key, name || `${who}’s HQ`);
    else if (act === 'compare') this.host.compare(pid);
    else if (act === 'message') this.host.message(pid);
    else if (act === 'ask') this.host.post({ t: 'crewAsk', id: pid });
    else if (act === 'heart' || act === 'unheart') this.host.post({ t: 'fleetHeart', id: pid, on: act === 'heart' });
    else if (act === 'invite') this.host.post({ t: 'crewInvite', id: pid });
    else if (act === 'mute' || act === 'unmute') this.host.post({ t: 'mute', id: pid, on: act === 'mute' });
    else if (act === 'edit') this.editing = true;
    else if (act === 'cancel') this.editing = false;
    else if (act === 'save') {
      const form = b.closest('form');
      if (form) this.save(form);
      this.editing = false;
    }
    return true;
  }

  private save(form: HTMLFormElement): void {
    const val = (n: string) => (form.elements.namedItem(n) as HTMLInputElement | HTMLSelectElement | null)?.value ?? '';
    const on = (n: string) => !!(form.elements.namedItem(n) as HTMLInputElement | null)?.checked;
    const uid = Number(val('showcase'));
    const unit = this.host.mine().units.find((u) => u.uid === uid);
    const pins = Array.from({ length: PINS_MAX }, (_, i) => val(`pin${i}`)).filter(Boolean);
    const set: Partial<Profile> = {
      motto: val('motto'), pronouns: val('pronouns'),
      showcase: unit ? { uid: unit.uid, model: unit.model } : null,
      pins: [...new Set(pins)],
      show: { goods: on('show-goods'), fleet: on('show-fleet'), neighbours: on('show-neighbours') },
      messages: (val('messages') || 'anyone') as Profile['messages'],
      backdrop: (val('backdrop') || 'county') as Backdrop,
      where: (val('where') || 'shown') as Profile['where'],
      building: val('building') || null,
    };
    this.host.post({ t: 'profile', set });
    // shown at once; the server's answer replaces it
    const me = this.host.me();
    if (me) {
      const had = this.cards.get(me);
      const clean: Profile = { ...(had?.profile ?? {}), ...set };
      if (!clean.motto) delete clean.motto;
      if (!clean.pronouns) delete clean.pronouns;
      this.cards.set(me, { profile: clean, founded: had?.founded ?? 0, crew: had?.crew, at: performance.now() });
    }
    this.host.say('Saved', 'Your card is updated for everyone');
  }
}
