import { PICK_ICON, PICK_LABEL, type LocalScope, type LocalWire, type Pick, type Picks } from '../../shared/marks';
import { hashString } from '../world/rng';

/**
 * The Tribune's daily edition (the user, 5 Nov 2026: "a rotating variety of different things, so it always feels
 * fresh"). The title's newspaper used to show the week's picks and then the first four of the world's lines, the
 * same for everyone all week. Now each day makes an edition from everything the server tells (online.json: the
 * picks, the world's figures, the titles, the vehicle boards and the news wire, server/news.ts):
 *
 * - every story scores its weight, how fresh it is (half as much three days on), whether this device has shown it
 *   already (a third as much), and a little of the day's own luck, so two days' editions differ;
 * - one desk is the day's column (Records desk, Crowns, Sport...), chosen by the day, and its stories count half again;
 * - an edition holds one story from each desk and one about each fleet first, then two when it still has room, so a
 *   small world is not one fleet's paper and a busy week is not all crowns;
 * - a device that has played online keeps places for its fleet's own news (one), its circle's (two) and its county's
 *   (two), from the server's /wire.json, each told with whose news it is ("Your circle · Crowns").
 *
 * Pure apart from the shown list (`seenStore`), so the gate (scripts/tribune.ts) runs it headless.
 */

/** Stories in an edition, at most. */
export const EDITION = 9;
const DAY = 86400e3;
/** A story's freshness halves this many days on; one shown on this device counts this much. */
const HALF_DAYS = 3, SEEN = 0.35;
/** The day's column counts this much more. */
const COLUMN = 1.5;
/** Days a shown story is remembered, and how many are kept. */
const SEEN_DAYS = 21, SEEN_MAX = 400;
const SEEN_KEY = 'tinyfleet-tribune-seen';

/** A story's desk: its own, or its pick kind's label. */
export const deskOf = (p: Pick): string => p.tag ?? PICK_LABEL[p.kind] ?? 'The world';
/** Its mark: its own, or its pick kind's. */
export const iconOf = (p: Pick): string => p.icon ?? PICK_ICON[p.kind] ?? '🌍';
/** The kicker: the desk, and for a reader's local news whose it is. */
export function kickerOf(p: Pick): string {
  const desk = deskOf(p);
  if (p.scope === 'you') return `Your fleet · ${desk}`;
  if (p.scope === 'circle') return `Your circle · ${desk}`;
  if (p.scope === 'county') return `${p.county ?? 'Near you'} · ${desk}`;
  return desk;
}
/** Places an edition keeps for a reader's own news, their circle's and their county's, when there is any. */
export const QUOTA: Record<LocalScope, number> = { you: 1, circle: 2, county: 2 };

/** An id for a story the server gave none (a pick, a world line): its kind, fleet and words. */
export const idOf = (p: Pick): string => p.id ?? `${p.kind}|${p.by}|${hashString(`${p.title}|${p.detail}`).toString(36)}`;

/** Every story the server told, in one pool: the picks weigh 3, the world's lines 2, the wire's its own; a reader's local stories first, so theirs is the copy kept. */
export function pool(p: Picks, local?: LocalWire | null): Pick[] {
  const out: Pick[] = [];
  const seen = new Set<string>();
  const add = (it: Pick, w: number, t?: number) => {
    const id = idOf(it);
    if (seen.has(id)) return;
    seen.add(id);
    out.push({ ...it, id, w: it.w ?? w, t: it.t ?? t });
  };
  // the picks and the world's lines are the week's: as fresh as the week is, or three days old for last week's
  const weekT = p.live ? undefined : p.from;
  for (const it of local?.stories ?? []) add(it, it.w ?? 2);
  for (const it of p.items) add(it, 3, weekT);
  for (const it of p.world ?? []) add(it, 2, weekT);
  for (const it of p.wire ?? []) add(it, it.w ?? 2);
  return out;
}

/** The day's column: one of the desks in the pool, by the day. */
export function columnOf(stories: Pick[], day: number): string | null {
  const desks = [...new Set(stories.map(deskOf))].sort();
  return desks.length ? desks[hashString(`column|${day}`) % desks.length] : null;
}

/**
 * The day's edition: the best `n` stories by score, at most one a desk and one a fleet while that fills it, then two.
 * The lead (the first) is the best of all; the rest follow by score. `seen`: ids this device has shown already.
 */
export function edition(p: Picks, now: number, seen: ReadonlySet<string>, n = EDITION, local?: LocalWire | null): { items: Pick[]; column: string | null; day: number } {
  const day = Math.floor(now / DAY);
  const all = pool(p, local);
  const column = columnOf(all, day);
  const score = (s: Pick): number => {
    const age = s.t === undefined ? 0 : Math.max(0, (now - s.t) / DAY);
    const luck = 0.85 + 0.3 * ((hashString(`${day}|${s.id}`) % 1000) / 1000);
    return (s.w ?? 2) / (1 + age / HALF_DAYS) * (seen.has(s.id!) ? SEEN : 1) * (deskOf(s) === column ? COLUMN : 1) * luck;
  };
  const ranked = all.map((s) => ({ s, v: score(s) })).sort((a, b) => b.v - a.v || (a.s.id! < b.s.id! ? -1 : 1));
  const out: Pick[] = [];
  const fits = (s: Pick, cap: number) => !out.includes(s) && out.filter((q) => deskOf(q) === deskOf(s)).length < cap && (!s.by || out.filter((q) => q.by === s.by).length < cap);
  // the reader's places first: their own fleet's best, their circle's two, their county's two
  for (const scope of ['you', 'circle', 'county'] as const) {
    let k = 0;
    for (const { s } of ranked) {
      if (k >= QUOTA[scope] || out.length >= n) break;
      if (s.scope === scope && fits(s, 1)) { out.push(s); k++; }
    }
  }
  for (const cap of [1, 2, Infinity]) {
    for (const { s } of ranked) {
      if (out.length >= n) break;
      if (fits(s, cap)) out.push(s);
    }
    if (out.length >= n) break;
  }
  // in score order, the lead first
  const at = new Map(ranked.map((r, i) => [r.s, i]));
  out.sort((a, b) => at.get(a)! - at.get(b)!);
  return { items: out, column, day };
}

/** This device's shown list: ids and the day each was last shown. Reads and writes never throw. */
export const seenStore = {
  read(now = Date.now()): Map<string, number> {
    try {
      const raw = JSON.parse(localStorage.getItem(SEEN_KEY) ?? '{}') as Record<string, number>;
      const day = Math.floor(now / DAY);
      return new Map(Object.entries(raw).filter(([, d]) => typeof d === 'number' && day - d <= SEEN_DAYS));
    } catch { return new Map(); }
  },
  mark(id: string, now = Date.now()): void {
    try {
      const m = seenStore.read(now);
      m.delete(id);
      m.set(id, Math.floor(now / DAY));
      const keep = [...m.entries()].slice(-SEEN_MAX);
      localStorage.setItem(SEEN_KEY, JSON.stringify(Object.fromEntries(keep)));
    } catch { /* private window: every story is new */ }
  },
};
