/**
 * Community (docs/community.html): what both the game and the server need to agree on about the works
 * players build, the hearts left on them, and the paths their tyres wear into open ground. Nothing here
 * touches the DOM or Node, and nothing here reads a World.
 *
 * - A **work** is something a player built that others can see and use: a road (`r…`), one span of a
 *   road's bridges or tunnels (`r….0`), a chunk of earthworks (`L37`), a chunk's worn paths (`W37`) or an
 *   HQ (its lot key, `b12`). Keyed `cx,cz#id` like a lot. A road's id is a hash of its nodes, so both sides
 *   work it out from the edit log alone and nothing has to be numbered or handed back.
 * - A **pass** is one fleet crossing one tile of open ground on one game day. Passes never fall, so a path,
 *   once worn, stays.
 */

/** The constants both sides are bound by. Path numbers are first guesses, to be fitted from real counts. */
export const COMMUNITY = {
  /** A work with this many hearts is listed: only its builder may bulldoze it. */
  listedAt: 10,
  /** Minutes signed in before a fleet's hearts count (a second account can't be made just to give them). */
  heartAfterMins: 30,
  /** The most work ids a player's record keeps as hearted. */
  heartsMax: 2000,
  /** Roads shorter than this (in nodes) are not listed anywhere, named or prompted for. */
  roadMin: 12,
  /** A bridge at least this long makes the news. */
  newsBridge: 20,
  /** Earthworks: lifts a landform needs (a hill, a lake, a canal) before it is a work, with a cairn, a name tag and hearts. */
  stakeLifts: 40,
  /** Builders a chunk of earthworks credits. */
  landByMax: 3,
  /** A work's name, at most. */
  nameMax: 24,
  /** Different fleets counted per work; past this the count stops. */
  usersMax: 64,
  /** Crossing milestones that are announced. */
  usesNews: [100, 1000, 10000],
  /** Each list on the World tab. */
  worldTop: 50,
  /** Seconds between path reports from a game, and the most tiles one may carry. */
  treadEvery: 20,
  treadMax: 300,
  /** km/h a land vehicle must be doing to wear the ground. */
  wearKmh: 8,
} as const;

/** The three stages of a path, and what each needs: passes on the tile, and fleets that have worn its chunk. */
export const PATH = {
  faint: 6,
  worn: 30, wornFleets: 3,
  beaten: 120, beatenFleets: 5,
  /** Fleets remembered per chunk. */
  fleetsMax: 16,
  /** Tiles a cell may have counted at once; past it, tiles below faint are let go to make room. */
  cap: 6000,
} as const;

export type PathStage = 0 | 1 | 2 | 3;

/** A tile's stage from its passes and the number of fleets that have worn its chunk. */
export function stageOf(passes: number, fleets: number): PathStage {
  if (passes >= PATH.beaten && fleets >= PATH.beatenFleets) return 3;
  if (passes >= PATH.worn && fleets >= PATH.wornFleets) return 2;
  if (passes >= PATH.faint) return 1;
  return 0;
}

/** Tiles per side of a cell and of a chunk (world/tiles.ts N and CHUNK, repeated so the server needn't load the world). */
const N = 256, CHUNK = 16, CHUNKS = N / CHUNK;

/** The chunk a tile of a cell falls in, 0–255. */
export const chunkOfTile = (i: number): number => Math.floor((i % N) / CHUNK) + Math.floor(Math.floor(i / N) / CHUNK) * CHUNKS;
/** A chunk's tile in the cell: `t` is 0–255 across the chunk, row by row. */
export function tileOfChunk(k: number, t: number): number {
  const kx = k % CHUNKS, kz = (k - kx) / CHUNKS;
  return (kz * CHUNK + Math.floor(t / CHUNK)) * N + kx * CHUNK + (t % CHUNK);
}
/** The tile's place within its chunk. */
export const slotOfTile = (i: number): number => (Math.floor(i / N) % CHUNK) * CHUNK + ((i % N) % CHUNK);

/** A chunk's 256 pass counts as kept and sent: zero runs as 0, n; any other count as its own byte; base64. */
export function encodePasses(p: Uint8Array): string {
  const bytes: number[] = [];
  for (let k = 0; k < p.length;) {
    if (p[k] === 0) {
      let n = 0;
      while (k < p.length && p[k] === 0 && n < 255) { n++; k++; }
      bytes.push(0, n);
    } else bytes.push(p[k++]);
  }
  let s = '';
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s);
}

export function decodePasses(s: string | undefined): Uint8Array {
  const out = new Uint8Array(CHUNK * CHUNK);
  if (!s) return out;
  let bin: string;
  try { bin = atob(s); } catch { return out; }
  let p = 0;
  for (let b = 0; b < bin.length && p < out.length; b++) {
    const v = bin.charCodeAt(b);
    if (v === 0) { p += bin.charCodeAt(++b) || 0; continue; }
    out[p++] = v;
  }
  return out;
}

/** FNV-1a over a road's nodes, in base 36: the same road has the same id in every game and on the server. */
export function roadWorkId(nodes: readonly number[]): string {
  let h = 0x811c9dc5;
  for (const n of nodes) {
    let v = n | 0;
    for (let k = 0; k < 4; k++) { h ^= v & 255; h = Math.imul(h, 0x01000193); v >>>= 8; }
  }
  return `r${(h >>> 0).toString(36)}`;
}

/** A work's key, "cx,cz#id", taken apart: its cell and its id; null when it isn't one. `F` is a landform, numbered by the server. */
export const WORK_KEY = /^(-?\d{1,5},-?\d{1,5})#(r[0-9a-z]{1,8}(?:\.\d{1,2})?|F\d{1,5}|W\d{1,3}|b\d{1,7})$/;

/** The landforms earthworks make, as `landFeatures` reads them. */
export type FeatureKind = 'mountain' | 'hill' | 'lake' | 'canal' | 'valley' | 'reclaim' | 'land';
export const FEATURE_KINDS: readonly FeatureKind[] = ['mountain', 'hill', 'lake', 'canal', 'valley', 'reclaim', 'land'];
export const isFeature = (k: string): k is FeatureKind => (FEATURE_KINDS as readonly string[]).includes(k);

/** What a work is, for its card, the lists and the plaques. */
export type WorkKind = 'road' | 'bridge' | 'suspension' | 'tunnel' | 'flyover' | 'viaduct' | FeatureKind | 'path' | 'hq';
export const WORK_LABEL: Record<WorkKind, string> = {
  road: 'Road', bridge: 'Bridge', suspension: 'Suspension bridge', tunnel: 'Tunnel', flyover: 'Flyover', viaduct: 'Viaduct', path: 'Beaten track', hq: 'HQ',
  mountain: 'Mountain', hill: 'Hill', lake: 'Lake', canal: 'Canal', valley: 'Valley', reclaim: 'Reclaimed land', land: 'Earthworks',
};
/** Ground other players made: a landform or a beaten track. Driven over, never crossed or bulldozed as a work. */
export const isGround = (k: string): boolean => k === 'path' || isFeature(k);

/** One chunk of earthworks (world/landCodec.ts's format), read without the world: four corner planes then water, 256 each. */
export function decodeLandChunk(s: string | null | undefined): Int8Array {
  const raw = new Int8Array(CHUNK * CHUNK * 5);
  if (!s) return raw;
  let bin: string;
  try { bin = atob(s); } catch { return raw; }
  let p = 0;
  for (let b = 0; b < bin.length && p < raw.length; b++) {
    const v = bin.charCodeAt(b);
    if (v === 0) { p += bin.charCodeAt(++b) || 0; continue; }
    raw[p++] = v > 127 ? v - 256 : v;
  }
  return raw;
}

/** A landform: a connected patch of ground that earthworks moved, what it reads as, and where its name goes. */
export interface LandFeature {
  tiles: number[];
  /** About how many steps of ground and water were moved (a corner shared by four tiles counts once). */
  lifts: number;
  kind: FeatureKind;
  /** Its summit, for something raised; the middle of it otherwise. */
  top: number;
  chunks: number[];
}

/**
 * A cell's earthworks as landforms: every connected patch (side or corner) of tiles whose ground or water
 * differs from the generator's, read as a hill or mountain (raised, six steps up or more for a mountain),
 * a valley or canal (dug: long and narrow is a canal), a lake or canal (water let in), reclaimed land
 * (water drained), or plain earthworks when it is a bit of everything. Pure, so the game and the server
 * read the same landforms from the same blocks.
 */
export function landFeatures(land: Record<string, string> | undefined): LandFeature[] {
  if (!land) return [];
  const raise = new Float32Array(N * N), dig = new Float32Array(N * N), wUp = new Float32Array(N * N), wDn = new Float32Array(N * N);
  const peak = new Int8Array(N * N);
  const changed = new Uint8Array(N * N);
  for (const [key, s] of Object.entries(land)) {
    const k = Number(key);
    if (!(k >= 0 && k < CHUNKS * CHUNKS)) continue;
    const raw = decodeLandChunk(s);
    for (let t = 0; t < CHUNK * CHUNK; t++) {
      const i = tileOfChunk(k, t);
      let up = 0, down = 0, top = 0;
      for (let q = 0; q < 4; q++) { const d = raw[q * 256 + t]; if (d > 0) up += d; else down -= d; if (d > top) top = d; }
      const wt = raw[1024 + t];
      if (!up && !down && !wt) continue;
      changed[i] = 1;
      raise[i] = up / 4; dig[i] = down / 4; peak[i] = top;
      if (wt > 0) wUp[i] = wt; else wDn[i] = -wt;
    }
  }
  const out: LandFeature[] = [];
  const seen = new Uint8Array(N * N);
  const stack: number[] = [];
  for (let start = 0; start < N * N; start++) {
    if (!changed[start] || seen[start]) continue;
    const tiles: number[] = [];
    seen[start] = 1;
    stack.push(start);
    while (stack.length) {
      const i = stack.pop()!;
      tiles.push(i);
      const x = i % N, z = (i - x) / N;
      for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
        const nx = x + dx, nz = z + dz;
        if (nx < 0 || nz < 0 || nx >= N || nz >= N) continue;
        const j = nz * N + nx;
        if (changed[j] && !seen[j]) { seen[j] = 1; stack.push(j); }
      }
    }
    let up = 0, down = 0, wu = 0, wd = 0, best = tiles[0], x0 = N, x1 = 0, z0 = N, z1 = 0, sx = 0, sz = 0;
    for (const i of tiles) {
      up += raise[i]; down += dig[i]; wu += wUp[i]; wd += wDn[i];
      if (peak[i] > peak[best]) best = i;
      const x = i % N, z = (i - x) / N;
      x0 = Math.min(x0, x); x1 = Math.max(x1, x); z0 = Math.min(z0, z); z1 = Math.max(z1, z);
      sx += x; sz += z;
    }
    const w = x1 - x0 + 1, d = z1 - z0 + 1;
    const long = Math.max(w, d) >= 3 * Math.min(w, d) && Math.min(w, d) <= 5;
    const mx = sx / tiles.length, mz = sz / tiles.length;
    const middle = tiles.reduce((b, i) => (Math.hypot((i % N) - mx, Math.floor(i / N) - mz) < Math.hypot((b % N) - mx, Math.floor(b / N) - mz) ? i : b), tiles[0]);
    let kind: FeatureKind;
    if (wu > 0.5 * Math.max(up, down) && wu >= wd) kind = long ? 'canal' : 'lake';
    else if (wd > 0.5 * Math.max(up, down)) kind = 'reclaim';
    else if (up >= 2 * down) kind = peak[best] >= 6 ? 'mountain' : 'hill';
    else if (down >= 2 * up) kind = long ? 'canal' : 'valley';
    else kind = 'land';
    out.push({
      tiles, lifts: Math.round(up + down + wu + wd), kind,
      top: kind === 'mountain' || kind === 'hill' ? best : middle,
      chunks: [...new Set(tiles.map(chunkOfTile))],
    });
  }
  return out;
}

/** Up to `n` of a landform's tiles, evenly spread: how the server knows it again after more digging. */
export const sampleTiles = (tiles: number[], n = 24): number[] =>
  tiles.length <= n ? tiles.slice() : Array.from({ length: n }, (_, k) => tiles[Math.floor((k * tiles.length) / n)]);
/**
 * A bridge span's kind from the flags its edit keeps (world/delta.ts): 1 suspension, 4 flyover, 8 tunnel,
 * 32 raised over water for boats (a bridge, crest and all), 64 an elevated stretch (a viaduct).
 */
export const spanKind = (flags: number): WorkKind => (flags & 8 ? 'tunnel' : flags & 64 ? 'viaduct' : flags & 32 ? (flags & 1 ? 'suspension' : 'bridge')
  : flags & 4 ? 'flyover' : flags & 1 ? 'suspension' : 'bridge');

// ---- projects ------------------------------------------------------------------------------------------------

/** Tiles apart, box to box, within which one builder's works make one project (the user, 5 Nov 2026). */
export const PROJECT_NEAR = 10;

/**
 * One builder's works that stand near each other, as projects (the user, 5 Nov 2026: an L of two roads, or land
 * reclaimed from two islands, read as one work): groups of indices into `items`, each group a builder's works whose
 * boxes ([x0, z0, x1, z1] in world tiles) come within `near` tiles of one another's, followed from work to work, over
 * county lines too. Works of different builders never group; a work near nothing of its builder's is a group alone.
 */
export function groupNear<T>(items: readonly T[], by: (t: T) => string, box: (t: T) => readonly [number, number, number, number], near = PROJECT_NEAR): number[][] {
  const parent = items.map((_, i) => i);
  const find = (i: number): number => (parent[i] === i ? i : (parent[i] = find(parent[i])));
  const byBuilder = new Map<string, number[]>();
  items.forEach((t, i) => { const b = by(t); const l = byBuilder.get(b); if (l) l.push(i); else byBuilder.set(b, [i]); });
  for (const ids of byBuilder.values()) {
    const boxes = ids.map((i) => box(items[i]));
    for (let a = 0; a < ids.length; a++) for (let b = a + 1; b < ids.length; b++) {
      const A = boxes[a], B = boxes[b];
      const dx = Math.max(0, A[0] - B[2], B[0] - A[2]), dz = Math.max(0, A[1] - B[3], B[1] - A[3]);
      if (Math.max(dx, dz) <= near) parent[find(ids[a])] = find(ids[b]);
    }
  }
  const groups = new Map<number, number[]>();
  items.forEach((_, i) => { const r = find(i); const g = groups.get(r); if (g) g.push(i); else groups.set(r, [i]); });
  return [...groups.values()];
}
