/**
 * A race meeting on a circuit (docs/circuits.html), as a simulation with no drawing in it, so the
 * gate (scripts/circuits.ts) can run one headless and the game (game/circuits.ts) can draw one.
 *
 * Four to six cars of one model roll out of the pit lane in grid order and run a slow lap to their
 * places on the grid, two by two. The five lights come on one by one and go out together; three laps;
 * the first over the line wins. Then a slow lap round to the pit lane, where each parks in the order it
 * finished. Every car is a CarState — the player's own physics — driven by `Racer`: it follows its path
 * with a lane offset it can move into to get past, lifts for the corners its car can't take flat, backs
 * off behind a car it can't get by, and now and then has a moment. Nobody is slowed or hurried to keep
 * it close.
 *
 * The player can take a grid slot (a Race Day mission): they are an entrant like the others, their
 * progress read along the same path, so a cut across the infield doesn't count.
 */
import { CarState, surfaceMul } from './car';
import { ALL_VEHICLES, halfSize, type LandDef } from './vehicles';
import { idx, inB, type World, type Building } from '../world/tiles';
import {
  DS, frameOf, offsetAt, planOf, toIsland, type CircuitPlan,
} from '../world/circuits';
import { mulberry32, type Rng } from '../world/rng';

// ---- paths ------------------------------------------------------------------------------------------

/** An open polyline in island tiles, with the lap distance each point was laid at. */
export class Path {
  x: number[] = []; z: number[] = []; s: number[] = []; cum: number[] = []; vmax: number[] = [];
  /** How sharply the path bends at each point, radians a tile. */
  k: number[] = [];

  add(pts: { x: number; z: number; s: number }[]): void {
    for (const q of pts) {
      const n = this.x.length;
      if (n) {
        const d = Math.hypot(q.x - this.x[n - 1], q.z - this.z[n - 1]);
        if (d < 0.05) continue;
        this.cum.push(this.cum[n - 1] + d);
      } else this.cum.push(0);
      this.x.push(q.x); this.z.push(q.z); this.s.push(q.s); this.vmax.push(Infinity); this.k.push(0);
    }
    this.speeds();
  }

  get length(): number { return this.cum[this.cum.length - 1] ?? 0; }
  get n(): number { return this.x.length; }

  /** The fastest each point can be taken: from how sharply the path bends there. */
  private speeds(): void {
    const n = this.n;
    for (let i = 0; i < n; i++) {
      const a = Math.max(0, i - 2), b = Math.min(n - 1, i + 2);
      if (b - a < 2) continue;
      const h1 = Math.atan2(this.x[i] - this.x[a], this.z[i] - this.z[a]), h2 = Math.atan2(this.x[b] - this.x[i], this.z[b] - this.z[i]);
      const turn = Math.abs(wrap(h2 - h1)), dist = this.cum[b] - this.cum[a];
      const k = dist > 0 ? turn / dist : 0;
      this.k[i] = k;
      this.vmax[i] = k > 1e-3 ? Math.sqrt(GRIP / k) : Infinity;
    }
  }

  /** The segment holding distance d, found from a hint. */
  segAt(d: number, hint = 0): number {
    let i = Math.max(0, Math.min(this.n - 2, hint));
    while (i < this.n - 2 && this.cum[i + 1] < d) i++;
    while (i > 0 && this.cum[i] > d) i--;
    return i;
  }

  /** The point `d` along, and the way the path runs there. */
  at(d: number, hint = 0): { x: number; z: number; tx: number; tz: number } {
    const i = this.segAt(d, hint), j = Math.min(this.n - 1, i + 1);
    const l = this.cum[j] - this.cum[i] || 1, f = Math.max(0, Math.min(1, (d - this.cum[i]) / l));
    const tx = (this.x[j] - this.x[i]) / l, tz = (this.z[j] - this.z[i]) / l;
    return { x: this.x[i] + (this.x[j] - this.x[i]) * f, z: this.z[i] + (this.z[j] - this.z[i]) * f, tx, tz };
  }

  /** The nearest point on the path to (x, z), looked for a few segments either side of `seg`: distance along, segment, and how far off. */
  project(x: number, z: number, seg: number, back = 4, ahead = 14): { d: number; seg: number; off: number } {
    let best = { d: this.cum[Math.max(0, Math.min(this.n - 1, seg))] ?? 0, seg, off: Infinity };
    for (let i = Math.max(0, seg - back); i <= Math.min(this.n - 2, seg + ahead); i++) {
      const ex = this.x[i + 1] - this.x[i], ez = this.z[i + 1] - this.z[i], l2 = ex * ex + ez * ez || 1;
      const f = Math.max(0, Math.min(1, ((x - this.x[i]) * ex + (z - this.z[i]) * ez) / l2));
      const px = this.x[i] + ex * f, pz = this.z[i] + ez * f, off = Math.hypot(x - px, z - pz);
      if (off < best.off) best = { d: this.cum[i] + Math.sqrt(l2) * f, seg: i, off };
    }
    return best;
  }

  /** The distance along at which the lap distance first reaches s. */
  dAtS(s: number): number {
    for (let i = 0; i < this.n; i++) if (this.s[i] >= s) return this.cum[i];
    return this.length;
  }
}

/** How hard a car may corner, tiles/s², before its driver lifts. Kinematic steering could take more; this reads as racing. */
const GRIP = 3.6;
/** A racer's share of its steering lock it takes a bend on: the rest is kept for holding the line. */
const RACE_MARGIN = 0.82;

/** The pit lane's offset from the centreline at lap distance s (s near the line: -len/2..len/2). */
function pitU(p: CircuitPlan, s: number): number {
  const q = p.pit;
  if (s <= q[0].s) return q[0].u;
  if (s >= q[q.length - 1].s) return q[q.length - 1].u;
  const f = (s - q[0].s) / DS, i = Math.min(q.length - 2, Math.floor(f)), k = f - i;
  return q[i].u + (q[i + 1].u - q[i].u) * k;
}

const ease = (a: number, b: number, t: number) => { const k = Math.max(0, Math.min(1, t)); return a + (b - a) * k * k * (3 - 2 * k); };

/** Points along the lap from s0 to s1 (unwrapped), `u(s)` right of the centreline, in island tiles. */
function lapPts(p: CircuitPlan, f: ReturnType<typeof frameOf>, s0: number, s1: number, u: (s: number) => number): { x: number; z: number; s: number }[] {
  const out: { x: number; z: number; s: number }[] = [];
  for (let s = s0; s <= s1 + 1e-6; s += DS) {
    const o = offsetAt(p, s, u(s)), q = toIsland(f, o.x, o.z);
    out.push({ x: q.x, z: q.z, s });
  }
  return out;
}

/** A lap flat out in a car of this top speed (tiles/s), lifting only for the corners: what a good lap is measured against. */
export function lapEstimate(p: CircuitPlan, top: number): number {
  let t = 0;
  for (let i = 0; i < p.n; i++) {
    const k = Math.abs(p.curv[i]);
    t += DS / Math.min(top, k > 1e-3 ? Math.sqrt(GRIP / k) : Infinity);
  }
  return t;
}

// ---- the field --------------------------------------------------------------------------------------

export const LAPS = 3;

/** Liveries for a field: no two alike. */
export const LIVERIES = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0x8e5cc7, 0xf28c38, 0xf4f2ec, 0x2bb3a3];
export const LIVERY_NAMES = ['Red', 'Blue', 'Yellow', 'Green', 'Purple', 'Orange', 'White', 'Teal'];

/** The cars that race for fun now and then, instead of the sports car. */
const FUN = ['pip', 'zippy', 'sunny', 'tomato', 'cab', 'limo', 'bus', 'atv', 'ambulance', 'sundae', 'stomper', 'clod', 'sandy', 'patrol'];

/** The model a meeting races: mostly the Wasabi, sometimes something silly; an old circuit likes old cars. */
export function pickModel(p: CircuitPlan, r: Rng): string {
  const land = (id: string) => { const d = ALL_VEHICLES.find((v) => v.id === id); return !!d && d.kind === 'land' && !(d as LandDef).trailer; };
  const fun = FUN.filter(land);
  if (p.design === 'heritage' && r() < 0.5) return r() < 0.6 ? 'sunny' : 'pip';
  if (r() < 0.64 || !fun.length) return 'wasabi';
  return fun[Math.floor(r() * fun.length)];
}

/** One car for the field: the model, in its livery, race-prepared (never slower than a stock one) and a touch quicker or slower than the next. */
function fieldDef(model: string, k: number, r: Rng): LandDef {
  const base = ALL_VEHICLES.find((v) => v.id === model) as LandDef;
  return { ...base, color: LIVERIES[k % LIVERIES.length], topSpeed: base.topSpeed * (1 + 0.04 * r()), accel: base.accel * (1.02 + 0.1 * r()) };
}

/**
 * The fastest a car can take a bend of curvature k (radians a tile) on its own steering: CarState turns at
 * steerRate × min(1, v/1.2) × (1 − 0.45 × v/top), and a bend needs v × k of it. `margin` keeps some lock in hand.
 */
export function cornerSpeed(def: LandDef, k: number, margin: number): number {
  if (k < 1e-3) return Infinity;
  const turn = (v: number) => def.steerRate * Math.min(1, v / 1.2) * (1 - 0.45 * Math.min(1, v / def.topSpeed)) * margin;
  let lo = 0, hi = def.topSpeed * 2;
  if (turn(hi) >= hi * k) return Infinity;
  for (let i = 0; i < 24; i++) { const m = (lo + hi) / 2; if (turn(m) >= m * k) lo = m; else hi = m; }
  return lo;
}

type MeetPhase = 'out' | 'grid' | 'race' | 'cool' | 'done';

/** A CPU car in the meeting. */
export class Racer {
  st: CarState;
  path = new Path();
  /** Distance along the path, and the segment it's on. */
  d = 0; seg = 0;
  lane = 0; laneWant = 0;
  finished: number | null = null;
  place = 0;
  parked = false;
  resets = 0;
  passes = 0;
  /** Seconds of a moment (a lift, a wobble), and until the next can come. */
  moment = 0; momentCool = 6;
  private stuck = 0;
  private bestD = 0;
  /** Seconds it has sat behind something that isn't going anywhere. */
  private walled = 0;
  /** When it may leave its garage on the out lap. */
  release = 0;
  /** Where the lap's racing ends on this car's path (the line after the last lap). */
  finishD = Infinity;

  constructor(readonly id: number, readonly def: LandDef, public w: World, x: number, z: number, heading: number, readonly slot: number, readonly r: Rng) {
    this.st = new CarState(def, x, z, heading, w);
  }

  get x(): number { return this.st.x; }
  get z(): number { return this.st.z; }

  /** Start along a new path from wherever the car is. */
  follow(path: Path): void {
    this.path = path;
    const q = path.project(this.st.x, this.st.z, 0, 0, Math.min(40, path.n));
    this.d = q.d; this.seg = q.seg; this.bestD = this.d; this.stuck = 0; this.parked = false;
  }

  /** One step: `cap` the fastest the phase allows (tiles/s), `racing` whether it may use the lanes. */
  drive(dt: number, cap: number, racing: boolean, others: { x: number; z: number; heading: number; v: number; id: number }[], half: number): void {
    const s = this.st, P = this.path;
    // where it is along its path
    const q = P.project(s.x, s.z, this.seg);
    if (q.off < 3.5 && q.d > this.d - 2) { this.d = q.d; this.seg = q.seg; }
    const rem = P.length - this.d;
    // home: at the end of the path, or as near it as the car parked ahead lets it get
    const fx0 = Math.sin(s.heading), fz0 = Math.cos(s.heading);
    const tucked = rem < 1.3 && Math.abs(s.v) < 0.15 && others.some((o) => o.id !== this.id && Math.abs(o.v) < 0.1
      && (o.x - s.x) * fx0 + (o.z - s.z) * fz0 > 0 && Math.hypot(o.x - s.x, o.z - s.z) < 1.6);
    if ((rem < 0.35 && Math.abs(s.v) < 0.25) || tucked) {
      this.parked = true;
      s.v = 0;
      s.step(this.w, { throttle: 0, steer: 0, lift: 0 }, dt);
      return;
    }
    this.parked = false;
    // the lane: back toward the middle when nothing is in the way
    const laneMax = half - 0.6;
    this.lane += Math.max(-dt * 0.9, Math.min(dt * 0.9, this.laneWant - this.lane));
    const look = 0.9 + Math.abs(s.v) * 0.42;
    const tgt = P.at(this.d + look, this.seg);
    const lane = racing ? this.lane : 0;
    const tx = tgt.x + tgt.tz * lane, tz = tgt.z - tgt.tx * lane;
    const err = wrap(Math.atan2(tx - s.x, tz - s.z) - s.heading);
    const steer = Math.max(-1, Math.min(1, err * 2.6));
    // the speed for what's coming
    // the circuit's asphalt goes like a paved road (car.ts surfaceMul): its top speed there is the car's real one
    const tx0 = Math.floor(s.x), tz0 = Math.floor(s.z);
    const surf = inB(tx0, tz0) ? surfaceMul(this.w, idx(tx0, tz0), this.def) : 1;
    let want = Math.min(cap * surf, this.def.topSpeed * surf);
    // the bends: racing, as hard as the car's steering will take them, braking for each in time; otherwise gently
    const horizon = 1.5 + Math.abs(s.v) * (racing ? 1.1 : 0.9);
    for (let i = this.seg; i < P.n && P.cum[i] < this.d + horizon; i++) {
      // (never below a crawl: a kink in the path sharper than any lock would otherwise stop it dead)
      const vc = racing ? Math.max(0.9, cornerSpeed(this.def, P.k[i], RACE_MARGIN)) : P.vmax[i];
      if (vc === Infinity) continue;
      const gap = Math.max(0, P.cum[i] - this.d - 0.3);
      want = Math.min(want, racing ? Math.sqrt(vc * vc + 2 * this.def.brake * 0.6 * gap) : vc);
    }
    if (this.moment > 0) { this.moment -= dt; want = Math.min(want, this.def.topSpeed * 0.82); }
    // stopping at the end of the path
    want = Math.min(want, Math.sqrt(2 * 1.5 * Math.max(0, rem - 0.2)));
    // anyone ahead: go round them in the racing, fall in behind them otherwise
    const fx = Math.sin(s.heading), fz = Math.cos(s.heading);
    let block: { v: number; fwd: number; side: number } | null = null;
    for (const o of others) {
      if (o.id === this.id) continue;
      const dx = o.x - s.x, dz = o.z - s.z, fwd = dx * fx + dz * fz, side = dx * fz - dz * fx;
      if (fwd > 0.2 && fwd < 1.4 + Math.abs(s.v) * 0.55 && Math.abs(side) < 0.66) {
        if (!block || fwd < block.fwd) block = { v: o.v, fwd, side };
      }
    }
    if (block) {
      if (racing && s.v > block.v - 0.3) {
        // pull out to the side the car ahead isn't on, if nobody is alongside there
        const target = block.side > 0 ? -laneMax * 0.85 : laneMax * 0.85;
        const clear = !others.some((o) => {
          if (o.id === this.id) return false;
          const dx = o.x - s.x, dz = o.z - s.z, fwd = dx * fx + dz * fz, side = dx * fz - dz * fx;
          return Math.abs(fwd) < 1.2 && Math.abs(side - (target - this.lane)) < 0.55;
        });
        if (clear && Math.abs(target - this.laneWant) > 0.3) { this.laneWant = target; this.passes++; }
      }
      want = Math.min(want, block.fwd < 0.7 ? block.v * 0.8 : block.v + 0.05);
      // something stopped dead in the way (a car stalled, the player parked on the track): pull out
      // round it whether or not the lane is clear, and if even that fails, hop past it
      this.walled = racing && block.v < 0.3 ? this.walled + dt : 0;
      if (this.walled > 2) { this.laneWant = block.side > 0 ? -laneMax : laneMax; want = Math.max(want, 0.8); }
      if (this.walled > 7) { this.walled = 0; this.reset(block.fwd + 1.6); return; }
    } else if (racing && this.r() < dt * 0.15) {
      // settle back toward the middle of the road
      this.laneWant *= 0.5;
    }
    const throttle = s.v < want - 0.05 ? 1 : s.v > want + 0.3 ? -1 : s.v > want + 0.08 ? -0.3 : 0;
    s.step(this.w, { throttle, steer, lift: 0 }, dt);
    // a car wedged, or thrown off its line: back on it where it left it, pointing the right way
    if (this.d > this.bestD + 0.3) { this.bestD = this.d; this.stuck = 0; }
    else if (want > 0.5) this.stuck += dt;
    const off = P.project(s.x, s.z, this.seg).off;
    if (this.stuck > 3.5 || off > 4) this.reset(0.8);
  }

  /** Put it back on its path, `ahead` tiles on, pointing along it. */
  reset(ahead: number): void {
    const P = this.path;
    const d = Math.min(P.length, this.d + ahead);
    const q = P.at(d, this.seg);
    this.st = new CarState(this.def, q.x, q.z, Math.atan2(q.tx, q.tz), this.w);
    this.d = d; this.seg = P.segAt(d, this.seg); this.bestD = d; this.stuck = 0;
    this.resets++;
  }

  /** Stand still (on the grid, in the garage). */
  hold(dt: number): void {
    const s = this.st;
    s.step(this.w, { throttle: s.v > 0.05 ? -1 : s.v < -0.05 ? 1 : 0, steer: 0, lift: 0 }, dt);
  }
}

/** The player as an entrant: where they are, read along the path their grid slot starts. */
export interface PlayerEntrant {
  /** The player's car, in this island's frame (null if they're somewhere else); pushed about in contact. */
  st: { x: number; z: number; heading: number; v: number } | null;
  def: LandDef | null;
  slot: number;
  path: Path;
  d: number; seg: number;
  finished: number | null;
  place: number;
  /** On the grid and still. */
  ready: boolean;
}

interface MeetEvents {
  light?(n: number): void;
  go?(): void;
  finish?(who: Racer | PlayerEntrant, place: number, secs: number): void;
}

/**
 * The meeting, from the out lap to the last car parked. `step` is called each frame with the player's
 * car (in this island's frame) when they're entered or nearby; everything else is its own.
 */
export class MeetSim {
  phase: MeetPhase = 'out';
  /** Seconds in this phase, and since the lights went out. */
  t = 0; raceT = 0;
  readonly racers: Racer[] = [];
  readonly p: CircuitPlan;
  readonly f: ReturnType<typeof frameOf>;
  lit = 0;
  /** When the first light came on, in the grid phase's seconds. */
  lightsAt: number | null = null;
  order: (Racer | PlayerEntrant)[] = [];
  player: PlayerEntrant | null = null;
  /** The player had a slot and never took it. */
  noShow = false;
  private lastFinishT = 0;

  constructor(readonly w: World, readonly b: Building, readonly model: string, cars: number, seed: number, entered: boolean, private ev: MeetEvents = {}) {
    this.p = planOf(b);
    this.f = frameOf(b);
    const r = mulberry32(seed);
    const n = Math.min(cars, this.p.garages.length);
    for (let k = 0; k < n; k++) {
      const g = this.p.garages[k];
      const at = toIsland(this.f, g.x, g.z);
      const racer = new Racer(k, fieldDef(model, k, r), w, at.x, at.z, g.heading + this.f.yaw, k, r);
      racer.release = k * 1.5;
      racer.follow(this.outPath(k));
      this.racers.push(racer);
    }
    if (entered) {
      const k = n;
      this.player = { st: null, def: null, slot: Math.min(k, this.p.grid.length - 1), path: this.racePath(Math.min(k, this.p.grid.length - 1)), d: 0, seg: 0, finished: null, place: 0, ready: false };
    }
  }

  /** Garage k onto the pit lane, out at its end, round a slow lap to grid slot k. */
  private outPath(k: number): Path {
    const p = this.p, g = p.garages[k], slot = p.grid[k];
    const pitEnd = p.pit[p.pit.length - 1].s;
    const path = new Path();
    path.add(lapPts(p, this.f, g.s, pitEnd, (s) => pitU(p, s)));
    const sEnd = slot.s < 0 ? slot.s + p.len : slot.s;
    // up the middle of the grid, and only across into its own slot at the last: the column behind a
    // front-row slot is full of cars (and perhaps the player) already waiting in theirs
    path.add(lapPts(p, this.f, pitEnd + DS, sEnd, (s) => ease(0, slot.u, (s - (sEnd - 1.5)) / 1.5)));
    return path;
  }

  /** From grid slot k, easing onto the racing line, three laps, and on round to the pit lane's mouth. */
  private racePath(k: number): Path {
    const p = this.p, slot = p.grid[k];
    const s0 = slot.s - p.len;
    const path = new Path();
    path.add(lapPts(p, this.f, s0, LAPS * p.len + p.len + p.pit[0].s, (s) => ease(slot.u, 0, (s - s0) / 9)));
    return path;
  }

  /** On into the pit lane after the flag, to the garage kept for this finishing place. */
  private pitIn(r: Racer, place: number): void {
    const p = this.p;
    const g = p.garages[Math.min(p.garages.length - 1, place - 1)];
    const base = (LAPS + 1) * p.len;
    const more = lapPts(p, this.f, base + p.pit[0].s + DS, base + g.s, (s) => pitU(p, s - base));
    r.path.add(more);
  }

  /** The player's car this frame, in this island's frame, or null when they're out of it. */
  step(dt: number, me: { st: { x: number; z: number; heading: number; v: number }; def: LandDef } | null): void {
    this.t += dt;
    const p = this.p;
    const others = () => {
      const o = this.racers.map((r) => ({ x: r.st.x, z: r.st.z, heading: r.st.heading, v: r.st.v, id: r.id }));
      if (me) o.push({ x: me.st.x, z: me.st.z, heading: me.st.heading, v: me.st.v, id: -1 });
      return o;
    };
    if (this.player) { this.player.st = me?.st ?? null; this.player.def = me?.def ?? null; }
    switch (this.phase) {
      case 'out': {
        const all = others();
        for (const r of this.racers) {
          if (this.t < r.release) r.hold(dt);
          else r.drive(dt, r.def.topSpeed * 0.62, false, all, p.half);
        }
        const formed = this.racers.every((r) => r.parked);
        if (formed || this.t > 110) {
          // anyone still out of place is put on their slot
          for (const r of this.racers) if (!r.parked) this.putOnSlot(r);
          this.enter('grid');
        }
        break;
      }
      case 'grid': {
        for (const r of this.racers) r.hold(dt);
        // an entered player lines up first; if they never come, the race goes without them
        const pl = this.player;
        if (pl && this.lightsAt === null) {
          const slot = toIsland(this.f, p.grid[pl.slot].x, p.grid[pl.slot].z);
          pl.ready = !!pl.st && Math.hypot(pl.st.x - slot.x, pl.st.z - slot.z) < 1.4 && Math.abs(pl.st.v) < 0.35;
          if (!pl.ready && this.t < 150) break;
          if (!pl.ready) { this.noShow = true; this.player = null; }
        }
        // five lights, one every 0.85 s, then all out together after a beat nobody can guess
        if (this.lightsAt === null) this.lightsAt = this.t;
        const since = this.t - this.lightsAt;
        const lit = Math.min(5, Math.floor(since / 0.85) + 1);
        if (lit > this.lit) { this.lit = lit; this.ev.light?.(lit); }
        if (since > 0.85 * 5 + 0.5 + ((this.b.seed >>> 3) % 7) * 0.15) {
          this.lit = 0;
          for (const [k, r] of this.racers.entries()) { r.follow(this.racePath(k)); r.finishD = r.path.dAtS(LAPS * p.len); }
          if (this.player) { this.player.d = 0; this.player.seg = 0; }
          this.ev.go?.();
          this.enter('race');
        }
        break;
      }
      case 'race':
      case 'cool': {
        this.raceT += dt;
        const all = others();
        for (const r of this.racers) {
          const done = r.finished !== null;
          if (r.moment <= 0 && !done) {
            r.momentCool -= dt;
            if (r.momentCool <= 0) { r.momentCool = 10 + r.r() * 16; if (r.r() < 0.2) r.moment = 0.3 + r.r() * 0.5; }
          }
          r.drive(dt, done ? r.def.topSpeed * 0.55 : r.def.topSpeed, !done, all, p.half);
          if (!done && r.d >= r.finishD) this.cross(r);
        }
        const pl = this.player;
        if (pl && pl.st && pl.finished === null) {
          // the player's progress along their own path: only forward, a step at a time, so a shortcut doesn't count
          const q = pl.path.project(pl.st.x, pl.st.z, pl.seg, 3, 10);
          if (q.off < p.half + 1.4 && q.d > pl.d && q.d < pl.d + 4) { pl.d = q.d; pl.seg = q.seg; }
          if (pl.d >= pl.path.dAtS(LAPS * p.len)) this.cross(pl);
        }
        this.contact(me);
        // nobody races for ever: long past any fair time, whoever is still out is placed by where they are
        if (this.phase === 'race' && this.raceT > (LAPS * p.len) / 1.2 + 40) {
          const left = this.racers.filter((r) => r.finished === null).sort((a, b) => b.d - a.d);
          for (const r of left) this.cross(r);
        }
        const cpuDone = this.racers.every((r) => r.finished !== null);
        if (this.phase === 'race' && cpuDone && (!pl || pl.finished !== null || this.raceT - this.lastFinishT > 45)) {
          if (pl && pl.finished === null) { pl.place = this.order.length + 1; pl.finished = -1; this.ev.finish?.(pl, pl.place, -1); }
          this.enter('cool');
        }
        if (this.phase === 'cool' && (this.racers.every((r) => r.parked) || this.t > 90)) {
          for (const r of this.racers) if (!r.parked) this.putInGarage(r);
          this.enter('done');
        }
        break;
      }
      case 'done':
        for (const r of this.racers) r.hold(dt);
        break;
    }
  }

  private enter(ph: MeetPhase): void { this.phase = ph; this.t = 0; this.lightsAt = null; }

  private cross(who: Racer | PlayerEntrant): void {
    this.order.push(who);
    const place = this.order.length;
    who.place = place;
    who.finished = this.raceT;
    this.lastFinishT = this.raceT;
    if (who instanceof Racer) this.pitIn(who, this.order.filter((q) => q instanceof Racer).length);
    this.ev.finish?.(who, place, this.raceT);
  }

  /** Where the lap's leader is: laps done (1-based lap on now) and positions, for the HUD. */
  standings(): { lap: number; order: (Racer | PlayerEntrant)[] } {
    const len = this.p.len;
    const prog = (e: Racer | PlayerEntrant) => (e.finished !== null && e.finished >= 0 ? 1e6 - e.place : e.path.s[Math.min(e.path.n - 1, e.seg)] ?? 0);
    const list: (Racer | PlayerEntrant)[] = [...this.racers, ...(this.player ? [this.player] : [])];
    list.sort((a, b) => prog(b) - prog(a));
    const lead = list[0];
    const ls = lead && lead.finished === null ? lead.path.s[Math.min(lead.path.n - 1, lead.seg)] : LAPS * len;
    return { lap: Math.max(1, Math.min(LAPS, Math.floor(Math.max(0, ls) / len) + 1)), order: list };
  }

  /** A car that never made its slot is put on it. */
  private putOnSlot(r: Racer): void {
    const g = this.p.grid[r.slot], q = toIsland(this.f, g.x, g.z);
    r.st = new CarState(r.def, q.x, q.z, g.heading + this.f.yaw, this.w);
    r.parked = true;
    r.resets++;
  }

  private putInGarage(r: Racer): void {
    const g = this.p.garages[Math.min(this.p.garages.length - 1, Math.max(0, (r.place || this.racers.length) - 1))];
    const q = toIsland(this.f, g.x, g.z);
    r.st = new CarState(r.def, q.x, q.z, g.heading + this.f.yaw, this.w);
    r.parked = true;
  }

  /**
   * Rubbing is racing: the cars in the meeting (and the player, entered or not) are solid to each other.
   * Each is its own box (halfSize), and two that overlap are pushed apart along the axis they overlap
   * least on, and trade speed along it like two equal weights in a soft knock: a car run into from behind
   * is shoved on and the one behind it is slowed to its pace, so nobody drives through anybody.
   */
  private contact(me: { st: Body; def: LandDef } | null): void {
    const cars: { st: Body; def: LandDef }[] = this.racers.map((r) => ({ st: r.st, def: r.def }));
    if (me) cars.push(me);
    for (let i = 0; i < cars.length; i++) {
      for (let j = i + 1; j < cars.length; j++) {
        const a = cars[i].st, b = cars[j].st;
        const [al, aw] = halfSize(cars[i].def), [bl, bw] = halfSize(cars[j].def);
        const dx = b.x - a.x, dz = b.z - a.z;
        if (dx * dx + dz * dz > (Math.hypot(al, aw) + Math.hypot(bl, bw)) ** 2) continue;
        // separating axes: each box's along and across; the overlap on the one it's least on
        const axes = [Math.sin(a.heading), Math.cos(a.heading), Math.sin(b.heading), Math.cos(b.heading)];
        let best = Infinity, nx = 0, nz = 0;
        for (const [ux, uz] of [[axes[0], axes[1]], [axes[1], -axes[0]], [axes[2], axes[3]], [axes[3], -axes[2]]]) {
          const ra = al * Math.abs(ux * axes[0] + uz * axes[1]) + aw * Math.abs(ux * axes[1] - uz * axes[0]);
          const rb = bl * Math.abs(ux * axes[2] + uz * axes[3]) + bw * Math.abs(ux * axes[3] - uz * axes[2]);
          const c = dx * ux + dz * uz, over = ra + rb - Math.abs(c);
          if (over <= 0) { best = -1; break; }
          if (over < best) { best = over; nx = c < 0 ? -ux : ux; nz = c < 0 ? -uz : uz; }
        }
        if (best <= 0) continue;
        // apart, half each, along the normal from a to b
        a.x -= nx * best * 0.5; a.z -= nz * best * 0.5;
        b.x += nx * best * 0.5; b.z += nz * best * 0.5;
        // the knock: equal weights, a little bounce; each car keeps only the part of its new velocity along its own travel
        const ca = a.course ?? a.heading, cb = b.course ?? b.heading;
        const vax = Math.sin(ca) * a.v, vaz = Math.cos(ca) * a.v, vbx = Math.sin(cb) * b.v, vbz = Math.cos(cb) * b.v;
        const closing = (vax - vbx) * nx + (vaz - vbz) * nz;
        if (closing <= 0) continue;
        const k = closing * (1 + BUMP) * 0.5;
        a.v = (vax - nx * k) * Math.sin(ca) + (vaz - nz * k) * Math.cos(ca);
        b.v = (vbx + nx * k) * Math.sin(cb) + (vbz + nz * k) * Math.cos(cb);
        // and rubbing scrubs: a side-on touch costs a little too
        a.v *= 0.97; b.v *= 0.97;
      }
    }
  }
}

/** Where a car in contact is and how it's going: a CarState, the player's or a racer's. */
type Body = { x: number; z: number; heading: number; v: number; course?: number };
/** How springy a knock between two race cars is: 0 dead, 1 a perfect bounce. */
const BUMP = 0.25;

const wrap = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));

/** Run a whole meeting with nobody watching, for the gate: how long each part took and whether everyone got round. */
export function runMeetHeadless(w: World, b: Building, cars: number, seed: number): {
  model: string; cars: number; gridSecs: number; raceSecs: number; parkSecs: number; finished: number; resets: number; passes: number; parked: boolean;
} {
  const p = planOf(b);
  const model = pickModel(p, mulberry32(seed * 7 + 1));
  const sim = new MeetSim(w, b, model, cars, seed, false);
  const DT = 1 / 30;
  let t = 0;
  const began: Partial<Record<MeetPhase, number>> = { out: 0 };
  while (sim.phase !== 'done' && t < 900) {
    const was = sim.phase;
    sim.step(DT, null);
    t += DT;
    if (sim.phase !== was) began[sim.phase] = t;
  }
  const gridSecs = began.grid ?? t, raceSecs = (began.cool ?? t) - (began.race ?? t), parkSecs = (began.done ?? t) - (began.cool ?? t);
  return {
    model, cars: sim.racers.length, gridSecs, raceSecs, parkSecs,
    finished: sim.racers.filter((r) => r.finished !== null).length,
    resets: sim.racers.reduce((a, r) => a + r.resets, 0), passes: sim.racers.reduce((a, r) => a + r.passes, 0),
    parked: sim.phase === 'done',
  };
}
