import { DRIVE_WEATHER } from './car';

/**
 * The convertible's roof (docs/rides.html). It follows the weather and the clock, the same for every
 * Sunny on the road, so after a shower passes every convertible in town opens up together.
 * main.ts writes the night each frame; the weather is the one the car already drives through.
 */
export const ROOF_SKY = { night: 0 };

/** Should a convertible's roof be up right now? */
export function roofUp(): boolean {
  const w = DRIVE_WEATHER;
  return w.rain > 0.25 || w.dust > 0.3 || w.blizzard > 0.05 || ROOF_SKY.night > 0.5;
}

/** A people load pays this much more when the roof was down for most of its ride. */
export const TOP_DOWN_BONUS = 0.25;
/** The share of the ride the roof must have been down. */
export const TOP_DOWN_SHARE = 0.75;
