import { N, idx, type Building, type Town, type TownKind, type World } from '../world/tiles';
import { TOWN_INFO } from '../world/towns';
import { PLAN_INFO } from '../world/plans/registry';
import type { PlanId } from '../world/plans/types';
import { GRADUATION, builtCount } from '../world/growth';
import { REGIONS } from '../world/regions';
import { seatLabel, seatOf, shapeOf, type TownShape } from '../world/townShape';
import { airportsOf } from '../world/airportTowns';
