export type { WhatsOn } from './townTabs/whatson';

/**
 * The town card (docs/towns.html, docs/townregister.html): a town selected as a whole — from its name in the
 * overview, its hall close up, a building's card or the world map — gets its border drawn over the ground and this
 * card on the left, in nine tabs: Overview, Buildings, Culture, Trade, Getting there, Works, What's on, Standing and
 * Your fleet. A town whose island has gone out of memory keeps its card in "far mode": the books and its last
 * digest, no streets. The new tabs are drawn by game/townTabs/*.ts from a TabCtx the card gathers.
 */

export type Tab = 'overview' | 'buildings' | 'culture' | 'trade' | 'transport' | 'works' | 'whatson' | 'standing' | 'fleet';

/** The tab strip: id, icon, label. */
const TABS: [Tab, string, string][] = [
  ['overview', '🏛️', 'Overview'], ['buildings', '🏢', 'Buildings'], ['culture', '🎎', 'Culture'], ['trade', '💰', 'Trade'],
  ['transport', '🚉', 'Getting there'], ['works', '🌉', 'Works'], ['whatson', '📅', 'What’s on'], ['standing', '🏁', 'Standing'],
  ['fleet', '🚚', 'Your fleet'],
];
const TAB_IDS = TABS.map(([id]) => id);
/** Tabs saved by the three-tab card, to the tab that has their rows now. */
const OLD_TAB: Record<string, Tab> = { town: 'overview', company: 'fleet' };

interface TownCardHost {
  /** Islands in memory. */
  worlds(): World[];
  economy: Economy;
  cargo: CargoSystem;
  fleet: Fleet;
  requests: Requests;
  atlas: Atlas;
  /** Where the player's own vehicle is, in its cell's tiles. */
  player(): { cx: number; cz: number; x: number; z: number } | null;
  /** The request board, open at this town's first ask. */
  openBoard(key: string): void;
  /** A card at the top of the screen. */
  say(title: string, body: string): void;
  /** A building's own card, from the busiest-lots list. */
  selectBuilding(w: World, b: Building): void;
  /** The camera on the town, or off it. */
  follow(on: boolean): void;
  following(): boolean;
  /** The card has let go of the town (its ×). */
  closed(): void;
  /** The deed book (docs/property.html). */
  estate: Estate;
  /** The rival firms (docs/rivals.html), for who carries the town. */
  firms?: Firms;
  /** Fleets' asks for more ground (docs/lobbying.html; building asks were retired for blueprints, docs/blueprints.html). */
  lobby?: Lobby;
  /** Who holds the town as territory, and what it pays (docs/territory.html). */
  territory?: Territory;
  /** Open the world map with the territory layer on. */
  showTerritory?(): void;
  /** The town's culture (docs/passport.html): what it has imported, by style, and which is the fleet's home town. */
  culture?: { strands(key: string): Strand[]; twins(key: string): string[]; homeKey(): string | null; festivalLeft(key: string): number; hall?(key: string): 'hq' | 'held' | null;
    /** Who brought it each style, most first (docs/townregister.html). */
    contributors?(key: string, style: Strand['style']): { name: string; pts: number; you: boolean }[] };
  /** The styles a blueprint may go up in inside a town's lines (game/blueprints.ts stylesAt): its own first. */
  stylesHere?(key: string): string[];
  /**
   * What's on (docs/townregister.html) over the next week: its stadium's home fixtures, and the events and markets of its
   * county (the calendar names a county, not a town). Game hours it starts and ends; `here` true for the town's own.
   */
  whatsOn?(key: string): WhatsOn[];
  /** Bookmarks: whether this town is starred, and starring it. */
  star?: { has(key: string): boolean; toggle(key: string, name: string, at: { x: number; z: number }): void };
  /** The paper this town publishes, if its issues are in the archive (docs/newspaper.html), and opening its latest. */
  paper?(key: string): { name: string; n: number; count: number } | null;
  openPaper?(n: number): void;
  /** Where the HQ stands, in world tiles. */
  hq?(): { x: number; z: number; name: string } | null;
  /** Yellow arrows from the car to the town (its seat), or off again; and whether they are up for it. */
  route?(key: string): void;
  routing?(key: string): boolean;
  /** The world map, on this town. */
  showMap?(): void;
  /** The town register on this town (docs/townregister.html). */
  register?(key: string): void;
}

const pct = (v: number) => `${Math.round(v * 100)}%`;
const pct1 = (v: number) => `${(v * 100).toFixed(1)}%`;

/** Seconds between redraws of the card's numbers. */
const REFRESH = 0.25;
const TAB_KEY = 'pocket-roads-town-tab';

export class TownCard {
  /** The town on the card: its key always, its island and town while they are in memory. */
  key = '';
  w: World | null = null;
  t: Town | null = null;
  private shape: TownShape | null = null;
  private tab: Tab = 'overview';
  /** Every town in memory this session, digested (docs/townregister.html). */
  readonly index = new TownIndex();
  private indexTimer = 0;
  private foot = document.createElement('footer');
  private picking = false;
  /** Online: what other players built in the town's county, for the company tab (net/community.ts). */
  builtHere: ((townKey: string) => string) | null = null;
  /** A town's own works (net/community.ts townWorks): the totals, and the list drawn by hearts, crossings or newest. */
  townWorks: ((townKey: string) => { n: number; hearts: number; uses: number; builders: number } | null) | null = null;
  townWorksHtml: ((townKey: string, by: 'hearts' | 'uses' | 'new') => string) | null = null;
  /** How the Works tab's list is ordered. */
  private worksBy: 'hearts' | 'uses' | 'new' = 'hearts';
  /** Online: who has held the town as territory, newest first (net/marks.ts, docs/marks.html). */
  holders: ((townKey: string) => { who: string; day: number }[]) | null = null;
  private timer = 0;
  private html = '';
  private panel = document.createElement('div');
  private head = document.createElement('header');
  private tabs = document.createElement('nav');
  private body = document.createElement('div');
  readonly border: TownBorder;

  constructor(scene: THREE.Scene, private host: TownCardHost) {
    this.border = new TownBorder(scene);
    try {
      const t = localStorage.getItem(TAB_KEY) ?? '';
      const tab = OLD_TAB[t] ?? (TAB_IDS.includes(t as Tab) ? (t as Tab) : null);
      if (tab) this.tab = tab;
    } catch { /* storage blocked */ }
    this.panel.id = 'town';
    this.panel.className = 'hud chip';
    this.panel.hidden = true;
    const close = document.createElement('button');
    close.className = 'x';
    close.type = 'button';
    close.title = 'Close';
    close.textContent = '×';
    close.addEventListener('click', () => this.host.closed());
    this.tabs.className = 'tabs';
    this.tabs.setAttribute('role', 'tablist');
    for (const [id, icon, label] of TABS) {
      const b = document.createElement('button');
      b.type = 'button';
      b.dataset.tab = id;
      b.setAttribute('role', 'tab');
      b.setAttribute('aria-label', label);
      b.title = label;
      b.innerHTML = `<span class="i">${icon}</span><span class="l">${label}</span>`;
      this.tabs.append(b);
    }
    this.tabs.addEventListener('keydown', (e) => {
      if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
      const n = TAB_IDS.length;
      const k = (TAB_IDS.indexOf(this.tab) + (e.key === 'ArrowRight' ? 1 : n - 1)) % n;
      this.setTab(TAB_IDS[k]);
      (this.tabs.children[k] as HTMLElement).focus();
      e.preventDefault();
      e.stopPropagation();
    });
    this.foot.className = 'tc-foot';
    this.panel.append(close, this.head, this.tabs, this.body, this.foot);
    this.panel.addEventListener('click', (e) => this.onClick(e));
    // a press on the card isn't a click on the world underneath
    this.panel.addEventListener('mousedown', (e) => e.stopPropagation());
    document.body.append(this.panel);
  }

  get open(): boolean { return !this.panel.hidden; }

  /** Put a town on the card, near (its island in memory) or far (only its key). */
  show(key: string, w: World | null, t: Town | null): void {
    if (key !== this.key) this.picking = false;
    this.key = key;
    this.w = w;
    this.t = t;
    this.panel.hidden = false;
    this.html = '';
    this.timer = 0;
    this.sync();
    this.render();
  }

  hide(): void {
    this.key = '';
    this.w = null;
    this.t = null;
    this.shape = null;
    this.panel.hidden = true;
    this.border.set(null, null, null);
  }

  /** Hidden while a full-screen panel is up, back when it goes. */
  setCovered(covered: boolean): void {
    if (this.key) this.panel.hidden = covered;
  }

  /** The middle of the town in world tiles, near or far. */
  centre(): { x: number; z: number; size: number } | null {
    if (this.w && this.t) {
      const s = this.shape ?? shapeOf(this.w, this.t);
      return { x: this.w.ox + s.cx, z: this.w.oz + s.cz, size: Math.max(s.bw, s.bh) };
    }
    const p = this.host.atlas.place(this.key);
    return p ? { x: p.cx * N + p.x, z: p.cz * N + p.z, size: 40 } : null;
  }

  /** The loops in world tiles, for the map. */
  worldLoops(): Float32Array[] {
    if (!this.w || !this.shape) return [];
    const ox = this.w.ox, oz = this.w.oz;
    return this.shape.loops.map((l) => {
      const out = new Float32Array(l.length);
      for (let k = 0; k < l.length; k += 2) { out[k] = l[k] + ox; out[k + 1] = l[k + 1] + oz; }
      return out;
    });
  }

  /** The name on the card. */
  name(): string {
    return this.t?.name ?? this.host.atlas.place(this.key)?.name ?? 'A town';
  }

  update(dt: number, camera: THREE.Camera): void {
    this.border.update(dt, camera);
    // the towns in memory, digested once a game hour each (the ranks on the Overview)
    this.indexTimer -= dt;
    if (this.indexTimer <= 0) {
      this.indexTimer = 1;
      this.index.refresh(this.host.worlds(), this.host.economy.hours);
    }
    if (!this.key) return;
    this.timer -= dt;
    if (this.timer > 0) return;
    this.timer = REFRESH;
    this.sync();
    this.render();
  }

  /** Near or far: the island coming into memory or going out of it, and the shape if it has changed. */
  private sync(): void {
    const [cell, id] = this.key.split('#');
    const [cx, cz] = cell.split(',').map(Number);
    const w = this.host.worlds().find((q) => q.cx === cx && q.cz === cz) ?? null;
    const t = w?.towns[Number(id)] ?? null;
    this.w = w && t ? w : null;
    this.t = w && t ? t : null;
    this.shape = this.w && this.t ? shapeOf(this.w, this.t) : null;
    this.border.set(this.w, this.t, this.shape);
  }

  private setTab(t: Tab): void {
    this.tab = t;
    try { localStorage.setItem(TAB_KEY, t); } catch { /* storage blocked */ }
    this.html = '';
    this.render();
  }

  // ---- clicks on the card ----

  private onClick(e: MouseEvent): void {
    const el = (e.target as HTMLElement).closest('[data-tab], [data-act], [data-base], [data-lot], [data-show], [data-wby]') as HTMLElement | null;
    if (!el) return;
    if (el.dataset.wby) { this.worksBy = el.dataset.wby as 'hearts' | 'uses' | 'new'; this.render(); return; }
    const tab = el.dataset.tab as Tab | undefined;
    if (tab) { this.setTab(tab); return; }
    if (el.dataset.base) { this.baseHere(Number(el.dataset.base)); return; }
    if (el.dataset.show) {
      const list = buildingsToShow(this.ctx(), el.dataset.show);
      if (this.w && list.length) this.border.showBuildings(this.w, list);
      return;
    }

    if (el.dataset.lot && this.w && this.t) {
      const b = this.t.buildings.find((q) => q.uid === Number(el.dataset.lot));
      if (b) this.host.selectBuilding(this.w, b);
      return;
    }
    switch (el.dataset.act) {
      case 'pick': this.picking = !this.picking; this.html = ''; this.render(); break;
      case 'send': this.sendIdle(); break;
      case 'follow': this.host.follow(!this.host.following()); this.render(); break;
      case 'route': this.host.route?.(this.key); this.render(); break;
      case 'map': this.host.showMap?.(); break;
      case 'register': this.host.register?.(this.key); break;
      case 'board': this.host.openBoard(this.key); break;
      case 'blight': if (this.w && this.t) this.border.showBuildings(this.w, this.t.buildings.filter((b) => b.derelict && !b.gone)); break;
      case 'seat': { const s = this.t && seatOf(this.t); if (this.w && s) this.border.showBuildings(this.w, [s]); break; }

      case 'terr-map': this.host.showTerritory?.(); break;
      case 'paper': this.host.openPaper?.(Number(el.dataset.n)); break;
      case 'ask-land': this.askLand(); break;
      case 'ask-clear': this.host.lobby?.clear(this.key); this.html = ''; this.render(); break;
      case 'star': { const c = this.centre(); if (c) this.host.star?.toggle(this.key, this.name(), c); this.html = ''; this.render(); break; }
    }
  }

  /** A unit of yours based here: the base a town (or its harbour, for a boat) its order goes back to. */
  private baseHere(uid: number): void {
    const { fleet } = this.host;
    const u = fleet.unit(uid);
    if (!u) return;
    const base = this.basesHere(u)[0];
    if (!base) return;
    fleet.chooseBase(u, base);
    this.host.say(u.name, `now based at ${base.name}`);
    this.picking = false;
    this.html = '';
    this.render();
  }

  private basesHere(u: Unit) {
    const [cx, cz, id] = this.keyParts();
    const w = this.w;
    return this.host.fleet.basesFor(u).filter((b) => b.cx === cx && b.cz === cz
      && (b.kind === 'town' ? b.id === id : !!w && w.ports.find((p) => p.id === b.id)?.town === id));
  }

  private keyParts(): [number, number, number] {
    const [cell, id] = this.key.split('#');
    const [cx, cz] = cell.split(',').map(Number);
    return [cx, cz, Number(id)];
  }

  /** The idle unit of yours on this island that could take most of the town's waiting work: sent for it. */
  private sendIdle(): void {
    const idle = this.idleUnits();
    const loads = this.waiting();
    let best: Unit | null = null, bestV = 0;
    for (const u of idle) {
      const def = defOf(u.model);
      const v = loads.filter((it) => canHaul(def, it)).reduce((s, it) => s + it.value, 0);
      if (v > bestV) { bestV = v; best = u; }
    }
    if (!best) {
      this.host.say(this.name(), idle.length ? 'None of your idle vehicles here can carry what is waiting' : 'None of your vehicles on this island is idle just now');
      return;
    }
    best.lure = this.key;
    const d = this.host.fleet.driverOf(best);
    this.host.say(best.name, `${d ? `${d.name} is` : 'Heading'} off for ${this.name()}'s loads, about ${money(bestV)} waiting`);
  }

  // ---- what the card reads ----

  /** Which town a cargo site's trade counts for, by key. */
  private siteKey(s: Site | null): string {
    const f = this.host.economy.townFor(s);
    return f ? townKey(f.w, f.t) : '';
  }

  /** Loads waiting to be picked up in this town, nobody on the way for them. */
  private waiting(): CargoItem[] {
    return this.host.cargo.items.filter((it) => it.ttl > 0 && !it.claimedBy && !it.type.ultra && this.siteKey(it.from) === this.key);
  }

  /** Your working units on this island with nothing to do. */
  private idleUnits(): Unit[] {
    const [cx, cz] = this.keyParts();
    return this.host.fleet.units.filter((u) => u.where === 'working' && u.cx === cx && u.cz === cz && !!u.agent && !u.agent.run && !u.order.wait && !!u.driver);
  }

  // ---- drawing ----

  private render(): void {
    if (!this.key) return;
    const near = !!(this.w && this.t);
    const r = this.host.economy.towns.get(this.key);
    const kind: TownKind = (this.t?.kind ?? r?.kind ?? (this.host.atlas.place(this.key)?.kind as TownKind | undefined) ?? 'rural');
    const head = this.headHtml(kind);
    if (head !== this.head.innerHTML) this.head.innerHTML = head;
    for (const b of Array.from(this.tabs.children) as HTMLElement[]) {
      const on = b.dataset.tab === this.tab;
      b.classList.toggle('on', on);
      b.setAttribute('aria-selected', String(on));
      b.tabIndex = on ? 0 : -1;
    }
    const c = this.ctx(kind);
    for (const b of Array.from(this.tabs.children) as HTMLElement[]) b.classList.toggle('dim', this.empty(b.dataset.tab as Tab, c));
    const rate = (key: string) => this.host.economy.towns.get(key)?.rate ?? 0;
    const html = this.tab === 'overview' ? overviewTab(c, rate)
      : this.tab === 'buildings' ? buildingsTab(c)
      : this.tab === 'culture' ? this.cultureTab()
      : this.tab === 'trade' ? this.tradeTab(c)
      : this.tab === 'transport' ? transportTab(c, this.tollTiles())
      : this.tab === 'works' ? this.worksTab(c)
      : this.tab === 'whatson' ? this.whatsOnTab()
      : this.tab === 'standing' ? this.standingTab()
      : this.fleetTab();
    if (html !== this.html) { this.html = html; this.body.innerHTML = html; }
    const foot = this.footHtml(near);
    if (foot !== this.foot.innerHTML) this.foot.innerHTML = foot;
  }

  /** What the tabs are drawn from (game/townTabs/common.ts). */
  private ctx(kind?: TownKind): TabCtx {
    const { economy } = this.host;
    const w = this.w, t = this.t;
    const k: TownKind = kind ?? t?.kind ?? economy.towns.get(this.key)?.kind ?? (this.host.atlas.place(this.key)?.kind as TownKind | undefined) ?? 'rural';
    const near = !!(w && t);
    const p = this.host.player();
    return {
      key: this.key, w, t, shape: this.shape, kind: k, name: this.name(),
      digest: near ? { ...digestOf(w!, t!, economy.hours, this.shape?.area), ...(this.index.get(this.key)?.works ? { works: this.index.get(this.key)!.works } : {}) } : this.index.get(this.key),
      index: this.index,
      ledger: near ? economy.ensure(w!, t!) : economy.towns.get(this.key) ?? null,
      mood: near ? { mood: economy.mood(w!, t!), p: economy.prosperity(w!, t!) } : null,
      hours: economy.hours,
      label: labelOf,
      link: townLink,
      player: p ? { x: p.cx * N + p.x, z: p.cz * N + p.z } : null,
      hq: this.host.hq?.() ?? null,
    };
  }

  /** A tab with nothing in it for this town: dimmed in the strip, never hidden, so the strip doesn't jump. */
  private empty(tab: Tab, c: TabCtx): boolean {
    const d = c.digest;
    switch (tab) {
      case 'culture': return !(this.host.culture?.strands(this.key).length) && !this.host.culture?.hall?.(this.key);
      case 'transport': return !!d && !d.ports && !d.stations && !d.airports && !d.roadsTo;
      case 'works': return !this.tollTiles() && !d?.playerBuilt && !d?.works?.[0] && !(this.builtHere?.(this.key));
      default: return false;
    }
  }

  /** The buttons under every tab. */
  private footHtml(near: boolean): string {
    const following = this.host.following();
    const routing = this.host.routing?.(this.key) ?? false;
    return `<button type="button" data-act="follow" class="${following ? 'on' : ''}">${following ? 'Stop following' : '👁 Follow'}</button>`
      + (this.host.route ? `<button type="button" data-act="route" class="${routing ? 'on' : ''}" ${near || routing ? '' : 'disabled title="Drive nearer: its streets aren’t in memory"'}>${routing ? '➜ Routing · stop' : '➜ Route here'}</button>` : '')
      + (this.host.showMap ? '<button type="button" data-act="map">🗺 Map</button>' : '')
      + (this.host.register ? '<button type="button" data-act="register" class="all" title="Every town you know of, ranked">All towns ›</button>' : '');
  }

  private headHtml(kind: TownKind): string {
    const t = this.t;
    const name = this.name();
    const region = t?.region ? REGIONS[t.region]?.title : '';
    const sub = [TOWN_INFO[kind].label, region ? cap(region) : '', t ? `${[cap(pretty(t.style)), ...(this.host.culture?.twins(this.key) ?? [])].join(' + ')} style` : ''].filter(Boolean).join(' · ');
    const mayor = mayorOf(name.replace(/ City$/, '')).name;
    const g = GRADUATION[kind];
    const steps = t && g && !(t.parent !== undefined && g.to === 'metro') ? gradSteps(t, g) : null;
    const grad = steps ? ` · ${steps.done} of ${steps.all} steps to ${TOWN_INFO[g!.to].label.toLowerCase()}` : '';
    const w = this.w;
    let family = '';
    if (w && t) {
      if (t.parent !== undefined && w.towns[t.parent]) family = `<p class="fam">Satellite of ${townLink(townKey(w, w.towns[t.parent]), w.towns[t.parent].name)}</p>`;
      const sats = w.towns.filter((q) => q.parent === t.id);
      if (sats.length) family = `<p class="fam">Satellites: ${sats.map((q) => townLink(townKey(w, q), q.name)).join(', ')}</p>`;
    }
    const star = this.host.star ? `<button type="button" class="tc-star${this.host.star.has(this.key) ? ' on' : ''}" data-act="star" title="Bookmark this town in your Passport">${this.host.star.has(this.key) ? '★' : '☆'}</button>` : '';
    // its city plan (GEN 53, docs/cityplans.html), and the real place it is after: none for a town on today's grid
    const plan = t?.plan && t.plan !== 'grid' ? PLAN_INFO[t.plan as PlanId] : null;
    const planLine = plan ? `<p class="mayor plan">Plan · ${esc(plan.label)}${plan.id === 'channel' ? '' : `, after ${esc(plan.after)}`}</p>`
      // an onsen town (GEN 53, world/onsen.ts), and the hot-spring town it is after
      : t?.onsen ? `<p class="mayor plan">Onsen town ♨️, after ${esc(t.onsen)}</p>`
      // a lake town (GEN 53, world/lakes.ts), and the resort lake it is after
      : t?.lake ? `<p class="mayor plan">Lake town ⛵, after ${esc(t.lake)}</p>` : '';
    return `<span class="ic">🏛️</span><b>${esc(name)}${star}</b><small>${esc(sub)}</small><p class="mayor">Mayor ${esc(mayor)}${esc(grad)}</p>${planLine}${family}`;
  }

  // ---- tab 1, Overview, and tab 2, Buildings: game/townTabs/overview.ts and buildings.ts ----

  // ---- tab 3: culture ----

  /** What the town has imported (docs/passport.html, docs/culturegate.html): each style's bar to its next rung. */
  private cultureTab(): string {
    const c = this.host.culture;
    if (!c) return '<p class="note">Culture is kept in the Passport (P).</p>';
    const strands = c.strands(this.key);
    const home = c.homeKey() === this.key;
    const hall = c.hall?.(this.key) ?? (home ? 'hq' : null);
    const fest = c.festivalLeft(this.key);
    let out = '';
    if (hall === 'hq') out += '<p class="note tc-hall">Your home town: your HQ takes cultural goods.</p>';
    else if (hall === 'held') out += '<p class="note tc-hall">Held as your territory: its hall takes cultural goods.</p>';
    if (fest > 0) out += `<p class="note"><em class="good">Festival on · ${Math.ceil(fest)} game hours left</em></p>`;
    if (!strands.length) {
      return out + `<p class="note">${hall ? 'Nothing imported yet: bring it cultural goods from somewhere it has never received from.' : 'It has taken in no other culture yet. Cultural goods handed in at a town you hold, or at your HQ, start one.'}</p>`;
    }
    out += '<div class="tc-strands">' + strands.map((s) => {
      const fill = s.next ? Math.min(100, (s.pts / s.next) * 100) : 100;
      const state = s.rung ? RUNG_NAME[s.rung] : 'Not yet curious';
      // who brought it: the top three fleets, you among them if you gave any (docs/townregister.html)
      const who = c.contributors?.(this.key, s.style) ?? [];
      const named = who.slice(0, 3).map((x) => `${x.you ? '<b>you</b>' : esc(x.name || 'a fleet')} ${Math.round(x.pts)}`);
      const you = who.findIndex((x) => x.you);
      if (you >= 3) named.push(`<b>you</b> ${Math.round(who[you].pts)}`);
      const by = who.length ? `brought by ${named.join(', ')}${who.length > named.length ? ` and ${who.length - named.length} more` : ''}` : [s.mine ? `${Math.round(s.mine)} of them yours` : '', s.lead ? `most by ${esc(s.lead)}` : ''].filter(Boolean).join(' · ');
      return `<div class="tc-strand r${s.rung}"><div class="row"><b>${esc(s.label)}</b><span>${state}</span></div>`
        + `<div class="bar"><i style="width:${fill.toFixed(1)}%"></i></div>`
        + `<small>${Math.round(s.pts)}${s.next ? ` of ${s.next} points to ${RUNG_NAME[Math.min(3, s.rung + 1)]}` : ' points'}${by ? ` · ${by}` : ''}</small>`
        + (s.needs ? `<small class="needs">Needs ${esc(s.needs)}</small>` : '') + '</div>';
    }).join('') + '</div>';
    const here = this.host.stylesHere?.(this.key) ?? [];
    if (here.length > 1) out += `<p class="note">Blueprints may go up here in ${esc(here.join(', '))}: its own style first, then each culture it is Influenced by.</p>`;
    else {
      const influenced = strands.filter((s) => s.rung >= 2).map((s) => s.label);
      if (influenced.length) out += `<p class="note">Fleets may put up ${esc(influenced.join(', '))} buildings from their blueprints inside its lines.</p>`;
    }
    return out;
  }

  // ---- tab 6: works ----

  /** What fleets have built here: the county's player works (online), fleet-built buildings, your toll bridges. */
  private worksTab(c: TabCtx): string {
    const d = c.digest;
    const rows: [string, string][] = [];
    // its own works: those whose tiles lie mostly in its lines (docs/townregister.html)
    const tw = c.w ? this.townWorks?.(this.key) ?? null : null;
    const n = tw?.n ?? d?.works?.[0] ?? 0, hearts = tw?.hearts ?? d?.works?.[1] ?? 0, uses = tw?.uses ?? d?.works?.[2] ?? 0;
    if (n) rows.push(['Works', `${n} in its lines · <b class="hrt">♥ ${hearts}</b>${uses ? ` · ${uses} crossing${uses === 1 ? '' : 's'} by other fleets` : ''}${tw ? ` · ${tw.builders} builder${tw.builders === 1 ? '' : 's'}` : ` <small>${c.w ? '' : 'when last here'}</small>`}`]);
    if (d?.playerBuilt) rows.push(['Fleet-built', `${d.playerBuilt} building${d.playerBuilt === 1 ? '' : 's'} put up from blueprints${c.w ? ' <button type="button" class="link" data-show="erected">show</button>' : ''}`]);
    const tolls = this.tollTiles();
    if (tolls) rows.push(['Toll bridges', `${tolls} tile${tolls === 1 ? '' : 's'} of yours in town`]);
    const county = this.builtHere?.(this.key) ?? '';
    const own = c.w && tw?.n ? this.townWorksHtml?.(this.key, this.worksBy) ?? '' : '';
    if (!rows.length && !county) return `${c.w ? '' : farNote()}<p class="note">Nothing built here by a fleet yet: roads, bridges, earthworks and buildings players put up show here.</p>`;
    const by = (k: 'hearts' | 'uses' | 'new', label: string) => `<button type="button" data-wby="${k}" class="${this.worksBy === k ? 'on' : ''}">${label}</button>`;
    return (c.w ? '' : farNote()) + (rows.length ? dl(rows) : '')
      + (own ? `<h4>In its lines <span class="tc-wby">${by('hearts', '♥ most loved')}${by('uses', 'busiest')}${by('new', 'newest')}</span></h4>${own}` : '')
      + county.replace('<h4>Built here</h4>', '<h4>In its county <span>most loved</span></h4>');
  }

  // ---- tab 7: what's on ----

  /** Its asks, its festival and its paper. */
  private whatsOnTab(): string {
    const [cx, cz, id] = this.keyParts();
    const rows: [string, string][] = [];
    let out = calendarHtml(this.host.whatsOn?.(this.key) ?? [], this.host.economy.hours, this.index.get(this.key)?.county ?? '');
    const asks = this.host.requests.open.filter((q) => q.cell[0] === cx && q.cell[1] === cz && q.townId === id);
    rows.push(['Asks', asks.length
      ? asks.map((q) => `<div class="u"><b>${esc(q.title)}</b> <span>${q.state === 'taken' ? `step ${Math.min(q.step + 1, q.steps.length)} of ${q.steps.length}` : `${q.steps.length} jobs · ${money(q.reward)}`}</span></div>`).join('')
      : '<span class="none">nothing asked just now</span>']);
    const fest = this.host.culture?.festivalLeft(this.key) ?? 0;
    if (fest > 0) rows.push(['Festival', `<em class="good">on now · ${Math.ceil(fest)} game hours left</em>`]);
    const paper = this.host.paper?.(this.key);
    if (paper) rows.push(['Paper', `Publishes <em>${esc(paper.name)}</em> · ${paper.count} issue${paper.count === 1 ? '' : 's'} <button type="button" class="link" data-act="paper" data-n="${paper.n}">read the latest</button>`]);
    out += `<h4>Here</h4>${dl(rows)}`;
    return out + `<div class="acts"><button type="button" data-act="board">Requests</button></div>`;
  }

  // ---- your say in how far it reaches (docs/lobbying.html; building asks went to blueprints, docs/blueprints.html) ----

  /** The row under Growth: your share, and the one ask left to a town: to take in more ground. */
  private sayHtml(): string {
    const lobby = this.host.lobby;
    if (!lobby) return '';
    const share = lobby.influence(this.key);
    const pct = `${Math.round(share * 100)}%`;
    const land = lobby.queue(this.key).find((p) => p.what === 'territory');
    if (!land) {
      if (share <= 0) return '<span class="say"><span>No say here yet: carry something for this town</span></span>';
      return `<span class="say"><span>${pct} chance at each new building that it grows its limits instead, if asked</span><button type="button" class="link" data-act="ask-land" title="${CLAIM_TILES} tiles of new ground, taken in where its border is nearest its heart: room to build on later">Ask it to grow</button></span>`;
    }
    const odds = share > 0 ? `${pct} at each new building` : '<span class="red">no say here now</span>';
    const why = land.blocked ? ' <span class="red">no ground left</span>' : '';
    const wait = land.waited ? ` <small>${land.waited} waited</small>` : '';
    return `<span class="say"><span>Asked to grow the town limits (+${CLAIM_TILES} tiles) · ${odds}${why}${wait}</span><button type="button" class="link" data-act="ask-clear">take it down</button></span>`;
  }

  private askLand(): void {
    const w = this.w, t = this.t, lobby = this.host.lobby;
    if (!w || !t || !lobby) return;
    const why = lobby.askTerritory(w, t);
    if (why) { this.host.say(t.name, why); return; }
    this.host.say(t.name, `You’ve asked it to take in ${CLAIM_TILES} tiles of new ground: shaded where it would take them now`);
    this.html = '';
    this.render();
  }

  private tollTiles(): number {
    const s = this.shape, w = this.w;
    if (!s || !w) return 0;
    let n = 0;
    for (let z = 0; z < s.bh; z++) for (let x = 0; x < s.bw; x++) {
      if (!s.mask[z * s.bw + x]) continue;
      const tx = s.x0 + x, tz = s.z0 + z;
      if (tx >= 0 && tz >= 0 && tx < N && tz < N && w.deckToll[idx(tx, tz)]) n++;
    }
    return n;
  }

  // ---- tab 4: trade ----

  private tradeTab(c: TabCtx): string {
    const { economy } = this.host;
    // its trade over its days, and the levy: near or far
    const r = c.ledger;
    const top: [string, string][] = [];
    const norm = ECONOMY.norm[c.kind];
    if (r) {
      top.push(['Trade', `${perHour(r.rate)} of ${perHour(norm)} a town this size expects`]);
      const chart = tradeChart(r, norm);
      top.push(['History', chart ? `${chart}<small class="tc-chart-key">its last ${r.hist!.length} days · - - expected · ● grew a building</small>` : '<span class="none">kept from its next midnight on</span>']);
      if (c.w && c.t) {
        const next = ECONOMY.threshold[c.kind] * (r.tax / ECONOMY.taxStep + 1);
        top.push(['Levy', r.tax
          ? `${r.tax}% on your deliveries in, half that on pickups · ${money(r.earned)} earned here lately`
          : `none yet · the mayor asks once you’ve earned ${money(next)} here (${money(r.earned)} so far)`]);
      } else if (r.tax) top.push(['Levy', `${r.tax}% on your deliveries`]);
    }
    if (!c.w || !c.t) return farNote() + (top.length ? dl(top) : '<p class="note">Nothing is on its books yet.</p>');
    const w = c.w, t = c.t;
    const kinds = new Set<string>(t.buildings.filter((b) => !b.gone).map((b) => b.kind));
    for (const p of w.ports) if (p.town === t.id) kinds.add(p.major ? 'majorPort' : 'minorPort');
    for (const g of airportsOf(w, t)) kinds.add(g.major ? 'intl' : 'airport');
    const makes = CARGO.filter((c) => c.from.some((k) => kinds.has(k)));
    // what pays best here first: a typical trip of twenty tiles
    const wants = CARGO.filter((c) => c.to.some((k) => kinds.has(k))).sort((a, b) => (b.base + b.perTile * 20) - (a.base + a.perTile * 20));
    const rows: [string, string][] = [];
    rows.push(['Makes', makes.length ? cargoList(makes) : 'Nothing that goes on a truck']);
    rows.push(['Wants', wants.length ? cargoList(wants) : 'Nothing brought in']);
    let out = dl([...top, ...rows]);

    const waiting = this.waiting().sort((a, b) => b.value - a.value);
    const idle = this.idleUnits().map((u) => defOf(u.model));
    out += `<h4>Waiting now <span>${waiting.length} load${waiting.length === 1 ? '' : 's'}</span></h4>`;
    if (!waiting.length) out += '<p class="note">Nothing waiting to be collected.</p>';
    else {
      out += '<ul class="loads">' + waiting.slice(0, 6).map((it) => {
        const fits = idle.some((d) => canHaul(d, it));
        // the town it is bound for, or the place's own name out in the country
        const to = economy.townFor(it.to)?.t.name ?? it.to.name.split(' · ')[0];
        return `<li><span class="c">${it.type.icon} ${esc(it.type.name)}</span><span class="to">→ ${esc(to)}</span><span class="v">${money(it.value)}</span>`
          + `<span class="u">${esc(it.urgency)}${fits ? ' · <em class="fits">fits</em>' : ''}</span></li>`;
      }).join('') + '</ul>';
      if (waiting.length > 6) out += `<p class="note">and ${waiting.length - 6} more</p>`;
    }

    const lots = t.buildings.map((b) => ({ b, l: economy.lots.get(`${w.cx},${w.cz}#b${b.uid}`) }))
      .filter((q) => q.l && (q.l.ins || q.l.outs)).sort((a, b) => b.l!.rate - a.l!.rate).slice(0, 5);
    out += `<h4>Busiest lots</h4>`;
    if (!lots.length) out += '<p class="note">No building here has sent or taken goods yet.</p>';
    else {
      out += '<ul class="lots">' + lots.map(({ b, l }) => {
        const q = this.host.estate.quote(w, b);
        const deal = q.owned ? '<em class="own">yours</em>' : `${money(q.price)} · <em class="word">${q.word.toLowerCase()}</em>`;
        return `<li><button type="button" data-lot="${b.uid}"><span>${esc(buildingLabel(b))}</span>`
          + `<small>${perHour(l!.rate)} · ${l!.ins} in · ${l!.outs} out${l!.mine ? ` · ${l!.mine} yours` : ''} · ${deal}</small></button></li>`;
      }).join('') + '</ul>';
    }
    return out;
  }

  // ---- tab 8: standing ----

  /** Your rung of its ladder, your say in its limits, its territory, its holders over time and who carries its trade. */
  private standingTab(): string {
    const say = this.sayHtml();
    return (this.w ? '' : farNote()) + this.standingHtml()
      + (say ? `<h5>Your say</h5>${say}` : '') + this.townHoldHtml() + this.holdersHtml();
  }

  // ---- tab 9: your fleet ----

  private fleetTab(): string {
    const { economy, fleet } = this.host;
    const b = economy.book(this.key);
    const [cx, cz, id] = this.keyParts();
    const rows: [string, string][] = [];

    const n = b ? b.ins + b.outs : 0;
    let out = (this.w ? '' : farNote()) + '<h4>Your history here</h4>';

    if (b && n) {
      const week = b.days.slice(0, 7).reduce((s, v) => s + v, 0);
      rows.push(['Deliveries', `${b.ins} dropped here · ${b.outs} picked up here`]);
      rows.push(['Earned here', `<b>${money(b.mine + b.fleet)}</b>${b.fleet ? ` · ${money(b.mine)} by you, ${money(b.fleet)} by the fleet` : ''}`]);
      rows.push(['Last 7 days', `${money(week)} ${sparkline(b)}`]);
      if (b.tax) rows.push(['Levy paid', money(b.tax)]);
      const top = Object.entries(b.by).sort((p, q) => q[1] - p[1])[0];
      if (top) rows.push(['Most here', `${top[0] ? esc(top[0]) : 'You'} · ${top[1]} deliver${top[1] === 1 ? 'y' : 'ies'}`]);
      if (b.first) rows.push(['First', `Day ${b.first[0] + 1} · ${b.first[1] ? esc(b.first[1]) : 'you'} · ${esc(b.first[2])}`]);
      if (b.best) rows.push(['Best load', money(b.best)]);
    } else {
      rows.push(['Deliveries', 'None yet: nothing of yours has been dropped or picked up here since the books were kept']);
    }
    const held = this.host.estate.heldIn(this.key);
    if (held.length) {
      const took = held.reduce((t, d) => t + d.took, 0);
      rows.push(['Estate', `${held.length} lot${held.length === 1 ? '' : 's'} · ${money(took)} taken here`]);
    }
    out += dl(rows);

    // the live rows
    const live: [string, string][] = [];
    const based = fleet.units.filter((u) => {
      const base = u.order.base;
      if (!base || base.cx !== cx || base.cz !== cz) return false;
      if (base.kind === 'town') return base.id === id;
      return !!this.w && this.w.ports.find((p) => p.id === base.id)?.town === id;
    });
    live.push(['Based here', based.length ? based.map((u) => unitLine(fleet, u)).join('') : '<span class="none">none</span>']);

    const coming: string[] = [];
    for (const u of fleet.units) {
      const a = u.agent, run = a?.run;
      if (!a || !run) continue;
      const rest = run.stops.slice(run.k);
      let calls = 0, firstAt = -1;
      rest.forEach((st, k) => {
        const site = st.kind === 'pickup' ? st.item.from : st.item.to;
        if (this.siteKey(site) === this.key) { calls++; if (firstAt < 0) firstAt = k; }
      });
      if (!calls) continue;
      // straight lines from where it is through its calls up to the first here, at its pace
      let d = 0, px = a.w.ox + a.state.x, pz = a.w.oz + a.state.z;
      for (let k = 0; k <= firstAt; k++) {
        const q = stopAt(rest[k]);
        d += Math.hypot(q.x - px, q.z - pz);
        px = q.x; pz = q.z;
      }
      const secs = d / (u.traffic ? u.traffic.paceOf(a) : 1);
      coming.push(`<div class="u"><b>${esc(u.name)}</b> <span>${calls} call${calls === 1 ? '' : 's'} here · ${firstAt === 0 ? 'next' : `after ${firstAt} more`} · ~${clock(secs)}</span></div>`);
    }
    live.push(['On the way', coming.length ? coming.join('') : '<span class="none">none</span>']);

    if (this.w && this.t) {
      const w = this.w, t = this.t;
      const here: string[] = [];
      const p = this.host.player();
      if (p && p.cx === cx && p.cz === cz && inTown(w, t, p.x, p.z)) here.push('<div class="u"><b>You</b></div>');
      for (const u of fleet.units) {
        if (u.cx !== cx || u.cz !== cz || u.where === 'ridden') continue;
        const x = u.agent ? u.agent.state.x : u.x, z = u.agent ? u.agent.state.z : u.z;
        if ((u.where === 'working' || u.where === 'parked') && inTown(w, t, x, z)) here.push(`<div class="u"><b>${esc(u.name)}</b> <span>${esc(u.where)}</span></div>`);
      }
      live.push(['In town now', here.length ? here.join('') : '<span class="none">nobody</span>']);
    }

    out += `<h4>Now</h4>${dl(live)}`;

    // what you can do about it
    const idle = this.idleUnits().length;
    out += `<div class="acts">`
      + `<button type="button" data-act="pick" class="${this.picking ? 'on' : ''}">Base a unit here</button>`
      + `<button type="button" data-act="send" ${idle ? '' : 'disabled'} title="${idle ? 'Send your best-placed idle vehicle on this island for the loads waiting here' : 'None of your vehicles on this island is idle'}">Send idle unit</button></div>`;
    if (this.picking) out += this.pickerHtml();
    return out;
  }

  /** A carrier's name on the card: you, a firm with its chip, or the other haulers. */
  private carrierHtml(who: string): string {
    if (who === YOU) return youHtml();
    const f = this.host.firms?.firm(who);
    return f ? `${chip(f.livery, f.logo)}${esc(f.name)}` : who ? esc(this.host.firms?.carrierName(who) ?? 'a firm long gone') : 'others';
  }

  /**
   * Standing (docs/standing.html): the player's rung of the town's carriage ladder — the one thing measured —
   * what it gives them now, what the next rung adds and how to reach it, and what they stand to lose.
   */
  private standingHtml(): string {
    const { economy } = this.host;
    const c = economy.carriage, terr = this.host.territory, key = this.key;
    const share = c.shareOf(key, YOU);
    const rung = c.rungOf(key, YOU);
    const st = terr?.status(key) ?? { who: c.preferred(key), strong: false, contested: '' };
    const held = rung === RUNG.territory;
    const strong = held && st.strong, contested = held ? st.contested : '';
    const kind = this.t?.kind ?? terr?.towns.get(key)?.kind ?? 'rural';
    const title = held ? (contested ? 'Your territory · contested' : strong ? 'Your strong territory' : 'Your territory') : RUNGS[rung].name;

    // the ladder: a column a rung, the bar in the same columns, filled through the rung you're on and on
    // toward the next by how far your share has come from this rung's bar to the next one's
    const cols = RUNGS.length;
    const from = RUNGS[rung].at, to = rung + 1 < cols ? RUNGS[rung + 1].at : 1;
    const toward = held || rung === RUNG.stranger ? 0 : Math.max(0, Math.min(1, (share - from) / Math.max(1e-6, to - from)));
    const fill = held ? 100 : ((rung + 1 + toward) / cols) * 100;
    const ticks = RUNGS.slice(1).map((_, k) => `<s style="left:${((k + 1) / cols) * 100}%"></s>`).join('');
    const steps = RUNGS.map((r, k) => `<span class="${k === rung ? 'on' : k < rung ? 'past' : ''}">${r.name}${k >= RUNG.regular ? `<em>${pct(r.at)}</em>` : ''}</span>`).join('');
    let out = `<div class="perf standing"><div class="row"><b>${title}</b><span>${pct(share)} of its trade</span></div>`
      + `<div class="bar"><i style="width:${Math.min(100, fill).toFixed(1)}%"></i>${ticks}</div><div class="ladder">${steps}</div></div>`;
    out += `<p class="note">What’s measured: your share of the goods carried for this town lately, against every other carrier. A delivery here counts its full value and a pickup here half; you and your whole fleet count together, and so does the rent your buildings here take from anyone’s deliveries. It all fades by half every ${Math.round(CARRIAGE.halfLife / 24)} game days.</p>`;

    // what you have
    const have = perksAt(rung, strong, !!contested);
    out += `<h5>You have here</h5>` + (have.length
      ? `<ul class="perks">${have.map((p) => `<li>${esc(p)}</li>`).join('')}</ul>`
      : '<p class="how none">Nothing yet: the town doesn’t know you.</p>');

    // the next step and how to take it
    const b = economy.book(key);
    const n = b ? b.ins + b.outs : 0;
    const avg = n >= 2 ? (b!.mine + b!.fleet) / n : 0;
    const loads = (d: number) => (avg > 0 ? ` (about ${Math.max(1, Math.ceil(d / avg))} load${Math.ceil(d / avg) === 1 ? '' : 's'} like your usual here)` : '');
    const missions = ' Town missions here help too: finishing one makes the town talk you up.';
    if (!held) {
      const next = rung + 1;
      const need = next === RUNG.territory ? c.gap(key, YOU) : c.need(key, YOU, RUNGS[next].at);
      const rival = c.nextFleet(key, YOU);
      out += `<h5>Next: ${RUNGS[next].name}${next >= RUNG.regular ? ` at ${pct(RUNGS[next].at)}` : ''}</h5><ul class="perks gain"><li>${esc(gainsAt(next))}</li></ul>`;
      if (next === RUNG.known) out += `<p class="how">Deliver anything here, or pick anything up here.</p>`;
      else {
        let how = need > 0 ? `Carry about <b>${money(need)}</b> more of its trade${loads(need)}` : 'You’re there: it counts at the next delivery';
        if (next === RUNG.territory) {
          how += rival ? `, to hold ${pct(CARRIAGE.prefer)} of it and ${CARRIAGE.lead}× the figure of ${this.carrierHtml(rival.who)} (they carry ${pct(rival.share)})` : `, to hold ${pct(CARRIAGE.prefer)} of it and ${CARRIAGE.lead}× any other fleet’s`;
          if (c.preferred(key) && c.preferred(key) !== YOU) how += `. It is ${this.carrierHtml(c.preferred(key))}’s now: they keep it until they’re under ${pct(CARRIAGE.keep)}, or you pass both bars`;
        }
        out += `<p class="how">${how}.${missions}</p>`;
      }
    } else if (contested) {
      const top = terr?.topOwner(key);
      const gap = top ? Math.max(0, Math.ceil(top.value - (terr!.propertyOf(key).own[YOU] ?? 0)) + 1) : 0;
      out += `<h5>Settle the contest</h5><ul class="perks gain"><li>◆ ${terr!.yieldOf(kind, false)} a day again</li></ul>`
        + `<p class="how">${this.carrierHtml(contested)} owns ${pct1(top?.share ?? 0)} of its property, more than your ${pct1(terr!.propertyShare(key))}. Own more of it than they do: about <b>${money(gap)}</b> more of its buildings. It also settles if they sell down under ${pct(TERRITORY.strongKeep)}.</p>`;
    } else if (!strong && terr) {
      const gap = terr.propertyGap(key);
      out += `<h5>Next: strong territory</h5><ul class="perks gain"><li>no levy here · ◆ ${terr.yieldOf(kind, true)} a day instead of ${terr.yieldOf(kind, false)}</li></ul>`
        + `<p class="how">Own over ${pct(TERRITORY.strong)} of its property and ${TERRITORY.strongLead}× any other fleet’s: buy about <b>${money(gap)}</b> more of its buildings (you own ${pct1(terr.propertyShare(key))}).</p>`;
    } else out += `<h5>Next</h5><p class="how">Nothing: this is the top of the ladder.</p>`;

    return out;
  }

  /** Online, the town's holders as territory over time: who, from what day (docs/marks.html). */
  private holdersHtml(): string {
    const list = this.holders?.(this.key) ?? [];
    if (!list.length) return '';
    const rows = list.slice(0, 6).map((h, k) => `<span class="${k ? '' : 'now'}">${h.who ? this.carrierHtml(h.who) : 'Nobody'} <small>from day ${h.day}</small></span>`).join('');
    return `<h5>Held by</h5><div class="tc-holders">${rows}</div>`;
  }

  /** The town's territory, whoever holds it, its property and who carries its trade (docs/territory.html, docs/standing.html). */
  private townHoldHtml(): string {
    const terr = this.host.territory, c = this.host.economy.carriage, key = this.key;
    const kind = this.t?.kind ?? terr?.towns.get(key)?.kind ?? 'rural';
    let out = '<h4>Territory</h4>';
    if (terr) {
      const st = terr.status(key);
      let line: string;
      if (st.who === YOU) {
        line = `<b>${st.contested ? 'Yours, contested' : st.strong ? 'Yours, strong' : 'Yours'}</b> since day ${c.since(key) + 1} · <b class="dia">◆ ${st.contested ? 0 : terr.yieldOf(kind, st.strong)} a day</b>`;
      } else if (st.who) {
        line = `<b>${this.carrierHtml(st.who)}’s${st.strong ? ' strong' : ''} territory</b>${st.contested ? `, contested by ${this.carrierHtml(st.contested)}` : ''} · they carry ${pct(c.shareOf(key, st.who))} of its trade`;
        if (st.contested === YOU) line += ' · <b>you out-own them here, so they earn no ◆ from it</b>';
        line += ` · yours would pay <b class="dia">◆ ${terr.yieldOf(kind, false)} a day</b>, ◆ ${terr.yieldOf(kind, true)} strong`;
      } else line = `<b>Nobody’s territory</b> · it would pay <b class="dia">◆ ${terr.yieldOf(kind, false)} a day</b>, ◆ ${terr.yieldOf(kind, true)} strong`;
      out += `<p class="note tc-terr">${line}${this.host.showTerritory ? ' · <button type="button" class="link" data-act="terr-map">show on map</button>' : ''}</p>`;
      // who owns it
      const p = terr.propertyOf(key);
      if (p.total > 0) {
        const owners = Object.entries(p.own).sort((a, z) => z[1] - a[1]).slice(0, 3)
          .map(([o, v]) => `${this.carrierHtml(o)} ${pct1(v / p.total)}`);
        if (!(YOU in p.own)) owners.push(`${youHtml()} 0%`);
        out += `<p class="note">Its property is worth ${money(Math.round(p.total))} · ${owners.join(' · ')}</p>`;
      }
    }
    // who carries it
    const shares = c.shares(key);
    out += '<div class="tc-carry">';
    if (!shares.length) out += '<p class="note">Nobody has carried anything here lately.</p>';
    else {
      const firms = this.host.firms;
      out += `<div class="bar">${shares.map((s) => `<i style="width:${(s.share * 100).toFixed(1)}%;background:${s.who ? css(firms ? firms.carrierColour(s.who) : 0x2f7fb5) : '#c9ced4'}"></i>`).join('')}</div>`;
      out += `<p class="note">Its trade lately: ${shares.filter((s) => s.share >= 0.03 || s.who === YOU).map((s) => `${this.carrierHtml(s.who)} ${pct(s.share)}`).join(' · ')}</p>`;
    }
    return out + '</div>';
  }

  private pickerHtml(): string {
    const { fleet } = this.host;
    const list = fleet.units.filter((u) => u.where !== 'ridden' && u.where !== 'garaged');
    if (!list.length) return '<p class="note">You have no other vehicles to base anywhere.</p>';
    return '<ul class="pick">' + list.map((u) => {
      const ok = this.basesHere(u).length > 0;
      const already = this.basesHere(u).some((b) => u.order.base && b.id === u.order.base.id && b.kind === u.order.base.kind && b.cx === u.order.base.cx && b.cz === u.order.base.cz);
      const why = already ? 'based here' : ok ? '' : u.cx !== this.keyParts()[0] || u.cz !== this.keyParts()[1] ? 'on another island' : 'can’t be based here';
      return `<li><span><b>${esc(u.name)}</b> <small>${esc(defOf(u.model).name)} · ${esc(u.order.base?.name ?? 'no base')}</small></span>`
        + (ok && !already ? `<button type="button" data-base="${u.uid}">Base here</button>` : `<small>${why}</small>`) + '</li>';
    }).join('') + '</ul>';
  }
}

