function gradSteps(t: Town, g: NonNullable<(typeof GRADUATION)[TownKind]>): { done: number; all: number } {
  const done = (builtCount(t) >= g.built ? 1 : 0) + (t.size >= g.size ? 1 : 0) + (t.buildings.some((b) => !b.gone && g.needs.includes(b.kind)) ? 1 : 0);
  return { done, all: 3 };
}

function cargoList(list: { icon: string; name: string }[]): string {
  const shown = list.slice(0, 8).map((c) => `<span class="cg">${c.icon} ${esc(c.name)}</span>`).join('');
  return shown + (list.length > 8 ? ` <span class="more">+${list.length - 8} more</span>` : '');
}

function unitLine(fleet: Fleet, u: Unit): string {
  const d = fleet.driverOf(u);
  return `<div class="u"><b>${esc(u.name)}</b> <span>${esc(defOf(u.model).name)}${d ? ` · ${esc(d.name)}` : ''} · ${esc(fleet.stateLine(u))}</span></div>`;
}

/** The last 14 days' earnings as little bars, oldest on the left. */
function sparkline(b: TownBook): string {
  const days = [...b.days].reverse();
  while (days.length < 14) days.unshift(0);
  const max = Math.max(1, ...days);
  const bars = days.map((v, k) => {
    const h = Math.max(v > 0 ? 1.5 : 0.5, (v / max) * 14);
    return `<rect x="${k * 5}" y="${16 - h}" width="4" height="${h}" rx="1"/>`;
  }).join('');
  return `<svg class="spark" viewBox="0 0 70 16" width="70" height="16" aria-label="earnings over the last 14 days">${bars}</svg>`;
}

function inTown(w: World, t: Town, x: number, z: number): boolean {
  const tx = Math.floor(x), tz = Math.floor(z);
  return tx >= 0 && tz >= 0 && tx < N && tz < N && w.townId[idx(tx, tz)] === t.id;
}




/** A kind's own label where it has one, else its name spelled out. */
function labelOf(kind: string): string { return buildingLabel({ kind } as Building); }
