/**
 * Bookmarks (docs/passport.html): any building, wonder, town or landform the player has seen, starred from its
 * card or from its stamp in the Passport, kept in a list they can come back to and light up on the map. They
 * belong to the player and stay on this machine: nothing here is sent anywhere.
 */

export type MarkKind = 'building' | 'town' | 'wonder' | 'landform' | 'biome' | 'place';
export const MARK_ICON: Record<MarkKind, string> = { building: '🏠', town: '🏘️', wonder: '🗿', landform: '🗻', biome: '🧭', place: '📍' };

export interface Bookmark {
  /** What it is a bookmark of: "b:3,-1#412" a building, "t:3,-1#2" a town, "s:arch:tokyo" a stamp's first sighting. */
  id: string;
  kind: MarkKind;
  label: string;
  /** The town or county it is in, for the list. */
  sub: string;
  cx: number; cz: number;
  /** Its place in the cell, in tiles. */
  x: number; z: number;
  /** Drawn on the maps and pointed at from the edge of the screen. */
  lit: boolean;
  note?: string;
  /** When it was starred. */
  t: number;
}

export const MAX_BOOKMARKS = 200;
const KEY = 'tinyfleet-bookmarks';
const keyOf = (player: string): string => `${KEY}:${player}`;

export class Bookmarks {
  private player = '';
  private list: Bookmark[] = [];
  /** Bumped at every change, for the book, the cards and the maps. */
  revision = 0;

  load(player: string): void {
    if (player === this.player) return;
    this.player = player;
    this.list = [];
    try {
      const r = JSON.parse(localStorage.getItem(keyOf(player)) ?? '[]') as Bookmark[];
      if (Array.isArray(r)) this.list = r.filter((b) => b && typeof b.id === 'string' && Number.isFinite(b.cx) && Number.isFinite(b.x));
    } catch { /* an unreadable list is an empty one */ }
    this.revision++;
  }

  private save(): void {
    this.revision++;
    if (!this.player) return;
    try { localStorage.setItem(keyOf(this.player), JSON.stringify(this.list)); } catch { /* kept in memory only */ }
  }

  all(): Bookmark[] { return this.list; }
  lit(): Bookmark[] { return this.list.filter((b) => b.lit); }
  has(id: string): boolean { return this.list.some((b) => b.id === id); }
  get(id: string): Bookmark | null { return this.list.find((b) => b.id === id) ?? null; }

  /** Star a place, lit from the start. False when the list is full. */
  add(b: Omit<Bookmark, 'lit' | 't'>): boolean {
    if (this.has(b.id)) return true;
    if (this.list.length >= MAX_BOOKMARKS) return false;
    this.list.unshift({ ...b, x: Math.round(b.x * 10) / 10, z: Math.round(b.z * 10) / 10, lit: true, t: Date.now() });
    this.save();
    return true;
  }

  remove(id: string): void {
    const k = this.list.findIndex((b) => b.id === id);
    if (k < 0) return;
    this.list.splice(k, 1);
    this.save();
  }

  /** Star it if it isn't, unstar it if it is. Returns whether it is now starred. */
  toggle(b: Omit<Bookmark, 'lit' | 't'>): boolean {
    if (this.has(b.id)) { this.remove(b.id); return false; }
    return this.add(b);
  }

  setLit(id: string, on: boolean): void {
    const b = this.get(id);
    if (!b || b.lit === on) return;
    b.lit = on;
    this.save();
  }

  /** Light every bookmark, or none. */
  lightAll(on: boolean): void {
    if (this.list.every((b) => b.lit === on)) return;
    for (const b of this.list) b.lit = on;
    this.save();
  }

  rename(id: string, label: string): void {
    const b = this.get(id);
    const text = label.trim().slice(0, 60);
    if (!b || !text || b.label === text) return;
    b.label = text;
    this.save();
  }
}

/** The one list: the current player's. */
export const bookmarks = new Bookmarks();

function forgetBookmarks(player: string): void {
  try { localStorage.removeItem(keyOf(player)); } catch { /* nothing to remove */ }
}
