import * as THREE from 'three';
import { type VehicleDef, type MenuGroup } from './vehicles';
import { buildVehicleMesh, disposeVehicleMesh, type VehicleMesh } from '../render/vehicleMeshes';
import { buildCar } from '../render/trainMeshes';
import { dressTrainTreats } from '../render/treats';
import { COUPLING_GAP, SETS, fillSet } from './rollingStock';
import { mulberry32 } from '../world/rng';
import { priceOf } from './economy';
import { esc, money } from './cargoHud';
import type { Wallet } from './economy';
import { defOf, type Fleet, type Unit, type Where } from './fleet';
import type { Address } from './hq';
import { WorkshopView } from './workshopView';
import { slotOf, type SlotId } from './parts';
import { DEAL_LABEL, KIND_LABEL, TRADE_GROUP, TRADE_LABEL, wayTo, type Outlet, type Outlets, type Trade } from './outlets';

const GROUPS: { id: MenuGroup; title: string }[] = [
  { id: 'road', title: 'On the road' },
  { id: 'water', title: 'On the water' },
  { id: 'sky', title: 'In the sky' },
  { id: 'rail', title: 'On the rails' },
];

type Tab = 'dealer' | 'workshop';
const TABS: Tab[] = ['dealer', 'workshop'];

/** What the panel asks of the game. */
interface GarageHost {
  /** Buy one of these at this price and ride it from here; a message when it can't be done. */
  buy(d: VehicleDef, price: number): string | null;
  /** Where the player is, in world tiles, for pointing the way to a shop or a dealer. */
  where(): { x: number; z: number };
  /** Go to a unit and take its wheel (the one fast travel); a message when it can't be done. */
  ride(u: Unit): string | null;
  /** Why a model can't be ridden from here (a train needs track nearby), or null. */
  rideCheck(d: VehicleDef): string | null;
  /** The game day, for today's candidates. */
  day(): number;
  /** Why the camera can't follow this unit (it's under you, out of range, on a tow), or null when it can. */
  watchable(u: Unit): string | null;
  /** Point the camera at the unit and keep it there until Esc. */
  watch(u: Unit): void;
  /** What a delivery driver would charge to bring this one over to the muster, or null when it cannot. */
  towOver(u: Unit): number | null;
  /** Have a delivery driver bring it over; a message when it can't be done. */
  bringOver(u: Unit): string | null;
  /** Bring a unit out of the garage into a free slot, parked beside the player; a message when it can't be done. */
  deploy(u: Unit): string | null;
  /** Take a unit out of the garage and drive it from here, the one ridden going into the garage; a message when it can't be done. */
  swapIn(u: Unit): string | null;
  /** Diamonds in the purse, for the charter credit line. */
  diamonds?(): number;
  /** The nearest building of each HQ grade above the one you have, in the islands in memory (docs/hq.html, Addresses). */
  addresses?(): Address[];
  /** Show one of those: its inspector card. */
  showAddress?(a: Address): void;
  /** A vehicle was bought and the counter has closed: show it (the HQ window's garage). */
  bought?(d: VehicleDef): void;
  /** The Dealer or Vehicle Shop whose ring the player stands in, for G; null anywhere else. */
  ringHere?(): Outlet | null;
  /** G away from a ring: say where the nearest is. */
  away?(): void;
  /** Open the tech trees (docs/territory.html), at a model's node if one is given. */
  openTech?(id?: string): void;
  /** May this model be sold yet (the tech trees)? Absent: everything may. */
  unlocked?(id: string): boolean;
  /** Diamonds a locked model costs to unlock. */
  techCost?(id: string): number;
}



/** A part's short name for the shop's banner. */
const PART_WORD: Partial<Record<SlotId, string>> = { bullbar: 'bull bar', rack: 'racks', tyres: 'tyres', horn: 'horns', paint: 'paint' };

/** A second Tomato is not free: the first one is the gift. */
export const priceFor = (fleet: Fleet, id: string): number => (priceOf(id) === 0 && fleet.owns(id) ? 300 : priceOf(id));

/**
 * The counter at a Vehicle Dealer or a Vehicle Shop (docs/hqwindow.html, "Keys, G and the rings"): the
 * dealer's stock this year at its prices, or the shop's parts fitted to your vehicles. It opens only at a
 * ring (Space at its door, or G standing in one); away from one, G says where the nearest is. Everything
 * the player owns, the drivers and the garage live in the HQ window (H) now. Plain elements, one class
 * each; arrow keys and Enter; 1, 2 or Tab for the tabs.
 */
export class GarageMenu {
  isOpen = false;
  private el = document.getElementById('vehicles')!;
  private tab: Tab = 'dealer';
  private tabs = new Map<Tab, HTMLButtonElement>();
  private pages = new Map<Tab, HTMLElement>();
  private note = document.createElement('div');
  // the dealer
  private cards: HTMLButtonElement[] = [];
  private imgs: HTMLImageElement[] = [];
  private tags: HTMLElement[] = [];
  private order: VehicleDef[] = [];
  private focusIdx = 0;
  private thumbs = new Map<string, string>();
  private thumbsDone = false;
  /** The unit the workshop is working on. */
  private selected = 0;
  // the workshop
  private shop: WorkshopView;
  private liveT = 0;
  private message = '';
  /** The Vehicle Shop or Dealer the menu was opened at (Space at its door), or null anywhere else. */
  private here: Outlet | null = null;
  /** Opened from the cheats menu: the whole catalogue on sale at list price, wherever the player is. */
  private anywhere = false;
  private banner = document.createElement('div');
  /** Each dealer group's heading and grid, hidden when a dealer has nothing of that group. */
  private groupEls = new Map<MenuGroup, HTMLElement[]>();

  constructor(defs: VehicleDef[], private wallet: Wallet, private fleet: Fleet, private host: GarageHost, private outlets: Outlets) {
    const panel = document.createElement('div');
    panel.className = 'panel';
    const head = document.createElement('header');
    head.innerHTML = `<h2>At the counter<span>.</span></h2>
      <div class="keys"><kbd>↑</kbd><kbd>↓</kbd><kbd>←</kbd><kbd>→</kbd> choose · <kbd>Enter</kbd> buy / fit · <kbd>Esc</kbd> leave · your fleet, garage and drivers: <kbd>H</kbd></div>`;
    const bar = document.createElement('nav');
    bar.className = 'gtabs';
    for (const [id, label] of [['dealer', 'Dealer'], ['workshop', 'Workshop']] as [Tab, string][]) {
      const b = document.createElement('button');
      b.type = 'button';
      b.textContent = label;
      b.addEventListener('click', () => this.show(id));
      bar.append(b);
      this.tabs.set(id, b);
    }
    this.note.className = 'note';
    this.banner.className = 'gstore';
    this.banner.hidden = true;
    panel.append(head, bar, this.note, this.banner);

    // dealer
    const dealer = document.createElement('section');
    dealer.className = 'dealer';
    for (const g of GROUPS) {
      const list = defs.filter((d) => d.group === g.id);
      if (!list.length) continue;
      const h3 = document.createElement('h3');
      h3.textContent = g.title;
      const grid = document.createElement('div');
      grid.className = 'grid';
      dealer.append(h3, grid);
      this.groupEls.set(g.id, [h3, grid]);
      for (const d of list) {
        const n = this.order.length;
        const card = document.createElement('button');
        card.type = 'button';
        card.className = 'vcard';
        card.tabIndex = -1;
        card.dataset.group = g.id;
        const thumb = document.createElement('div');
        thumb.className = 'thumb';
        const img = document.createElement('img');
        img.alt = d.name;
        thumb.append(img);
        const price = document.createElement('span');
        price.className = 'price';
        const name = document.createElement('div');
        name.className = 'name';
        name.textContent = d.name;
        const blurb = document.createElement('div');
        blurb.className = 'blurb';
        blurb.textContent = d.blurb;
        const tags = document.createElement('div');
        tags.className = 'tags';
        for (const t of d.tags) {
          const s = document.createElement('span');
          s.textContent = t;
          tags.append(s);
        }
        const cap = document.createElement('span');
        cap.className = 'cap';
        cap.textContent = `holds ${d.capacity}`;
        tags.append(cap);
        card.append(thumb, price, name, blurb, tags);
        card.addEventListener('click', () => this.buy(n));
        card.addEventListener('mousemove', () => { if (this.focusIdx !== n) this.setFocus(n, false); });
        grid.append(card);
        this.cards.push(card);
        this.imgs.push(img);
        this.tags.push(price);
        this.order.push(d);
      }
    }
    panel.append(dealer);
    this.pages.set('dealer', dealer);

    // workshop
    this.shop = new WorkshopView(fleet, wallet, defs, {
      units: () => this.sorted(),
      selected: () => this.selected,
      select: (uid) => this.select(uid),
      say: (text) => this.say(text),
      sync: () => this.sync(),
      model: (def) => {
        if (def.kind === 'rail') return { ...railThumb(def.id, def), lift: 0, dispose: () => {} };
        const m = buildVehicleMesh(def);
        return { holder: m.holder, body: m.body, wheels: m.wheels, lift: m.lift ?? 0, dispose: () => disposeVehicleMesh(m) };
      },
      partMul: (slot) => (this.anywhere ? 1 : this.here?.kind === 'shop' && this.outlets.slots(this.here).includes(slot) ? this.outlets.terms(this.here).mul : null),
      whereToBuy: (slot) => this.whereToBuyPart(slot),
      paid: (n) => { if (this.here) this.outlets.record(this.here, n); },
    });
    panel.append(this.shop.el);
    this.pages.set('workshop', this.shop.el);

    this.el.append(panel);
    this.el.addEventListener('mousedown', (e) => { if (e.target === this.el) this.close(); });
    window.addEventListener('keydown', (e) => this.onKey(e));
  }

  /**
   * G: the counter of the ring you are standing in, if any; anywhere else a line on where the nearest
   * one is (a dealer or a shop is drive-to only, docs/hqwindow.html).
   */
  /** Is the player stopped in a Vehicle Shop's or Dealer's ring, where G opens its counter? */
  ringHere(): boolean { return !!this.host.ringHere?.(); }

  toggle(): void {
    if (this.isOpen) { this.close(); return; }
    const o = this.host.ringHere?.() ?? null;
    if (o) this.openAt(o);
    else this.host.away?.();
  }

  /** Go in at a Vehicle Shop's or Dealer's door: the workshop or the dealer, at its stock and its prices. */
  openAt(o: Outlet): void {
    this.here = o;
    this.open(o.kind === 'shop' ? 'workshop' : 'dealer', true);
  }

  /** The cheats menu's full dealer, full shop or full roster: everything, at list, from anywhere. */
  openCatalogue(tab: Tab = 'dealer'): void {
    this.here = null;
    this.anywhere = true;
    this.open(tab, true);
  }

  /** The workshop's stage made ready before it is first opened (WorkshopView.warm). */
  warmWorkshop(): void { void this.shop.warm(); }

  open(tab?: Tab, keepHere = false): void {
    if (!keepHere) { this.here = null; this.anywhere = false; }
    this.isOpen = true;
    this.el.hidden = false;
    this.message = '';
    // the menu opens on the vehicle under you: the garage lines and the workshop's stage both start
    // with the car you are driving, whatever was last picked in an earlier visit
    const was = this.selected;
    this.selected = this.fleet.ridden?.uid ?? (this.fleet.unit(this.selected) ? this.selected : this.fleet.units[0]?.uid ?? 0);
    if (this.selected !== was) this.shop.unitChanged();
    this.show(tab ?? this.tab);
    if (!this.thumbsDone) {
      this.thumbsDone = true;
      setTimeout(() => {
        const cat = vehicleThumbs(this.order);
        this.imgs.forEach((img, i) => { img.src = cat.get(this.order[i].id) ?? ''; this.thumbs.set(this.order[i].id, img.src); });
        if (this.tab === 'workshop') this.renderWorkshop();
      }, 20);
    }
  }

  /**
   * Open the workshop on the ridden unit with one part going on: it appears on the vehicle in a poof, then
   * its square glows and wears a badge, and the line under the menu says where it came from. The first jobs' ending.
   */
  showPart(slot: SlotId, badge: string, line: string): void {
    this.open('workshop');
    this.shop.reveal(slot, badge);
    this.renderWorkshop();
    this.say(line);
  }

  close(): void {
    const was = this.isOpen;
    this.here = null;
    this.anywhere = false;
    this.isOpen = false;
    this.el.hidden = true;
    this.shop.setVisible(false);
    // only its own focus: closed when already shut (the title's world arriving), the sign-in card keeps the caret
    if (was) (document.activeElement as HTMLElement | null)?.blur?.();
  }

  private show(tab: Tab): void {
    this.tab = tab;
    // a dealer sells vehicles and a shop fits parts: each counter shows only its own tab
    for (const [id, b] of this.tabs) { b.classList.toggle('on', id === tab); b.hidden = !this.anywhere && id !== tab; }
    for (const [id, p] of this.pages) p.hidden = id !== tab;
    this.shop.setVisible(this.isOpen && tab === 'workshop');
    this.sync();
    if (tab === 'dealer') {
      let cur = this.order.findIndex((d, i) => d.id === this.fleet.ridden?.model && !this.cards[i].hidden);
      if (cur < 0) cur = Math.max(0, this.cards.findIndex((c) => !c.hidden));
      this.setFocus(cur, true);
    }
  }

  /** The banner under the tabs at a shop or a dealer: whose it is, what it has, and how its prices run. */
  private renderBanner(): void {
    const o = this.here;
    if (this.anywhere) {
      this.banner.hidden = false;
      const [what, sub] = this.tab === 'workshop' ? ['Full shop', 'every part and paint at list price, fitted from anywhere']
        : ['Full dealer', 'every model at list price, from anywhere'];
      this.banner.innerHTML = `<div class="gs-name"><span class="ic">🃏</span><b>${what}</b><small>Cheats · ${sub}</small></div>`;
      return;
    }
    this.banner.hidden = !o;
    if (!o) return;
    const t = this.outlets.terms(o);
    const pct = (v: number) => `${v >= 0 ? '−' : '+'}${Math.abs(Math.round(v * 100))}%`;
    const left = this.outlets.restockIn();
    const bits = [
      left > 0 ? `<span class="gs-restock">${left === 1 ? 'Restocks tonight at midnight' : `${left} days until restock`}</span>` : '',
      `<span class="gs-deal ${t.deal}">${DEAL_LABEL[t.deal]} this year · ${pct(1 - t.roll)}</span>`,
      `<span>${esc(t.loyalName)}${t.loyalOff ? ` · ${pct(t.loyalOff)}` : ''}</span>`,
      t.standingOff ? `<span>${esc(o.townName)} knows you · ${pct(t.standingOff)}</span>` : '',
      t.ownedOff ? `<span class="gs-owned">Your building · ${pct(t.ownedOff)}</span>` : '',
    ].filter(Boolean).join('');
    const what = o.kind === 'shop'
      ? `Parts this year: ${this.outlets.slots(o).map((id) => `<span class="gs-part">${slotOf(id).icon} ${esc(PART_WORD[id] ?? id)}</span>`).join('')}`
      : `Sells ${TRADE_LABEL[o.trade!]} · ${this.outlets.models(o).length} this year · new stock every year`;
    this.banner.innerHTML = `<div class="gs-name"><span class="ic">${o.icon}</span><b>${esc(o.name)}</b><small>${KIND_LABEL[o.kind]} · ${esc(o.townName)}</small></div>
      <div class="gs-what">${what}</div><div class="gs-terms">${bits}<em>all prices ${pct(1 - t.mul)} on list</em></div>`;
  }

  /** Where a part can be bought: the nearest shop known to have it this year. */
  private whereToBuyPart(slot: SlotId): string {
    const me = this.host.where();
    const n = this.outlets.nearest('shop', me.x, me.z, (o) => this.outlets.slots(o).includes(slot));
    return n ? `buy it at ${n.o.name}, ${wayTo(me.x, me.z, n.o)}` : 'buy it at a Vehicle Shop that has it this year';
  }

  /** Where a model can be bought: the nearest dealer known to have it this year, else one of its trade. */
  private whereToBuyModel(d: VehicleDef): string {
    const me = this.host.where();
    const n = this.outlets.nearest('dealer', me.x, me.z, (o) => this.outlets.models(o).includes(d.id));
    if (n) return `${n.o.name} has one this year, ${wayTo(me.x, me.z, n.o)}`;
    const trade = (Object.keys(TRADE_GROUP) as Trade[]).find((k) => TRADE_GROUP[k] === d.group);
    const any = trade ? this.outlets.nearest('dealer', me.x, me.z, (o) => o.trade === trade) : null;
    return any ? `no dealer near has one this year · ${any.o.name} sells ${TRADE_LABEL[trade!]}, ${wayTo(me.x, me.z, any.o)}`
      : `buy it at a Vehicle Dealer that sells ${trade ? TRADE_LABEL[trade] : 'them'}`;
  }

  /** What a model costs from here: at a dealer that has it, its price there; rail at list anywhere; else null. */
  private priceHere(d: VehicleDef): number | null {
    if (this.host.unlocked && !this.host.unlocked(d.id)) return null;
    // trains too only at a dealer that stocks them (a train dealer, at a station); the cheats' full dealer anywhere
    if (this.anywhere) return priceFor(this.fleet, d.id);
    const o = this.here;
    // one of each on a dealer's floor a year: sold, and it's gone until the new year's stock
    if (o?.kind !== 'dealer' || !this.outlets.models(o).includes(d.id) || this.outlets.soldOut(o, d.id)) return null;
    return this.outlets.price(o, priceFor(this.fleet, d.id));
  }

  /** Called every frame while open, and whenever money or the fleet changes: keep the live lines true. */
  tick(dt: number): void {
    if (!this.isOpen) return;
    this.liveT -= dt;
  }

  /** Prices, the wallet, and whatever tab is up. */
  sync(): void {
    if (!this.isOpen) return;
    const c = this.fleet.company();
    this.note.textContent = this.message || `Wallet ${money(this.wallet.cash)} · ${c.units} unit${c.units === 1 ? '' : 's'} · ${c.drivers} driver${c.drivers === 1 ? '' : 's'}`;
    this.renderBanner();
    if (this.tab === 'dealer') {
      const atDealer = this.here?.kind === 'dealer' ? this.here : null;
      const stock = atDealer ? this.outlets.models(atDealer) : [];
      this.order.forEach((d, i) => {
        // at a dealer: only what it has this year (the cheats' full dealer: everything)
        this.cards[i].hidden = !!atDealer && !stock.includes(d.id);
        const here = this.priceHere(d);
        const list = priceFor(this.fleet, d.id), price = here ?? list, have = this.fleet.units.filter((u) => u.model === d.id).length;
        const tag = this.tags[i];
        const shut = !!this.host.unlocked && !this.host.unlocked(d.id);
        const gone = !!atDealer && this.outlets.soldOut(atDealer, d.id);
        const cost = shut ? `🔒 unlock · ◆ ${this.host.techCost?.(d.id) ?? '?'}` : gone ? 'sold · back next year' : price === 0 ? 'free' : here === null ? `list ${money(list)}` : money(price);
        const was = here !== null && d.group !== 'rail' && list > 0 && here !== list ? ` <s>${money(list)}</s>` : '';
        tag.innerHTML = `${have ? `owned${have > 1 ? ` ×${have}` : ''} · ` : ''}${cost}${was}`;
        tag.className = `price${gone ? ' list' : have ? ' owned' : shut ? ' tech' : here === null ? ' list' : this.wallet.canAfford(price) ? '' : ' dear'}`;
        this.cards[i].classList.toggle('locked', here === null || !this.wallet.canAfford(price));
      });
      for (const [g, els] of this.groupEls) {
        const any = this.order.some((d, i) => d.group === g && !this.cards[i].hidden);
        for (const el of els) el.hidden = !any;
      }
    } else this.renderWorkshop();
  }

  private say(text: string): void {
    this.message = text;
    this.note.textContent = text;
  }

  // ---- the dealer ----

  private buy(i: number): void {
    const d = this.order[i];
    const here = this.priceHere(d);
    if (this.host.unlocked && !this.host.unlocked(d.id)) {
      this.say(`${d.name} is locked · unlock it in the tech trees for ◆ ${this.host.techCost?.(d.id) ?? '?'}`);
      this.close();
      this.host.openTech?.(d.id);
      return;
    }
    if (here === null) {
      const gone = this.here?.kind === 'dealer' && this.outlets.soldOut(this.here, d.id);
      this.say(gone ? `${d.name} · sold: ${this.here!.name} had one this year, and you bought it. ${this.outlets.restockIn() <= 1 ? 'New stock comes in tonight' : `New stock in ${this.outlets.restockIn()} days`}` : `${d.name} · ${this.whereToBuyModel(d)}`);
      this.cards[i].classList.remove('shake');
      void this.cards[i].offsetWidth;
      this.cards[i].classList.add('shake');
      return;
    }
    const price = here;
    if (!this.wallet.canAfford(price)) {
      this.say(`${d.name} costs ${money(price)} — you have ${money(this.wallet.cash)}`);
      this.cards[i].classList.remove('shake');
      void this.cards[i].offsetWidth;
      this.cards[i].classList.add('shake');
      return;
    }
    const at = this.here;
    // the sale is booked before the vehicle is handed over: the HQ window opens on it (docs/hqwindow.html)
    if (at) { this.outlets.record(at, price); this.outlets.sell(at, d.id); }
    const why = this.host.buy(d, price);
    if (why) {
      // it didn't go through: back on the floor
      if (at) { this.outlets.unsell(at, d.id); this.outlets.record(at, -price); }
      this.say(why);
      return;
    }
    this.close();
    this.host.bought?.(d);
  }

  private setFocus(i: number, scroll: boolean): void {
    this.cards[this.focusIdx]?.classList.remove('focus');
    this.focusIdx = i;
    this.cards[i].classList.add('focus');
    if (scroll) this.cards[i].scrollIntoView({ block: 'nearest' });
  }

  private onKey(e: KeyboardEvent): void {
    if (!this.isOpen) return;
    if (e.code === 'Escape') { if (!(this.tab === 'workshop' && this.shop.escape())) this.close(); e.preventDefault(); return; }
    const tabs = TABS;
    // at a ring, its own counter only; the cheats' full catalogue has both
    if (this.anywhere && /^Digit[1-2]$/.test(e.code)) { this.show(tabs[Number(e.code.slice(5)) - 1]); e.preventDefault(); return; }
    if (this.anywhere && e.code === 'Tab') { this.show(tabs[(tabs.indexOf(this.tab) + 1) % tabs.length]); e.preventDefault(); return; }
    if (this.tab === 'workshop') { if (this.shop.key(e.code)) e.preventDefault(); return; }
    if (this.tab === 'dealer') {
      switch (e.code) {
        case 'ArrowLeft': this.setFocus(this.stepCard(-1), true); break;
        case 'ArrowRight': this.setFocus(this.stepCard(1), true); break;
        case 'ArrowUp': this.moveVertical(-1); break;
        case 'ArrowDown': this.moveVertical(1); break;
        case 'Enter': case 'NumpadEnter': this.buy(this.focusIdx); break;
        default: return;
      }
      e.preventDefault();
    }
  }

  /** The next card shown, one way or the other, round the end. */
  private stepCard(dir: 1 | -1): number {
    const n = this.cards.length;
    for (let k = 1; k <= n; k++) {
      const i = (this.focusIdx + dir * k + n * 2) % n;
      if (!this.cards[i].hidden) return i;
    }
    return this.focusIdx;
  }

  /** Jump to the nearest card in the next row up or down, even across section headings. */
  private moveVertical(dir: 1 | -1): void {
    const cur = this.cards[this.focusIdx].getBoundingClientRect();
    const cy = cur.top + cur.height / 2, cx = cur.left + cur.width / 2;
    let best = -1, bestScore = Infinity;
    this.cards.forEach((c, i) => {
      if (c.hidden) return;
      const r = c.getBoundingClientRect();
      const y = r.top + r.height / 2;
      if (dir > 0 ? y <= cy + 4 : y >= cy - 4) return;
      const score = Math.abs(y - cy) * 10 + Math.abs(r.left + r.width / 2 - cx);
      if (score < bestScore) { bestScore = score; best = i; }
    });
    if (best >= 0) this.setFocus(best, true);
  }

  // ---- the workshop's units ----

  /** Ridden first, then working, on the road, shadowed, waiting, towing and parked. */
  private sorted(): Unit[] {
    const rank: Record<Where, number> = { ridden: 0, working: 1, enroute: 2, shadowed: 3, waiting: 4, towing: 5, parked: 6, garaged: 7 };
    return [...this.fleet.units].sort((a, b) => rank[a.where] - rank[b.where] || a.uid - b.uid);
  }

  private select(uid: number): void {
    if (this.selected === uid) return;
    this.selected = uid;
    this.message = '';
    this.shop.unitChanged();
    this.renderWorkshop();
  }

  private renderWorkshop(): void {
    this.shop.render();
  }

}


/** Every model's card art once rendered, by id: shared by the dealer's cards and the tech trees. */
const CATALOGUE = new Map<string, string>();

/**
 * Card art for these models, rendered once each and kept (the tech trees ask for all of them): a data URL
 * by id. Renders only what isn't already in the catalogue.
 */
export function vehicleThumbs(defs: VehicleDef[]): Map<string, string> {
  const want = defs.filter((d) => !CATALOGUE.has(d.id));
  if (want.length) renderThumbs(want, want.map(() => new Image()));
  return CATALOGUE;
}

/** Render each vehicle once in a small offscreen scene and use the pixels as card art. */
function renderThumbs(defs: VehicleDef[], imgs: HTMLImageElement[]): void {
  const W = 300, H = 200;
  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, preserveDrawingBuffer: true });
  renderer.setPixelRatio(1);
  renderer.setSize(W, H, false);
  renderer.toneMapping = THREE.NeutralToneMapping;
  renderer.toneMappingExposure = 1.05;
  const scene = new THREE.Scene();
  scene.add(new THREE.HemisphereLight(0xd8ecff, 0x8fb37a, 1.15));
  const sun = new THREE.DirectionalLight(0xfff1d6, 2.4);
  sun.position.set(3, 5, 4);
  scene.add(sun);
  const fov = 26;
  const cam = new THREE.PerspectiveCamera(fov, W / H, 0.05, 100);
  const box = new THREE.Box3(), center = new THREE.Vector3(), size = new THREE.Vector3();
  const dir = new THREE.Vector3(1.1, 0.75, 1.25).normalize();
  defs.forEach((d, i) => {
    const m = d.kind === 'rail' ? railThumb(d.id) : buildVehicleMesh(d);
    scene.add(m.holder);
    m.holder.updateMatrixWorld(true);
    box.setFromObject(m.holder);
    box.getCenter(center);
    box.getSize(size);
    const dist = (size.length() * 0.5) / Math.sin(THREE.MathUtils.degToRad(fov / 2)) * 0.82;
    cam.position.copy(center).addScaledVector(dir, dist);
    cam.lookAt(center);
    renderer.render(scene, cam);
    imgs[i].src = renderer.domElement.toDataURL();
    CATALOGUE.set(d.id, imgs[i].src);
    scene.remove(m.holder);
    if (d.kind !== 'rail') disposeVehicleMesh(m as VehicleMesh);
  });
  renderer.dispose();
  renderer.forceContextLoss();
}

/** Pictures of tuned units, by model and looks: rendered once each. */
const UNIT_THUMBS = new Map<string, string>();

/**
 * A unit's picture as it is now (the HQ window's depot board): the catalogue's for a stock one, rendered
 * once per look for a tuned or painted one.
 */
export function unitThumbOf(fleet: Fleet, u: Unit): string | undefined {
  const def = fleet.defFor(u);
  const stock = vehicleThumbs([defOf(u.model)]).get(u.model);
  // (a topper, a crown or the gold is drawn too, a train's among them: the user, 6 Nov 2026)
  const treats = !!(def.topper || def.gild || def.lantern);
  if (!treats && (!def.looks || def.kind === 'rail')) return stock;
  const key = `${u.model}#${def.looks?.key ?? ''}#${def.topper ?? ''}#${def.gild ?? ''}#${def.lantern ?? ''}`;
  let src = UNIT_THUMBS.get(key);
  if (!src) { src = unitThumb(def); UNIT_THUMBS.set(key, src); }
  return src;
}

let thumbKit: { renderer: THREE.WebGLRenderer; scene: THREE.Scene; cam: THREE.PerspectiveCamera } | null = null;
/**
 * One tuned vehicle's card art, the dealer's way: an offscreen renderer kept for the workshop, since a
 * new look is rendered each time a part goes on.
 */
function unitThumb(def: VehicleDef): string {
  const W = 300, H = 200, fov = 26;
  if (!thumbKit) {
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, preserveDrawingBuffer: true });
    renderer.setPixelRatio(1);
    renderer.setSize(W, H, false);
    renderer.toneMapping = THREE.NeutralToneMapping;
    renderer.toneMappingExposure = 1.05;
    const scene = new THREE.Scene();
    scene.add(new THREE.HemisphereLight(0xd8ecff, 0x8fb37a, 1.15));
    const sun = new THREE.DirectionalLight(0xfff1d6, 2.4);
    sun.position.set(3, 5, 4);
    scene.add(sun);
    thumbKit = { renderer, scene, cam: new THREE.PerspectiveCamera(fov, W / H, 0.05, 100) };
  }
  const { renderer, scene, cam } = thumbKit;
  const v = def.kind === 'rail' ? null : buildVehicleMesh(def);
  const m = v ?? railThumb(def.id, def);
  // the body sits as it would on the road, lifted over its tyres
  if (v) v.body.position.y = v.lift ?? 0;
  scene.add(m.holder);
  m.holder.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(m.holder), center = new THREE.Vector3(), size = new THREE.Vector3();
  box.getCenter(center);
  box.getSize(size);
  const dist = (size.length() * 0.5) / Math.sin(THREE.MathUtils.degToRad(fov / 2)) * 0.82;
  cam.position.copy(center).addScaledVector(new THREE.Vector3(1.1, 0.75, 1.25).normalize(), dist);
  cam.lookAt(center);
  renderer.render(scene, cam);
  const src = renderer.domElement.toDataURL();
  scene.remove(m.holder);
  if (v) disposeVehicleMesh(v);
  return src;
}

/**
 * A train's card: its engine and the first cars behind it, coupled up on straight, level track, as the
 * trains lay them out (each car's middle one half-length plus a coupling gap behind the last). Engine
 * forward along +z and the whole consist centred on the origin, so the stage and the card both frame it.
 * With the unit's `def`, its treats too (a topper or crown on the engine, the gold), as on the line.
 */
export function railThumb(id: string, def?: VehicleDef, most = 4): { holder: THREE.Group; wheels: THREE.Object3D[] } {
  const holder = new THREE.Group();
  const wheels: THREE.Object3D[] = [];
  const set = SETS.find((s) => s.id === id);
  if (!set) return { holder, wheels };
  // `most` cars of the set: 1 is the engine alone, close enough to see its topper (game/toppersTab.ts)
  const ids = (set.freight ? fillSet(set, mulberry32(7)) : set.cars).slice(0, most);
  let z = 0;
  const cars = ids.map((cid, k) => {
    const car = buildCar(cid, k);
    if (k) z -= COUPLING_GAP;
    car.group.position.set(0, 0, z - car.length / 2);
    holder.add(car.group);
    wheels.push(...car.wheels);
    z -= car.length;
    return car;
  });
  if (def) dressTrainTreats(cars, def);
  for (const c of holder.children) c.position.z -= z / 2;
  return { holder, wheels };
}
