import type { CellDoc, LikeEntry, ServerMsg, Welcome, CommunityStats } from '../../shared/protocol';
import type { OnlineExtra } from '../net/online';
import type { GemEntry, Territory } from './territory';
import { esc } from './cargoHud';

/**
 * The HQ window's Diamonds and Hearts tabs (the user, 22 Oct 2026): where every diamond and every heart came
 * from, and when. Diamonds are the save's own (game/territory.ts keeps the account); hearts are kept on the
 * server with the player's record (server/community.ts) and asked for whenever the tab is shown.
 */

const gem = (n: number): string => `◆ ${(Math.round(n * 10) / 10).toLocaleString('en-US', { maximumFractionDigits: 1 })}`;
const signed = (n: number, f: (v: number) => string): string => `${n < 0 ? '−' : '+'}${f(Math.abs(n))}`;

/** A game hour as "Day 12 · 14:05". */
function when(h: number): string {
  const day = Math.floor(h / 24) + 1, t = ((h % 24) + 24) % 24;
  const hh = Math.floor(t), mm = Math.floor((t - hh) * 60);
  return `Day ${day} · ${String(hh).padStart(2, '0')}:${String(mm).padStart(2, '0')}`;
}

/** Real time ago, short. */
function ago(t: number): string {
  const s = (Date.now() - t) / 1000;
  if (s < 90) return 'just now';
  if (s < 5400) return `${Math.round(s / 60)} min ago`;
  if (s < 129600) return `${Math.round(s / 3600)} h ago`;
  if (s < 30 * 86400) return `${Math.round(s / 86400)} days ago`;
  return new Date(t).toLocaleDateString(undefined, { day: 'numeric', month: 'short' });
}

const card = (big: string, label: string, sub = ''): string =>
  `<div class="pt-card"><b>${big}</b><span>${esc(label)}</span>${sub ? `<small>${sub}</small>` : ''}</div>`;

interface DiamondsHost {
  hours(): number;
  /** The Tech tab, where diamonds are spent. */
  openTech(): void;
  /** PvP Challenge boards held now (docs/challenges.html): name and ◆ a day. */
  pvp?(): { name: string; perDay: number }[];
}

/**
 * The diamonds, condensed over the Tech tab (the user, 6 Nov 2026: Diamonds and Tech as one tab, the diamonds in about
 * half the pane above the whole tree): a strip of the four totals, then three columns side by side, what pays now,
 * lately and lifetime, each a few one-line rows with the rest under "See more".
 */
export class DiamondsTab {
  readonly el = document.createElement('div');
  private sig = '';
  /** The columns opened past their first rows. */
  private open = new Set<string>();

  constructor(private territory: Territory, private host: DiamondsHost) {
    this.el.className = 'hq-acct hq-dia';
    this.el.addEventListener('click', (e) => {
      const b = (e.target as HTMLElement).closest<HTMLElement>('[data-more]');
      if (!b) return;
      const k = b.dataset.more!;
      if (this.open.has(k)) this.open.delete(k); else this.open.add(k);
      this.render(true);
    });
  }

  /** A column: its heading, its first `show` rows and the rest folded under "See N more". */
  private col(key: string, title: string, rows: string[], show: number, none: string): string {
    const open = this.open.has(key);
    const list = open ? rows : rows.slice(0, show);
    const more = rows.length > show
      ? `<button type="button" class="dia-more" data-more="${key}">${open ? 'Show fewer ▴' : `See ${rows.length - show} more ▾`}</button>` : '';
    return `<div class="dia-col"><h4>${title}</h4>${rows.length ? `<ul>${list.join('')}</ul>${more}` : `<p class="pt-none">${none}</p>`}</div>`;
  }

  render(force = false): void {
    const t = this.territory, L = t.ledger;
    const sig = `${Math.round(t.diamonds * 10)}|${Math.round(t.earned * 10)}|${L.recent.length}|${L.recent[L.recent.length - 1]?.n ?? 0}|${t.version}|${this.host.pvp?.().length ?? 0}`;
    if (!force && sig === this.sig) return;
    this.sig = sig;
    const daily = t.daily();
    const spent = Object.values(L.spent).reduce((a, b) => a + b, 0);
    const towns = Object.entries(L.towns).sort((a, b) => b[1] - a[1]);
    const bonus = Object.entries(L.bonus).sort((a, b) => b[1] - a[1]);
    const pvpLife = Object.entries(L.pvp ?? {}).sort((a, b) => b[1] - a[1]);
    const pvpNow = this.host.pvp?.() ?? [];
    const pvpDay = pvpNow.reduce((a, p) => a + p.perDay, 0);
    const counted = towns.reduce((a, [, n]) => a + n, 0) + L.deeds + bonus.reduce((a, [, n]) => a + n, 0) + pvpLife.reduce((a, [, n]) => a + n, 0);
    const before = Math.max(0, t.earned - counted);
    const li = (what: string, n: string, cls = 'good', sub = '') => `<li><span class="w">${what}${sub ? ` <small>${sub}</small>` : ''}</span><span class="n ${cls}">${n}</span></li>`;

    const now = [
      ...t.paying().map((p) => li(`🏘️ ${esc(p.name)}`, p.perDay ? gem(p.perDay) : '—', p.contested ? 'bad' : 'good',
        p.contested ? '<span class="pt-chip bad">contested</span>' : p.strong ? '<span class="pt-chip good">strong</span>' : '')),
      ...pvpNow.map((p) => li(`🏁 ${esc(p.name)}`, gem(p.perDay), 'good', '<span class="pt-chip good">top spot</span>')),
    ];
    const lately = [...L.recent].reverse().map((e) => {
      const icon = e.kind === 'town' ? '🏘️' : e.kind === 'deed' ? '🏅' : e.kind === 'bonus' ? '🎁' : e.kind === 'pvp' ? '🏁' : '🛒';
      return li(`${icon} ${esc(e.what)}`, signed(e.n, gem), e.n < 0 ? 'bad' : 'good', when(e.h));
    });
    const life: string[] = [];
    if (L.deeds) life.push(li(`🏅 Achievements`, gem(L.deeds), 'good', `${L.tiers} tier${L.tiers === 1 ? '' : 's'}`));
    for (const [name, n] of towns) life.push(li(`🏘️ ${esc(name)}`, gem(n)));
    for (const [name, n] of pvpLife) life.push(li(`🏁 ${esc(name)}`, gem(n)));
    for (const [what, n] of bonus) life.push(li(`🎁 ${esc(what)}`, gem(n)));
    for (const [what, n] of Object.entries(L.spent).sort((a, b) => b[1] - a[1])) life.push(li(`🛒 ${esc(what)}`, signed(-n, gem), 'bad'));
    if (before >= 0.5) life.push(li('Before this account began', gem(before)));

    const stat = (big: string, label: string) => `<div class="dia-stat"><b>${big}</b><span>${label}</span></div>`;
    this.el.innerHTML = `<div class="dia-strip">
        ${stat(gem(Math.floor(t.diamonds + 1e-9)), 'to spend on the tree below')}
        ${stat(`+${gem(daily.perDay + pvpDay)}`, `a day · ${daily.towns} town${daily.towns === 1 ? '' : 's'}${daily.strong ? `, ${daily.strong} strong` : ''}${pvpNow.length ? ` · ${pvpNow.length} PvP` : ''}`)}
        ${stat(gem(t.earned), 'earned in all')}
        ${stat(gem(spent), 'spent')}
      </div>
      <div class="dia-cols">
        ${this.col('now', 'Earning now', now, 4, 'No towns pay yet: carry more of a town’s trade than any other fleet and it pays every game hour.')}
        ${this.col('lately', 'Lately', lately, 10, 'Nothing yet: territory pays every day, and every achievement tier pays too.')}
        ${this.col('life', 'Lifetime', life, 4, 'Nothing earned yet.')}
      </div>`;
  }
}

interface HeartsHost {
  /** Signed in online: hearts are only given there. */
  online(): boolean;
  /** Ask the server for the history (a 'likesLog' comes back). */
  ask(): void;
}

/** The Hearts tab, and the online extra that hears the server's answer. */
export class HeartsTab implements OnlineExtra {
  readonly el = document.createElement('div');
  private data: { log: LikeEntry[]; by: Record<string, number>; since: number; s: CommunityStats } | null = null;
  private askedAt = 0;
  private sig = '';
  /** The HQ window redraws when an answer comes in. */
  onData: () => void = () => {};

  constructor(private host: HeartsHost) { this.el.className = 'hq-acct'; }

  /** Shown: ask for the latest, at most every few seconds. */
  shown(): void {
    if (!this.host.online()) return;
    const t = performance.now();
    if (t - this.askedAt < 4000) return;
    this.askedAt = t;
    this.host.ask();
  }

  render(force = false): void {
    if (!this.host.online()) {
      if (this.sig === 'off' && !force) return;
      this.sig = 'off';
      this.el.innerHTML = `<p class="pt-none">Hearts come from other players, online. Every heart on a road or bridge you built, every thumbs-up on a sign you put up, and every fleet that takes a car from your postcard counts here.</p>`;
      return;
    }
    const d = this.data;
    const sig = d ? `${d.log.length}|${d.log[d.log.length - 1]?.t ?? 0}|${d.s.likes ?? 0}|${d.s.loved}` : 'wait';
    if (!force && sig === this.sig) return;
    this.sig = sig;
    if (!d) { this.el.innerHTML = '<p class="pt-none">Asking the server…</p>'; return; }
    const by = d.by;
    const since = d.since ? new Date(d.since).toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' }) : '';
    const recent = [...d.log].reverse();
    const rows = recent.length
      ? `<table class="pt-table"><thead><tr><th>When</th><th>What</th><th>From</th><th class="n">♥</th></tr></thead><tbody>${recent.map((e) => {
        const what = e.why === 'heart' ? `♥ on your ${esc(e.what ?? 'work')}` : e.why === 'sign' ? `👍 on your sign ${esc(e.what ?? '')}` : `📮 a car taken from your postcard ${esc(e.what ?? '')}`;
        return `<tr><td class="pt-when" title="${esc(new Date(e.t).toLocaleString())}">${ago(e.t)}</td><td>${e.n < 0 ? `<span class="pt-sub">taken back:</span> ${what}` : what}</td><td>${esc(e.who ?? '—')}</td><td class="n ${e.n < 0 ? 'bad' : 'hrt'}">${signed(e.n, (v) => `♥ ${v}`)}</td></tr>`;
      }).join('')}</tbody></table>`
      : '<p class="pt-none">No hearts yet since this record began. Build a road or a bridge people use, put up a sign, or share a postcard.</p>';
    const life = [
      ['♥ Hearts on your works', by.heart ?? 0],
      ['👍 Thumbs-up on your signs', by.sign ?? 0],
      ['📮 Postcard rides (5 each)', by.postcard ?? 0],
    ].map(([k, n]) => `<tr><td>${k}</td><td class="n hrt">♥ ${Number(n).toLocaleString('en-US')}</td></tr>`).join('');
    const counted = (by.heart ?? 0) + (by.sign ?? 0) + (by.postcard ?? 0);
    const before = Math.max(0, (d.s.likes ?? 0) - counted);
    this.el.innerHTML = `<div class="pt-cards">
        ${card(`♥ ${(d.s.likes ?? 0).toLocaleString('en-US')}`, 'likes kept', 'nothing spends them yet')}
        ${card(`♥ ${d.s.loved.toLocaleString('en-US')}`, 'hearts on your works now')}
        ${card(d.s.works.toLocaleString('en-US'), 'works built', `${d.s.listed} listed · ${d.s.uses.toLocaleString('en-US')} crossings`)}
        ${card(d.s.gave.toLocaleString('en-US'), 'builders you’ve hearted')}
      </div>
      <h3>Lately</h3>${rows}
      <h3>Lifetime${since ? ` <small>since ${esc(since)}</small>` : ''}</h3>
      <table class="pt-table"><tbody>${life}${before > 0 ? `<tr><td class="pt-sub">From before this record began</td><td class="n hrt">♥ ${before.toLocaleString('en-US')}</td></tr>` : ''}</tbody></table>`;
  }

  // ---- the online session ----
  welcome(_w: Welcome): void { this.data = null; this.askedAt = 0; }
  cell(_k: string, _doc: CellDoc): void { /* nothing per cell */ }
  got(m: ServerMsg): boolean {
    if (m.t !== 'likesLog') return false;
    this.data = { log: m.log, by: m.by, since: m.since, s: m.s };
    this.onData();
    return true;
  }
  ready(): void { /* asked for when shown */ }
  frame(): void { /* nothing per frame */ }
  forget(): void { /* nothing per cell */ }
  reset(): void { this.data = null; this.askedAt = 0; this.sig = ''; }
}
