/**
 * The way back from the journal's Show Me: while the camera is off looking at a mission's place, a bar
 * across the bottom of the screen says what is being shown and offers the two ways back — to the
 * journal on the same mission (J), or to your own vehicle (Esc). Either button, or its key, ends it.
 */
import { esc } from './card';

export class ShowMeBar {
  private el = document.createElement('div');
  private back: (() => void) | null = null;
  private home: (() => void) | null = null;

  constructor(private blocked: () => boolean) {
    this.el.id = 'showme-bar';
    this.el.hidden = true;
    document.body.append(this.el);
    this.el.addEventListener('click', (e) => {
      const a = (e.target as HTMLElement).closest<HTMLElement>('[data-act]')?.dataset.act;
      if (a === 'journal') this.toJournal();
      else if (a === 'car') this.toCar();
    });
    // ahead of the game's own keys: J would toggle the journal shut again and Esc would open the pause menu
    window.addEventListener('keydown', (e) => {
      // not while a card, the journal or a menu is over it (update() hides the bar then)
      if (!this.active || this.el.hidden || this.blocked()) return;
      if (e.code === 'KeyJ') this.toJournal();
      else if (e.code === 'Escape') this.toCar();
      else return;
      e.preventDefault();
      e.stopPropagation();
    }, true);
  }

  get active(): boolean { return !!this.home; }

  /** The camera has gone to look at `what`: `back` reopens the journal there, `home` brings the camera back to the vehicle. */
  show(what: string, back: () => void, home: () => void): void {
    this.back = back;
    this.home = home;
    this.el.innerHTML = `<span class="sm-what">👁 Showing <b>${esc(what)}</b></span>
      <button type="button" data-act="journal">↩ Back to journal <kbd>J</kbd></button>
      <button type="button" data-act="car">Back to your vehicle <kbd>Esc</kbd></button>`;
    this.el.hidden = false;
  }

  /** Put away without moving the camera (something else has taken it). */
  hide(): void {
    this.back = this.home = null;
    this.el.hidden = true;
  }

  /** Hidden while a card or the journal is over it; back once they close. */
  update(covered: boolean): void {
    if (this.active) this.el.hidden = covered;
  }

  private toJournal(): void {
    const back = this.back, home = this.home;
    this.hide();
    home?.();
    back?.();
  }

  private toCar(): void {
    const home = this.home;
    this.hide();
    home?.();
  }
}
