import * as THREE from 'three';
import { fadingCone, softPoolTexture } from './softLight';

/**
 * A helicopter's searchlight: after dark a white beam from under the nose to the ground, aimed with the
 * mouse. The pointer picks a spot on the ground and the light swings to it, as far as REACH tiles out
 * from the point straight below; beyond that it stops at the edge of its reach, pointing the pointer's
 * way. With no pointer (a gamepad, or the mouse off the window) it looks a little ahead of the nose.
 */

/** How far from straight below the beam can reach, in tiles, and how quickly it swings (per second). */
const REACH = 7, SWING = 5;

export class HeliSpot {
  private light = new THREE.SpotLight(0xfff4dc, 0, 40, 0.15, 0.5, 1);
  private beam: THREE.Mesh;
  private pool: THREE.Mesh;
  private aim = new THREE.Vector3();
  private aimed = false;
  private level = 0;
  private ray = new THREE.Raycaster();
  private plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
  private hit = new THREE.Vector3();
  private lit: { x: number; z: number; r: number } | null = null;

  /** Where the pool of light is on the ground and how wide, in world tiles; null while it is off. */
  spot(): { x: number; z: number; r: number } | null { return this.lit; }

  constructor(scene: THREE.Scene) {
    // the visible shaft: an open cone, its tip at the lamp, glowing faintly in the night air
    // fading over its last part, so it ends in the pool rather than at a ring (render/softLight.ts)
    const cone = fadingCone(20, 0.55);
    this.beam = new THREE.Mesh(cone, new THREE.MeshBasicMaterial({
      color: 0xfff1c8, vertexColors: true, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide,
    }));
    this.beam.renderOrder = 5;
    // and the bright pool where it lands, so the spot reads even on dark ground
    this.pool = new THREE.Mesh(new THREE.CircleGeometry(1, 24), new THREE.MeshBasicMaterial({
      color: 0xfff1c8, map: softPoolTexture(), transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending,
    }));
    this.pool.rotation.x = -Math.PI / 2;
    this.beam.visible = this.pool.visible = false;
    scene.add(this.light, this.light.target, this.beam, this.pool);
  }

  /**
   * One frame. `on` says whether the searchlight is lit now; `lamp` is where it hangs (world tiles) and
   * which way the helicopter faces; `ground(x, z)` the height of the ground there; `pointer` the mouse
   * in normalised device coordinates, or null.
   */
  update(dt: number, on: boolean, lamp: { x: number; y: number; z: number; heading: number }, ground: (x: number, z: number) => number,
    pointer: { x: number; y: number } | null, camera: THREE.Camera): void {
    this.level += ((on ? 1 : 0) - this.level) * Math.min(1, dt * 6);
    if (this.level < 0.01) {
      this.light.intensity = 0;
      this.beam.visible = this.pool.visible = false;
      this.aimed = false;
      this.lit = null;
      return;
    }
    const below = ground(lamp.x, lamp.z);
    // where it wants to look: the ground under the pointer, or a little ahead of the nose
    let tx = lamp.x + Math.sin(lamp.heading) * 2.5, tz = lamp.z + Math.cos(lamp.heading) * 2.5;
    if (pointer) {
      this.ray.setFromCamera(new THREE.Vector2(pointer.x, pointer.y), camera);
      this.plane.constant = -below;
      if (this.ray.ray.intersectPlane(this.plane, this.hit)) { tx = this.hit.x; tz = this.hit.z; }
    }
    const dx = tx - lamp.x, dz = tz - lamp.z, d = Math.hypot(dx, dz);
    if (d > REACH) { tx = lamp.x + (dx / d) * REACH; tz = lamp.z + (dz / d) * REACH; }
    const ty = ground(tx, tz);
    if (!this.aimed) { this.aim.set(tx, ty, tz); this.aimed = true; }
    else {
      const k = Math.min(1, dt * SWING);
      this.aim.x += (tx - this.aim.x) * k;
      this.aim.z += (tz - this.aim.z) * k;
      this.aim.y += (ty - this.aim.y) * k;
    }
    const top = new THREE.Vector3(lamp.x, lamp.y - 0.1, lamp.z);
    const len = top.distanceTo(this.aim);
    this.light.position.copy(top);
    this.light.target.position.copy(this.aim);
    this.light.distance = len + 12;
    this.light.intensity = 26 * this.level;
    // the shaft: its tip at the lamp, stretched down to the spot, as wide there as the light's cone
    const r = Math.tan(this.light.angle) * len;
    this.beam.visible = this.pool.visible = true;
    this.beam.position.copy(top);
    this.beam.scale.set(r, len, r);
    this.beam.quaternion.setFromUnitVectors(new THREE.Vector3(0, -1, 0), this.aim.clone().sub(top).normalize());
    (this.beam.material as THREE.MeshBasicMaterial).opacity = 0.07 * this.level;
    this.pool.position.set(this.aim.x, this.aim.y + 0.06, this.aim.z);
    this.pool.scale.setScalar(r * 0.9);
    this.lit = this.level > 0.6 ? { x: this.aim.x, z: this.aim.z, r: r * 0.9 } : null;
    (this.pool.material as THREE.MeshBasicMaterial).opacity = 0.1 * this.level;
  }

  hide(): void { this.update(1, false, { x: 0, y: 0, z: 0, heading: 0 }, () => 0, null, new THREE.Camera()); }
}
