import { CATS, CAT_COLOUR, CAT_LABEL, catOf, notable, type Cat } from '../../world/townDigest';
import type { Building } from '../../world/tiles';
import { asOf, cap, dl, esc, farNote, plural, pretty, type TabCtx } from './common';

/** How long a town's own building site stands, in game hours (render/townMesh.ts BUILD_HOURS). */
const TOWN_BUILD_HOURS = 2;

/**
 * Tab 2 (docs/townregister.html): what the town is made of. Near, each category, notable kind and set lights its
 * buildings over the ground (the card's `data-show`); a notable building there is only one of opens its card.
 */
export function buildingsTab(c: TabCtx): string {
  const d = c.digest;
  if (!d) return farNote() + '<p class="note">Nothing is known of its buildings yet.</p>';
  const near = !!(c.w && c.t);
  let out = near ? '' : `${farNote()}<p class="note">${asOf(d.day)}.</p>`;

  // the categories as one bar, then a row each
  const cats = CATS.filter((k) => d.cats[k] > 0);
  const total = cats.reduce((s, k) => s + d.cats[k], 0) || 1;
  out += `<div class="tc-cats" role="img" aria-label="Buildings by kind">${cats.map((k) => `<i style="width:${((d.cats[k] / total) * 100).toFixed(2)}%;background:${CAT_COLOUR[k]}" title="${esc(`${CAT_LABEL[k]}: ${d.cats[k]}`)}"></i>`).join('')}</div>`;
  out += `<ul class="tc-catlist">${cats.map((k) => `<li><span class="sw" style="background:${CAT_COLOUR[k]}"></span><span>${CAT_LABEL[k]}</span><b>${d.cats[k]}</b>${near ? `<button type="button" class="link" data-show="cat:${k}">show</button>` : ''}</li>`).join('')}</ul>`;

  // the notable ones
  if (d.notable.length) {
    out += `<h4>Notable <span>${plural(d.notable.reduce((s, [, n]) => s + n, 0), 'building')}</span></h4><ul class="tc-notable">`;
    for (const [kind, n] of d.notable) {
      const one = n === 1 && near ? c.t!.buildings.find((b) => b.kind === kind && !b.gone) : null;
      const tag = catOf(kind) === 'wonder' ? '<em class="wonder">wonder</em>' : catOf(kind) === 'landmark' ? '<em class="lm">landmark</em>' : '';
      const name = `${esc(c.label(kind))}${n > 1 ? ` <small>×${n}</small>` : ''}`;
      out += one ? `<li><button type="button" data-lot="${one.uid}"><span>${name}</span>${tag}</button></li>`
        : near ? `<li><button type="button" data-show="kind:${esc(kind)}"><span>${name}</span>${tag}</button></li>`
        : `<li><span class="plain"><span>${name}</span>${tag}</span></li>`;
    }
    out += '</ul>';
  }

  // the styles it is built in
  if (d.styles.length) {
    const all = d.styles.reduce((s, [, n]) => s + n, 0) || 1;
    out += `<h4>Styles <span>${plural(d.styles.length, 'style')}</span></h4><p class="tc-styles">${d.styles.map(([s, n]) => `<span class="cu${s === d.style ? ' own' : ''}"${near ? ` data-show="style:${esc(s)}"` : ''} title="${esc(`${n} of ${all} buildings`)}">${esc(cap(pretty(s)))} · ${n}${s === d.style ? ' <small>its own</small>' : ''}</span>`).join(' ')}</p>`;
  }

  // what is changing
  const rows: [string, string][] = [];
  if (d.sites) rows.push(['Going up', `${plural(d.sites, 'site')}${near ? ' <button type="button" class="link" data-show="sites">show</button>' : ''}`]);
  if (d.playerBuilt) rows.push(['Fleet-built', `${plural(d.playerBuilt, 'building')} from fleets’ blueprints${near ? ' <button type="button" class="link" data-show="erected">show</button>' : ''}`]);
  if (d.derelict) rows.push(['Blight', `<em class="bad">${d.derelict} boarded up</em>${near ? ' <button type="button" class="link" data-show="blight">show</button>' : ''}`]);
  if (c.ledger?.grown) rows.push(['Grown', `${plural(c.ledger.grown, 'building')} since the books began`]);
  if (rows.length) out += `<h4>Changing</h4>${dl(rows)}`;
  return out;
}

/** The buildings a `data-show` on this tab lights. */
export function buildingsToShow(c: TabCtx, what: string): Building[] {
  const t = c.t;
  if (!t) return [];
  const live = t.buildings.filter((b) => !b.gone);
  const [k, v] = what.split(':');
  switch (k) {
    case 'cat': return live.filter((b) => catOf(b.kind) === (v as Cat));
    case 'kind': return live.filter((b) => b.kind === v);
    case 'style': return live.filter((b) => b.solid && (b.style ?? t.style) === v);
    case 'sites': return live.filter((b) => b.grownAt !== undefined && c.hours < b.grownAt + (b.buildHours ?? TOWN_BUILD_HOURS));
    case 'erected': return live.filter((b) => b.erected);
    case 'blight': return live.filter((b) => b.derelict);
    case 'notable': return live.filter((b) => notable(b.kind));
  }
  return [];
}
