/**
 * Sound effects, synthesised with Web Audio rather than loaded: a knock against a wall, a softer
 * thump against a curb or a slope, the crack of a fence going down and the rasp of a car grinding
 * along a wall. Everything is shaped noise and a falling sine, so there is nothing to download.
 *
 * The context is only made once the player has pressed a key or clicked, as browsers require, and
 * the volume is kept in localStorage beside the music's settings.
 */

const KEY = 'pocket-roads-effects';

interface Stored { volume: number; shake: number }

export class Sfx {
  /** 0..1; 0 is silent. */
  volume = 0.6;
  /** Camera shake from a knock: 1 full, 0.5 gentle, 0 off. Kept here so the settings live together. */
  shake = 1;
  private ctx: AudioContext | null = null;
  private out: GainNode | null = null;
  private noise: AudioBuffer | null = null;
  private scrapeGain: GainNode | null = null;
  private scrapeFilter: BiquadFilterNode | null = null;
  private scrapeSilent = false;
  private screechGain: GainNode | null = null;
  private screechFilter: BiquadFilterNode | null = null;
  private screechSilent = false;
  private listeners = new Set<() => void>();
  private sirenGain: GainNode | null = null;
  private sirenSilent = true;

  constructor() {
    try {
      const s = JSON.parse(localStorage.getItem(KEY) ?? 'null') as Partial<Stored> | null;
      if (s && typeof s.volume === 'number') this.volume = Math.min(1, Math.max(0, s.volume));
      if (s && typeof s.shake === 'number') this.shake = Math.min(1, Math.max(0, s.shake));
    } catch { /* storage blocked: defaults */ }
    const wake = () => this.ensure();
    window.addEventListener('keydown', wake);
    window.addEventListener('pointerdown', wake);
  }

  onChange(fn: () => void): void { this.listeners.add(fn); }

  setVolume(v: number): void {
    this.volume = Math.min(1, Math.max(0, v));
    if (this.out && this.ctx) this.out.gain.setTargetAtTime(this.volume, this.ctx.currentTime, 0.02);
    this.save();
  }

  setShake(v: number): void {
    this.shake = Math.min(1, Math.max(0, v));
    this.save();
  }

  private save(): void {
    try { localStorage.setItem(KEY, JSON.stringify({ volume: this.volume, shake: this.shake } satisfies Stored)); } catch { /* ignore */ }
    for (const fn of this.listeners) fn();
  }

  /** The context, made (or resumed) on the first gesture; null until then. */
  private ensure(): AudioContext | null {
    if (!this.ctx) {
      const Ctor = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
      if (!Ctor) return null;
      try { this.ctx = new Ctor(); } catch { return null; }
      const ctx = this.ctx;
      this.out = ctx.createGain();
      this.out.gain.value = this.volume;
      // a gentle limiter, so a knock and a crack landing together don't clip
      const comp = ctx.createDynamicsCompressor();
      comp.threshold.value = -10;
      comp.ratio.value = 6;
      this.out.connect(comp).connect(ctx.destination);
      const len = ctx.sampleRate;
      this.noise = ctx.createBuffer(1, len, ctx.sampleRate);
      const data = this.noise.getChannelData(0);
      for (let k = 0; k < len; k++) data[k] = Math.random() * 2 - 1;
    }
    if (this.ctx.state === 'suspended') void this.ctx.resume();
    return this.ctx;
  }

  private ready(): AudioContext | null {
    if (!this.ctx || this.ctx.state !== 'running' || this.volume <= 0) return null;
    return this.ctx;
  }

  /** A burst of noise through a filter, with a fast attack and an exponential tail. */
  private burst(t: number, type: BiquadFilterType, freq: number, q: number, gain: number, decay: number, rate = 1): void {
    const ctx = this.ctx!;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    src.playbackRate.value = rate;
    const f = ctx.createBiquadFilter();
    f.type = type;
    f.frequency.value = freq;
    f.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.004);
    g.gain.exponentialRampToValueAtTime(0.0001, t + decay);
    src.connect(f).connect(g).connect(this.out!);
    src.start(t, Math.random() * 0.8);
    src.stop(t + decay + 0.05);
  }

  /** A sine that drops in pitch as it dies: the body of a knock. */
  private boom(t: number, from: number, to: number, gain: number, decay: number): void {
    const ctx = this.ctx!;
    const o = ctx.createOscillator();
    o.type = 'sine';
    o.frequency.setValueAtTime(from, t);
    o.frequency.exponentialRampToValueAtTime(to, t + decay);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.006);
    g.gain.exponentialRampToValueAtTime(0.0001, t + decay);
    o.connect(g).connect(this.out!);
    o.start(t);
    o.stop(t + decay + 0.05);
  }

  /** Into a wall: a low knock, and for a hard one the clank of a bumper. */
  knock(strength: number): void {
    const ctx = this.ready();
    if (!ctx) return;
    const t = ctx.currentTime, s = Math.min(1, Math.max(0, strength));
    const pitch = 0.9 + Math.random() * 0.2;
    this.boom(t, 120 * pitch, 42, 0.25 + 0.55 * s, 0.18 + 0.12 * s);
    this.burst(t, 'lowpass', 500 + 900 * s, 0.7, 0.2 + 0.5 * s, 0.1 + 0.15 * s);
    if (s > 0.35) this.burst(t + 0.005, 'bandpass', 2300 * pitch, 6, 0.12 * s, 0.07);
  }

  /** Against a curb, a slope, the shore or a fence that held: a dull thump with no clatter. */
  thump(strength: number): void {
    const ctx = this.ready();
    if (!ctx) return;
    const t = ctx.currentTime, s = Math.min(1, Math.max(0, strength));
    this.boom(t, 85, 38, 0.2 + 0.4 * s, 0.16 + 0.08 * s);
    this.burst(t, 'lowpass', 280 + 300 * s, 0.7, 0.12 + 0.25 * s, 0.12);
  }

  /** A building done: the scaffold comes away in a soft whump of dust. `level` is how near it is, 0 to 1. */
  poof(level: number): void {
    const ctx = this.ready();
    if (!ctx || level < 0.02) return;
    const t = ctx.currentTime, s = Math.min(1, level);
    this.boom(t, 120, 45, 0.25 * s, 0.22);
    this.burst(t, 'bandpass', 900, 0.6, 0.3 * s, 0.35, 0.7);
  }

  /** A fence going down: splintering timber, or stones tumbling off a wall. */
  crack(stone: boolean, strength: number): void {
    const ctx = this.ready();
    if (!ctx) return;
    const t = ctx.currentTime, s = Math.min(1, Math.max(0, strength));
    this.boom(t, stone ? 90 : 140, 45, 0.2 + 0.25 * s, 0.14);
    const pieces = stone ? 6 : 4;
    for (let k = 0; k < pieces; k++) {
      const at = t + k * (stone ? 0.035 : 0.022) + Math.random() * 0.015;
      if (stone) this.burst(at, 'bandpass', 500 + Math.random() * 500, 3, 0.25 * (1 - k / pieces) + 0.05, 0.08, 0.7);
      else this.burst(at, 'bandpass', 1400 + Math.random() * 1600, 4, 0.35 * (1 - k / pieces) + 0.08, 0.05);
    }
  }

  /** A deed's tier landing: a rising fifth, a step higher per tier, at the volume of a thump. */
  chime(tier: number): void {
    const ctx = this.ready();
    if (!ctx) return;
    const t = ctx.currentTime;
    // a whole tone per tier from A4: Bronze low, Diamond bright
    const base = 440 * Math.pow(2, (2 * Math.max(0, Math.min(4, tier - 1))) / 12);
    for (const [k, f] of [[0, base], [1, base * 1.5]] as const) {
      const o = ctx.createOscillator();
      o.type = 'triangle';
      o.frequency.value = f;
      const g = ctx.createGain();
      const at = t + k * 0.13;
      g.gain.setValueAtTime(0.0001, at);
      g.gain.exponentialRampToValueAtTime(0.22, at + 0.01);
      g.gain.exponentialRampToValueAtTime(0.0001, at + 0.55);
      o.connect(g).connect(this.out!);
      o.start(at);
      o.stop(at + 0.6);
    }
  }

  /**
   * A diamond (docs/territory.html): a quick rising sparkle of bell notes, a fifth brighter for each extra
   * diamond in the same payment (to an octave), with a shimmer of high noise over it.
   */
  sparkle(n = 1): void {
    const ctx = this.ready();
    if (!ctx) return;
    const t = ctx.currentTime;
    const lift = Math.pow(2, Math.min(12, (Math.max(1, n) - 1) * 2) / 12);
    const notes = [1046.5, 1318.5, 1568, 2093].map((f) => f * lift);
    notes.forEach((f, k) => {
      const o = ctx.createOscillator();
      o.type = k === notes.length - 1 ? 'sine' : 'triangle';
      o.frequency.value = f;
      const g = ctx.createGain();
      const at = t + k * 0.055;
      g.gain.setValueAtTime(0.0001, at);
      g.gain.exponentialRampToValueAtTime(k === notes.length - 1 ? 0.16 : 0.1, at + 0.006);
      g.gain.exponentialRampToValueAtTime(0.0001, at + (k === notes.length - 1 ? 0.9 : 0.3));
      o.connect(g).connect(this.out!);
      o.start(at);
      o.stop(at + 1);
    });
    this.burst(t + 0.16, 'highpass', 7000, 0.7, 0.05, 0.5, 1.4);
  }

  /** A milestone on the way to a tier: one soft bell note, quieter and shorter than a tier's chime. */
  nudge(): void {
    const ctx = this.ready();
    if (!ctx) return;
    const t = ctx.currentTime;
    const o = ctx.createOscillator();
    o.type = 'sine';
    o.frequency.value = 880;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.09, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.35);
    o.connect(g).connect(this.out!);
    o.start(t);
    o.stop(t + 0.4);
  }

  /** Nitrous lighting: a rush of filtered air that swells and dies over the burst, with a low thump under it. */
  /**
   * Thunder after a lightning flash (render/weather.ts): `near` 0..1. The nearer, the sooner it comes, with a
   * sharp crack first; then a low rumble that rolls on for a few seconds.
   */
  thunder(near: number): void {
    const ctx = this.ready();
    if (!ctx) return;
    const n = Math.min(1, Math.max(0, near));
    const t = ctx.currentTime + 0.25 + (1 - n) * 2.2;
    if (n > 0.6) this.burst(t, 'highpass', 1600, 0.7, 0.16 * n, 0.14);
    this.boom(t, 62, 26, 0.22 + 0.32 * n, 1.4 + 1.2 * (1 - n));
    const len = 2.2 + 2.0 * (1 - n);
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    src.loop = true;
    src.playbackRate.value = 0.5;
    const f = ctx.createBiquadFilter();
    f.type = 'lowpass';
    f.Q.value = 0.6;
    f.frequency.setValueAtTime(260 + 200 * n, t);
    f.frequency.exponentialRampToValueAtTime(90, t + len);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.28 + 0.3 * n, t + 0.08);
    // it rolls: swells and ebbs on its way out
    for (let k = 1; k <= 4; k++) g.gain.exponentialRampToValueAtTime((0.28 + 0.3 * n) * (k % 2 ? 0.45 : 0.8) * (1 - k * 0.15), t + (len * k) / 5);
    g.gain.exponentialRampToValueAtTime(0.0001, t + len);
    src.connect(f).connect(g).connect(this.out!);
    src.start(t);
    src.stop(t + len + 0.1);
  }

  /**
   * A boost pad biting (`launch` false), or a car leaving a jump's kicker (true): a rising sweep of rushing air
   * over a synth zip, the take-off longer and lower. `level` is how near it is, 0..1.
   */
  whoosh(launch = false, level = 1): void {
    const ctx = this.ready();
    if (!ctx || level < 0.02) return;
    const t = ctx.currentTime, len = launch ? 0.9 : 0.55, s = Math.min(1, level);
    this.boom(t, launch ? 90 : 140, 45, 0.3 * s, 0.25);
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    src.loop = true;
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.Q.value = 1.4;
    f.frequency.setValueAtTime(launch ? 400 : 700, t);
    f.frequency.exponentialRampToValueAtTime(launch ? 2200 : 3600, t + len * 0.6);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.32 * s, t + 0.06);
    g.gain.exponentialRampToValueAtTime(0.0001, t + len);
    src.connect(f).connect(g).connect(this.out!);
    src.start(t);
    src.stop(t + len + 0.05);
    const o = ctx.createOscillator();
    o.type = 'sawtooth';
    o.frequency.setValueAtTime(launch ? 110 : 220, t);
    o.frequency.exponentialRampToValueAtTime(launch ? 660 : 1320, t + len * 0.7);
    const og = ctx.createGain();
    og.gain.setValueAtTime(0.0001, t);
    og.gain.exponentialRampToValueAtTime(0.06 * s, t + 0.04);
    og.gain.exponentialRampToValueAtTime(0.0001, t + len * 0.8);
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 1800;
    o.connect(lp).connect(og).connect(this.out!);
    o.start(t);
    o.stop(t + len);
  }

  hiss(secs: number): void {
    const ctx = this.ready();
    if (!ctx) return;
    const t = ctx.currentTime;
    this.boom(t, 70, 40, 0.35, 0.25);
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    src.loop = true;
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.Q.value = 0.8;
    f.frequency.setValueAtTime(900, t);
    f.frequency.exponentialRampToValueAtTime(2600, t + 0.4);
    f.frequency.exponentialRampToValueAtTime(1200, t + secs);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.3, t + 0.4);
    g.gain.setValueAtTime(0.3, t + Math.max(0.45, secs - 0.4));
    g.gain.exponentialRampToValueAtTime(0.0001, t + secs + 0.2);
    src.connect(f).connect(g).connect(this.out!);
    src.start(t);
    src.stop(t + secs + 0.3);
  }

  /**
   * A horn. Cars beep and then blare; boats and ships drone; flyers honk; trains whistle. The top tier
   * plays a five-note tune hashed from `seed`, so every car's is its own.
   */
  horn(kind: string, tier: number, seed: number): void {
    const ctx = this.ready();
    if (!ctx) return;
    const t = ctx.currentTime;
    const tone = (at: number, f: number, dur: number, type: OscillatorType, gain: number, f2 = 0) => {
      const o = ctx.createOscillator();
      o.type = type;
      o.frequency.setValueAtTime(f, at);
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, at);
      g.gain.exponentialRampToValueAtTime(gain, at + 0.02);
      g.gain.setValueAtTime(gain, at + Math.max(0.03, dur - 0.05));
      g.gain.exponentialRampToValueAtTime(0.0001, at + dur);
      const lp = ctx.createBiquadFilter();
      lp.type = 'lowpass';
      lp.frequency.value = 2400;
      o.connect(lp).connect(g).connect(this.out!);
      o.start(at);
      o.stop(at + dur + 0.02);
      if (f2) {
        const o2 = ctx.createOscillator();
        o2.type = type;
        o2.frequency.value = f2;
        o2.connect(lp);
        o2.start(at);
        o2.stop(at + dur + 0.02);
      }
    };
    if (tier >= 3 && kind !== 'water') {
      // five notes of a major scale, picked by the unit
      const scale = [0, 2, 4, 5, 7, 9, 12];
      let h = (seed * 2654435761) >>> 0;
      const base = kind === 'rail' ? 523 : 392;
      for (let k = 0; k < 5; k++) {
        h = (h * 1103515245 + 12345) >>> 0;
        const f = base * Math.pow(2, scale[h % scale.length] / 12);
        tone(t + k * 0.14, f, 0.13, kind === 'rail' ? 'sine' : 'square', 0.12);
      }
      return;
    }
    if (kind === 'water') {
      const f = tier === 1 ? 110 : tier === 2 ? 82 : 98;
      tone(t, f, tier === 1 ? 1 : 1.6, 'sawtooth', 0.22, tier === 3 ? f * 1.26 : 0);
    } else if (kind === 'rail') {
      tone(t, 660, tier === 1 ? 0.5 : 1.1, 'sine', 0.16, tier === 1 ? 830 : 990);
    } else if (kind === 'air') {
      tone(t, 330, tier === 1 ? 0.35 : 0.8, 'square', 0.14, 415);
    } else if (tier === 1) {
      tone(t, 440, 0.12, 'square', 0.13);
      tone(t + 0.14, 660, 0.14, 'square', 0.13);
    } else {
      tone(t, 311, 0.2, 'sawtooth', 0.16, 392);
      tone(t + 0.22, 311, 0.4, 'sawtooth', 0.18, 466);
    }
  }

  /**
   * A Passport treat horn (game/passportRewards.ts), made like the horns above from oscillators: 'fanfare' a short
   * brass call (two voices of buzzing reed through a soft filter, the last note held with a vibrato over a chord);
   * 'confetti' a party blower's two squawks, the second unrolling up, and the pop of the confetti cannon.
   */
  treatHorn(tune: 'fanfare' | 'confetti'): void {
    const ctx = this.ready();
    if (!ctx) return;
    const t = ctx.currentTime;
    const brass = (at: number, f: number, dur: number, gain: number, vib = 0) => {
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, at);
      g.gain.exponentialRampToValueAtTime(gain, at + 0.03);
      g.gain.setValueAtTime(gain * 0.85, at + Math.max(0.05, dur - 0.06));
      g.gain.exponentialRampToValueAtTime(0.0001, at + dur);
      const lp = ctx.createBiquadFilter();
      lp.type = 'lowpass';
      // the bell opens as the note speaks
      lp.frequency.setValueAtTime(900, at);
      lp.frequency.exponentialRampToValueAtTime(3200, at + 0.06);
      lp.Q.value = 2;
      lp.connect(g).connect(this.out!);
      for (const [type, mul, lvl] of [['sawtooth', 1, 1], ['square', 0.5, 0.45]] as [OscillatorType, number, number][]) {
        const o = ctx.createOscillator();
        o.type = type;
        o.frequency.setValueAtTime(f * mul * 0.985, at);
        o.frequency.exponentialRampToValueAtTime(f * mul, at + 0.04);
        const og = ctx.createGain();
        og.gain.value = lvl;
        o.connect(og).connect(lp);
        if (vib) {
          const lfo = ctx.createOscillator(), lg = ctx.createGain();
          lfo.frequency.value = 5.5;
          lg.gain.value = f * mul * vib;
          lfo.connect(lg).connect(o.frequency);
          lfo.start(at + 0.15);
          lfo.stop(at + dur + 0.02);
        }
        o.start(at);
        o.stop(at + dur + 0.02);
      }
    };
    if (tune === 'fanfare') {
      // G4 C5 E5, a breath, then G5 held over E5 and C5
      const G4 = 392, C5 = 523.25, E5 = 659.25, G5 = 783.99;
      brass(t, G4, 0.13, 0.1);
      brass(t + 0.15, C5, 0.13, 0.1);
      brass(t + 0.3, E5, 0.13, 0.1);
      brass(t + 0.47, G5, 0.75, 0.11, 0.012);
      brass(t + 0.47, E5, 0.75, 0.05);
      brass(t + 0.47, C5, 0.75, 0.05);
      return;
    }
    // a party blower: a buzzy reed, a short squawk then a longer one rising as it unrolls, with a flutter
    const blow = (at: number, f0: number, f1: number, dur: number) => {
      const o = ctx.createOscillator();
      o.type = 'sawtooth';
      o.frequency.setValueAtTime(f0, at);
      o.frequency.exponentialRampToValueAtTime(f1, at + dur * 0.7);
      o.frequency.exponentialRampToValueAtTime(f1 * 0.94, at + dur);
      const flutter = ctx.createOscillator(), fg = ctx.createGain();
      flutter.frequency.value = 26;
      fg.gain.value = 0.35;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, at);
      g.gain.exponentialRampToValueAtTime(0.13, at + 0.02);
      g.gain.setValueAtTime(0.12, at + dur - 0.04);
      g.gain.exponentialRampToValueAtTime(0.0001, at + dur);
      const trem = ctx.createGain();
      trem.gain.value = 0.65;
      flutter.connect(fg).connect(trem.gain);
      const bp = ctx.createBiquadFilter();
      bp.type = 'bandpass';
      bp.frequency.value = 1400;
      bp.Q.value = 0.7;
      o.connect(bp).connect(trem).connect(g).connect(this.out!);
      o.start(at); o.stop(at + dur + 0.02);
      flutter.start(at); flutter.stop(at + dur + 0.02);
    };
    blow(t, 470, 520, 0.14);
    blow(t + 0.2, 430, 640, 0.5);
    // the cannon's pop: a burst of noise and a low thump
    if (this.noise) {
      const at = t + 0.2;
      const src = ctx.createBufferSource();
      src.buffer = this.noise;
      const hp = ctx.createBiquadFilter();
      hp.type = 'highpass';
      hp.frequency.value = 1200;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.35, at);
      g.gain.exponentialRampToValueAtTime(0.0001, at + 0.12);
      src.connect(hp).connect(g).connect(this.out!);
      src.start(at);
      src.stop(at + 0.15);
      this.boom(at, 120, 60, 0.2, 0.12);
    }
  }

  /** Tyres sliding, called every frame like the scrape: a high squeal that rises with the slide. */
  screech(level: number): void {
    const ctx = this.ctx;
    if (!ctx || ctx.state !== 'running' || !this.noise) return;
    if (!this.screechGain) {
      if (level <= 0) return;
      const src = ctx.createBufferSource();
      src.buffer = this.noise;
      src.loop = true;
      const f = ctx.createBiquadFilter();
      f.type = 'bandpass';
      f.Q.value = 9;
      f.frequency.value = 2200;
      const g = ctx.createGain();
      g.gain.value = 0;
      src.connect(f).connect(g).connect(this.out!);
      src.start();
      this.screechGain = g;
      this.screechFilter = f;
    }
    const l = Math.min(1, Math.max(0, level));
    if (l === 0 && this.screechSilent) return;
    this.screechSilent = l === 0;
    this.screechGain.gain.setTargetAtTime(l * 0.2, ctx.currentTime, l > 0 ? 0.03 : 0.08);
    this.screechFilter!.frequency.setTargetAtTime(1900 + 900 * l + Math.random() * 120, ctx.currentTime, 0.04);
  }

  /**
   * A police siren, called every frame with how near the nearest one is: 0 is silent. A two-tone wail
   * (a sawtooth swapped between two notes by a slow square wave), started the first time and then only
   * turned up and down, like the screech.
   */
  siren(level: number): void {
    const ctx = this.ctx;
    if (!ctx || ctx.state !== 'running') return;
    if (!this.sirenGain) {
      if (level <= 0) return;
      const o = ctx.createOscillator();
      o.type = 'sawtooth';
      o.frequency.value = 760;
      const lfo = ctx.createOscillator();
      lfo.type = 'square';
      lfo.frequency.value = 1.3;
      const depth = ctx.createGain();
      depth.gain.value = 130;
      lfo.connect(depth).connect(o.frequency);
      const lp = ctx.createBiquadFilter();
      lp.type = 'lowpass';
      lp.frequency.value = 2200;
      const g = ctx.createGain();
      g.gain.value = 0;
      o.connect(lp).connect(g).connect(this.out!);
      o.start();
      lfo.start();
      this.sirenGain = g;
    }
    const l = Math.min(1, Math.max(0, level));
    if (l === 0 && this.sirenSilent) return;
    this.sirenSilent = l === 0;
    this.sirenGain.gain.setTargetAtTime(l * l * 0.13, ctx.currentTime, l > 0 ? 0.05 : 0.25);
  }

  /**
   * Jets (docs/rides.html), called every frame: `level` is how loud the nearest one is (0 silent) and
   * `pitch` 0..1 how hard its engines are working. A low roar of filtered noise under a thin turbine
   * whine, started the first time and then only turned up and down, like the siren.
   */
  jet(level: number, pitch: number): void {
    const ctx = this.ctx;
    if (!ctx || ctx.state !== 'running' || !this.noise) return;
    if (!this.jetGain) {
      if (level <= 0) return;
      const src = ctx.createBufferSource();
      src.buffer = this.noise;
      src.loop = true;
      const lp = ctx.createBiquadFilter();
      lp.type = 'lowpass';
      lp.frequency.value = 420;
      lp.Q.value = 0.7;
      const whine = ctx.createOscillator();
      whine.type = 'triangle';
      whine.frequency.value = 1400;
      const wg = ctx.createGain();
      wg.gain.value = 0.05;
      const g = ctx.createGain();
      g.gain.value = 0;
      src.connect(lp).connect(g);
      whine.connect(wg).connect(g);
      g.connect(this.out!);
      src.start();
      whine.start();
      this.jetGain = g;
      this.jetFilter = lp;
      this.jetWhine = whine;
    }
    const l = Math.min(1, Math.max(0, level));
    if (l === 0 && this.jetSilent) return;
    this.jetSilent = l === 0;
    const p = Math.min(1, Math.max(0, pitch));
    this.jetGain.gain.setTargetAtTime(l * l * 0.22, ctx.currentTime, 0.2);
    this.jetFilter!.frequency.setTargetAtTime(300 + 500 * p, ctx.currentTime, 0.3);
    this.jetWhine!.frequency.setTargetAtTime(1100 + 900 * p, ctx.currentTime, 0.4);
  }
  private jetGain: GainNode | null = null;
  private jetFilter: BiquadFilterNode | null = null;
  private jetWhine: OscillatorNode | null = null;
  private jetSilent = true;

  /** The whoop a patrol car gives as it pulls in front: a quick rising sweep. */
  whoop(): void {
    const ctx = this.ready();
    if (!ctx) return;
    const t = ctx.currentTime;
    const o = ctx.createOscillator();
    o.type = 'sawtooth';
    o.frequency.setValueAtTime(300, t);
    o.frequency.exponentialRampToValueAtTime(1200, t + 0.35);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.14, t + 0.05);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.45);
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 2400;
    o.connect(lp).connect(g).connect(this.out!);
    o.start(t);
    o.stop(t + 0.5);
  }

  /** A soft tick: a cone's edge came close. */
  tick(): void {
    const ctx = this.ready();
    if (!ctx) return;
    const t = ctx.currentTime;
    const o = ctx.createOscillator();
    o.type = 'sine';
    o.frequency.setValueAtTime(1800, t);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.06, t + 0.005);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.07);
    o.connect(g).connect(this.out!);
    o.start(t);
    o.stop(t + 0.1);
  }

  /**
   * Grinding along a wall, called every frame: 0 is silent. The loop is started the first time it's
   * needed and then only has its level and pitch moved, so it doesn't click in and out.
   */
  scrape(level: number): void {
    const ctx = this.ctx;
    if (!ctx || ctx.state !== 'running' || !this.noise) return;
    if (!this.scrapeGain) {
      if (level <= 0) return;
      const src = ctx.createBufferSource();
      src.buffer = this.noise;
      src.loop = true;
      const f = ctx.createBiquadFilter();
      f.type = 'bandpass';
      f.Q.value = 1.4;
      f.frequency.value = 1500;
      const g = ctx.createGain();
      g.gain.value = 0;
      src.connect(f).connect(g).connect(this.out!);
      src.start();
      this.scrapeGain = g;
      this.scrapeFilter = f;
    }
    const l = Math.min(1, Math.max(0, level));
    // silent and already told to be: don't pile another automation event onto the params every frame
    if (l === 0 && this.scrapeSilent) return;
    this.scrapeSilent = l === 0;
    // a quick attack when contact starts, a slightly slower release when it stops
    this.scrapeGain.gain.setTargetAtTime(l * 0.32 * (0.85 + Math.random() * 0.3), ctx.currentTime, l > 0 ? 0.015 : 0.06);
    this.scrapeFilter!.frequency.setTargetAtTime(900 + 1600 * l, ctx.currentTime, 0.05);
  }
}
