/**
 * The social window (docs/social.html): everything about other fleets, in one centred card on I, in the
 * HQ window's frame. Each tab is a module that draws two columns (a list on the left, what is picked in it
 * on the right) and takes the presses inside them; this is the shell: the header with the fleet's shield
 * and a search box, the tab row with its keys, the note line, the two columns and the redraw rhythm.
 *
 * Tabs: Standings (game/standings.ts), Fleets (net/fleetsTab.ts: every other fleet, player's or CPU firm's,
 * with the fleet card), Neighbours (net/neighbours.ts: the dealings ledger), Shared Fleet (net/crewTab.ts) and
 * World (net/worldTab.ts: the map's records) and Inbox (net/inbox.ts: notes, invites, asks and whispers). The
 * online tabs are hidden in a local game. The window redraws four times a second while open and swaps a
 * column's markup only when it has changed, never while something in it is being typed into.
 */
import { esc } from './cargoHud';

export type SocialTab = 'standings' | 'fleets' | 'neighbours' | 'crew' | 'world' | 'inbox';
const TAB_LABEL: Record<SocialTab, string> = { standings: 'Standings', fleets: 'Fleets', neighbours: 'Neighbours', crew: 'Shared Fleet', world: 'World', inbox: 'Inbox' };
const ORDER: SocialTab[] = ['standings', 'fleets', 'neighbours', 'crew', 'world', 'inbox'];
const TAB_KEY = 'tinyfleet-social-tab';

/** Seconds between redraws while open. */
const REFRESH = 0.25;

/** One tab of the window. */
export interface SocialTabBody {
  /** The two columns' markup. */
  html(): { left: string; right: string };
  /** A pointerdown inside the window: true if it was this tab's. */
  press(target: HTMLElement): boolean;
  /** Shown (opened, or switched to). */
  opened?(): void;
  /** Every few seconds while shown. */
  tick?(): void;
  /** Something typed into the window's search box (the Fleets tab filters by it). */
  search?(text: string): void;
  /** Something typed into a field in the columns, by the field's name, so a redraw can keep it. */
  typed?(name: string, value: string): void;
  /** Only while playing online. */
  onlineOnly?: boolean;
  /** A count on the tab's label (unread in the Inbox). */
  badge?(): number;
  /** Something in the drawn columns to finish after they are on the page (stills to draw). */
  afterRender?(left: HTMLElement, right: HTMLElement): void;
}

interface SocialHost {
  /** The fleet's shield, for the header. */
  shield(): string;
  /** Playing online. */
  online(): boolean;
  /** Called on open, so the other windows and tools can step aside. */
  opened(): void;
  /** A player's name pressed inside the window: their fleet's card (net/fleetCard.ts). */
  openCard(pid: string): void;
}

export class SocialWindow {
  readonly el = document.createElement('div');
  isOpen = false;
  private tab: SocialTab = 'standings';
  private tabsEl = document.createElement('nav');
  private head = document.createElement('div');
  private search = document.createElement('input');
  private note = document.createElement('p');
  private left = document.createElement('div');
  private right = document.createElement('div');
  private leftHtml = '';
  private rightHtml = '';
  private headHtml = '';
  private message = '';
  private messageT = 0;
  private t = 0;
  private tickT = 0;
  private tabs = new Map<SocialTab, SocialTabBody>();

  constructor(private host: SocialHost) {
    this.el.id = 'social';
    this.el.hidden = true;
    const panel = document.createElement('div');
    panel.className = 'panel';
    const header = document.createElement('header');
    this.head.className = 'sw-head';
    const find = document.createElement('label');
    find.className = 'sw-find';
    this.search.type = 'text';
    this.search.placeholder = 'Find a fleet or a player';
    this.search.maxLength = 40;
    this.search.spellcheck = false;
    this.search.autocomplete = 'off';
    this.search.addEventListener('input', () => {
      const text = this.search.value.trim();
      if (text && this.tab !== 'fleets' && this.tabs.has('fleets')) this.show('fleets');
      this.tabs.get('fleets')?.search?.(text);
      this.render();
    });
    find.append('🔍', this.search);
    header.append(this.head, find);
    this.tabsEl.className = 'gtabs sw-tabs';
    this.tabsEl.setAttribute('role', 'tablist');
    this.note.className = 'note sw-note';
    const body = document.createElement('div');
    body.className = 'sw-body';
    this.left.className = 'sw-col sw-left';
    this.right.className = 'sw-col sw-right';
    body.append(this.left, this.right);
    panel.append(header, this.tabsEl, this.note, body);
    this.el.append(panel);
    this.el.addEventListener('mousedown', (e) => { if (e.target === this.el) this.close(); });
    // on pointerdown: the window redraws four times a second, and a click could fall between two of them
    body.addEventListener('pointerdown', (e) => {
      const t = e.target as HTMLElement;
      if (t.tagName === 'INPUT' || t.tagName === 'SELECT' || t.tagName === 'TEXTAREA' || t.closest('label')) return;
      const page = this.tabs.get(this.tab);
      if (page?.press(t)) {
        e.preventDefault();
        // a field that was being typed in lets go, so the columns may be drawn again
        const a = document.activeElement as HTMLElement | null;
        if (a && body.contains(a)) a.blur();
        this.render();
        return;
      }
      // a player's name anywhere in the columns is their card: taken here on pointerdown, since a redraw between
      // the press and its release (the ranking's numbers move) would lose a click
      const named = t.closest('[data-pid]') as HTMLElement | null;
      if (named?.dataset.pid && !named.dataset.fcact && !t.closest('button, a, input, select, label')) {
        e.preventDefault();
        this.host.openCard(named.dataset.pid);
        this.render();
      }
    });
    body.addEventListener('input', (e) => {
      const t = e.target as HTMLInputElement | null;
      if (t?.name) this.tabs.get(this.tab)?.typed?.(t.name, t.value);
    });
    window.addEventListener('keydown', (e) => this.onKey(e));
    try {
      const t = localStorage.getItem(TAB_KEY) as SocialTab | null;
      if (t && ORDER.includes(t)) this.tab = t;
    } catch { /* not remembered */ }
  }

  /** A tab's module, in the window's order. */
  add(id: SocialTab, body: SocialTabBody): void {
    this.tabs.set(id, body);
    this.tabsEl.replaceChildren();
    for (const t of ORDER) {
      const page = this.tabs.get(t);
      if (!page) continue;
      const b = document.createElement('button');
      b.type = 'button';
      b.dataset.tab = t;
      b.setAttribute('role', 'tab');
      b.addEventListener('click', () => this.show(t));
      b.innerHTML = TAB_LABEL[t];
      this.tabsEl.append(b);
    }
    // laid out (which tabs show, their keys) only once open: the host's online check needs a game that is up
    if (this.isOpen) this.drawTabs();
  }

  get current(): SocialTab { return this.tab; }

  /** The tabs that can show now: the online ones only online. */
  private shownTabs(): SocialTab[] {
    const on = this.host.online();
    return ORDER.filter((t) => { const p = this.tabs.get(t); return p && (on || !p.onlineOnly); });
  }

  private drawTabs(): void {
    const shown = this.shownTabs();
    for (const b of Array.from(this.tabsEl.children) as HTMLButtonElement[]) {
      const t = b.dataset.tab as SocialTab;
      const k = shown.indexOf(t);
      b.hidden = k < 0;
      const n = this.tabs.get(t)?.badge?.() ?? 0;
      // drawn four times a second: the label is only rewritten when it changes, so a click on it is never lost
      const html = `<kbd>${k + 1}</kbd> ${TAB_LABEL[t]}${n ? ` <em class="sw-badge">${n}</em>` : ''}`;
      if (b.innerHTML !== html) b.innerHTML = html;
      b.classList.toggle('on', t === this.tab);
      b.setAttribute('aria-selected', String(t === this.tab));
    }
  }

  toggle(tab?: SocialTab): void {
    if (this.isOpen && (!tab || tab === this.tab)) { this.close(); return; }
    this.show(tab);
  }

  /** Open, at a tab if given (else the last one used). */
  open(tab?: SocialTab): void { this.show(tab); }

  show(tab?: SocialTab): void {
    const shown = this.shownTabs();
    if (tab && !shown.includes(tab)) tab = undefined;
    if (!this.isOpen) {
      this.isOpen = true;
      this.el.hidden = false;
      this.host.opened();
      this.message = '';
      this.search.value = '';
      this.tabs.get('fleets')?.search?.('');
    }
    if (!tab && !shown.includes(this.tab)) tab = shown[0];
    if (tab) this.tab = tab;
    try { localStorage.setItem(TAB_KEY, this.tab); } catch { /* not remembered */ }
    this.tabs.get(this.tab)?.opened?.();
    this.tickT = 0;
    this.drawTabs();
    this.render(true);
  }

  close(): void {
    if (!this.isOpen) return;
    this.isOpen = false;
    this.el.hidden = true;
    this.search.blur();
  }

  /** A line under the tabs for a few seconds. */
  say(text: string): void { this.message = text; this.messageT = 4; this.note.textContent = text; }

  /** Something a tab shows has changed: drawn again now if it is up. */
  refresh(): void { if (this.isOpen) this.render(); }

  tick(dt: number): void {
    if (!this.isOpen) return;
    if (this.messageT > 0) { this.messageT -= dt; if (this.messageT <= 0) { this.message = ''; this.note.textContent = ''; } }
    // a local game has no online tabs: back to the first
    if (!this.shownTabs().includes(this.tab)) { this.show(); return; }
    this.tickT -= dt;
    if (this.tickT <= 0) { this.tickT = 3; this.tabs.get(this.tab)?.tick?.(); }
    this.t -= dt;
    if (this.t <= 0) { this.t = REFRESH; this.render(); }
  }

  private onKey(e: KeyboardEvent): void {
    if (!this.isOpen) return;
    const t = e.target as HTMLElement | null;
    if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT')) {
      // Enter in a reply box sends it, as its button does (the inbox's whisper, 7 Nov 2026)
      if ((e.code === 'Enter' || e.code === 'NumpadEnter') && !e.shiftKey && !e.isComposing) {
        const send = t.closest('.ib-reply')?.querySelector<HTMLElement>('[data-iact="send"]');
        if (send && this.tabs.get(this.tab)?.press(send)) {
          e.preventDefault(); e.stopImmediatePropagation();
          // the column is redrawn with what was sent (it is left alone while typed in), and the box keeps the focus for the next line
          t.blur();
          this.render(true);
          this.right.querySelector<HTMLInputElement>('.ib-reply input')?.focus();
          return;
        }
      }
      if (e.code === 'Escape' && t === this.search) { this.search.value = ''; this.tabs.get('fleets')?.search?.(''); this.search.blur(); this.render(); e.preventDefault(); e.stopImmediatePropagation(); }
      return;
    }
    const shown = this.shownTabs();
    if (/^Digit[1-9]$/.test(e.code)) { const tab = shown[Number(e.code.slice(5)) - 1]; if (tab) { this.show(tab); e.preventDefault(); } return; }
    if (e.code === 'Tab') { this.show(shown[(shown.indexOf(this.tab) + (e.shiftKey ? shown.length - 1 : 1)) % shown.length]); e.preventDefault(); return; }
    if (e.code === 'Slash' && !e.ctrlKey && !e.metaKey) { this.search.focus(); e.preventDefault(); e.stopImmediatePropagation(); }
  }

  private render(force = false): void {
    if (!this.isOpen) return;
    const head = `<img class="shield" src="${esc(this.host.shield())}" alt=""><h2>Social<span>.</span> <small>${TAB_LABEL[this.tab]}</small></h2>`;
    if (head !== this.headHtml) { this.headHtml = head; this.head.innerHTML = head; }
    this.drawTabs();
    if (!this.message && this.note.textContent) this.note.textContent = '';
    const page = this.tabs.get(this.tab);
    const { left, right } = page?.html() ?? { left: '', right: '' };
    // a column is left alone while a field in it is being typed into (a redraw would drop the typing)
    const typingIn = (el: HTMLElement) => {
      const a = document.activeElement as HTMLElement | null;
      return !!a && el.contains(a) && (a.tagName === 'TEXTAREA' || a.tagName === 'SELECT' || (a.tagName === 'INPUT' && (a as HTMLInputElement).type !== 'checkbox'));
    };
    const changed = { left: false, right: false };
    if ((force || left !== this.leftHtml) && !typingIn(this.left)) { this.leftHtml = left; this.left.innerHTML = left; changed.left = true; }
    if ((force || right !== this.rightHtml) && !typingIn(this.right)) { this.rightHtml = right; this.right.innerHTML = right; changed.right = true; }
    if (changed.left || changed.right) page?.afterRender?.(this.left, this.right);
  }
}
