import * as THREE from 'three';
import { N, STEP, heightAt, type World } from '../world/tiles';

const ray = new THREE.Raycaster();
const ndc = new THREE.Vector2();

/**
 * The ground point under a screen position, found by marching the camera ray through the height
 * field and then bisecting where it first goes under. Every tile surface lies between TOP and BOTTOM.
 */
export function pickGround(w: World, camera: THREE.Camera, clientX: number, clientY: number, ox = 0, oz = 0): THREE.Vector3 | null {
  ndc.set((clientX / window.innerWidth) * 2 - 1, -(clientY / window.innerHeight) * 2 + 1);
  ray.setFromCamera(ndc, camera);
  const o = ray.ray.origin, d = ray.ray.direction;
  if (d.y > -1e-3) return null;
  // every tile surface lies under the county's highest ground (and the ordinary roof at least)
  const TOP = Math.max(14, (w.peak + 8) * STEP + 1), BOTTOM = -2;
  const tEnd = (BOTTOM - o.y) / d.y;
  const stepT = 0.08 / Math.max(0.05, Math.hypot(d.x, d.z));
  const below = (t: number) => {
    const x = o.x + d.x * t - ox, z = o.z + d.z * t - oz;
    if (x < 0 || z < 0 || x >= N || z >= N) return false;
    return o.y + d.y * t <= heightAt(w, x, z);
  };
  let last = Math.max(0, (TOP - o.y) / d.y);
  for (let t = last; t <= tEnd; t += stepT) {
    if (below(t)) {
      let lo = last, hi = t;
      for (let k = 0; k < 8; k++) {
        const m = (lo + hi) / 2;
        if (below(m)) hi = m; else lo = m;
      }
      return new THREE.Vector3(o.x + d.x * hi - ox, o.y + d.y * hi, o.z + d.z * hi - oz);
    }
    last = t;
  }
  return null;
}
