/** Kinds of place goods appear at or are wanted at: town and port buildings, the ports themselves, and country places. */
export type SiteKind = BuildingKind | 'majorPort' | 'minorPort' | 'cabin' | 'lighthouse' | 'landmark' | 'volcano' | 'saltFlat' | PadKind
  // jet work (docs/rides.html): a stand on any airfield's apron, the same at an international, and a point far out over the horizon
  | 'airport' | 'intl' | 'overseas'
  // submarine work (docs/underwater.html): a place on the seabed, under a dive buoy (world/seabed.ts)
  | SeabedKind;

/**
 * How long this particular consignment will wait, and what the hurry is worth. Every good gets one
 * when it appears: the tighter the window, the better it pays and the faster its value falls once
 * it's aboard.
 */
export type Urgency = 'urgent' | 'timely' | 'standard' | 'relaxed' | 'none';

export const URGENCY: Record<Urgency, { label: string; ttl: number; pay: number; decay: number }> = {
  // decay is the share of the pick-up value lost a second; with the floor at 35% a load bottoms out after
  // about 163 s urgent, 279 s timely, 488 s standard and 975 s relaxed (tripled 17 Sep 2026: it was 54/93/163/325)
  urgent: { label: 'Urgent', ttl: 0.45, pay: 1.8, decay: 0.004 },
  timely: { label: 'Timely', ttl: 0.7, pay: 1.35, decay: 0.00233 },
  standard: { label: 'Standard', ttl: 1, pay: 1, decay: 0.00133 },
  relaxed: { label: 'Relaxed', ttl: 1.7, pay: 0.85, decay: 0.000667 },
  none: { label: 'No limit', ttl: Infinity, pay: 0.7, decay: 0 },
};

/** What each unit of a load is worth to carry, by class: people and parcels pay best per unit. */
export const CLASS_RATE: Record<CargoClass, number> = { people: 12, parcel: 8, freight: 6, bulk: 4, container: 5 };

/**
 * Heavy work pays half as much again (Oct 2026): every freight load, and any load that takes HEAVY_UNITS or
 * more of a hold — once, for a type that is both. cargo.ts valueOf applies it, so the board, missions and
 * town requests all pay it.
 */
export const HEAVY_PAY = 1.5;
export const HEAVY_UNITS = 8;
export const heavyPay = (t: Pick<CargoType, 'cls' | 'units'>): number => (t.cls === 'freight' || t.units >= HEAVY_UNITS ? HEAVY_PAY : 1);

/** The mix of time limits a good gets when its type doesn't ask for something particular. */
export const DEFAULT_URGENCY: Urgency[] = ['urgent', 'timely', 'timely', 'standard', 'standard', 'standard', 'relaxed', 'relaxed', 'none'];

export interface CargoType {
  id: string;
  name: string;
  icon: string;
  color: number;
  cls: CargoClass;          // which holds can take it
  units: number;            // hold space it fills — its quantity and weight
  from: SiteKind[];         // where it turns up
  to: SiteKind[];           // where it's wanted
  base: number;             // the type's own worth, before units, distance and the time limit
  perTile: number;          // ...plus this much per tile of the trip
  ttl: [number, number];    // seconds it waits to be collected, before its time limit scales it
  every: [number, number];  // seconds between new ones turning up somewhere
  max: number;              // most waiting at once
  urgency?: Urgency[];      // the time limits this kind of load comes with
  blurb: string;
  /** Helicopter work: it turns up only while the player flies a helicopter, and only the player sees it or takes it. */
  heli?: boolean;
  /** Jet work: it turns up only while the player flies a jet, at airport stands, and only the player takes it. */
  jet?: boolean;
  /**
   * Submarine work (docs/underwater.html): to or from a place on the seabed, only while the player drives a
   * submarine, and only the player takes it. Goods on the bottom load, and goods for the bottom are set down,
   * only with the sub sounded (gone down to the seabed over the ring).
   */
  sub?: boolean;
  /**
   * Harbour to harbour across the water: only a boat takes it. Ferry passengers and the island post are
   * a boat's bread and butter; a van driving them round by road left the boats with nothing to do.
   */
  sea?: boolean;
  /** Made only by a mission (a rescue's stranded boater): it never turns up on its own, and goes nowhere but where the mission says. */
  missionOnly?: boolean;
  /**
   * The cuts this load belongs to. `veh` names the models the work is really meant for — a prom party
   * wants the limousine, a school trip the omnibus — and it only turns up while such a vehicle is about
   * (the player's, a hired driver's, a rival's or the island's own traffic). `tier` and `style` want one
   * end of the trip in a town of that size, or built in that style. None of them stops another vehicle
   * carrying a load it physically fits: they decide what turns up, and who goes for it first (game/affinity.ts).
   */
  veh?: string[];
  tier?: TownKind[];
  style?: Arch[];
  /**
   * Long-haul work (the user, 28 Oct 2026): worth $5,000–$19,999, bound for a place five or more counties away,
   * put out only by CargoSystem's long-haul spawner (never by the timers or the demand): a jet's at an airport
   * stand, a train's at a station on its line. Gold with a pillar of light over it (game/cargoLook.ts).
   */
  longHaul?: boolean;
  /** Only a train takes it (long-haul station work): nothing on the road carries it off. */
  rail?: boolean;
  /**
   * Ultra-Bulk work (the user, 28 Oct 2026): 50–100 units, for the four biggest holds alone (`rides`, of
   * ULTRA_RIDES), between places one of them loads and unloads at (`from`, `to`). The type's own `from` and `to`
   * stay empty, so nothing that reads those (the timers, the demand, the boats' harbour work, missions, town
   * cards) makes or offers one: CargoSystem's Ultra-Bulk spawner puts them out, only while the player drives a
   * ride of theirs, and only the player takes them. Lime with a black hazard halo (game/cargoLook.ts).
   */
  ultra?: { from: SiteKind[]; to: SiteKind[]; rides: string[] };
  /**
   * A crewed train's beat work (docs/crewtrains.html): station to station along a beat a hired driver runs, put out by
   * CargoSystem's beat stock alone while one does (`from` and `to` the station kinds it runs between). The type's own
   * `from` and `to` stay empty, so nothing else makes or offers one. Named as the station loads they look like, so the
   * crowns and the boards count them with those.
   */
  beat?: { from: SiteKind[]; to: SiteKind[] };
}

