/**
 * Ids that have been renamed, and what they mean now. Until 22 Sep 2026 the railway's travellers and
 * commuters shared their ids with the town's own, so every lookup by id found the railway's and the
 * town's were unreachable; a save, a mission or a request written before then still names the old id.
 */
const OLD_IDS: Record<string, string> = { travellers: 'railTravellers', commuters: 'railCommuters' };

/** A cargo type by its id, following a renamed id to whatever it is called now. */
export function cargoById(id: string | undefined): CargoType | undefined {
  if (!id) return undefined;
  return CARGO.find((c) => c.id === id) ?? CARGO.find((c) => c.id === OLD_IDS[id]);
}
