/**
 * Metric or imperial: how speeds and heights are written (settings). The game counts in km/h and
 * metres; imperial shows mph and feet. The first time, it follows the device's own region — the United
 * States, the United Kingdom, Liberia and Myanmar drive in miles — and after that whatever was chosen.
 */

type UnitSystem = 'metric' | 'imperial';

/** Where the choice is remembered on this device. */
const KEY = 'tinyfleet-units';
/** Regions whose roads are signed in miles an hour. */
const MILES = new Set(['US', 'GB', 'LR', 'MM', 'PR', 'GU', 'VI', 'AS', 'MP', 'BS', 'BZ', 'KY', 'VG', 'FK']);

/** The device's region, from its preferred languages and, failing that, its time zone. */
function guess(): UnitSystem {
  try {
    const langs = navigator.languages?.length ? navigator.languages : [navigator.language];
    for (const l of langs) {
      const region = new Intl.Locale(l).maximize().region;
      if (region) return MILES.has(region) ? 'imperial' : 'metric';
    }
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone ?? '';
    if (/^America\/(New_York|Chicago|Denver|Los_Angeles|Phoenix|Anchorage|Detroit|Indiana|Kentucky|Boise)|^Pacific\/Honolulu|^Europe\/London/.test(tz)) return 'imperial';
  } catch { /* an old browser: metric */ }
  return 'metric';
}

let current: UnitSystem = (() => {
  try {
    const v = localStorage.getItem(KEY);
    if (v === 'metric' || v === 'imperial') return v;
  } catch { /* storage blocked: the device's guess */ }
  return guess();
})();
const listeners: ((u: UnitSystem) => void)[] = [];

export function unitSystem(): UnitSystem { return current; }

export function setUnitSystem(u: UnitSystem): void {
  if (u === current) return;
  current = u;
  try { localStorage.setItem(KEY, u); } catch { /* for this visit only */ }
  for (const f of listeners) f(u);
}

/** Told whenever the choice changes (labels drawn once, like the speedo's unit). */
function onUnitSystem(f: (u: UnitSystem) => void): void { listeners.push(f); }

/** The speed unit's label. */
export const speedUnit = (): string => (current === 'imperial' ? 'mph' : 'km/h');
/** A speed the game counts in km/h, as a whole number in the chosen unit. */
export const speedIn = (kmh: number): number => Math.round(current === 'imperial' ? kmh * 0.621371 : kmh);
/** "44 km/h" or "27 mph". */
export const speedText = (kmh: number): string => `${speedIn(kmh)} ${speedUnit()}`;
/** A height the game counts in metres: "26 m" or "85 ft". */
export const heightText = (m: number): string => (current === 'imperial' ? `${Math.round(m * 3.28084)} ft` : `${Math.round(m)} m`);
/** An altitude the game counts in feet (aviation's own unit): "12,000 ft" or "3,658 m". */
export const altText = (ft: number): string => (current === 'imperial' ? `${Math.round(ft).toLocaleString()} ft` : `${Math.round(ft / 3.28084).toLocaleString()} m`);
