import { esc, money } from './cargoHud';
import { CLASS_LABEL } from './cargoTypes';
import { moodWord, nextRank, rankOf, TEMPER, type Driver, type Licence, type Rank, type Temper } from './drivers';
import { portraitImg } from './crewPortrait';
import type { CargoClass } from './vehicles';

/**
 * A crew member's card (the user, 6 Nov 2026), the same wherever crew is shown (the vehicle pane, the hiring lists,
 * the bench): their portrait (game/crewPortrait.ts), then in rows: who they are (name, rank, mood); what they are
 * (licences, temper and nose, as pills); and their life with the fleet (deliveries, tiles, what they have made you).
 */

const RANK_ICON: Record<Rank, string> = { rookie: '🔰', regular: '⭐', veteran: '🎖️', ace: '🏆' };
const RANK_TIP: Record<Rank, string> = {
  rookie: 'Rookie: new to the job', regular: 'Regular: 25 deliveries or more', veteran: 'Veteran: 100 deliveries or more', ace: 'Ace: 300 deliveries or more · their tows are free',
};
const LICENCE: Record<Licence, [string, string]> = { road: ['🚗', 'Road'], sea: ['⛵', 'Sea'], air: ['✈️', 'Air'], rail: ['🚂', 'Rail'] };
const TEMPER_PILL: Record<Temper, [string, string]> = {
  careful: ['🛡️', 'Half the incidents, a little slower'], steady: ['⚖️', 'Even pace, even luck'], quick: ['⚡', 'Faster, but twice the incidents'],
};
const MOOD_ICON: Record<string, string> = { content: '😄', fine: '🙂', restless: '😟', leaving: '😠' };
const CLASS_ICON: Record<CargoClass, string> = { people: '🧍', parcel: '📦', freight: '🏗️', bulk: '⛏️', container: '🚢' } as Record<CargoClass, string>;

const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
const num = (n: number) => Math.round(n).toLocaleString('en-GB');

export interface CrewCardOpts {
  /** A button or line at the card's end (Hire, Put in…). */
  extra?: string;
  /** Hired: their lifetime stats show; a candidate shows their experience instead. */
  hired?: boolean;
  /** Today's game day, for how long they have been with the fleet. */
  day?: number;
  /** A line of where they are or what they do now. */
  note?: string;
  /** Smaller, for lists. */
  compact?: boolean;
}

/** The card's HTML. */
export function crewCard(d: Driver, o: CrewCardOpts = {}): string {
  const rank = rankOf(d), mood = moodWord(d.mood), next = nextRank(d);
  const r1 = `<div class="cc-r1"><b>${esc(d.name)}</b><span class="cc-pill cc-rank r-${rank}" title="${esc(RANK_TIP[rank])}">${RANK_ICON[rank]} ${cap(rank)}</span>`
    + `<span class="cc-mood m-${mood}" title="Mood: your cut and their work move it">${MOOD_ICON[mood] ?? ''} ${mood}</span></div>`;
  const pills = [
    ...d.licences.map((l) => `<span class="cc-pill cc-lic" title="${LICENCE[l][1]} licence">${LICENCE[l][0]} ${LICENCE[l][1]}</span>`),
    `<span class="cc-pill cc-temper t-${d.temper}" title="${esc(TEMPER_PILL[d.temper][1])}">${TEMPER_PILL[d.temper][0]} ${cap(TEMPER[d.temper].label)}</span>`,
    d.nose ? `<span class="cc-pill cc-nose" title="Takes ${esc(CLASS_LABEL[d.nose])} gladly and finds more of them">${CLASS_ICON[d.nose] ?? '📦'} Nose for ${esc(CLASS_LABEL[d.nose])}</span>` : '',
  ].join('');
  const r2 = `<div class="cc-r2">${pills}</div>`;
  let stats: string[];
  if (o.hired) {
    const days = d.since !== undefined && o.day !== undefined ? Math.max(0, o.day - d.since) : null;
    stats = [
      `<span title="Deliveries made${next ? ` · ${next.left} more to ${next.rank}` : ''}">📦 <b>${num(d.deliveries)}</b> deliveries</span>`,
      d.tiles ? `<span title="Tiles driven for you">🛣️ <b>${num(d.tiles)}</b> tiles</span>` : '',
      `<span title="What their deliveries have paid you${d.earned === undefined ? ' (counted from this update)' : ''}">💰 <b>${money(Math.round(d.earned ?? 0))}</b> for you</span>`,
      `<span title="Their own share, all told">👛 keeps <b>${money(Math.round(d.kept))}</b></span>`,
      d.incidents ? `<span title="Towed after an incident">🛻 <b>${d.incidents}</b> tow${d.incidents === 1 ? '' : 's'}</span>` : '',
      days !== null ? `<span title="Game days with the fleet">📅 <b>${days}</b> day${days === 1 ? '' : 's'} with you</span>` : '',
    ];
  } else {
    stats = [d.deliveries ? `<span title="Experience before joining">📦 <b>${num(d.deliveries)}</b> deliveries behind them</span>` : '<span>New to the job</span>'];
  }
  const nextLine = o.hired && next ? `<span class="cc-next" title="Deliveries still to make for the next rank">${next.left} to ${RANK_ICON[next.rank]} ${next.rank}</span>` : '';
  const r3 = `<div class="cc-r3">${stats.filter(Boolean).join('')}${nextLine}</div>`;
  const note = o.note ? `<div class="cc-note">${o.note}</div>` : '';
  return `<div class="ccard${o.compact ? ' compact' : ''}"><div class="cc-face">${portraitImg(d.name, o.compact ? 38 : 48)}</div><div class="cc-main">${r1}${r2}${r3}${note}</div>${o.extra ? `<div class="cc-act">${o.extra}</div>` : ''}</div>`;
}
