export interface Controls {
  throttle: number; steer: number; lift: number;
  /** Nitrous burning: the share added to top speed (0.25 is +25%). */
  boost?: number;
  /** The handbrake is held (only a car with one fitted answers). */
  handbrake?: boolean;
  /** The game is holding the vehicle still (a card up, a countdown): a train's throttle lever goes to stop. */
  stop?: boolean;
}

/** What the renderer, camera and HUD need from any vehicle, whatever it drives on. */
export interface VehicleState {
  x: number; y: number; z: number; heading: number; v: number;
  pitch: number; roll: number; bob: number; lean: number;
  wheelSpin: number; steerVis: number;
  power: number;          // 0..1, drives propellers and rotors
  blocked: number;        // seconds of "bump" feedback remaining
  trailerHeading: number;
  sailAngle: number;
  surfaceY: number;       // water surface under a moving vehicle (for the wake), else NaN
  /** The strongest collision since main.ts last read it, which clears it. */
  impact?: Impact | null;
  /** 0..1 while grinding along a wall, for the sparks and the rasp. */
  scrape?: number;
  /** The face of the wall it is grinding along, turned back toward the vehicle. */
  contactNx?: number; contactNz?: number;
  /** 0..1 while the tyres are skidding (a drift, a burnout, a hard stop), so any ground takes a mark. */
  skid?: number;
  /** A jet's undercarriage: 1 down, 0 tucked away. */
  gear?: number;
  /** People riding along, for a convertible to show their heads (the driver is always there). */
  riders?: number;
  /** The driver's throttle this frame (-1..1), for a tow crew to mirror. Only the player's car carries it. */
  pedal?: number;
  step(w: World, c: Controls, dt: number): void;
  status(): string;
}

/**
 * A collision, for the camera, the sound, the sparks and the rumble to answer. `hard` is a wall (a
 * building, a railing, the rails); `soft` is something ridden up against (a curb, a slope, deep water,
 * a fence taken too slowly); `break` is a fence knocked flat.
 */
export interface Impact {
  kind: 'hard' | 'soft' | 'break';
  /** 0..1, from the speed into the obstacle. */
  strength: number;
  /** Unit normal out of the obstacle, back toward the vehicle, in tile coordinates. */
  nx: number; nz: number;
  /** Where it touched, in the vehicle's own island's tile coordinates. */
  px: number; pz: number;
  /** Tiles a second into the obstacle's face, where a car measures it: a mission's knock-down asks for so much. */
  into?: number;
  /** A knocked-down fence: its kind, its tile and edge, and which way it fell. */
  fence?: { kind: FenceKind; i: number; d: number; fell: number };
}

/** Keep the stronger of two collisions in the same frame. */
export function reportImpact(s: VehicleState, imp: Impact): void {
  if (!s.impact || imp.strength >= s.impact.strength) s.impact = imp;
}

/** Shared environment the vehicles read. Wind blows toward windHeading. */
export const env = { windHeading: 0.8 };

export type MenuGroup = 'road' | 'water' | 'sky' | 'rail';

/** What a hold can take: people ride in seats, parcels go anywhere, the rest needs a bed, a trailer or a ship. */
export type CargoClass = 'people' | 'parcel' | 'freight' | 'bulk' | 'container';

interface Base {
  id: string;
  name: string;
  color: number;
  group: MenuGroup;
  blurb: string;
  tags: string[];
  hint: string;
  capacity: number;  // cargo units the hold takes
  holds: CargoClass[];
  scale?: number;    // model scale; the sizes a def carries are already multiplied by it
  /** Built oversize: multiplies the model scale and every size that comes with it. Default 1. */
  size?: number;
  /** A soft top that folds away in fine weather (the Sunny): its people loads pay more with it down. */
  convertible?: boolean;
  /** A bus's fare box: a people fare pays this share more for every other people load aboard with it (to +50%). */
  fareBox?: number;
  /** An ambulance's siren: loads aboard lose value this much slower. */
  siren?: number;
  /** A dump truck's tipper: bulk it delivers pays this share more. */
  tipper?: number;
  /** A postal van's round: parcels it delivers pay this share more, and a little more again for every other parcel aboard. */
  postal?: number;
  /** A limousine's VIPs: people fares pay this share more, and every hard knock takes a tenth off them. */
  vip?: number;
  /** A tow truck's hook: while the player owns one, their hired drivers' tow bills are cut by this share. */
  wrecker?: number;
  /** A bulldozer: while you own one (out of the garage), clearing anything with the bulldoze tool (X) costs this share less. */
  dozer?: number;
  /** The licence a driver needs, when it isn't the one its kind implies (a hovercraft drives like a car but is a sea craft). */
  licence?: 'road' | 'sea' | 'air';
  // ---- set by workshop parts (game/parts.ts) on a unit's own definition ----
  /** How the parts look: the mesh builder reads it. */
  looks?: Looks;
  /** How much of a knock reaches the camera, the pad and the body (bull bar); default 1. */
  knock?: number;
  /** A nitrous bottle or two, fired with Shift. */
  nitrous?: NitrousStats;
  /** A horn's tier, sounded with K. */
  horn?: number;
  /** The towed banner a Barnstormer flies (0.7.0, game/parts.ts `banner`): 1 the fleet's name, 2 "Visit" a town, 3 lit. */
  banner?: number;
  /** A rival firm's accent (docs/rivals.html): a board on the roof, or a pennant, in that colour. */
  livery?: number;
  /**
   * A hot air balloon's envelope (render/vehicleMeshes.ts `balloon`): `p` its pattern (BALLOON_PATTERNS), `c` its colours.
   * Without one it is the Sunrise's own: its colour and yellow in stripes.
   */
  envelope?: { p: number; c: number[] };
  /** A paintjob (docs/factions.html, game/factions/paintjobs.ts): a faction's house paint, or one the player earned. */
  job?: string;
  /**
   * The Passport's treats (game/passportRewards.ts, set by the unit's parts): `topper` the topper on the roof (game/toppers.ts, `wonder` the Wonder Ball),
   * `lantern` coloured headlamps and a roof searchlight, `tune` a treat horn on K, `gild` 1 gold trim / 2 gold all over.
   */
  topper?: string;
  lantern?: number;
  tune?: 'fanfare' | 'confetti';
  gild?: number;
  /**
   * The factions' vehicles (docs/factions.html). `faction`: whose it is. `bonus`: these kinds of load pay
   * this share more in it (a Mixer's cement, a Mail Truck's parcels). `pursuit`: a siren on K that has the
   * traffic ahead pull over (its reach in tiles). `stealth`: how much of a police cone's reach sees it.
   * `beam`: a tractor beam on Shift (the Saucer). `mast`: a broadcast mast that goes up at a live event.
   * `trawl`: nets hauled at a shoal, this many units a haul. `beach`: it lands on any beach (the Pelican).
   * `crane`: parked by a building site, the site goes up faster. `sights`: fares pay more for every sight passed.
   */
  faction?: string;
  bonus?: { ids: string[]; share: number; label: string };
  pursuit?: number;
  stealth?: number;
  beam?: boolean;
  mast?: boolean;
  trawl?: number;
  beach?: boolean;
  crane?: boolean;
  sights?: number;
}

/** What a unit's parts look like: the tier fitted in each slot that shows, and its paint. */
export interface Looks {
  key: string;
  paint: number; colour: number; accent: number;
  engine: number; tyres: number; brakes: number; suspension: number; rack: number;
  bullbar: number; nitrous: number; hull: number; wings: number;
}

/** A bottle: how many, how long a burst lasts, the top-speed and acceleration multipliers while it burns. */
interface NitrousStats { bottles: number; secs: number; mul: number; acc: number }

export interface LandDef extends Base, CarStats { kind: 'land' }

export interface WaterDef extends Base {
  kind: 'water';
  topSpeed: number; accel: number; brake: number; coast: number; reverseCap: number;
  steerRate: number;
  turnRef: number;   // speed (tiles/s) for full rudder authority
  yawLag: number;    // seconds for the turn rate to catch up with the helm
  grip: number;      // how quickly sideways drift dies away (1/s)
  minDepth: number;  // shallowest water it floats in, in steps
  halfLen: number; halfWid: number;
  wave: number;      // bob amplitude
  planing: number;   // bow lift at full speed (rad)
  sail?: boolean;
  /** An auxiliary outboard on a sailboat: the speed (tiles/s) it makes whatever the wind. */
  motor?: number;
  /**
   * A submarine (docs/storychains.html): Shift takes it under and Space brings it up. `depth` is how far
   * below its surfaced line the hull settles (model units, scaled with the rest), leaving the sail or
   * the hatch cutting the waves; `speed` multiplies the top speed while dived; `need` is the water (in
   * height steps) it needs under it to go down.
   */
  dive?: { depth: number; speed: number; need: number };
}

export interface AirDef extends Base {
  kind: 'air';
  topSpeed: number; minSpeed: number; accel: number; brake: number; coast: number; reverseCap: number;
  steerRate: number; yawLag: number;
  bank: number;          // roll into turns (rad)
  bankToTurn?: boolean;  // planes turn by banking
  minClear: number; maxClear: number; cruiseClear: number; // height above ground
  climbRate: number;
  floor: number;         // lowest the model may sit above the ground
  bobAmp: number; bobFreq: number;
  tilt: number;          // nose-down pitch at full speed (helicopter)
  /** A rotorcraft: it can put down on a helipad, and only it is offered helicopter work (docs: README, Helipads). */
  rotor?: boolean;
  /** A jet (docs/rides.html): it sits on the ground at an airfield, takes off down a runway and lands on one. */
  jet?: JetStats;
  /**
   * A plane that is not a jet but still lands on runways (the Barnstormer): the same wheels and landing
   * aid as a jet, without being one for jet cargo, jet sound, the jet rating or delivery to a stand.
   */
  gear?: JetStats;
  halfLen: number; halfWid: number;
}

/**
 * How a jet behaves on the ground. `rotate` is the speed (tiles/s) it lifts off at, `taxi` its top speed
 * on the apron, `approach` the speed the landing aid slows it to, and `runway` the shortest usable
 * runway (threshold to threshold, in tiles) it fits.
 */
export interface JetStats { rotate: number; taxi: number; groundAccel: number; groundBrake: number; approach: number; runway: number }

/** A train you can buy: one of the six sets (seven from 0.7.0), driven along whatever line it is put on. */
interface RailDef extends Base {
  kind: 'rail';
  set: string;
  /** The cog locomotive: a rack railway's only, held on its cog up the grade (game/trains.ts). */
  rack?: boolean;
  topSpeed: number; accel: number; brake: number; coast: number; reverseCap: number; weight: number;
  /** Half the consist's length, and a car's half-width. */
  halfLen: number; halfWid: number;
}

export type VehicleDef = LandDef | WaterDef | AirDef | RailDef;

export function halfSize(d: VehicleDef): [number, number] {
  if (d.kind === 'land') return [d.halfLen ?? 0.45, d.halfWid ?? 0.3];
  return [d.halfLen, d.halfWid];
}

const FLY_HINT = 'Space climb · Shift descend';
const JET_HINT = 'W down a runway to take off · line up with one and hold Shift to land · loads only on an apron';

/** Road vehicles are modelled smaller still, so one fits a single lane of a two-lane road. */
export const LAND_SCALE = 0.6;
/** Every vehicle, ridden or CPU-driven, is modelled at this scale (on top of LAND_SCALE for road vehicles). */
export const VEHICLE_SCALE = 0.5;

/** Speed into an obstacle (tiles/s) that makes a full-strength knock: about a quick car's top speed, square on. */
export const FULL_HIT = 3.25;
/** Slower than this into an obstacle is a touch, not a knock: no jolt, no sound. */
export const MIN_HIT = 0.5;

/**
 * Scale a vehicle's body, and every size the simulation reads from it (its hitbox), down. A def with
 * its own `size` (the blimp, the container ship) is built that many times bigger, hitbox and all.
 */
function scaled(d: VehicleDef): VehicleDef {
  const big = d.size ?? 1;
  if (d.kind === 'land') {
    const s = LAND_SCALE * VEHICLE_SCALE * big;
    return {
      ...d,
      scale: s,
      halfLen: (d.halfLen ?? 0.45) * s,
      halfWid: (d.halfWid ?? 0.3) * s,
      draft: d.draft === undefined ? undefined : d.draft * s,
      trailer: d.trailer ? { hitch: d.trailer.hitch * s, length: d.trailer.length * s } : undefined,
    };
  }
  if (d.kind === 'rail') return d;
  const s = VEHICLE_SCALE * big;
  if (d.kind === 'water') {
    return {
      ...d, scale: s, halfLen: d.halfLen * s, halfWid: d.halfWid * s, wave: d.wave * s,
      dive: d.dive ? { ...d.dive, depth: d.dive.depth * s } : undefined,
    };
  }
  return { ...d, scale: s, halfLen: d.halfLen * s, halfWid: d.halfWid * s, floor: d.floor * s, bobAmp: d.bobAmp * s };
}

