/** The consist's length in tiles, freight wagons taken at a typical length. */
function setLength(set: TrainSet): number {
  let len = 0;
  set.cars.forEach((id, k) => { len += (id === '*' ? 1.1 : CARS[id]?.length ?? 1) + (k ? COUPLING_GAP : 0); });
  return len;
}

/**
 * The six trains in the Rail tab. A train accelerates at a third of a car's rate and brakes at half, so a
 * stop takes planning; grades pull on it through its weight like on a car, and a freight is heavy.
 */
export const RAIL_VEHICLES: RailDef[] = SETS.map((set) => ({
  kind: 'rail', id: set.id, set: set.id, group: 'rail', name: set.name,
  color: set.era === 'steam' ? 0x2f3a33 : set.era === 'streamline' ? 0xc9ced4 : 0xf4f2ec,
  blurb: set.blurb, tags: set.tags.filter((t) => t !== 'rail'),
  hint: 'W/S move the throttle, which stays set: S through stop into reverse · A/D take the left or right branch at a turnout',
  capacity: set.capacity, holds: [...set.holds],
  topSpeed: set.topSpeed, accel: set.accel, brake: set.accel * 1.6, coast: 0.08, reverseCap: 0.8,
  weight: set.freight ? 1.1 : 0.7,
  halfLen: setLength(set) / 2, halfWid: 0.16,
  ...(set.rack ? { rack: true, hint: 'W/S move the throttle, which stays set: S through stop into reverse · on the rack railway only' } : {}),
}));

/** Every vehicle there is, trains included, for the menu and for finding a ride by its id. */
export const ALL_VEHICLES: VehicleDef[] = [...VEHICLES, ...RAIL_VEHICLES];

/** Is this a jet: something that lands only on runways and loads only on an airport's apron? */
export const isJet = (d: VehicleDef | null | undefined): boolean => !!d && d.kind === 'air' && !!d.jet;
/** A plane with wheels for a runway: every jet, and the Barnstormer. */
export const wheelsOf = (d: VehicleDef | null | undefined): JetStats | null => (d && d.kind === 'air' ? d.jet ?? d.gear ?? null : null);

/**
 * Can this model ever load? A plane that can't stop can't; a jet stops on the ground, and from 0.7.0 a hired
 * pilot flies it on the air service (game/jetPilots.ts); before that only the player flies one.
 */
export function canLoad(d: VehicleDef): boolean {
  if (d.kind === 'air' && d.jet) return NEXT_WORLD;
  return !(d.kind === 'air' && d.minSpeed > 0);
}

/** Is this a helicopter: something that can put down on a helipad and take helicopter work? */
export const isHelicopter = (d: VehicleDef | null | undefined): boolean => !!d && d.kind === 'air' && !!(d as AirDef).rotor;

/** A submarine: it can dive (game/boat.ts). */
const isSub = (d: VehicleDef | null | undefined): boolean => !!d && d.kind === 'water' && !!d.dive;
