import * as THREE from 'three';
import { N, type World } from '../world/tiles';
import { PATROL, halfSize, type VehicleDef } from './vehicles';
import type { Agent, Traffic } from './traffic';
import { CONE, beatOf, castCone, coneHas, patrolsFor, type Beat } from './policeBeat';
import { CONTACTS_FROM, isNight } from './nightRules';
import { rand } from '../util/math';

/**
 * The police (docs/smuggling.html). From dusk to dawn every town near the player puts patrol cars on
 * its beat: out of the station at 18:30, round the square, the ways in and the busiest junctions, a
 * stop now and then to look both ways, and home again at six. More come out while the player carries
 * contraband, and a highway unit drives each stretch of open road on the run's route. Each car casts
 * its cone of sight every frame; while the player is carrying, a car inside a lit cone is seen, and the
 * run's owner (game/smuggling.ts) is told. With a clean hold the police are just cars.
 *
 * The cars themselves are traffic agents (game/traffic.ts, `police`): they drive, give way and route
 * like anyone else. This decides where each one goes next, which way it looks, and what it sees.
 */

/** Towns whose middle is within this many tiles of the player have their patrols out. */
const RANGE = 170;
/** Patrols further than this from the player when their town drops out of range are taken off at once. */
const QUIET = 40;
/** Cones are cast for cars within this many tiles of the player, nearest first, at most MAX_CAST of them. */
const CAST_RANGE = 26, MAX_CAST = 16;
/** A patrol car that stops at a beat's stop looks round for this long, this often. */
const PAUSE: [number, number] = [4, 8];
const PAUSE_CHANCE = 0.4;
/** A checkpoint stands at the busiest way in for three game hours (75 s), then does a round. */
const CHECK_SECONDS = 75;
/** How far a stopped car's gaze swings either side, and how fast. */
const SWEEP = 0.7, SWEEP_RATE = 1.3, CHECK_RATE = 0.5;
/** A fresh car on a loaded save or a town coming into range starts at least this far from the player. */
const SPAWN_CLEAR = 14;
/** A stretch of open road on the run's route at least this long gets a highway unit; at most MAX_HIGHWAY. */
const HIGHWAY_MIN = 24, MAX_HIGHWAY = 2;
/** After a bust the cars stay put this long before going back to their beats. */
const HOLD = 10;
/** How long a cleared circle (a run just taken) keeps fresh cars out of it. */
const CLEAR_SECONDS = 25;

type Mode = 'drive' | 'pause' | 'check' | 'home' | 'chase' | 'hold' | 'converge';

export interface Patrol {
  agent: Agent;
  traffic: Traffic;
  /** The cell whose town this car belongs to (its beat's frame), and the town. */
  cell: World;
  town: number;
  key: string;
  beat: Beat | null;
  /** Its own order through the beat's stops, and where it is in it. */
  loop: number[];
  k: number;
  mode: Mode;
  timer: number;
  sweep: number;
  /** Which way the cone points, smoothed. */
  dir: number;
  /** Out only because the player is carrying. */
  extra: boolean;
  /** Stands the checkpoint at its town's busiest way in. */
  checkpoint: boolean;
  /** A highway unit: back and forth between two points in world tiles. */
  highway: { a: { x: number; z: number }; b: { x: number; z: number }; toB: boolean } | null;
  /** The cone, cast this frame (or not): each ray's length, and where it starts in the agent's frame. */
  lens: Float32Array;
  cast: boolean;
  ox: number; oz: number; oy: number;
  /** The player is just outside this cone. */
  warn: boolean;
  siren: boolean;
  bars: THREE.MeshStandardMaterial[];
}

interface PoliceHost {
  /** Every cell whose traffic is running, with its traffic. */
  alive(): [World, Traffic][];
  /** The player in world tiles, and what they drive; null when there is nobody. */
  player(): { x: number; y: number; z: number; heading: number; v: number; def: VehicleDef } | null;
  /** The hour of the day. */
  hour(): number;
  /** Is the player carrying contraband? */
  carrying(): boolean;
  /** The run's road route in world tiles, for the highway units, or null. */
  route(): { x: number; z: number }[] | null;
}

const wrap = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));

export class Police {
  patrols: Patrol[] = [];
  /** Console: police on duty at any hour. */
  forced = false;
  /** Console: nobody sees anything. */
  ghost = false;
  /** Told when a car sees the player carrying. */
  onSpotted: (p: Patrol) => void = () => {};
  /** Told each time the player comes within the warning band of a cone while carrying. */
  onNearMiss: () => void = () => {};
  /** Set by the run's owner while a bust plays out: nobody else looks. */
  busy = false;
  private manageT = 0;
  private time = 0;
  private near = false;
  private routeKey = '';
  /** A circle nobody is put out inside while it lasts: where a run was just taken (clearAround). */
  private cleared: { x: number; z: number; r: number; until: number } | null = null;

  constructor(private host: PoliceHost) {}

  /** Everything off the road (a new world, the title). */
  clear(): void {
    for (const p of this.patrols) p.traffic.dropPolice(p.agent);
    this.patrols = [];
    this.busy = false;
    this.routeKey = '';
    this.cleared = null;
  }

  /**
   * A run has just been taken (game/smuggling.ts): every patrol car within `r` tiles of (x, z) goes off
   * duty on the spot, and no fresh one is put out inside that circle for a while. The player gets a mile
   * of their own before the night's first cone finds them.
   */
  clearAround(x: number, z: number, r: number): void {
    for (const p of [...this.patrols]) if (this.distTo(p, x, z) <= r) this.drop(p);
    this.cleared = { x, z, r, until: this.time + CLEAR_SECONDS };
  }

  /** Is (x, z), in world tiles, inside a live cleared circle? */
  private barred(x: number, z: number): boolean {
    const c = this.cleared;
    if (!c) return false;
    if (this.time >= c.until) { this.cleared = null; return false; }
    return Math.hypot(x - c.x, z - c.z) < c.r;
  }

  get onDuty(): boolean { return this.forced || isNight(this.host.hour()); }

  /** One frame. `dt` is 0 while the world is paused. */
  update(dt: number): void {
    // a car whose traffic has gone (its island out of range) has gone with it
    this.patrols = this.patrols.filter((p) => p.traffic.agents.includes(p.agent));
    if (dt <= 0) return;
    this.time += dt;
    this.manageT -= dt;
    if (this.manageT <= 0) { this.manageT = 1; this.manage(); }
    const pl = this.host.player();
    for (const p of [...this.patrols]) this.drive(p, dt);
    this.look(dt, pl);
    this.flash();
  }

  // ---- who is out ----

  private manage(): void {
    const pl = this.host.player();
    if (!pl) return;
    const duty = this.onDuty, carrying = this.host.carrying();
    const want = new Map<string, { w: World; t: World['towns'][number]; traffic: Traffic; n: number }>();
    if (duty) {
      for (const [w, traffic] of this.host.alive()) {
        for (const t of w.towns) {
          const d = Math.hypot(w.ox + t.x0 + t.size / 2 - pl.x, w.oz + t.z0 + t.size / 2 - pl.z);
          if (d > RANGE) continue;
          want.set(`${w.cx},${w.cz}#${t.id}`, { w, t, traffic, n: patrolsFor(t, carrying) });
        }
      }
    }
    for (const p of [...this.patrols]) {
      if (p.mode === 'chase' || p.mode === 'hold' || p.mode === 'converge' || p.mode === 'home') continue;
      const keep = p.highway ? duty && carrying : want.has(p.key);
      if (keep) continue;
      if (this.distTo(p, pl.x, pl.z) > QUIET) this.drop(p);
      else this.sendHome(p);
    }
    for (const [key, { w, t, traffic, n }] of want) {
      const mine = this.patrols.filter((p) => p.key === key && p.mode !== 'home');
      if (mine.length > n) {
        // the extras go home first
        const extras = mine.filter((p) => p.mode !== 'chase' && p.mode !== 'hold' && p.mode !== 'converge').sort((a, b) => Number(b.extra) - Number(a.extra));
        for (const p of extras.slice(0, mine.length - n)) this.sendHome(p);
        continue;
      }
      const beat = beatOf(w, t);
      if (!beat) continue;
      for (let k = mine.length; k < Math.min(n, mine.length + 2); k++) {
        this.spawn(w, t.id, key, beat, traffic, k >= patrolsFor(t, false), k === 0 && t.buildings.length >= 60 && beat.checkpoint >= 0, pl);
      }
    }
    this.highways(duty && carrying, pl);
  }

  private spawn(w: World, town: number, key: string, beat: Beat, traffic: Traffic, extra: boolean, checkpoint: boolean, pl: { x: number; z: number }): void {
    if (traffic.world !== w) return;
    const hour = this.host.hour();
    const loop = beat.stops.map((_, k) => k).sort(() => Math.random() - 0.5);
    if (checkpoint) { loop.splice(loop.indexOf(beat.checkpoint), 1); loop.unshift(beat.checkpoint); }
    // at dusk they roll out of the station; any other time (a save loaded, a town come into range) they
    // are already about, somewhere along the beat and never on top of the player
    const dusk = hour >= CONTACTS_FROM && hour < CONTACTS_FROM + 1;
    let at = beat.station;
    if (!dusk || extra) {
      const far = beat.stops.filter((s) => Math.hypot(w.ox + s.x - pl.x, w.oz + s.z - pl.z) >= SPAWN_CLEAR && !this.barred(w.ox + s.x, w.oz + s.z));
      const pool = far.length ? far : [...beat.stops].sort((a, b) => Math.hypot(w.ox + b.x - pl.x, w.oz + b.z - pl.z) - Math.hypot(w.ox + a.x - pl.x, w.oz + a.z - pl.z)).slice(0, 1);
      at = pool[Math.floor(Math.random() * pool.length)];
    }
    // a run has just been taken here: this beat waits until the circle has run out
    if (this.barred(w.ox + at.x, w.oz + at.z)) return;
    const next = beat.stops[loop[0]] === at ? beat.stops[loop[1 % loop.length]] : beat.stops[loop[0]];
    const heading = Math.atan2(next.x - at.x, next.z - at.z);
    const agent = traffic.launchPolice(PATROL, at.x, at.z, heading);
    if (!agent) return;
    const p: Patrol = {
      agent, traffic, cell: w, town, key, beat, loop, k: -1, mode: 'drive', timer: 0, sweep: Math.random() * 6, dir: heading,
      extra, checkpoint, highway: null, lens: new Float32Array(CONE.rays), cast: false, ox: 0, oz: 0, oy: 0, warn: false, siren: false,
      bars: barsOf(agent),
    };
    this.patrols.push(p);
    if (!this.nextStop(p)) this.drop(p);
  }

  /** While the player carries: a unit on each long stretch of open road the run's route takes. */
  private highways(on: boolean, pl: { x: number; z: number }): void {
    const route = on ? this.host.route() : null;
    const key = route ? `${Math.round(route[0].x)},${Math.round(route[0].z)}:${route.length}` : '';
    if (key === this.routeKey) return;
    this.routeKey = key;
    for (const p of this.patrols.filter((q) => q.highway && q.mode !== 'chase' && q.mode !== 'hold')) this.sendHome(p);
    if (!route) return;
    // runs of the route outside every town
    const stretches: { x: number; z: number }[][] = [];
    let cur: { x: number; z: number }[] = [];
    const cells = new Map(this.host.alive().map(([w, t]) => [`${w.cx},${w.cz}`, { w, t }]));
    for (const pt of route) {
      const cx = Math.floor(pt.x / N), cz = Math.floor(pt.z / N);
      const c = cells.get(`${cx},${cz}`);
      const lx = Math.floor(pt.x - cx * N), lz = Math.floor(pt.z - cz * N);
      const open = !!c && c.w.townId[lz * N + lx] < 0 && c.w.road[lz * N + lx] > 0;
      if (open) cur.push(pt);
      else { if (cur.length) stretches.push(cur); cur = []; }
    }
    if (cur.length) stretches.push(cur);
    const long = stretches.filter((s) => s.length >= HIGHWAY_MIN).sort((a, b) => b.length - a.length).slice(0, MAX_HIGHWAY);
    let missed = false;
    for (const s of long) {
      const a = s[4], b = s[s.length - 5];
      // start at whichever end is further from the player, heading along the road
      const [from, to] = Math.hypot(a.x - pl.x, a.z - pl.z) > Math.hypot(b.x - pl.x, b.z - pl.z) ? [a, b] : [b, a];
      if (this.barred(from.x, from.z)) { missed = true; continue; }
      const cx = Math.floor(from.x / N), cz = Math.floor(from.z / N);
      const c = cells.get(`${cx},${cz}`);
      if (!c || c.t.world !== c.w) continue;
      const next = s[s.indexOf(from) + (from === a ? 1 : -1)] ?? to;
      const agent = c.t.launchPolice(PATROL, from.x - c.w.ox, from.z - c.w.oz, Math.atan2(next.x - from.x, next.z - from.z));
      if (!agent) continue;
      const p: Patrol = {
        agent, traffic: c.t, cell: c.w, town: -1, key: 'highway', beat: null, loop: [], k: 0, mode: 'drive', timer: 0, sweep: 0,
        dir: agent.state.heading, extra: true, checkpoint: false, highway: { a: from, b: to, toB: true }, lens: new Float32Array(CONE.rays),
        cast: false, ox: 0, oz: 0, oy: 0, warn: false, siren: false, bars: barsOf(agent),
      };
      this.patrols.push(p);
      if (!this.nextStop(p)) this.drop(p);
    }
    // a unit kept out by the cleared circle is tried again on the next round
    if (missed) this.routeKey = '';
  }

  private drop(p: Patrol): void {
    p.traffic.dropPolice(p.agent);
    this.patrols = this.patrols.filter((q) => q !== p);
  }

  /** Back to the station, to be taken off on arrival; straight off if there is no way there. */
  private sendHome(p: Patrol): void {
    p.mode = 'home';
    p.siren = false;
    p.agent.chase = null;
    const st = p.beat?.station;
    if (!st || !p.traffic.driveOwned(p.agent, st.x + p.cell.ox - p.agent.w.ox, st.z + p.cell.oz - p.agent.w.oz)) this.drop(p);
  }

  private distTo(p: Patrol, x: number, z: number): number {
    return Math.hypot(p.agent.w.ox + p.agent.state.x - x, p.agent.w.oz + p.agent.state.z - z);
  }

  // ---- where each goes ----

  /** On to the next stop of its loop (or the other end of its road); false when none can be reached. */
  private nextStop(p: Patrol): boolean {
    const a = p.agent;
    if (p.highway) {
      const h = p.highway;
      const to = h.toB ? h.b : h.a;
      h.toB = !h.toB;
      return p.traffic.driveOwned(a, to.x - a.w.ox, to.z - a.w.oz);
    }
    const beat = p.beat!;
    for (let tries = 0; tries < p.loop.length; tries++) {
      p.k = (p.k + 1) % p.loop.length;
      const s = beat.stops[p.loop[p.k]];
      const x = s.x + p.cell.ox - a.w.ox, z = s.z + p.cell.oz - a.w.oz;
      if (Math.hypot(x - a.state.x, z - a.state.z) < 1.5) continue;
      if (p.traffic.driveOwned(a, x, z)) return true;
    }
    return false;
  }

  private drive(p: Patrol, dt: number): void {
    const a = p.agent;
    switch (p.mode) {
      case 'drive':
        if (a.phase !== 'parked') return;
        // arrived at a stop: stand the checkpoint, look round a while, or drive on
        if (p.checkpoint && p.beat && p.loop[p.k] === p.beat.checkpoint) { p.mode = 'check'; p.timer = CHECK_SECONDS; return; }
        if (!p.highway && Math.random() < PAUSE_CHANCE) { p.mode = 'pause'; p.timer = rand(PAUSE[0], PAUSE[1]); return; }
        if (!this.nextStop(p)) this.drop(p);
        return;
      case 'pause':
      case 'check':
        p.sweep += dt * (p.mode === 'check' ? CHECK_RATE : SWEEP_RATE);
        p.timer -= dt;
        if (p.timer <= 0) { p.mode = 'drive'; if (!this.nextStop(p)) this.drop(p); }
        return;
      case 'home':
        if (a.phase === 'parked') this.drop(p);
        return;
      case 'hold':
        p.timer -= dt;
        if (p.timer <= 0) { p.siren = false; p.mode = 'drive'; a.chase = null; if (!this.nextStop(p)) this.drop(p); }
        return;
      default:
        return;
    }
  }

  // ---- what each sees ----

  private look(dt: number, pl: { x: number; y: number; z: number; heading: number; def: VehicleDef } | null): void {
    for (const p of this.patrols) { p.cast = false; p.warn = false; }
    if (!pl) return;
    const near = this.patrols
      .map((p) => ({ p, d: this.distTo(p, pl.x, pl.z) }))
      .filter((e) => e.d < CAST_RANGE)
      .sort((a, b) => a.d - b.d)
      .slice(0, MAX_CAST);
    const carrying = this.host.carrying() && !this.ghost && !this.busy;
    const [hl, hw] = halfSize(pl.def);
    const fx = Math.sin(pl.heading), fz = Math.cos(pl.heading);
    // the player's four corners and middle, in world tiles
    const pts = [[0, 0], [hl, hw], [hl, -hw], [-hl, hw], [-hl, -hw]].map(([f, s]) => ({ x: pl.x + fx * f + fz * s, z: pl.z + fz * f - fx * s }));
    let anyNear = false;
    for (const { p } of near) {
      const a = p.agent, s = a.state;
      const [ahl] = halfSize(a.def);
      let want = s.heading;
      if (p.mode === 'pause' || p.mode === 'check') want = s.heading + Math.sin(p.sweep) * SWEEP;
      else if (a.phase === 'travel' && a.aimX !== undefined && a.aimZ !== undefined && Math.hypot(a.aimX - s.x, a.aimZ - s.z) > 0.3) want = Math.atan2(a.aimX - s.x, a.aimZ - s.z);
      p.dir += wrap(want - p.dir) * Math.min(1, dt * 8);
      p.ox = s.x + Math.sin(s.heading) * ahl;
      p.oz = s.z + Math.cos(s.heading) * ahl;
      p.oy = s.y + 0.3;
      castCone(a.w, p.ox, p.oz, p.oy, p.dir, p.lens);
      p.cast = true;
      if (!carrying) continue;
      let seen = false, close = false;
      // a Family car is harder to see (docs/factions.html): its stealth shrinks the reach of the cone that tests it
      const stealth = pl.def.stealth ?? 1;
      const cone = stealth === 1 ? CONE : { ...CONE, shrink: CONE.shrink * stealth };
      for (const q of pts) {
        const lx = q.x - a.w.ox, lz = q.z - a.w.oz;
        const d = Math.hypot(lx - p.ox, lz - p.oz);
        // another deck: under a flyover, in a tunnel, on a bridge overhead
        if (Math.abs(pl.y - s.y) > 1 + 0.2 * d) continue;
        const r = coneHas(p.lens, p.ox, p.oz, p.dir, lx, lz, cone);
        if (r === 'in') { seen = true; break; }
        if (r === 'near') close = true;
      }
      if (seen) { this.onSpotted(p); return; }
      if (close) { p.warn = true; anyNear = true; }
    }
    if (anyNear && !this.near) this.onNearMiss();
    this.near = anyNear;
  }

  // ---- the bust ----

  /** This car has seen the player: sirens on, and every car within 12 tiles turns its lights on and comes over. */
  chase(p: Patrol, at: { x: number; z: number }): void {
    p.mode = 'chase';
    p.siren = true;
    for (const q of this.patrols) {
      if (q === p || q.mode === 'chase') continue;
      if (this.distTo(q, at.x, at.z) > 12) continue;
      q.mode = 'converge';
      q.siren = true;
      q.traffic.driveOwned(q.agent, at.x - q.agent.w.ox, at.z - q.agent.w.oz);
    }
  }

  /** Where the chasing car is headed, in world tiles, and whether to stop there. */
  chaseTo(p: Patrol, x: number, z: number, stop: boolean): void {
    p.agent.chase = { x: x - p.agent.w.ox, z: z - p.agent.w.oz, stop };
  }

  /** It's over: everyone involved stays put a while, then goes back to work. */
  release(): void {
    for (const p of this.patrols) {
      if (p.mode !== 'chase' && p.mode !== 'converge') continue;
      p.agent.chase = { x: p.agent.state.x, z: p.agent.state.z, stop: true };
      p.mode = 'hold';
      p.timer = HOLD;
      p.siren = false;
    }
  }

  /** How loud the nearest siren is from (x, z) in world tiles: 1 alongside, 0 beyond 40 tiles. */
  sirenLevel(x: number, z: number): number {
    let best = 0;
    for (const p of this.patrols) if (p.siren) best = Math.max(best, 1 - Math.min(1, this.distTo(p, x, z) / 40));
    return best;
  }

  /** The lightbars: steady and dim on patrol, flashing red and blue with the siren on. */
  private flash(): void {
    const on = Math.sin(this.time * 14) > 0;
    for (const p of this.patrols) {
      for (const m of p.bars) {
        const red = m.userData.lightbar === 'red';
        m.emissiveIntensity = p.siren ? ((red === on) ? 4 : 0.05) : 0.5;
      }
    }
  }

  /** Console: one line per car. */
  lines(): string[] {
    const pl = this.host.player();
    return this.patrols.map((p) => `${p.key} ${p.mode}${p.extra ? ' (extra)' : ''}${p.checkpoint ? ' (checkpoint)' : ''}${pl ? ` · ${Math.round(this.distTo(p, pl.x, pl.z))} tiles` : ''}`);
  }
}

/** The lightbar's two halves on a patrol car's mesh. */
function barsOf(a: Agent): THREE.MeshStandardMaterial[] {
  const out: THREE.MeshStandardMaterial[] = [];
  a.mesh.holder.traverse((o) => {
    const m = (o as THREE.Mesh).material as THREE.MeshStandardMaterial | undefined;
    if (m && m.userData?.lightbar && !out.includes(m)) out.push(m);
  });
  return out;
}
