import * as THREE from 'three';
import { hex, scale, type RGB } from '../../world/biomes';
import type { Sched } from '../nightLights';
import { DARK, WHITE, type Kit, type P3 } from './kit';

/**
 * Roller coasters that run: a closed track laid as a smooth spline through control points, banked into
 * its turns and turned over through its loops, and a train that goes round it under gravity. The chain
 * hauls it up the lift hill, it falls and coasts on what it has, friction and the air take a little off,
 * the brake run slows it and it stops in the station to load before the tyres push it out again.
 *
 * Distances are in tiles and times in seconds of real time (the frame loop's dt).
 */

/**
 * What a stretch of track does to the train: Brake is a block of drive tyres, which slow a fast train and
 * push a slow one; Trim is a set of fins that only shave off speed, ahead of a turn too tight to take flat out.
 */
export const enum Sec { Free = 0, Lift = 1, Brake = 2, Station = 3, Trim = 4 }

/** A control point: where the track passes, and what the track does from here to the next point. */
export interface CP {
  p: P3;
  sec?: Sec;
  /** Through a loop: the up of the track points at the loop's centre line, which runs along `axis` through `c`. */
  loop?: { c: P3; axis: 'x' | 'z' };
}

/** Gravity, tiles/s²: a little under real life at this scale, so the rides read at a glance. */
export const G = 3.2;
/** Rolling friction (as a share of G) and air drag (per unit of speed squared). */
const MU = 0.012, DRAG = 0.018;
/** Speeds the machinery holds: the chain, the station tyres, the brake run. */
const LIFT_V = 0.5, LAUNCH_V = 0.7, BRAKE_V = 0.75, CREEP_V = 0.35, TRIM_V = 2.2;
/** Arc length between samples. */
const H = 0.04;

export interface Track {
  len: number;
  n: number;
  pos: Float32Array;
  tan: Float32Array;
  up: Float32Array;
  sec: Uint8Array;
  /** Where the front car stops in the station, as arc length. */
  stop: number;
  /** How far the station runs before the stop mark. */
  platform: number;
  /** Highest point of the track. */
  top: number;
}

type V = [number, number, number];
const sub = (a: V, b: V): V => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const dot = (a: V, b: V) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const norm = (a: V): V => { const l = Math.hypot(a[0], a[1], a[2]) || 1; return [a[0] / l, a[1] / l, a[2] / l]; };
const cross = (a: V, b: V): V => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];

/** Centripetal Catmull–Rom between p1 and p2. */
function catmull(p0: V, p1: V, p2: V, p3: V, t: number): V {
  const d = (a: V, b: V) => Math.max(1e-4, Math.sqrt(Math.hypot(b[0] - a[0], b[1] - a[1], b[2] - a[2])));
  const t0 = 0, t1 = t0 + d(p0, p1), t2 = t1 + d(p1, p2), t3 = t2 + d(p2, p3);
  const u = t1 + (t2 - t1) * t;
  const out: V = [0, 0, 0];
  for (let k = 0; k < 3; k++) {
    const a1 = ((t1 - u) * p0[k] + (u - t0) * p1[k]) / (t1 - t0);
    const a2 = ((t2 - u) * p1[k] + (u - t1) * p2[k]) / (t2 - t1);
    const a3 = ((t3 - u) * p2[k] + (u - t2) * p3[k]) / (t3 - t2);
    const b1 = ((t2 - u) * a1 + (u - t0) * a2) / (t2 - t0);
    const b2 = ((t3 - u) * a2 + (u - t1) * a3) / (t3 - t1);
    out[k] = ((t2 - u) * b1 + (u - t1) * b2) / (t2 - t1);
  }
  return out;
}

/** Lay a closed track through the control points; the first point should start the station. */
export function buildTrack(cps: CP[]): Track {
  const m = cps.length;
  // a dense polyline first, each point remembering the control segment it came from
  const dense: { p: V; seg: number }[] = [];
  for (let i = 0; i < m; i++) {
    const P = (j: number) => cps[(j + m) % m].p as V;
    for (let s = 0; s < 48; s++) dense.push({ p: catmull(P(i - 1), P(i), P(i + 1), P(i + 2), s / 48), seg: i });
  }
  const acc = [0];
  for (let i = 1; i <= dense.length; i++) {
    const a = dense[i - 1].p, b = dense[i % dense.length].p;
    acc.push(acc[i - 1] + Math.hypot(b[0] - a[0], b[1] - a[1], b[2] - a[2]));
  }
  const total = acc[dense.length];
  const n = Math.max(16, Math.round(total / H));
  const step = total / n;
  const pos = new Float32Array(n * 3), tan = new Float32Array(n * 3), up = new Float32Array(n * 3), sec = new Uint8Array(n);
  const segOf = new Int32Array(n);
  let j = 0;
  for (let i = 0; i < n; i++) {
    const s = i * step;
    while (j < dense.length - 1 && acc[j + 1] < s) j++;
    const f = (s - acc[j]) / Math.max(1e-6, acc[j + 1] - acc[j]);
    const a = dense[j].p, b = dense[(j + 1) % dense.length].p;
    pos.set([a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f, a[2] + (b[2] - a[2]) * f], i * 3);
    segOf[i] = dense[j].seg;
    sec[i] = cps[dense[j].seg].sec ?? Sec.Free;
  }
  const P = (i: number): V => { const k = ((i % n) + n) % n; return [pos[k * 3], pos[k * 3 + 1], pos[k * 3 + 2]]; };
  for (let i = 0; i < n; i++) tan.set(norm(sub(P(i + 1), P(i - 1))), i * 3);
  const T = (i: number): V => { const k = ((i % n) + n) % n; return [tan[k * 3], tan[k * 3 + 1], tan[k * 3 + 2]]; };
  let top = -Infinity;
  for (let i = 0; i < n; i++) top = Math.max(top, pos[i * 3 + 1]);
  // the sideways pull of each turn, smoothed, for the banking
  const kh: V[] = [];
  for (let i = 0; i < n; i++) {
    const d = sub(T(i + 2), T(i - 2));
    kh.push([d[0] / (4 * step), 0, d[2] / (4 * step)]);
  }
  const W = 8;
  const raw: V[] = [];
  for (let i = 0; i < n; i++) {
    const t = T(i), p = P(i), cp = cps[segOf[i]];
    let a: V;
    if (cp.loop) {
      const c = cp.loop.c as V;
      const centre: V = cp.loop.axis === 'x' ? [p[0], c[1], c[2]] : [c[0], c[1], p[2]];
      a = sub(centre, p);
    } else {
      a = [0, G, 0];
      if (sec[i] === Sec.Free) {
        let sx = 0, sz = 0;
        for (let q = -W; q <= W; q++) { const v = kh[((i + q) % n + n) % n]; sx += v[0]; sz += v[2]; }
        sx /= 2 * W + 1; sz /= 2 * W + 1;
        // banked for the speed the train carries here, as if it had fallen from the top
        const v2 = Math.max(0.4, 2 * G * (top - p[1]) * 0.8);
        const lat = Math.min(Math.hypot(sx, sz) * v2, G * 1.7);
        const l = Math.hypot(sx, sz) || 1;
        a = [(sx / l) * lat, G, (sz / l) * lat];
      }
    }
    let u = sub(a, scl(t, dot(a, t)));
    if (Math.hypot(u[0], u[1], u[2]) < 1e-4) u = i ? raw[i - 1] : [0, 1, 0];
    raw.push(norm(u));
  }
  // smooth the ups a little so nothing kinks where a loop or a bank begins
  for (let i = 0; i < n; i++) {
    let u: V = [0, 0, 0];
    for (let q = -4; q <= 4; q++) { const v = raw[((i + q) % n + n) % n]; u = [u[0] + v[0], u[1] + v[1], u[2] + v[2]]; }
    const t = T(i);
    up.set(norm(sub(u, scl(t, dot(u, t)))), i * 3);
  }
  // the station: from its first sample to its last, the stop mark a little short of the end
  let st0 = -1, st1 = -1;
  for (let i = 0; i < n; i++) if (sec[i] === Sec.Station) { if (st0 < 0) st0 = i; st1 = i; }
  const stop = st1 >= 0 ? (st1 - 2) * step : 0;
  const platform = st1 >= 0 ? (st1 - st0) * step : 0;
  return { len: total, n, pos, tan, up, sec, stop, platform, top };
}

const scl = (a: V, k: number): V => [a[0] * k, a[1] * k, a[2] * k];

function wrap(t: Track, s: number): number { return ((s % t.len) + t.len) % t.len; }

/** Position, tangent and up at arc length s. */
export function frameAt(t: Track, s: number, p: V, tg: V, u: V): void {
  const x = wrap(t, s) / (t.len / t.n), i = Math.floor(x) % t.n, i2 = (i + 1) % t.n, f = x - Math.floor(x);
  for (let k = 0; k < 3; k++) {
    p[k] = t.pos[i * 3 + k] * (1 - f) + t.pos[i2 * 3 + k] * f;
    tg[k] = t.tan[i * 3 + k] * (1 - f) + t.tan[i2 * 3 + k] * f;
    u[k] = t.up[i * 3 + k] * (1 - f) + t.up[i2 * 3 + k] * f;
  }
}

export function secAt(t: Track, s: number): Sec {
  return t.sec[Math.floor(wrap(t, s) / (t.len / t.n)) % t.n] as Sec;
}

function slopeAt(t: Track, s: number): number {
  const x = wrap(t, s) / (t.len / t.n), i = Math.floor(x) % t.n, i2 = (i + 1) % t.n, f = x - Math.floor(x);
  return t.tan[i * 3 + 1] * (1 - f) + t.tan[i2 * 3 + 1] * f;
}

/** A train on a track: where its front car is, how fast it goes, and what it is doing. */
export class Train {
  s: number;
  v = 0;
  state: 'run' | 'dwell' = 'dwell';
  wait: number;
  private stuck = 0;
  laps = 0;
  constructor(readonly track: Track, readonly cars: number, readonly gap: number, seed = 0) {
    this.s = track.stop;
    this.wait = 1 + (seed % 7);
  }

  /** Advance by dt; `open` while the ride is taking riders (otherwise it parks in the station). */
  step(dt: number, open: boolean): void {
    const t = this.track;
    for (let left = dt; left > 1e-6; left -= 1 / 120) this.tick(Math.min(left, 1 / 120), open, t);
  }

  private tick(dt: number, open: boolean, t: Track): void {
    if (this.state === 'dwell') {
      this.v = 0;
      this.wait -= dt;
      if (this.wait <= 0 && open) { this.state = 'run'; this.v = 0.05; }
      return;
    }
    let slope = 0, lift = false, brake = false, tyres = false, trim = false;
    for (let c = 0; c < this.cars; c++) {
      const s = this.s - c * this.gap;
      slope += slopeAt(t, s);
      const k = secAt(t, s);
      if (k === Sec.Lift) lift = true;
      else if (k === Sec.Brake) brake = true;
      else if (k === Sec.Station) tyres = true;
      else if (k === Sec.Trim) trim = true;
    }
    slope /= this.cars;
    let v = this.v;
    const was = v;
    v += (-G * slope - MU * G * Math.sign(v) - DRAG * v * Math.abs(v)) * dt;
    // the chain takes the train up at its own pace, and holds it there
    if (lift) v = Math.max(v, Math.min(LIFT_V, was + 1.6 * dt));
    if (trim && v > TRIM_V) v = Math.max(TRIM_V, v - 6 * dt);
    if (brake) v = v > BRAKE_V ? Math.max(BRAKE_V, v - 3 * dt) : Math.max(v, CREEP_V);
    // into the station: brake to a stand at the stop mark
    const toStop = wrap(t, t.stop - this.s);
    if (toStop < t.platform + 0.3 && toStop > 0) {
      const most = Math.sqrt(2 * 1.2 * toStop);
      v = Math.max(Math.min(v, most), 0.03);
      if (toStop < 0.01) {
        this.s = t.stop; this.v = 0; this.state = 'dwell'; this.wait = 5 + Math.random() * 3; this.laps++;
        return;
      }
    } else if (tyres && v < LAUNCH_V) v = Math.min(LAUNCH_V, v + 0.9 * dt);
    // never left hanging in a dip: a hidden booster nudges a train that has run out of speed
    this.stuck = Math.abs(v) < 0.06 ? this.stuck + dt : 0;
    if (this.stuck > 2) { v = 0.4; this.stuck = 0; }
    this.v = v;
    const ds = v * dt;
    // the stop mark can't be overshot in one step
    this.s = wrap(t, this.s + (toStop > 0 && toStop < ds ? toStop : ds));
  }
}

// ---- drawing ------------------------------------------------------------------------------------

interface TrackLook {
  rail: RGB;
  spine: RGB;
  legs: RGB;
  /** Bulb colours along the rails after dark. */
  bulbs: RGB[];
  lit: Sched;
  /** The bulbs' own schedule, when it differs from the track's. */
  bulbLit?: Sched;
  /** How much of a tile between bulbs; 0 for none. */
  bulbGap?: number;
}

const GAUGE = 0.05;

/** The rails, the spine under them, the ties, the legs to the ground, the chain, and the bulbs. */
export function drawTrack(k: Kit, t: Track, look: TrackLook): void {
  const p: V = [0, 0, 0], tg: V = [0, 0, 0], u: V = [0, 0, 0];
  const step = 0.12, n = Math.round(t.len / step);
  const at = (s: number) => {
    frameAt(t, s, p, tg, u);
    const x = norm(cross(u, tg));
    const L: P3 = [p[0] + x[0] * GAUGE, p[1] + x[1] * GAUGE, p[2] + x[2] * GAUGE];
    const R: P3 = [p[0] - x[0] * GAUGE, p[1] - x[1] * GAUGE, p[2] - x[2] * GAUGE];
    const S: P3 = [p[0] - u[0] * 0.05, p[1] - u[1] * 0.05, p[2] - u[2] * 0.05];
    return { L, R, S, c: [p[0], p[1], p[2]] as P3, u: [u[0], u[1], u[2]] as V, x };
  };
  let prev = at(0);
  let nextLeg = 0, nextBulb = 0, bulb = 0;
  const gap = n ? t.len / n : step;
  for (let i = 1; i <= n; i++) {
    const s = i * gap, cur = at(s), kind = secAt(t, s);
    k.bar(prev.L, cur.L, 0.012, look.rail);
    k.bar(prev.R, cur.R, 0.012, look.rail);
    k.bar(prev.S, cur.S, 0.02, look.spine);
    k.bar(cur.L, cur.S, 0.008, look.spine);
    k.bar(cur.R, cur.S, 0.008, look.spine);
    if (kind === Sec.Lift) k.bar([prev.c[0], prev.c[1] + 0.006, prev.c[2]], [cur.c[0], cur.c[1] + 0.006, cur.c[2]], 0.008, DARK);
    // a leg down to the ground wherever the track is the right way up and off the ground
    if (s >= nextLeg) {
      const g = k.ground(cur.S[0], cur.S[2]) - 0.02;
      const side = Math.abs(cur.u[1]) < 0.2;
      if ((cur.u[1] > 0.5 || side) && cur.S[1] - g > 0.12) {
        k.cyl(cur.S[0], g, cur.S[2], side ? 0.02 : 0.024, cur.S[1] - g, look.legs, 6);
        if (cur.S[1] - g > 0.9) k.box(cur.S[0], g, cur.S[2], 0.09, 0.03, 0.09, scale(look.legs, 0.8));
        nextLeg = s + (side ? 0.3 : 0.5);
      }
    }
    // the bulbs along both rails, a chase of colours
    if (look.bulbGap && s >= nextBulb) {
      nextBulb = s + look.bulbGap;
      const col = look.bulbs[bulb++ % look.bulbs.length];
      for (const sd of [1, -1]) {
        const q = sd > 0 ? cur.L : cur.R;
        k.glowBox(q[0] + cur.x[0] * sd * 0.02, q[1] - 0.01, q[2] + cur.x[2] * sd * 0.02, 0.024, 0.024, 0.024, col, look.bulbLit ?? look.lit, col);
      }
    }
    prev = cur;
  }
}

const SKIN = [0xf1c7a1, 0xd9a07a, 0x9a6a48, 0x6a4632, 0xf4d9bf].map(hex);
const SHIRT = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0xf4f2ec, 0x8e5cc7, 0xff7fae].map(hex);

/** One car, front +z, its wheels on the rails at y = 0: a tub, a seat back, two riders and a lap bar. */
export function drawCar(k: Kit, col: RGB, lead: boolean, r: () => number, size = 1, lamp?: Sched): void {
  const s = size;
  k.box(0, 0.006 * s, 0, 0.12 * s, 0.022 * s, 0.17 * s, DARK);
  for (const sz of [-1, 1]) for (const sx of [-1, 1]) k.box(sx * 0.055 * s, -0.012 * s, sz * 0.06 * s, 0.022 * s, 0.03 * s, 0.03 * s, scale(DARK, 0.7));
  k.box(0, 0.028 * s, 0, 0.15 * s, 0.05 * s, 0.19 * s, col, scale(col, 1.08));
  k.box(0, 0.078 * s, -0.075 * s, 0.14 * s, 0.06 * s, 0.025 * s, scale(col, 0.75));
  for (const sx of [-1, 1]) {
    const shirt = SHIRT[Math.floor(r() * SHIRT.length)];
    k.box(sx * 0.035 * s, 0.078 * s, -0.025 * s, 0.045 * s, 0.045 * s, 0.04 * s, shirt);
    k.box(sx * 0.035 * s, 0.123 * s, -0.025 * s, 0.032 * s, 0.032 * s, 0.032 * s, SKIN[Math.floor(r() * SKIN.length)]);
  }
  k.box(0, 0.085 * s, 0.03 * s, 0.13 * s, 0.012 * s, 0.012 * s, hex(0xf2c14e));
  if (lead) {
    k.box(0, 0.028 * s, 0.11 * s, 0.13 * s, 0.04 * s, 0.04 * s, scale(col, 0.85));
    if (lamp) for (const sx of [-1, 1]) k.glowBox(sx * 0.04 * s, 0.035 * s, 0.13 * s, 0.022 * s, 0.018 * s, 0.01 * s, WHITE, lamp, hex(0xfff2c0));
  }
}

const tmpP: V = [0, 0, 0], tmpT: V = [0, 0, 0], tmpU: V = [0, 0, 0];
const basis = new THREE.Matrix4(), vx = new THREE.Vector3(), vy = new THREE.Vector3(), vz = new THREE.Vector3();

/** Put each car of the train where it is on the track, sitting square on the rails. */
export function placeCars(train: Train, cars: THREE.Object3D[]): void {
  for (let c = 0; c < cars.length; c++) {
    frameAt(train.track, train.s - c * train.gap, tmpP, tmpT, tmpU);
    vz.set(tmpT[0], tmpT[1], tmpT[2]).normalize();
    vy.set(tmpU[0], tmpU[1], tmpU[2]);
    vx.crossVectors(vy, vz).normalize();
    vy.crossVectors(vz, vx);
    basis.makeBasis(vx, vy, vz);
    cars[c].quaternion.setFromRotationMatrix(basis);
    cars[c].position.set(tmpP[0] + tmpU[0] * 0.012, tmpP[1] + tmpU[1] * 0.012, tmpP[2] + tmpU[2] * 0.012);
  }
}

/**
 * Strings of bulbs: some parks go all warm white, some go rainbow, red through violet in order so a run
 * of them reads as a rainbow along a rail or round a rim. `lightsFor` picks by the building's seed.
 */
const RAINBOW_BULBS = [0xff2a2a, 0xff8c1a, 0xffe01a, 0x3cff3c, 0x2a8cff, 0xa040ff].map(hex);
const WHITE_BULBS = [0xfff3d6, 0xfff3d6, 0xffe9b8].map(hex);
export function lightsFor(seed: number): { bulbs: RGB[]; lit: Sched } {
  // coloured bulbs burn a little softer, or the glow bleaches them back to white
  return (seed >>> 3) % 2 ? { bulbs: RAINBOW_BULBS, lit: [17.5, 24, 1.6] } : { bulbs: WHITE_BULBS, lit: [17.5, 24, 2.4] };
}

/** Open from 9 in the morning until midnight. */
export const rideOpen = (hour: number) => hour >= 9 && hour < 24;
