import { DIRS, N, idx, inB, waterDepth, type Building, type World } from '../../world/tiles';
import { hashString } from '../../world/rng';
import { SITE_LABEL, type SiteKind } from '../cargoTypes';
import { RUSH, RUSH_KINDS, bandOf, type EndKind, type Family, type RushKind } from './kinds';

/**
 * Where a county's rushes are (docs/rushes.html): worked out at run time from the county as generated, like the
 * PvP lines (game/challenges/sites.ts), never written into it. For each kind, an A among the county's places of
 * its `from` kinds and a B of its `to` kinds inside its family's band, measured the way that family goes: by road
 * (no level crossing on the way: a train can shut it mid-run), by water deep enough for any boat, straight through
 * the air, or along the track between two stations on one line. Picked by a hash of the county, so every game
 * has the same.
 *
 * It is spread out over frames: `pump` first lists the places the rushes use (not the whole of buildSites, which
 * took 30–100 ms a county), then tries one A a call (at most one flood), and a county's list is ready once every
 * kind has found its rush or run out of As to try.
 */

export interface RushEnd { x: number; z: number; name: string }

export interface RushSite {
  /** `<kind>:<cx>.<cz>:<A's stop tile>`: what the year's wait is kept under. */
  key: string;
  kind: RushKind;
  cx: number; cz: number;
  /** Where a vehicle stops to fill (A) and unload (B), world tiles. */
  a: RushEnd;
  b: RushEnd;
  /** A to B the family's way, tiles. */
  len: number;
}

/** The most As tried for a kind in a county (a flood each). */
const TRIES = 24;
/** What stands at a pithead and what a works is, for the Coal Shuttle's sidings; how near the track (tiles) a siding is. */
const PITHEAD = new Set<string>(['coalTipple', 'mineHeadframe', 'crusher', 'gravelPlant']);
const MILL = new Set<string>(['powerPlant', 'steelworks', 'factory']);
const SIDING_R = 8;
/** Water a rush boat needs, in steps: every boat but the biggest floats in it (vehicles.ts minDepth). */
const DEEP = 2;

/**
 * A place a rush may start or end at: what kind, its name, where a vehicle of each family stops for it (local
 * tiles), and for a station its line and how far along it.
 */
interface Place { kind: EndKind; name: string; lx: number; lz: number; b?: Building; rail?: { path: number; s: number } }

/** One kind's search: the As left to try, in hash order. */
interface Search { kind: RushKind; froms: Place[]; tos: Place[]; tried: number }

interface Work { searches: Search[]; done: RushSite[] }

const ready = new WeakMap<World, RushSite[]>();
const work = new WeakMap<World, Work>();

/** A county's rushes, or null while they are still being worked out (call pump). */
export function rushesOf(w: World): RushSite[] | null {
  return ready.get(w) ?? null;
}

/** Try the next A for the first of these counties not yet done. Returns whether anything was done. */
export function pump(worlds: World[]): boolean {
  for (const w of worlds) {
    if (ready.has(w)) continue;
    const job = work.get(w);
    if (!job) { work.set(w, { searches: searches(w), done: [] }); return true; }
    const q = job.searches[0];
    if (q) {
      const s = q.tried < Math.min(TRIES, q.froms.length) ? tryA(w, q, q.froms[q.tried++]) : null;
      if (s) job.done.push(s);
      if (s || q.tried >= Math.min(TRIES, q.froms.length)) job.searches.shift();
    }
    if (!job.searches.length) { ready.set(w, job.done); work.delete(w); }
    return true;
  }
  return false;
}

/** Every kind at once (the gate). */
export function rushesNow(w: World): RushSite[] {
  while (!ready.has(w)) pump([w]);
  return ready.get(w)!;
}

const hash = (w: World, salt: string): number => hashString(`rush:${w.cx},${w.cz}:${salt}`);
const deep = (w: World, i: number): boolean => w.water[i] >= 0 && waterDepth(w, i) >= DEEP;

/** The road tile nearest a local point, within r tiles; -1 for none. */
function roadNear(w: World, x: number, z: number, r = 3): number {
  return nearest(w, x, z, r, (i) => !!w.road[i] && !w.blocked[i] && !w.rail[i] && w.water[i] < 0);
}

/** The tile nearest a local point within r tiles that passes `ok`; -1 for none. */
function nearest(w: World, x: number, z: number, r: number, ok: (i: number) => boolean): number {
  let best = -1, bd = Infinity;
  const tx = Math.floor(x), tz = Math.floor(z);
  for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
    const nx = tx + dx, nz = tz + dz;
    if (!inB(nx, nz)) continue;
    const i = idx(nx, nz);
    if (!ok(i)) continue;
    const d = Math.hypot(nx + 0.5 - x, nz + 0.5 - z);
    if (d < bd) { bd = d; best = i; }
  }
  return best;
}

/** The flood's buffers, kept between calls: only the tiles the last flood reached are set back. */
const dist = new Int16Array(N * N).fill(-1);
const queue = new Int32Array(N * N);
let reached = 0;

/**
 * Distance (tiles) from one tile to those within `cap` over the edges `step` allows, into `dist` (-1 unreached).
 * Given `want`, it stops once every one of those tiles has its distance, and goes on only from tiles that could
 * still reach one of them within `cap` (the steps so far and the grid distance left): a hundred-tile band floods a
 * lot of open water or road otherwise, and one step a frame must not hitch.
 */
function flood(from: number, cap: number, step: (i: number, k: number, j: number) => boolean, want?: Set<number>): void {
  for (let k = 0; k < reached; k++) dist[queue[k]] = -1;
  let head = 0, tail = 0, left = want ? want.size - (want.has(from) ? 1 : 0) : -1;
  const goals = want ? [...want].map((g) => [g % N, Math.floor(g / N)]) : null;
  const near = (j: number, d: number): boolean => {
    if (!goals) return true;
    const x = j % N, z = (j - x) / N;
    for (const [gx, gz] of goals) if (d + Math.abs(gx - x) + Math.abs(gz - z) <= cap) return true;
    return false;
  };
  dist[from] = 0;
  queue[tail++] = from;
  while (head < tail && left !== 0) {
    const i = queue[head++], d = dist[i];
    if (d >= cap) continue;
    const tx = i % N, tz = (i - tx) / N;
    for (let k = 0; k < 4; k++) {
      const nx = tx + DIRS[k][0], nz = tz + DIRS[k][1];
      if (!inB(nx, nz)) continue;
      const j = idx(nx, nz);
      if (dist[j] >= 0 || !step(i, k, j) || !near(j, d + 1)) continue;
      dist[j] = d + 1;
      queue[tail++] = j;
      if (want?.has(j)) left--;
    }
  }
  reached = tail;
}

/** By road, never over a rail (a level crossing can shut mid-run). */
const byRoad = (w: World) => (i: number, k: number, j: number) => !!(w.roadEdges[i] & (1 << k)) && !!w.road[j] && !w.blocked[j] && !w.rail[j];
const byWater = (w: World) => (_i: number, _k: number, j: number) => deep(w, j);

/** The middle of the side a building faces, where its door is, local tiles. */
function front(b: Building, name: string): Place {
  const lx = b.facing === 0 ? b.x + b.w + 0.3 : b.facing === 2 ? b.x - 0.3 : b.x + b.w / 2;
  const lz = b.facing === 1 ? b.z + b.d + 0.3 : b.facing === 3 ? b.z - 0.3 : b.z + b.d / 2;
  return { kind: b.kind, name, lx, lz, b };
}

/** The town nearest a local point, for a place's name. */
function townNear(w: World, x: number, z: number): string {
  let best = w.name || 'the county', d = Infinity;
  for (const t of w.towns) {
    const e = Math.hypot(t.x0 + t.size / 2 - x, t.z0 + t.size / 2 - z);
    if (e < d) { d = e; best = t.name; }
  }
  return best;
}

/** Every rush kind's search for a county: the places it may start and end at, As in the county's hash order. */
function searches(w: World): Search[] {
  const wanted = new Set<EndKind>(RUSH_KINDS.flatMap((k) => [...k.from, ...k.to]));
  const places: Place[] = [];
  const label = (k: string) => SITE_LABEL[k as SiteKind] ?? k;
  for (const t of w.towns) for (const b of t.buildings) if (!b.derelict && wanted.has(b.kind)) places.push(front(b, `${label(b.kind)} · ${t.name}`));
  for (const b of w.countryside) if (!b.gone && wanted.has(b.kind)) places.push(front(b, `${label(b.kind)} · ${w.name}`));
  for (const g of w.works) for (const b of g.buildings) if (!b.gone && wanted.has(b.kind)) places.push(front(b, g.name || `${label(b.kind)} · ${w.name}`));
  // stations: on the line, at the middle of the platform
  for (const st of w.stations) {
    const path = w.rails.find((p) => p.id === st.path) ?? w.rails[st.path];
    if (!path) continue;
    const s = (st.s0 + st.s1) / 2;
    let k = 0;
    while (k < path.s.length - 1 && path.s[k] < s) k++;
    places.push({ kind: 'station', name: st.name, lx: path.xz[k * 2], lz: path.xz[k * 2 + 1], b: st.building ?? undefined, rail: { path: path.id, s } });
  }
  // the track beside a pithead (coal, gravel, ore) and beside a works that burns or uses it, on the nearest line within reach
  for (const b of w.allBuildings) {
    const end = PITHEAD.has(b.kind) ? 'pithead' : MILL.has(b.kind) ? 'mill' : null;
    if (!end || b.gone) continue;
    const mx = b.x + b.w / 2, mz = b.z + b.d / 2;
    let best: { path: number; k: number; d: number } | null = null;
    for (const p of w.rails) for (let k = 0; k < p.s.length; k++) {
      const d = Math.hypot(p.xz[k * 2] - mx, p.xz[k * 2 + 1] - mz);
      if (d < SIDING_R && (!best || d < best.d)) best = { path: p.id, k, d };
    }
    if (!best) continue;
    const p = w.rails.find((q) => q.id === best!.path)!;
    places.push({ kind: end, name: `the ${end === 'pithead' ? 'pithead' : label(b.kind).toLowerCase()} siding · ${townNear(w, mx, mz)}`, lx: p.xz[best.k * 2], lz: p.xz[best.k * 2 + 1], b, rail: { path: p.id, s: p.s[best.k] } });
  }
  // harbours: a few tiles out from the end of the pier, in water any rush boat floats in
  for (const p of w.ports) {
    const [dx, dz] = DIRS[p.dir];
    const rx = p.root % N, rz = Math.floor(p.root / N);
    for (let k = 2; k <= 8; k++) {
      const x = rx + dx * k, z = rz + dz * k;
      if (inB(x, z) && deep(w, idx(x, z))) { places.push({ kind: 'port', name: p.name, lx: x + 0.5, lz: z + 0.5 }); break; }
    }
  }
  // each town's waterfront: deep water beside the land, the one nearest its middle
  for (const t of w.towns) {
    const mx = t.x0 + t.size / 2, mz = t.z0 + t.size / 2;
    const i = nearest(w, mx, mz, Math.ceil(t.size / 2) + 4, (j) => {
      if (!deep(w, j)) return false;
      const x = j % N, z = Math.floor(j / N);
      return DIRS.some(([a, b]) => inB(x + a, z + b) && w.water[idx(x + a, z + b)] < 0);
    });
    if (i >= 0) places.push({ kind: 'shore', name: `the waterfront · ${t.name}`, lx: (i % N) + 0.5, lz: Math.floor(i / N) + 0.5 });
  }
  // shoals: open water with nothing but water for six tiles round
  for (let z = 10; z < N - 10; z += 12) for (let x = 10; x < N - 10; x += 12) {
    let open = true;
    for (let dz = -6; dz <= 6 && open; dz += 2) for (let dx = -6; dx <= 6 && open; dx += 2) if (!deep(w, idx(x + dx, z + dz))) open = false;
    if (open) places.push({ kind: 'shoal', name: `the shoal off ${townNear(w, x, z)}`, lx: x + 0.5, lz: z + 0.5 });
  }
  // a heli's pad: the ground in front of a park, square or plaza
  for (const t of w.towns) for (const b of t.buildings) if (b.kind === 'park' || b.kind === 'plaza' || b.kind === 'marketSquare') places.push({ ...front(b, `the green · ${t.name}`), kind: 'field' });
  return RUSH_KINDS.map((kind) => {
    const h = hash(w, kind.id);
    const froms = places.filter((p) => kind.from.includes(p.kind))
      .map((p, k) => ({ p, r: hashString(`${h}:${k}`) })).sort((a, b) => a.r - b.r).map((q) => q.p);
    return { kind, froms, tos: places.filter((p) => kind.to.includes(p.kind)), tried: 0 };
  }).filter((q) => q.froms.length && q.tos.length);
}

/** Where a vehicle of a family stops for a place, as a tile index (rail: the place's own tile); -1 for nowhere. */
function stopOf(w: World, fam: Family, p: Place): number {
  const tx = Math.floor(p.lx), tz = Math.floor(p.lz);
  if (!inB(tx, tz)) return -1;
  if (fam === 'road') return roadNear(w, p.lx, p.lz, p.kind === 'shore' ? 5 : 3);
  if (fam === 'sea') return deep(w, idx(tx, tz)) ? idx(tx, tz) : nearest(w, p.lx, p.lz, 3, (i) => deep(w, i));
  if (fam === 'air') return nearest(w, p.lx, p.lz, 3, (i) => !w.blocked[i] && w.water[i] < 0);
  return idx(tx, tz);
}

/** One A tried: a B of the kind inside the band from it, the family's way, or null. At most two floods. */
function tryA(w: World, q: Search, a: Place): RushSite | null {
  const fam = q.kind.family;
  const [lo, hi] = bandOf(q.kind);
  const crow = (b: Place) => Math.hypot(b.lx - a.lx, b.lz - a.lz);
  let near = q.tos.filter((b) => b !== a && (!b.b || b.b !== a.b) && crow(b) >= Math.max(RUSH.crowMin, fam === 'air' ? lo : 0) && crow(b) <= hi);
  if (fam === 'rail') near = near.filter((b) => b.rail && a.rail && b.rail.path === a.rail.path);
  if (!near.length) return null;
  const ai = stopOf(w, fam, a);
  if (ai < 0) return null;
  const stops = near.map((b) => stopOf(w, fam, b));
  const want = new Set(stops.filter((i) => i >= 0));
  if (fam === 'road') flood(ai, hi + 1, byRoad(w), want);
  else if (fam === 'sea') flood(ai, hi + 1, byWater(w), want);
  const fits: { b: Place; bi: number; d: number }[] = [];
  for (let k = 0; k < near.length; k++) {
    const b = near[k], bi = stops[k];
    if (bi < 0) continue;
    const d = fam === 'air' ? Math.round(crow(b)) : fam === 'rail' ? Math.round(Math.abs(b.rail!.s - a.rail!.s)) : dist[bi];
    if (d < lo || d > hi) continue;
    fits.push({ b, bi, d });
  }
  // an island: B's land is not reached by road from A's
  if (q.kind.twist === 'island' && fits.length) {
    const ar = roadNear(w, a.lx, a.lz, 8);
    if (ar < 0) return null;
    flood(ar, 700, byRoad(w));
    for (let k = fits.length - 1; k >= 0; k--) {
      const br = roadNear(w, fits[k].b.lx, fits[k].b.lz, 8);
      if (br < 0 || dist[br] >= 0) fits.splice(k, 1);
    }
  }
  if (!fits.length) return null;
  const f = fits[hashString(`${hash(w, q.kind.id)}:b`) % fits.length];
  const at = (i: number, p: Place) => fam === 'rail'
    ? { x: w.ox + p.lx, z: w.oz + p.lz }
    : { x: w.ox + (i % N) + 0.5, z: w.oz + Math.floor(i / N) + 0.5 };
  return {
    key: `${q.kind.id}:${w.cx}.${w.cz}:${ai}`, kind: q.kind, cx: w.cx, cz: w.cz,
    a: { ...at(ai, a), name: a.name }, b: { ...at(f.bi, f.b), name: f.b.name }, len: f.d,
  };
}
