import { hex, mix, scale, type RGB } from '../../world/biomes';
import { mallPlan, type MallUnit } from '../../world/malls';
import type { PlayKind } from '../../world/playKinds';
import { mulberry32, type Rng } from '../../world/rng';
import type { Building } from '../../world/tiles';
import { NEXT_WORLD } from '../../world/nextWorld';
import { BUSINESS_DRAW } from './business';
import { VENUE_DRAW } from './venues';
import { variantDraw } from './variants';
import { BRIGHT, CARS, DARK, GLASS, METAL, SHOP_GLOW, WARM_GLOW, WATER, WHITE, WOOD, bladeSign, car, neonColour, pick, tree, type Draw, type Kit } from './kit';

/**
 * The outdoor mall (world/malls.ts mallPlan), after Old Orchard in Skokie: car parks striped into bays round three
 * sides, lamp posts over them; in the middle a village of low shops and places to eat facing in on paved walks with
 * a fountain, planted beds and trees, tables under parasols outside the eateries; along the back a cinema under its
 * marquee and two department-store anchors with their names in a band. Lit up after dark.
 */

const PAVING = hex(0xd9cfbc), PAVING_B = hex(0xcfc4ae), LINE = hex(0xeceae2), KERB = hex(0xb9b3a6);
const BED = hex(0x6b8a3e), SOIL = hex(0x7a5e40), PARASOL = [0xe2412f, 0xf2c14e, 0x2f7fb5, 0x3f9b4a, 0xf4f2ec];
const WALLS = [0xe8dcc6, 0xd9c2a0, 0xc9b49a, 0xe6e0d4, 0xb9765a, 0xd8cdb8].map(hex);
const ANCHOR = [0xe4ddd0, 0xc8b8a0, 0xa9a39a].map(hex), CINEMA = [0x6b2f3a, 0x2f3f5a, 0x3a3f45].map(hex);
/** Shopfronts lit from dusk to late evening; a cinema's marquee till midnight and after. */
const SHOP_HOURS: [number, number, number] = [16.5, 22.5, 1], MARQUEE_HOURS: [number, number, number] = [17, 24.5, 1];

/** A flat rectangle facing up. */
function flat(k: Kit, x: number, z: number, w: number, d: number, y: number, col: RGB): void {
  const x0 = x - w / 2, x1 = x + w / 2, z0 = z - d / 2, z1 = z + d / 2;
  k.quad([x0, y, z0], [x1, y, z0], [x1, y, z1], [x0, y, z1], col, [x, y - 1, z]);
}

/** One building: walls, a parapet, its shopfront glass and awning toward the walk, and a sign. */
function unit(k: Kit, r: Rng, u: MallUnit): void {
  const wall = u.kind === 'cinema' ? CINEMA[Math.floor(r() * CINEMA.length)] : u.kind === 'anchor' ? ANCHOR[Math.floor(r() * ANCHOR.length)] : WALLS[Math.floor(r() * WALLS.length)];
  k.box(u.x, 0, u.z, u.w, u.h, u.d, wall, scale(wall, 0.86));
  // a parapet round the flat roof, and plant on it
  k.box(u.x, u.h, u.z, u.w + 0.04, 0.05, u.d + 0.04, scale(wall, 0.9));
  if (u.w * u.d > 1.2) k.box(u.x - u.w * 0.2, u.h + 0.05, u.z - u.d * 0.15, 0.22, 0.09, 0.18, METAL);
  // the front: which side, and how wide it runs
  const fx = u.face === 'px' ? 1 : u.face === 'nx' ? -1 : 0, fz = u.face === 'pz' ? 1 : 0;
  const run = fz ? u.w : u.d, ox = u.x + fx * (u.w / 2 + 0.006), oz = u.z + fz * (u.d / 2 + 0.006);
  const across = (a: number, y: number, len: number, h: number, depth: number, col: RGB) => {
    if (fz) k.box(ox + a, y, oz - depth / 2, len, h, depth, col);
    else k.box(ox - fx * depth / 2, y, oz + a, depth, h, len, col);
  };
  const glow = (a: number, y: number, len: number, h: number, day: RGB, s: [number, number, number], g: RGB) => {
    if (fz) k.glowBox(ox + a, y, oz, len, h, 0.02, day, s, g);
    else k.glowBox(ox, y, oz + a, 0.02, h, len, day, s, g);
  };
  if (u.kind === 'cinema') {
    // the lobby glass, the marquee over it lit up, and a tall blade sign with the name down it
    glow(0, 0.02, run * 0.6, 0.3, GLASS, SHOP_HOURS, SHOP_GLOW);
    across(0, 0.36, run * 0.82, 0.16, 0.34, scale(wall, 0.7));
    glow(0, 0.38, run * 0.8, 0.11, WHITE, MARQUEE_HOURS, neonColour(r));
    for (const s of [-1, 1]) across(s * run * 0.38, 0.06, 0.16, 0.24, 0.03, hex(0xf2c14e));
    bladeSign(k, r, ox + (fz ? -run * 0.36 : 0), 0.5, u.h + 0.32, oz + (fz ? 0.02 : -run * 0.36), 0.2);
    return;
  }
  if (u.kind === 'anchor') {
    // a tall glazed entrance in the middle under a canopy, and the store's name in a band across the top
    glow(0, 0.02, run * 0.34, 0.42, GLASS, SHOP_HOURS, SHOP_GLOW);
    across(0, 0.45, run * 0.42, 0.04, 0.28, scale(wall, 0.75));
    across(0, u.h - 0.16, run * 0.7, 0.1, 0.02, pick(r, BRIGHT));
    for (const s of [-1, 1]) glow(s * run * 0.33, 0.12, run * 0.16, 0.26, GLASS, SHOP_HOURS, SHOP_GLOW);
    return;
  }
  // a shop or a place to eat: a glass front under a striped awning, and its own sign
  const awn = pick(r, BRIGHT);
  glow(0, 0.03, run * 0.84, 0.27, GLASS, SHOP_HOURS, u.kind === 'eatery' ? WARM_GLOW : SHOP_GLOW);
  const stripes = Math.max(3, Math.round(run / 0.14));
  for (let s = 0; s < stripes; s++) {
    const a = -run * 0.44 + (s + 0.5) * (run * 0.88 / stripes);
    across(a, 0.33, run * 0.88 / stripes, 0.03, 0.22, s % 2 ? WHITE : awn);
  }
  across(0, 0.4, run * 0.6, 0.08, 0.02, u.kind === 'eatery' ? hex(0xf2c14e) : WHITE);
}

/**
 * 0.7.0 (docs/models070-audit.md): an anchor is the town's own department store and the cinema its own cinema (with the
 * cinemas' variants), two floors, turned to face the walk.
 */
function realUnit(k: Kit, u: MallUnit, seed: number): void {
  const yaw = u.face === 'px' ? Math.PI / 2 : u.face === 'nx' ? -Math.PI / 2 : 0;
  const W = u.face === 'pz' ? u.w : u.d, D = u.face === 'pz' ? u.d : u.w;
  const kind = u.kind === 'anchor' ? 'departmentStore' : 'cinema';
  const b = { kind, x: 0, z: 0, w: W, d: D, facing: 1, floors: 2, seed, solid: true, level: 0, uid: 0 } as Building;
  const d = (kind === 'cinema' ? variantDraw(b) : null) ?? (kind === 'departmentStore' ? BUSINESS_DRAW.departmentStore : VENUE_DRAW.cinema);
  k.within(u.x, u.z, yaw, () => d(k, W, D, b, mulberry32(seed), null));
}

/** The pylon sign at the road: a tall post, the mall's name in lights at the top, the tenants' panels stacked under it. */
function pylon(k: Kit, r: Rng, x: number, z: number): void {
  const H = 1.5;
  for (const sx of [-1, 1]) k.box(x + sx * 0.1, 0, z, 0.05, H, 0.05, DARK);
  k.box(x, 0, z, 0.3, 0.08, 0.12, scale(KERB, 0.9));
  k.glowBox(x, H - 0.24, z, 0.36, 0.22, 0.06, WHITE, MARQUEE_HOURS, SHOP_GLOW);
  k.box(x, H - 0.02, z, 0.4, 0.04, 0.08, DARK);
  for (let i = 0; i < 4; i++) k.glowBox(x, 0.3 + i * 0.22, z, 0.3, 0.17, 0.05, pick(r, BRIGHT), SHOP_HOURS, SHOP_GLOW);
}

/** The clock tower at the mouth of the main walk: brick, a clock on each face, a copper cap and a weathervane. */
function clockTower(k: Kit, x: number, z: number): void {
  const brick = hex(0xa4583f), H = 1.25;
  k.box(x, 0, z, 0.3, H, 0.3, brick);
  k.box(x, 0, z, 0.36, 0.08, 0.36, KERB);
  k.box(x, H, z, 0.36, 0.04, 0.36, KERB);
  for (const [fx, fz] of [[0, 1], [1, 0], [0, -1], [-1, 0]] as const) {
    const cx = x + fx * 0.151, cz = z + fz * 0.151;
    k.glowBox(cx, H - 0.26, cz, fx ? 0.01 : 0.18, 0.18, fz ? 0.01 : 0.18, WHITE, [17, 30, 1], SHOP_GLOW);
    k.box(cx + fx * 0.004, H - 0.17, cz + fz * 0.004, fx ? 0.006 : 0.012, 0.07, fz ? 0.006 : 0.012, DARK);
  }
  k.hip(x, H + 0.04, z, 0.34, 0.3, 0.34, hex(0x5f9e8e));
  k.cyl(x, H + 0.34, z, 0.006, 0.12, DARK, 4);
  k.box(x + 0.03, H + 0.42, z, 0.08, 0.025, 0.004, DARK);
}

const draw: Draw = (k, W, D, b, r) => {
  const p = mallPlan(b.seed, W, D);
  // the car parks: kerbed edges, bays striped across the front and down the sides
  for (const bay of p.bays) car(k, bay.x, bay.z, bay.alongX, pick(r, CARS));
  for (let bx = -W / 2 + 0.35 - 0.145; bx <= W / 2 - 0.2; bx += 0.29) {
    if (Math.abs(bx + 0.145) < 0.45 && Math.abs(bx) < 0.6) continue;
    for (const z of [D / 2 - 0.35, D / 2 - 2.5 + 0.55]) flat(k, bx, z, 0.012, 0.42, 0.006, LINE);
  }
  for (const side of [-1, 1]) {
    for (let bz = -D / 2 + 0.35 - 0.145; bz <= D / 2 - 2.5 - 0.1; bz += 0.29) flat(k, side * (W / 2 - 0.3), bz, 0.42, 0.012, 0.006, LINE);
    k.box(side * (W / 2 - 1.6), 0, (-D / 2 + D / 2 - 2.5) / 2, 0.05, 0.03, D - 2.6, KERB);
  }
  for (const [lx, lz] of p.lamps) {
    k.bar([lx, 0, lz], [lx, 0.62, lz], 0.016, DARK);
    k.glowBox(lx, 0.6, lz, 0.1, 0.03, 0.1, METAL, [17.5, 30, 1], WARM_GLOW);
  }
  // the village: paving under it all, the walks a shade lighter, beds and trees, the fountain
  const c = p.core;
  flat(k, (c.x0 + c.x1) / 2, (c.z0 + c.z1) / 2, c.x1 - c.x0 + 0.2, c.z1 - c.z0 + 0.2, 0.008, PAVING_B);
  for (const wk of p.walks) flat(k, wk.x, wk.z, wk.w, wk.d, 0.012, PAVING);
  for (const [tx, tz] of p.trees) {
    k.box(tx, 0, tz, 0.34, 0.07, 0.34, SOIL, BED);
    tree(k, tx, 0.07, tz, 0.95, false);
  }
  // planted beds down both sides of the main walk, a bench facing out of each
  const main = p.walks[0];
  for (const sx of [-1, 1]) for (const f of [-0.22, 0.22]) {
    const bx = sx * (main.w / 2 - 0.22), bz = main.z + main.d * f;
    k.box(bx, 0, bz, 0.2, 0.08, 0.55, SOIL, BED);
    k.box(bx - sx * 0.2, 0, bz, 0.08, 0.07, 0.3, WOOD);
  }
  for (const f of p.fountains) {
    k.cyl(f.x, 0, f.z, f.r, 0.07, KERB, 14, WATER);
    k.cyl(f.x, 0.07, f.z, f.r * 0.25, 0.12, KERB, 8);
    k.cyl(f.x, 0.19, f.z, 0.03, 0.12, mix(WATER, WHITE, 0.6), 6);
  }
  if (NEXT_WORLD) { pylon(k, r, W / 2 - 0.5, D / 2 - 0.12); clockTower(k, main.x, p.core.z1 - 0.25); }
  for (const u of p.units) {
    if (NEXT_WORLD && (u.kind === 'anchor' || u.kind === 'cinema')) realUnit(k, u, b.seed ^ Math.round(u.x * 97 + u.z * 13));
    else unit(k, r, u);
    // tables under parasols out on the walk in front of a place to eat
    if (u.kind !== 'eatery' || u.face === 'pz') continue;
    const fx = u.face === 'px' ? 1 : -1;
    for (const dz of [-u.d * 0.22, u.d * 0.22]) {
      const tx = u.x + fx * (u.w / 2 + 0.28), tz = u.z + dz;
      k.box(tx, 0, tz, 0.12, 0.08, 0.12, WOOD);
      k.bar([tx, 0, tz], [tx, 0.32, tz], 0.008, WHITE);
      k.cone(tx, 0.26, tz, 0.17, 0.08, hex(PARASOL[Math.floor(r() * PARASOL.length)]), 8);
    }
  }
};

/** The mall's model, by kind (render/buildings/play.ts gathers it with the places to play). */
export const MALL_DRAW: Partial<Record<PlayKind, Draw>> = { outdoorMall: draw };
