import { hex, scale, type RGB } from '../../../world/biomes';
import type { RegionBuildingKind } from '../../../world/tiles';
import type { Sched } from '../../nightLights';
import { DARK, WARM_GLOW, WOOD, type Draw, type Kit, type P3 } from '../kit';

/**
 * The Lavender Plateau: the purple rows themselves, a distillery with its copper still, a farmhouse
 * behind its cypresses, a pigeon tower, and the plain grey abbey at the head of its fields.
 * Honey limestone, terracotta, pale blue shutters.
 */

const HONEY = hex(0xe3cc9a), HONEY_SHADE = hex(0xd2b884), ABBEY = hex(0xd9d0ba), ABBEY_SHADE = hex(0xc6bda6), SLAB = hex(0xa9a394);
const TERRA = hex(0xc8683f), TERRA_DARK = hex(0xa85434), SHUTTER = hex(0x9cc3d6), EARTH = hex(0xd9cdb2), GRAVEL = hex(0xe6dcc4);
const SOIL = hex(0xb39572), FLAG = hex(0xd8d2c4), FLAG_SHADE = hex(0xc9c1b0), BOX = hex(0x4d7240), BOX_TOP = hex(0x5d8a4c);
const CYPRESS = hex(0x2f5a3c), PLANE = hex(0x6a9a4a), GREEN = hex(0x7f9a5a), COPPER = hex(0xc87a3c), COPPER_LIT = hex(0xe09a58);
const PURPLES = [0x8a5fc0, 0x7a4fb0, 0x9a72cc, 0x6f48a3, 0xa27fd2].map(hex);
const EVENING: Sched = [18, 23.5, 1.4];

/** A rounded ridge of lavender (or anything heaped in a row): a long low prism, narrower on top, along x or z. */
function ridge(k: Kit, x: number, z: number, len: number, w: number, h: number, col: RGB, alongZ = false, y = 0.02): void {
  const L = len / 2, e = L - Math.min(0.08, L * 0.3), b = w / 2, t = w * 0.22, y1 = y + h, top = scale(col, 1.1);
  const P = (u: number, v: number, yy: number): P3 => (alongZ ? [x + v, yy, z + u] : [x + u, yy, z + v]);
  const I: P3 = [x, y + h / 3, z];
  k.quad(P(-e, -t, y1), P(e, -t, y1), P(e, t, y1), P(-e, t, y1), top, I);
  for (const s of [-1, 1]) {
    k.quad(P(-L, s * b, y), P(L, s * b, y), P(e, s * t, y1), P(-e, s * t, y1), s > 0 ? col : scale(col, 0.92), I);
    k.quad(P(s * L, -b, y), P(s * L, b, y), P(s * e, t, y1), P(s * e, -t, y1), col, I);
  }
}

/** A cypress: a dark green spindle. */
function cypress(k: Kit, x: number, z: number, s: number, y = 0): void {
  k.cyl(x, y, z, 0.02 * s, 0.08 * s, hex(0x5a4632), 5);
  k.band(x, z, y + 0.06 * s, 0.05 * s, y + 0.22 * s, 0.085 * s, 7, CYPRESS);
  k.cone(x, y + 0.22 * s, z, 0.085 * s, 0.5 * s, CYPRESS, 7);
}

/** A low hipped roof over a rectangle: a short ridge along the longer side, four tiled slopes. */
function hipRoof(k: Kit, x: number, y: number, z: number, w: number, h: number, d: number, col: RGB): void {
  const x0 = x - w / 2, x1 = x + w / 2, z0 = z - d / 2, z1 = z + d / 2, I: P3 = [x, y + h / 4, z];
  if (w >= d) {
    const rx = (w - d) / 2 + d * 0.12, A: P3 = [x - rx, y + h, z], B: P3 = [x + rx, y + h, z];
    k.quad([x0, y, z1], [x1, y, z1], B, A, col, I);
    k.quad([x0, y, z0], [x1, y, z0], B, A, scale(col, 0.9), I);
    k.tri([x0, y, z0], [x0, y, z1], A, scale(col, 0.95), I);
    k.tri([x1, y, z0], [x1, y, z1], B, scale(col, 0.95), I);
  } else {
    const rz = (d - w) / 2 + w * 0.12, A: P3 = [x, y + h, z - rz], B: P3 = [x, y + h, z + rz];
    k.quad([x1, y, z0], [x1, y, z1], B, A, col, I);
    k.quad([x0, y, z0], [x0, y, z1], B, A, scale(col, 0.9), I);
    k.tri([x0, y, z0], [x1, y, z0], A, scale(col, 0.95), I);
    k.tri([x0, y, z1], [x1, y, z1], B, scale(col, 0.95), I);
  }
}

/** A shuttered window on a front (+z) wall: the pane, and a pale blue leaf folded back either side. */
function shuttered(k: Kit, x: number, y: number, z: number, w: number, h: number): void {
  k.pane(x, y, z, w, h, 1, DARK, EVENING, WARM_GLOW);
  for (const s of [-1, 1]) k.box(x + s * (w / 2 + 0.022), y - 0.005, z + 0.006, 0.04, h + 0.01, 0.012, SHUTTER);
}

// ---- a lavender field (6 × 5, or near it) -------------------------------------------------------------

/**
 * Rows of lavender: long purple ridges along x on pale stony earth, the purple shifting from row to
 * row, with a stone borie or a lone cypress in the back corner. All of it low: an open lot.
 */
const lavenderField: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2;
  k.box(0, 0, 0, W - 0.2, 0.02, D - 0.2, EARTH);
  const n = Math.floor((D - 0.5) / 0.36), gap = (D - 0.5) / n, left = r() < 0.5;
  let col = PURPLES[Math.floor(r() * PURPLES.length)];
  for (let i = 0; i < n; i++) {
    if (r() < 0.6) col = PURPLES[Math.floor(r() * PURPLES.length)];
    const z = -hd + 0.25 + (i + 0.5) * gap;
    // the back rows stop short of the corner the hut stands in
    const cut = z < -hd + 1.15 ? 1.0 : 0;
    const len = W - 0.5 - cut;
    ridge(k, (left ? cut : -cut) / 2, z, len, 0.26, 0.11, col);
  }
  const cx = (left ? -1 : 1) * (hw - 0.55), cz = -hd + 0.6;
  if (r() < 0.55) {
    // a borie: a dry-stone beehive hut
    k.cyl(cx, 0.02, cz, 0.24, 0.12, HONEY_SHADE, 9);
    k.band(cx, cz, 0.14, 0.24, 0.3, 0.17, 9, HONEY);
    k.dome(cx, 0.3, cz, 0.17, HONEY_SHADE, 9, 2);
    k.box(cx, 0.02, cz + 0.235, 0.1, 0.15, 0.02, DARK);
  } else {
    cypress(k, cx, cz, 1.25);
    k.box(cx + 0.22, 0.02, cz + 0.1, 0.16, 0.07, 0.12, HONEY_SHADE);
  }
};

// ---- the perfumery (2 × 2) -----------------------------------------------------------------------------

/**
 * A lavender distillery: a honey-stone barn under terracotta, a copper still beneath a lean-to at its
 * side with a swan neck over to the condenser barrel, cut lavender on a cart, and the chimney.
 */
const perfumery: Draw = (k, W, D) => {
  const hd = D / 2;
  k.box(0, 0, 0, W - 0.2, 0.02, D - 0.2, GRAVEL);
  // the barn, gable to the road, with its arched door
  const bx = -0.32, bz = -0.2, bw = 0.95, bd = 1.15, bh = 0.5;
  k.box(bx, 0.02, bz, bw, bh, bd, HONEY);
  k.gable(bx, 0.02 + bh, bz, bw + 0.08, 0.32, bd + 0.08, TERRA, HONEY, true);
  const fz = bz + bd / 2;
  k.box(bx, 0.02, fz + 0.006, 0.3, 0.3, 0.012, hex(0x6a4a36));
  k.face(bx, 0.32, fz + 0.012, 0.15, hex(0x6a4a36), 10);
  k.pane(bx, 0.6, fz, 0.12, 0.12, 1, DARK, EVENING, WARM_GLOW);
  for (const dz of [-0.3, 0.2]) k.pane(bx - bw / 2, 0.22, bz + dz, 0.12, 0.14, 2, DARK, EVENING, WARM_GLOW);
  // the chimney up the back
  k.box(bx - 0.22, 0.02, bz - bd / 2 + 0.1, 0.16, 1.0, 0.16, HONEY_SHADE);
  k.box(bx - 0.22, 1.02, bz - bd / 2 + 0.1, 0.2, 0.04, 0.2, TERRA_DARK);
  // the lean-to down the right side, open to the front and the yard
  const lx0 = bx + bw / 2, lx1 = lx0 + 0.62, lz0 = bz - bd / 2 + 0.05, lz1 = 0.02;
  k.quad([lx0, 0.62, lz0], [lx0, 0.62, lz1], [lx1, 0.5, lz1], [lx1, 0.5, lz0], TERRA_DARK, [lx0, 0, bz]);
  k.quad([lx0, 0.605, lz0], [lx0, 0.605, lz1], [lx1, 0.485, lz1], [lx1, 0.485, lz0], hex(0x7a5a40), [lx0 + 0.3, 2, bz]);
  for (const z of [lz0 + 0.03, lz1 - 0.03]) k.box(lx1 - 0.03, 0.02, z, 0.04, 0.47, 0.04, WOOD);
  // the still: a brick hearth, the copper pot and its dome, the swan neck, the condenser barrel
  const sx = lx0 + 0.3, sz = -0.2;
  k.cyl(sx, 0.02, sz, 0.17, 0.1, hex(0x9c4f3d), 8);
  k.cyl(sx, 0.12, sz, 0.15, 0.16, COPPER, 10);
  k.dome(sx, 0.28, sz, 0.15, COPPER_LIT, 10, 3);
  k.cyl(sx, 0.42, sz, 0.035, 0.1, COPPER, 6);
  const cz = hd - 0.5;
  k.bar([sx, 0.52, sz], [sx + 0.03, 0.5, sz + 0.2], 0.018, COPPER_LIT);
  k.bar([sx + 0.03, 0.5, sz + 0.2], [sx + 0.06, 0.28, cz], 0.016, COPPER_LIT);
  k.cyl(sx + 0.06, 0.02, cz, 0.11, 0.24, WOOD, 8, hex(0x6fb3cf));
  for (const y of [0.07, 0.19]) k.cyl(sx + 0.06, y, cz, 0.115, 0.02, DARK, 8);
  k.glowBox(sx, 0.03, sz + 0.17, 0.08, 0.06, 0.02, hex(0x5a2a1a), [17, 24, 2], hex(0xff8a3a));
  // cut lavender: sheaves stacked by the door and a cartload out front
  const kx = -0.45, kz = hd - 0.32;
  k.box(kx, 0.11, kz, 0.4, 0.03, 0.22, WOOD);
  for (const s of [-1, 1]) k.hoop(kx + 0.06, 0.09, kz + s * 0.125, 0.07, 0.012, DARK, 8, 'xy');
  k.bar([kx - 0.2, 0.125, kz], [kx - 0.38, 0.04, kz], 0.012, WOOD);
  ridge(k, kx, kz - 0.05, 0.36, 0.11, 0.08, PURPLES[0], false, 0.14);
  ridge(k, kx, kz + 0.05, 0.36, 0.11, 0.08, PURPLES[2], false, 0.14);
  for (const dz of [-0.05, 0.05]) k.box(kx - 0.19, 0.145, kz + dz, 0.03, 0.04, 0.06, GREEN);
  for (let i = 0; i < 3; i++) ridge(k, bx + 0.33, fz + 0.1 + i * 0.09, 0.2, 0.09, 0.07, PURPLES[(i + 1) % 5]);
};

// ---- the bastide (2 × 2) -------------------------------------------------------------------------------

/**
 * A Provençal farmhouse: a solid two-storey block of honey stone under a low terracotta hip, blue
 * shutters, a lower wing, a gravel court with a plane tree and a well, cypresses down one edge.
 */
const bastide: Draw = (k, W, D) => {
  const hw = W / 2, hd = D / 2;
  k.box(0, 0, 0, W - 0.2, 0.02, D - 0.2, GRAVEL);
  // the house
  const mx = -0.18, mz = -0.42, mw = 0.95, md = 0.62, mh = 0.62;
  k.box(mx, 0.02, mz, mw, mh, md, HONEY);
  k.box(mx, 0.02 + mh, mz, mw + 0.05, 0.03, md + 0.05, HONEY_SHADE);
  hipRoof(k, mx, 0.05 + mh, mz, mw + 0.12, 0.2, md + 0.12, TERRA);
  k.box(mx + 0.3, 0.7, mz - 0.1, 0.09, 0.2, 0.09, HONEY_SHADE, TERRA_DARK);
  const fz = mz + md / 2;
  k.box(mx, 0.02, fz + 0.006, 0.12, 0.22, 0.012, SHUTTER);
  for (const dx of [-0.3, 0.3]) shuttered(k, mx + dx, 0.1, fz, 0.09, 0.13);
  for (const dx of [-0.3, 0, 0.3]) shuttered(k, mx + dx, 0.4, fz, 0.09, 0.13);
  k.pane(mx - mw / 2, 0.4, mz, 0.09, 0.13, 2, DARK, EVENING, WARM_GLOW);
  // the lower wing
  const wx = mx + mw / 2 + 0.24, wz = mz + 0.02;
  k.box(wx, 0.02, wz, 0.5, 0.32, 0.52, HONEY_SHADE);
  k.gable(wx, 0.34, wz, 0.56, 0.15, 0.6, TERRA_DARK, HONEY_SHADE);
  k.box(wx, 0.02, wz + 0.266, 0.2, 0.22, 0.012, hex(0x6a4a36));
  // the court: a plane tree with a pale trunk, and the well
  const tx = 0.42, tz = 0.42;
  k.cyl(tx, 0.02, tz, 0.04, 0.34, hex(0xcfc8b4), 6);
  k.dome(tx, 0.3, tz, 0.3, PLANE, 8, 3);
  k.dome(tx - 0.12, 0.36, tz + 0.08, 0.2, scale(PLANE, 1.12), 7, 2);
  const ox = -0.3, oz = 0.45;
  k.cyl(ox, 0.02, oz, 0.1, 0.11, HONEY_SHADE, 8, hex(0x4a5a6a));
  for (const s of [-1, 1]) k.box(ox + s * 0.085, 0.13, oz, 0.02, 0.17, 0.02, WOOD);
  k.gable(ox, 0.3, oz, 0.26, 0.07, 0.16, TERRA_DARK, WOOD);
  // cypresses down the left edge, and a low wall at the back
  for (let i = 0; i < 5; i++) cypress(k, -hw + 0.2, -hd + 0.3 + i * ((D - 0.6) / 4), 1.05 + (i % 2) * 0.15);
  k.box(0.3, 0.02, -hd + 0.14, W - 1.0, 0.1, 0.06, HONEY_SHADE);
};

// ---- the dovecote (1 × 1) ------------------------------------------------------------------------------

/**
 * A pigeonnier: a small square stone tower under a tiled pyramid, a band of glazed tiles near the
 * top to keep the rats out, and rows of flight holes above it.
 */
const dovecote: Draw = (k) => {
  const w = 0.44, h = 0.82;
  k.box(0, 0, 0, 0.62, 0.04, 0.62, HONEY_SHADE);
  k.box(0, 0.04, 0, w, h, w, HONEY);
  // the glazed band, green and yellow, and a plain ledge under it
  k.box(0, 0.5, 0, w + 0.05, 0.025, w + 0.05, HONEY_SHADE);
  k.box(0, 0.56, 0, w + 0.024, 0.05, w + 0.024, hex(0x3f8f6a));
  k.box(0, 0.575, 0, w + 0.03, 0.02, w + 0.03, hex(0xe6c04e));
  // the flight holes: two rows on every face
  for (let f = 0; f < 4; f++) {
    for (let row = 0; row < 2; row++) for (let i = 0; i < 3 - row; i++) {
      const u = (i - (2 - row) / 2) * 0.12, y = 0.65 + row * 0.085, e = w / 2 + 0.003;
      if (f % 2) k.box(u, y, f === 1 ? e : -e, 0.045, 0.05, 0.008, DARK);
      else k.box(f === 0 ? e : -e, y, u, 0.008, 0.05, 0.045, DARK);
    }
  }
  k.box(0, 0.04, w / 2 + 0.004, 0.14, 0.24, 0.01, hex(0x6a4a36));
  k.pane(0, 0.36, w / 2, 0.07, 0.08, 1, DARK, EVENING, WARM_GLOW);
  // the roof, its eaves standing out, and a finial for the birds to land on
  k.box(0, 0.04 + h, 0, w + 0.06, 0.025, w + 0.06, HONEY_SHADE);
  k.hip(0, 0.065 + h, 0, w + 0.16, 0.3, w + 0.16, TERRA);
  k.box(0, 1.15, 0, 0.035, 0.07, 0.035, TERRA_DARK);
  k.box(0.04, 1.22, 0, 0.05, 0.03, 0.025, hex(0xf4f2ec));
};

// ---- the abbey (the wonder, 12 × 12) -------------------------------------------------------------------

/** A small round-headed abbey window on a wall facing `face`. */
function lancet(k: Kit, x: number, y: number, z: number, face: number, w = 0.13, h = 0.34): void {
  k.pane(x, y, z, w, h, face, DARK, EVENING, WARM_GLOW);
}

/**
 * The abbey among its lavender, after Sénanque: a plain Romanesque church with a squat tower over
 * the crossing and a round apse, a cloister of lean-to roofs round a garden, dormitory ranges under
 * stone slabs, and the whole front of the lot in purple rows running up to its door.
 */
const lavenderAbbey: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2;
  k.box(0, 0, -3.0, W - 0.4, 0.02, 5.6, GRAVEL);
  k.box(0, 0, 2.8, W - 0.4, 0.02, 6.0, SOIL);
  // the walk up to the door: flagstones on a grass verge between low clipped box hedges, so it reads as a
  // garden path, not a road carried on through the lot (the user, 7 Oct 2026: a wide pale strip in line
  // with the approach road looked like one)
  k.box(0, 0.02, 2.75, 1.1, 0.012, 5.9, GREEN);
  for (let z = -0.25, i = 0; z < hd - 0.35; z += 0.3, i++) k.box((i % 2 ? 0.03 : -0.03), 0.032, z, 0.34, 0.012, 0.22, i % 3 ? FLAG : FLAG_SHADE);
  for (const sx of [-1, 1]) {
    k.box(sx * 0.5, 0.02, 3.05, 0.13, 0.14, hd - 0.6, BOX);
    k.box(sx * 0.5, 0.16, 3.05, 0.09, 0.03, hd - 0.64, BOX_TOP);
  }
  // the lavender: rows running toward the abbey, the right-hand field reaching back past the apse
  let col = PURPLES[0];
  for (let x = -hw + 0.5; x <= hw - 0.45; x += 0.42) {
    if (Math.abs(x) < 0.62) continue;
    if (r() < 0.5) col = PURPLES[Math.floor(r() * PURPLES.length)];
    const z0 = x > 1.0 ? -2.3 : 0.2, z1 = hd - 0.3;
    ridge(k, x, (z0 + z1) / 2, z1 - z0, 0.3, 0.13, col, true);
  }
  // the church: nave, choir and apse along the back, the transept across them
  const cz = -4.4, wallH = 1.5;
  k.box(-1.85, 0.02, cz, 5.1, wallH, 1.5, ABBEY);
  k.gable(-1.85, 0.02 + wallH, cz, 5.2, 0.55, 1.62, SLAB, ABBEY);
  k.box(1.4, 0.02, cz, 1.4, 1.3, 1.4, ABBEY);
  k.gable(1.4, 1.32, cz, 1.5, 0.5, 1.5, SLAB, ABBEY);
  k.cyl(2.1, 0.02, cz, 0.68, 1.05, ABBEY, 12);
  k.cone(2.1, 1.07, cz, 0.75, 0.42, SLAB, 12);
  k.box(0, 0.02, -4.15, 1.4, wallH, 2.9, ABBEY);
  k.gable(0, 0.02 + wallH, -4.15, 1.52, 0.55, 3.0, SLAB, ABBEY, true);
  // the tower over the crossing: squat and square, two openings a side, a low stone pyramid
  k.box(0, wallH, cz, 1.35, 1.55, 1.35, ABBEY_SHADE);
  k.box(0, wallH + 1.55, cz, 1.46, 0.06, 1.46, ABBEY);
  k.hip(0, wallH + 1.61, cz, 1.52, 0.42, 1.52, SLAB);
  for (const s of [-1, 1]) for (const u of [-0.28, 0.28]) {
    k.box(u, 2.42, cz + s * 0.676, 0.2, 0.44, 0.012, DARK);
    k.box(s * 0.676, 2.42, cz + u, 0.012, 0.44, 0.2, DARK);
  }
  k.box(0, 2.3, cz, 1.39, 0.04, 1.39, ABBEY);
  // windows: the nave's clerestory, the apse, and the door in the transept's end at the head of the path
  for (let i = 0; i < 5; i++) for (const s of [1, -1]) lancet(k, -3.9 + i * 0.7, 0.95, cz + s * 0.75, s > 0 ? 1 : 3);
  for (const a of [-0.7, 0, 0.7]) k.box(2.1 + Math.cos(a) * 0.68, 0.45, cz + Math.sin(a) * 0.68, 0.06, 0.3, 0.06, DARK);
  lancet(k, 1.4, 0.7, cz + 0.7, 1);
  const tz = -2.7;
  k.box(0, 0.02, tz + 0.02, 0.62, 0.78, 0.04, ABBEY_SHADE);
  k.box(0, 0.02, tz + 0.045, 0.4, 0.5, 0.012, hex(0x5a4030));
  k.face(0, 0.52, tz + 0.05, 0.2, hex(0x5a4030), 10);
  k.face(0, 1.25, tz + 0.006, 0.17, DARK, 10);
  for (const s of [-1, 1]) lancet(k, s * 0.42, 0.95, tz, 1, 0.1, 0.26);
  for (let i = 0; i < 3; i++) k.box(0, 0.02, tz + 0.12 + i * 0.07, 0.9 - i * 0.12, 0.05 - i * 0.015, 0.1, ABBEY_SHADE);
  // the ranges round the cloister: the dormitory down the west side, the refectory along the front
  k.box(-4.8, 0.02, -2.1, 1.2, 1.05, 3.2, ABBEY);
  k.gable(-4.8, 1.07, -2.1, 1.3, 0.45, 3.3, SLAB, ABBEY, true);
  for (let i = 0; i < 5; i++) {
    lancet(k, -5.4, 0.62, -3.3 + i * 0.6, 2, 0.1, 0.2);
    lancet(k, -5.4, 0.2, -3.3 + i * 0.6, 2, 0.1, 0.2);
  }
  lancet(k, -4.8, 0.55, -0.5, 1, 0.14, 0.3);
  k.box(-2.5, 0.02, -0.95, 3.6, 0.85, 0.9, ABBEY);
  k.gable(-2.5, 0.87, -0.95, 3.7, 0.4, 1.0, SLAB, ABBEY);
  for (let i = 0; i < 6; i++) lancet(k, -3.9 + i * 0.56, 0.3, -0.5, 1, 0.11, 0.3);
  // the cloister: four lean-to walks on little arches round a garden
  const cx0 = -4.2, cx1 = -0.7, cq0 = -3.65, cq1 = -1.4, ww = 0.5, yo = 0.74, yi = 0.5;
  const gx0 = cx0 + ww, gx1 = cx1 - ww, gz0 = cq0 + ww, gz1 = cq1 - ww, I: P3 = [(cx0 + cx1) / 2, 0.2, (cq0 + cq1) / 2];
  const under: P3 = [I[0], -3, I[2]];
  k.quad([cx0, yo, cq0], [cx1, yo, cq0], [gx1, yi, gz0], [gx0, yi, gz0], TERRA, under);
  k.quad([cx0, yo, cq1], [cx1, yo, cq1], [gx1, yi, gz1], [gx0, yi, gz1], TERRA, under);
  k.quad([cx0, yo, cq0], [cx0, yo, cq1], [gx0, yi, gz1], [gx0, yi, gz0], TERRA_DARK, under);
  k.quad([cx1, yo, cq0], [cx1, yo, cq1], [gx1, yi, gz1], [gx1, yi, gz0], TERRA_DARK, under);
  const nxp = 8, nzp = 4;
  for (let i = 0; i <= nxp; i++) for (const z of [gz0, gz1]) k.box(gx0 + (i * (gx1 - gx0)) / nxp, 0.02, z, 0.06, 0.4, 0.06, ABBEY);
  for (let j = 1; j < nzp; j++) for (const x of [gx0, gx1]) k.box(x, 0.02, gz0 + (j * (gz1 - gz0)) / nzp, 0.06, 0.4, 0.06, ABBEY);
  for (const z of [gz0, gz1]) k.box((gx0 + gx1) / 2, 0.42, z, gx1 - gx0 + 0.08, 0.075, 0.08, ABBEY_SHADE);
  for (const x of [gx0, gx1]) k.box(x, 0.42, (gz0 + gz1) / 2, 0.08, 0.075, gz1 - gz0 - 0.08, ABBEY_SHADE);
  k.box((gx0 + gx1) / 2, 0.02, (gz0 + gz1) / 2, gx1 - gx0 - 0.1, 0.02, gz1 - gz0 - 0.1, GREEN);
  k.cyl((gx0 + gx1) / 2, 0.04, (gz0 + gz1) / 2, 0.16, 0.1, ABBEY_SHADE, 8, hex(0x6fb3cf));
  for (const s of [-1, 1]) ridge(k, (gx0 + gx1) / 2 + s * 0.7, (gz0 + gz1) / 2, 0.6, 0.2, 0.08, PURPLES[2], false, 0.04);
  // a lay brothers' barn beyond the apse, the precinct wall, and cypresses
  k.box(4.3, 0.02, -4.7, 1.9, 0.62, 1.0, ABBEY);
  k.gable(4.3, 0.64, -4.7, 2.0, 0.36, 1.1, SLAB, ABBEY);
  k.box(4.0, 0.02, -4.194, 0.34, 0.4, 0.012, hex(0x5a4030));
  lancet(k, 4.8, 0.28, -4.2, 1, 0.1, 0.2);
  k.box(0, 0.02, -hd + 0.25, W - 0.5, 0.3, 0.1, ABBEY_SHADE);
  k.box(hw - 0.25, 0.02, -4.1, 0.1, 0.3, 3.4, ABBEY_SHADE);
  for (const [x, z, s] of [[3.0, -5.3, 2.2], [3.1, -3.0, 1.9], [5.3, -3.2, 1.7], [-0.95, -0.15, 1.6], [0.95, -0.15, 1.6], [-5.5, 0.0, 1.8], [1.1, -2.9, 1.5]] as const) cypress(k, x, z, s);
};

