import { hex, scale } from '../../world/biomes';
import type { MediaKind } from '../../world/tiles';
import { FLOOR } from '../../world/towns';
import type { PadLocal } from '../../world/helipads';
import { GLASS, TAU, WHITE, pick, row, tower, win, type Draw, type Kit } from './kit';

/**
 * Broadcasting, and the helipad marking every pad carries. The radio station is a single-storey studio
 * with its ON AIR light, a dish and a pad on the roof; beside it stands a guyed mast (radioMast: a
 * slender lattice held up by wires to three anchors) or a free-standing lattice tower (radioTower: four
 * legs tapering to a platform of antennas). The news station is a glass block in the station's colours,
 * dishes and a mast on the roof beside its pad, and the vans parked out front. Both towers are painted in
 * the aviation red and white, with red obstruction lights that come on at dusk.
 */

const RED = hex(0xd23a2e), WHITE_PAINT = hex(0xf2f0ea), STEEL = hex(0x8e959c);
const OBSTRUCTION = hex(0xff3a2a), PAD = hex(0x383c42), PAD_LINE = hex(0xf4f4f0), PAD_EDGE = hex(0xf2c14e);
/** Lit from dusk to dawn, bright: aviation lights. */
const NIGHT_BRIGHT: [number, number, number] = [17.2, 30.5, 3.2];

/**
 * The marking every helipad has, standing on a roof at p.y: a dark square edged in yellow, a white ring
 * and a big white H, and a green light on each corner after dark. Readable from any camera height.
 */
export function helipadMark(k: Kit, p: PadLocal): void {
  const { x, y, z, s } = p, t = s * 0.05;
  k.box(x, y, z, s, 0.02, s, PAD);
  for (const sz of [-1, 1]) k.box(x, y + 0.02, z + sz * (s / 2 - t / 2), s, 0.006, t, PAD_EDGE);
  for (const sx of [-1, 1]) k.box(x + sx * (s / 2 - t / 2), y + 0.02, z, t, 0.006, s - 2 * t, PAD_EDGE);
  k.cyl(x, y + 0.02, z, s * 0.4, 0.004, PAD_LINE, 20);
  k.cyl(x, y + 0.024, z, s * 0.34, 0.004, PAD, 20);
  const hh = s * 0.36, hw = s * 0.26, bar = s * 0.07;
  for (const sx of [-1, 1]) k.box(x + sx * (hw / 2 - bar / 2), y + 0.028, z, bar, 0.004, hh, PAD_LINE);
  k.box(x, y + 0.028, z, hw, 0.004, bar, PAD_LINE);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    k.glowBox(x + sx * (s / 2 - 0.03), y + 0.02, z + sz * (s / 2 - 0.03), 0.035, 0.03, 0.035, hex(0x3a7a4a), NIGHT_BRIGHT, hex(0x5dff8a));
  }
}

/** Red and white bands up a shaft from y0 to y1, `n` of them: [bottom, top, colour]. */
function bands(y0: number, y1: number, n: number): [number, number, typeof RED][] {
  const out: [number, number, typeof RED][] = [];
  for (let i = 0; i < n; i++) out.push([y0 + ((y1 - y0) * i) / n, y0 + ((y1 - y0) * (i + 1)) / n, i % 2 ? WHITE_PAINT : RED]);
  return out;
}

// ---- the radio station -------------------------------------------------------------------------

const radioStation: Draw = (k, _W, _D, b, r) => {
  const wall = pick(r, [0xf1ede4, 0xe4d9c4, 0xd9dde0]), roof = hex(0x5a5f66), h = 0.42, z = -0.2;
  k.box(0, 0, z, 1.4, h, 1.0, wall, roof);
  // the eaves band stops short of the roof, or its top and the roof fight and the roof flickers
  k.box(0, h - 0.06, z, 1.44, 0.04, 1.04, scale(wall, 0.85));
  row(k, b, r, -0.2, 0.12, z + 0.5, 0.8, 0.16, 3, 1);
  for (const sx of [-1, 1]) win(k, b, r, sx * 0.7, 0.12, z, 0.16, 0.16, sx > 0 ? 0 : 2);
  k.box(0.45, 0, z + 0.505, 0.18, 0.28, 0.02, hex(0x3a4a5a));
  // the ON AIR light over the door, red and glowing whenever the station is broadcasting (always)
  k.glowBox(0.45, 0.31, z + 0.515, 0.2, 0.06, 0.02, hex(0x7a1a14), [0, 24, 2.4], hex(0xff4a3a));
  // a dish on its stand beside the building, looking at the sky
  const dx = -0.62, dz = 0.55;
  k.box(dx, 0, dz, 0.08, 0.26, 0.08, STEEL);
  k.cyl(dx, 0.28, dz, 0.2, 0.03, WHITE, 12);
  k.box(dx, 0.31, dz, 0.02, 0.14, 0.02, STEEL);
  // cable run and a little fenced transmitter hut at the back
  k.box(-0.35, 0, z - 0.7, 0.36, 0.22, 0.26, scale(wall, 0.9), roof);
  k.box(-0.35, 0.22, z - 0.7, 0.4, 0.02, 0.3, roof);
};

// ---- the news station --------------------------------------------------------------------------

const newsStation: Draw = (k, W, D, b, r) => {
  const brand = pick(r, [0x2f5fb0, 0xd23a2e, 0x2a8a6a, 0x6a3aa0]);
  const wall = pick(r, [0xe8ebee, 0xdfe3e6]), glass = hex(0x6f9fb8), f = b.floors, z = -0.15, w = W - 0.4, d = D - 0.6;
  const top = tower(k, b, r, 0, 0, z, w, d, f, wall, glass, 0.14);
  // a brand-coloured cornice round the roof edge: its top stops short of the roof, or the two
  // coplanar faces fight and the roof flickers blue and white as the camera moves
  k.box(0, top - 0.08, z, w + 0.04, 0.06, d + 0.04, brand);
  // the station's name band, lit at night, and its logo block at the corner
  k.glowBox(0, FLOOR * 0.72, z + d / 2 + 0.012, w * 0.7, 0.1, 0.02, brand, [16.5, 30, 1.8], scale(brand, 1.8));
  k.box(w / 2 - 0.2, top, z + d / 2 - 0.2, 0.3, 0.3, 0.3, brand);
  k.glowBox(w / 2 - 0.2, top + 0.08, z + d / 2 - 0.045, 0.2, 0.14, 0.02, WHITE, [16.5, 30, 1.6], WHITE);
  // dishes and the mast on the roof beside the pad
  for (const [x, zz, rr] of [[W / 2 - 0.6, z - 0.2, 0.17], [W / 2 - 1.0, z + 0.1, 0.13]] as [number, number, number][]) {
    k.box(x, top, zz, 0.05, 0.12, 0.05, STEEL);
    k.cyl(x, top + 0.12, zz, rr, 0.025, WHITE, 12);
  }
  const mx = W / 2 - 0.35, mz = z - 0.35;
  k.bar([mx, top, mz], [mx, top + 1.1, mz], 0.022, STEEL);
  for (let i = 0; i < 3; i++) k.box(mx, top + 0.45 + i * 0.25, mz, 0.2 - i * 0.04, 0.012, 0.012, STEEL);
  k.glowBox(mx, top + 1.1, mz, 0.04, 0.04, 0.04, hex(0x882222), NIGHT_BRIGHT, OBSTRUCTION);
  // two outside-broadcast vans parked in front, dishes folded on their roofs
  for (const sx of [-1, 1]) {
    const vx = sx * 0.5, vz = z + d / 2 + 0.3;
    k.box(vx, 0.02, vz, 0.22, 0.13, 0.36, WHITE, WHITE);
    k.box(vx, 0.06, vz + 0.05, 0.225, 0.04, 0.2, brand);
    k.cyl(vx, 0.15, vz - 0.06, 0.07, 0.015, hex(0xdfe3e6), 10);
    k.box(vx, 0.08, vz + 0.181, 0.18, 0.05, 0.005, GLASS);
  }
};

// ---- the guyed mast ----------------------------------------------------------------------------

const radioMast: Draw = (k, _W, _D, _b, r) => {
  const H = 6.6 + r() * 0.8, bw = 0.12;
  // the concrete pad and the base insulator
  k.box(0, 0, 0, 0.5, 0.08, 0.5, hex(0xb8b4ac));
  k.box(0, 0.08, 0, 0.14, 0.12, 0.14, hex(0x5a4a3a));
  // the shaft: a slim triangular lattice, banded red and white, as three chords with rungs between
  const legs: [number, number][] = [0, 1, 2].map((i) => [Math.cos((i / 3) * TAU) * bw, Math.sin((i / 3) * TAU) * bw]);
  for (const [y0, y1, col] of bands(0.2, H, 7)) {
    for (const [lx, lz] of legs) k.bar([lx, y0, lz], [lx, y1, lz], 0.018, col);
    const steps = Math.max(2, Math.round((y1 - y0) / 0.28));
    for (let s = 0; s < steps; s++) {
      const ya = y0 + ((y1 - y0) * s) / steps, yb = y0 + ((y1 - y0) * (s + 1)) / steps;
      for (let i = 0; i < 3; i++) {
        const a = legs[i], c = legs[(i + 1) % 3];
        k.bar([a[0], ya, a[1]], [c[0], yb, c[1]], 0.008, col);
      }
    }
  }
  // guy wires from three heights to three anchors out on the lot
  for (let i = 0; i < 3; i++) {
    const a = (i / 3) * TAU + 0.5, ax = Math.cos(a) * 1.35, az = Math.sin(a) * 1.35;
    k.box(ax, 0, az, 0.14, 0.07, 0.14, hex(0x9a968e));
    for (const f of [0.35, 0.65, 0.92]) k.bar([ax, 0.07, az], [Math.cos(a) * bw, H * f, Math.sin(a) * bw], 0.006, hex(0x4a4e54));
  }
  // obstruction lights at the top and part way up
  k.box(0, H, 0, 0.05, 0.25, 0.05, STEEL);
  k.glowBox(0, H + 0.25, 0, 0.07, 0.07, 0.07, hex(0x882222), NIGHT_BRIGHT, OBSTRUCTION);
  for (const f of [0.35, 0.68]) k.glowBox(bw + 0.03, H * f, 0, 0.05, 0.05, 0.05, hex(0x882222), NIGHT_BRIGHT, OBSTRUCTION);
  // the tuning hut at the foot
  k.box(0.6, 0, -0.55, 0.36, 0.22, 0.26, hex(0xd9d5cc), hex(0x6a6f76));
};

// ---- the lattice tower -------------------------------------------------------------------------

const radioTower: Draw = (k, _W, _D, _b, r) => {
  const H = 5.6 + r() * 0.8, base = 0.62, tip = 0.14;
  k.box(0, 0, 0, 1.5, 0.05, 1.5, hex(0xb8b4ac));
  // four legs tapering in, red and white by the section, cross-braced on every face
  const sections = 6;
  const half = (y: number) => base + (tip - base) * (y / H);
  for (let s = 0; s < sections; s++) {
    const y0 = (H * s) / sections, y1 = (H * (s + 1)) / sections, col = s % 2 ? WHITE_PAINT : RED;
    const a = half(y0), b2 = half(y1);
    const corners0: [number, number][] = [[-a, -a], [a, -a], [a, a], [-a, a]];
    const corners1: [number, number][] = [[-b2, -b2], [b2, -b2], [b2, b2], [-b2, b2]];
    for (let i = 0; i < 4; i++) {
      k.bar([corners0[i][0], y0, corners0[i][1]], [corners1[i][0], y1, corners1[i][1]], 0.028, col);
      const n = (i + 1) % 4;
      // an X on each face, and a ring at the top of the section
      k.bar([corners0[i][0], y0, corners0[i][1]], [corners1[n][0], y1, corners1[n][1]], 0.01, col);
      k.bar([corners0[n][0], y0, corners0[n][1]], [corners1[i][0], y1, corners1[i][1]], 0.01, col);
      k.bar([corners1[i][0], y1, corners1[i][1]], [corners1[n][0], y1, corners1[n][1]], 0.012, col);
    }
  }
  // the platform at the top with its dishes and the whip antenna
  k.box(0, H, 0, 0.5, 0.04, 0.5, STEEL);
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * TAU + 0.4;
    k.box(Math.cos(a) * 0.2, H + 0.04, Math.sin(a) * 0.2, 0.06, 0.24, 0.06, WHITE);
  }
  k.cyl(0.18, H - 0.6, 0.18, 0.13, 0.02, WHITE, 10);
  k.bar([0, H + 0.04, 0], [0, H + 0.9, 0], 0.014, STEEL);
  k.glowBox(0, H + 0.9, 0, 0.06, 0.06, 0.06, hex(0x882222), NIGHT_BRIGHT, OBSTRUCTION);
  for (const sx of [-1, 1]) k.glowBox(sx * (half(H * 0.5) + 0.03), H * 0.5, 0, 0.05, 0.05, 0.05, hex(0x882222), NIGHT_BRIGHT, OBSTRUCTION);
  // the equipment shelter at its foot
  k.box(0, 0, 0.62, 0.4, 0.2, 0.22, hex(0xd9d5cc), hex(0x6a6f76));
};

export const MEDIA_DRAW: Record<MediaKind, Draw> = { radioStation, newsStation, radioMast, radioTower };
