import { DIRS, STEP, type Building } from '../../world/tiles';

/**
 * Where everything is at a lido (an open-air public pool), for each of its models: the water, its lanes, the
 * diving boards, the slides, the loungers, the stand. The models (venues.ts `lido`, variants/lido.ts) are drawn
 * from these numbers and the bathers (game/pools.ts) and a swim meet (game/events/swimMeet.ts) go by them, so a
 * diver steps off the end of the board that is drawn, and a race swims the lanes that are painted.
 *
 * All in the model's own frame: the lot's middle at the origin, x across its width W, z its depth D (+z the
 * front), y up from its floor, in tiles (a tile is a world unit across). The changing block always stands at
 * the +x end, inside the kind's solid shape (world/footprint.ts), as the original model's does.
 *
 * The alternatives lay themselves out along the longer side of what the changing block leaves free: drawn in a
 * frame of their own (x' along it, z' across) that is turned a quarter about the lot's middle when the lot is
 * deeper than it is wide. Every point here is already turned back into the model's frame.
 */

export type P3 = [number, number, number];
export type Pt = { x: number; z: number };

/** Model numbers: 0 is the kind's own (venues.ts), then the alternatives in variants/lido.ts. */
export const LIDO_CLASSIC = 0, LIDO_BOARDS = 1, LIDO_SLIDES = 2, LIDO_HALL = 3;
const LIDO_MODELS = 4;

export interface Board {
  /** Where the queue starts on the deck, at the ladder's foot. */
  foot: Pt;
  /** The top of the ladder (the back of the board), and the end of the board. */
  top: P3; tip: P3;
  /** A springboard bounces before the dive; a platform doesn't. */
  spring: boolean;
}
export interface Slide {
  /** Top to bottom: the last point is in the water. */
  path: P3[];
  /** The queue's place at the foot of the stairs, and the top of them. */
  foot: Pt; top: P3;
}
export interface Pool { x0: number; z0: number; x1: number; z1: number }

export interface LidoPlan {
  model: number;
  W: number; D: number;
  /** The water's surface above the floor, and the rim's top. */
  wy: number; rim: number;
  /** The main pool's water. */
  pool: Pool;
  /** Round pools (a splash pool): centre and radius. */
  rounds: (Pt & { r: number })[];
  /** Lanes: how many, and which way they run (the pool's longer side). */
  lanes: number; along: 'x' | 'z';
  /** A race's walls along that way: the start (where the blocks are) and the turn (short of a diving well). */
  race: { start: number; turn: number };
  boards: Board[];
  slides: Slide[];
  loungers: (Pt & { yaw: number })[];
  /** Seats in a stand (top of the seat), if it has one. */
  seats: P3[];
  /** Somewhere a lifeguard sits. */
  guard: P3 | null;
  /** The changing rooms' door, where bathers come out and go home. */
  door: Pt;
  /** The deck: strips round the water to stand, walk and sit on. */
  deck: Pool[];
  /** The scoreboard's face: its middle, and the way it faces (yaw about y, 0 = +z), if the model has one. */
  board: P3 | null; boardYaw: number;
  /** A roof that closes out of summer (the hall): nobody is seen swimming under it then. */
  roofed: boolean;
}

/** The water's surface and the rim's top, above the lot's floor. */
export const WATER_Y = 0.055, RIM_Y = 0.05;

/** The width and depth a building's model is drawn at (townMesh drawBuilding). */
export function lidoDims(b: Building): { W: number; D: number } {
  const alongZ = b.facing % 2 === 1;
  return { W: alongZ ? b.w : b.d, D: alongZ ? b.d : b.w };
}

/** The model's frame on its island: the lot's middle, its floor and its turn (Kit.place in drawBuilding). */
export function lidoFrame(b: Building): { ox: number; oy: number; oz: number; yaw: number } {
  return { ox: b.x + b.w / 2, oy: b.level * STEP, oz: b.z + b.d / 2, yaw: Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]) };
}

/** A point in the model's frame on the island. */
export function lidoToIsland(b: Building, x: number, z: number): Pt {
  const f = lidoFrame(b), c = Math.cos(f.yaw), s = Math.sin(f.yaw);
  return { x: f.ox + x * c + z * s, z: f.oz - x * s + z * c };
}

/** The free ground an alternative lays itself out on, in its own frame: x' ax0..ax1 (the long way), z' az0..az1. */
export function freeArea(W: number, D: number): { rot: boolean; ax0: number; ax1: number; az0: number; az1: number } {
  const rot = W < D;
  // the changing block takes the +x end of the lot: the long way when it is wide, the +z' side when it is turned
  return rot
    ? { rot, ax0: -D / 2 + 0.05, ax1: D / 2 - 0.05, az0: -W / 2 + 0.05, az1: W / 2 - 0.6 }
    : { rot, ax0: -W / 2 + 0.05, ax1: W / 2 - 0.6, az0: -D / 2 + 0.05, az1: D / 2 - 0.05 };
}

/** The changing block: its middle, depth, and the front of its door side (the side facing the water). */
export const blockOf = (W: number, D: number) => ({ cx: W / 2 - 0.3, cz: 0.1, w: 0.44, d: Math.min(1.4, D - 0.6) });

/** Lay out a model on a W × D lot. */
export function lidoPlan(W: number, D: number, model: number): LidoPlan {
  return model === LIDO_CLASSIC ? classic(W, D) : alternative(W, D, model);
}

/** The kind's own model (venues.ts lido): its pool, platform and slide where it draws them. */
function classic(W: number, D: number): LidoPlan {
  const pw = W - 0.9, pd = D - 0.6, pz = 0.1, px = -0.25;
  const pool = { x0: px - pw / 2, x1: px + pw / 2, z0: pz - pd / 2, z1: pz + pd / 2 };
  const post = pool.x0 + 0.1;
  const blk = blockOf(W, D);
  return {
    model: LIDO_CLASSIC, W, D, wy: WATER_Y, rim: RIM_Y, pool, rounds: [],
    lanes: 5, along: 'x', race: { start: pool.x1, turn: pool.x0 },
    boards: [{ foot: { x: pool.x0 - 0.04, z: pz + 0.12 }, top: [post, 0.49, pz], tip: [post + 0.22, 0.49, pz], spring: false }],
    slides: [{
      path: [[W / 2 - 0.55, 0.36, pz - 0.2], [px + pw / 2 - 0.1, WATER_Y, pz + 0.3]],
      foot: { x: W / 2 - 0.58, z: pz - 0.42 }, top: [W / 2 - 0.55, 0.36, pz - 0.24],
    }],
    loungers: Array.from({ length: 6 }, (_, i) => ({ x: -W / 2 + 0.3 + i * 0.3, z: D / 2 - 0.12, yaw: 0 })),
    seats: [], guard: null,
    door: { x: blk.cx - blk.w / 2 - 0.04, z: pz + 0.3 },
    deck: [
      { x0: pool.x0, x1: pool.x1, z0: -D / 2 + 0.06, z1: pool.z0 - 0.08 },
      { x0: -W / 2 + 0.08, x1: pool.x0 - 0.08, z0: pool.z0, z1: pool.z1 },
      { x0: pool.x1 + 0.07, x1: blk.cx - blk.w / 2 - 0.03, z0: pool.z0, z1: pool.z1 },
    ],
    board: null, boardYaw: 0, roofed: false,
  };
}

/** One of the alternatives, laid out in its own frame and turned back into the model's. */
function alternative(W: number, D: number, model: number): LidoPlan {
  const A = freeArea(W, D);
  // the turn back: (x', z') in the alternative's frame to (x, z) in the model's
  const P = (x: number, z: number): Pt => (A.rot ? { x: z, z: -x } : { x, z });
  const P3 = (x: number, y: number, z: number): P3 => { const q = P(x, z); return [q.x, y, q.z]; };
  const R = (x0: number, z0: number, x1: number, z1: number): Pool => {
    const a = P(x0, z0), b = P(x1, z1);
    return { x0: Math.min(a.x, b.x), x1: Math.max(a.x, b.x), z0: Math.min(a.z, b.z), z1: Math.max(a.z, b.z) };
  };
  const blk = blockOf(W, D);
  const door = { x: blk.cx - blk.w / 2 - 0.04, z: blk.cz + Math.min(0.3, blk.d / 2 - 0.1) };
  const yaw = (y: number) => (A.rot ? y + Math.PI / 2 : y);
  const L = layout(model, A);
  const lanes = Math.max(3, Math.min(6, Math.floor((L.pz1 - L.pz0) / 0.17)));
  return {
    model, W, D, wy: WATER_Y, rim: RIM_Y,
    pool: R(L.px0, L.pz0, L.px1, L.pz1),
    rounds: L.rounds.map((c) => ({ ...P(c.x, c.z), r: c.r })),
    lanes: model === LIDO_SLIDES ? Math.min(lanes, 4) : lanes, along: A.rot ? 'z' : 'x',
    // the blocks are at the +x' end; the turn is short of the boards' diving well (x' turns to -z when turned)
    race: A.rot ? { start: -L.px1, turn: -(L.px0 + (model === LIDO_BOARDS ? 0.44 : 0)) } : { start: L.px1, turn: L.px0 + (model === LIDO_BOARDS ? 0.44 : 0) },
    boards: L.boards.map((b) => ({ foot: P(b.foot.x, b.foot.z), top: P3(...b.top), tip: P3(...b.tip), spring: b.spring })),
    slides: L.slides.map((s) => ({ path: s.path.map((p) => P3(...p)), foot: P(s.foot.x, s.foot.z), top: P3(...s.top) })),
    loungers: L.loungers.map((l) => ({ ...P(l.x, l.z), yaw: yaw(l.yaw) })),
    seats: L.seats.map((p) => P3(...p)),
    guard: L.guard ? P3(...L.guard) : null,
    door,
    deck: L.deck.map((d) => R(d.x0, d.z0, d.x1, d.z1)),
    board: L.board ? P3(...L.board) : null, boardYaw: yaw(L.boardYaw),
    roofed: model === LIDO_HALL,
  };
}

/** An alternative's layout in its own frame (x' the long way, +z' toward the front or the changing block). */
export interface Layout {
  px0: number; px1: number; pz0: number; pz1: number;
  rounds: (Pt & { r: number })[];
  boards: { foot: Pt; top: P3; tip: P3; spring: boolean }[];
  slides: { path: P3[]; foot: Pt; top: P3 }[];
  loungers: (Pt & { yaw: number })[];
  seats: P3[];
  guard: P3 | null;
  deck: Pool[];
  board: P3 | null; boardYaw: number;
  /** Model 1: the tower's middle and the stand's depth; model 2: the slide tower's middle and height. */
  tower: Pt & { h: number; w: number; d: number };
  stand: { x0: number; x1: number; z0: number; z1: number; tiers: number; rise: number } | null;
}

/** The tiers of a stand along the back, x0..x1, from z1 (the front row, nearest the water) back to z0. */
function standSeats(st: NonNullable<Layout['stand']>): P3[] {
  const out: P3[] = [];
  const deep = (st.z1 - st.z0) / st.tiers;
  for (let t = 0; t < st.tiers; t++) {
    const z = st.z1 - deep * (t + 0.5), y = st.rise * (t + 1);
    for (let x = st.x0 + 0.06; x <= st.x1 - 0.05; x += 0.1) out.push([x, y, z]);
  }
  return out;
}

export function layout(model: number, A: ReturnType<typeof freeArea>): Layout {
  const { ax0, ax1, az0, az1 } = A;
  const S = az1 - az0;
  if (model === LIDO_BOARDS) {
    // a racing pool with a diving well at its deep end, a tower of boards beside it and a stand along the back
    const standD = Math.max(0.24, Math.min(0.42, S * 0.24));
    const px0 = ax0 + 0.36, px1 = ax1 - 0.08, pz0 = az0 + standD + 0.08, pz1 = az1 - 0.22;
    const pc = (pz0 + pz1) / 2, pd = pz1 - pz0;
    const tx = ax0 + 0.15;
    const boards = [
      { foot: { x: tx, z: pc + pd * 0.3 + 0.12 }, top: [tx + 0.06, 0.14, pc + pd * 0.3] as P3, tip: [px0 + 0.26, 0.14, pc + pd * 0.3] as P3, spring: true },
      { foot: { x: tx + 0.02, z: pc + 0.16 }, top: [tx + 0.1, 0.33, pc] as P3, tip: [px0 + 0.24, 0.33, pc] as P3, spring: true },
      { foot: { x: tx, z: pc - pd * 0.3 + 0.13 }, top: [tx + 0.08, 0.62, pc - pd * 0.3] as P3, tip: [px0 + 0.2, 0.62, pc - pd * 0.3] as P3, spring: false },
    ];
    const stand = { x0: px0 + 0.1, x1: px1 - 0.36, z0: az0, z1: az0 + standD, tiers: standD >= 0.32 ? 4 : 3, rise: 0.055 };
    const loungers: Layout['loungers'] = [];
    for (let x = px0 + 0.12; x < px1 - 0.05; x += 0.26) loungers.push({ x, z: az1 - 0.1, yaw: Math.PI / 2 });
    return {
      px0, px1, pz0, pz1, rounds: [], boards, slides: [], loungers, seats: standSeats(stand), guard: [px1 - 0.2, 0.2, pz1 + 0.12],
      deck: [{ x0: px0, x1: px1, z0: pz1 + 0.07, z1: az1 - 0.03 }, { x0: px1 - 0.32, x1: px1, z0: az0 + 0.04, z1: pz0 - 0.07 }],
      board: [px1 - 0.16, 0.6, az0 + 0.06], boardYaw: 0,
      tower: { x: tx, z: pc, h: 0.62, w: 0.24, d: pd * 0.75 }, stand,
    };
  }
  if (model === LIDO_SLIDES) {
    // a family lido: the slide tower at the back of the deep end, a flume curling down into a splash pool, a
    // straight speed slide into the main pool, umbrellas and loungers along the front
    const H = 0.72, tx = ax0 + 0.2, tz = az0 + 0.2;
    const sr = Math.max(0.2, Math.min(0.3, S * 0.16));
    const splash = { x: ax0 + 0.08 + sr, z: az1 - 0.08 - sr, r: sr };
    const px0 = splash.x + sr + 0.2, px1 = ax1 - 0.06, pz0 = az0 + 0.24, pz1 = az1 - 0.26;
    // the flume: off the tower's back corner, a coil between it and the splash pool, then a run-out into it
    const cz = (tz + splash.z) / 2, cx = tx + 0.05, cr = Math.max(0.12, Math.min(0.2, (splash.z - tz) / 2 - 0.08));
    const path: P3[] = [[tx - 0.08, H - 0.03, tz + 0.12]];
    const a0 = Math.atan2(tz + 0.12 - cz, tx - 0.08 - cx) + 0.5;
    const turns = 2.3 * Math.PI, n = 16;
    for (let i = 0; i <= n; i++) {
      const t = i / n, a = a0 + t * turns;
      path.push([cx + Math.cos(a) * cr, H - 0.08 - t * (H - 0.26), cz + Math.sin(a) * cr]);
    }
    path.push([splash.x + 0.02, 0.12, splash.z - splash.r * 0.4], [splash.x + 0.04, WATER_Y, splash.z]);
    // the speed slide: a steep drop, a hump, a run-out into the main pool's end
    const sx = tx + 0.14, sz = tz - 0.06, ex = px0 + 0.22, ez = pz0 + 0.18;
    const lerp = (t: number, y: number): P3 => [sx + (ex - sx) * t, y, sz + (ez - sz) * t];
    const speed: P3[] = [[sx, H - 0.03, sz], lerp(0.32, 0.2), lerp(0.48, 0.26), lerp(0.66, 0.12), lerp(0.86, 0.08), [ex, WATER_Y, ez]];
    // the stair up the tower's front corner, clear of both slides
    const foot = { x: tx + 0.28, z: tz + 0.24 };
    const loungers: Layout['loungers'] = [];
    for (let x = px0 + 0.1; x < px1 - 0.05; x += 0.22) loungers.push({ x, z: az1 - 0.1, yaw: Math.PI / 2 });
    return {
      px0, px1, pz0, pz1, rounds: [splash], boards: [],
      slides: [{ path, foot, top: [tx + 0.09, H, tz + 0.09] }, { path: speed, foot, top: [tx + 0.09, H, tz + 0.09] }],
      loungers, seats: [], guard: [px1 - 0.3, 0.24, pz0 - 0.1],
      deck: [{ x0: px0, x1: px1, z0: pz1 + 0.07, z1: az1 - 0.03 }, { x0: px0 + 0.1, x1: px1, z0: az0 + 0.04, z1: pz0 - 0.07 }],
      board: null, boardYaw: 0,
      tower: { x: tx, z: tz, h: H, w: 0.26, d: 0.26 }, stand: null,
    };
  }
  // the aquatic centre: a racing pool in a hall whose glass roof slides back for the summer, a gallery behind
  const standD = Math.max(0.2, Math.min(0.3, S * 0.18));
  const px0 = ax0 + 0.1, px1 = ax1 - 0.12, pz0 = az0 + standD + 0.08, pz1 = az1 - 0.14;
  const stand = { x0: px0 + 0.08, x1: px1 - 0.08, z0: az0 + 0.02, z1: az0 + standD, tiers: 2, rise: 0.07 };
  return {
    px0, px1, pz0, pz1, rounds: [], boards: [], slides: [],
    loungers: [], seats: standSeats(stand), guard: [px0 + 0.1, 0.2, pz1 + 0.08],
    deck: [{ x0: px0, x1: px1, z0: pz1 + 0.06, z1: az1 - 0.03 }],
    board: [ax0 + 0.03, 0.42, (pz0 + pz1) / 2], boardYaw: Math.PI / 2,
    tower: { x: 0, z: 0, h: 0, w: 0, d: 0 }, stand,
  };
}
