/**
 * The first fifteen minutes, for the play reports (src/net/report.ts, the developer's Games tab): what a new
 * player did, in order, and where they were when they stopped. It exists to answer "why do players leave in
 * their first 15 minutes?" (the user, 27 Oct 2026), the way net/perf.ts answers "why do some never drive".
 *
 * Main hands it a small picture of the game once a second (Journey.look); it notes what changed:
 *  - marks: each milestone once, the first time it happens in this game ([play seconds, real seconds into this
 *    visit]), from the welcome card closing to the first delivery, the first vehicle bought and the tutorial done;
 *  - trail: everything worth seeing in order (a mission taken, done or failed, a panel opened, the tutorial's
 *    step, a long stop, a jump across the map, the tab hidden), the last TRAIL_KEPT of them;
 *  - now: the picture itself at the moment of the report, so the last report before someone leaves says what
 *    they were looking at, what the tutorial asked of them and how long they had been standing still.
 * The server keeps every visit's marks and trail for the game (server/admin.ts), so a reload loses nothing.
 * Nothing personal: names of the game's own things only, nothing typed.
 */

/** What main sees each second (main.ts journeyLook). */
export interface JourneyLook {
  played: number;
  /** The first drive's stage (game/tutorial.ts), and the getting-started track's step (missions TRACK). */
  stage: string; track: number;
  /** Missions under way, as template and step; and how many are done and failed in all. */
  active: { tpl: string; step: number; label: string }[];
  done: number; failed: number; offered: number;
  /** The panel in front, if any: 'menu', 'journal', 'card', 'map', 'region', 'hq:<tab>', 'builder', 'terrain', 'garage', 'shop'. */
  panel: string | null;
  /** What the tooltip, guide or hint on screen says, if any (short). */
  tip: string | null;
  speed: number; x: number; z: number; cell: string; model: string;
  cash: number; earned: number; delivered: number; hold: number;
  units: number; drivers: number; hq: number;
  /** The first drive's missions done so far (first:parts … first:drift), and whether it has let the player roam
   *  while the handbrake waits for fifteen minutes of play (game/tutorial.ts roaming). */
  firsts?: string[]; roam?: boolean;
  /**
   * A game begun this visit: the controls used in its first five minutes of play ('A,D,Q,S,W,wheel'…), and how the
   * first drive's camera card closed and what was tried on it ('closed:QEP', 'timeout:'); game/tutorial.ts controls.
   */
  controls?: { used: string; camera: string };
}

export interface JourneyReport {
  /** This visit (a page load): its id, and the play seconds it began at. */
  visit: string; from: number;
  marks: Record<string, [number, number]>;
  /** [play seconds, real seconds into the visit, what, detail]. */
  trail: [number, number, string, string?][];
  now: JourneyLook & { still: number; wall: number };
  /** Seconds stood still in all (a panel open or not), and the longest stretch. */
  idle: { total: number; longest: number };
}

/** Trail entries kept by the game between reports (the server keeps more, merged across visits). */
const TRAIL_KEPT = 160;
/** Standing still this long is noted (and again at each multiple of it). */
const STILL_NOTE = 45;

const round = (v: number) => Math.round(v);

export class Journey {
  private visit = Array.from(crypto.getRandomValues(new Uint8Array(6)), (b) => b.toString(16).padStart(2, '0')).join('');
  private t0 = performance.now();
  private from: number | null = null;
  private marks: Record<string, [number, number]> = {};
  private trail: [number, number, string, string?][] = [];
  private last: JourneyLook | null = null;
  private still = 0;
  private idle = { total: 0, longest: 0 };
  private wait = 0;

  /** A game begun or loaded: a new picture (the server keeps what an earlier visit to the same game noted). */
  restart(): void { this.last = null; this.still = 0; this.from = null; this.marks = {}; this.trail = []; this.idle = { total: 0, longest: 0 }; }

  private wall(): number { return round((performance.now() - this.t0) / 1000); }

  /** Something happened: onto the trail, and a milestone the first time. */
  note(what: string, detail?: string, mark?: string): void {
    const played = round(this.last?.played ?? 0);
    this.trail.push(detail ? [played, this.wall(), what, detail.slice(0, 80)] : [played, this.wall(), what]);
    if (this.trail.length > TRAIL_KEPT) this.trail.splice(0, this.trail.length - TRAIL_KEPT);
    if (mark && !this.marks[mark]) this.marks[mark] = [played, this.wall()];
  }

  /** Once a second from main (it may be called every frame: it looks once a second). */
  look(dt: number, see: () => JourneyLook | null): void {
    this.wait -= dt;
    if (this.wait > 0) return;
    const step = 1 - this.wait;
    this.wait = 1;
    const now = see();
    if (!now) return;
    if (this.from === null) { this.from = now.played; this.note('visit', `at ${round(now.played)} s played`, 'play'); }
    const was = this.last;
    // standing still, in a panel or out of one: a stop long enough to be stuck, or lost, or reading a card
    if (Math.abs(now.speed) < 0.15) {
      this.still += step;
      this.idle.total += step;
      this.idle.longest = Math.max(this.idle.longest, this.still);
      if (this.still >= STILL_NOTE && Math.floor(this.still / STILL_NOTE) !== Math.floor((this.still - step) / STILL_NOTE)) {
        this.note('still', `${round(this.still)} s · ${now.panel ? `in ${now.panel} · ` : ''}${now.stage}${now.active[0] ? ` · ${now.active[0].tpl} ${now.active[0].label}` : ''}${now.tip ? ` · tip: ${now.tip}` : ''}`);
      }
    } else this.still = 0;
    if (was) {
      if (now.stage !== was.stage) this.note('tutorial', now.stage, `tut:${now.stage}`);
      if (now.track !== was.track) this.note('track', String(now.track), `track:${now.track}`);
      if (now.panel !== was.panel && now.panel) this.note('panel', now.panel, `panel:${now.panel.split(':')[0]}`);
      if (now.tip !== was.tip && now.tip) this.note('tip', now.tip);
      for (const m of now.active) {
        const before = was.active.find((q) => q.tpl === m.tpl);
        if (!before) this.note('took', `${m.tpl} · ${m.label}`, this.marks.took ? undefined : 'took');
        else if (before.step !== m.step) this.note('step', `${m.tpl} ${m.step} · ${m.label}`);
      }
      for (const m of was.active) {
        if (now.active.some((q) => q.tpl === m.tpl)) continue;
        this.note('ended', m.tpl);
      }
      if (now.done > was.done) this.note('done', String(now.done), 'missionDone');
      if (now.failed > was.failed) this.note('failed', String(now.failed), 'missionFailed');
      if (now.offered > was.offered) this.note('offered', String(now.offered), 'offered');
      if (now.hold > was.hold) this.note('pickup', String(now.hold), 'pickup');
      if (now.delivered > was.delivered) this.note('delivered', String(now.delivered), 'delivered');
      if (now.earned > was.earned && !this.marks.earned) this.note('earned', `$${round(now.earned)}`, 'earned');
      if (now.units > was.units) this.note('vehicle', `${now.units} units`, 'vehicle');
      if (now.drivers > was.drivers) this.note('driver', `${now.drivers} drivers`, 'driver');
      if (now.hq > was.hq) this.note('hq', `grade ${now.hq}`, 'hq');
      // each of the first drive's missions done (did:first:nitrous …), and the free roam before the handbrake
      for (const t of now.firsts ?? []) if (!(was.firsts ?? []).includes(t)) this.note('lesson', t, `did:${t}`);
      if (now.roam && !was.roam) this.note('roam', undefined, 'roam');
      if (now.model !== was.model) this.note('ride', now.model);
      if (now.cell !== was.cell) this.note('county', now.cell, 'county');
      // a jump across the map: a tow home, an airlift, a ferry, a fast travel
      else if (Math.hypot(now.x - was.x, now.z - was.z) > 25) this.note('jump', `${round(Math.hypot(now.x - was.x, now.z - was.z))} tiles`);
      // the first drive over: done (its last stage) or skipped
      if (was.stage !== 'off' && now.stage === 'off') this.note('tutorialEnd', was.stage, 'tutorialEnd');
    }
    // milestones that are only a state reached
    if (now.played >= 300 && !this.marks.min5) this.note('5 min', undefined, 'min5');
    if (now.played >= 900 && !this.marks.min15) this.note('15 min', undefined, 'min15');
    this.last = now;
  }

  /** The tab hidden, or the page left: onto the trail (the report that goes with it says where they were). */
  away(why: string): void { if (this.last) this.note('away', why); }

  report(): JourneyReport | null {
    const now = this.last;
    if (!now) return null;
    return {
      visit: this.visit, from: round(this.from ?? now.played),
      marks: { ...this.marks }, trail: this.trail.slice(),
      now: { ...now, played: round(now.played), speed: Math.round(now.speed * 10) / 10, cash: round(now.cash), earned: round(now.earned), x: round(now.x), z: round(now.z), still: round(this.still), wall: this.wall() },
      idle: { total: round(this.idle.total), longest: round(this.idle.longest) },
    };
  }
}
