import { N } from '../world/tiles';
import { railLines } from '../world/rail';
import { hashString } from '../world/rng';
import { SETS, type TrainSet } from './rollingStock';
import { allowed, sampleAt, type Loc, type Track, type Train, type Trains } from './trains';
import { FAR_DWELL, drawFar, farDests, farPoint, farRoute, farStation, legTime, reversedRoute, type FarWire } from './farRun';
import type { StationRef } from '../world/rail';
import type { SiteKind } from './cargoTypes';
import { beatFor, customBeat, endOf, serves, stationsInReach, type Beat, type BeatKind } from './railBeat';
import type { BeatEnd } from './orders';
import { MODES, TEMPER, modeOf, type Driver } from './drivers';
import type { Unit } from './fleet';
import type { VehicleDef } from './vehicles';
import type { RailStation } from '../world/tiles';
import type { BeatWork, CargoItem } from './cargo';

/**
 * Hired train drivers (docs/crewtrains.html, phase 1): one of the player's trains with a driver at the regulator, put on
 * the line where it stands and run up and down its beat by the dispatcher (game/trains.ts), which never takes it off.
 * This is the fleet's side of it: which train is whose, putting one on and taking it back, and its beat kept in step
 * with the track in memory. Loads and pay come in phase 2; for now it runs its beat and calls at every stop.
 */

/** Tiles from where a train was left to the track it is put on: as near as the player rides one from. */
const ON_TRACK = 6;
/** A county's neighbour across each of its sides, as world/rail.ts numbers them. */
const SIDE_DX = [1, 0, -1, 0], SIDE_DZ = [0, 1, 0, -1];
/** Most crewed trains on one connected stretch of track at once. */
export const CREW_PER_NETWORK = 4;

export interface RailCrewHost {
  trains: Trains;
  seed(): string;
  /** A county's world in memory, or null. */
  worldAt(cx: number, cz: number): { cx: number; cz: number; ox: number; oz: number } | null;
  driverOf(u: Unit): Driver | null;
  /** What a freight's wagons carry: what the county it was bought in makes. */
  producers(u: Unit): string[] | undefined;
  /** A crewed train's track has gone from memory: the fleet takes it back as out of sight, where it stood. */
  lost(u: Unit, at: Spot): void;
  /** The unit a crewed train belongs to. */
  unit(uid: number): Unit | null;
  /** At a call: what is aboard for here is handed in, and what waits for the beat comes aboard (cargo.crewCall). */
  call(u: Unit, st: RailStation, beat: RailStation[], ahead: RailStation[], aboard: CargoItem[]): { drop: CargoItem[]; take: CargoItem[] };
  /** A load handed in at a world point: paid as any driver's delivery. */
  paid(u: Unit, it: CargoItem, at: { x: number; y: number; z: number }): void;
  /** Where the HQ stands, in world tiles: where a train with no line comes out of the sheds nearest to. */
  hq?(): { x: number; z: number } | null;
  /** The fleet's colours, for a crewed train's livery; null for a fleet with none. */
  livery(): [number, number] | null;
  /** Long haul: a load at a beat's end bound for one of these far stations, taken aboard at once (cargo.crewLong). */
  long?(u: Unit, st: RailStation, room: number, dests: StationRef[]): CargoItem | null;
  /** At the far station: return loads for those handed in, bound for the beat's end (cargo.railBack). */
  back?(u: Unit, done: CargoItem[], home: FarEnd): CargoItem[];
  /** A saved far run's load aboard again (cargo.farCarried). */
  restore?(u: Unit, k: FarLoad): CargoItem | null;
  /** A far run has begun a leg (or is back: null), for the other games near its route (net/online.ts). */
  sendFar?(uid: number, w: FarWire | null): void;
}

/** The beat end a far run left from and comes back to: where it stands, as the cargo and the fleet need it. */
export interface FarEnd { name: string; kind: SiteKind; x: number; y: number; z: number; cx: number; cz: number; spot: Spot }
/** A far run's load as a save keeps it. */
export interface FarLoad { type: string; value: number; to: { name: string; kind: string; x: number; z: number; cx: number; cz: number } }
/** A far run as a unit's save keeps it (docs/crewtrains.html): the leg, its clock, where it left and its loads. */
export interface FarSave {
  leg: 'out' | 'back';
  w: FarWire;
  /** The county it left (and comes back into) and the side it left by. */
  home: { cx: number; cz: number; side: number };
  end: FarEnd;
  paid?: boolean;
  loads: FarLoad[];
}

/** Seconds between long-haul offers at one end of a beat. */
const LONG_EVERY = 90;
/** A long haul's far station: counties on along the line past the beat's end, nearest and farthest. */
const LONG_MIN = 5, LONG_MAX = 14;
/** Seconds a train back from its far run waits at the border for the line to clear before it stands at its beat's end out of sight. */
const BACK_WAIT = 120;

/** Where a unit stands, the way the fleet keeps it. */
export interface Spot { cx: number; cz: number; x: number; z: number; y: number; heading: number }

export class RailCrew {
  private byUid = new Map<number, Train>();
  /** What each crewed train has aboard, by unit: kept while it is off the line too (out of sight), lost with the session. */
  private holds = new Map<number, CargoItem[]>();
  /** For the console and the gate: put on, refused (and why), beats worked out again, loads handed in and taken on. */
  readonly stats = { placed: 0, refused: 0, rebeat: 0, lost: 0, delivered: 0, loaded: 0, longOffered: 0, farLeft: 0, farPaid: 0, farBack: 0, farShadowed: 0, farTurned: 0 };
  /** Far runs, by unit: kept on the unit as its save slot too (Unit.far). */
  private far = new Map<number, { u: Unit; f: FarSave; wait: number; sent: number }>();
  /** The beat end each long haul aboard was taken on at: where the train runs on from. */
  private longEnd = new Map<CargoItem, string>();
  /** When each end of each unit's beat last offered a long haul (seconds of play this session). */
  private offered = new Map<string, number>();
  private clock = 0;
  readonly refusals: string[] = [];

  constructor(private host: RailCrewHost) {
    const tr = host.trains;
    tr.onCrewCall = (t, st) => this.called(t, st);
    tr.onCrewLost = (t) => {
      const u = t.crew ? host.unit(t.crew.uid) : null;
      const at = this.spotOf(t);
      if (t.crew) this.byUid.delete(t.crew.uid);
      this.stats.lost++;
      if (u && at) host.lost(u, at);
    };
    tr.onNetChanged = () => this.rebeatAll();
    tr.onCrewFar = (t, exit) => this.leave(t, exit);
  }

  private setOf(def: VehicleDef): TrainSet | null { return SETS.find((s) => s.id === (def as { set?: string }).set) ?? null; }
  private kindOf(set: TrainSet): BeatKind { return { freight: set.freight, rack: !!set.rack }; }

  /** How fast a driver runs their train: their temper, and what the cut has them do. */
  private paceOf(d: Driver | null): number {
    if (!d) return 1;
    return TEMPER[d.temper].pace + MODES[modeOf(d.cut)].pace;
  }

  /** The train a unit's driver is running, if it is on the line. */
  train(u: Unit): Train | null {
    const tr = this.byUid.get(u.uid) ?? null;
    if (tr && !this.host.trains.trains.includes(tr)) { this.byUid.delete(u.uid); return null; }
    return tr;
  }
  running(u: Unit): boolean { return !!this.train(u) || this.far.has(u.uid); }
  /** On a far run, out of memory (docs/crewtrains.html, Long haul). */
  away(u: Unit): boolean { return this.far.has(u.uid); }
  /** The units away on far runs. */
  farUnits(): Unit[] { return [...this.far.values()].map((r) => r.u); }

  /**
   * Put a crewed train on the line where the unit stands: its beat worked out from its order (the whole line within
   * reach by default). Null when it is on, else why not (the fleet holds it with that line and tries again).
   */
  run(u: Unit, def: VehicleDef): string | null {
    if (this.train(u)) return null;
    const set = this.setOf(def);
    if (!set) return 'Not a train';
    const w = this.host.worldAt(u.cx, u.cz);
    if (!w && !u.sheds) return 'Its county is not in memory yet';
    const trains = this.host.trains;
    let near = w && !u.sheds ? trains.net.nearest(w.ox + u.x, w.oz + u.z, ON_TRACK, !!set.rack) : null;
    // left away from any line (or brought out of the garage): it comes out of the sheds at a station
    if (!near) {
      const sheds = this.shedsAt(u, set);
      if (!sheds) return this.refuse(u, 'No station in memory to bring it out at: ride it onto a line first');
      Object.assign(u, sheds.spot);
      u.order.beat = { home: [sheds.spot.cx, sheds.spot.cz], ...(u.order.beat?.custom ? { custom: u.order.beat.custom } : {}) };
      near = trains.net.nearest(sheds.gx, sheds.gz, ON_TRACK, !!set.rack);
      if (!near) return this.refuse(u, 'No track at the sheds');
    }
    const order = u.order.beat ?? (u.order.beat = { home: [u.cx, u.cz] });
    const got = beatFor(trains.net, this.kindOf(set), order, near.loc);
    if (!got.beat) return this.refuse(u, got.why);
    const busy = trains.crewOnNetwork(near.loc.t).length;
    if (busy >= CREW_PER_NETWORK) return this.refuse(u, `${CREW_PER_NETWORK} of your trains already work this line`);
    const d = this.host.driverOf(u);
    const placed = trains.placeCrew(set, near.loc, got.beat, { uid: u.uid, driver: d?.name ?? 'a driver', name: u.name, pace: this.paceOf(d), paint: this.host.livery() ?? undefined },
      hashString(`${this.host.seed()}:${def.id}:${u.uid}`), set.freight ? this.host.producers(u) : undefined);
    if (typeof placed === 'string') return this.refuse(u, placed);
    this.byUid.set(u.uid, placed);
    delete u.sheds;
    this.stats.placed++;
    return null;
  }

  /**
   * Where a train with no line under it comes out of the sheds (docs/crewtrains.html): the nearer end of the beat it
   * last had a choice of (Custom's), else the station in memory nearest the HQ, else nearest where it was left.
   * Its platform's middle, as a spot and in world tiles.
   */
  shedsAt(u: Unit, set: TrainSet): { spot: Spot; gx: number; gz: number } | null {
    const trains = this.host.trains;
    const kind = this.kindOf(set);
    const hq = this.host.hq?.() ?? null;
    const w0 = this.host.worldAt(u.cx, u.cz);
    const from = hq ?? (w0 ? { x: w0.ox + u.x, z: w0.oz + u.z } : null);
    const ends = u.order.beat?.custom ? [u.order.beat.custom.a, u.order.beat.custom.b] : [];
    let best: { t: Track; s: number; d: number } | null = null;
    const p = { x: 0, y: 0, z: 0, ang: 0 };
    for (const t of trains.net.tracks.values()) {
      if (t.p.kind === 'loop' || (t.p.oneWay && !t.twin) || t.p.key.startsWith('rack:') !== kind.rack) continue;
      for (const { st, loop } of t.stations) {
        if (loop || st.passing) continue;
        const real = st.of ?? st;
        const mid = (st.s0 + st.s1) / 2;
        sampleAt(t, mid, p);
        const named = ends.some((e) => e.cx === t.w.cx && e.cz === t.w.cz && e.name === real.name);
        // a Custom end first, then one this train calls at, then any, nearest the HQ
        const d = (named ? 0 : 1e7) + (serves(kind, real) ? 0 : 1e6) + (from ? Math.hypot(p.x - from.x, p.z - from.z) : 0);
        if (!best || d < best.d) best = { t, s: mid, d };
      }
    }
    if (!best) return null;
    sampleAt(best.t, best.s, p);
    const cx = Math.floor(p.x / N), cz = Math.floor(p.z / N);
    return { spot: { cx, cz, x: p.x - cx * N, z: p.z - cz * N, y: p.y, heading: p.ang }, gx: p.x, gz: p.z };
  }

  private refuse(_u: Unit, why: string): string {
    this.stats.refused++;
    this.refusals.push(why);
    if (this.refusals.length > 20) this.refusals.shift();
    return why;
  }

  /** Take a crewed train off the line (its driver benched, the player at the regulator): where it stood, or null. */
  stop(u: Unit): Spot | null {
    const tr = this.train(u);
    if (!tr) return null;
    const at = this.spotOf(tr);
    this.byUid.delete(u.uid);
    this.host.trains.remove(tr);
    return at;
  }

  /** Where a train's engine stands, as a unit's spot: its county and the tile in it. */
  spotOf(tr: Train): Spot | null {
    const f = tr.trail[0];
    if (!f) return null;
    const p = sampleAt(f.t, f.b, { x: 0, y: 0, z: 0, ang: 0 });
    const cx = Math.floor(p.x / N), cz = Math.floor(p.z / N);
    // (the engine faces back along the trail when it runs reversed: the unit keeps the way it is going)
    return { cx, cz, x: p.x - cx * N, z: p.z - cz * N, y: p.y, heading: f.d > 0 ? p.ang : p.ang + Math.PI };
  }

  /** A crewed train has called at a station of its beat: hand in, load up, and say how many loads that was. */
  private called(tr: Train, st: RailStation): number {
    const u = tr.crew ? this.host.unit(tr.crew.uid) : null;
    if (!u || !tr.crew) return 0;
    const b = tr.crew.beat;
    const order = b.stops.map((s) => s.st);
    const i = order.indexOf(st);
    // the stops still to come: at an end, the whole way back; else on toward the end it is bound for
    const toB = i === 0 || (i !== order.length - 1 && tr.to === b.ends[1].name);
    const ahead = i < 0 ? [] : toB ? order.slice(i + 1) : order.slice(0, i).reverse();
    const aboard = this.aboard(u);
    const { drop, take } = this.host.call(u, st, order, ahead, aboard);
    const m = this.host.trains.middle(tr);
    const at = m ?? { x: 0, y: 0, z: 0 };
    for (const it of drop) this.host.paid(u, it, at);
    const hold = [...aboard.filter((it) => !drop.includes(it)), ...take];
    this.holds.set(u.uid, hold);
    this.stats.delivered += drop.length;
    this.stats.loaded += take.length;
    for (const it of drop) this.longEnd.delete(it);
    return drop.length + take.length + this.longAt(u, tr, st, hold);
  }

  /** A long haul aboard bound past the beat (not a return load for one of its stops). */
  private outbound(b: Beat, it: CargoItem): boolean { return !!it.longHaul && !b.stops.some((s) => s.name === it.to.name); }

  /**
   * Long haul at an end of the beat (docs/crewtrains.html): one aboard taken on here, and the train runs on past this end
   * after the call; none aboard, and now and then one is offered here, bound 5–14 counties on, and taken if it fits
   * (the train finishes the run back along the beat first). How many loads that was.
   */
  private longAt(u: Unit, tr: Train, st: RailStation, hold: CargoItem[]): number {
    const c = tr.crew, b = c?.beat;
    if (!c || !b || !b.ends.some((e) => e.st === st)) return 0;
    const out = hold.filter((it) => this.outbound(b, it));
    const mine = out.find((it) => this.longEnd.get(it) === st.name);
    if (mine) { c.runOn = { end: st, to: mine.to.name }; return 0; }
    if (out.length || !this.host.long || !u.order.beat?.long) return 0;
    const key = `${u.uid}|${st.name}`;
    if (this.clock - (this.offered.get(key) ?? -Infinity) < LONG_EVERY) return 0;
    this.offered.set(key, this.clock);
    const set = SETS.find((q) => q.id === u.model);
    if (!set) return 0;
    const end = b.ends.find((e) => e.st === st)!;
    const dests = farDests(hashString(this.host.seed()), end.cx, end.cz, b.cells, LONG_MIN, LONG_MAX).map((d) => d.st);
    const room = set.capacity - hold.reduce((n, it) => n + it.type.units, 0);
    const it = this.host.long(u, st, room, dests);
    if (!it) return 0;
    hold.push(it);
    this.longEnd.set(it, st.name);
    this.stats.longOffered++;
    return 1;
  }

  /** Whether the line runs on past either end of a unit's beat to a far station (the Long haul pill is shown only then). */
  longOk(u: Unit): boolean {
    const b = this.beat(u);
    if (!b) return !!u.far;
    const sh = hashString(this.host.seed());
    return b.ends.some((e) => farDests(sh, e.cx, e.cz, b.cells, LONG_MIN, LONG_MAX).length > 0);
  }

  /** A crewed train running on past its beat's end has reached the edge of memory: its far run begins. False: it turns back. */
  private leave(tr: Train, exit: { cx: number; cz: number; side: number }): boolean {
    const u = tr.crew ? this.host.unit(tr.crew.uid) : null;
    const b = tr.crew?.beat;
    if (!u || !b) return false;
    const sh = hashString(this.host.seed());
    const hold = this.aboard(u);
    const long = hold.filter((it) => this.outbound(b, it));
    const it = long[0];
    let cells = it ? farRoute(sh, exit.cx, exit.cz, exit.side, { cx: it.longHaul!.cell[0], cz: it.longHaul!.cell[1] }) : null;
    if (it && !cells) {
      // the line it ran on doesn't reach the far station (a turnout the plan reads the other way): the farthest station
      // of a kind it is bound for along the way it went instead
      const all = farRoute(sh, exit.cx, exit.cz, exit.side, null) ?? [];
      for (let i = all.length - 1; i >= 0 && !cells; i--) {
        const st = farStation(sh, [{ ...all[i], exit: -1 }]);
        if (!st || i < LONG_MIN - 2 || !it.type.to.includes(st.kind)) continue;
        cells = [...all.slice(0, i), { ...all[i], exit: -1 }];
        for (const q of long) { q.to = { ...q.to, name: st.name, kind: st.kind, x: (st.cx + 0.5) * N, z: (st.cz + 0.5) * N }; q.longHaul = { ...q.longHaul!, cell: [st.cx, st.cz] }; }
      }
    }
    if (!it || !cells) { this.stats.farTurned++; return false; }
    const endStop = b.ends.find((e) => e.name === this.longEnd.get(it)) ?? b.ends[1];
    const p = sampleAt(endStop.t, endStop.s, { x: 0, y: 0, z: 0, ang: 0 });
    const ecx = Math.floor(p.x / N), ecz = Math.floor(p.z / N);
    const end: FarEnd = { name: endStop.name, kind: endStop.st.kind as SiteKind, x: p.x, y: p.y, z: p.z, cx: endStop.cx, cz: endStop.cz,
      spot: { cx: ecx, cz: ecz, x: p.x - ecx * N, z: p.z - ecz * N, y: p.y, heading: p.ang } };
    // a county's run at its top speed, with a little over for the stations passed through
    const spc = (N / Math.max(0.5, tr.vMax)) * 1.1;
    const w: FarWire = { uid: u.uid, m: u.model, n: u.name, ids: tr.cars.map((c) => c.id), cells, spc, t: 0, dwell: FAR_DWELL };
    const f: FarSave = { leg: 'out', w, home: exit, end, loads: [] };
    this.byUid.delete(u.uid);
    this.far.set(u.uid, { u, f, wait: 0, sent: 0 });
    u.far = f;
    this.stats.farLeft++;
    this.host.sendFar?.(u.uid, w);
    return true;
  }

  /**
   * The far runs' clocks (docs/crewtrains.html), every frame of play: the stand-in drawn where the clock puts it when that
   * county is in memory, the far station's pay at the end of the way out, the way back, and coming back in at the border.
   */
  tick(dt: number): void {
    this.clock += dt;
    if (!this.far.size) return;
    const sh = hashString(this.host.seed());
    for (const [uid, r] of [...this.far]) {
      const { u, f } = r;
      if (!this.host.unit(uid)) { this.endFar(uid); continue; }
      f.w.t += dt;
      const total = legTime(f.w);
      drawFar(this.host.trains, sh, `me:${uid}`, f.w, f.w.t, { paint: this.host.livery() ?? undefined, what: `Your fleet · long haul · ${this.host.driverOf(u)?.name ?? 'a driver'} at the regulator` });
      if ((r.sent += dt) > 20) { r.sent = 0; this.host.sendFar?.(uid, f.w); }
      if (f.leg === 'out' && f.w.t >= total && !f.paid) this.arrive(r);
      if (f.leg === 'out' && f.w.t >= total + f.w.dwell) {
        f.leg = 'back';
        f.w = { ...f.w, cells: reversedRoute(f.w.cells), t: 0, dwell: 0 };
        f.paid = false;
        this.host.sendFar?.(uid, f.w);
        continue;
      }
      if (f.leg === 'back' && f.w.t >= total) this.comeBack(r, dt);
    }
    // (what is aboard kept on the save slot, so a save mid-leg carries it)
    for (const r of this.far.values()) {
      r.f.loads = this.aboard(r.u).filter((it) => it.longHaul).map((it) => ({ type: it.type.id, value: it.value, to: { name: it.to.name, kind: it.to.kind, x: it.to.x, z: it.to.z, cx: it.longHaul!.cell[0], cz: it.longHaul!.cell[1] } }));
    }
  }

  /** At the far station: its long hauls paid there, return loads for the beat's end aboard. */
  private arrive(r: { u: Unit; f: FarSave }): void {
    const { u, f } = r;
    f.paid = true;
    const hold = this.aboard(u);
    const last = f.w.cells[f.w.cells.length - 1];
    const done = hold.filter((it) => it.longHaul && it.longHaul.cell[0] === last.cx && it.longHaul.cell[1] === last.cz && it.to.name !== f.end.name);
    const at = { x: (last.cx + 0.5) * N, y: 0, z: (last.cz + 0.5) * N };
    for (const it of done) { this.host.paid(u, it, at); this.longEnd.delete(it); }
    const back = this.host.back?.(u, done, f.end) ?? [];
    this.holds.set(u.uid, [...hold.filter((it) => !done.includes(it)), ...back]);
    this.stats.farPaid += done.length;
    this.stats.delivered += done.length;
  }

  /** Back at the border it left by: on the line again there, heading in; out of sight at its beat's end when it can't be. */
  private comeBack(r: { u: Unit; f: FarSave; wait: number }, dt: number): void {
    const { u, f } = r;
    const set = SETS.find((q) => q.id === u.model);
    const trains = this.host.trains;
    const w = this.host.worldAt(f.home.cx, f.home.cz);
    let front: Loc | null = null;
    if (w && set) {
      for (const t of trains.net.tracks.values()) {
        if (t.w.cx !== f.home.cx || t.w.cz !== f.home.cz || t.p.kind === 'loop') continue;
        if (t.p.start.kind === 'border' && t.p.start.side === f.home.side && allowed(t, 0, 1)) front = { t, s: 0, dir: 1 };
        else if (t.p.end.kind === 'border' && t.p.end.side === f.home.side && allowed(t, t.p.length, -1)) front = { t, s: t.p.length, dir: -1 };
        if (front) break;
      }
    }
    const order = u.order.beat ?? (u.order.beat = { home: [f.end.cx, f.end.cz] });
    const got = front && set ? beatFor(trains.net, this.kindOf(set), order, front) : null;
    if (front && set && got?.beat) {
      const d = this.host.driverOf(u);
      const placed = trains.placeCrewIn(set, front, got.beat, { uid: u.uid, driver: d?.name ?? 'a driver', name: u.name, pace: this.paceOf(d), paint: this.host.livery() ?? undefined },
        hashString(`${this.host.seed()}:${u.model}:${u.uid}`), set.freight ? this.host.producers(u) : undefined);
      if (typeof placed !== 'string') {
        this.byUid.set(u.uid, placed);
        this.stats.farBack++;
        this.endFar(u.uid);
        return;
      }
    }
    // its beat out of memory, or the line in held too long: out of sight at the end it left from, back the usual way
    if (!w || (r.wait += dt) > BACK_WAIT) {
      this.stats.farShadowed++;
      this.endFar(u.uid);
      this.host.lost(u, f.end.spot);
    }
  }

  private endFar(uid: number): void {
    const r = this.far.get(uid);
    this.far.delete(uid);
    this.host.trains.phantom(`me:${uid}`, null as never, null, 0);
    if (r) delete r.u.far;
    this.host.sendFar?.(uid, null);
  }

  /** A save's far run carried on from where it was, its loads aboard again (from Fleet.launchAll). */
  resume(u: Unit): boolean {
    const f = u.far;
    if (!f) return false;
    if (this.far.has(u.uid)) return true;
    const hold = this.aboard(u);
    for (const k of f.loads) {
      const it = this.host.restore?.(u, k);
      if (!it) continue;
      hold.push(it);
      // (a long haul still on its way out was taken on at the end it left from)
      if (k.to.name !== f.end.name) this.longEnd.set(it, f.end.name);
    }
    this.holds.set(u.uid, hold);
    this.far.set(u.uid, { u, f, wait: 0, sent: 0 });
    this.host.sendFar?.(u.uid, f.w);
    return true;
  }

  /** Where a far run is, for the follow-cam, the map and the dock: the stand-in's middle if drawn, else the plan's guess. */
  farView(u: Unit): { x: number; y: number; z: number } | null {
    const r = this.far.get(u.uid);
    if (!r) return null;
    const ph = this.host.trains.phantomOf(`me:${u.uid}`);
    const m = ph ? this.host.trains.middle(ph) : null;
    if (m) return m;
    const p = farPoint(hashString(this.host.seed()), r.f.w, Math.min(r.f.w.t, legTime(r.f.w)));
    return { x: p.x, y: 0, z: p.z };
  }

  /** A far run in words: where it is bound, how far it has to go, and when it gets there. */
  farLine(u: Unit): string | null {
    const r = this.far.get(u.uid);
    if (!r) return null;
    const { f } = r;
    const sh = hashString(this.host.seed());
    const total = legTime(f.w);
    const n = f.w.cells.length;
    const togo = Math.max(0, n - 1 - Math.min(n - 1, Math.floor((f.w.t / Math.max(1, total)) * n)));
    const mins = (sec: number) => (sec < 60 ? 'under a minute' : `about ${Math.round(sec / 60)} min`);
    const far = farStation(sh, f.leg === 'out' ? f.w.cells : reversedRoute(f.w.cells))?.name ?? 'a far station';
    if (f.leg === 'out' && f.w.t >= total) return `long haul · at ${far} · back to ${f.end.name} in ${mins(f.w.dwell - (f.w.t - total) + total)}`;
    if (f.leg === 'out') return `long haul to ${far} · ${togo} ${togo === 1 ? 'county' : 'counties'} to go · arrives in ${mins(total - f.w.t)}`;
    return `long haul · on the way back from ${far} to ${f.end.name} · in ${mins(total - f.w.t)}`;
  }

  /** A far run's route for the map's dashed line: the plan's points along it, two a county. */
  farLineOf(u: Unit): { x: number; z: number }[] | null {
    const r = this.far.get(u.uid);
    if (!r) return null;
    const sh = hashString(this.host.seed());
    const w = r.f.w, total = legTime(w), out: { x: number; z: number }[] = [];
    for (let k = 0; k <= w.cells.length * 2; k++) out.push(farPoint(sh, w, (k / (w.cells.length * 2)) * total));
    return out;
  }

  /** What a crewed train has aboard. */
  aboard(u: Unit): CargoItem[] { return this.holds.get(u.uid) ?? []; }

  /** Everything aboard, taken out of its hold (its driver benched, or the player at the regulator): the caller says where it goes. */
  unload(u: Unit): CargoItem[] {
    const out = this.holds.get(u.uid) ?? [];
    this.holds.delete(u.uid);
    return out;
  }

  /** Every crewed train's beat as the beat stock reads it: its stops, kind, hold and round trip. */
  beatWork(): BeatWork[] {
    const out: BeatWork[] = [];
    for (const [uid, tr] of this.byUid) {
      const u = this.host.unit(uid);
      const b = tr.crew?.beat;
      const set = u ? SETS.find((s) => s.id === u.model) : null;
      if (!b || !set) continue;
      // there and back at its speed, and a stop's worth at every station both ways
      const trip = (2 * b.length) / Math.max(0.3, tr.vMax) + 2 * b.stops.length * 14;
      out.push({ stops: b.stops.map((s) => s.st), freight: set.freight, capacity: set.capacity, holds: [...set.holds], trip });
    }
    return out;
  }

  /** The beat a crewed train is working, if it is on the line. */
  beat(u: Unit): Beat | null { return this.train(u)?.crew?.beat ?? null; }

  /** What its driver is doing, in the garage's words. */
  describe(u: Unit): string | null {
    const away = this.farLine(u);
    if (away) return away;
    const tr = this.train(u);
    if (!tr?.crew) return null;
    const b = tr.crew.beat;
    const line = `${b.ends[0].name} — ${b.ends[1].name}`;
    if (tr.crew.out) return `long haul · running on toward ${tr.crew.out} · ${line}`;
    if (tr.state === 'dwell') return `working · calling at ${tr.called} · ${line}`;
    if (tr.v < 0.05 && tr.why) return `working · waiting for the line · bound for ${tr.to}`;
    return `working · bound for ${tr.to}${tr.stop ? ` · next stop ${tr.stop.station.name}` : ''} · ${line}`;
  }

  /**
   * The counties a crewed train's beat runs through, for the world to keep in memory: the beat's own when it is on the
   * line, else the county it stands in and the ones its line runs on into (from the world plan, so nothing need be in
   * memory to know), so the beat can be worked out when it comes back.
   */
  cells(u: Unit): [number, number][] {
    // on a far run its beat is let go (road drivers far off get the slots back), till it is nearly home again
    const r = this.far.get(u.uid);
    if (r) return r.f.leg === 'back' && legTime(r.f.w) - r.f.w.t < 40 ? [[r.f.home.cx, r.f.home.cz], [r.f.end.cx, r.f.end.cz]] : [];
    const b = this.beat(u);
    if (b) return b.cells;
    const home = u.order.beat?.home ?? [u.cx, u.cz];
    const out: [number, number][] = [[u.cx, u.cz]];
    const add = (x: number, z: number) => { if (!out.some(([a, b2]) => a === x && b2 === z)) out.push([x, z]); };
    add(home[0], home[1]);
    const sh = hashString(this.host.seed());
    for (const l of railLines(sh, home[0], home[1])) {
      for (const d of l.sides) add(home[0] + SIDE_DX[d], home[1] + SIDE_DZ[d]);
    }
    return out;
  }

  /** Why a crewed train's beat gives it no work, or null: a passenger train on a line of goods yards alone. */
  idleWhy(u: Unit): string | null {
    const b = this.beat(u);
    const set = SETS.find((s) => s.id === u.model);
    if (!b || !set || set.freight) return null;
    return b.stops.some((s) => serves(this.kindOf(set), s.st)) ? null : 'Only goods yards on this line: a passenger train finds no work here. Put a freight train on it, or give this one a Custom beat with stations.';
  }

  /** The stations a unit's beat may name as ends (Custom): every station of the cells in memory within reach of it. */
  reachable(u: Unit): BeatEnd[] {
    const set = SETS.find((s) => s.id === u.model);
    if (!set) return [];
    const home = u.order.beat?.home ?? [u.cx, u.cz];
    const net = this.host.trains.net, kind = this.kindOf(set);
    const all = stationsInReach(net, kind, home).map((b) => endOf(b));
    // only those joined to the line it is on: a station it could never get to is no end to offer
    const b = this.beat(u);
    if (!b) return all;
    const on = (e: BeatEnd) => b.stops.some((s) => s.name === e.name && s.cx === e.cx && s.cz === e.cz);
    const a0 = endOf(b.ends[0]), a1 = endOf(b.ends[1]);
    return all.filter((e) => on(e) || !!customBeat(net, kind, home, a0, e).beat || !!customBeat(net, kind, home, a1, e).beat);
  }

  /**
   * Custom's two ends (null: back to Whole line), and the beat worked out again at once when the train is on the line.
   * Null when it took, else why not (the ends kept as they were).
   */
  setEnds(u: Unit, ends: { a: BeatEnd; b: BeatEnd } | null): string | null {
    const order = u.order.beat ?? (u.order.beat = { home: [u.cx, u.cz] });
    const tr = this.train(u);
    const set = SETS.find((s) => s.id === u.model);
    if (ends && tr && set) {
      const f = tr.trail[0];
      const got = customBeat(this.host.trains.net, this.kindOf(set), order.home, ends.a, ends.b);
      if (!got.beat) return got.why;
      order.custom = ends;
      if (f) this.host.trains.reBeat(tr, got.beat);
      return null;
    }
    if (ends) order.custom = ends; else delete order.custom;
    if (tr && set) {
      const f = tr.trail[0];
      const got = f ? beatFor(this.host.trains.net, this.kindOf(set), order, { t: f.t, s: f.b }) : null;
      if (got?.beat) this.host.trains.reBeat(tr, got.beat);
    }
    return null;
  }

  /** Every crewed train's beat worked out again from the track now in memory (the dispatcher calls this when it changes). */
  rebeatAll(): void {
    const trains = this.host.trains;
    for (const [uid, tr] of [...this.byUid]) {
      if (!trains.trains.includes(tr) || !tr.crew) { this.byUid.delete(uid); continue; }
      const u = this.host.unit(uid);
      const f = tr.trail[0];
      if (!u || !f) continue;
      const set = SETS.find((s) => s.name === u.model || s.id === u.model);
      if (!set) continue;
      const order = u.order.beat ?? (u.order.beat = { home: [u.cx, u.cz] });
      const got = beatFor(trains.net, this.kindOf(set), order, { t: f.t, s: f.b });
      if (got.beat) { trains.reBeat(tr, got.beat); this.stats.rebeat++; }
    }
  }

  /** Every crewed train on the line, for the console. */
  list(): { u: Unit | null; tr: Train }[] {
    return [...this.byUid].map(([uid, tr]) => ({ u: this.host.unit(uid), tr }));
  }

  clear(): void {
    for (const tr of this.byUid.values()) this.host.trains.remove(tr);
    this.byUid.clear();
    for (const uid of [...this.far.keys()]) this.host.trains.phantom(`me:${uid}`, null as never, null, 0);
    this.far.clear();
    this.longEnd.clear();
  }
}
