/**
 * The Tail (the user's pitch, Oct 2026): somebody wants a car followed to wherever it is going, unseen — or
 * a train, from the roads beside the line. This is the run itself, from the moment the mission is taken:
 * the target waiting at its kerb, driving its legs as real traffic (game/traffic.ts, `launchTour` and
 * `driveOwned`, the touring acts' way of putting a vehicle on the road that no one else owns), its mirror
 * watching the player (sight.ts), the warnings on screen, and the ending — home unseen, made and chased down,
 * or lost.
 *
 * The target is a CPU car like any other: it keeps to the roads and its lane, stops behind the traffic and
 * waits at the barriers, and goes where its legs send it — pulling over to check its mirror, parking up to
 * wait somewhere quiet, doubling back, putting its foot down for a stretch, or going into a garage and
 * coming out in another car. Made, it bolts: a working driver's spirit, nitrous and handbrake (Agent.bolt).
 *
 * A train keeps to its rails and its timetable (game/trains.ts) and waits for nobody. Its eyes are the guard
 * at the back looking down the line, the driver looking ahead, and both of them out of the side windows at
 * anyone keeping level for long; it ends when it next calls at a yard with the player there to see it.
 *
 * Nothing of the mirror is drawn. What the player sees: a suspicion meter on the strip at the foot of the
 * screen, the screen's edge pulsing red as it fills, "Too close — drop back!" when it is high, the target
 * glancing in its mirror (brake lights flickering, 👀 over it) once it starts to wonder, and "Losing them…"
 * when they have dropped too far back or out of sight for too long.
 */
import * as THREE from 'three';
import { N, type World } from '../../world/tiles';
import { halfSize, type LandDef, type VehicleDef, type VehicleState } from '../vehicles';
import { defOf, kerbNear } from '../fleet';
import { applyParts, type Parts } from '../parts';
import type { Agent, Traffic } from '../traffic';
import { pointBehind, sampleAt, type Train, type Trains } from '../trains';
import { DRIVER } from '../lamps';
import { MIRROR, SCREEN, TAIL, carSight, coneRate, followsBy, mirrorOf, seesLine, stepSuspicion, type Seen } from './sight';
import type { Obj, TailCar } from '../missions/model';
import { clamp } from '../../util/math';

export type TailObj = Extract<Obj, { t: 'tail' }>;
/** How a tail ended: `ok` with the place found; `made` when it was seen on the way (and chased down, if `ok`). */
interface TailResult { ok: boolean; made: boolean; score: number; line: string }

export interface TailHost {
  worldAt(cx: number, cz: number): World | null;
  /** The player: island, state in its frame, what they drive. Null with nobody out. */
  player(): { w: World; state: VehicleState; def: VehicleDef } | null;
  /** The road traffic of a cell in memory, to put the target on the road in. */
  trafficOf(w: World): Traffic | null;
  /** The railway, for a train tail. */
  trains(): Trains | null;
  /** How dark it is for driving, 0..1 (night, dust, snow). */
  dark(): number;
  say(title: string, body: string): void;
  beep(final: boolean): void;
}

/** The player must come this near the target's kerb for it to set off; it is put on the road from this far. */
export const START_R = 22, SHOW_R = 80;
/** Seconds a target pulled over checks its mirror, parks up to wait, doubles back, and spends in the garage before its other car comes out. */
const CHECK_SECS: [number, number] = [6, 9], WAIT_SECS: [number, number] = [14, 20], BACK_SECS = 9, SWAP_IN = 3, SWAP_OUT = 7;
/** A swap seen: the player must be this near the garage when the other car pulls out. */
const SWAP_SEE = 36;
/** The ending: the player within this many tiles of the target when it stops for good. */
const END_R = 40;
/** A run that goes on this long has been given the slip. */
const GIVE_UP = 900;
/** The train: its guard's mirror reaches further down a straight line than a car's; the lookouts' side windows. */
const TRAIN_MIRROR = { ...MIRROR, range: 11, half: (20 * Math.PI) / 180 };
const TRAIN_SIDE = 3.2, TRAIN_SIDE_RATE = 0.16;
/** A car standing still as a train goes by is only a car at the crossing: it counts this much of a follower's rate. */
const TRAIN_PARKED = 0.12;
/** Seconds of tailing before a train's next call counts (one already pulling out of the meet doesn't). */
const TRAIN_MIN = 25;
/** A freight this near is taken as the one; the player then has TRAIN_CATCH seconds to come within TRAIN_CLOSE of it. */
const TRAIN_FIND = 110, TRAIN_CLOSE = 30, TRAIN_CATCH = 75;

const esc = (s: string) => s.replace(/[<&]/g, (c) => (c === '<' ? '&lt;' : '&amp;'));
const between = (r: [number, number], k: number) => r[0] + ((k * 0.618) % 1) * (r[1] - r[0]);

/** The target's car: its model in its own paint, with a bottle of nitrous and a handbrake for when it bolts. */
const DEFS = new Map<string, LandDef>();
export function tailDef(c: TailCar): LandDef {
  const key = `${c.model}|${c.colour}`;
  let d = DEFS.get(key);
  if (!d) {
    const parts: Parts = { t: { paint: [1, 1], nitrous: [2, 2], handbrake: [2, 2] }, c: c.colour, spent: 0 };
    d = applyParts(defOf(c.model), parts) as LandDef;
    DEFS.set(key, d);
  }
  return d;
}

type Phase = 'wait' | 'brief' | 'tail' | 'bolt' | 'done';

export class TailRun {
  result: TailResult | null = null;
  phase: Phase = 'wait';
  /** Seconds since it set off. */
  t = 0;
  /** The meter, 0..1, and the most it reached. */
  sus = 0;
  peak = 0;
  made = false;
  /** Where the follower stood to it this frame, how far from its back, and its mirror's reach now. */
  seen: Seen = 'out';
  dist = 0;
  reach = MIRROR.range;
  /** The leg being driven (legs.length is the last run, to the ending). */
  k = 0;
  /** The car target on the road, its traffic, and its def now (the swap changes it). */
  a: Agent | null = null;
  private tr: Traffic | null = null;
  private def: LandDef;
  /** The car it is in now: the one it set off in, or the one it came out of the garage in. */
  car: TailCar;
  /** The train being followed. */
  train: Train | null = null;
  private trains: Trains | null = null;
  /** Seconds left of: a pull-over, a park-up, a doubling back, the garage; and which. */
  private hold = 0;
  private holding: 'check' | 'wait' | 'back' | 'swapIn' | 'swapOut' | null = null;
  private last = { x: 0, z: 0, heading: 0 };
  private fails = 0;
  private hornSeen = DRIVER.horns;
  private hornT = 0;
  private farT = 0;
  private unseenT = 0;
  private catchT = 0;
  private escT = 0;
  private findT = 0;
  /** The player has come up near the train once (a train tail's lost checks start then). */
  private closed = false;
  private briefT = 0;
  private lens = new Float32Array(16);
  private said = '';
  private glanceT = 0;
  // ---- on screen ----
  private g = new THREE.Group();
  private lamps: THREE.Mesh[] = [];
  private strip: HTMLDivElement | null = null;
  private warn: HTMLDivElement | null = null;
  private edge: HTMLDivElement | null = null;
  private tag: HTMLDivElement | null = null;
  private stripText = '';
  private warnText = '';
  private next = '';

  constructor(readonly id: number, private host: TailHost, private scene: THREE.Scene | null, readonly o: TailObj) {
    this.def = tailDef(o.car);
    this.car = o.car;
    if (scene) {
      scene.add(this.g);
      // the target's brake lights, flickered when it glances in its mirror (its own lamps are the traffic's to light)
      for (let k = 0; k < 2; k++) {
        const m = new THREE.Mesh(new THREE.SphereGeometry(0.07, 8, 6), new THREE.MeshBasicMaterial({ color: 0xff2a1a, transparent: true, opacity: 0.95, depthWrite: false, blending: THREE.AdditiveBlending }));
        m.visible = false;
        this.lamps.push(m);
        this.g.add(m);
      }
    }
    if (typeof document !== 'undefined') {
      this.strip = document.createElement('div');
      this.strip.className = 'race-strip hud chip tail-strip';
      this.warn = document.createElement('div');
      this.warn.className = 'tail-warn';
      this.edge = document.createElement('div');
      this.edge.className = 'tail-edge';
      this.tag = document.createElement('div');
      this.tag.className = 'race-tag tail-tag';
      this.strip.hidden = this.warn.hidden = this.tag.hidden = true;
      document.body.append(this.edge, this.strip, this.warn, this.tag);
    }
  }

  /** Under way (past waiting for the player at the start). */
  get running(): boolean { return this.phase !== 'wait' && !this.result; }

  /** The player in world tiles. */
  private me(): { x: number; z: number; y: number; land: boolean } | null {
    const p = this.host.player();
    return p ? { x: p.w.ox + p.state.x, z: p.w.oz + p.state.z, y: p.state.y, land: p.def.kind === 'land' } : null;
  }

  /** The target in world tiles: where, which way, how fast. Null while it isn't on the road (or the line). */
  where(): { x: number; z: number; y: number; heading: number; v: number } | null {
    if (this.train) {
      const s = frontOf(this.train);
      return s ? { x: s.x, z: s.z, y: s.y, heading: s.ang, v: this.train.v } : null;
    }
    const a = this.a;
    if (!a) return null;
    return { x: a.w.ox + a.state.x, z: a.w.oz + a.state.z, y: a.state.y, heading: a.state.heading, v: a.state.v };
  }

  // ---- the frame ----------------------------------------------------------------------------------

  update(dt: number, paused: boolean): void {
    if (this.result) { this.draw(); return; }
    if (!paused && dt > 0) {
      // the horn: a press since last frame rings for a few seconds
      if (DRIVER.horns !== this.hornSeen) {
        this.hornSeen = DRIVER.horns;
        if (this.running) { this.hornT = TAIL.horn.secs; this.once('📯 Every mirror turns your way', 'The horn makes you hard to miss for a few seconds'); }
      }
      this.hornT = Math.max(0, this.hornT - dt);
      if (this.o.train) this.runTrain(dt);
      else this.runCar(dt);
    }
    this.draw();
  }

  private once(title: string, body: string): void {
    const k = `${title}|${body}`;
    if (k === this.said) return;
    this.said = k;
    this.host.say(title, body);
  }

  private finish(ok: boolean, score: number, line: string): void {
    if (this.result) return;
    this.result = { ok, made: this.made, score: clamp(score, 0, 1), line };
    this.phase = 'done';
    this.host.beep(true);
    // the target goes back to being traffic: it parks where it was going and, a while later, is gone
    const a = this.a;
    if (a) { a.tour = false; a.bolt = false; if (a.phase === 'parked') a.timer = 45; }
  }

  // ---- a car ------------------------------------------------------------------------------------

  /** Put the target on the road at (world) x, z facing `heading`, in whichever cell that is. */
  private launch(x: number, z: number, heading: number, car: TailCar): boolean {
    const w = this.host.worldAt(Math.floor(x / N), Math.floor(z / N));
    const tr = w ? this.host.trafficOf(w) : null;
    if (!w || !tr) return false;
    const k = kerbNear(w, x - w.ox, z - w.oz, 6) ?? { x: x - w.ox, z: z - w.oz };
    this.def = tailDef(car);
    this.car = car;
    const a = tr.launchTour(this.def, k.x, k.z, heading);
    if (!a) return false;
    this.a = a;
    this.tr = tr;
    this.last = { x: w.ox + k.x, z: w.oz + k.z, heading };
    return true;
  }

  /** Off the road (the garage, the end of the run). */
  private drop(): void {
    if (this.a && this.tr) this.tr.dropTour(this.a);
    this.a = null;
    this.tr = null;
  }

  /** Send it to a place in world tiles. False when there is no way there from where it is. */
  private send(p: { x: number; z: number }): boolean {
    const a = this.a, tr = this.tr;
    if (!a || !tr) return false;
    if (tr.driveOwned(a, p.x - a.w.ox, p.z - a.w.oz)) return true;
    // the spot itself may be off the road: the nearest kerb to it, in its own cell
    const w = this.host.worldAt(Math.floor(p.x / N), Math.floor(p.z / N));
    const k = w ? kerbNear(w, p.x - w.ox, p.z - w.oz, 8) : null;
    return !!k && !!w && tr.driveOwned(a, w.ox + k.x - a.w.ox, w.oz + k.z - a.w.oz);
  }

  /** The leg after this one (or the ending), started. */
  private nextLeg(): void {
    this.k++;
    this.holding = null;
    this.startLeg();
  }

  private startLeg(): void {
    const legs = this.o.legs;
    const leg = this.k < legs.length ? legs[this.k] : null;
    const goal = leg ?? this.o.to;
    if (this.a) this.a.bolt = this.phase === 'bolt' || leg?.act === 'dash';
    if (leg?.act === 'dash') this.once('It’s speeding up', 'Trying to shake anyone behind · keep up, but not on its bumper');
    if (!this.send(goal)) {
      // no way to that stop: on to the next (the ending always has a way: the template checked)
      if (leg) { this.nextLeg(); return; }
      this.finish(false, 0, 'It turned off where you couldn’t follow');
    }
  }

  /** It has pulled up at the end of the leg it was on: whatever that stop is for. */
  private arrived(): void {
    const legs = this.o.legs;
    if (this.k >= legs.length) { this.ending(); return; }
    const leg = legs[this.k];
    switch (leg.act) {
      case 'check':
        this.holding = 'check'; this.hold = between(CHECK_SECS, this.id + this.k);
        this.once('It’s pulled over', 'Checking its mirror · drive on past, or stop well back out of sight');
        return;
      case 'wait':
        this.holding = 'wait'; this.hold = between(WAIT_SECS, this.id + this.k);
        this.once('It’s parked up', 'Waiting to see who comes by · keep out of its mirror until it moves');
        return;
      case 'back': {
        // round, and back the way it came for a while: it meets anyone behind it face on
        const prev = this.k > 0 ? legs[this.k - 1] : this.o.at;
        this.holding = 'back'; this.hold = BACK_SECS;
        this.send(prev);
        this.once('It’s doubling back!', 'Coming back your way · don’t stare, keep driving');
        return;
      }
      case 'swap':
        this.holding = 'swapIn'; this.hold = SWAP_IN;
        this.once('It’s gone into the garage', 'Watch who comes out');
        return;
      default:
        this.nextLeg();
    }
  }

  /** At the end: found, if the player is near enough to see where. */
  private ending(): void {
    const p = this.me(), q = this.where();
    const d = p && q ? Math.hypot(p.x - q.x, p.z - q.z) : Infinity;
    const place = this.o.to.name;
    if (d > END_R) { this.finish(false, 0, 'It got where it was going without you'); return; }
    if (this.made) this.finish(true, 0.15, `Followed it to ${place}, but it knew`);
    else this.finish(true, 1 - this.peak * 0.6, `Followed it to ${place} unseen`);
  }

  private runCar(dt: number): void {
    const p = this.me();
    const pl = this.host.player();
    if (!p || !pl) return;
    const at = this.o.at;
    // ---- waiting at its kerb for the player
    if (this.phase === 'wait') {
      const d = Math.hypot(p.x - at.x, p.z - at.z);
      if (!this.a && d < SHOW_R) {
        const first = this.o.legs[0] ?? this.o.to;
        this.launch(at.x, at.z, Math.atan2(first.x - at.x, first.z - at.z), this.o.car);
      }
      this.next = `Drive to ${at.name}`;
      if (!p.land) { this.show(`🕵️ Needs a road car · ${Math.round(d)} t to ${esc(at.name)}`); return; }
      this.show(`🕵️ ${Math.round(d)} t to ${esc(at.name)} · look for ${esc(this.o.car.name)}`);
      if (d > START_R || !this.a) return;
      this.phase = 'brief';
      this.briefT = 2.5;
      this.host.say(`That’s them: ${this.o.car.name}`, 'Follow it, but stay out of its mirror · too close and you’re made, too far and it’s gone');
    }
    this.t += dt;
    if (this.t > GIVE_UP) { this.finish(false, 0, 'It gave you the slip'); return; }
    // ---- the target vanished from the road (stuck fast, its cell unloaded): back on at a kerb near where it was
    if (this.a && this.tr && !this.tr.agents.includes(this.a)) {
      this.a = null;
      if (++this.fails > 4 || !this.launch(this.last.x, this.last.z, this.last.heading, this.car)) {
        this.finish(false, 0, 'Lost it in the traffic');
        return;
      }
      if (this.phase !== 'brief') this.startLeg();
    }
    const a = this.a;
    if (a) this.last = { x: a.w.ox + a.state.x, z: a.w.oz + a.state.z, heading: a.state.heading };
    // ---- the brief pause, then off
    if (this.phase === 'brief') {
      this.briefT -= dt;
      if (this.briefT <= 0) {
        this.phase = 'tail';
        this.k = 0;
        this.startLeg();
        // after dark, the trick worth knowing
        if (this.host.dark() > 0.3 && !DRIVER.lightsOff) this.once('Running dark?', 'N switches your headlights off · a mirror at night shows little else');
      }
    } else if (this.phase === 'tail') {
      this.drive(dt);
      // the tracker's line: the one thing to do now
      this.next = this.holding === 'swapIn' || this.holding === 'swapOut' ? 'Watch who comes out of the garage'
        : this.holding === 'back' ? 'It’s doubling back: drive on past'
        : this.holding ? 'It’s stopped: keep out of its mirror'
        : `Follow ${this.car.name}, out of its mirror`;
    }
    // ---- what it sees of the player
    const q = this.where();
    const d = q ? Math.hypot(p.x - q.x, p.z - q.z) : Math.hypot(p.x - this.last.x, p.z - this.last.z);
    this.dist = d;
    if (a && this.holding !== 'swapIn' && this.holding !== 'swapOut') {
      const others = (this.tr?.agents ?? []).filter((g) => g !== a).map((g) => ({ x: g.w.ox + g.state.x - a.w.ox, z: g.w.oz + g.state.z - a.w.oz }));
      const r = carSight({
        w: a.w, x: a.state.x, z: a.state.z, y: a.state.y, heading: a.state.heading, halfLen: halfSize(this.def)[0],
        px: p.x - a.w.ox, pz: p.z - a.w.oz, ph: pl.state.heading, pv: pl.state.v, dark: this.host.dark(), lightsOff: DRIVER.lightsOff, horn: this.hornT / TAIL.horn.secs,
        checking: this.holding === 'check' || this.holding === 'wait', others,
      }, this.lens);
      this.seen = r.seen;
      this.reach = r.mirror.range;
      if (!this.made) this.sus = stepSuspicion(this.sus, r.rate, dt);
      this.filled += r.rate * dt;
      if (r.rate > 0) this.seenFor += dt;
      this.peak = Math.max(this.peak, this.sus);
      if (this.sus >= 1 && !this.made && this.phase === 'tail') this.bolt();
    } else this.seen = 'out';
    if (this.result) return;
    // ---- lost, or getting away
    if (this.phase === 'bolt') this.chase(dt, d);
    else if (this.phase === 'tail') this.lostCheck(dt, d, p, q);
  }

  /** Driving its legs: arrivals, and the stops on the way. */
  private drive(dt: number): void {
    const a = this.a;
    if (this.holding) {
      this.hold -= dt;
      if (this.holding === 'swapIn' && this.hold <= 0) {
        // the driver walks in; the other car pulls out a few seconds later
        this.drop();
        this.holding = 'swapOut';
        this.hold = SWAP_OUT;
        return;
      }
      if (this.holding === 'swapOut') {
        if (this.hold > 0) return;
        const p = this.me(), leg = this.o.legs[this.k];
        const out = this.o.swap ?? this.o.car;
        if (p && Math.hypot(p.x - leg.x, p.z - leg.z) > SWAP_SEE) { this.finish(false, 0, 'You missed it come out of the garage'); return; }
        // out of the garage pointing the way it goes next
        const on = this.o.legs[this.k + 1] ?? this.o.to;
        if (!this.launch(this.last.x, this.last.z, Math.atan2(on.x - this.last.x, on.z - this.last.z), out)) { this.finish(false, 0, 'Lost it at the garage'); return; }
        this.host.say(`Out comes ${out.name}`, 'Same driver, another car · that’s who you follow now');
        this.nextLeg();
        return;
      }
      if (this.hold <= 0 || (this.holding === 'back' && a && a.phase === 'parked')) this.nextLeg();
      return;
    }
    if (a && a.phase === 'parked') this.arrived();
  }

  /** Seen: it bolts for wherever it was going, every trick it has, and the player can still run it down. */
  private bolt(): void {
    this.made = true;
    this.phase = 'bolt';
    this.holding = null;
    this.escT = 0;
    this.catchT = 0;
    if (this.a) this.a.bolt = true;
    this.send(this.o.to);
    this.host.beep(false);
    this.host.say('Made!', 'It’s seen you and it’s running · stay on its bumper to pull it over, or lose it for good');
  }

  private chase(dt: number, d: number): void {
    this.next = 'Stay on its bumper to pull it over';
    if (d < TAIL.bolt.catchR) this.catchT += dt;
    if (this.catchT >= TAIL.bolt.catchSecs) {
      if (this.a) { this.a.bolt = false; this.tr?.stopForConvoy(this.a); }
      this.finish(true, 0.15, `Made, but ran it down before ${this.o.to.name}`);
      return;
    }
    this.escT = d > TAIL.bolt.escape ? this.escT + dt : Math.max(0, this.escT - dt);
    if (this.escT > TAIL.bolt.escapeSecs) { this.finish(false, 0, 'Made, and it got away'); return; }
    if (this.a && this.a.phase === 'parked') this.ending();
  }

  /** Too far back, or out of its sight line too long while it was moving: gone. */
  private lostCheck(dt: number, d: number, p: { x: number; z: number; y: number }, q: { x: number; z: number; y: number; v: number } | null): void {
    this.farT = d > TAIL.lost.far ? this.farT + dt : 0;
    if (this.farT > TAIL.lost.farSecs) { this.finish(false, 0, 'Lost it: fell too far behind'); return; }
    const moving = !!q && Math.abs(q.v) > 0.15 && !this.holding;
    const a = this.a;
    const inView = !!q && !!a && (d < TAIL.lost.near || seesLine(a.w, p.x - a.w.ox, p.z - a.w.oz, Math.max(p.y, q.y) + 0.3, q.x - a.w.ox, q.z - a.w.oz));
    if (inView) this.unseenT = 0;
    else if (moving) this.unseenT += dt;
    if (this.unseenT > TAIL.lost.unseen) this.finish(false, 0, 'Lost it: out of sight too long');
  }

  // ---- a train ----------------------------------------------------------------------------------

  /** Points along a train from its front back to its last car, a tile and a half apart, in world tiles. */
  body(tr: Train): { x: number; z: number; y: number }[] {
    const out: { x: number; z: number; y: number }[] = [];
    const tmp = { x: 0, y: 0, z: 0, ang: 0 };
    for (let d = 0; d <= tr.length; d += 1.5) {
      const q = pointBehind(tr, Math.min(d, tr.length - 0.05));
      if (!q) break;
      sampleAt(q.t, q.s, tmp);
      out.push({ x: tmp.x, z: tmp.z, y: tmp.y });
    }
    return out;
  }

  private runTrain(dt: number): void {
    const p = this.me();
    const pl = this.host.player();
    if (!p || !pl) return;
    const at = this.o.at;
    this.trains ??= this.host.trains();
    if (this.phase === 'wait') {
      const d = Math.hypot(p.x - at.x, p.z - at.z);
      this.next = `Drive to ${at.name}`;
      if (!p.land) { this.show(`🚂 Needs a road car · ${Math.round(d)} t to ${esc(at.name)}`); return; }
      if (d > START_R + 8) { this.show(`🚂 ${Math.round(d)} t to ${esc(at.name)} · the freight comes through there`); return; }
      // the freight: one already on the line near by, or the next one put out
      this.show(`🚂 Waiting at ${esc(at.name)} for the freight…`);
      this.findT -= dt;
      if (this.findT > 0 || !this.trains) return;
      this.findT = 2;
      const near = (t: Train) => { const f = frontOf(t); return f ? Math.hypot(f.x - p.x, f.z - p.z) : Infinity; };
      let pick = this.trains.trains.filter((t) => !t.player && t.freight && t.trail.length && t.state !== 'dwell').sort((x, y) => near(x) - near(y))[0];
      if (!pick || near(pick) > TRAIN_FIND) {
        const made = this.trains.spawn('freight', { x: p.x, z: p.z });
        if (made && near(made) <= TRAIN_FIND) pick = made;
        else return;
      }
      this.train = pick;
      this.phase = 'tail';
      this.host.say(`There: the ${pick.name || 'freight'}`, `Bound for ${pick.to || 'the yards'} · follow it from the road, out of the guard’s sight, and see where it stops`);
    }
    const tr = this.train;
    if (!tr || !this.trains) return;
    this.t += dt;
    if (!this.trains.trains.includes(tr)) { this.finish(false, 0, 'Lost it: it went off up the line'); return; }
    if (this.t > GIVE_UP) { this.finish(false, 0, 'It ran on past where you could follow'); return; }
    const body = this.body(tr);
    if (!body.length) return;
    let d = Infinity;
    for (const b of body) d = Math.min(d, Math.hypot(b.x - p.x, b.z - p.z));
    this.dist = d;
    // first the player has to catch it up: nothing counts until they are near it once
    if (!this.closed) {
      this.next = `Catch up with the ${tr.name || 'freight'}`;
      if (d < TRAIN_CLOSE) { this.closed = true; this.host.say('On its tail', 'Keep it in sight from the road · stay out of the guard’s view'); }
      else if (this.t > TRAIN_CATCH) { this.finish(false, 0, 'It left without you'); return; }
      else return;
    }
    // its eyes: the guard down the line behind, the driver ahead, and both at the side windows
    const rear = body[body.length - 1], before = body[Math.max(0, body.length - 2)];
    const w = this.host.worldAt(Math.floor(rear.x / N), Math.floor(rear.z / N));
    let rate = 0;
    this.seen = 'out';
    // a car going the train's way looks like a tail; one going the other way, or waiting at a crossing, doesn't
    const like = followsBy({ heading: frontOf(tr)?.ang ?? 0, ph: pl.state.heading, pv: pl.state.v }, TRAIN_PARKED);
    if (w) {
      const shape = mirrorOf(this.host.dark(), DRIVER.lightsOff, this.hornT / TAIL.horn.secs, tr.state !== 'run', TRAIN_MIRROR);
      this.reach = shape.range;
      // down the line behind the last car (a train whose tail is still beyond the cells in memory: behind its front)
      const back = body.length > 1 ? Math.atan2(rear.x - before.x, rear.z - before.z) : (frontOf(tr)?.ang ?? 0) + Math.PI;
      const r = coneRate(w, rear.x - w.ox, rear.z - w.oz, rear.y + 0.4, back, shape, this.lens, p.x - w.ox, p.z - w.oz, like);
      if (r.at === 'in') { rate = r.rate; this.seen = 'mirror'; } else if (r.at === 'near') this.seen = 'edge';
      const f = body[0];
      const ahead = frontOf(tr)?.ang ?? 0;
      if (!rate) {
        const s = coneRate(w, f.x - w.ox, f.z - w.oz, f.y + 0.4, ahead, SCREEN, this.lens, p.x - w.ox, p.z - w.oz, TAIL.rate.front);
        if (s.at === 'in') { rate = s.rate; this.seen = 'screen'; }
      }
      if (!rate && d < TRAIN_SIDE) {
        const b = body.reduce((m, q) => (Math.hypot(q.x - p.x, q.z - p.z) < Math.hypot(m.x - p.x, m.z - p.z) ? q : m), body[0]);
        if (seesLine(w, b.x - w.ox, b.z - w.oz, b.y + 0.4, p.x - w.ox, p.z - w.oz)) { rate = TRAIN_SIDE_RATE * like; this.seen = 'side'; }
      }
    }
    this.sus = stepSuspicion(this.sus, rate, dt);
    this.filled += rate * dt;
    if (rate > 0) this.seenFor += dt;
    this.peak = Math.max(this.peak, this.sus);
    if (this.sus >= 1) {
      this.made = true;
      this.finish(false, 0, 'The guard saw you: it ran straight through the yards');
      return;
    }
    // it calls: the place found, if the player is near enough to see it
    if (tr.state === 'dwell' && this.t > TRAIN_MIN && d < END_R) {
      this.finish(true, 1 - this.peak * 0.6, `It stopped at ${tr.called || 'the yards'}: that's where the wagon comes off`);
      return;
    }
    this.next = `Follow the ${tr.name || 'freight'} from the road`;
    this.farT = d > TAIL.lost.far + 6 ? this.farT + dt : 0;
    if (this.farT > TAIL.lost.farSecs) { this.finish(false, 0, 'Lost it: the train doesn’t wait'); return; }
    const inView = d < TAIL.lost.near || (w ? body.some((b, k) => k % 3 === 0 && seesLine(w, p.x - w.ox, p.z - w.oz, p.y + 0.5, b.x - w.ox, b.z - w.oz)) : false);
    if (inView) this.unseenT = 0;
    else if (tr.v > 0.2) this.unseenT += dt;
    if (this.unseenT > TAIL.lost.unseen + 6) this.finish(false, 0, 'Lost it: out of sight too long');
  }

  // ---- what the player sees ----------------------------------------------------------------------

  /** Where the tracker points: the meet until it sets off, then the target itself. */
  target(): { x: number; z: number; name: string } {
    const q = this.running ? this.where() : null;
    return q ? { x: q.x, z: q.z, name: this.train ? 'the train' : this.o.car.name } : { x: this.o.at.x, z: this.o.at.z, name: this.o.at.name };
  }
  line(): string | null { return this.next || null; }

  /** Suspicion added so far, all told (the gate compares runs by it), and seconds spent being seen. */
  filled = 0;
  seenFor = 0;

  /** The suspicion as a word, for the strip. */
  private mood(): string {
    if (this.made) return 'made';
    if (this.sus >= TAIL.warn) return 'onto you';
    if (this.sus >= TAIL.glance) return 'wondering';
    return this.sus > 0.05 ? 'uneasy' : 'unaware';
  }

  private show(html: string): void {
    if (!this.strip) return;
    if (html !== this.stripText) { this.stripText = html; this.strip.innerHTML = html; }
    this.strip.hidden = false;
  }

  private draw(): void {
    const live = this.running;
    // the strip
    if (live) {
      const pct = Math.round(this.sus * 100);
      const lvl = this.made || this.sus >= TAIL.warn ? 'hot' : this.sus >= TAIL.glance ? 'warm' : 'cool';
      const icon = this.o.train ? '🚂' : '🕵️';
      const who = this.train ? `the ${this.train.name || 'freight'}` : this.holding === 'swapOut' ? 'the garage' : this.car.name;
      const doing = this.holding === 'check' ? ' · pulled over' : this.holding === 'wait' ? ' · parked up' : this.holding === 'back' ? ' · doubling back' : this.holding ? ' · in the garage' : '';
      const extra = `${DRIVER.lightsOff ? ' <span class="tail-pill">🌑 lights off</span>' : ''}${this.hornT > 0 ? ' <span class="tail-pill hot">📯</span>' : ''}`;
      this.show(`${icon} <span>Tailing ${esc(who)}${doing}</span><span class="tail-meter ${lvl}" title="Suspicion"><i style="width:${pct}%"></i></span><b class="tail-mood ${lvl}">${this.mood()}</b><span class="clock">${Math.round(this.dist)} t</span>${extra}`);
    } else if (this.result && this.strip) this.strip.hidden = true;
    // the warning in the middle
    let w = '';
    let cls = '';
    if (live && this.phase === 'bolt') { w = 'MADE · run it down!'; cls = 'hot'; }
    else if (live && this.phase === 'tail') {
      if (this.sus >= TAIL.warn) { w = 'Too close · drop back!'; cls = 'hot'; }
      else if ((this.seen === 'mirror' || this.seen === 'side' || this.seen === 'screen') && this.sus >= TAIL.glance) { w = this.seen === 'screen' ? 'It’s looking right at you' : 'In its mirror · ease off'; cls = 'warm'; }
      else if (this.dist > TAIL.lost.warn || this.unseenT > TAIL.lost.unseenWarn) { w = 'Losing them…'; cls = 'far'; }
    }
    if (this.warn) {
      const k = `${cls}|${w}`;
      if (k !== this.warnText) { this.warnText = k; this.warn.textContent = w; this.warn.className = `tail-warn ${cls}`; }
      this.warn.hidden = !w;
    }
    // the screen's edge: a red pulse that grows and quickens as the meter fills
    if (this.edge) {
      const heat = live ? (this.made ? 1 : clamp((this.sus - 0.25) / 0.75, 0, 1)) : 0;
      this.edge.style.opacity = heat.toFixed(2);
      this.edge.style.animationDuration = `${(1.4 - heat * 0.9).toFixed(2)}s`;
    }
    // the brake lights flicker as it glances in its mirror
    const q = live && !this.train ? this.where() : null;
    const glancing = !!q && (this.made || this.sus >= TAIL.glance || this.holding === 'check');
    this.glanceT += 1 / 60;
    const beat = 1.6 - this.sus;
    const on = glancing && (this.glanceT % beat) < 0.18;
    this.lamps.forEach((m, k) => {
      m.visible = !!q && on;
      if (!q || !on) return;
      const [hl, hw] = halfSize(this.def);
      const fx = Math.sin(q.heading), fz = Math.cos(q.heading);
      const side = (k ? 1 : -1) * hw * 0.7;
      m.position.set(q.x - fx * (hl + 0.02) + fz * side, q.y + 0.22, q.z - fz * (hl + 0.02) - fx * side);
    });
  }

  /** The 👀 over the target as it starts to wonder (❗ once made), projected. */
  label(camera: THREE.Camera): void {
    if (!this.tag) return;
    const q = this.running ? this.where() : null;
    const text = !q ? '' : this.made ? '❗' : this.sus >= TAIL.glance ? (this.sus >= TAIL.warn ? '👀❗' : '👀') : this.holding === 'check' || this.holding === 'wait' ? '🪞' : '';
    if (!q || !text) { this.tag.hidden = true; return; }
    const v = new THREE.Vector3(q.x, q.y + 0.9, q.z).project(camera);
    if (v.z > 1) { this.tag.hidden = true; return; }
    this.tag.hidden = false;
    if (this.tag.textContent !== text) this.tag.textContent = text;
    this.tag.style.transform = `translate(${((v.x + 1) / 2) * innerWidth}px, ${((1 - v.y) / 2) * innerHeight}px) translate(-50%, -100%)`;
  }

  /** For the console and the gate. */
  snapshot(): Record<string, unknown> {
    const q = this.where();
    return {
      phase: this.phase, t: Math.round(this.t), leg: `${this.k}/${this.o.legs.length}`, holding: this.holding, sus: +this.sus.toFixed(2), peak: +this.peak.toFixed(2),
      seen: this.seen, dist: +this.dist.toFixed(1), reach: +this.reach.toFixed(1), made: this.made, lightsOff: DRIVER.lightsOff, horn: +this.hornT.toFixed(1),
      at: q ? [Math.round(q.x), Math.round(q.z)] : null, result: this.result,
    };
  }

  dispose(): void {
    // an ending leaves the car parked where it stopped, as traffic; given up part way, it goes
    if (!this.result) this.drop();
    this.scene?.remove(this.g);
    for (const m of this.lamps) { m.geometry.dispose(); (m.material as THREE.Material).dispose(); }
    this.strip?.remove();
    this.warn?.remove();
    this.edge?.remove();
    this.tag?.remove();
  }
}

/** A train's front, in world tiles, with the way it is running. */
function frontOf(t: Train): { x: number; y: number; z: number; ang: number } | null {
  const f = t.trail[0];
  if (!f) return null;
  const s = sampleAt(f.t, f.b, { x: 0, y: 0, z: 0, ang: 0 });
  // the track's own sense, turned to the way the train is running along it
  if (f.d < 0) s.ang += Math.PI;
  return s;
}
