import { DIRS, N, STEP, heightOnTile, idx, inB, waterDepth, type Building, type Town, type World } from '../world/tiles';
import { hash2, mulberry32 } from '../world/rng';
import { hex } from '../world/biomes';
import { Vis } from './nightLights';
import type { Kit } from './buildings/kit';
import { bench, cypress, ferry, ferryOf, lakeLamp, lakePalm, planeTree, pontoon, riva, rowboat, sailboat, IRON } from './buildings/lakeKit';

/**
 * A lake town's shore and its water (world/lakes.ts cuts the lake), drawn with the town's buildings a chunk at a time
 * (render/townMesh.ts), from the tiles alone:
 *
 * - the walk along the shore (the free ground between the lakeshore drive and the water): Léman's plane trees, iron
 *   lamps and the railing along the quay; Como's globe lamps, palms and oleanders; benches and lamps on the American
 *   lakes' lawns, a picnic table here and there;
 * - the lake's boats, from the chunk the town's first steamer landing stands in: the steamer or ferry the town's
 *   lake is served by (the Queen II, the mail boat, a Léman paddle steamer, a Como battello) running from landing to
 *   landing and waiting at each, and a few small boats (Rivas, pontoons, sailing boats, a rowing boat) going about the
 *   lake on loops of their own. Their routes keep to open water a tile off the shore.
 */
export function lakeDress(k: Kit, w: World, t: Town, x0: number, z0: number, x1: number, z1: number): void {
  k.place(0, 0, 0, 0);
  const inSquare = (x: number, z: number) => x >= t.x0 && z >= t.z0 && x < t.x0 + t.size && z < t.z0 + t.size;
  const wet = (x: number, z: number) => inB(x, z) && waterDepth(w, idx(x, z)) > 0 && !w.road[idx(x, z)];
  const style = t.style, walk = walkOf(t);
  for (let z = Math.max(z0, t.z0); z < Math.min(z1, t.z0 + t.size); z++) {
    for (let x = Math.max(x0, t.x0); x < Math.min(x1, t.x0 + t.size); x++) {
      const i = idx(x, z);
      if (!walk.has(i) || w.blocked[i] || w.road[i]) continue;
      // a tile of the walk: the side the water lies on
      for (const [dx, dz] of DIRS) {
        if (!wet(x + dx, z + dz)) continue;
        const px = x + 0.5 + dx * 0.32, pz = z + 0.5 + dz * 0.32;
        const y = heightOnTile(w, x, z, px, pz) - 0.01;
        const roll = hash2(x, z, 7411);
        if (style === 'leman' || style === 'como') {
          // the railing along the quay's edge
          const ex = x + 0.5 + dx * 0.47, ez = z + 0.5 + dz * 0.47;
          k.box(ex, y + 0.01, ez, dx ? 0.012 : 1, 0.07, dz ? 0.012 : 1, IRON);
          k.box(ex, y + 0.075, ez, dx ? 0.02 : 1, 0.012, dz ? 0.02 : 1, IRON);
        }
        const qx = x + 0.5 - dx * 0.05, qz = z + 0.5 - dz * 0.05;
        if (style === 'leman') {
          if (roll < 0.45) planeTree(k, qx, y, qz, 0.95 + hash2(x, z, 7413) * 0.2);
          else if (roll < 0.7) lakeLamp(k, style, px, y, pz);
          else if (roll < 0.85) bench(k, qx, y, qz);
        } else if (style === 'como') {
          if (roll < 0.25) lakeLamp(k, style, px, y, pz);
          else if (roll < 0.45) lakePalm(k, qx, y, qz, 0.5 + hash2(x, z, 7415) * 0.15, mulberry32((x * 73856093) ^ (z * 19349663)));
          else if (roll < 0.6) oleander(k, qx, y, qz, x, z);
          else if (roll < 0.7) cypress(k, qx, y, qz, 0.75);
          else if (roll < 0.8) bench(k, qx, y, qz, IRON);
        } else {
          if (roll < 0.18) lakeLamp(k, style, px, y, pz);
          else if (roll < 0.32) bench(k, qx, y, qz);
          else if (roll < 0.4) picnic(k, qx, y, qz);
          else if (roll < 0.5) tree(k, qx, y, qz, x, z);
        }
        break;
      }
    }
  }
  // the lake's boats, once, from the chunk its first landing is in
  const piers = t.buildings.filter((b) => b.kind === 'steamerPier' && !b.gone);
  const anchor = piers[0] ?? t.buildings.find((b) => (b.kind === 'lakeDock' || b.kind === 'lakeBoathouse') && !b.gone);
  if (!anchor || anchor.x < x0 || anchor.x >= x1 || anchor.z < z0 || anchor.z >= z1) return;
  // (seen all year: the kit may still carry the last building's seasonal tag)
  k.tagged(Vis.Always, () => boats(k, w, t, piers, anchor));
}

/** The town's walk along the water: the shore it keeps unbuilt (world/lakes.ts reserves it). */
const WALKS = new WeakMap<Town, Set<number>>();
function walkOf(t: Town): Set<number> {
  let s = WALKS.get(t);
  if (!s) WALKS.set(t, (s = new Set(t.reserve ?? [])));
  return s;
}

function oleander(k: Kit, x: number, y: number, z: number, tx: number, tz: number): void {
  k.dome(x, y, z, 0.12, hex(0x4a7a3a), 7, 2);
  for (let i = 0; i < 5; i++) k.box(x + (hash2(tx, tz, 80 + i) - 0.5) * 0.18, y + 0.04 + hash2(tx, tz, 90 + i) * 0.06, z + (hash2(tx, tz, 100 + i) - 0.5) * 0.18, 0.03, 0.03, 0.03, hex(hash2(tx, tz, 110) < 0.5 ? 0xe85a9a : 0xf4f2ec));
}
function picnic(k: Kit, x: number, y: number, z: number): void {
  const wood = hex(0x8a6a48);
  k.box(x, y + 0.06, z, 0.16, 0.012, 0.08, wood);
  for (const s of [-1, 1]) k.box(x, y + 0.035, z + s * 0.07, 0.16, 0.01, 0.03, wood);
  for (const s of [-0.06, 0.06]) k.box(x + s, y, z, 0.012, 0.06, 0.1, wood);
}
function tree(k: Kit, x: number, y: number, z: number, tx: number, tz: number): void {
  const s = 0.8 + hash2(tx, tz, 7417) * 0.3;
  k.box(x, y, z, 0.05 * s, 0.24 * s, 0.05 * s, hex(0x7a5a3a));
  k.dome(x, y + 0.24 * s, z, 0.2 * s, hex(0x5a9a46), 7, 3);
}

// ---------------------------------------------------------------------------------------------
// the lake's boats

type P = [number, number];

/**
 * The lake's water near the town as a grid: which tiles are open water, and how far each is from the shore. Kept to
 * a box round the square (the lake may run on out of town, and out there into a river).
 */
function waterGrid(w: World, t: Town): { bx: number; bz: number; W: number; H: number; open: Uint8Array; clear: Float32Array } {
  const M = 24, bx = Math.max(0, t.x0 - M), bz = Math.max(0, t.z0 - M);
  const W = Math.min(N, t.x0 + t.size + M) - bx, H = Math.min(N, t.z0 + t.size + M) - bz;
  const open = new Uint8Array(W * H), clear = new Float32Array(W * H).fill(Infinity);
  const q: number[] = [];
  // the lake itself: the water joined to the water in the town's square (not a river or the sea in the same box)
  const seeds: number[] = [];
  for (let z = 0; z < H; z++) for (let x = 0; x < W; x++) {
    const i = idx(bx + x, bz + z);
    if (waterDepth(w, i) > 0 && !w.road[i] && bx + x >= t.x0 && bz + z >= t.z0 && bx + x < t.x0 + t.size && bz + z < t.z0 + t.size) { open[z * W + x] = 1; seeds.push(z * W + x); }
  }
  for (let h = 0; h < seeds.length; h++) {
    const j = seeds[h], x = j % W, z = (j - x) / W;
    for (const [dx, dz] of DIRS) {
      const nx = x + dx, nz = z + dz;
      if (nx < 0 || nz < 0 || nx >= W || nz >= H || open[nz * W + nx]) continue;
      const i = idx(bx + nx, bz + nz);
      if (waterDepth(w, i) > 0 && !w.road[i] && w.water[i] === w.water[idx(bx + x, bz + z)]) { open[nz * W + nx] = 1; seeds.push(nz * W + nx); }
    }
  }
  for (let j = 0; j < W * H; j++) if (!open[j]) { clear[j] = 0; q.push(j); }
  for (let h = 0; h < q.length; h++) {
    const j = q[h], x = j % W, z = (j - x) / W;
    for (const [dx, dz] of DIRS) {
      const nx = x + dx, nz = z + dz;
      if (nx < 0 || nz < 0 || nx >= W || nz >= H) continue;
      const k2 = nz * W + nx;
      if (clear[k2] > clear[j] + 1) { clear[k2] = clear[j] + 1; q.push(k2); }
    }
  }
  return { bx, bz, W, H, open, clear };
}

/** A way across open water from a to b (tile points), as few straight legs as will keep a tile off the shore; null if none. */
function route(g: ReturnType<typeof waterGrid>, a: P, b: P): P[] | null {
  return routeAt(g, a, b, 2) ?? routeAt(g, a, b, 1);
}

function routeAt(g: ReturnType<typeof waterGrid>, a: P, b: P, off: number): P[] | null {
  const { bx, bz, W, H, open, clear } = g;
  const cell = (p: P) => { const x = Math.floor(p[0]) - bx, z = Math.floor(p[1]) - bz; return x >= 0 && z >= 0 && x < W && z < H ? z * W + x : -1; };
  const ok = (j: number, min: number) => j >= 0 && open[j] && clear[j] >= min;
  const s = cell(a), e = cell(b);
  if (s < 0 || e < 0 || !open[s] || !open[e]) return null;
  const prev = new Int32Array(W * H).fill(-1);
  const q = [s];
  prev[s] = s;
  for (let h = 0; h < q.length && prev[e] < 0; h++) {
    const j = q[h], x = j % W, z = (j - x) / W;
    for (const [dx, dz] of DIRS) {
      const nx = x + dx, nz = z + dz;
      if (nx < 0 || nz < 0 || nx >= W || nz >= H) continue;
      const k2 = nz * W + nx;
      // a tile off the shore, except near either end (a landing is at the shore)
      const near = Math.hypot(nx + bx - a[0], nz + bz - a[1]) < 2.5 || Math.hypot(nx + bx - b[0], nz + bz - b[1]) < 2.5;
      if (prev[k2] < 0 && ok(k2, near ? 1 : off)) { prev[k2] = j; q.push(k2); }
    }
  }
  if (prev[e] < 0) return null;
  const cells: P[] = [];
  for (let j = e; ; j = prev[j]) { cells.push([(j % W) + bx + 0.5, Math.floor(j / W) + bz + 0.5]); if (j === s) break; }
  cells.reverse();
  cells[0] = a;
  cells[cells.length - 1] = b;
  // pulled straight wherever the water allows
  const sight = (p: P, q2: P) => {
    const n = Math.ceil(Math.hypot(q2[0] - p[0], q2[1] - p[1]) * 3);
    for (let i = 1; i < n; i++) { const u = i / n, c = cell([p[0] + (q2[0] - p[0]) * u, p[1] + (q2[1] - p[1]) * u]); if (c < 0 || !open[c]) return false; }
    return true;
  };
  const out: P[] = [cells[0]];
  let i = 0;
  while (i < cells.length - 1) {
    let j = cells.length - 1;
    while (j > i + 1 && !sight(cells[i], cells[j])) j--;
    out.push(cells[j]);
    i = j;
  }
  return out;
}

/** Where the boats tie up at a landing: open water off the lot on the side the lake lies on. */
function berthOf(w: World, b: Building): P | null {
  const cx = b.x + b.w / 2, cz = b.z + b.d / 2;
  let best: P | null = null, most = 0;
  for (const [dx, dz] of DIRS) {
    let n = 0, first: P | null = null;
    const half = dx ? b.w / 2 : b.d / 2;
    for (let o = 0.5; o < 4; o += 1) {
      const x = Math.floor(cx + dx * (half + o)), z = Math.floor(cz + dz * (half + o));
      if (!inB(x, z) || waterDepth(w, idx(x, z)) <= 0) break;
      n++;
      if (o >= 1.5 && !first) first = [x + 0.5, z + 0.5];
    }
    if (n > most && first) { most = n; best = first; }
  }
  return best;
}

/** The boats on the lake, as rigs whose frame is the world's: the ferry on its round of the landings, small boats on loops. */
function boats(k: Kit, w: World, t: Town, piers: Building[], anchor: Building): void {
  const g = waterGrid(w, t);
  const rnd = mulberry32((t.x0 * 92821) ^ (t.z0 * 68917) ^ 0x1a4e);
  // the open water: cells two tiles or more from the shore
  const openCells: P[] = [];
  for (let z = 0; z < g.H; z++) for (let x = 0; x < g.W; x++) if (g.open[z * g.W + x] && g.clear[z * g.W + x] >= 2.5) openCells.push([x + g.bx + 0.5, z + g.bz + 0.5]);
  if (openCells.length < 6) return;
  const lake = w.water[idx(Math.floor(openCells[0][0]), Math.floor(openCells[0][1]))];
  const wy = lake * STEP;
  const pick = (): P => openCells[Math.floor(rnd() * openCells.length)];
  // the ferry's stops: every landing, else its own landing and two far points of the lake
  const stops = piers.map((b) => berthOf(w, b)).filter((p): p is P => !!p);
  if (stops.length < 2) {
    const home = stops[0] ?? berthOf(w, anchor) ?? pick();
    const far = openCells.reduce((a, c) => (Math.hypot(c[0] - home[0], c[1] - home[1]) > Math.hypot(a[0] - home[0], a[1] - home[1]) ? c : a), openCells[0]);
    stops.splice(0, stops.length, home, far, pick());
  }
  const legs: P[][] = [];
  for (let i = 0; i < stops.length; i++) {
    const r = route(g, stops[i], stops[(i + 1) % stops.length]);
    if (r) legs.push(r);
  }
  const kind = ferryOf(t.style);
  if (legs.length) cruise(k, wy, legs, (sk) => ferry(sk, kind, 1), 0.55, piers.length >= 2 ? 9 : 4, rnd);
  // the small boats, each going round a loop of three open-water points of its own
  const fleet = t.kind === 'rural' ? 2 : t.kind === 'suburb' ? 3 : 4;
  for (let n = 0; n < fleet; n++) {
    const pts = [pick(), pick(), pick()];
    const loop: P[][] = [];
    for (let i = 0; i < 3; i++) { const r = route(g, pts[i], pts[(i + 1) % 3]); if (r) loop.push(r); }
    if (loop.length < 3) continue;
    const q = rnd();
    const draw = (sk: Kit) => sk.turned(-Math.PI / 2, () => {
      const r2 = mulberry32(Math.floor(q * 1e6));
      if (t.style === 'como') riva(sk, 0, 0, 0, 1);
      else if (t.style === 'leman') (q < 0.6 ? sailboat(sk, 0, 0, 0, r2, true) : riva(sk, 0, 0, 0, 0.95));
      else if (t.style === 'victorian') (q < 0.5 ? sailboat(sk, 0, 0, 0, r2, true) : riva(sk, 0, 0, 0, 1));
      else (q < 0.65 ? pontoon(sk, 0, 0, 0, r2) : rowboat(sk, 0, 0, 0, r2));
    });
    k.tagged(Vis.NotWinter, () => cruise(k, wy, loop, draw, t.style === 'lakeside' && q >= 0.65 ? 0.25 : 0.8, 2, rnd));
  }
}

/**
 * A boat going round `legs` (each a run of points across the water, one after another, the last back to the first),
 * at `speed` tiles a second, waiting `wait` seconds at the end of each leg, turning smoothly onto its course, rocking
 * gently. Drawn round its own origin, bow to +z.
 */
function cruise(k: Kit, wy: number, legs: P[][], draw: (sk: Kit) => void, speed: number, wait: number, rnd: () => number): void {
  const path: { p: P; stop: boolean }[] = [];
  for (const leg of legs) leg.forEach((p, i) => path.push({ p, stop: i === leg.length - 1 }));
  const segs: { a: P; b: P; len: number; stop: boolean }[] = [];
  for (let i = 0; i < path.length; i++) {
    const a = path[i].p, b = path[(i + 1) % path.length].p, len = Math.hypot(b[0] - a[0], b[1] - a[1]);
    if (len > 0.05) segs.push({ a, b, len, stop: path[(i + 1) % path.length].stop });
  }
  if (!segs.length) return;
  const [ox, oz] = segs[0].a;
  let seg = Math.floor(rnd() * segs.length), u = 0, hold = 0, head = Math.atan2(segs[seg].b[0] - segs[seg].a[0], segs[seg].b[1] - segs[seg].a[1]), clock = rnd() * 10;
  k.rig(ox, wy, oz, [draw], (ps, dt) => {
    clock += dt;
    const s = segs[seg];
    if (hold > 0) hold -= dt;
    else {
      u += (speed * dt) / s.len;
      if (u >= 1) {
        u = 0;
        if (s.stop) hold = wait;
        seg = (seg + 1) % segs.length;
      }
    }
    const c = segs[seg], x = c.a[0] + (c.b[0] - c.a[0]) * u, z = c.a[1] + (c.b[1] - c.a[1]) * u;
    const want = Math.atan2(c.b[0] - c.a[0], c.b[1] - c.a[1]);
    let d = want - head;
    d = Math.atan2(Math.sin(d), Math.cos(d));
    head += d * Math.min(1, dt * 1.8);
    const o = ps[0];
    o.position.set(x - ox, Math.sin(clock * 1.3) * 0.006, z - oz);
    o.rotation.set(Math.sin(clock * 0.9) * 0.015, head, Math.sin(clock * 1.1) * 0.02, 'YXZ');
  });
}
