import type { CargoClass } from './vehicles';
import type { SiteKind } from './cargoTypes';

/**
 * Night runs (docs/smuggling.html): the numbers, with nothing to draw and nothing to wire, so the game
 * and the gate (npm run smuggle) read the same rules. Contraband, its pay against an honest load of the
 * same trip, the fine for being caught, and the clock that says when contacts are about and when a run
 * is too long to finish before the sun comes up.
 */

type ContrabandId = 'cigarettes' | 'moonshine' | 'stolen' | 'dirtyMoney' | 'narcotics' | 'guns';

export interface Contraband {
  id: ContrabandId;
  name: string;
  icon: string;
  cls: CargoClass;
  units: number;
  /** The kind's own multiplier, before the hurry and the roll. */
  base: number;
  /** How often a contact is holding this, out of the whole table. */
  share: number;
  /** Quiet places it is picked up at, and where the buyers wait. */
  from: SiteKind[];
  to: SiteKind[];
  /** The line the offer card reads. */
  blurb: string;
}

