export const contrabandById = (id: string): Contraband | undefined => CONTRABAND.find((c) => c.id === id);

/** Every kind of place contraband comes from or goes to: the cargo system builds sites for these too. */
export const CONTRABAND_SITES: SiteKind[] = [...new Set(CONTRABAND.flatMap((c) => [...c.from, ...c.to]))];

export type NightUrgency = 'dawn' | 'tonight' | 'hot';

export const NIGHT_URGENCY: Record<NightUrgency, { label: string; k: number; share: number; /** deadline as a share of the run's estimate; 0 = sunrise */ slack: number }> = {
  dawn: { label: 'Before dawn', k: 1, share: 55, slack: 0 },
  tonight: { label: 'Tonight', k: 1.15, share: 30, slack: 1.5 },
  hot: { label: 'Hot', k: 1.3, share: 15, slack: 1.2 },
};

/** A run pays between these many times the honest price. */
const MULT_MIN = 4, MULT_MAX = 10;
/** The random roll on top of the kind and the hurry. */
export const ROLL_LO = 0.9, ROLL_HI = 1.15;

/** The pace every job is priced at, tiles a second (cargo.ts's EASY_PACE). */
export const EASY_PACE = 0.6;
/** Real seconds in a game hour (render/daynight.ts). */
export const HOUR_SECONDS = 25;
/** Sunrise and sunset, game hours. */
export const SUNRISE = 6, SUNSET = 18;
/** Contacts start to appear at this hour, once it is properly dark. */
export const CONTACTS_FROM = 18.5;
/** Slack on the estimate, and seconds for loading and the stop at the drop. */
const CUTOFF_SLACK = 1.3, CUTOFF_EXTRA = 30;
/** Runs are this long by road, in tiles. */
export const RUN_MIN = 40, RUN_MAX = 115;

/** What each unit of a load is worth to carry, by class (cargoTypes' CLASS_RATE). */
const CLASS_RATE: Record<CargoClass, number> = { people: 12, parcel: 8, freight: 6, bulk: 4, container: 5 };
/** The honest twin every run is priced against: an ordinary load of the same class and units. */
const TWIN_BASE = 45, TWIN_PER_TILE = 1.1;

const round5 = (v: number) => Math.round(v / 5) * 5;

/**
 * What an honest load of the same class and size pays for this trip at Standard urgency, with a limit
 * of exactly the trip at the easy pace: cargo.ts's valueOf with the pressure at 1.
 */
export function honestPrice(c: Contraband, dist: number): number {
  const goods = TWIN_BASE + CLASS_RATE[c.cls] * c.units + TWIN_PER_TILE * dist;
  return Math.max(5, round5(goods * (0.9 + 0.5)));
}

/** The multiplier for a run: the kind's base, the hurry and a roll in [0, 1), held to 4..10. */
export function multiplier(c: Contraband, u: NightUrgency, roll: number): number {
  const r = ROLL_LO + (ROLL_HI - ROLL_LO) * roll;
  return Math.min(MULT_MAX, Math.max(MULT_MIN, c.base * NIGHT_URGENCY[u].k * r));
}

/** What a run pays. */
export function payFor(c: Contraband, dist: number, u: NightUrgency, roll: number): number {
  return round5(honestPrice(c, dist) * multiplier(c, u, roll));
}

/** The fine for being caught: a quarter of the cash in hand, capped at $5,000 and never under $100. */
const FINE_SHARE = 0.25, FINE_CAP = 5000, FINE_MIN = 100;
export function fineFor(cash: number): number {
  return Math.max(FINE_MIN, Math.min(FINE_CAP, round5(FINE_SHARE * Math.max(0, cash))));
}

/** Is it night, as the police and the contacts reckon it? */
export function isNight(hour: number): boolean {
  return hour >= CONTACTS_FROM || hour < SUNRISE;
}

/** Game hours until 06:00. */
function hoursToDawn(hour: number): number {
  return (SUNRISE - hour + 24) % 24;
}

/** The absolute game hour (days × 24 + hour) of the next sunrise. */
export function nextDawn(abs: number): number {
  const day = Math.floor(abs / 24), hour = abs - day * 24;
  return hour < SUNRISE ? day * 24 + SUNRISE : (day + 1) * 24 + SUNRISE;
}

/** Real seconds a run of this many road tiles is expected to take: the pace, the slack, the stops. */
function runSeconds(tiles: number): number {
  return (CUTOFF_SLACK * tiles) / EASY_PACE + CUTOFF_EXTRA;
}

/** Is there time to offer a run this long at this hour? Only after dusk, and only with time to finish before dawn. */
export function offerOpen(tiles: number, hour: number): boolean {
  if (!isNight(hour)) return false;
  return hoursToDawn(hour) * HOUR_SECONDS >= runSeconds(tiles);
}

/** The latest hour a run of this length is offered: the cutoff table on the page. */
export function latestOffer(tiles: number): number {
  return (SUNRISE - runSeconds(tiles) / HOUR_SECONDS + 24) % 24;
}

/** Pick from a table by its shares, with a roll in [0, 1). */
export function byShare<T extends { share: number }>(list: T[], roll: number): T {
  const total = list.reduce((s, x) => s + x.share, 0);
  let r = roll * total;
  for (const x of list) { r -= x.share; if (r < 0) return x; }
  return list[list.length - 1];
}
