import { SURVEY_C, SURVEY_PER } from '../world/survey';

/**
 * Where the traffic goes (the user, 4 Nov 2026: "a heatmap showing road segments where the most vehicles have
 * driven in the last 10 game years"): every road vehicle this game sees moving, the CPU's, the fleet's, other
 * players' and the player's own, counted each time it comes onto a map pixel (two tiles, the region map's
 * survey pixel, world/survey.ts). Kept a game year to a bucket and only the last YEARS of them, so the map shows
 * the last ten years and old roads cool off. Kept on this device per world (localStorage), not in the save:
 * it is a picture of what this game has seen, and every client sees its own part of the world.
 */
export const TRAFFIC_YEARS = 10;
/** Pixels a vehicle may jump between two looks and still be counted along the way (further is a tow or a teleport). */
const MAX_JUMP = 24;
const STORE = 'tinyfleet-traffic:';
/** Seconds between writes to storage. */
const SAVE_EVERY = 90;
/** Storage is small: past this many characters the oldest years are let go until it fits. */
const MAX_CHARS = 1_500_000;

const P = SURVEY_C;
/** A global pixel id: county and pixel within it. */
const cellKey = (cx: number, cz: number) => `${cx},${cz}`;

export class TrafficLog {
  /** year → county → pixel → passes. */
  private years = new Map<number, Map<string, Map<number, number>>>();
  /** Each vehicle's last pixel, global (px, pz), and when it was last seen (to forget the gone). */
  private last = new Map<string, { px: number; pz: number; seen: number }>();
  private world = '';
  private year = 0;
  private saveT = SAVE_EVERY;
  private dirty = false;
  private tick = 0;
  /** Changes whenever a count does, at most once a second or so (the map redraws on it). */
  version = 0;
  private sum = new Map<string, { v: number; a: Uint32Array | null }>();

  /** A new world (or the same one again after a load): read what this device saw of it. */
  begin(world: string, year: number): void {
    if (world === this.world) { this.year = year; return; }
    this.flush();
    this.world = world;
    this.year = year;
    this.years.clear();
    this.last.clear();
    this.sum.clear();
    this.version++;
    try {
      const raw = localStorage.getItem(STORE + world);
      if (raw) this.read(JSON.parse(raw) as Record<string, Record<string, string>>);
    } catch { /* storage blocked or old */ }
    this.trim();
  }

  /**
   * A vehicle seen at global tiles (gx, gz) in game year `year`: every pixel it has come onto since the last look
   * is counted once (a straight walk between the two, so a fast car between looks still lights the road it took).
   */
  note(id: string, gx: number, gz: number, year: number): void {
    if (!this.world) return;
    if (year !== this.year) { this.year = year; this.trim(); }
    const px = Math.floor(gx / SURVEY_PER), pz = Math.floor(gz / SURVEY_PER);
    const was = this.last.get(id);
    this.last.set(id, { px, pz, seen: this.tick });
    if (was && was.px === px && was.pz === pz) return;
    if (!was || Math.max(Math.abs(px - was.px), Math.abs(pz - was.pz)) > MAX_JUMP) { this.add(px, pz); return; }
    // the pixels between, the one it left not counted again
    const dx = px - was.px, dz = pz - was.pz, n = Math.max(Math.abs(dx), Math.abs(dz));
    for (let k = 1; k <= n; k++) this.add(was.px + Math.round((dx * k) / n), was.pz + Math.round((dz * k) / n));
  }

  /** Once a look round every vehicle is done: forget the ones not seen for a while, and write to storage now and then. */
  step(dt: number): void {
    this.tick++;
    if (this.tick % 64 === 0) for (const [k, v] of this.last) if (this.tick - v.seen > 64) this.last.delete(k);
    this.saveT -= dt;
    if (this.saveT <= 0) { this.saveT = SAVE_EVERY; this.flush(); }
  }

  /** One county's passes over the last TRAFFIC_YEARS years, a count a survey pixel (SURVEY_C squared), or null for none. */
  cell(cx: number, cz: number): Uint32Array | null {
    const k = cellKey(cx, cz);
    const had = this.sum.get(k);
    if (had && had.v === this.version) return had.a;
    let a: Uint32Array | null = null;
    for (const [y, cells] of this.years) {
      if (y <= this.year - TRAFFIC_YEARS) continue;
      const m = cells.get(k);
      if (!m) continue;
      a ??= new Uint32Array(P * P);
      for (const [i, n] of m) a[i] += n;
    }
    this.sum.set(k, { v: this.version, a });
    return a;
  }

  /** Write to storage (and on the way out of the page). */
  flush(): void {
    if (!this.world || !this.dirty) return;
    this.dirty = false;
    for (;;) {
      const text = JSON.stringify(this.write());
      try {
        if (text.length > MAX_CHARS) throw new Error('too big');
        localStorage.setItem(STORE + this.world, text);
        return;
      } catch {
        // full: let the oldest year go and try again (the last one standing is kept whatever)
        if (this.years.size <= 1) return;
        this.years.delete(Math.min(...this.years.keys()));
        this.version++;
      }
    }
  }

  private add(px: number, pz: number): void {
    const cx = Math.floor(px / P), cz = Math.floor(pz / P);
    const i = (pz - cz * P) * P + (px - cx * P);
    let cells = this.years.get(this.year);
    if (!cells) { cells = new Map(); this.years.set(this.year, cells); }
    const k = cellKey(cx, cz);
    let m = cells.get(k);
    if (!m) { m = new Map(); cells.set(k, m); }
    m.set(i, (m.get(i) ?? 0) + 1);
    this.dirty = true;
    // the map draws again on a new version: once a second is plenty
    const now = Math.floor(performance.now() / 1000);
    if (now !== this.stamp) { this.stamp = now; this.version++; }
  }
  private stamp = 0;

  /** Drop the years that have run out of the window. */
  private trim(): void {
    for (const y of [...this.years.keys()]) if (y <= this.year - TRAFFIC_YEARS || y > this.year + 1) { this.years.delete(y); this.version++; this.dirty = true; }
  }

  /** As stored: year → county → pixel/count pairs in base 36, "i:n,i:n". */
  private write(): Record<string, Record<string, string>> {
    const out: Record<string, Record<string, string>> = {};
    for (const [y, cells] of this.years) {
      const o: Record<string, string> = {};
      for (const [k, m] of cells) o[k] = [...m].map(([i, n]) => `${i.toString(36)}:${n.toString(36)}`).join(',');
      out[y] = o;
    }
    return out;
  }

  private read(o: Record<string, Record<string, string>>): void {
    for (const [ys, cells] of Object.entries(o)) {
      const y = Number(ys);
      if (!Number.isFinite(y)) continue;
      const map = new Map<string, Map<number, number>>();
      for (const [k, s] of Object.entries(cells)) {
        const m = new Map<number, number>();
        for (const pair of s.split(',')) {
          const [i, n] = pair.split(':').map((v) => parseInt(v, 36));
          if (i >= 0 && i < P * P && n > 0) m.set(i, n);
        }
        if (m.size) map.set(k, m);
      }
      this.years.set(y, map);
    }
  }
}
