/**
 * The factions (docs/factions.html): ten powers that live in the world, each with its colours, its crest,
 * its buildings, its vehicles and one bar of standing with the player. This file is the roster and the
 * rules every other file reads: who they are, what they want, how they feel about each other, the ladder
 * a bar climbs, and the three things each one unlocks. Nothing in it changes at run time.
 */

export type FactionId = 'police' | 'family' | 'ministry' | 'visitors' | 'unions' | 'post' | 'army' | 'studios' | 'guild' | 'press';
export const FACTION_IDS: FactionId[] = ['police', 'family', 'ministry', 'visitors', 'unions', 'post', 'army', 'studios', 'guild', 'press'];

/** One of a faction's three unlocks: a paintjob on a model, or a model put on sale. */
export interface Unlock {
  /** The unlock's own id, kept in the player's account forever (game/factions/unlocks.ts). */
  id: string;
  kind: 'job' | 'model';
  /** The model: the one the paintjob goes on, or the one put on sale. */
  model: string;
  /** What the player sees it called. */
  name: string;
  /** One line on what it is and what it does. */
  blurb: string;
}

interface FactionDef {
  id: FactionId;
  /** Its name in the game, the plain word for what it is, and a short name for tight places. */
  name: string; common: string; short: string;
  /** Livery: the body colour and the accent, on its buildings, its vehicles and its bar. */
  colour: number; accent: number;
  /** The crest's glyph (a text symbol Segoe UI Symbol draws: no colour emoji) and an emoji for HUD lines. */
  glyph: string; icon: string;
  blurb: string;
  /** What it pays for and what it hates, in a line each (the Factions screen). */
  wants: string; hates: string;
  /** What its people do to a player at Hostile and below, and for one who is Sworn, in a line. */
  hostile: string; sworn: string;
  /** Its people's small help at Honoured, in a line. */
  honoured: string;
  /** Who gives its work, and where: building kinds in order of preference (the first found near the player wins). */
  giver: string; hall: string[];
  /** Friend, Honoured, Sworn. */
  unlocks: [Unlock, Unlock, Unlock];
}

const job = (f: FactionId, model: string, name: string, blurb: string): Unlock => ({ id: `job:${f}`, kind: 'job', model, name, blurb });
const mdl = (model: string, name: string, blurb: string): Unlock => ({ id: `model:${model}`, kind: 'model', model, name, blurb });

