export const factionOf = (id: string): FactionDef | undefined => (FACTIONS as Record<string, FactionDef>)[id];

/** Every unlock by its id, with its faction and rung (4 Friend, 5 Honoured, 6 Sworn). */
export const UNLOCKS = new Map<string, { u: Unlock; f: FactionId; rung: number }>();
for (const f of FACTION_IDS) FACTIONS[f].unlocks.forEach((u, k) => UNLOCKS.set(u.id, { u, f, rung: 4 + k }));

/**
 * Models that only a faction's standing puts on sale (beyond each faction's own Honoured and Sworn vehicles):
 * the military's hardware, and the patrol car. A model the player already owns stays theirs whatever.
 */
export const GATED: Record<string, { f: FactionId; rung: number }> = {
  humvee: { f: 'army', rung: 4 }, chinook: { f: 'army', rung: 4 }, tank: { f: 'army', rung: 5 },
  fighter: { f: 'army', rung: 6 }, carrier: { f: 'army', rung: 6 },
};
for (const [, v] of UNLOCKS) if (v.u.kind === 'model') GATED[v.u.model] = { f: v.f, rung: v.rung };

// ---- the ladder ----------------------------------------------------------------------------------

export const REP_MIN = -6000, REP_MAX = 10000;
/** The bar stops here until the faction's Oath is done. */
export const OATH_AT = 9999;

export interface Rung { name: string; at: number; colour: string }
/** The seven rungs, lowest first: a bar is on the highest rung whose `at` it has reached. */
/** How far below zero a bar can fall and still read Neutral. */
const NEUTRAL_GIVE = 100;

export const RUNGS: Rung[] = [
  { name: 'Outcast', at: -Infinity, colour: '#b32d22' },
  { name: 'Hostile', at: -5999, colour: '#d2533f' },
  { name: 'Wary', at: -2999, colour: '#e0a24a' },
  // a little give below zero: a new player's first few loads for one side (each spilling onto its
  // opposite) don't make the other side Wary of them straight away
  { name: 'Neutral', at: -NEUTRAL_GIVE, colour: '#9aa6ad' },
  { name: 'Friend', at: 1000, colour: '#6faf57' },
  { name: 'Honoured', at: 4000, colour: '#3f9b6a' },
  { name: 'Sworn', at: 10000, colour: '#d9b34a' },
];
export const RUNG = { outcast: 0, hostile: 1, wary: 2, neutral: 3, friend: 4, honoured: 5, sworn: 6 } as const;

export function rungOf(points: number): number {
  for (let i = RUNGS.length - 1; i > 0; i--) if (points >= RUNGS[i].at) return i;
  return points <= REP_MIN ? 0 : 1;
}

/** What a faction's own cargo pays the player at each rung (Hostile and Outcast: not offered at all, and ×0.8 if carried anyway). */
export const PAY_MUL = [0.8, 0.8, 0.9, 1, 1.1, 1.2, 1.3];

/** The pace (docs/factions.html, "Pace"). */
export const PACE = {
  /** A delivery of the faction's own cargo moves its bar by the load's value over this. */
  cargo: 8,
  /** Any other delivery to one of its doors, over this. */
  door: 16,
  /** No one act moves a bar further than this either way (the Oath's steps pay their own). */
  cap: 300,
  /** Acts by a hired driver count this much. */
  crew: 0.5,
  /** Below zero, a bar heals by this much each game day with no new offence. */
  heal: 50,
  /** One Oath step. */
  oathStep: 250,
  /** A dollar on roads and earthworks is this many Brotherhood points (before the cap). */
  perDollar: 0.25,
};

