export function contestFor(cargo: string, from: string | undefined, to: string): Contest | null {
  for (const c of CONTESTS) {
    if (c.cargo !== cargo) continue;
    if (c.to && !c.to.includes(to)) continue;
    if (c.from && (!from || !c.from.includes(from))) continue;
    return c;
  }
  return null;
}

/** Mission givers and templates that work for a faction (docs/factions.html, "How standing moves"). */
const GIVER_FACTION: Record<string, FactionId> = {
  police: 'police', detective: 'police', smuggler: 'family', reporter: 'press', news: 'press', studio: 'studios',
  coastguard: 'guild', harbour: 'guild', rescue: 'guild',
};
const TPL_FACTION: [string, FactionId][] = [
  ['sea:', 'guild'], ['fac:police', 'police'], ['fac:family', 'family'], ['fac:ministry', 'ministry'], ['fac:visitors', 'visitors'],
  ['fac:unions', 'unions'], ['fac:post', 'post'], ['fac:army', 'army'], ['fac:studios', 'studios'], ['fac:guild', 'guild'], ['fac:press', 'press'],
  ['oath:police', 'police'], ['oath:family', 'family'], ['oath:ministry', 'ministry'], ['oath:visitors', 'visitors'], ['oath:unions', 'unions'],
  ['oath:post', 'post'], ['oath:army', 'army'], ['oath:studios', 'studios'], ['oath:guild', 'guild'], ['oath:press', 'press'],
  ...FACTION_IDS.map((f): [string, FactionId] => [`rise:${f}:`, f]),
];
export function missionFaction(tpl: string, who: string): FactionId | undefined {
  for (const [p, f] of TPL_FACTION) if (tpl.startsWith(p)) return f;
  return GIVER_FACTION[who];
}

