/** The models a faction's depot can sell: its two vehicles and, for the Army, the hardware it keeps. */
export function depotModels(f: FactionId): string[] {
  const own = FACTIONS[f].unlocks.filter((u) => u.kind === 'model').map((u) => u.model);
  const kept = Object.entries(GATED).filter(([, g]) => g.f === f).map(([m]) => m);
  return [...new Set([...own, ...kept])];
}

