import { cellKind, coastalContinent, hasMega, regionAt } from '../../world/macro';
import type { CellKind, RegionKind } from '../../world/tiles';

/**
 * The kinds of in-world event (docs/events.html): what each is, how rare, when in the day it happens and
 * the cheap test, from the seed alone, of whether a county could hold one. The calendar (calendar.ts) puts
 * them on days; the stage (stage.ts) finds the actual place in the county once it is in memory, and plays it.
 *
 * Only kinds that are built are in the table: a kind still on paper would take slots from the others.
 */

export type EventKind = 'parade' | 'motorcade' | 'carShow' | 'newYear'
  // phase 2: water, air, the military, light
  | 'regatta' | 'boatParade' | 'militaryParade' | 'pride' | 'airShow' | 'tallShips' | 'lightShow' | 'winterLights' | 'spookyNight'
  // phase 3: races
  | 'offroadRace' | 'powerboatRace' | 'driftMeet' | 'dragonBoats' | 'gondolaRegatta'
  // phase 4: everything else
  | 'vintageRally' | 'weddingConvoy' | 'monsterTrucks' | 'truckConvoy' | 'circusCaravan' | 'foodTrucks' | 'cycleRace' | 'royalProcession'
  | 'tractorRun' | 'fireboatSalute' | 'blessingFleet' | 'balloonFestival' | 'sponsorBlimp' | 'launchWatch' | 'marathon' | 'streetMarket'
  | 'mardiGras' | 'lunarNewYear' | 'lanternFestival' | 'veniceCarnival' | 'harvestFair' | 'parkConcert' | 'strikePickets' | 'climateMarch'
  | 'grandOpening' | 'premiereNight' | 'blackout' | 'meteorShower' | 'eclipse' | 'aurora' | 'whalePod' | 'murmuration' | 'superbloom'
  // after: at the town pool
  | 'swimMeet'
  // the markets (0.7.0, NEXT_WORLD): recurring, on a calendar of their own outside the 40-day rule (MARKETS)
  | 'farmersMarket' | 'christmasMarket';

/** How a kind comes round in a county: every `period` days on its own slot, or one year in `years` on a day of the year. */
type Cadence =
  | { k: 'slot'; period: number }
  | { k: 'rotation'; years: number; season: 0 | 1 | 2 | 3 }
  /** A title won: a window of `win` days on its own slot every `period` days, on the evening after a season's final table. */
  | { k: 'title'; period: number; win: number }
  /** Moving across counties: routes in a region of REGION × REGION counties, each on its own day of a `period`-day cycle. */
  | { k: 'route'; period: number }
  /** A market: every week on its weekday (farmers'), or every winter's day (Christmas). Not on the 40-day calendar (calendar.ts marketsOn). */
  | { k: 'market'; weekday?: number; season?: number };

export interface KindSpec {
  id: EventKind;
  name: string;
  /** For the map pin, the log line and the stamp. */
  icon: string;
  /** What the stamp page says about it, in a few words. */
  blurb: string;
  cadence: Cadence;
  /** The chance it goes ahead on a slot day (a route: on its day). */
  gate: number;
  /** Crowds, closures and noise: at most MAJORS of these in a 3 × 3 block of counties on a day. */
  major: boolean;
  /** The game hours its start falls between (a day's hours; 22.5 is half past ten at night). */
  hours: [number, number];
  /** Game hours it runs once started (a route works its own out). */
  dur: number;
  /** Game hours before its start that the place is got ready: crowds gathering, barriers, the stage. */
  lead: number;
  /** Game hours after its end it is packed away (a market: its roads stay shut till then). */
  pack?: number;
  /** Only in these seasons (0 spring … 3 winter): a slot in another passes. Its period is kept off a multiple of four so every county's slots come round the seasons. */
  seasons?: number[];
  /**
   * Which goes ahead when two kinds' slots fall on one county's day (and which majors a block keeps): the higher.
   * By default its spacing, so the rarer wins. A kind that needs something few counties have (a Venice's canals)
   * is ranked low, so it doesn't take the day from a kind the county can hold.
   */
  rank?: number;
  /** A moving kind's game hours in each county it crosses (the motorcade's, if not given). */
  perCounty?: number;
  /** Could this county hold one, from the seed alone. */
  could: (sh: number, cx: number, cz: number) => boolean;
}

/** Cells with towns of some size: islands, the bigger islets and the continent's counties. */
const TOWNED = new Set<CellKind>(['full', 'small', 'continent']);
const towned = (sh: number, cx: number, cz: number): boolean => TOWNED.has(cellKind(sh, cx, cz));
/** Where a city or bigger is likely: a full island or a county of the continent. */
const citied = (sh: number, cx: number, cz: number): boolean => { const k = cellKind(sh, cx, cz); return k === 'full' || k === 'continent'; };
/** Open water at the county's edge: an island, or a continental county on the coast. */
const coasted = (sh: number, cx: number, cz: number): boolean => {
  const k = cellKind(sh, cx, cz);
  return k === 'full' || k === 'small' || (k === 'continent' && coastalContinent(sh, cx, cz));
};
/**
 * A county that counts as a seat of government for a motorcade: a megalopolis's, or about one in five of the
 * counties likely to have a city (the world has no capitals of its own; the region's are these).
 */
export const capital = (sh: number, cx: number, cz: number): boolean => {
  if (hasMega(sh, cx, cz)) return true;
  if (!citied(sh, cx, cz)) return false;
  let h = Math.imul(sh ^ Math.imul(cx, 0x27d4eb2d) ^ Math.imul(cz, 0x165667b1) ^ 0xca91, 0x85ebca6b);
  h ^= h >>> 15;
  return (h >>> 0) / 4294967296 < 0.2;
};
/** Open country for a rally: the deserts, mesas, golden hills, steppe and moors, and a few counties of anywhere else. */
const OPEN = new Set<string>(['sands', 'redrock', 'goldhills', 'steppe', 'moors', 'saltpan', 'veldt', 'heights', 'firecoast', 'lavender']);
export const wild = (sh: number, cx: number, cz: number): boolean => {
  const k = cellKind(sh, cx, cz);
  if (k !== 'full' && k !== 'continent') return false;
  const r = regionAt(sh, cx, cz);
  if (r && OPEN.has(r)) return true;
  let h = Math.imul(sh ^ Math.imul(cx, 0x2c1b3c6d) ^ Math.imul(cz, 0x297a2d39) ^ 0x51ed, 0x85ebca6b);
  h ^= h >>> 15;
  return (h >>> 0) / 4294967296 < 0.15;
};
/** Farm country: the green, the golden hills, the lavender, the veldt and the moors, and a share of anywhere else. */
const FARM = new Set<string>(['green', 'goldhills', 'lavender', 'veldt', 'moors', 'terraces']);
const roll = (sh: number, cx: number, cz: number, salt: number): number => {
  let h = Math.imul(sh ^ Math.imul(cx, 0x3c6ef372) ^ Math.imul(cz, 0x1b873593) ^ salt, 0x85ebca6b);
  h ^= h >>> 15;
  return (h >>> 0) / 4294967296;
};
export const farmland = (sh: number, cx: number, cz: number): boolean => {
  if (!towned(sh, cx, cz)) return false;
  const r = regionAt(sh, cx, cz);
  return r ? FARM.has(r) : roll(sh, cx, cz, 0x7a1) < 0.45;
};
/** Cold country, for the aurora: the ice, the fjords, the heights, the big timber. */
const COLD = new Set<string>(['icefield', 'fjords', 'heights', 'bigtimber', 'steppe']);
export const cold = (sh: number, cx: number, cz: number): boolean => {
  if (cellKind(sh, cx, cz) === 'sea') return false;
  const r = regionAt(sh, cx, cz);
  return r ? COLD.has(r) : roll(sh, cx, cz, 0x2b9) < 0.08;
};
/** Desert and dry hills, for a superbloom. */
const DRY = new Set<string>(['sands', 'goldhills', 'redrock', 'saltpan', 'veldt']);
export const desert = (sh: number, cx: number, cz: number): boolean => { const r = regionAt(sh, cx, cz); return !!r && DRY.has(r); };
/** A biome the county is in, if it is in one. */
const biomeOf = (sh: number, cx: number, cz: number): RegionKind | null => regionAt(sh, cx, cz);

