/**
 * The toppers' models (docs/toppers.html, game/toppers.ts). Each is built once from a few primitives into at most four
 * merged geometries (still or turning, matte or shiny), coloured per vertex, and shared by every vehicle wearing it;
 * the materials are two, shared by every topper, both flat standard with vertex colours (the program every merged
 * vehicle body already uses, render/vehicleMeshes.ts mergeStatic), so a topper turning up compiles nothing.
 *
 * Units: a topper stands on y = 0, about one tall and within ±0.5 across, its front to +z (the vehicle's nose).
 * render/treats.ts measures the roof and scales it to the body. The Wonder Ball (`wonder`) is drawn by
 * render/wonderBall.ts and has no model here. `npm run toppers` checks every model against its bounds and budget.
 */

export const TOPPER_TRI_MAX = 900;
/** A crown carries its cargo's whole ring model (up to 2,400 triangles, render/cargoModels.ts) inside its band. */
export const CROWN_TRI_MAX = 3000;
/** A mascot is its model's whole body, shrunk (render/vehicleMeshes.ts). */
export const MASCOT_TRI_MAX = 8000;

type Axis = 'x' | 'y' | 'z';
type V3 = [number, number, number];

/** A part of a topper turning about its own origin by the clock as it is drawn (as the Wonder Ball, render/wonderBall.ts). */
class Turning extends THREE.Mesh {
  axis: Axis = 'y';
  rate = 1;
  phase = Math.random() * Math.PI * 2;
  override onBeforeRender(): void {
    this.rotation[this.axis] = (performance.now() / 1000) * this.rate + this.phase;
    this.updateMatrix();
    if (this.parent) this.matrixWorld.multiplyMatrices(this.parent.matrixWorld, this.matrix);
    else this.matrixWorld.copy(this.matrix);
  }
}

let mats: { matte: THREE.MeshStandardMaterial; shiny: THREE.MeshStandardMaterial } | null = null;
function topperMats(): NonNullable<typeof mats> {
  if (mats) return mats;
  const mk = (rough: number, metal: number): THREE.MeshStandardMaterial => {
    const m = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: rough, metalness: metal, flatShading: true });
    m.userData.shared = true;
    return m;
  };
  mats = { matte: mk(0.62, 0.05), shiny: mk(0.25, 0.42) };
  return mats;
}

/** One topper's pieces: a still part and turning parts, each matte and shiny. */
interface Piece { geo: THREE.BufferGeometry; shiny: boolean; spin: { axis: Axis; rate: number; at: V3 } | null }

class Kit {
  private buckets = new Map<string, { list: THREE.BufferGeometry[]; shiny: boolean; spin: Piece['spin'] }>();
  private cur: Piece['spin'] = null;
  private c = new THREE.Color();
  private m = new THREE.Matrix4();
  private q = new THREE.Quaternion();
  private e = new THREE.Euler();

  /** Every colour added from here in gold (the Patron's culture toppers). */
  gild = false;

  /** A geometry already placed and coloured per vertex (a mascot's body): taken as it is. */
  addColoured(geo: THREE.BufferGeometry, shiny = false): this {
    const key = `${shiny ? 1 : 0}|${this.cur ? `${this.cur.axis}${this.cur.rate}${this.cur.at.join(',')}` : ''}`;
    const b = this.buckets.get(key) ?? { list: [], shiny, spin: this.cur };
    b.list.push(geo);
    this.buckets.set(key, b);
    return this;
  }

  /** What follows turns about `axis` round the point `at`, its coordinates from that point; `still()` ends it. */
  spin(axis: Axis, rate: number, at: V3 = [0, 0, 0]): this { this.cur = { axis, rate, at }; return this; }
  still(): this { this.cur = null; return this; }

  add(g: THREE.BufferGeometry, col: number, shiny: boolean, at: V3, rot: V3 = [0, 0, 0], scale: V3 = [1, 1, 1]): this {
    this.e.set(rot[0], rot[1], rot[2]);
    this.q.setFromEuler(this.e);
    this.m.compose(new THREE.Vector3(...at), this.q, new THREE.Vector3(...scale));
    let geo = g.index ? g.toNonIndexed() : g;
    if (geo === g) geo = g.clone();
    geo.applyMatrix4(this.m);
    for (const k of Object.keys(geo.attributes)) if (k !== 'position' && k !== 'normal') geo.deleteAttribute(k);
    this.c.setHex(col);
    // the Patron's finish (phase 3): every colour turned to gold, lighter where the colour was light
    if (this.gild) {
      const l = 0.3 * this.c.r + 0.59 * this.c.g + 0.11 * this.c.b, f = 0.5 + 0.7 * l;
      this.c.setRGB(Math.min(1, f), Math.min(1, 0.8 * f), Math.min(1, 0.3 * f));
      shiny = true;
    }
    const n = geo.getAttribute('position').count, cc = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) cc.set([this.c.r, this.c.g, this.c.b], i * 3);
    geo.setAttribute('color', new THREE.BufferAttribute(cc, 3));
    const key = `${shiny ? 1 : 0}|${this.cur ? `${this.cur.axis}${this.cur.rate}${this.cur.at.join(',')}` : ''}`;
    const b = this.buckets.get(key) ?? { list: [], shiny, spin: this.cur };
    b.list.push(geo);
    this.buckets.set(key, b);
    g.dispose();
    return this;
  }

  box(w: number, h: number, d: number, at: V3, col: number, shiny = false, rot?: V3): this {
    return this.add(new THREE.BoxGeometry(w, h, d), col, shiny, at, rot);
  }
  cyl(rt: number, rb: number, h: number, seg: number, at: V3, col: number, shiny = false, rot?: V3): this {
    return this.add(new THREE.CylinderGeometry(rt, rb, h, seg), col, shiny, at, rot);
  }
  ball(r: number, at: V3, col: number, shiny = false, scale: V3 = [1, 1, 1], seg = 12, rot?: V3): this {
    return this.add(new THREE.SphereGeometry(r, seg, Math.max(4, Math.round(seg * 0.6))), col, shiny, at, rot, scale);
  }
  /** The top half of a ball. */
  dome(r: number, at: V3, col: number, shiny = false, scale: V3 = [1, 1, 1], seg = 14): this {
    return this.add(new THREE.SphereGeometry(r, seg, Math.max(3, Math.round(seg * 0.35)), 0, Math.PI * 2, 0, Math.PI / 2), col, shiny, at, undefined, scale);
  }
  /** A slice of a ball, round y from phi0 across dphi (a balloon's gore). */
  gore(r: number, phi0: number, dphi: number, at: V3, col: number, scale: V3 = [1, 1, 1]): this {
    return this.add(new THREE.SphereGeometry(r, 3, 8, phi0, dphi), col, false, at, undefined, scale);
  }
  torus(R: number, t: number, at: V3, col: number, shiny = false, rot?: V3, arc = Math.PI * 2, seg = 18): this {
    return this.add(new THREE.TorusGeometry(R, t, 6, seg, arc), col, shiny, at, rot);
  }
  /** A flat shape in the xy plane, `depth` thick along z. */
  flat(pts: [number, number][], depth: number, at: V3, col: number, shiny = false, rot?: V3): this {
    const s = new THREE.Shape(pts.map(([x, y]) => new THREE.Vector2(x, y)));
    const g = new THREE.ExtrudeGeometry(s, { depth, bevelEnabled: false });
    g.translate(0, 0, -depth / 2);
    return this.add(g, col, shiny, at, rot);
  }
  lathe(pts: [number, number][], seg: number, at: V3, col: number, shiny = false): this {
    return this.add(new THREE.LatheGeometry(pts.map(([x, y]) => new THREE.Vector2(x, y)), seg), col, shiny, at);
  }

  pieces(): Piece[] {
    const out: Piece[] = [];
    for (const b of this.buckets.values()) {
      const geo = mergeGeometries(b.list, false);
      b.list.forEach((g) => g.dispose());
      if (!geo) continue;
      geo.computeBoundingSphere();
      out.push({ geo, shiny: b.shiny, spin: b.spin });
    }
    return out;
  }
}

