// ---- the ladders: one prop each, its metal by step ----
function ladder(key: string, step: number): ((k: Kit) => void) | null {
  const m = metal(step);
  const gem = (k: Kit, y: number) => { if (step >= 4) k.ball(0.06, [0, y, 0], 0x5ad1ff, true, [1, 1.3, 1], 8); };
  switch (key) {
    case 'odo': return (k) => { k.cyl(0.2, 0.24, 0.06, 16, [0, 0.03, 0], m, true).cyl(0.025, 0.03, 0.14, 8, [0, 0.12, 0], m, true);
      k.spin('y', 2, [0, 0.46, 0]).torus(0.24, 0.09, [0, 0, 0], C.black, false, [0, 0, 0], PI * 2, 16).cyl(0.15, 0.15, 0.12, 14, [0, 0, 0], m, true, [PI / 2, 0, 0]).still(); gem(k, 0.88); };
    case 'hauler': return (k) => {
      let y = 0;
      for (let i = 0; i < step; i++) {
        const c = 0.34 - i * 0.04, ry = i % 2 ? 0.4 : -0.1;
        k.box(c, c, c, [0, y + c / 2, 0], C.wood, false, [0, ry, 0]).box(c + 0.01, 0.04, c + 0.01, [0, y + c * 0.72, 0], m, true, [0, ry, 0]);
        y += c;
      }
    };
    case 'tycoon': return (k) => {
      if (step === 1) post(k, 0.12, m).cyl(0.27, 0.27, 0.05, 22, [0, 0.42, 0], m, true, [PI / 2, 0, 0]).cyl(0.2, 0.2, 0.055, 22, [0, 0.42, 0], 0xb36d30, true, [PI / 2, 0, 0]);
      else if (step === 2) k.ball(0.27, [0, 0.27, 0], C.tan, false, [1, 0.95, 1]).cyl(0.07, 0.1, 0.12, 10, [0, 0.56, 0], C.tan).torus(0.08, 0.02, [0, 0.52, 0], m, true, [PI / 2, 0, 0])
        .box(0.06, 0.18, 0.02, [0, 0.27, 0.27], m, true).box(0.14, 0.03, 0.02, [0, 0.31, 0.275], m, true).box(0.14, 0.03, 0.02, [0, 0.23, 0.275], m, true);
      else if (step === 3) for (const [x, y] of [[-0.26, 0], [0, 0], [0.26, 0], [-0.13, 1], [0.13, 1], [0, 2]] as [number, number][]) k.box(0.24, 0.11, 0.14, [x, 0.055 + y * 0.11, 0], m, true);
      else { k.cyl(0.4, 0.4, 0.03, 22, [0, 0.03, 0], C.black).cyl(0.24, 0.25, 0.52, 18, [0, 0.3, 0], C.black).cyl(0.255, 0.255, 0.08, 18, [0, 0.1, 0], m, true); gem(k, 0.62); }
    };
    case 'fleet': return (k) => {
      post(k, 0.9, m).ball(0.045, [0, 0.92, 0], m, true);
      const cols = [C.red, C.blue, C.yellow, C.green];
      for (let i = 0; i < step; i++) k.flat([[0, 0], [0.34 - i * 0.04, -0.06], [0, -0.12]], 0.015, [0.02, 0.86 - i * 0.17, 0], cols[i]);
    };
    case 'landlord': return (k) => {
      for (let i = 0; i < step; i++) k.cyl(0.19 - i * 0.012, 0.21 - i * 0.012, 0.18, 8, [0, 0.09 + i * 0.18, 0], C.stone);
      const top = step * 0.18, r = 0.19 - (step - 1) * 0.012;
      for (let i = 0; i < 6; i++) { const a = (i / 6) * PI * 2; k.box(0.07, 0.06, 0.07, [Math.cos(a) * r * 0.9, top + 0.03, Math.sin(a) * r * 0.9], C.stone, false, [0, -a, 0]); }
      k.cyl(0.01, 0.01, 0.28, 6, [0, top + 0.14, 0], C.dark).flat([[0, 0], [0.18, -0.05], [0, -0.1]], 0.012, [0.01, top + 0.27, 0], m, true);
    };
    case 'roads': return (k) => {
      const at: [number, number][][] = [[], [[0, 0]], [[-0.17, 0], [0.17, 0]], [[-0.18, -0.12], [0.18, -0.12], [0, 0.18]], [[-0.18, -0.18], [0.18, -0.18], [-0.18, 0.18], [0.18, 0.18]]];
      for (const [x, z] of at[step]) {
        k.box(0.24, 0.03, 0.24, [x, 0.015, z], C.black).cyl(0.02, 0.12, 0.34, 10, [x, 0.2, z], C.orange).cyl(0.075, 0.095, 0.06, 10, [x, 0.2, z], m, true);
      }
    };
    default: return null;
  }
}

function laurel(step: number): (k: Kit) => void {
  return (k) => {
    const m = metal(step);
    k.cyl(0.14, 0.17, 0.05, 14, [0, 0.025, 0], C.dark);
    for (const side of [-1, 1]) {
      for (let i = 0; i < 9; i++) {
        const a = -PI / 2 + 0.25 + (i / 8) * (PI - 0.55), x = side * Math.cos(a) * 0.3, y = 0.46 + Math.sin(a) * 0.36;
        k.ball(0.06, [x, y, 0], m, true, [0.45, 1, 0.3], 6, [0, 0, side * (a + 0.5)]);
      }
    }
    k.box(0.16, 0.06, 0.03, [0, 0.12, 0.02], C.red).box(0.04, 0.12, 0.025, [-0.05, 0.08, 0.02], C.red, false, [0, 0, 0.3]).box(0.04, 0.12, 0.025, [0.05, 0.08, 0.02], C.red, false, [0, 0, -0.3]);
  };
}

function cabinet(step: number): (k: Kit) => void {
  return (k) => {
    const m = metal(step), shelves = step, h = 0.26 * shelves + 0.06;
    const car = (x: number, y: number, col: number) => k.box(0.12, 0.05, 0.07, [x, y + 0.045, 0], col).box(0.07, 0.035, 0.065, [x - 0.01, y + 0.085, 0], C.glass)
      .ball(0.02, [x - 0.04, y + 0.02, 0.035], C.black, false, [1, 1, 1], 6).ball(0.02, [x + 0.04, y + 0.02, 0.035], C.black, false, [1, 1, 1], 6);
    if (step === 3) k.spin('y', 0.5, [0, 0, 0]);
    k.box(0.6, 0.05, 0.34, [0, 0.025, 0], m, true).box(0.6, 0.04, 0.34, [0, h + 0.02, 0], m, true).box(0.58, h, 0.02, [0, h / 2, -0.16], C.wood);
    for (const [x, z] of [[-0.28, -0.15], [0.28, -0.15], [-0.28, 0.15], [0.28, 0.15]] as [number, number][]) k.box(0.03, h, 0.03, [x, h / 2, z], m, true);
    const cols = [C.red, C.blue, C.yellow, C.green];
    for (let s = 0; s < shelves; s++) {
      const y = 0.05 + s * 0.26;
      if (s) k.box(0.56, 0.02, 0.3, [0, y, 0], C.wood);
      car(-0.13, y + 0.01, cols[s % 4]); car(0.13, y + 0.01, cols[(s + 2) % 4]);
    }
    if (step === 3) k.ball(0.06, [0, h + 0.1, 0], m, true).still();
  };
}

// ---- the crowns: the cargo's own ring model (or the culture's good) turning inside a crown band of its metal ----
const CROWN_METAL = [0xffd248, 0xc9ced6, 0xcd8a46];
const CULTURE_VIOLET = 0xbe4af2;
const shade = (c: number, f: number): number => (Math.round(((c >> 16) & 255) * f) << 16) | (Math.round(((c >> 8) & 255) * f) << 8) | Math.round((c & 255) * f);
function crown(model: THREE.BufferGeometry | null, paint: number, place: number): (k: Kit) => void {
  return (k) => {
    const m = CROWN_METAL[place], R = 0.3;
    k.cyl(R - 0.02, R, 0.05, 20, [0, 0.025, 0], m, true).torus(R, 0.03, [0, 0.07, 0], m, true, [PI / 2, 0, 0], PI * 2, 20)
      .add(new THREE.CylinderGeometry(R * 0.97, R, 0.13, 20, 1, true), m, true, [0, 0.135, 0]);
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * PI * 2, x = Math.sin(a) * R * 0.97, z = Math.cos(a) * R * 0.97;
      k.cyl(0, 0.05, 0.15, 6, [x, 0.285, z], m, true).ball(0.03, [x, 0.37, z], i % 2 ? paint : 0xf4f2ec, true, [1, 1, 1], 6);
    }
    if (!model) return;
    // the cargo stands on a pedestal above the band, every one brought to about the same size whatever its ring model's,
    // and turns slowly in its ring colours as the cargo look paints them
    k.cyl(0.07, 0.1, 0.2, 10, [0, 0.15, 0], m, true).cyl(0.14, 0.12, 0.03, 14, [0, 0.265, 0], m, true);
    model.computeBoundingBox();
    const bb = model.boundingBox!, big = Math.max(bb.max.y - bb.min.y, 2 * Math.max(-bb.min.x, bb.max.x, -bb.min.z, bb.max.z), 0.05);
    const sc = Math.min(2.4, 0.52 / big);
    const cols = [paint, shade(paint, 0.62), 0xf4f2ec, 0xf1c7a0];
    const pos = model.getAttribute('position'), nor = model.getAttribute('normal');
    const groups = model.groups.length ? model.groups : [{ start: 0, count: pos.count, materialIndex: 0 }];
    k.spin('y', 0.7, [0, 0.28 - bb.min.y * sc, 0]);
    for (const g of groups) {
      const part = new THREE.BufferGeometry();
      part.setAttribute('position', new THREE.BufferAttribute((pos.array as Float32Array).slice(g.start * 3, (g.start + g.count) * 3), 3));
      part.setAttribute('normal', new THREE.BufferAttribute((nor.array as Float32Array).slice(g.start * 3, (g.start + g.count) * 3), 3));
      k.add(part, cols[g.materialIndex ?? 0] ?? paint, false, [0, 0, 0], [0, 0, 0], [sc, sc, sc]);
    }
    k.still();
  };
}
/**
 * A vehicle's crown (the user, 5 Nov 2026: the vehicle boards): the band of its metal with the model's own body turning
 * in it, as its mascot shows it; an earnings crown's studs are green. A train has no body to shrink: the band alone.
 */
function vehicleCrown(model: string, place: number, earn: boolean): (k: Kit) => void {
  const band = crown(null, earn ? 0x2fb36a : 0xe2412f, place);
  const def = VEHICLES.find((d) => d.id === model && d.kind !== 'rail');
  return (k) => {
    band(k);
    if (!def) return;
    const m = CROWN_METAL[place];
    k.cyl(0.07, 0.1, 0.2, 10, [0, 0.15, 0], m, true).cyl(0.14, 0.12, 0.03, 14, [0, 0.265, 0], m, true);
    const v = buildVehicleMesh({ ...def, topper: undefined, lantern: undefined, gild: undefined } as VehicleDef);
    k.spin('y', 0.7, [0, 0.28, 0]);
    shrinkInto(k, v.holder, 0.5, 0.5, 0.4, 0);
    k.still();
    disposeVehicleMesh(v);
  };
}
function crownBuilder(id: string): ((k: Kit) => void) | null {
  const m = /^c([gcve]):([A-Za-z0-9]{1,24}):([gsb])$/.exec(id);
  if (!m) return null;
  const place = 'gsb'.indexOf(m[3]);
  if (m[1] === 'v' || m[1] === 'e') return ALL_VEHICLES.some((d) => d.id === m[2]) ? vehicleCrown(m[2], place, m[1] === 'e') : null;
  if (m[1] === 'g') {
    const t = cargoById(m[2]);
    return t ? crown(cargoModel(t.id), t.color, place) : null;
  }
  const good = (m[2] === 'visitor' ? VISITOR_GOODS : (GOODS as Record<string, [string, string][]>)[m[2]])?.[0];
  return good ? crown(cargoModel(goodModelId(good[0])), CULTURE_VIOLET, place) : null;
}

