function cultureBuilder(style: string, patron: boolean): ((k: Kit) => void) | null {
  const b = CULTURE_BUILD[style];
  return b ? (k) => { k.gild = patron; b(k); k.gild = false; } : null;
}

// ---- the mascots (phase 3): the model's own body, as built, shrunk onto a chrome plinth ----
function mascotBuilder(model: string): ((k: Kit) => void) | null {
  const def = VEHICLES.find((d) => d.id === model && d.kind !== 'rail');
  if (!def) return null;
  return (k) => {
    k.cyl(0.42, 0.44, 0.05, 18, [0, 0.025, 0], 0xd9dde2, true);
    const m = buildVehicleMesh({ ...def, topper: undefined, lantern: undefined, gild: undefined } as VehicleDef);
    shrinkInto(k, m.holder, 0.86, 0.84, 0.75, 0.05);
    disposeVehicleMesh(m);
  };
}

/**
 * Anything already built (a vehicle's body, a building drawn alone), shrunk into the kit: every lit mesh's triangles
 * in its own colours (a material's, times its vertices' where it has them), the light and the see-through left out,
 * fitted to `len` along z, `wid` across and `tall` up, standing at `y0` in the middle.
 */
function shrinkInto(k: Kit, root: THREE.Object3D, len: number, wid: number, tall: number, y0: number): void {
  {
    const m = { holder: root };
    m.holder.updateMatrixWorld(true);
    const parts: THREE.BufferGeometry[] = [];
    const col = new THREE.Color();
    m.holder.traverse((o) => {
      const mesh = o as THREE.Mesh;
      if (!mesh.isMesh || !mesh.visible || Array.isArray(mesh.material)) return;
      const mat = mesh.material as THREE.MeshStandardMaterial;
      // light, not things: the beams, the glows, anything see-through
      // (the town mesh is marked see-through only to fade in: fully opaque, it is drawn)
      if (!mat || (mat.transparent && mat.opacity < 0.95) || (mat as unknown as THREE.MeshBasicMaterial).blending === THREE.AdditiveBlending || !(mat as THREE.MeshStandardMaterial).color) return;
      let g = mesh.geometry.index ? mesh.geometry.toNonIndexed() : mesh.geometry.clone();
      g.applyMatrix4(mesh.matrixWorld);
      const pos = g.getAttribute('position');
      if (!pos) return;
      if (!g.getAttribute('normal')) g.computeVertexNormals();
      const vc = g.getAttribute('color');
      const out = new Float32Array(pos.count * 3);
      const base = mat.emissive && mat.emissive.getHex() && mat.emissiveIntensity > 0.5 ? mat.emissive : mat.color;
      for (let i = 0; i < pos.count; i++) {
        col.copy(base);
        if (vc && mat.vertexColors) col.multiply(new THREE.Color(vc.getX(i), vc.getY(i), vc.getZ(i)));
        out.set([col.r, col.g, col.b], i * 3);
      }
      for (const a of Object.keys(g.attributes)) if (a !== 'position' && a !== 'normal') g.deleteAttribute(a);
      g.setAttribute('color', new THREE.BufferAttribute(out, 3));
      parts.push(g);
    });
    if (!parts.length) return;
    const box = new THREE.Box3();
    for (const g of parts) { g.computeBoundingBox(); box.union(g.boundingBox!); }
    const size = box.getSize(new THREE.Vector3());
    const sc = Math.min(len / Math.max(size.z, 1e-3), wid / Math.max(size.x, 1e-3), tall / Math.max(size.y, 1e-3));
    const mx = new THREE.Matrix4().makeScale(sc, sc, sc).premultiply(new THREE.Matrix4().makeTranslation(0, y0, 0))
      .multiply(new THREE.Matrix4().makeTranslation(-(box.min.x + box.max.x) / 2, -box.min.y, -(box.min.z + box.max.z) / 2));
    for (const g of parts) { g.applyMatrix4(mx); k.addColoured(g, false); }
  }
}

// ---- phase 4: curios, the wild things themselves, drawn alone by the town mesher and shrunk onto a slab of ground ----
function curioBuilder(kind: string): ((k: Kit) => void) | null {
  if (!(WILD_KINDS as readonly string[]).includes(kind)) return null;
  return (k) => {
    k.cyl(0.42, 0.44, 0.05, 16, [0, 0.025, 0], 0x7f9a52);
    const [w, d] = WILD_SIZE[kind as keyof typeof WILD_SIZE];
    const g = loneBuilding({ kind: kind as BuildingKind, wx: w, wz: d, facing: 0, floors: 1, seed: 7, style: 'classic' });
    shrinkInto(k, g, 0.82, 0.82, 0.8, 0.05);
    g.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh) m.geometry.dispose(); });
  };
}

