function builderFor(id: string): ((k: Kit) => void) | null {
  if (BUILD[id]) return BUILD[id];
  const cu = /^cul:([a-z]+)(:p)?$/.exec(id);
  if (cu) return cultureBuilder(cu[1], !!cu[2]);
  const ma = /^mas:([A-Za-z0-9]+)$/.exec(id);
  if (ma) return mascotBuilder(ma[1]);
  if (PHASE4[id]) return PHASE4[id];
  const ev = /^ev:([A-Za-z0-9]+)$/.exec(id);
  if (ev) return souvenirBuilder(ev[1]);
  const wd = /^wd:([A-Za-z0-9]+)$/.exec(id);
  if (wd) return curioBuilder(wd[1]);
  if (id.startsWith('rp:')) return pennantBuilder(id);
  if (id.startsWith('cf:')) return flagBuilder(id);
  if (id.startsWith('rk:')) return rangeTrophyBuilder(id);
  if (id.startsWith('tt:')) return trackBuilder(id);
  if (/^c[gcve]:/.test(id)) return crownBuilder(id);
  let m = /^ms:([a-z]+)(\d)$/.exec(id);
  if (m) return ladder(m[1], Number(m[2]));
  m = /^deeds:(\d)$/.exec(id);
  if (m) return laurel(Number(m[1]));
  m = /^col:(\d)$/.exec(id);
  if (m) return cabinet(Number(m[1]));
  return null;
}

const cache = new Map<string, Piece[] | null>();
/** A topper's merged pieces, built once; null for one with no model here (the Wonder Ball, or an id this game doesn't know). */
export function topperPieces(id: string): Piece[] | null {
  if (cache.has(id)) return cache.get(id)!;
  const b = builderFor(id);
  let out: Piece[] | null = null;
  if (b) { const k = new Kit(); b(k); out = k.pieces(); }
  cache.set(id, out);
  return out;
}

/** Whether a topper has a model of its own (render/treats.ts draws the rest, the Wonder Ball, itself). */
export const hasTopperModel = (id: string): boolean => !!topperPieces(id);
/** Whether any part of it turns (a far body would freeze it: render/vehicleMeshes.ts). */
export const topperTurns = (id: string): boolean => id === 'wonder' || !!topperPieces(id)?.some((p) => p.spin);

/**
 * Put a topper on: standing on (`up` 1) or hanging from (`up` −1) the point (x, y, z) of `body`, `size` tall. Returns
 * every mesh it added, to be kept out of the body's merge (their colours are their vertices', which the merge
 * would paint over), each a shared piece the vehicle's disposal leaves alone.
 */
export function addTopper(body: THREE.Object3D, id: string, x: number, y: number, z: number, size: number, up: 1 | -1 = 1, ground: THREE.Object3D | null = null, spread = 1): THREE.Object3D[] {
  const pieces = topperPieces(id);
  if (!pieces) return [];
  const m = topperMats();
  const holder = new THREE.Group();
  holder.position.set(x, y, z);
  holder.scale.setScalar(size);
  if (up < 0) holder.rotation.x = Math.PI;
  const out: THREE.Object3D[] = [];
  for (const p of pieces) {
    const mat = p.shiny ? m.shiny : m.matte;
    let mesh: THREE.Mesh;
    if (p.spin) {
      const t = new Turning(p.geo, mat);
      t.axis = p.spin.axis; t.rate = p.spin.rate;
      t.position.set(...p.spin.at);
      mesh = t;
    } else mesh = new THREE.Mesh(p.geo, mat);
    mesh.userData.shared = true;
    mesh.castShadow = true;
    holder.add(mesh);
    out.push(mesh);
  }
  body.add(holder);
  // a gold crown throws a faint gold ring of light on the ground after dark (the Wonder Ball's spots' material, lit by night)
  if (ground && /^c[gc]:.*:g$/.test(id)) {
    const ring = sharedPiece(new THREE.Mesh(goldRing(), treatFx().ringMat));
    ring.scale.set(spread, 1, spread);
    ring.position.set(x, 0.03, z);
    ring.renderOrder = 4;
    ground.add(ring);
  }
  return out;
}

let ringGeo: THREE.BufferGeometry | null = null;
/** The gold crown's ring of light: a soft band, brightest along its middle, gold. */
function goldRing(): THREE.BufferGeometry {
  if (ringGeo) return ringGeo;
  const g = new THREE.RingGeometry(0.62, 1, 40, 1).rotateX(-Math.PI / 2).toNonIndexed();
  const pos = g.getAttribute('position'), col = new Float32Array(pos.count * 4);
  for (let i = 0; i < pos.count; i++) {
    const r = Math.hypot(pos.getX(i), pos.getZ(i)), a = r > 0.7 && r < 0.92 ? 0.5 : 0.12;
    col.set([1, 0.8, 0.3, a], i * 4);
  }
  g.setAttribute('color', new THREE.BufferAttribute(col, 4));
  ringGeo = g;
  return g;
}

/** For the gate (npm run toppers): every vertex of a topper as built, with its spin parts at their pivots, and its triangles. */
export function topperExtent(id: string): { box: THREE.Box3; tris: number } | null {
  const pieces = topperPieces(id);
  if (!pieces) return null;
  const box = new THREE.Box3();
  let tris = 0;
  const v = new THREE.Vector3();
  for (const p of pieces) {
    const pos = p.geo.getAttribute('position');
    tris += pos.count / 3;
    const off = p.spin?.at ?? [0, 0, 0];
    // a turning part sweeps a circle round its axis: its reach is measured off the axis both ways
    for (let i = 0; i < pos.count; i++) {
      v.fromBufferAttribute(pos, i);
      if (p.spin) {
        const ax = p.spin.axis;
        const r = ax === 'y' ? Math.hypot(v.x, v.z) : ax === 'x' ? Math.hypot(v.y, v.z) : Math.hypot(v.x, v.y);
        const along = v[ax];
        const pts: V3[] = ax === 'y' ? [[r, along, 0], [-r, along, 0], [0, along, r], [0, along, -r]]
          : ax === 'x' ? [[along, r, 0], [along, -r, 0], [along, 0, r], [along, 0, -r]] : [[r, 0, along], [-r, 0, along], [0, r, along], [0, -r, along]];
        for (const q of pts) box.expandByPoint(new THREE.Vector3(q[0] + off[0], q[1] + off[1], q[2] + off[2]));
      } else box.expandByPoint(v);
    }
  }
  return { box, tris };
}
