/**
 * Film mode, for the trailer shoot (scripts/film/shoot.mjs; the user, 6 Nov 2026: fifty 10-second shots for
 * Instagram reels, the Steam trailer and YouTube, in 16:9 and 9:16, smooth, with no UI of any kind and CPU
 * vehicles going about their own business).
 *
 * It runs on the title's world (the online seed, every county's own traffic alive round the camera), in place
 * of the reel's director, and is stepped one frame at a time by the shoot over the DevTools protocol:
 *
 * - a virtual clock: performance.now() and Date.now() move exactly one frame (1/60 s) per frame, so everything
 *   animated from the wall clock (water, flags, lamps, the season shader) moves in step with the simulation
 *   however long a frame takes to draw; within a frame they creep a hair a call, so time budgets still end;
 * - no throttles: every CPU vehicle ticked every frame, no far bodies, every chunk in view built before the
 *   frame is drawn, the quality held at High;
 * - each shot is set up (cell, light, season, subject found in the real world), run on for a while unrecorded so
 *   the traffic is flowing, checked for a camera path that never dips under the ground, then filmed;
 * - every frame reports the vehicles on screen (cars, boats, planes, trains), so the shoot can fail a clip where
 *   anything jumps, stalls and catches up, or pops into or out of the frame.
 */
import * as THREE from 'three';
import { Flag, N, idx, inB, steepness, waterDepth, type World } from '../world/tiles';
import { propsOn } from '../render/props';
import type { ReelHost } from './director';

export type FilmMove = 'orbit' | 'push' | 'pull' | 'pan' | 'spin' | 'crane' | 'fly' | 'track';
/** horizon: the game's lowest P camera, 6° down. */
export type FilmAngle = 'low' | 'mid' | 'high' | 'top' | 'horizon';

/** What a shot films: a building kind, a landform or a work in its cell, a town, or a CPU vehicle near one. */
export type FilmSubject =
  | { building: string; town?: string }
  | { landform: string }
  | { work: string; name?: string }
  | { town: string }
  | { hero: 'land' | 'water' | 'air' | 'rail' | 'jet'; near?: string }
  | { at: [number, number]; r: number };

export interface FilmShot {
  id: string;
  cell: [number, number];
  subject: FilmSubject;
  move: FilmMove;
  angle: FilmAngle;
  /** 0 spring … 3 winter; the hour. */
  season: number; hour: number;
  /** Seconds (10). */
  len?: number;
  /** Optional overrides: framing radius multiplier, a fly's heading (degrees), the starting yaw (degrees). */
  zoom?: number; heading?: number; yaw?: number;
  /** False where the subject can have no traffic (an atoll, a salt pan): the vehicle rule doesn't apply. */
  vehicles?: boolean;
  /** Which of the directions ranked by traffic in view to film from (0 the best; the shoot tries the next on a fail). */
  pick?: number;
  /**
   * A track shot of a place: follow a CPU vehicle of this kind already out nearest the subject, the place behind it
   * (the user, 6 Nov 2026: twenty tracking shots). A hero subject is the same with no place.
   */
  follow?: HeroKind;
  /** Models tracked in other shots, never tracked again (filled in by the shoot from the picks so far). */
  avoid?: string[];
  /**
   * The camera mode's own tools (C, game/photoMode.ts; the user, 7 Nov 2026): orbit round the tracked subject at
   * its pace (0.1 rad/s), 1 one way, -1 the other; a slow zoom in (the distance halved) or out (doubled).
   */
  orbit?: 1 | -1; dolly?: 'in' | 'out';
  /** Track a train coming towards the place (one nearer now than a second before). */
  approach?: boolean;
  /** A V of n vehicles of one model driven across open ground near the place, tracked (the user, 7 Nov 2026). */
  formation?: { model: string; n: number };
}

export type HeroKind = 'land' | 'water' | 'air' | 'rail' | 'jet';
/** The kind of vehicle a shot tracks, if it tracks one. */
const heroKind = (shot: FilmShot): HeroKind | null => ('hero' in shot.subject ? shot.subject.hero : shot.formation ? 'land' : shot.follow ?? null);
/** The camera mode's orbit pace (game/photoMode.ts SPIN), radians a second. */
const SPIN = 0.1;
/** How big a tracked vehicle is framed, by kind. */
const HERO_R: Record<HeroKind, number> = { air: 3.5, jet: 9, rail: 7, water: 3, land: 2 };

export interface FilmHost {
  reel: ReelHost;
  /** One frame of the title's world without the director: sky, traffic, trains, chunks, weather. */
  sim(dt: number): void;
  /** One whole frame as the game runs it (step()): sim + render. */
  step(now: number): void;
  /** Build every chunk round a point, however long it takes; how many are still missing. */
  warmAll(gx: number, gz: number): number;
  groundAt(x: number, z: number): number;
  camera: THREE.PerspectiveCamera;
  /** An airliner of the ambient air traffic (game/skyTraffic.ts) nearest a point, to follow. */
  /**
   * Vehicles of a kind round a point that could be tracked (the user, 6 Nov 2026: tracked vehicles stuck, not
   * driving smoothly, stopped at a station): each with its model, distance, speed and seconds of travel left before
   * it must next stop (its route's end, a calling point, a train ahead), and a handle on where it is.
   */
  candidates?(kind: HeroKind, x: number, z: number, avoid?: string[]): { model: string; d: number; speed: number; ahead: number; get: () => { x: number; y: number; z: number; heading: number } | null }[];
  /** Planes' contrails on or off (off while filming, but for the shot tracking a jet: its own trail). */
  contrails?(on: boolean): void;
  /**
   * A V of n vehicles of a model put down with its tip at (x, z) (global tiles) facing heading, driven on along it
   * by their escorts (the formation's own steering, traffic.ts station): update(dt) moves the V on; get() is its
   * middle; r its radius in tiles.
   */
  formationSpeed?(model: string): number;
  formation?(model: string, n: number, x: number, z: number, heading: number, w: World): { update(dt: number): void; get(): { x: number; y: number; z: number; heading: number } | null; drop(): void; r: number; speed: number } | null;
  flight(x: number, z: number, avoid?: string[]): (() => { x: number; y: number; z: number; heading: number } | null) | null;
  /** Everything that moves on its own, in global tiles, for the motion check. */
  movers(): { id: string; kind: string; x: number; y: number; z: number; wedged?: boolean }[];
  /** Hold the game's own frame loop (the shoot steps it), and turn the throttles and the UI off. */
  setFilming(on: boolean): void;
  /** The tilt-shift band: centre and half-height. */
  setBand(focus: number, band: number): void;
}

const DT = 1 / 60;
const deg = (d: number) => (d * Math.PI) / 180;
const ease = (t: number) => t * t * (3 - 2 * t);
/** Pitch by angle class. */
const PITCH: Record<FilmAngle, number> = { low: deg(13), mid: deg(28), high: deg(46), top: deg(72), horizon: deg(6) };
/** tan of the camera's half vertical field of view (18°). */
const VTAN = Math.tan(deg(9));
/** A mover's length in tiles, by kind (a car, a boat, a helicopter or small plane, a train's middle car run; an airliner). */
const LENGTH: Record<string, number> = { land: 0.8, water: 1.4, air: 1.4, rail: 5, jet: 4 };
/** Share of the frame's height a vehicle must be long to count as readable: 5%, ~54 px in the 1080p clip. */
const READABLE = 0.05;
/** Is a mover at distance d from the camera big enough on screen to read? */
const bigEnough = (kind: string, id: string, d: number): boolean => (LENGTH[id.startsWith('f') ? 'jet' : kind] ?? 1) / (Math.max(0.1, d) * 2 * VTAN) >= READABLE;

interface Plan {
  shot: FilmShot;
  /** The subject in global tiles, its ground height and radius. */
  x: number; y: number; z: number; r: number;
  /** yaw, pitch and distance at the start and end; a target glide (dx, dz) from start to end. */
  yaw0: number; yaw1: number; pitch0: number; pitch1: number; dist0: number; dist1: number;
  gx: number; gz: number;
  hero: (() => { x: number; y: number; z: number; heading: number } | null) | null;
  band: number;
}

export class Film {
  active = false;
  /** The model the shot tracks (train:<name> for a train), for the shoot's one-shot-per-model rule. */
  tracked: string | null = null;
  private plan: Plan | null = null;
  private t = 0;
  private clock: { real: () => number; realDate: () => number; v: number; frame: number; epoch: number } | null = null;
  private followYaw = 0;
  /** The tracked vehicle: where the camera holds it (eased, so a twitch in its position never shakes the shot), its last place, its cruising speed, frames spent slow. */
  private heroAt = new THREE.Vector3();
  private heroLast: { x: number; z: number } | null = null;
  private heroSpeeds: number[] = [];
  private heroSlow = 0;
  private heroEasedAt = -1;
  /** An orbit's yaw at the start of the shot; the formation on the move, if the shot has one; trains' distances a second before the pick. */
  private orbitYaw = 0;
  private squad: ReturnType<NonNullable<FilmHost['formation']>> | null = null;
  private approachD = new Map<string, number>();
  private readonly target = new THREE.Vector3();
  /** The last frame's mover positions, for the motion check. */
  private last = new Map<string, { x: number; y: number; z: number; kind: string; d: number }>();
  readonly log: string[] = [];
  private aimNote = '';
  private readonly probeCam = new THREE.PerspectiveCamera();

  constructor(private host: FilmHost) {}

  // ---- the clock ---------------------------------------------------------------------------------

  /** Take over performance.now() and Date.now(): from here they move a frame a frame. */
  private installClock(): void {
    if (this.clock) return;
    const real = performance.now.bind(performance), realDate = Date.now.bind(Date);
    const c = { real, realDate, v: real(), frame: real(), epoch: realDate() - real() };
    this.clock = c;
    // a hair a call within a frame (so "until 3 ms are spent" still ends), never past half the frame
    performance.now = () => (c.v = Math.min(c.v + 0.0005, c.frame + 8));
    Date.now = () => Math.floor(c.epoch + performance.now());
  }
  private tick(): number {
    const c = this.clock!;
    c.frame += DT * 1000;
    c.v = c.frame;
    return c.frame;
  }

  // ---- a shot ------------------------------------------------------------------------------------

  /**
   * Set a shot up: go to its cell, wait for it, find the subject, set the light, run the world on unrecorded for
   * `preroll` seconds, and work out a camera path that stays above the ground. Resolves to a line about it, or
   * throws why it can't be filmed.
   */
  async setup(shot: FilmShot, preroll = 20): Promise<string> {
    const h = this.host, reel = h.reel;
    this.installClock();
    this.active = true;
    h.setFilming(true);
    const [cx, cz] = shot.cell;
    // the cell and its neighbours in memory, then made the centre (its traffic comes alive)
    this.squad?.drop(); this.squad = null;
    reel.release();
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) reel.keep(cx + dx, cz + dz);
    // three minutes: a county not built before (no cached world) takes a while
    for (let k = 0; k < 1800 && !reel.ready(cx, cz); k++) await new Promise((r) => setTimeout(r, 100));
    if (!reel.ready(cx, cz)) throw new Error(`cell ${cx},${cz} never came into memory`);
    reel.moveTo(cx, cz);
    const w = reel.worldAt(cx, cz);
    if (!w) throw new Error(`no world at ${cx},${cz}`);
    const found = this.find(w, shot);
    if (!found) throw new Error(`no ${JSON.stringify(shot.subject)} in ${w.name} (${cx},${cz})`);
    reel.setLight(shot.hour, shot.season);
    const kind = heroKind(shot);
    const placeR = found.r;
    h.contrails?.(kind === 'jet');
    // a place tracked past: the vehicle framed, not the place (it goes by behind)
    if (kind && !('hero' in shot.subject)) found.r = HERO_R[kind] * (shot.zoom ?? 1);
    // a formation: open ground near the place, long enough for the run-up and the shot
    let lane: { x: number; z: number; h: number } | null = null;
    const place = { x: found.x, z: found.z };
    if (shot.formation) {
      // long enough for the run-up, the whole clip and two seconds more at the V's own speed, plus its rows
      const v = h.formationSpeed?.(shot.formation.model) ?? 0;
      lane = this.lane(w, found.x, found.z, placeR, Math.max(26 + shot.formation.n * 2.4, v * (4 + (shot.len ?? 10) + 2) + shot.formation.n * 2), 3 + shot.formation.n * 1.5);
      if (!lane) throw new Error(`no open ground near ${found.what} for a V of ${shot.formation.n}`);
    }
    const plan = this.path(shot, found.x, found.y, found.z, found.r);
    this.plan = plan;
    this.tracked = null;
    // run the world on: traffic out on the roads, trains on the lines, chunks built (a frame at a time, drawn,
    // so every lazily-compiled shader is made before the clip, not in it)
    this.t = 0;
    this.pose(0);
    h.warmAll(plan.x, plan.z);
    const frames = Math.round(preroll / DT);
    for (let i = 0; i < frames; i++) {
      // the world only (no drawing) until the last second and a half, which is drawn: any shader still to be made
      // is made then, not in the clip
      if (i < frames - 90) { this.tick(); h.sim(DT); } else h.step(this.tick());
      // keep the hour where the shot wants it while the run-up passes
      if (i % 60 === 0) reel.setLight(shot.hour, shot.season);
      // the V put down four seconds before the shot, so it has formed up and is moving when the clip starts
      if (lane && shot.formation && i === frames - 240) {
        this.squad = h.formation?.(shot.formation.model, shot.formation.n, lane.x, lane.z, lane.h, w) ?? null;
        if (!this.squad) throw new Error(`couldn't put down a V of ${shot.formation.n} ${shot.formation.model}`);
      }
      this.squad?.update(DT);
      // where every train is a second before the pick: an approaching one is nearer by then
      if (shot.approach && i === frames - 60 && h.candidates) {
        this.approachD.clear();
        for (const c of h.candidates('rail', plan.x, plan.z, shot.avoid)) this.approachD.set(c.model, c.d);
      }
    }
    reel.setLight(shot.hour, shot.season);
    if (kind) {
      plan.hero = this.squad ? Object.assign(() => this.squad?.get() ?? null, { model: `formation:${shot.formation!.model}x${shot.formation!.n}` }) : this.heroFor(w, shot, kind);
      // nothing fit to follow just now (no train on the line with the clip ahead of it): run the world on five
      // seconds at a time, up to a minute, and look again, the last second and a half drawn as in the run-up
      for (let tries = 0; !plan.hero && tries < 12; tries++) {
        const more = 300;
        for (let i = 0; i < more; i++) {
          if (i < more - 90) { this.tick(); h.sim(DT); } else h.step(this.tick());
          if (i % 60 === 0) reel.setLight(shot.hour, shot.season);
          if (shot.approach && i === more - 60 && h.candidates) {
            this.approachD.clear();
            for (const c of h.candidates('rail', plan.x, plan.z, shot.avoid)) this.approachD.set(c.model, c.d);
          }
        }
        reel.setLight(shot.hour, shot.season);
        plan.hero = this.heroFor(w, shot, kind);
      }
      if (!plan.hero) throw new Error(`no ${kind} vehicle to follow near ${w.name}${shot.avoid?.length ? ` (not one of the ${shot.avoid.length} tracked already)` : ''}`);
      this.tracked = (plan.hero as { model?: string }).model ?? null;
      const h0 = plan.hero()!;
      this.heroAt.set(h0.x, h0.y, h0.z);
      this.heroLast = null; this.heroSpeeds = []; this.heroSlow = 0; this.heroEasedAt = -1;
      const p = plan.hero()!;
      this.followYaw = p.heading + Math.PI + deg(shot.yaw ?? 0);
      if (this.squad) { const hero = plan.hero; Object.assign(plan, this.path(shot, plan.x, plan.y, plan.z, this.squad.r), { hero }); }
      // an orbit: the place behind the subject halfway through (the camera on the far side of it from the place)
      if (shot.orbit) {
        const len = shot.len ?? 10;
        const v = this.squad ? this.squad.speed : 0;
        const mx = p.x + Math.sin(p.heading) * v * len / 2, mz = p.z + Math.cos(p.heading) * v * len / 2;
        this.orbitYaw = Math.atan2(mx - place.x, mz - place.z) - shot.orbit * SPIN * len / 2;
        this.followYaw = this.orbitYaw;
      }
    }
    // aim where the traffic is: the directions round the subject ranked by how many CPU vehicles sit readable in
    // the middle of the frame through the move, and the shot filmed from the one asked for (never staged: only aimed)
    if (!kind && shot.yaw === undefined) {
      const ranked: { yaw: number; score: number }[] = [];
      for (let i = 0; i < 16; i++) {
        const yaw = i * 22.5;
        const q = this.path({ ...shot, yaw, heading: shot.heading ?? yaw + 90 }, found.x, found.y, found.z, found.r);
        let score = 0;
        for (const k of [0.1, 0.35, 0.65, 0.9]) score += this.readable(q, k).v * 2 + this.readable(q, k).l;
        ranked.push({ yaw, score });
      }
      ranked.sort((a, b) => b.score - a.score);
      const pickYaw = ranked[Math.min(ranked.length - 1, shot.pick ?? 0)];
      Object.assign(plan, this.path({ ...shot, yaw: pickYaw.yaw, heading: shot.heading ?? pickYaw.yaw + 90 }, found.x, found.y, found.z, found.r));
      this.aimNote = ` · aimed ${pickYaw.yaw}° (traffic score ${pickYaw.score}, best ${ranked[0].score})`;
    } else this.aimNote = '';
    this.clearance(plan, shot.angle === 'horizon' ? 1.5 : 4);
    this.t = 0;
    this.last.clear();
    this.pose(0);
    h.warmAll(this.target.x, this.target.z);
    return `${shot.id}${shot.pick ? ` (take ${shot.pick + 1})` : ''}: ${w.name} (${cx},${cz}) · ${found.what} · r ${found.r.toFixed(0)} · ${shot.move}/${shot.angle} · pitch ${(plan.pitch0 * 180 / Math.PI).toFixed(0)}→${(plan.pitch1 * 180 / Math.PI).toFixed(0)} dist ${plan.dist0.toFixed(0)}→${plan.dist1.toFixed(0)}${this.aimNote}${this.tracked ? ` · tracking ${this.tracked}` : ''}`;
  }

  /**
   * One filmed frame: the clock a frame on, the camera posed, every chunk round what it sees built, the frame
   * stepped and drawn. Returns the motion check's findings for this frame (empty when all is well).
   */
  frame(): { t: number; bad: string[]; seen: number; veh: number; vehV: number } {
    const p = this.plan;
    if (!p) throw new Error('no shot set up');
    const len = p.shot.len ?? 10;
    this.t = Math.min(len, this.t + DT);
    // pose before the step (the step poses again from film.update with the same t), so the warm sees this frame's view
    this.squad?.update(DT);
    this.pose(this.t / len);
    this.host.warmAll(this.target.x, this.target.z);
    this.host.step(this.tick());
    const r = this.readable(p, this.t / len, this.host.camera);
    const c = this.check();
    if (p.hero) c.bad.push(...this.heroCheck(p));
    return { ...c, veh: r.l, vehV: r.v };
  }

  /**
   * The tracked vehicle keeps going the whole clip: lost, or below 45% of its cruising speed (its first half second)
   * for more than a third of a second (a stop at lights, a station, a jam, a wedge), fails the take, and the retake
   * follows the next vehicle on the list.
   */
  private heroCheck(p: Plan): string[] {
    const h = p.hero!();
    if (!h) return ['tracked vehicle lost'];
    const was = this.heroLast;
    this.heroLast = { x: h.x, z: h.z };
    if (!was) return [];
    const v = Math.hypot(h.x - was.x, h.z - was.z) / DT;
    if (this.heroSpeeds.length < 30) { this.heroSpeeds.push(v); return []; }
    const cruise = this.heroSpeeds.reduce((a, b) => a + b, 0) / this.heroSpeeds.length;
    if (cruise < 0.5) return [`tracked vehicle barely moving (${cruise.toFixed(2)} tiles/s)`];
    this.heroSlow = v < cruise * 0.45 ? this.heroSlow + 1 : 0;
    return this.heroSlow > 20 ? [`tracked vehicle slowed to ${v.toFixed(2)} of ${cruise.toFixed(2)} tiles/s`] : [];
  }

  /** Called by the game's title frame in place of the director: hold the camera on the shot's pose. */
  update(): void {
    const p = this.plan;
    if (!p) return;
    this.pose(this.t / (p.shot.len ?? 10));
    this.host.setBand(0.5, p.band);
  }

  end(): void {
    this.active = false;
    this.plan = null;
    this.squad?.drop(); this.squad = null;
    this.host.contrails?.(true);
    this.host.setFilming(false);
  }

  // ---- finding the subject -----------------------------------------------------------------------

  private find(w: World, shot: FilmShot): { x: number; y: number; z: number; r: number; what: string } | null {
    const s = shot.subject;
    const gy = (lx: number, lz: number) => this.host.groundAt(w.ox + lx, w.oz + lz);
    const out = (lx: number, lz: number, r: number, what: string) => ({ x: w.ox + lx, y: gy(lx, lz), z: w.oz + lz, r: r * (shot.zoom ?? 1), what });
    if ('building' in s) {
      const all = [...w.towns.flatMap((t) => t.buildings.map((b) => ({ b, t: t.name }))), ...w.countryside.map((b) => ({ b, t: '' }))];
      const hit = all.find((e) => e.b.kind === s.building && !e.b.gone && (!s.town || e.t === s.town));
      if (!hit) return null;
      const b = hit.b;
      return out(b.x + b.w / 2, b.z + b.d / 2, Math.max(2.5, Math.hypot(b.w, b.d) * 0.55), `${b.kind}${hit.t ? ` in ${hit.t}` : ''}`);
    }
    if ('landform' in s) {
      const l = w.landmarks.find((q) => q.kind === s.landform);
      return l ? out(l.x, l.z, Math.max(6, Math.min(70, l.r)), `${l.kind} ${l.name}`) : null;
    }
    if ('work' in s) {
      const g = w.works.find((q) => q.kind === s.work && (!s.name || q.name === s.name));
      return g ? out(g.x, g.z, g.kind === 'airfield' ? 30 : g.kind === 'wonder' ? 10 : 20, `${g.kind} ${g.name}`) : null;
    }
    if ('town' in s) {
      const t = w.towns.find((q) => q.name === s.town);
      return t ? out(t.x0 + t.size / 2, t.z0 + t.size / 2, t.size / 2, `${t.kind} ${t.name} (${t.style})`) : null;
    }
    if ('hero' in s) {
      const t = s.near ? w.towns.find((q) => q.name === s.near) : w.towns[0];
      const lx = t ? t.x0 + t.size / 2 : w.spawn.x, lz = t ? t.z0 + t.size / 2 : w.spawn.z;
      return out(lx, lz, HERO_R[s.hero], `${s.hero} near ${t?.name ?? w.name}`);
    }
    if ('at' in s) return out(s.at[0], s.at[1], s.r, `spot ${s.at.join(',')}`);
    return null;
  }

  /** The vehicle to track: one already out doing its own thing, nearest the subject (never one sent out for it). */
  private heroFor(w: World, shot: FilmShot, kind: HeroKind): (() => { x: number; y: number; z: number; heading: number } | null) | null {
    const p = this.plan!;
    if (this.host.candidates) {
      // moving at speed with the whole clip and some to spare before it must stop; nearest the subject first, and
      // each retake the next one along
      const need = (shot.len ?? 10) + 3;
      const all = this.host.candidates(kind, p.x, p.z, shot.avoid);
      const list = all.filter((c) => c.ahead >= need && (!shot.approach || (this.approachD.get(c.model) ?? -1) > c.d + 0.3)).sort((a, b) => a.d - b.d);
      if (!list.length) this.log.push(`${shot.id}: no ${kind} with ${need} s ahead of ${all.length} moving: ${all.slice(0, 8).map((c) => `${c.model} ${c.ahead.toFixed(1)} s @${c.d.toFixed(0)}`).join(", ")}`);
      const c = list[Math.min(list.length - 1, shot.pick ?? 0)];
      return c ? Object.assign(c.get, { model: c.model }) : null;
    }
    if (kind === 'jet') return this.host.flight(p.x, p.z, shot.avoid);
    return this.host.reel.hero(kind, w, p.x - w.ox, p.z - w.oz, shot.avoid);
  }

  // ---- the camera path ---------------------------------------------------------------------------

  /** The distance at which a radius r fills `fill` of the half-height: the 9:16 crop then still holds it across. */
  private distFor(r: number, fill: number): number { return Math.max(14, Math.min(420, r / (fill * VTAN))); }

  private path(shot: FilmShot, x: number, y: number, z: number, r: number): Plan {
    const yaw = deg(shot.yaw ?? ((x * 7.13 + z * 3.71) % 360));
    const pitch = PITCH[shot.angle];
    // how much of the half-height the subject's radius fills: a building or a vehicle up close, a town or a landform
    // with room round it (the 9:16 crop is 0.56 of the height across, so a fill near 0.6 still holds the subject)
    const s0 = shot.subject;
    const fill = 'building' in s0 || 'hero' in s0 || shot.follow ? 0.62 : 'town' in s0 ? 0.85 : 0.72;
    const d = this.distFor(r, fill);
    const p: Plan = { shot, x, y, z, r, yaw0: yaw, yaw1: yaw, pitch0: pitch, pitch1: pitch, dist0: d, dist1: d, gx: 0, gz: 0, hero: null, band: 0.16 };
    const head = deg(shot.heading ?? (shot.yaw ?? 0) + 90);
    switch (shot.move) {
      case 'orbit': p.yaw1 = yaw + deg(60); p.dist1 = d * 0.94; break;
      case 'push': p.dist0 = d * 1.7; p.dist1 = d * 0.8; p.yaw1 = yaw + deg(12); break;
      case 'pull': p.dist0 = d * 0.75; p.dist1 = d * 1.9; p.pitch1 = pitch + deg(6); p.yaw1 = yaw - deg(10); break;
      case 'pan': {
        // the target glides across the subject, side to side as the camera sees it
        const g = Math.max(r * 0.8, 5);
        p.gx = Math.cos(yaw) * g * 2; p.gz = -Math.sin(yaw) * g * 2;
        p.x -= p.gx / 2; p.z -= p.gz / 2;
        break;
      }
      case 'spin': p.yaw1 = yaw + deg(80); p.pitch0 = p.pitch1 = Math.max(pitch, deg(60)); break;
      case 'crane': p.pitch0 = Math.max(deg(9), pitch - deg(10)); p.pitch1 = Math.min(deg(75), pitch + deg(30)); p.dist1 = d * 1.15; p.yaw1 = yaw + deg(8); break;
      case 'fly': {
        // a sweep: the camera's aim travels across the area along `heading`, the camera behind it
        const g = Math.max(r * 2.4, 40);
        p.gx = Math.sin(head) * g; p.gz = Math.cos(head) * g;
        p.x -= p.gx / 2; p.z -= p.gz / 2;
        p.yaw0 = p.yaw1 = head + Math.PI;
        p.dist0 = p.dist1 = Math.max(60, d * 0.8);
        break;
      }
      case 'track': p.dist0 = d; p.dist1 = d * 0.92; p.band = 0.12; break;
    }
    // the camera mode's zoom: in, from 1.4 of the framing distance to 0.7 (halved); out, the other way (doubled)
    if (shot.dolly) { p.dist0 = d * (shot.dolly === 'in' ? 1.4 : 0.7); p.dist1 = d * (shot.dolly === 'in' ? 0.7 : 1.4); }
    return p;
  }

  /** Tilt the whole move up until no frame of it puts the camera within 4 tiles of the ground. */
  private clearance(p: Plan, least = 4): void {
    for (let tries = 0; tries < 16; tries++) {
      let worst = Infinity;
      // and, tracking, the ground never between the camera and what it follows (the Wasabi V hid behind a ridge
      // from the lowest camera): its line of sight sampled, the formation where it will be by then
      let seen = Infinity;
      const h0 = p.hero?.() ?? null, len = p.shot.len ?? 10, v = this.squad?.speed ?? 0;
      for (let i = 0; i <= 60; i++) {
        const k = i / 60, pos = this.camAt(p, k);
        const mx = h0 ? Math.sin(h0.heading) * v * k * len : 0, mz = h0 ? Math.cos(h0.heading) * v * k * len : 0;
        pos.x += mx; pos.z += mz;
        worst = Math.min(worst, pos.y - this.host.groundAt(pos.x, pos.z));
        if (h0) {
          const tx = h0.x + mx, ty = h0.y + 0.3, tz = h0.z + mz;
          for (let j = 1; j < 24; j++) {
            const u = j / 24, x = pos.x + (tx - pos.x) * u, y = pos.y + (ty - pos.y) * u, z = pos.z + (tz - pos.z) * u;
            seen = Math.min(seen, y - this.host.groundAt(x, z));
          }
        }
      }
      if (worst >= least && seen >= 0.2) return;
      p.pitch0 += deg(3); p.pitch1 += deg(3);
      this.log.push(`${p.shot.id}: camera ${worst.toFixed(1)} above the ground, sight line ${seen.toFixed(1)}, tilting up 3°`);
    }
  }

  private targetAt(p: Plan, k: number): THREE.Vector3 {
    const e = ease(k), even = p.shot.move === 'fly' || p.shot.move === 'orbit' || p.shot.move === 'spin';
    return new THREE.Vector3(p.x + p.gx * (even ? k : e), p.y, p.z + p.gz * (even ? k : e));
  }

  /**
   * CPU vehicles readable in a pose: inside the frame (l: the 16:9 frame; v: the 9:16 crop, its middle 0.316 of the
   * width), no further than half as far again as the subject (the sharp band, big enough to see), in front.
   */
  private readable(p: Plan, k: number, cam?: THREE.PerspectiveCamera): { l: number; v: number } {
    let c = cam;
    let dist = p.dist0 + (p.dist1 - p.dist0) * ease(k);
    if (!c) {
      c = this.probeCam;
      c.copy(this.host.camera);
      c.position.copy(this.camAt(p, k));
      c.lookAt(this.targetAt(p, k));
      c.updateMatrixWorld();
      c.updateProjectionMatrix();
    } else dist = c.position.distanceTo(this.target);
    void dist;
    const v = new THREE.Vector3();
    let l = 0, vert = 0;
    for (const m of this.host.movers()) {
      if (!bigEnough(m.kind, m.id, Math.hypot(m.x - c.position.x, m.y - c.position.y, m.z - c.position.z))) continue;
      v.set(m.x, m.y, m.z).project(c);
      if (v.z >= 1 || Math.abs(v.y) > 0.9 || Math.abs(v.x) > 0.92) continue;
      l++;
      if (Math.abs(v.x) < 0.29) vert++;
    }
    return { l, v: vert };
  }

  /**
   * Open ground for a formation near a place (global x, z, radius r): a straight lane `len` tiles long and `wide`
   * across, every tile of it dry, off rails, clear of buildings and no steeper than a car climbs, passing the place
   * side on at 12 to 100 tiles. Of those, the one with fewest rocks and cacti on it, then fewest trees on it and in the
   * 12 tiles either side, so the lowest camera sees the V rather than a wood (the limo V first ran down a railway,
   * the semi V behind a copse); a lane's own trees count four times. Returns its start (global) and heading, or null.
   */
  private lane(w: World, x: number, z: number, r: number, len: number, wide: number): { x: number; z: number; h: number } | null {
    const VIEW = 12;
    const tile = (gx: number, gz: number): number => {
      const tx = Math.floor(gx - w.ox), tz = Math.floor(gz - w.oz);
      return inB(tx, tz) ? idx(tx, tz) : -1;
    };
    // nor through a point of interest (the semi V ran into a stone circle and one sat wedged in it), and every side
    // of every tile drivable (a semi of the V caught on a road's edge and dropped out)
    const nearPoi = new Uint8Array(N * N);
    for (const p of w.pois) for (let dz = -4; dz <= 4; dz++) for (let dx = -4; dx <= 4; dx++) { const tx = Math.floor(p.x) + dx, tz = Math.floor(p.z) + dz; if (inB(tx, tz)) nearPoi[idx(tx, tz)] = 1; }
    const open = (i: number): boolean => i >= 0 && !w.blocked[i] && !w.rail[i] && !(w.flags[i] & Flag.Poi) && !nearPoi[i] && w.edges[i] === 15 && waterDepth(w, i) <= 0 && steepness(w, i) <= 1;
    const trees = (i: number): number => propsOn(w, i % N, Math.floor(i / N)).trees;
    let best: { x: number; z: number; h: number } | null = null, bestScore = Infinity, lanes = 0, bestOff = 0;
    for (let off = r + 12; off <= r + 100 && bestScore > 0; off += 4) {
      for (let a = 0; a < 24; a++) {
        const ang = (a / 24) * Math.PI * 2;
        // the lane's middle off the place this way, running across that line (both ways), a little skewed either side
        const mx = x + Math.sin(ang) * off, mz = z + Math.cos(ang) * off;
        for (const skew of [0, 0.35, -0.35]) for (const dir of [1, -1]) {
          const h = ang + dir * Math.PI / 2 + skew;
          const fx = Math.sin(h), fz = Math.cos(h), nx = Math.cos(h), nz = -Math.sin(h);
          const sx = mx - fx * len / 2, sz = mz - fz * len / 2;
          // and near the place: two points a tile further out, so the place stays big behind the V
          let ok = true, score = (off - r - 12) * 2;
          const seen = new Set<number>();
          for (let u = 0; u <= len && ok; u += 0.5) for (let q = -wide / 2; q <= wide / 2 && ok; q += 0.5) {
            const i = tile(sx + fx * u + nx * q, sz + fz * u + nz * q);
            ok = open(i);
            if (ok && !seen.has(i)) {
              seen.add(i);
              // a rock or cactus stops a car dead (a limo of the V sat wedged on one): one counts as forty trees,
              // so a lane with none wins wherever there is one (the semi V's 43 by 14 tiles near Grand Tessaly had none)
              const p = propsOn(w, i % N, Math.floor(i / N));
              // and level ground over a slope or a feature (a broad beach: the semi V broke up on its humps and two
              // stuck): the V holds its shape where every car keeps its speed
              score += 4 * p.trees + 160 * (p.rocks + p.cacti) + 3 * steepness(w, i) + (w.feature[i] ? 200 : 0);
            }
          }
          for (let u = 0; u <= len && ok && score < bestScore; u += 1) for (let q = wide / 2 + 1; q <= wide / 2 + VIEW; q += 1) for (const sd of [1, -1]) {
            const i = tile(sx + fx * u + sd * nx * q, sz + fz * u + sd * nz * q);
            if (i >= 0 && !seen.has(i)) { seen.add(i); score += trees(i); }
          }
          // and the ground the camera looks across at the V: from the lane's middle out 45 tiles on the far side from
          // the place, over the orbit's sweep each way (the limo V drove behind a wood the whole shot); three apiece
          if (ok && score < bestScore) {
            const dx = mx - x, dz = mz - z, base = Math.atan2(dx, dz);
            for (let da = -0.6; da <= 0.6 + 1e-6 && score < bestScore; da += 0.15) {
              const ex = Math.sin(base + da), ez = Math.cos(base + da);
              for (let q = 2; q <= 45; q += 1) {
                const i = tile(mx + ex * q, mz + ez * q);
                if (i >= 0 && !seen.has(i)) { seen.add(i); score += 3 * trees(i); }
              }
            }
          }
          // the place in sight over the ground from the lowest camera halfway through, 30 tiles out on the V's far
          // side (the limo V's Artemision sat behind a hill the whole shot): hidden counts as a thousand trees
          if (ok && score < bestScore) {
            const dx = mx - x, dz = mz - z, dl = Math.hypot(dx, dz) || 1;
            const cx = mx + (dx / dl) * 30, cz = mz + (dz / dl) * 30;
            const cy = this.host.groundAt(cx, cz) + 3.5, ty = this.host.groundAt(x, z) + Math.max(8, r * 0.5);
            for (let j = 1; j < 40; j++) {
              const u = j / 40, gx = cx + (x - cx) * u, gz = cz + (z - cz) * u;
              if (this.host.groundAt(gx, gz) > cy + (ty - cy) * u - 0.3) { score += 1000; break; }
            }
          }
          if (ok) lanes++;
          if (ok && score < bestScore) { bestScore = score; best = { x: sx, z: sz, h }; bestOff = off - r; }
        }
      }
    }
    if (best) this.log.push(`lane: score ${bestScore.toFixed(0)} of ${lanes} open, ${bestOff.toFixed(0)} tiles out`);
    return best;
  }

  private camAt(p: Plan, k: number): THREE.Vector3 {
    const e = ease(k);
    const yaw = p.hero ? (p.shot.orbit ? this.orbitYaw + p.shot.orbit * SPIN * k * (p.shot.len ?? 10) : this.followYaw) : p.yaw0 + (p.yaw1 - p.yaw0) * (p.shot.move === 'orbit' || p.shot.move === 'spin' ? k : e);
    const pitch = p.pitch0 + (p.pitch1 - p.pitch0) * e, dist = p.dist0 + (p.dist1 - p.dist0) * e;
    let tx = p.x + p.gx * (p.shot.move === 'fly' ? k : e), tz = p.z + p.gz * (p.shot.move === 'fly' ? k : e), ty = p.y;
    if (p.hero) { const h = p.hero(); if (h) { tx = h.x; ty = h.y; tz = h.z; } }
    const cp = Math.cos(pitch);
    return new THREE.Vector3(tx + Math.sin(yaw) * cp * dist, ty + Math.sin(pitch) * dist, tz + Math.cos(yaw) * cp * dist);
  }

  /** Pose the camera k (0..1) through the shot. Orbits, spins and flies run at an even pace; the rest ease. */
  private pose(k: number): void {
    const p = this.plan!;
    const e = ease(k);
    const even = p.shot.move === 'orbit' || p.shot.move === 'spin' || p.shot.move === 'fly';
    const pitch = p.pitch0 + (p.pitch1 - p.pitch0) * e;
    const dist = p.dist0 + (p.dist1 - p.dist0) * e;
    let yaw = p.yaw0 + (p.yaw1 - p.yaw0) * (even ? k : e);
    if (p.hero) {
      const h = p.hero();
      if (h) {
        // eased once a frame (pose runs twice a frame): about a tenth of a second behind, never a shake
        if (this.heroEasedAt !== this.t) { this.heroAt.lerp(new THREE.Vector3(h.x, h.y, h.z), 1 - Math.exp(-DT / 0.1)); this.heroEasedAt = this.t; }
        this.target.copy(this.heroAt);
        // the camera swings round behind (or beside) it slowly, never snapping
        const want = h.heading + Math.PI + deg(p.shot.yaw ?? 0);
        this.followYaw += Math.atan2(Math.sin(want - this.followYaw), Math.cos(want - this.followYaw)) * 0.02;
      }
      yaw = p.shot.orbit ? this.orbitYaw + p.shot.orbit * SPIN * k * (p.shot.len ?? 10) : this.followYaw;
    } else {
      const g = even ? k : e;
      this.target.set(p.x + p.gx * g, p.y, p.z + p.gz * g);
    }
    this.host.reel.pose(yaw, pitch, dist, this.target);
  }

  // ---- the motion check --------------------------------------------------------------------------

  /**
   * Every mover in the frame (the middle 90% of it, the vertical crop's band included) against where it was last
   * frame: a jump further than any vehicle goes in a frame, one standing still after moving fast (a stall, then a
   * catch-up), or one appearing or vanishing inside the frame rather than driving in or out.
   */
  private check(): { t: number; bad: string[]; seen: number } {
    const cam = this.host.camera;
    cam.updateMatrixWorld();
    const v = new THREE.Vector3();
    const now = new Map<string, { x: number; y: number; z: number; kind: string; d: number }>();
    const bad: string[] = [];
    let seen = 0;
    const cp = cam.position;
    // in the frame and big enough to see: a pop or a stutter of something a few pixels long, far off in the blur, isn't
    const inner = (x: number, y: number, z: number, kind = 'land', id = '') => {
      if (!bigEnough(kind, id, Math.hypot(x - cp.x, y - cp.y, z - cp.z))) return false;
      v.set(x, y, z).project(cam);
      return v.z < 1 && Math.abs(v.x) < 0.9 && Math.abs(v.y) < 0.9;
    };
    for (const m of this.host.movers()) {
      const was = this.last.get(m.id);
      const d = was ? Math.hypot(m.x - was.x, m.z - was.z) : -1;
      now.set(m.id, { ...m, d });
      const inFrame = inner(m.x, m.y, m.z, m.kind, m.id);
      if (inFrame) seen++;
      // a CPU driver pressed into a building, backing off one or on a tow: retake (the user, 6 Nov 2026)
      if (inFrame && m.wedged) bad.push(`${m.kind} ${m.id} wedged`);
      if (!was) { if (inFrame && this.last.size) bad.push(`${m.kind} ${m.id} appeared in frame`); continue; }
      // a step that changes size suddenly: ticked every other frame (0, then double), a stall and a catch-up, a
      // snap. Driving, a step changes by thousandths of a tile a frame; even braking hard by ~0.003
      if (inFrame && was.d >= 0 && Math.abs(d - was.d) > 0.03 + 0.25 * Math.max(d, was.d) * (m.kind === 'air' ? 1 : 0)) bad.push(`${m.kind} ${m.id} step ${was.d.toFixed(3)}→${d.toFixed(3)}`);
      // 6 tiles a second is a fast car, 40 a plane: a frame is 1/60 s
      const most = (m.kind === 'air' ? 1.2 : m.kind === 'rail' ? 0.35 : 0.3);
      if (inFrame && d > most) bad.push(`${m.kind} ${m.id} jumped ${d.toFixed(2)} tiles`);
    }
    if (this.last.size) for (const [id, was] of this.last) if (!now.has(id) && inner(was.x, was.y, was.z, was.kind, id)) bad.push(`${was.kind} ${id} vanished in frame`);
    this.last = now;
    return { t: +this.t.toFixed(3), bad, seen };
  }
}
