/**
 * Names players choose: what is allowed, and how often a fleet may be renamed (the user, 4 Nov 2026). Shared by the
 * server, which decides (server/index.ts: a new player, a one-click fleet kept, a fleet renamed), and the game, which
 * says so before anything is sent (title/menu.ts: the sign-in card, the fleet editor).
 *
 * The filter is a basic one on purpose: common profanity and slurs, seen through capitals, separators, repeated
 * letters and digits for letters ("Sh1t", "f_u_c_k", "fuuuck"). Words that hide inside ordinary ones (cock in
 * Peacock, coon in Tycoon, rape in Grape) are only refused as a word of their own, split at spaces, separators, digits
 * and capitals ("BigCock", "big_cock"), so a fair name is not caught.
 */

/** Refused anywhere in a name, once squashed (letters only, digits read as letters, repeats run together). */
const ANYWHERE = [
  'fuck', 'shit', 'cunt', 'bitch', 'whore', 'slut', 'twat', 'bollock', 'bastard', 'pussy', 'penis', 'vagina',
  'dildo', 'jizz', 'blowjob', 'handjob', 'porn', 'asshole', 'arsehole', 'retard', 'nigger', 'nigga', 'faggot', 'kike',
  'kyke', 'wetback', 'beaner', 'towelhead', 'raghead', 'tranny', 'shemale', 'chingchong', 'hitler', 'whitepower',
  'siegheil', 'gaschamber', 'molest',
];
/** Refused only as a word of the name's own (see the top). */
const WORDS = [
  'ass', 'arse', 'asses', 'cock', 'cocks', 'dick', 'dicks', 'cum', 'tit', 'tits', 'anal', 'rape', 'raped', 'rapist',
  'fag', 'fags', 'dyke', 'homo', 'spic', 'spick', 'coon', 'coons', 'paki', 'pakis', 'gook', 'gooks', 'chink', 'chinks',
  'jap', 'japs', 'negro', 'nazi', 'nazis', 'heil', 'kkk', 'sex', 'nig', 'nigs', 'wank', 'wanker', 'wankers', 'pedo',
  'pedos', 'paedo', 'pedophile', 'paedophile',
];
/** Refused as written, digits and all. */
const RAW = ['1488', 'kkk', '88heil'];
/** Ordinary words and places with one of the above inside, taken out before looking (a town, a mushroom, a surname). */
const ALLOW = ['scunthorpe', 'penistone', 'shitake', 'shiitake', 'cockburn', 'hancock', 'peacock', 'cocktail', 'cockpit', 'dickens', 'sussex', 'essex', 'middlesex'];

/** Digits and symbols read as the letters they stand in for. */
const LEET: Record<string, string> = { 0: 'o', 1: 'i', 2: 'z', 3: 'e', 4: 'a', 5: 's', 6: 'g', 7: 't', 8: 'b', 9: 'g', '@': 'a', $: 's', '!': 'i', '|': 'i', '+': 't' };
const letters = (s: string): string => [...s.toLowerCase()].map((ch) => LEET[ch] ?? ch).join('').replace(/[^a-z]/g, '');
const squash = (s: string): string => letters(s).replace(/(.)\1+/g, '$1');
const ANY_SQ = ANYWHERE.map(squash);

/** The name's own words: split at anything not a letter or digit, at digits, and where a capital starts a word. */
function words(name: string): string[] {
  return name.replace(/([a-z])([A-Z])/g, '$1 $2').split(/[^A-Za-z]+/).map((w) => w.toLowerCase()).filter(Boolean);
}

/** Why a name may not be used, or null when it's fine. Says nothing about which word, so it can't be gamed by trial. */
export function nameProblem(given: string): string | null {
  let name = given;
  for (const a of ALLOW) name = name.replace(new RegExp(a, 'gi'), ' ');
  const raw = name.toLowerCase().replace(/[\s_.-]+/g, '');
  const sq = squash(name);
  const bad = RAW.some((w) => raw.includes(w))
    || ANY_SQ.some((w) => sq.includes(w))
    || words(name).some((w) => WORDS.includes(w) || WORDS.includes(letters(w)));
  return bad ? 'That name isn’t allowed here: please pick another.' : null;
}

/**
 * How long a fleet's name stays as it is after each rename, in days: a day after the first, a week after the second
 * (however soon it came after the first), then a month, three months, and a year between every rename after that.
 * The name a fleet is made with is not a rename.
 */
export const RENAME_WAIT_DAYS = [1, 7, 30, 90, 365] as const;
const DAY_MS = 86_400_000;

/** A fleet's renames so far: how many, and when the last was (ms). */
export interface Renames { n: number; at: number }

/** When the fleet may next be renamed (ms; 0 for now). */
export function renameOpensAt(r: Renames | null | undefined): number {
  if (!r || !(r.n > 0)) return 0;
  return r.at + RENAME_WAIT_DAYS[Math.min(r.n, RENAME_WAIT_DAYS.length) - 1] * DAY_MS;
}

/** The wait a rename now would start (days): what the fleet editor warns of before saving. */
export function renameWaitAfterNext(r: Renames | null | undefined): number {
  return RENAME_WAIT_DAYS[Math.min((r?.n ?? 0) + 1, RENAME_WAIT_DAYS.length) - 1];
}

/** "in 5 days", "in 3 hours", "in a few minutes": how long until a time. */
export function untilText(at: number, now = Date.now()): string {
  const ms = Math.max(0, at - now);
  const d = Math.floor(ms / DAY_MS), h = Math.floor(ms / 3_600_000), m = Math.ceil(ms / 60_000);
  return d >= 2 ? `in ${d} days` : h >= 2 ? `in ${h} hours` : m > 5 ? `in ${m} minutes` : 'in a few minutes';
}

/** "a day", "a week", "30 days": a wait in days, in words. */
export function daysText(d: number): string {
  return d === 1 ? 'a day' : d === 7 ? 'a week' : d === 365 ? 'a year' : `${d} days`;
}
