/**
 * The frame rate, minute by minute (the user, 4 Nov 2026: the fps figure in the top bar went; Settings → Frame rate
 * shows a small chart of the average frame rate of each of the last few minutes instead). Counted by real time, so
 * a paused game or a hidden tab (frames a second or more apart) doesn't drag a minute's average down.
 */

/** Minutes kept for the chart, the one under way among them. */
export const FPS_MINUTES = 6;
/** A gap between frames longer than this (seconds) is the game not drawing (a pause, a hidden tab): not counted. */
const GAP = 1;

interface Minute { at: number; frames: number; secs: number }

class FpsLog {
  private minutes: Minute[] = [];
  private last = 0;

  /** One frame drawn, now. */
  tick(now = performance.now()): void {
    const dt = this.last ? (now - this.last) / 1000 : 0;
    this.last = now;
    const at = Math.floor(now / 60000);
    let m = this.minutes[this.minutes.length - 1];
    if (!m || m.at !== at) {
      m = { at, frames: 0, secs: 0 };
      this.minutes.push(m);
      if (this.minutes.length > FPS_MINUTES) this.minutes.shift();
    }
    if (dt > 0 && dt < GAP) { m.frames++; m.secs += dt; }
  }

  /**
   * The average frame rate of each minute kept, oldest first, the one under way last (`live`); `ago` is minutes before
   * now. Minutes with too little in them to tell (under two seconds drawn) are left out.
   */
  history(): { ago: number; fps: number; live: boolean }[] {
    const now = Math.floor(performance.now() / 60000);
    return this.minutes
      .filter((m) => m.secs >= 2)
      .map((m) => ({ ago: now - m.at, fps: m.frames / m.secs, live: m.at === now }));
  }
}

export const fpsLog = new FpsLog();
