/**
 * Submarine jobs (docs/underwater.html, phase 2): side work offered only while the player drives a submarine,
 * all of it on the seabed (world/seabed.ts). Two want the Leviathan's freight hold (a lost container, a cable
 * repair kit); two are anyone's in a sub (wreck finds against Greywater Salvage's clock, a reef census of three
 * dives held on the bottom). Every one binds in the `sub` form, so only a submarine takes it.
 */
import type { Site } from '../cargo';
import type { MissionCtx } from './missions';
import type { Giver, Obj, PlaceRef } from './model';
import { siteRef, townRef, type Draft, type Template } from './templates';
import { BIG_SHIP } from '../cargoTypes';
import { roomAt } from '../../world/seabed';
import { N } from '../../world/tiles';

/** How far off (tiles) a job's seabed site may lie from the player. */
const REACH = 420;
/** A census dive's ring, in tiles: the water is deep enough for the sub everywhere inside it. */
const CENSUS_R = 2;

/** The water the sub being driven dives in (its dive.need), or null out of a submarine. */
function needOf(c: MissionCtx): number | null {
  return c.def.kind === 'water' && c.def.dive ? c.def.dive.need : null;
}
const inSub = (c: MissionCtx): string | null => (needOf(c) === null ? 'a submarine' : null);
const inLeviathan = (c: MissionCtx): string | null => (c.def.id === 'submarine' ? null : 'a Leviathan');

/** A seabed site of these kinds the sub being driven can go down to, nearest the player, within REACH (the h-th nearest of the first three). */
function seabedNear(c: MissionCtx, kinds: string[], h: number): Site | null {
  const need = needOf(c);
  if (need === null) return null;
  const list = c.sites(kinds).filter((s) => s.seabed && (s.depth ?? 0) >= need && Math.hypot(s.x - c.at.x, s.z - c.at.z) <= REACH)
    .sort((a, b) => Math.hypot(a.x - c.at.x, a.z - c.at.z) - Math.hypot(b.x - c.at.x, b.z - c.at.z));
  return list.length ? list[h % Math.min(3, list.length)] : null;
}

/** The harbour nearest a place that the sub being driven can berth at (the Leviathan only at a big one). */
function harbourNear(c: MissionCtx, p: { x: number; z: number }, not?: Site): Site | null {
  const big = c.def.kind === 'water' && c.def.halfLen > BIG_SHIP;
  let best: Site | null = null, bd = REACH * 1.5;
  for (const s of c.sites(big ? ['majorPort'] : ['minorPort', 'majorPort'])) {
    if (s === not || s.quay) continue;
    const d = Math.hypot(s.x - p.x, s.z - p.z);
    if (d < bd) { bd = d; best = s; }
  }
  return best;
}

/** A harbour's master, as a giver. */
function harbourGiver(s: Site, name = 'The harbourmaster'): Giver {
  const port = s.w.ports.find((p) => p.id === s.port);
  const t = s.w.towns.find((q) => port?.town === q.id) ?? null;
  return { who: 'harbour', name, at: { ...siteRef(s), name: port?.name ?? 'the harbour' }, town: t ? townRef(s.w, t) : null };
}

/** A site's name for a card: "the wreck of the Calypso" (its name carries the county after a " · "). */
const called = (s: Site): string => { const n = s.name.split(' · ')[0]; return n.charAt(0).toLowerCase() + n.slice(1); };

/** Goods to or from the seabed, as a step: the load's own value, scaled by the trip. */
function haul(cargo: string, icon: string, label: string, from: Site, to: Site, perTile: number, base: number): Extract<Obj, { t: 'deliver' }> {
  const fr = { ...siteRef(from), name: from.seabed ? called(from) : siteRef(from).name };
  const tr = { ...siteRef(to), name: to.seabed ? called(to) : siteRef(to).name };
  const dist = Math.hypot(to.x - from.x, to.z - from.z);
  return { t: 'deliver', label: label.slice(0, 28), icon, cargo, from: fr, to: tr, n: 1, value: Math.round((base + dist * perTile) / 5) * 5 };
}

const round = (v: number) => Math.round(v / 10) * 10;

// ---- the Leviathan's ------------------------------------------------------------------------------

const overTheSide: Template = {
  id: 'sub:overside', thread: 'town', kind: 'job', side: true, cooldown: 30,
  gate: inLeviathan,
  bind(c, h): Draft | null {
    const lost = seabedNear(c, ['seaLost'], h);
    const port = lost && harbourNear(c, lost);
    if (!lost || !port) return null;
    const obj = haul('lostContainer', '📦', `Container → ${siteRef(port).name}`, lost, port, 2.2, 160);
    return {
      title: 'Over the Side', why: `A container went over the side and lies on the bottom. Bring it up and land it at the ${obj.to.name.toLowerCase()} before its owners give up.`,
      details: `It lies on the bottom at ${called(lost)}. The ship never stopped. Its owners want the box back dry or not, and they want it today.`,
      giver: harbourGiver(port), hero: { kind: 'crate', colour: 0x2f6fa8 }, caption: 'Lost overboard',
      objs: [obj], reward: [{ r: 'cash', n: round(obj.value * 1.6 + 400) }], hours: 8, form: 'sub',
    };
  },
};

const downTheLine: Template = {
  id: 'sub:downline', thread: 'town', kind: 'job', side: true, cooldown: 30,
  gate: inLeviathan,
  bind(c, h): Draft | null {
    const fault = seabedNear(c, ['seaFault'], h);
    const port = fault && harbourNear(c, fault);
    if (!fault || !port) return null;
    const pipe = /pipeline/.test(fault.name);
    const obj = haul('repairKit', '🔧', 'Repair Kit → the break', port, fault, 2.1, 160);
    return {
      title: 'Down the Line', why: `The ${pipe ? 'pipeline' : 'cable'} has broken on the bottom. Take the repair kit down from the ${siteRef(port).name.toLowerCase()} and set it beside the break.`,
      details: pipe ? 'The rig is running on what is in its tanks. The divers can splice it once the kit is on the bottom beside the break.'
        : 'Half the coast is on the generators. The divers can splice it once the kit is on the bottom beside the break.',
      giver: harbourGiver(port, pipe ? 'The rig’s engineer' : 'The power company'), hero: { kind: 'crate', colour: 0xd23a2e }, caption: pipe ? 'A pipeline fault' : 'A cable fault',
      objs: [obj], reward: [{ r: 'cash', n: round(obj.value * 1.6 + 450) }], hours: 8, form: 'sub',
    };
  },
};

// ---- anyone's in a sub ----------------------------------------------------------------------------

const wreckRun: Template = {
  id: 'sub:wreckrun', thread: 'car', kind: 'job', side: true, cooldown: 24,
  gate: inSub,
  bind(c, h): Draft | null {
    const wreck = seabedNear(c, ['seaWreck'], h);
    const port = wreck && harbourNear(c, wreck);
    if (!wreck || !port) return null;
    const obj = haul('wreckFinds', '🏺', `Finds → ${siteRef(port).name}`, wreck, port, 1.4, 90);
    return {
      title: 'Wreck Run', why: `Greywater Salvage has a barge on its way to the wreck. Get down there first and land what you find for the museum.`,
      details: `The wreck is ${called(wreck)}. Whatever is on the bottom belongs to whoever brings it up first. Greywater knows that too.`,
      giver: harbourGiver(port, 'The museum’s curator'), hero: { kind: 'vehicle', model: 'minisub' }, caption: 'Beat the salvage men',
      objs: [obj], reward: [{ r: 'cash', n: round(obj.value * 1.5 + 250) }], hours: 4, form: 'sub',
    };
  },
};

/** Two more spots round a reef, `need` deep or more, a few tiles from it and from each other, picked by the hash. */
function censusSpots(reef: Site, need: number, h: number): PlaceRef[] {
  const w = reef.w, out: PlaceRef[] = [];
  if (roomAt(w, Math.floor(reef.lx), Math.floor(reef.lz), CENSUS_R) >= need) out.push({ x: reef.x, z: reef.z, cell: [w.cx, w.cz], name: 'the reef' });
  for (let k = 0; k < 16 && out.length < 3; k++) {
    const a = ((h % 16) + k * 5) / 16 * Math.PI * 2, r = 6 + ((h >> 4) + k) % 6;
    const lx = reef.lx + Math.cos(a) * r, lz = reef.lz + Math.sin(a) * r;
    const tx = Math.floor(lx), tz = Math.floor(lz);
    // deep enough for this sub anywhere in the dive's ring (CENSUS_R), not only at its middle
    if (tx < 4 || tz < 4 || tx >= N - 4 || tz >= N - 4 || roomAt(w, tx, tz, CENSUS_R) < need) continue;
    const x = w.ox + tx + 0.5, z = w.oz + tz + 0.5;
    if (out.some((p) => Math.hypot(p.x - x, p.z - z) < 5)) continue;
    out.push({ x, z, cell: [w.cx, w.cz], name: out.length ? `the reef’s ${out.length === 1 ? 'edge' : 'far side'}` : 'the reef' });
  }
  return out;
}

const reefCensus: Template = {
  id: 'sub:reefcensus', thread: 'town', kind: 'job', side: true, cooldown: 36,
  gate: inSub,
  bind(c, h): Draft | null {
    const need = needOf(c);
    const reef = need !== null ? seabedNear(c, ['seaReef'], h) : null;
    if (!reef || need === null) return null;
    const spots = censusSpots(reef, need, h);
    if (spots.length < 3) return null;
    const port = harbourNear(c, reef);
    const near = c.sites(['aquarium', 'university', 'researchStation']).sort((a, b) => Math.hypot(a.x - reef.x, a.z - reef.z) - Math.hypot(b.x - reef.x, b.z - reef.z))[0];
    const giver: Giver | null = near && Math.hypot(near.x - reef.x, near.z - reef.z) < 600
      ? { who: 'scientist', name: 'Dr Teodor Lind', at: siteRef(near), town: near.w.towns.find((t) => t.buildings.includes(near.b!)) ? townRef(near.w, near.w.towns.find((t) => t.buildings.includes(near.b!))!) : null }
      : port ? harbourGiver(port, 'The marine survey') : null;
    if (!giver) return null;
    const objs: Obj[] = spots.map((at, k) => ({ t: 'reach', label: `Dive at ${k === 0 ? 'the reef' : k === 1 ? 'its edge' : 'its far side'}`, icon: '🪸', at, r: CENSUS_R, stop: true, hold: 8, dived: true }));
    return {
      title: 'Reef Census', why: `The ${/coral/.test(reef.name) ? 'coral' : 'kelp'} needs counting. Go down at three places on it and stay down at each while the cameras run.`,
      details: 'Eight seconds on the bottom at each mark, stopped, while the survey cameras count the fish.',
      giver, hero: { kind: 'vehicle', model: c.def.id }, caption: 'A census of the reef',
      objs, reward: [{ r: 'cash', n: round(650 + Math.hypot(reef.x - c.at.x, reef.z - c.at.z) * 1.5) }], hours: 10, form: 'sub',
    };
  },
};

export const SUB_TEMPLATES: Template[] = [overTheSide, downTheLine, wreckRun, reefCensus];
