import { N, STEP, heightAt, idx, inB, waterDepth, type World } from './tiles';
import { cell01, hashString } from './rng';

/**
 * Places on the seabed (docs/underwater.html): a wreck, a container gone over the side, a reef, a cable or
 * pipeline fault and a survey beacon, where only a submarine that has dived and sounded (gone down to the
 * bottom) takes goods up or sets them down. Worked out from a county's water when it is in memory, the way the
 * PvP lines are, and never written into the world: the generator, the world's GEN and the online world are
 * untouched. The same county always has the same sites, in the same places.
 */

export type SeabedKind = 'seaWreck' | 'seaLost' | 'seaReef' | 'seaFault' | 'seaBeacon';
export const SEABED_KINDS: readonly SeabedKind[] = ['seaWreck', 'seaLost', 'seaReef', 'seaFault', 'seaBeacon'];
export const isSeabed = (k: string): k is SeabedKind => (SEABED_KINDS as readonly string[]).includes(k);

export interface SeabedSite {
  kind: SeabedKind;
  /** Its name on a load's card: "the wreck of the Calypso". */
  name: string;
  /** The middle of its tile, in the county's own tiles. */
  lx: number; lz: number;
  /** The water there, in height steps: what a submarine must be able to dive in (VehicleDef dive.need). */
  depth: number;
  /** The seabed's height and the water's surface there, in world units. */
  floor: number; surface: number;
}

/** The shallowest water a site lies in: a Guppy (dive.need 3) sounds over the shallowest. */
export const SEABED_MIN_DEPTH = 3;
/** A Leviathan (dive.need 4) needs this: the freight sites (a lost container, a fault) lie at least this deep. */
export const SEABED_DEEP = 4;
/** Sites keep at least this far apart, and this far from a harbour's pier, in tiles. */
const APART = 24, OFF_PIER = 10;
/** How often a county has each kind (a seeded roll per county and kind), before what it needs is looked for. */
const CHANCE: Record<SeabedKind, number> = { seaWreck: 0.6, seaLost: 0.55, seaReef: 0.65, seaFault: 0.8, seaBeacon: 0.5 };
/** What a fault lies off: the works a cable or a pipe runs out from. */
const FAULT_FROM = new Set(['oilRig', 'refinery', 'substation', 'powerPlant']);
const PIPE = new Set(['oilRig', 'refinery']);

const WRECKS = ['Calypso', 'Lady Grey', 'Northern Star', 'Saint Anne', 'Cormorant', 'Albatross', 'Endeavour', 'Mary Ellen', 'Gannet', 'Providence', 'Kittiwake', 'Halcyon'];

const cache = new WeakMap<World, { rev: number; sites: SeabedSite[] }>();

/** The seabed sites of a county in memory (worked out once per world and revision). */
export function seabedSites(w: World): SeabedSite[] {
  const c = cache.get(w);
  if (c && c.rev === w.revision) return c.sites;
  const sites = place(w);
  cache.set(w, { rev: w.revision, sites });
  return sites;
}

/** Water joined to the open sea (not a lake or a canal): what a submarine can sail to from a harbour. */
const ocean = (w: World, i: number): boolean => w.water[i] >= 0 && w.coastDist[i] === 0;

/** The least depth on a tile and its four neighbours: room to sound without the hull touching a bank (0 off the open sea). */
export function depthAt(w: World, x: number, z: number): number {
  let d = Infinity;
  for (const [dx, dz] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) {
    const tx = x + dx, tz = z + dz;
    if (!inB(tx, tz)) return 0;
    const i = idx(tx, tz);
    if (!ocean(w, i)) return 0;
    d = Math.min(d, waterDepth(w, i));
  }
  return d;
}

/** Tiles from the nearest land (or lake, or canal) for every ocean tile, up to `far` (a flood out from the shore). */
/**
 * The least depth (depthAt) over the tiles within `rad` of tile (x, z): what a submarine can count on anywhere in a
 * ring that wide round it, so a dive asked for there never meets a bank too shallow to go down from.
 */
export function roomAt(w: World, x: number, z: number, rad: number): number {
  let d = Infinity;
  for (let dz = -rad; dz <= rad; dz++) for (let dx = -rad; dx <= rad; dx++) {
    if (dx * dx + dz * dz > rad * rad + 1) continue;
    d = Math.min(d, depthAt(w, x + dx, z + dz));
    if (d <= 0) return 0;
  }
  return d;
}

function landDistance(w: World, far: number): Uint8Array {
  const d = new Uint8Array(N * N).fill(255);
  let q: number[] = [];
  for (let i = 0; i < N * N; i++) if (!ocean(w, i)) { d[i] = 0; q.push(i); }
  for (let step = 1; step <= far && q.length; step++) {
    const next: number[] = [];
    for (const i of q) {
      const x = i % N, z = (i - x) / N;
      for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const tx = x + dx, tz = z + dz;
        if (!inB(tx, tz)) continue;
        const j = idx(tx, tz);
        if (d[j] !== 255) continue;
        d[j] = step;
        next.push(j);
      }
    }
    q = next;
  }
  return d;
}

function place(w: World): SeabedSite[] {
  const seed = hashString(w.seed);
  const roll = (salt: number) => cell01(seed, w.cx, w.cz, salt);
  // no sea at all, or no harbour to bring anything to: nothing down there anyone would fetch
  if (!w.ports.length) return [];
  const land = landDistance(w, 60);
  const out: SeabedSite[] = [];
  const piers = w.ports.map((p) => ({ x: (p.root % N) + 0.5, z: Math.floor(p.root / N) + 0.5 }));
  const free = (x: number, z: number) => out.every((s) => Math.hypot(s.lx - x, s.lz - z) >= APART)
    && piers.every((p) => Math.hypot(p.x - x, p.z - z) >= OFF_PIER);
  /** Every tile (every other one, each way) passing `ok`, in scan order: the seeded roll picks one. */
  const scan = (ok: (x: number, z: number, i: number, depth: number) => boolean): [number, number, number][] => {
    const c: [number, number, number][] = [];
    for (let z = 2; z < N - 2; z += 2) for (let x = 2; x < N - 2; x += 2) {
      const i = idx(x, z);
      if (!ocean(w, i)) continue;
      const depth = depthAt(w, x, z);
      if (depth < SEABED_MIN_DEPTH || !ok(x, z, i, depth) || !free(x + 0.5, z + 0.5)) continue;
      c.push([x, z, depth]);
    }
    return c;
  };
  const add = (kind: SeabedKind, name: string, c: [number, number, number][], salt: number, best?: (a: [number, number, number]) => number) => {
    if (!c.length) return;
    const pick = best ? c.reduce((a, b) => (best(b) < best(a) ? b : a)) : c[Math.floor(roll(salt) * c.length) % c.length];
    const [x, z, depth] = pick;
    const lx = x + 0.5, lz = z + 0.5, i = idx(x, z);
    out.push({ kind, name, lx, lz, depth, floor: heightAt(w, lx, lz), surface: w.water[i] * STEP });
  };
  const buildings = [...w.towns.flatMap((t) => t.buildings), ...w.countryside, ...w.works.flatMap((g) => g.buildings)].filter((b) => !b.gone);

  // a wreck: off the shore, off a wreck on the beach when there is one (the rest of her went down)
  if (roll(1) < CHANCE.seaWreck) {
    const hulk = buildings.find((b) => b.kind === 'shipwreck');
    const name = `the wreck of the ${WRECKS[Math.floor(roll(2) * WRECKS.length) % WRECKS.length]}`;
    const c = scan((_x, _z, i) => land[i] >= 4 && land[i] <= 22);
    add('seaWreck', name, c, 3, hulk ? ([x, z]) => Math.hypot(x - hulk.x, z - hulk.z) : undefined);
  }
  // a container gone over the side: deep water about halfway between the two harbours furthest apart
  if (roll(4) < CHANCE.seaLost && w.ports.length >= 2) {
    let a = piers[0], b = piers[1], far = 0;
    for (const p of piers) for (const q of piers) { const d = Math.hypot(p.x - q.x, p.z - q.z); if (d > far) { far = d; a = p; b = q; } }
    const mx = (a.x + b.x) / 2, mz = (a.z + b.z) / 2;
    const c = scan((x, z, i, depth) => depth >= SEABED_DEEP && land[i] >= 6 && Math.hypot(x - mx, z - mz) < Math.max(30, far / 2));
    add('seaLost', 'a lost container', c, 5, ([x, z]) => Math.hypot(x - mx, z - mz));
  }
  // a reef: shallow water close in, in the warm (a kelp garden in the cold)
  if (roll(6) < CHANCE.seaReef) {
    const c = scan((_x, _z, i, depth) => depth <= SEABED_DEEP && land[i] >= 3 && land[i] <= 14);
    const warm = c.length ? w.temp[idx(c[0][0], c[0][1])] > 0.55 : false;
    add('seaReef', warm ? 'the coral garden' : 'the kelp garden', c, 7);
  }
  // a fault: on the cable or pipe running out from a rig, a refinery or a power works on the coast
  if (roll(8) < CHANCE.seaFault) {
    const src = buildings.filter((b) => FAULT_FROM.has(b.kind));
    if (src.length) {
      const s = src[Math.floor(roll(9) * src.length) % src.length];
      const sx = s.x + s.w / 2, sz = s.z + s.d / 2;
      const c = scan((x, z, i, depth) => depth >= SEABED_DEEP && land[i] >= 5 && Math.hypot(x - sx, z - sz) <= 50);
      add('seaFault', PIPE.has(s.kind) ? 'the pipeline fault' : 'the cable fault', c, 10, ([x, z]) => Math.abs(Math.hypot(x - sx, z - sz) - 26));
    }
  }
  // a survey beacon: the deepest open water in the county
  if (roll(11) < CHANCE.seaBeacon) {
    const c = scan((_x, _z, i, depth) => depth >= 5 && land[i] >= 15);
    add('seaBeacon', `survey beacon ${String.fromCharCode(65 + Math.floor(roll(12) * 26))}-${1 + Math.floor(roll(13) * 9)}`, c, 14, ([, , depth]) => -depth);
  }
  return out;
}
