import { isPid, type FriendRow, type Pid } from '../../shared/protocol';
import type { Online } from './online';

/**
 * Friends, online: anyone else playing can be added from their name wherever it shows (a name tag over
 * their car, the chat, the Fleets tab, the standings, the territory key) by right-clicking it, or from
 * their fleet's card, which a left-click on the name opens (net/fleetCard.ts). The Friends chip of the
 * social window's Fleets tab (net/fleetsTab.ts) lists them, signed in or not. The list itself is kept by the server on the player's record, so it is the
 * same on every machine they sign in from. Only players can be friends: the CPU firms carry no `data-pid`.
 *
 * Anything that shows a player's name marks it `data-pid="p:12"`; one listener on the page does the rest.
 */

interface FriendsHost {
  /** The camera follows this player's own vehicle, wherever they are. */
  follow(id: Pid, name: string): void;
  /** The camera goes to look at an HQ: its lot key ("cx,cz#b12") and name. */
  viewHq(key: string, name: string): void;
  /** Something to say on a card. */
  say(title: string, body: string): void;
  /** The cell the player is in, "cx,cz", for how far away a friend is. */
  here(): string;
  /** Their fleet's card in the social window (net/fleetCard.ts, docs/social.html): a left-click on a name anywhere. */
  openCard(id: Pid): void;
}

const esc = (s: string): string => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]!));
const hex = (c: number): string => `#${c.toString(16).padStart(6, '0')}`;

export class Friends {
  private menu = document.createElement('div');
  private menuFor: Pid | null = null;

  constructor(private online: Online, private host: FriendsHost) {
    this.menu.id = 'friend-menu';
    this.menu.hidden = true;
    document.body.append(this.menu);
    // right-click on a player's name, anywhere: the little menu at the pointer
    document.addEventListener('contextmenu', (e) => {
      const el = (e.target as HTMLElement | null)?.closest?.('[data-pid]') as HTMLElement | null;
      const id = el?.dataset.pid;
      if (!id || !this.online.active || !isPid(id) || id === this.online.me?.id) return;
      e.preventDefault();
      this.openMenu(id, el!.textContent?.trim() || this.online.people.get(id)?.name || 'Them', e.clientX, e.clientY);
    });
    // a left-click on a player's name, anywhere: their fleet's card (a button that happens to hold a name does its own thing)
    document.addEventListener('click', (e) => {
      const el = (e.target as HTMLElement | null)?.closest?.('[data-pid]') as HTMLElement | null;
      const id = el?.dataset.pid;
      if (!el || !id || !this.online.active || !isPid(id) || id === this.online.me?.id) return;
      if (el.dataset.fcact || (e.target as HTMLElement).closest('button:not([data-pid]), a, input, select, label')) return;
      e.preventDefault();
      this.host.openCard(id);
    });
    this.menu.addEventListener('pointerdown', (e) => {
      const b = (e.target as HTMLElement).closest('button[data-act]') as HTMLElement | null;
      if (!b || !this.menuFor) return;
      e.preventDefault();
      e.stopPropagation();
      this.act(b.dataset.act!, this.menuFor, b.dataset.name ?? '', b.dataset.key ?? '');
      this.closeMenu();
    });
    // anywhere else, or Escape, puts it away
    window.addEventListener('pointerdown', (e) => { if (!this.menu.hidden && !this.menu.contains(e.target as Node)) this.closeMenu(); }, true);
    // a Follow or HQ button on any player's row, friend or not (the Rivals tab, the Players tab): taken
    // before the window it sits in sees the press, which would open or close the row instead
    window.addEventListener('pointerdown', (e) => {
      const b = (e.target as HTMLElement | null)?.closest?.('button[data-pact]') as HTMLElement | null;
      if (!b || !this.online.active) return;
      e.preventDefault();
      e.stopPropagation();
      this.act(b.dataset.pact!, b.dataset.id!, b.dataset.name ?? '', b.dataset.key ?? '');
    }, true);
    window.addEventListener('keydown', (e) => { if (e.key === 'Escape') this.closeMenu(); });
  }

  private row(id: Pid): FriendRow | undefined { return this.online.friends.find((f) => f.id === id); }

  /** Any player's HQ, friend or not: their friend line, else their line on the server's board. */
  hqOf(id: Pid): { key: string; name: string } | undefined {
    return this.row(id)?.hq ?? this.online.ui.rows.find((r) => r.id === id)?.hq;
  }

  private openMenu(id: Pid, name: string, x: number, y: number): void {
    const f = this.row(id);
    const hq = this.hqOf(id);
    const on = !!this.online.cellOf(id);
    const who = this.online.people.get(id);
    const head = `<b>${esc(who?.name ?? name)}</b>${who?.brand?.name ? `<small>${esc(who.brand.name)}</small>` : ''}`;
    const btn = (act: string, label: string, extra = '') => `<button type="button" data-act="${act}"${extra}>${label}</button>`;
    this.menu.innerHTML = head
      + btn('card', 'Their card')
      + (f ? btn('drop', 'Remove friend') : btn('add', 'Add friend'))
      + (on ? btn('follow', 'Follow their vehicle', ` data-name="${esc(who?.name ?? name)}"`) : '')
      + (hq ? btn('hq', 'View their HQ', ` data-key="${esc(hq.key)}" data-name="${esc(hq.name)}"`) : '');
    this.menuFor = id;
    this.menu.hidden = false;
    // kept on screen
    const w = this.menu.offsetWidth, h = this.menu.offsetHeight;
    this.menu.style.left = `${Math.min(x, window.innerWidth - w - 8)}px`;
    this.menu.style.top = `${Math.min(y, window.innerHeight - h - 8)}px`;
  }

  private closeMenu(): void {
    this.menu.hidden = true;
    this.menuFor = null;
  }

  private act(act: string, id: Pid, name: string, key: string): void {
    const who = this.online.people.get(id)?.name ?? this.row(id)?.name ?? 'them';
    if (act === 'card') { this.host.openCard(id); return; }
    if (act === 'add') { this.online.friend(id, true); this.host.say('Friend added', `${who} · find them in the social window (I), Fleets → Friends`); }
    else if (act === 'drop') { this.online.friend(id, false); this.host.say('Friend removed', who); }
    else if (act === 'follow') {
      if (!this.online.cellOf(id)) { this.host.say(who, 'Not signed in just now'); return; }
      this.host.follow(id, name || who);
    } else if (act === 'hq' && key) this.host.viewHq(key, name || `${who}’s HQ`);
  }

  // ---- the Friends tab of Standings ------------------------------------------------------------------

  /** Shown: ask the server for the list as it stands. */
  opened(): void { this.online.askFriends(); }

  /** A press inside the tab. True if it was the tab's. */
  press(target: HTMLElement): boolean {
    const b = target.closest('.friends button[data-act]') as HTMLElement | null;
    if (!b) return false;
    this.act(b.dataset.act!, b.dataset.id!, b.dataset.name ?? '', b.dataset.key ?? '');
    return true;
  }

  html(): string {
    const list = this.online.friends;
    const here = this.host.here().split(',').map(Number);
    const away = (c: string) => {
      const [cx, cz] = c.split(',').map(Number);
      const n = Math.max(Math.abs(cx - here[0]), Math.abs(cz - here[1]));
      return n === 0 ? 'in this county' : `${n} ${n === 1 ? 'county' : 'counties'} away`;
    };
    const rows = list.map((f) => {
      const c = f.brand ? hex(f.brand.primary) : '#9aa6ad';
      const cell = this.online.cellOf(f.id) ?? f.c;
      const where = f.online && cell ? `<i class="on"></i>signed in · ${away(cell)}` : 'not signed in';
      const btn = (act: string, label: string, extra = '') => `<button type="button" class="link" data-act="${act}" data-id="${esc(f.id)}"${extra}>${label}</button>`;
      return `<li><span class="what"><i class="dot" style="background:${c}"></i><b data-pid="${esc(f.id)}">${esc(f.name)}</b>`
        + `<small>${esc(f.brand?.name ?? '')}${f.brand?.name ? ' · ' : ''}${where}${f.mutual ? '' : ' · hasn’t added you back'}</small></span>`
        + `<span class="acts">${f.online ? btn('follow', 'Follow', ` data-name="${esc(f.name)}"`) : ''}`
        + `${f.hq ? btn('hq', 'HQ', ` data-key="${esc(f.hq.key)}" data-name="${esc(f.hq.name)}"`) : ''}`
        + `${btn('drop', 'Remove')}</span></li>`;
    }).join('');
    return `<div class="friends">${rows ? `<ul class="people">${rows}</ul>` : '<p class="none">No friends yet.</p>'}`
      + `<p class="foot">Right-click a player’s name anywhere (over their car, in the chat, in Players or the standings) to add them. Follow puts the camera on their vehicle; HQ goes to look at theirs. Anyone can be followed or have their HQ looked at, friend or not: right-click their name, or use the buttons in Players and Rivals.</p></div>`;
  }
}
