import { allowed, sampleAt, type Switch, type Track, type Trains } from './trains';
import type { RailStation } from '../world/tiles';
import type { BeatEnd, BeatOrder } from './orders';

/**
 * A crewed train's beat (docs/crewtrains.html): the stretch of line a hired driver runs it up and down, calling at the
 * stations on it and turning round at each end. Worked out from the track in memory and nothing else, so it follows
 * the track: lay a station within reach, or take one up, and the beat changes with it.
 *
 * Whole line (the default, the user, 4 Nov 2026): every station on the line within reach, which is the county the
 * beat works from and the next one each way (three counties along the track at most), straight on through every
 * turnout. Custom: two stations of the player's within reach, and the way between them, over any turnout it needs.
 *
 * No three.js and no game state: a gate can ask it about any network.
 */

type Net = Trains['net'];

export interface BeatStop {
  /** The station as the county keeps it (a second track's platform reads as its own station). */
  st: RailStation;
  /** Its platform road, and the middle of the platform on it. */
  t: Track; s: number;
  name: string; cx: number; cz: number;
}

export interface Beat {
  /** The stations it calls at, from one end to the other. */
  stops: BeatStop[];
  ends: [BeatStop, BeatStop];
  /** Every turnout met head on between the ends, either way, and whether it is taken (passing loops left to the dispatcher). */
  choices: Map<string, boolean>;
  /** The counties the way between the ends runs through. */
  cells: [number, number][];
  /** Tiles from one end to the other. */
  length: number;
  custom: boolean;
  /** On double track (0.8.0): out along one track, back along the other, crossing over at each end. */
  double: boolean;
  /** The way between the ends as points every few tiles, in world tiles: what the region map draws. */
  line: { x: number; z: number }[];
}

/** What kind of train it is, for which stations it calls at and which track it may run on. */
export interface BeatKind { freight: boolean; rack: boolean }

/** Counties either way of the beat's own a beat may reach into. */
export const BEAT_REACH = 1;

const isRack = (t: Track): boolean => t.p.key.startsWith('rack:');
/** A station's passing loop, or one the player laid: the dispatcher's to take, never the beat's way. */
const loopish = (t: Track): boolean => t.p.kind === 'loop' || t.stations.some((s) => s.loop);
const goods = (st: RailStation): boolean => st.kind === 'goodsYard' || st.kind === 'harbourDepot';

/** Does a train of this kind call at this station? A freight at goods yards and harbour depots, a passenger train everywhere else. */
export function serves(k: BeatKind, st: RailStation): boolean {
  if (st.passing) return false;
  return k.freight ? goods(st) : !goods(st);
}

export const sameEnd = (a: BeatEnd, b: BeatEnd): boolean => a.cx === b.cx && a.cz === b.cz && a.name === b.name;
export const endOf = (s: BeatStop): BeatEnd => ({ cx: s.cx, cz: s.cz, name: s.name });

function inReach(home: [number, number], t: Track): boolean {
  return Math.max(Math.abs(t.w.cx - home[0]), Math.abs(t.w.cz - home[1])) <= BEAT_REACH;
}

/** May a beat of this kind run on this track at all? */
function usable(k: BeatKind, home: [number, number], t: Track): boolean {
  if (!inReach(home, t) || loopish(t)) return false;
  // a rack railway takes the cog engine and nothing else, and the cog engine runs nowhere else
  return isRack(t) === k.rack;
}

interface Seg { t: Track; s0: number; s1: number }

/**
 * Straight on from `loc` (no turnout taken) for as long as the track is usable: the stretches it runs over. Stops at
 * buffers, the edge of the cells in memory, out of reach, or onto track this kind of train may not run on.
 */
function straight(net: Net, k: BeatKind, home: [number, number], t: Track, s: number, dir: 1 | -1, anyWay = false): Seg[] {
  const out: Seg[] = [];
  for (let guard = 0; guard < 48; guard++) {
    // (anyWay: the line's extent, against a one-way track's way too: how far back the line runs behind a train on it)
    if (!anyWay && !allowed(t, s, dir)) break;
    const end = dir > 0 ? t.p.length : 0;
    out.push({ t, s0: s, s1: end });
    const nx = net.next(t, dir > 0);
    if (!nx || !usable(k, home, nx.t) || out.some((q) => q.t === nx.t)) break;
    t = nx.t; s = nx.s; dir = nx.dir;
  }
  return out;
}

/** The stations along stretches, in the order met, each once: every one (for the ends) and those this train calls at. */
function stationsOn(segs: Seg[]): BeatStop[] {
  const out: BeatStop[] = [];
  for (const g of segs) {
    const lo = Math.min(g.s0, g.s1), hi = Math.max(g.s0, g.s1), dir = g.s1 >= g.s0 ? 1 : -1;
    const here: { b: BeatStop; at: number }[] = [];
    for (const { st, loop } of g.t.stations) {
      if (loop || st.passing) continue;
      const mid = (st.s0 + st.s1) / 2;
      if (mid < lo - 1e-6 || mid > hi + 1e-6) continue;
      const real = st.of ?? st;
      if (out.some((b) => b.st === real) || here.some((h) => h.b.st === real)) continue;
      here.push({ b: { st: real, t: g.t, s: mid, name: real.name, cx: g.t.w.cx, cz: g.t.w.cz }, at: (mid - g.s0) * dir });
    }
    here.sort((a, b) => a.at - b.at);
    out.push(...here.map((h) => h.b));
  }
  return out;
}

/** Reverse a run of stretches: the same track the other way. */
const reversed = (segs: Seg[]): Seg[] => [...segs].reverse().map((g) => ({ t: g.t, s0: g.s1, s1: g.s0 }));

/**
 * The turnouts met head on along stretches travelled in order: one at the very end of a stretch leading onto the next
 * one's track is taken, every other passed straight by. Passing loops are left out: the dispatcher takes those.
 */
function choicesAlong(segs: Seg[], into: Map<string, boolean>): void {
  segs.forEach((g, i) => {
    const dir = g.s1 >= g.s0 ? 1 : -1;
    const nx = segs[i + 1];
    for (const sw of g.t.switches) {
      if (sw.dir !== dir || loopish(sw.to)) continue;
      const a = (sw.s - g.s0) * dir, len = (g.s1 - g.s0) * dir;
      if (a <= 1e-6 || a > len + 1e-6) continue;
      const take = !!nx && nx.t === sw.to && Math.abs(sw.s - g.s1) < 1e-3 && Math.abs(nx.s0 - sw.toS) < 1e-3;
      // (a turnout met twice, once taken: taken wins)
      into.set(sw.key, (into.get(sw.key) ?? false) || take);
    }
  });
}

/** Cut a run of stretches to the part between two points on it (each a track and an arc length). */
function between(segs: Seg[], a: { t: Track; s: number }, b: { t: Track; s: number }): Seg[] {
  const ia = segs.findIndex((g) => g.t === a.t && a.s >= Math.min(g.s0, g.s1) - 1e-6 && a.s <= Math.max(g.s0, g.s1) + 1e-6);
  const ib = segs.findIndex((g, i) => i >= ia && g.t === b.t && b.s >= Math.min(g.s0, g.s1) - 1e-6 && b.s <= Math.max(g.s0, g.s1) + 1e-6);
  if (ia < 0 || ib < 0) return [];
  const out = segs.slice(ia, ib + 1).map((g) => ({ ...g }));
  out[0].s0 = a.s;
  out[out.length - 1].s1 = b.s;
  return out;
}

function cellsOf(segs: Seg[]): [number, number][] {
  const out: [number, number][] = [];
  for (const g of segs) if (!out.some(([x, z]) => x === g.t.w.cx && z === g.t.w.cz)) out.push([g.t.w.cx, g.t.w.cz]);
  return out;
}

const lengthOf = (segs: Seg[]): number => segs.reduce((n, g) => n + Math.abs(g.s1 - g.s0), 0);

/**
 * The beat from the way out (ends[0] to ends[1]) and the way back: on single track the same stretches reversed; on
 * double track (0.8.0) the other track, its own way (the user, 4 Nov 2026: hired trains keep to the correct side).
 */
function build(segs: Seg[], stops: BeatStop[], ends: [BeatStop, BeatStop], custom: boolean, back: Seg[] | null = null): Beat {
  const choices = new Map<string, boolean>();
  choicesAlong(segs, choices);
  choicesAlong(back ?? reversed(segs), choices);
  const cells = cellsOf(segs);
  for (const c of cellsOf(back ?? [])) if (!cells.some(([x, z]) => x === c[0] && z === c[1])) cells.push(c);
  return { stops, ends, choices, cells, length: lengthOf(segs), custom, line: lineOf(segs), double: !!back };
}

/** The middle of a station's platform on this track (its own or a second track's stand-in), or null. */
function platformOn(t: Track, st: RailStation): number | null {
  for (const e of t.stations) if (!e.loop && (e.st.of ?? e.st) === st) return (e.st.s0 + e.st.s1) / 2;
  return null;
}

/** Double track: from one end's platform on the other track, straight on its way to the far end's platform there. */
function otherWay(net: Net, k: BeatKind, home: [number, number], from: BeatStop, to: BeatStop): Seg[] | null {
  const t = from.t.twin;
  const s = t ? platformOn(t, from.st) : null;
  if (!t || s === null || !t.p.oneWay) return null;
  const segs = straight(net, k, home, t, s, t.p.oneWay);
  const g = segs.find((q) => { const m = platformOn(q.t, to.st); return m !== null && m >= Math.min(q.s0, q.s1) - 1e-6 && m <= Math.max(q.s0, q.s1) + 1e-6; });
  if (!g) return null;
  const cut = between(segs, { t, s }, { t: g.t, s: platformOn(g.t, to.st)! });
  return cut.length ? cut : null;
}

/** Points along stretches every LINE_STEP tiles, ends included. */
const LINE_STEP = 6;
function lineOf(segs: Seg[]): { x: number; z: number }[] {
  const out: { x: number; z: number }[] = [];
  const p = { x: 0, y: 0, z: 0, ang: 0 };
  for (const g of segs) {
    const len = Math.abs(g.s1 - g.s0), dir = g.s1 >= g.s0 ? 1 : -1;
    for (let d = 0; d < len; d += LINE_STEP) { sampleAt(g.t, g.s0 + dir * d, p); out.push({ x: p.x, z: p.z }); }
  }
  const last = segs[segs.length - 1];
  if (last) { sampleAt(last.t, last.s1, p); out.push({ x: p.x, z: p.z }); }
  return out;
}

/** Why a beat can't be had here, in the player's words; or the beat. */
export type BeatResult = { beat: Beat; why: null } | { beat: null; why: string };

/**
 * The whole line within reach of `home`, through the point a train stands at (track and arc length): straight on both
 * ways, the outermost stations it calls at as the ends. A train with fewer than two to call at turns at the outermost
 * stations of any kind instead, calling at those two (a freight on a line with one goods yard still runs it).
 */
export function wholeLine(net: Net, k: BeatKind, home: [number, number], at: { t: Track; s: number }): BeatResult {
  const ow = at.t.p.oneWay;
  if (ow && !at.t.twin) return { beat: null, why: 'Put this one on the main line: a crossover is no place to start a beat' };
  if (!usable(k, home, at.t)) return { beat: null, why: 'Too far from the county it works from' };
  // (on double track the line's own way, and its extent back the other way)
  const fwd = straight(net, k, home, at.t, at.s, ow ?? 1);
  const back = straight(net, k, home, at.t, at.s, (ow ? -ow : -1) as 1 | -1, !!ow);
  // the whole stretch, one end to the other: back reversed, then forward
  const segs = [...reversed(back), ...fwd];
  const all = stationsOn(segs);
  const calls = all.filter((b) => serves(k, b.st));
  const pick = calls.length >= 2 ? calls : all;
  if (pick.length < 2) return { beat: null, why: all.length ? `Only ${all[0].name} within reach: a beat needs two stations` : 'No station within reach of this train' };
  const ends: [BeatStop, BeatStop] = [pick[0], pick[pick.length - 1]];
  const run = between(segs, ends[0], ends[1]);
  const stops = calls.length >= 2 ? calls : [ends[0], ...calls.filter((b) => b !== ends[0] && b !== ends[1]), ends[1]];
  if (!ow) {
    if (!run.some((g) => g.t.p.oneWay)) return { beat: build(run, stops, ends, false), why: null };
    // a branch's single track running onto a double-tracked main line (0.8.0): the way back found on its own, each track its way
    const back = shortest(net, k, home, ends[1], ends[0]);
    if (!back) return { beat: null, why: `No way back from ${ends[1].name} to ${ends[0].name} along the track within reach` };
    return { beat: build(run, stops, ends, false, back), why: null };
  }
  const ret = otherWay(net, k, home, ends[1], ends[0]);
  if (!ret) return { beat: null, why: `No way back from ${ends[1].name} along the other track within reach` };
  return { beat: build(run, stops, ends, false, ret), why: null };
}

/** Every station of the cells in memory within reach of `home` a train might name as an end (its platform road). */
export function stationsInReach(net: Net, k: BeatKind, home: [number, number]): BeatStop[] {
  const out: BeatStop[] = [];
  for (const t of net.tracks.values()) {
    if (!usable(k, home, t)) continue;
    for (const { st, loop } of t.stations) {
      const real = st.of ?? st;
      if (loop || st.passing || out.some((b) => b.st === real)) continue;
      out.push({ st: real, t, s: (st.s0 + st.s1) / 2, name: real.name, cx: t.w.cx, cz: t.w.cz });
    }
  }
  return out;
}

/**
 * Custom: the way from end a to end b over the track within reach, any turnout taken that leads there (the shortest,
 * by a search over the stretches between turnouts). The stations it calls at are the ones on that way, ends always.
 */
export function customBeat(net: Net, k: BeatKind, home: [number, number], a: BeatEnd, b: BeatEnd): BeatResult {
  const have = stationsInReach(net, k, home);
  const A = have.find((s) => sameEnd(endOf(s), a)), B = have.find((s) => sameEnd(endOf(s), b));
  if (!A || !B) return { beat: null, why: `${(A ? b : a).name} is not within reach of this beat` };
  if (A.st === B.st) return { beat: null, why: 'A beat needs two different stations' };
  const best = shortest(net, k, home, A, B);
  if (!best) return { beat: null, why: `No way along the track from ${A.name} to ${B.name} within reach` };
  const calls = stationsOn(best).filter((s) => s.st !== A.st && s.st !== B.st && serves(k, s.st));
  // double track somewhere on the way (0.8.0): the way back found on its own, keeping each track's way
  if (!best.some((g) => g.t.p.oneWay)) return { beat: build(best, [A, ...calls, B], [A, B], true), why: null };
  const back = shortest(net, k, home, B, A);
  if (!back) return { beat: null, why: `No way back from ${B.name} to ${A.name} along the track within reach` };
  return { beat: build(best, [A, ...calls, B], [A, B], true, back), why: null };
}

/** The shortest way from one station's platform to another's, from either track it stands on, either way. */
function shortest(net: Net, k: BeatKind, home: [number, number], A: BeatStop, B: BeatStop): Seg[] | null {
  let best: Seg[] | null = null, bestLen = Infinity;
  for (const t of [A.t, A.t.twin].filter((q): q is Track => !!q)) {
    const s = platformOn(t, A.st);
    if (s === null) continue;
    for (const dir of [1, -1] as const) {
      const found = search(net, k, home, t, s, dir, B, bestLen);
      if (found && lengthOf(found) < bestLen) { best = found; bestLen = lengthOf(found); }
    }
  }
  return best;
}

/** Depth-first over stretches between turnouts, shortest found kept: the stretches from (t, s, dir) to B's platform, or null. */
function search(net: Net, k: BeatKind, home: [number, number], t0: Track, s0: number, dir0: 1 | -1, B: BeatStop, cap: number): Seg[] | null {
  let best: Seg[] | null = null, bestLen = cap;
  const seen = new Set<string>();
  const go = (t: Track, s: number, dir: 1 | -1, path: Seg[], len: number, depth: number): void => {
    if (depth > 24 || len >= bestLen || !allowed(t, s, dir)) return;
    const key = `${t.key}|${dir}|${Math.round(s)}`;
    if (seen.has(key)) return;
    seen.add(key);
    const end = dir > 0 ? t.p.length : 0;
    // B on this track ahead (its platform, or on double track its platform on this track)
    const bs = platformOn(t, B.st);
    if (bs !== null && (bs - s) * dir >= 0) {
      const seg = { t, s0: s, s1: bs };
      const l = len + Math.abs(bs - s);
      if (l < bestLen) { bestLen = l; best = [...path, seg]; }
      seen.delete(key);
      return;
    }
    // every turnout ahead on this track that leads on to usable track, nearest first, and the end of the track
    const ahead: Switch[] = t.switches.filter((sw) => sw.dir === dir && (sw.s - s) * dir > 1e-6 && !loopish(sw.to) && usable(k, home, sw.to))
      .sort((p, q) => (p.s - s) * dir - (q.s - s) * dir);
    for (const sw of ahead) go(sw.to, sw.toS, sw.toDir, [...path, { t, s0: s, s1: sw.s }], len + Math.abs(sw.s - s), depth + 1);
    const nx = net.next(t, dir > 0);
    if (nx && usable(k, home, nx.t)) go(nx.t, nx.s, nx.dir, [...path, { t, s0: s, s1: end }], len + Math.abs(end - s), depth + 1);
    seen.delete(key);
  };
  go(t0, s0, dir0, [], 0, 0);
  return best;
}

/** The beat an order gives a train standing at `at`: Custom's ends when it has them (and they still make a beat), else the whole line. */
export function beatFor(net: Net, k: BeatKind, order: BeatOrder, at: { t: Track; s: number }): BeatResult & { fellBack?: string } {
  if (order.custom) {
    const c = customBeat(net, k, order.home, order.custom.a, order.custom.b);
    if (c.beat) return c;
    const w = wholeLine(net, k, order.home, at);
    return w.beat ? { ...w, fellBack: c.why } : c;
  }
  return wholeLine(net, k, order.home, at);
}
