import { Biome, DIRS, Flag, N, RailBit, idx, inB, type Arch, type Building, type BuildingKind, type Town, type World } from './tiles';
import { lotLevelOf, placeBuilding } from './growth';
import { SEAM_BAND } from './generate';
import { inShape, shapeOf } from './townShape';
import { insideCurve } from './curves';
import { KIND_SPEC } from './townKinds';
import { follyLot } from './scenery';
import { ERECT_MAX, ERECT_MAX_FLOORS, ERECT_MAX_SIDE } from '../../shared/erect';

/**
 * Blueprints (docs/blueprints.html): a building a fleet puts up from the plans of one it owns. The `erect` edit on
 * the county's log carries everything the copy is — its kind, the lot as it stands on the tiles (turned already), its
 * facing (the street side), storeys, model seed and style — and the game hours its site runs. Replayed, it makes a
 * real `Building` with `grownAt` set, so render/construction.ts opens a site on it with no new state, and the model
 * appears when the hours are up. Inside a town's square it joins the town; anywhere else it is countryside.
 *
 * Where it may stand is `erectProblem`: open ground with a road at the door, outside every town's traced border, or
 * inside a town the fleet holds (the holder predicate is the caller's: the game's territory, main.ts). The replay
 * checks only the ground, never the lines: a holding lost later takes nothing down.
 */

/** The edit's body: the lot's corner tile and its size on the tiles as turned, the facing (DIRS index: the street side). */
export interface ErectSpec {
  kind: BuildingKind;
  x: number; z: number; w: number; d: number;
  f: number;
  fl: number;
  seed: number;
  /** The copy's style, kept on the building when it stands outside a town or in a town of another style. */
  st?: Arch;
  solid: 0 | 1;
  /** Game hours the site runs (shared/erect.ts erectHours). */
  hrs: number;
}

/** The ruling spread of ground under a lot before it is too steep to build on, in steps (the station rule). */
const PAD_ROUGH = 3;

/** Every tile of the lot. */
function lotTiles(s: { x: number; z: number; w: number; d: number }): number[] {
  const out: number[] = [];
  for (let z = s.z; z < s.z + s.d; z++) for (let x = s.x; x < s.x + s.w; x++) out.push(idx(x, z));
  return out;
}

/** The tiles just outside the lot on its street side: where a road must run. */
export function doorTiles(s: { x: number; z: number; w: number; d: number; f: number }): [number, number][] {
  const [fx, fz] = DIRS[s.f & 3];
  const out: [number, number][] = [];
  if (fx !== 0) { const x = fx > 0 ? s.x + s.w : s.x - 1; for (let z = s.z; z < s.z + s.d; z++) out.push([x, z]); }
  else { const z = fz > 0 ? s.z + s.d : s.z - 1; for (let x = s.x; x < s.x + s.w; x++) out.push([x, z]); }
  return out;
}

/** Is there a street at the door? */
export function roadAtDoor(w: World, s: { x: number; z: number; w: number; d: number; f: number }): boolean {
  return doorTiles(s).some(([x, z]) => inB(x, z) && w.road[idx(x, z)] > 0 && !w.deckAxis[idx(x, z)]);
}

/** Constructions standing on this island (razed ones are gone from the count). */
export const erectedCount = (w: World): number => w.allBuildings.filter((b) => b.erected && !b.gone).length;

/**
 * The town whose lines a lot lies within, by the border the town-select traces (townShape.ts) or by its own ground
 * (`townId`): null for open country. A lot across a border counts as inside.
 */
export function townOfLot(w: World, s: { x: number; z: number; w: number; d: number }): Town | null {
  const tiles = lotTiles(s);
  for (const t of w.towns) {
    if (tiles.some((i) => w.townId[i] === t.id)) return t;
    const shape = shapeOf(w, t);
    if (tiles.some((i) => inShape(shape, i % N, Math.floor(i / N)))) return t;
  }
  return null;
}

/**
 * The town whose square or claimed ground holds the lot's middle: the one whose list the building goes on (the town
 * chunk mesher draws a town's buildings only within that box). Null puts it on the countryside list.
 */
export function townForLot(w: World, s: { x: number; z: number; w: number; d: number }): Town | null {
  const mx = Math.floor(s.x + s.w / 2), mz = Math.floor(s.z + s.d / 2);
  if (!inB(mx, mz)) return null;
  const i = idx(mx, mz);
  for (const t of w.towns) {
    if (mx >= t.x0 && mz >= t.z0 && mx < t.x0 + t.size && mz < t.z0 + t.size) return t;
    if (t.claims?.includes(i)) return t;
  }
  return null;
}

/**
 * Why a copy can't stand here, or null when it can. `holder` says whether the fleet holds a town (uncontested
 * territory, docs/territory.html): inside a town's lines only a holder builds. The ground is judged as the station
 * tool judges it, with a road wanted at the door.
 */
export function erectProblem(w: World, s: ErectSpec, holder: (t: Town) => boolean): string | null {
  if (s.w < 1 || s.d < 1 || s.w > ERECT_MAX_SIDE || s.d > ERECT_MAX_SIDE) return 'That lot is too big to build';
  if (s.fl < 1 || s.fl > ERECT_MAX_FLOORS) return 'That building is too tall to build';
  const band = w.kind === 'continent' ? SEAM_BAND : 3;
  if (s.x < band || s.z < band || s.x + s.w > N - band || s.z + s.d > N - band) return 'Too close to the county line: build further in';
  const tiles = lotTiles(s);
  let lo = Infinity, hi = -Infinity;
  for (const i of tiles) {
    if (w.biome[i] === Biome.Ocean || w.water[i] >= 0) return 'Not in the water';
    if (w.road[i] || w.deckAxis[i]) return 'Not on a road: pick the ground beside it';
    if (w.rail[i] & (RailBit.Track | RailBit.Pad | RailBit.Loop | RailBit.Deck | RailBit.Pier)) return 'Not on the railway';
    if (w.blocked[i]) return 'A building stands here';
    if (w.flags[i] & Flag.Field) return 'Not on the farm’s fields';
    if (w.flags[i] & Flag.Poi) return 'Something stands here already';
    if (w.portId[i] >= 0) return 'Not on harbour ground';
    if (w.feature[i]) return 'Not on the airfield, the quarry or the piste';
    if (w.boost[i]) return 'Not on a boost pad';
    if (insideCurve(w, i)) return 'Not inside a road’s bend';
    for (let q = 0; q < 4; q++) { const c = w.corners[i * 4 + q]; if (c < lo) lo = c; if (c > hi) hi = c; }
  }
  if (hi - lo > PAD_ROUGH) return 'Too steep: level it with the terrain tool (U) first';
  const x1 = s.x + s.w, z1 = s.z + s.d;
  if (w.allBuildings.some((b) => !b.gone && b.x < x1 && b.x + b.w > s.x && b.z < z1 && b.z + b.d > s.z)) return 'A building’s lot is here';
  for (const q of w.placed) {
    const o = follyLot(q);
    if (o ? o.x < x1 && o.x + o.w > s.x && o.z < z1 && o.z + o.d > s.z : q.x > s.x - 0.1 && q.x < x1 + 0.1 && q.z > s.z - 0.1 && q.z < z1 + 0.1) return 'Something placed is in the way: take it up first';
  }
  if (!roadAtDoor(w, s)) return 'No road at the door: build beside a street (R turns it)';
  const t = townOfLot(w, s);
  if (t && !holder(t)) return `Inside ${t.name}’s lines: only the town’s holder builds here`;
  if (erectedCount(w) >= ERECT_MAX) return `This island has all the works it can take (${ERECT_MAX})`;
  return null;
}

/** Told when a construction has been stood on an island (the game grants the deed and starts the clock on refunds). */
let onErected: ((w: World, b: Building, e: ErectSpec & { by?: string; at?: number }) => void) | null = null;
export function setErected(f: typeof onErected): void { onErected = f; }

/**
 * Apply an `erect` edit: the building stands at once, its site running from `at`. Only the ground is checked (a
 * replay onto ground that has changed under it, or online a lot another fleet took first, lays nothing and returns
 * no tiles); the lines and the holding were the click's business.
 */
export function applyErect(w: World, e: ErectSpec & { by?: string; at?: number }): number[] {
  if (e.w < 1 || e.d < 1 || e.w > ERECT_MAX_SIDE || e.d > ERECT_MAX_SIDE) return [];
  if (e.x < 0 || e.z < 0 || e.x + e.w > N || e.z + e.d > N) return [];
  const tiles = lotTiles(e);
  for (const i of tiles) {
    if (w.water[i] >= 0 || w.biome[i] === Biome.Ocean || w.road[i] || w.deckAxis[i] || w.blocked[i] || w.portId[i] >= 0 || w.feature[i]) return [];
    if (w.rail[i] & (RailBit.Track | RailBit.Pad | RailBit.Loop | RailBit.Deck | RailBit.Pier)) return [];
  }
  const x1 = e.x + e.w, z1 = e.z + e.d;
  if (w.allBuildings.some((b) => !b.gone && b.x < x1 && b.x + b.w > e.x && b.z < z1 && b.z + b.d > e.z)) return [];
  const t = townForLot(w, e);
  const level = lotLevelOf(w, e.x, e.z, e.w, e.d);
  const b: Building = {
    kind: e.kind, x: e.x, z: e.z, w: e.w, d: e.d, facing: e.f & 3, floors: Math.max(1, Math.round(e.fl)), seed: e.seed >>> 0,
    solid: e.solid === 1, level, uid: w.allBuildings.length, grownAt: e.at ?? 0, buildHours: e.hrs, erected: true,
  };
  if (e.by) b.by = e.by;
  if (e.st && (!t || e.st !== t.style)) b.style = e.st;
  const lot = KIND_SPEC[e.kind]?.lot;
  const out = placeBuilding(w, t, b, lot ?? -1);
  onErected?.(w, b, e);
  return out;
}
