  ruinWall(k, r, cx - cw / 2, nz0 + t / 2, cx + cw / 2, nz0 + t / 2, ch, t, cs, [[0.4, 0.6, 0.3]], 0.3);
  // the tower, broken off short: a solid base, corner piers standing to different heights, dark belfry openings
