  k.tagged(Vis.Always, () => k.glowBox(cx, 0.04, tz + TW / 2 - 0.02, 0.06, 0.08, 0.04, hex(0x3a5a52), [20, 29, 0.9], hex(0x9fe8d8)));
  // the bell, fallen out of the belfry and green with the sea, and blocks of the tower round it
  const bx = cx - cw / 2 - 0.3, bz = tz - 0.1, BRONZE = hex(0x5f8a72);
