  // the churchyard: leaning headstones and a cross
  for (let i = 0; i < 5; i++) {
    const gx = cx - cw / 2 - 0.35 - (i % 2) * 0.3, gz = nz0 + 0.35 + Math.floor(i / 2) * 0.3;
    k.box(gx + (r() - 0.5) * 0.06, 0, gz, 0.11, 0.1 + r() * 0.06, 0.03, STONE_DARK, MOSS);
  }
  k.box(cx - cw / 2 - 0.65, 0, nz0 + 1.05, 0.03, 0.24, 0.03, STONE_DARK);
  k.box(cx - cw / 2 - 0.65, 0.16, nz0 + 1.05, 0.12, 0.03, 0.03, STONE_DARK);
