import { hex, scale, type RGB } from '../../../world/biomes';
import type { RegionBuildingKind } from '../../../world/tiles';
import { DARK, GLASS, METAL, TAU, WARM_GLOW, WHITE, win, type Draw, type Kit } from '../kit';

/**
 * The Moors: the distillery with its pagoda kilns, the croft, the bothy, the cairn field on a
 * summit, and the wonder, the castle, a ruined keep and curtain wall on a crag.
 */

const GRANITE = hex(0x8e8c86), GRANITE_DK = hex(0x6e6c66), SLATE = hex(0x4a5058), THATCH = hex(0x9c8558);
const WHITEWASH = hex(0xf2f0e8), PEAT = hex(0x3e2e22), TIMBER = hex(0x5a4432), TURF = hex(0x6f7a48);

/** A stone gable end with a chimney on it. */
function chimney(k: Kit, x: number, y: number, z: number, col: RGB): void {
  k.box(x, y, z, 0.08, 0.1, 0.08, col);
  k.box(x, y + 0.1, z, 0.1, 0.015, 0.1, scale(col, 0.85));
}

// ---- 1. distillery -----------------------------------------------------------------------------

/** A malting kiln's pagoda roof: a flared hip, a neck, and a little cap. */
function pagoda(k: Kit, x: number, y: number, z: number, s: number): void {
  k.hip(x, y, z, s * 1.3, s * 0.28, s * 1.3, SLATE);
  k.box(x, y + s * 0.2, z, s * 0.36, s * 0.26, s * 0.36, WHITEWASH);
  k.box(x, y + s * 0.3, z, s * 0.37, s * 0.1, s * 0.37, DARK);
  k.hip(x, y + s * 0.46, z, s * 0.6, s * 0.26, s * 0.6, SLATE);
  k.box(x, y + s * 0.7, z, 0.012, s * 0.1, 0.012, METAL);
}

const distillery: Draw = (k, W, D, b, r) => {
  // the long malt barn along the back
  const bz = -D / 2 + 0.4, bw = W - 0.25, h = 0.42;
  k.box(0, 0, bz, bw, h, 0.6, WHITEWASH);
  k.gable(0, h, bz, bw + 0.06, 0.24, 0.68, SLATE, WHITEWASH);
  for (let i = 0; i < 5; i++) win(k, b, r, -0.7 + i * 0.35, 0.18, bz + 0.3, 0.08, 0.12, 1);
  // two square kilns rising through the roof with their pagoda tops
  for (const kx of [-0.45, 0.2]) {
    k.box(kx, h, bz, 0.34, 0.42, 0.34, WHITEWASH);
    pagoda(k, kx, h + 0.42, bz, 0.42);
  }
  // the stillhouse in front, its tall windows showing the copper stills
  const sx = 0.35, sz = 0.35;
  k.box(sx, 0, sz, 0.9, 0.36, 0.6, WHITEWASH);
  k.gable(sx, 0.36, sz, 0.96, 0.2, 0.66, SLATE, WHITEWASH, true);
  for (let i = 0; i < 2; i++) k.pane(sx - 0.2 + i * 0.4, 0.06, sz + 0.3, 0.22, 0.24, 1, hex(0xb8743a), [16.5, 22, 1.4], WARM_GLOW);
  win(k, b, r, sx + 0.45, 0.1, sz, 0.16, 0.14, 0);
  // the painted name board along the barn
  k.box(-0.35, 0.3, bz + 0.305, 0.7, 0.08, 0.01, DARK);
  k.box(-0.35, 0.33, bz + 0.314, 0.56, 0.02, 0.004, hex(0xe8d27a));
  // the stack
  k.box(W / 2 - 0.18, 0, -D / 2 + 0.18, 0.16, 1.25, 0.16, hex(0x8a5a44));
  k.box(W / 2 - 0.18, 1.25, -D / 2 + 0.18, 0.2, 0.05, 0.2, DARK);
  // casks in the yard and a door
  k.box(-0.3, 0, sz + 0.06, 0.2, 0.26, 0.02, TIMBER);
  const cask = hex(0x8a5a34);
  for (let i = 0; i < 5; i++) {
    const cx = -0.8 + (i % 3) * 0.16, cz = 0.5 + Math.floor(i / 3) * 0.16;
    k.cyl(cx, 0, cz, 0.065, 0.14, cask, 8, scale(cask, 0.85));
    k.cyl(cx, 0.03, cz, 0.068, 0.015, DARK, 8);
    k.cyl(cx, 0.1, cz, 0.068, 0.015, DARK, 8);
  }
  // a peat heap for the kilns
  k.box(-0.75, 0, 0.05, 0.32, 0.1, 0.24, PEAT);
  k.box(-0.75, 0.1, 0.05, 0.22, 0.06, 0.16, scale(PEAT, 1.2));
  k.glowBox(sx - 0.45, 0.28, sz + 0.2, 0.04, 0.05, 0.04, DARK, [17, 23, 1.5], WARM_GLOW);
};

// ---- 2. croft ----------------------------------------------------------------------------------

const croft: Draw = (k, W, D, b, r) => {
  const stone = scale(GRANITE, 0.95 + r() * 0.1), x0 = -0.08, z0 = -0.08, w = 0.6, d = 0.34, h = 0.18;
  k.box(x0, 0, z0, w, h, d, stone);
  // the thatch, roped down with stones along the eaves
  k.gable(x0, h, z0, w + 0.06, 0.2, d + 0.1, THATCH, stone);
  k.box(x0, h + 0.18, z0, w + 0.04, 0.03, 0.05, scale(THATCH, 0.8));
  for (let i = 0; i < 5; i++) for (const s of [-1, 1]) k.box(x0 - w / 2 + 0.06 + i * 0.12, h - 0.03, z0 + s * (d / 2 + 0.05), 0.03, 0.03, 0.02, GRANITE_DK);
  for (const s of [-1, 1]) chimney(k, x0 + s * (w / 2 - 0.02), h + 0.08, z0, stone);
  k.box(x0 - 0.1, 0, z0 + d / 2 + 0.005, 0.08, 0.13, 0.01, hex(0x2f5a6b));
  win(k, b, r, x0 + 0.12, 0.07, z0 + d / 2, 0.08, 0.06, 1);
  // the lean-to byre, turf-roofed
  const bx = x0 + w / 2 + 0.12;
  k.box(bx, 0, z0, 0.24, 0.12, d - 0.04, scale(stone, 0.92));
  k.quad([bx - 0.12, h - 0.01, z0 - d / 2], [bx - 0.12, h - 0.01, z0 + d / 2], [bx + 0.14, 0.12, z0 + d / 2], [bx + 0.14, 0.12, z0 - d / 2], TURF, [bx, 0, z0]);
  k.box(bx, 0, z0 + d / 2 - 0.015, 0.1, 0.09, 0.01, TIMBER);
  // the peat stack, a kail yard wall, a washing line
  for (let i = 0; i < 3; i++) k.box(-W / 2 + 0.16, i * 0.05, D / 2 - 0.22, 0.2 - i * 0.04, 0.05, 0.16 - i * 0.03, i % 2 ? scale(PEAT, 1.2) : PEAT);
  k.box(0.1, 0, D / 2 - 0.06, 0.6, 0.06, 0.05, GRANITE_DK);
  k.box(0.38, 0, D / 2 - 0.2, 0.05, 0.06, 0.3, GRANITE_DK);
  for (const lx of [-0.42, -0.12]) k.box(lx, 0, D / 2 - 0.36, 0.015, 0.16, 0.015, TIMBER);
  k.box(-0.27, 0.15, D / 2 - 0.36, 0.3, 0.004, 0.004, WHITE);
  k.box(-0.3, 0.1, D / 2 - 0.36, 0.06, 0.05, 0.004, hex(0x3f6b9a));
};

// ---- 3. bothy ----------------------------------------------------------------------------------

const bothy: Draw = (k, _W, _D, _b, r) => {
  const stone = scale(GRANITE_DK, 0.95 + r() * 0.1);
  k.box(0, 0, -0.04, 0.4, 0.15, 0.3, stone);
  k.gable(0, 0.15, -0.04, 0.44, 0.13, 0.36, SLATE, stone);
  chimney(k, 0.18, 0.2, -0.04, stone);
  k.box(-0.06, 0, 0.115, 0.08, 0.12, 0.01, hex(0x7a2e2a));
  k.box(0.1, 0.07, 0.115, 0.05, 0.04, 0.01, DARK);
  // a bit of drystone shelter wall and scattered rocks
  k.box(-0.3, 0, 0.1, 0.05, 0.08, 0.4, GRANITE);
  k.box(-0.18, 0, 0.3, 0.3, 0.07, 0.05, GRANITE);
  for (let i = 0; i < 5; i++) {
    const a = r() * TAU, d = 0.32 + r() * 0.12;
    k.box(Math.cos(a) * d, 0, Math.sin(a) * d, 0.05 + r() * 0.05, 0.03 + r() * 0.03, 0.05 + r() * 0.04, GRANITE);
  }
};

// ---- 4. cairn field ----------------------------------------------------------------------------

/** A heap of stones, stacked smaller as it rises. */
function cairn(k: Kit, x: number, z: number, s: number, r: () => number): void {
  const c = scale(GRANITE, 0.85 + r() * 0.3), rad = 0.1 * s, h = 0.12 * s + r() * 0.1 * s;
  k.cyl(x, 0, z, rad, 0.04 * s, scale(c, 0.9), 6);
  k.cone(x, 0.04 * s, z, rad * 0.95, h, c, 6);
  for (let i = 0; i < 3; i++) {
    const a = r() * TAU;
    k.box(x + Math.cos(a) * rad * 0.8, r() * h * 0.5, z + Math.sin(a) * rad * 0.8, 0.04 * s, 0.03 * s, 0.035 * s, scale(c, 0.8 + r() * 0.4));
  }
  k.box(x, 0.04 * s + h * 0.8, z, 0.035 * s, 0.05 * s, 0.03 * s, scale(GRANITE, 1.15));
}

const cairnField: Draw = (k, W, D, _b, r) => {
  // the summit cairn: a great tapering heap with a trig pillar beside it
  k.cyl(0, 0, 0, 0.45, 0.14, GRANITE_DK, 9);
  k.cone(0, 0.14, 0, 0.44, 0.55, GRANITE, 9);
  for (let i = 0; i < 10; i++) {
    const a = r() * TAU, d = 0.25 + r() * 0.2;
    k.box(Math.cos(a) * d * 0.9, r() * 0.2, Math.sin(a) * d * 0.9, 0.09, 0.07, 0.08, scale(GRANITE_DK, 0.9 + r() * 0.3));
  }
  k.box(0.66, 0, 0.3, 0.09, 0.3, 0.09, WHITEWASH);
  k.box(0.66, 0.3, 0.3, 0.1, 0.02, 0.1, scale(WHITEWASH, 0.9));
  // walkers' cairns scattered over the top
  let placed = 0;
  for (let i = 0; i < 60 && placed < 22; i++) {
    const x = (r() - 0.5) * (W - 0.3), z = (r() - 0.5) * (D - 0.3);
    if (Math.hypot(x, z) < 0.65) continue;
    cairn(k, x, z, 0.6 + r() * 0.8, r);
    placed++;
  }
  // bare rock breaking through the heath
  for (let i = 0; i < 6; i++) {
    const x = (r() - 0.5) * (W - 0.4), z = (r() - 0.5) * (D - 0.4);
    if (Math.hypot(x, z) < 0.7) continue;
    k.box(x, 0, z, 0.2 + r() * 0.25, 0.05, 0.15 + r() * 0.2, scale(GRANITE_DK, 0.8), hex(0x6a6a50));
  }
};

// ---- 5. the castle (wonder) --------------------------------------------------------------------

const castle: Draw = (k, _W, D, _b, r) => {
  const stone = hex(0x7e7b74), dark = hex(0x62605a), top = hex(0x7a7f68), rock = hex(0x5e5a54);
  const e = 5.2, wh = 1.0, wt = 0.4;
  // the crag breaking out below the walls
  for (let i = 0; i < 36; i++) {
    const side = i % 4, u = -6 + ((i >> 2) + r()) * (12 / 9), o = 5.9 + r() * 0.5;
    const [x, z] = side === 0 ? [u, -o] : side === 1 ? [o, u] : side === 2 ? [-o, u] : [u, o];
    if (side === 3 && Math.abs(x) < 1.8) continue;
    const g = Math.max(-3, Math.min(0, k.ground(x, z))), h = 0.35 + r() * 0.5, w = 0.6 + r() * 0.6, d = 0.6 + r() * 0.6;
    const c = scale(rock, 0.75 + r() * 0.3);
    k.box(x, g - 0.3, z, w, h + 0.3 - g, d, c, scale(c, 1.1));
    k.box(x + (r() - 0.5) * w * 0.4, h, z + (r() - 0.5) * d * 0.4, w * 0.55, 0.12 + r() * 0.25, d * 0.55, scale(c, 1.08), hex(0x6a7050));
  }
  /** A run of curtain wall from a to b along one axis, with gaps where it has fallen. */
  const run = (ax: number, az: number, bx: number, bz: number, breaks: [number, number][]) => {
    const alongX = az === bz, len = Math.abs(alongX ? bx - ax : bz - az), n = Math.round(len / 0.3);
    const at = (t: number): [number, number] => [ax + (bx - ax) * t, az + (bz - az) * t];
    // walls as a few long pieces between the breaks
    const cuts = [0, ...breaks.flat(), 1];
    for (let c = 0; c < cuts.length - 1; c++) {
      const t0 = cuts[c], t1 = cuts[c + 1], broken = c % 2 === 1;
      const [mx, mz] = at((t0 + t1) / 2), l = (t1 - t0) * len;
      if (!broken) k.box(mx, 0, mz, alongX ? l : wt, wh, alongX ? wt : l, stone, top);
      else {
        // a breach: a rubble slope and a jagged stump either side
        k.box(mx, 0, mz, alongX ? l : wt + 0.3, 0.18, alongX ? wt + 0.3 : l, dark, top);
        for (const tt of [t0, t1]) {
          const [sx, sz] = at(tt), h = 0.5 + r() * 0.3, o = (tt === t0 ? 1 : -1) * 0.12;
          k.box(sx + (alongX ? o : 0), 0, sz + (alongX ? 0 : o), alongX ? 0.24 : wt, h, alongX ? wt : 0.24, stone, top);
        }
        for (let i = 0; i < 4; i++) {
          const [px, pz] = at(t0 + (t1 - t0) * r());
          k.box(px + (r() - 0.5) * 0.6, 0.1, pz + (r() - 0.5) * 0.6, 0.14, 0.1, 0.12, stone);
        }
      }
    }
    // merlons, some long gone
    for (let i = 0; i < n; i++) {
      const t = (i + 0.5) / n;
      if (cuts.some((c, j) => j % 2 === 1 && j < cuts.length - 1 && t > c - 0.03 && t < cuts[j + 1] + 0.03) || r() < 0.3) continue;
      const [x, z] = at(t), o = alongX ? (az > 0 ? 1 : -1) : (ax > 0 ? 1 : -1);
      k.box(x + (alongX ? 0 : o * 0.14), wh, z + (alongX ? o * 0.14 : 0), alongX ? 0.14 : 0.1, 0.14, alongX ? 0.1 : 0.14, stone);
    }
  };
  run(-e, -e, e, -e, [[0.3, 0.42]]);
  run(-e, -e, -e, e, [[0.55, 0.66]]);
  run(e, -e, e, e, []);
  run(-e, e, -1.3, e, []);
  run(1.3, e, e, e, [[0.4, 0.62]]);
  // corner towers; the north-east one a broken stump
  for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
    const x = sx * e, z = sz * e, ruined = sx > 0 && sz < 0, h = ruined ? 1.05 : 1.55;
    k.cyl(x, 0, z, 0.75, h, stone, 10, top);
    if (ruined) {
      for (let i = 0; i < 5; i++) {
        const a = Math.PI * 0.6 + i * 0.35;
        k.box(x + Math.cos(a) * 0.62, h, z + Math.sin(a) * 0.62, 0.22, 0.12 + i * 0.1, 0.22, stone);
      }
      for (let i = 0; i < 6; i++) k.box(x + 0.7 + r() * 0.6, 0, z - 0.5 + r() * 1.2, 0.18, 0.12, 0.16, dark);
    } else {
      k.cyl(x, h, z, 0.8, 0.08, dark, 10);
      for (let i = 0; i < 8; i++) {
        if (r() < 0.25) continue;
        const a = (i / 8) * TAU;
        k.box(x + Math.cos(a) * 0.7, h + 0.08, z + Math.sin(a) * 0.7, 0.18, 0.16, 0.18, stone);
      }
      for (let i = 0; i < 3; i++) {
        const a = (sz > 0 ? 0.5 : -0.5) * Math.PI + (i - 1) * 0.7;
        k.box(x + Math.cos(a) * 0.76, 0.5 + i * 0.2, z + Math.sin(a) * 0.76, 0.04, 0.16, 0.04, hex(0x1e1e1e));
      }
    }
  }
  // the gatehouse: two drum towers with the arch and a raised portcullis between them
  for (const sx of [-1, 1]) {
    k.cyl(sx * 1.25, 0, e + 0.1, 0.6, 1.7, stone, 10, top);
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * TAU;
      if (i === (sx > 0 ? 1 : 4)) continue;
      k.box(sx * 1.25 + Math.cos(a) * 0.52, 1.7, e + 0.1 + Math.sin(a) * 0.52, 0.16, 0.15, 0.16, stone);
    }
    k.box(sx * 1.25, 0.7, e + 0.7, 0.04, 0.2, 0.02, hex(0x1e1e1e));
    k.box(sx * 0.7, 0, e, 0.12, 0.8, 0.9, dark);
  }
  k.box(0, 0.8, e, 1.5, 0.75, 0.9, stone, top);
  k.box(0, 0.72, e + 0.46, 1.3, 0.08, 0.02, dark);
  for (let i = 0; i < 6; i++) k.box(-0.5 + i * 0.2, 0.62, e + 0.4, 0.025, 0.2, 0.025, hex(0x2a2a2a));
  for (let i = 0; i < 4; i++) k.box(-0.45 + i * 0.3, 1.55, e + 0.32, 0.14, 0.14, 0.12, stone);
  // the causeway out of the gate, over whatever water or bog lies below
  for (let z = e + 0.6; z < D / 2 + 3; z += 0.8) {
    const g = Math.max(-2.5, Math.min(-0.3, k.ground(0, z + 0.4) - 0.3));
    k.box(0, g, z + 0.4, 1.3, 0.04 - g, 0.8, dark, hex(0x7e7a70));
    for (const sx of [-0.62, 0.62]) k.box(sx, 0.04, z + 0.4, 0.08, 0.12, 0.8, stone);
  }
  // the keep: roofless, one corner fallen, one window lit
  const kx = -1.4, kz = -2.2, kw = 3.0, kd = 2.6, kh = 2.7;
  k.box(kx, 0, kz, kw, 1.9, kd, stone, top);
  k.box(kx, 1.9, kz - kd / 4, kw, kh - 1.9, kd / 2, stone, dark);
  k.box(kx - kw / 4, 1.9, kz + kd / 4, kw / 2, kh - 1.9, kd / 2, stone, dark);
  k.box(kx + kw / 4 - 0.25, 1.9, kz + kd / 4 - 0.2, kw / 2 - 0.5, 0.35, kd / 2 - 0.4, stone, dark);
  for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1]]) k.box(kx + sx * (kw / 2 - 0.2), kh, kz + sz * (kd / 2 - 0.2), 0.45, 0.35, 0.45, stone, top);
  for (let i = 0; i < 6; i++) k.box(kx - kw / 2 + 0.2 + i * 0.26, kh, kz - kd / 2 + 0.06, 0.14, 0.16, 0.12, stone);
  for (let i = 0; i < 3; i++) k.box(kx + kw / 2 - 0.3 + r() * 0.2, 1.9 + i * 0.12, kz + kd / 2 - 0.2 - i * 0.3, 0.3, 0.12, 0.3, dark);
  for (let i = 0; i < 7; i++) k.box(kx + 1.2 + r() * 1.0, 0, kz + kd / 2 + 0.2 + r() * 0.8, 0.2, 0.12 + r() * 0.1, 0.18, dark);
  for (const fy of [0.5, 1.2, 2.1]) {
    for (let i = 0; i < 3; i++) {
      const wx = kx - 0.9 + i * 0.9;
      if (fy === 2.1 && i === 2) continue;
      if (fy === 1.2 && i === 0) k.pane(wx, fy, kz + kd / 2, 0.12, 0.26, 1, hex(0x1e1e1e), [17.5, 30, 1.6], WARM_GLOW);
      else k.box(wx, fy, kz + kd / 2 + 0.005, fy > 1 ? 0.12 : 0.05, fy > 1 ? 0.26 : 0.2, 0.01, hex(0x1e1e1e));
    }
    k.box(kx + kw / 2 + 0.005, fy, kz, 0.01, 0.22, 0.06, hex(0x1e1e1e));
  }
  k.box(kx, 0, kz + kd / 2 + 0.25, 0.5, 0.3, 0.5, stone, top);
  k.box(kx, 0.3, kz + kd / 2 + 0.01, 0.22, 0.34, 0.02, hex(0x1e1e1e));
  // the great hall: four roofless walls and one gable standing
  const hx = 2.9, hz = -3.2, hw = 2.4, hd = 1.3, hh = 0.7;
  for (const s of [-1, 1]) {
    k.box(hx, 0, hz + s * hd / 2, hw, s > 0 ? hh * 0.7 : hh, 0.14, stone, top);
    k.box(hx + s * hw / 2, 0, hz, 0.14, hh, hd, stone, top);
  }
  k.tri([hx - hw / 2 - 0.07, hh, hz - hd / 2], [hx - hw / 2 - 0.07, hh, hz + hd / 2], [hx - hw / 2 - 0.07, hh + 0.5, hz], stone, [hx, 0.5, hz]);
  k.tri([hx - hw / 2 + 0.07, hh, hz - hd / 2], [hx - hw / 2 + 0.07, hh, hz + hd / 2], [hx - hw / 2 + 0.07, hh + 0.5, hz], stone, [hx - 5, 0.5, hz]);
  for (let i = 0; i < 3; i++) k.box(hx - 0.7 + i * 0.7, 0.3, hz + hd / 2 + 0.075, 0.14, 0.28, 0.01, hex(0x1e1e1e));
  // a well, rubble and nettles in the bailey
  k.cyl(1.6, 0, 1.6, 0.26, 0.2, stone, 9, hex(0x1e2a2e));
  for (let i = 0; i < 10; i++) {
    const x = -4 + r() * 8, z = -0.5 + r() * 4;
    if (Math.abs(x) < 1 && z > 2) continue;
    k.box(x, 0, z, 0.12 + r() * 0.12, 0.06 + r() * 0.06, 0.12 + r() * 0.1, r() < 0.5 ? dark : hex(0x5f6e3e));
  }
  void [GLASS, WHITE];
};

export const MOORS_DRAW: Partial<Record<RegionBuildingKind, Draw>> = {
  distillery, croft, bothy, cairnField, castle,
};
