/** At most this many chains stand at once, and a town that has just been asked waits this many days. */
const MAX_OPEN = 3, TOWN_COOLDOWN = 2;
/**
 * The whole-chain deadline: the fit estimate of every step, times this, and never less than a day.
 * It is generous on purpose — the deadline is there so a chain can lapse and be replaced, not to hurry
 * anyone; a step's own time limit does the hurrying.
 */
const DEADLINE_SLACK = 2.5, MIN_HOURS = 24;
/** The purse on the last drop, as a share of what the steps paid between them. */
const PURSE_SHARE = 0.4;

/** What the request system needs from the game around it. */
interface RequestHost {
  /** Game hours since the world began. */
  hours(): number;
  /** The islands whose towns may ask. */
  resident(): World[];
  /** Where the player is now, which is what reach is measured from. */
  at(): Place | null;
  /** The vehicle in the player's hands. */
  def(): VehicleDef;
  /** How far along the player is. */
  progress(): Progress;
  /** A town's plain name and books. */
  announce(title: string, body: string): void;
  /** A town is asking: the mayor's letter, with Accept and Not now. */
  ask(r: Request): void;
  /** Pay the purse and credit the town. */
  reward(r: Request, purse: number): void;
  /** Do what the chain promised. Returns false when the town could not, which is not an error. */
  effect(r: Request): boolean;
  /** Something changed: the board should redraw. */
  changed(): void;
}

export class Requests {
  /** Every chain the player can see: offered, taken, and the last few that went. */
  list: Request[] = [];
  /** The day each town last asked, keyed "cx,cz#id". */
  private asked = new Map<string, number>();
  private nextId = 1;
  private lastDay = -1;
  private history: string[] = [];

  constructor(private host: RequestHost, private cargo: CargoSystem) {}

  /** The chains standing now: what the board lists. */
  get open(): Request[] { return this.list.filter((r) => r.state === 'offered' || r.state === 'taken'); }
  /** The one being run, if any. One at a time, so the board always has a subject. */
  get taken(): Request | null { return this.list.find((r) => r.state === 'taken') ?? null; }
  /** The last few lines about chains that finished or lapsed. */
  get log(): string[] { return this.history; }

  /** Start again: a new world, or a load. */
  clear(): void {
    for (const r of this.list) this.dropLoads(r);
    this.list = [];
    this.asked.clear();
    this.history = [];
    this.lastDay = -1;
    this.nextId = 1;
  }

  // ---- the daily roll --------------------------------------------------------------------------

  /**
   * One tick. The day turning rolls each resident town for a chain; the clock on a taken chain runs
   * whatever the player is doing, and an offered chain that nobody took goes at the end of its day.
   */
  update(): void {
    const hours = this.host.hours();
    const day = Math.floor(hours / 24);
    for (const r of this.list) {
      if (r.state !== 'taken' && r.state !== 'offered') continue;
      if (hours < r.due) continue;
      this.lapse(r);
    }
    if (day === this.lastDay) return;
    this.lastDay = day;
    this.roll(day, hours);
  }

  private roll(day: number, hours: number): void {
    if (this.open.length >= MAX_OPEN) return;
    const stage = stageOf(this.host.progress());
    const at = this.host.at();
    if (!at) return;
    for (const w of this.host.resident()) {
      for (const t of w.towns) {
        if (this.open.length >= MAX_OPEN) return;
        const key = `${w.cx},${w.cz}#${t.id}`;
        if (day - (this.asked.get(key) ?? -99) < TOWN_COOLDOWN) continue;
        if (this.open.some((r) => r.town === plain(t))) continue;
        const h = hashString(`${w.seed}|request|${key}|${day}`);
        // not every town asks every day: about one in three that could
        if (h % 3 !== 0) continue;
        const r = this.make(w, t, stage, h, hours, at);
        if (!r) continue;
        this.asked.set(key, day);
        this.list.push(r);
        this.host.ask(r);
        this.host.changed();
        return;   // one new ask a day, so the board never fills at once
      }
    }
  }

  /** Fill a template for this town, or null when none of them fits what the town has. */
  private make(w: World, t: Town, stage: number, h: number, hours: number, at: Place, only?: string): Request | null {
    const blight = t.buildings.some((b) => b.derelict && !b.gone);
    const bag = TEMPLATES.filter((tp) => tp.stage <= stage
      && (!only || tp.kind === only)
      && (!tp.needsBlight || blight)
      && (!tp.needsPort || w.ports.some((p) => p.town === t.id))
      && (!tp.needsGraduation || t.kind !== 'mega'));
    if (!bag.length) return null;
    const def = this.host.def();
    // walk the bag from the hash, hardest first so a late player sees the late chains
    const order = [...bag].sort((a, b) => b.stage - a.stage || a.kind.localeCompare(b.kind));
    const start = h % order.length;
    for (let k = 0; k < order.length; k++) {
      const tp = order[(start + k) % order.length];
      const steps = this.fill(tp, w, t, def, at);
      if (!steps) continue;
      const paid = steps.reduce((s, q) => s + q.value, 0);
      const seconds = steps.reduce((s, q) => s + fitOf(def, at, q).seconds, 0);
      return {
        id: this.nextId++, kind: tp.kind, title: tp.title,
        line: tp.lines[h % tp.lines.length],
        town: plain(t), cell: [w.cx, w.cz], townId: t.id,
        steps, step: 0, posted: hours,
        due: hours + Math.max(MIN_HOURS, (seconds * DEADLINE_SLACK) / SECONDS_PER_HOUR),
        reward: Math.max(40, Math.round((paid * PURSE_SHARE) / 10) * 10),
        effect: tp.effect, effectLine: tp.effectLine, state: 'offered', colour: tp.colour, stage: tp.stage,
      };
    }
    return null;
  }

  /** Every step of a template filled from this town's own sites, or null if any one of them cannot be. */
  private fill(tp: Template, w: World, t: Town, def: VehicleDef, at: Place): Step[] | null {
    const out: Step[] = [];
    const used = new Set<Site>();
    for (const spec of tp.steps) {
      const step = this.fillStep(spec, w, t, def, at, used);
      if (!step) return null;
      used.add(step.from);
      used.add(step.to);
      out.push(step);
    }
    return out;
  }

  private fillStep(spec: StepSpec, w: World, t: Town, def: VehicleDef, at: Place, used: Set<Site>): Step | null {
    const mid = { x: w.ox + t.x0 + t.size / 2, z: w.oz + t.z0 + t.size / 2 };
    const inTown = (s: Site) => s.w === w && s.lx >= t.x0 - 4 && s.lx <= t.x0 + t.size + 4 && s.lz >= t.z0 - 4 && s.lz <= t.z0 + t.size + 4;
    for (const id of spec.types) {
      const type = cargoById(id);
      if (!type) continue;
      let froms = this.cargo.sitesOfKinds(type.from);
      let tos = this.cargo.sitesOfKinds(type.to);
      if (spec.fromKinds) froms = froms.filter((s) => spec.fromKinds!.includes(s.kind as string));
      if (spec.toKinds) tos = tos.filter((s) => spec.toKinds!.includes(s.kind as string));
      if (spec.fromTown) froms = froms.filter(inTown);
      if (spec.toTown) tos = tos.filter(inTown);
      if (!spec.fromTown && !spec.toTown) {
        // an end of the chain still has to be this town's business: keep it near
        froms = froms.filter((s) => Math.hypot(s.x - mid.x, s.z - mid.z) < 110);
        tos = tos.filter((s) => Math.hypot(s.x - mid.x, s.z - mid.z) < 110);
      }
      // the nearest ends first: a chain that wanders the island is not a town's errand
      const near = (s: Site) => Math.hypot(s.x - mid.x, s.z - mid.z);
      froms = froms.filter((s) => !used.has(s)).sort((a, b) => near(a) - near(b)).slice(0, 8);
      tos = tos.filter((s) => !used.has(s)).sort((a, b) => near(a) - near(b)).slice(0, 8);
      for (const from of froms) {
        for (const to of tos) {
          if (to === from || spanOf(from, to) < 6) continue;
          if (to.port >= 0 && from.port >= 0 && to.port === from.port) continue;
          // the hold is set aside here: a chain is posted whatever is being driven, and the board
          // greys it with the reason. Reach and distance still hold.
          const fit = offerable(def, at, from, to, type, true);
          if (!fit.ok || !fit.urgency) continue;
          return {
            type, from, to, note: noteFor(type, to), value: valueOf(type, fit.dist, fit.urgency, fit.seconds),
            item: null, done: false,
          };
        }
      }
    }
    return null;
  }

  // ---- taking one, running it, finishing it ----------------------------------------------------

  /** Why this chain cannot be run in the vehicle being driven, or null when it can. */
  whyNot(r: Request): string | null {
    const def = this.host.def(), at = this.host.at();
    if (!at) return null;
    for (const s of r.steps) {
      if (s.done) continue;
      const fit = offerable(def, at, s.from, s.to, s.type);
      if (!fit.ok) return fit.text;
    }
    return null;
  }

  /** The fit of the step being run now, for the card. */
  fitNow(r: Request): Fit | null {
    const s = r.steps[r.step];
    const at = this.host.at();
    if (!s || !at) return null;
    return offerable(this.host.def(), at, s.from, s.to, s.type);
  }

  /** Take it on: the first step's goods appear, held for the player. Only one chain at a time. */
  accept(r: Request): string | null {
    if (r.state !== 'offered') return 'That is not on offer.';
    const running = this.taken;
    if (running) return `${running.title} is still running. Give it up first.`;
    r.state = 'taken';
    this.spawnStep(r);
    this.host.changed();
    return null;
  }

  /** Hand it back: the goods go back to being ordinary loads, and the town may ask again tomorrow. */
  giveUp(r: Request): void {
    if (r.state !== 'taken') return;
    this.dropLoads(r);
    r.state = 'lapsed';
    this.note(`${r.town} · ${r.title} given up`);
    this.host.changed();
  }

  /** The current step's goods, put on the ground and held. */
  private spawnStep(r: Request): void {
    const s = r.steps[r.step];
    if (!s || s.item) return;
    const it = this.cargo.spawnFor(s.type, s.from, s.to, s.value, r.id, r.colour);
    if (!it) { this.lapse(r); return; }
    s.item = it;
  }

  /** Every load this chain still has on the ground goes back to being anybody's. */
  private dropLoads(r: Request): void {
    for (const s of r.steps) {
      if (!s.item) continue;
      this.cargo.unchain(s.item);
      s.item = null;
    }
  }

  /**
   * The player has delivered something. When it is the step being run, the step is ticked and the
   * next one appears; when it was the last, the chain pays and the town does what it promised.
   */
  delivered(it: CargoItem): void {
    const r = this.taken;
    if (!r) return;
    const s = r.steps[r.step];
    if (!s || s.item !== it) return;
    s.done = true;
    s.item = null;
    r.step++;
    if (r.step < r.steps.length) {
      this.spawnStep(r);
      this.host.changed();
      return;
    }
    this.finish(r);
  }

  private finish(r: Request): void {
    r.state = 'done';
    const paid = r.steps.reduce((s, q) => s + q.value, 0);
    this.host.reward(r, r.reward);
    const did = this.host.effect(r);
    this.note(`${r.town} · ${r.title} finished · ${paid + r.reward} earned`);
    this.host.announce(`${r.title} · ${r.town}`, did ? r.effectLine : 'the town is grateful');
    press.write({
      k: 'requestDone', who: 'you', town: `${r.cell[0]},${r.cell[1]}#${r.townId}`, w: did && r.effect === 'graduate' ? 4 : undefined,
      f: { title: r.title.replace(/^the\s+/i, '').replace(/^./, (c) => c.toUpperCase()), job: r.title.replace(/^the\s+/i, '').toLowerCase(), town: r.town, effect: did ? r.effectLine.replace(/[.\s]+$/, '') : '' },
    });
    this.host.changed();
  }

  private lapse(r: Request): void {
    if (r.state === 'done' || r.state === 'lapsed') return;
    this.dropLoads(r);
    const was = r.state;
    r.state = 'lapsed';
    if (was === 'taken') this.host.announce(`${r.title} · ${r.town}`, 'the moment has passed; they will ask again');
    this.note(`${r.town} · ${r.title} lapsed`);
    this.host.changed();
  }

  private note(line: string): void {
    this.history.unshift(line);
    if (this.history.length > 8) this.history.pop();
    // a chain that is over stops being listed, but the last few are kept for the board's history
    this.list = this.list.filter((r) => r.state === 'offered' || r.state === 'taken').concat(
      this.list.filter((r) => r.state !== 'offered' && r.state !== 'taken').slice(-3),
    );
  }

  // ---- saving ----------------------------------------------------------------------------------

  toSave(): SavedRequests {
    return {
      asked: [...this.asked].map(([k, d]) => [k, d] as [string, number]),
      day: this.lastDay,
      open: this.open.map((r) => ({
        k: r.kind, t: r.town, c: r.cell, i: r.townId, s: r.step,
        p: Math.round(r.posted), d: Math.round(r.due), r: r.reward,
        st: r.state === 'taken' ? 1 : 0,
      })),
    };
  }

  /**
   * Requests come back as the day and the cooldowns; the chains themselves are re-rolled from the same
   * hash the next day rather than rebuilt, since their steps point at sites the world has yet to make.
   */
  fromSave(saved: SavedRequests | undefined): void {
    this.clear();
    if (!saved) return;
    for (const [k, d] of saved.asked) this.asked.set(k, d);
    this.lastDay = saved.day ?? -1;
  }

  // ---- the console -----------------------------------------------------------------------------

  /** pr.requests.list() */
  lines(): string[] {
    return this.list.map((r) => `${r.id} ${r.town} · ${r.title} [${r.state}] step ${r.step + 1}/${r.steps.length} · $${r.reward} · ${r.effect}`);
  }

  /** pr.requests.post('market') — roll one now, whatever the day says. */
  post(kind?: string): string {
    const at = this.host.at();
    if (!at) return 'nowhere to ask from';
    const stage = stageOf(this.host.progress());
    const hours = this.host.hours();
    for (const w of this.host.resident()) {
      for (const t of w.towns) {
        const h = hashString(`${t.name}|${hours}|${kind ?? ''}`);
        const r = this.make(w, t, kind ? 4 : stage, h, hours, at, kind);
        if (!r) continue;
        this.list.push(r);
        this.host.ask(r);
        this.host.changed();
        return `${r.town} asks: ${r.title}`;
      }
    }
    return kind ? `nothing in reach fits ${kind}` : 'nothing fits right now';
  }

  /**
   * pr.requests.why('market') — why this template is not being posted: for the nearest few towns, the
   * first step that could not be filled, and what stopped it. Tuning without the board.
   */
  explain(kind: string): string[] {
    const tp = TEMPLATES.find((q) => q.kind === kind);
    if (!tp) return [`no template called ${kind}`];
    const at = this.host.at();
    const def = this.host.def();
    if (!at) return ['nowhere to ask from'];
    const out: string[] = [`${tp.title} · stage ${tp.stage} · driving the ${def.name} (holds ${def.capacity})`];
    for (const w of this.host.resident()) {
      for (const t of w.towns) {
        if (tp.needsBlight && !t.buildings.some((b) => b.derelict && !b.gone)) { out.push(`${plain(t)}: nothing boarded up`); continue; }
        if (tp.needsPort && !w.ports.some((p) => p.town === t.id)) { out.push(`${plain(t)}: no harbour of its own`); continue; }
        const used = new Set<Site>();
        let line = `${plain(t)}: ok`;
        for (let k = 0; k < tp.steps.length; k++) {
          const spec = tp.steps[k];
          const step = this.fillStep(spec, w, t, def, at, used);
          if (step) { used.add(step.from); used.add(step.to); continue; }
          line = `${plain(t)}: step ${k + 1} (${spec.types.join('/')}) — ${this.stepWhy(spec, w, t, def, at, used)}`;
          break;
        }
        out.push(line);
      }
    }
    return out;
  }

  /** What stopped one step being filled: no such cargo here, nowhere to take it, or nothing this vehicle can do. */
  private stepWhy(spec: StepSpec, w: World, t: Town, def: VehicleDef, at: Place, used: Set<Site>): string {
    const mid = { x: w.ox + t.x0 + t.size / 2, z: w.oz + t.z0 + t.size / 2 };
    const inTown = (s: Site) => s.w === w && s.lx >= t.x0 - 4 && s.lx <= t.x0 + t.size + 4 && s.lz >= t.z0 - 4 && s.lz <= t.z0 + t.size + 4;
    const notes: string[] = [];
    for (const id of spec.types) {
      const type = cargoById(id);
      if (!type) { notes.push(`${id}: no such cargo`); continue; }
      const hold = !def.holds.includes(type.cls) ? `${def.name} can’t carry ${type.cls}`
        : type.units > def.capacity ? `${type.units} units, hold is ${def.capacity}` : 'fits the hold';
      let froms = this.cargo.sitesOfKinds(type.from);
      let tos = this.cargo.sitesOfKinds(type.to);
      if (spec.fromKinds) froms = froms.filter((s) => spec.fromKinds!.includes(s.kind as string));
      if (spec.toKinds) tos = tos.filter((s) => spec.toKinds!.includes(s.kind as string));
      if (spec.fromTown) froms = froms.filter(inTown);
      if (spec.toTown) tos = tos.filter(inTown);
      if (!spec.fromTown && !spec.toTown) {
        froms = froms.filter((s) => Math.hypot(s.x - mid.x, s.z - mid.z) < 110);
        tos = tos.filter((s) => Math.hypot(s.x - mid.x, s.z - mid.z) < 110);
      }
      froms = froms.filter((s) => !used.has(s));
      tos = tos.filter((s) => !used.has(s));
      if (!froms.length) { notes.push(`${id}: nowhere it comes from`); continue; }
      if (!tos.length) { notes.push(`${id}: nowhere it goes`); continue; }
      const near = (s: Site) => Math.hypot(s.x - mid.x, s.z - mid.z);
      const fs = froms.sort((a, b) => near(a) - near(b)).slice(0, 8);
      const ts = tos.sort((a, b) => near(a) - near(b)).slice(0, 8);
      const tally = new Map<string, number>();
      for (const from of fs) {
        for (const to of ts) {
          if (to === from) { tally.set('same place', (tally.get('same place') ?? 0) + 1); continue; }
          if (spanOf(from, to) < 6) { tally.set('too close', (tally.get('too close') ?? 0) + 1); continue; }
          const fit = offerable(def, at, from, to, type, true);
          tally.set(fit.why, (tally.get(fit.why) ?? 0) + 1);
        }
      }
      notes.push(`${id}: ${hold}; ${fs.length}×${ts.length} pairs — ${[...tally].map(([k, n]) => `${k} ${n}`).join(', ')}`);
    }
    return notes.join(' | ');
  }

  /** pr.requests.finish() — tick every step of the running chain and pay it out. */
  finishNow(): string {
    const r = this.taken;
    if (!r) return 'no chain running';
    this.dropLoads(r);
    for (const s of r.steps) s.done = true;
    r.step = r.steps.length;
    this.finish(r);
    return `${r.title} finished`;
  }
}

export interface SavedRequests {
  asked: [string, number][];
  day: number;
  open: { k: string; t: string; c: [number, number]; i: number; s: number; p: number; d: number; r: number; st: number }[];
}

const plain = (t: Town): string => t.name.replace(/ City$/, '');

/**
 * The step's line on the card, written from what was actually found — never from the template — so a
 * chain can never claim to want something other than what it is carrying.
 */
function noteFor(t: CargoType, to: Site): string {
  const place = to.port >= 0 ? (to.major ? 'harbour' : 'dock')
    : (SITE_LABEL[to.kind] ?? String(to.kind).replace(/([a-z])([A-Z])/g, '$1 $2')).toLowerCase();
  return `${t.name.toLowerCase()} to the ${place}`;
}

const fitOf = (def: VehicleDef, at: Place, s: Step): Fit => offerable(def, at, s.from, s.to, s.type);
