import { DIRS, STEP, type Building, type BuildingKind, type World } from './tiles';
import { FLOOR } from './towns';

/**
 * Helipads: a marked pad on the roof of a hospital, a police station, a news or radio station, an
 * airport terminal and one tall tower in three, where a helicopter can put down. This one table says
 * where each pad is in its building's own frame; the renderer draws the marking there and the cargo
 * system makes a place of it, so the paint and the pickup point can never disagree, and a pad exists
 * whether or not its chunk has been drawn yet.
 */

/** A pad in the model's frame (origin mid-lot, +z the way it faces): its middle, the height of its surface, its size. */
export interface PadLocal { x: number; z: number; y: number; s: number }

/** A pad in the island's frame: tiles across, and height in world units. */
export interface Helipad { x: number; z: number; y: number; s: number; b: Building; kind: PadKind }

/** Which kind of place a pad is, as the cargo system names it. */
export type PadKind = 'padHospital' | 'padPolice' | 'padTower' | 'padNews' | 'padRadio' | 'padAirport';

const PAD_KIND: Partial<Record<BuildingKind, PadKind>> = {
  hospital: 'padHospital', police: 'padPolice', skyscraper: 'padTower', newsStation: 'padNews', radioStation: 'padRadio', terminal: 'padAirport',
};

/** A skyscraper this tall, one in three of them, trades its crown for a pad. */
const TOWER_FLOORS = 10;
export const towerHasPad = (b: Building): boolean => b.kind === 'skyscraper' && b.floors >= TOWER_FLOORS && (b.seed >>> 0) % 3 === 0;

/**
 * Where a building's pad is, in its model's frame with W across and D deep, or null if it has none. The
 * heights are read off the models in render/townMesh.ts and render/buildings/media.ts.
 */
export function padLocal(b: Building, W: number, D: number): PadLocal | null {
  if (b.derelict || b.gone) return null;
  switch (b.kind) {
    // on the ward tower, which stands on a 0.55 podium
    case 'hospital': return { x: -0.5, z: -0.4, y: 0.55 + b.floors * FLOOR, s: 0.95 };
    // the back half of the flat roof, clear of the mast and the sign
    case 'police': return { x: -0.35, z: -0.38, y: 0.74, s: 0.72 };
    // on the roof slab that stands in for the crown
    case 'skyscraper': return towerHasPad(b) ? { x: 0, z: 0, y: b.floors * FLOOR + 0.06, s: 0.95 } : null;
    case 'newsStation': return { x: -W / 2 + 0.75, z: -0.15, y: b.floors * FLOOR, s: 0.9 };
    case 'radioStation': return { x: 0.28, z: -0.2, y: 0.42, s: 0.72 };
    // at one end of the terminal's curved roof, on its top course
    case 'terminal': return { x: W / 2 - 1.3, z: 0, y: 0.8 + b.floors * FLOOR * 1.6 + 0.24, s: 1.0 };
    default: return null;
  }
}

/** A building's pad in the island's frame, or null. */
export function padOf(b: Building): Helipad | null {
  const kind = PAD_KIND[b.kind];
  if (!kind) return null;
  const alongZ = b.facing % 2 === 1;
  const p = padLocal(b, alongZ ? b.w : b.d, alongZ ? b.d : b.w);
  if (!p) return null;
  // the model's frame to the island's: the same turn the renderer places the model with
  const yaw = Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]);
  const c = Math.cos(yaw), s = Math.sin(yaw);
  const ox = b.x + b.w / 2, oz = b.z + b.d / 2;
  return { x: ox + p.x * c + p.z * s, z: oz - p.x * s + p.z * c, y: b.level * STEP + p.y, s: p.s, b, kind };
}

/** Every pad on an island. */
export function helipadsOf(w: World): Helipad[] {
  const out: Helipad[] = [];
  for (const b of w.allBuildings) {
    const p = padOf(b);
    if (p) out.push(p);
  }
  return out;
}

/** The buildings on an island that could carry a pad, kept until the island gains or loses a building. */
const hosts = new WeakMap<World, { n: number; bs: Building[] }>();

/**
 * The pad a helicopter at (x, z) in this island's frame is over, or null: within the painted square
 * and a little over its edge, so a pilot needn't be exact. The pad comes back in the same frame.
 */
export function padUnder(w: World, x: number, z: number): Helipad | null {
  let h = hosts.get(w);
  if (!h || h.n !== w.allBuildings.length) {
    h = { n: w.allBuildings.length, bs: w.allBuildings.filter((b) => PAD_KIND[b.kind]) };
    hosts.set(w, h);
  }
  for (const b of h.bs) {
    if (x < b.x - 1 || z < b.z - 1 || x > b.x + b.w + 1 || z > b.z + b.d + 1) continue;
    const p = padOf(b);
    if (p && Math.abs(x - p.x) <= p.s / 2 + 0.3 && Math.abs(z - p.z) <= p.s / 2 + 0.3) return p;
  }
  return null;
}
