  k.box(dx - 0.02, 0.12, dz - 0.02, 0.1, 0.1, 0.1, ORANGE, BLACK);
  k.pane(dx - 0.02, 0.15, dz + 0.03, 0.08, 0.06, 1, GLASS, EVENING, WARM_GLOW);
  k.bar([dx + 0.05, 0.12, dz + 0.04], [dx + 0.05, 0.28, dz + 0.16], 0.016, ORANGE);
  k.bar([dx + 0.05, 0.28, dz + 0.16], [dx + 0.05, 0.1, dz + 0.27], 0.012, ORANGE);
  k.box(dx + 0.05, 0.02, dz + 0.27, 0.08, 0.07, 0.06, BLACK);
