  bags(k, tx - 0.42, tz - 0.3, tx - 0.42, tz + 0.3, 2);
  // the road in from the gate, the boom and the guard hut
  k.box(0.6, 0.02, 1.53, 0.5, 0.012, 1.86, ASPHALT);
  boom(k, 0.33, 2.2, 0.55);
  guardHut(k, 1.15, 2.1, 0.28, 0.28, 0.3);
  bags(k, 1.0, 2.36, 1.32, 2.36, 2);
  // the camouflage net over a bowser and a lorry, by the left shelter
  armyLorry(k, -2.75, 1.95, false, 1);
  bowser(k, -2.3, 1.95, false, 1);
  camoNet(k, -2.52, 1.92, 1.0, 0.72, 0.46, 0.1);
  // the gun pit by the right shelter
  const gx = 2.5, gz = 1.95;
  bagRing(k, gx, gz, 0.26, 14, 3);
  k.box(gx, 0.02, gz, 0.16, 0.08, 0.16, OLIVE_DK);
  for (const s of [-1, 1]) k.bar([gx + s * 0.03, 0.12, gz], [gx + s * 0.03, 0.3, gz - 0.2], 0.012, DARK);
  k.box(gx, 0.08, gz, 0.1, 0.07, 0.1, OLIVE);
  // the windsock
  const wx = 3.0, wz = -0.95;
