  tube(k, [wx, 0.5, wz], [wx + 0.1, 0.48, wz + 0.1], 0.04, 0.032, ORANGE, 6, false);
  tube(k, [wx + 0.1, 0.48, wz + 0.1], [wx + 0.2, 0.45, wz + 0.2], 0.032, 0.022, WHITE, 6, false);
  // chain-link round it all, open at the gate
  const fx = hw - 0.08, fz = hd - 0.08;
