// ---- the Army: checkpoint (1 × 2) -----------------------------------------------------------------------

/**
 * A roadside checkpoint in the front half of its lot: a red and white boom raised on its post at the kerb
 * (it pivots about x at (0.32, 0.3, 0.84), so lowering it swings it out across the road), a sentry hut with
 * an aerial, an L of sandbags and a soldier on watch.
 */
const checkpoint: Draw = (k) => {
  k.box(0, 0, 0.45, 0.9, 0.015, 1.0, CONCRETE);
  // the sentry hut
  const hx = -0.18, hz = 0.22;
  guardHut(k, hx, hz, 0.38, 0.34, 0.33);
  k.bar([hx + 0.14, 0.38, hz - 0.12], [hx + 0.14, 0.82, hz - 0.12], 0.006, DARK);
  // sandbags along the front and down the side
  bags(k, -0.44, 0.6, 0.06, 0.6, 3);
  bags(k, -0.42, 0.42, -0.42, 0.54, 3);
  // the boom raised on its post, its counterweight below the pivot
  const px = 0.32, pz = 0.84, py = 0.3, L = 0.56, a = (80 * Math.PI) / 180;
  k.box(px, 0.015, pz, 0.08, py - 0.01, 0.08, WHITE, RED);
  k.box(px, 0.015, pz, 0.086, 0.06, 0.086, RED);
  const dir: [number, number] = [Math.sin(a), -Math.cos(a)];
  const n = 6;
  for (let i = 0; i < n; i++) {
    const t0 = 0.03 + (L * i) / n, t1 = 0.03 + (L * (i + 1)) / n;
    k.bar([px - 0.065, py + dir[0] * t0, pz + dir[1] * t0], [px - 0.065, py + dir[0] * t1, pz + dir[1] * t1], 0.016, i % 2 ? WHITE : RED);
  }
  k.bar([px - 0.065, py - dir[0] * 0.03, pz - dir[1] * 0.03], [px - 0.065, py - dir[0] * 0.13, pz - dir[1] * 0.13], 0.03, DARK);
  k.box(px - 0.035, py - 0.02, pz, 0.03, 0.04, 0.04, DARK);
  k.glowBox(px - 0.065, py + dir[0] * (L + 0.04), pz + dir[1] * (L + 0.04), 0.03, 0.03, 0.03, hex(0xc23a30), ALL_NIGHT, RED_LIGHT);
  // the soldier on watch by the boom
  soldier(k, 0.1, 0.8, 0.015);
};

