import * as THREE from 'three';
import type { Build, Kit } from '../vehicleMeshes';

/**
 * The horse-drawn carriage (game/carriages.ts): a pair of horses at a trot ahead of an open landau, the coachman
 * up on his box in a top hat, a couple riding behind under the folded hood. The legs swing with the distance
 * covered (vehicleMeshes poseVehicleMesh, `legs`), so the pair trots when it moves and stands when it stops.
 */

// (a box's y is its middle; front is +z; the body's panels are in d.color)
const BLACK = 0x15161a, LEATHER = 0x3a2a1e, BRASS = 0xd8b04a, WOOD = 0x6b3f22;
/** Each livery's horses: dark bays with the black carriage, greys with the white, chestnuts with the green. */
const COATS: Record<string, [number, number]> = {
  carriage: [0x4a2c1c, 0x1a1210], carriageWhite: [0xe8e6e0, 0xb9b4aa], carriageGreen: [0x9a5a2e, 0x5a3418],
};

/** A horse standing at (x, z), facing +z: body, neck, head, mane, tail and four legs hung from the shoulder and hip. */
function horse(k: Kit, b: THREE.Object3D, x: number, z: number, coat: number, mane: number, legs: { obj: THREE.Object3D; phase: number }[]): void {
  const g = k.group(b, x, 0, z);
  k.box(g, 0.13, 0.15, 0.4, coat, 0, 0.4, 0);
  const neck = k.box(g, 0.09, 0.2, 0.1, coat, 0, 0.53, 0.21);
  neck.rotation.x = 0.55;
  k.box(g, 0.025, 0.16, 0.06, mane, 0, 0.56, 0.17).rotation.x = 0.55;
  const head = k.box(g, 0.075, 0.075, 0.17, coat, 0, 0.62, 0.3);
  head.rotation.x = 0.35;
  for (const sx of [-1, 1]) k.box(g, 0.02, 0.04, 0.02, coat, sx * 0.025, 0.69, 0.25);
  k.box(g, 0.03, 0.14, 0.04, mane, 0, 0.36, -0.22).rotation.x = -0.35;
  // the collar and the saddle pad of the harness
  k.box(g, 0.145, 0.05, 0.05, LEATHER, 0, 0.5, 0.15);
  k.box(g, 0.14, 0.03, 0.08, LEATHER, 0, 0.48, -0.02);
  // diagonal pairs move together, as in a trot
  for (const [lx, lz, phase] of [[-0.045, 0.15, 0], [0.045, 0.15, Math.PI], [-0.045, -0.15, Math.PI], [0.045, -0.15, 0]] as const) {
    const hip = k.group(g, lx, 0.36, lz);
    k.box(hip, 0.035, 0.3, 0.04, coat, 0, -0.15, 0);
    k.box(hip, 0.04, 0.04, 0.05, BLACK, 0, -0.32, 0.005);
    legs.push({ obj: hip, phase });
  }
}

/** A carriage wheel: an iron tyre on wooden spokes round a brass hub, turning with the road. */
function wheel(k: Kit, b: THREE.Object3D, r: number, x: number, z: number, steer: boolean): void {
  const g = k.wheel(b, r, 0.04, x, r, z, steer, BRASS);
  const tyre = g.children[0];
  for (let s = 0; s < 4; s++) {
    const spoke = k.box(tyre, 0.02, r * 1.85, 0.025, WOOD);
    spoke.rotation.x = (s * Math.PI) / 4;
  }
}

export const carriage: Build = (k, b, d, x) => {
  const p = d.color;
  const [coat, mane] = COATS[d.id] ?? COATS.carriage;
  const legs: { obj: THREE.Object3D; phase: number }[] = [];
  for (const sx of [-1, 1]) horse(k, b, sx * 0.1, 0.56, coat, mane, legs);
  // the pole between them and the traces back to the splinter bar
  k.box(b, 0.025, 0.025, 0.6, WOOD, 0, 0.36, 0.42);
  for (const sx of [-1, 1]) k.box(b, 0.012, 0.012, 0.42, LEATHER, sx * 0.1, 0.43, 0.3);
  k.box(b, 0.34, 0.03, 0.03, WOOD, 0, 0.36, 0.12);
  // the undercarriage: a perch from the front axle to the back, sprung under the body
  k.box(b, 0.05, 0.04, 0.62, BLACK, 0, 0.24, -0.2);
  for (const sz of [0.04, -0.42]) k.box(b, 0.44, 0.03, 0.04, BLACK, 0, 0.2 + (sz < 0 ? 0.03 : 0), sz);
  // the body: a boat-shaped tub between the wheels, a step and a door on each side, mudguards over the front
  k.box(b, 0.36, 0.16, 0.52, p, 0, 0.38, -0.22);
  k.box(b, 0.3, 0.06, 0.1, p, 0, 0.34, 0.08);
  k.box(b, 0.37, 0.02, 0.53, BRASS, 0, 0.47, -0.22);
  for (const sx of [-1, 1]) {
    k.box(b, 0.01, 0.1, 0.16, BLACK, sx * 0.183, 0.38, -0.2);
    k.box(b, 0.06, 0.012, 0.08, BLACK, sx * 0.2, 0.26, -0.2);
    k.box(b, 0.05, 0.012, 0.16, BLACK, sx * 0.19, 0.32, 0.05);
  }
  // inside: buttoned red seats, the couple facing forward under the folded hood
  k.box(b, 0.3, 0.04, 0.16, 0x8a1f2a, 0, 0.47, -0.36);
  k.box(b, 0.3, 0.14, 0.04, 0x8a1f2a, 0, 0.54, -0.45);
  k.rider(b, -0.07, 0.47, -0.34, 0x2f4d7a);
  const lady = k.rider(b, 0.07, 0.47, -0.34, 0xc95b8a);
  k.cyl(lady, 0.09, 0.09, 0.012, 10, 0xf2e6c8, 0, 0.36, 0.01);
  const hood = new THREE.CylinderGeometry(0.17, 0.17, 0.14, 8, 1, true, -Math.PI / 2, Math.PI);
  hood.rotateZ(Math.PI / 2);
  k.add(b, hood, k.cloth(BLACK), 0, 0.5, -0.47).scale.set(1, 0.9, 1);
  // the box seat up front, the coachman in a top hat with the reins out to the pair
  k.box(b, 0.3, 0.16, 0.12, p, 0, 0.5, 0.08);
  k.box(b, 0.3, 0.03, 0.14, LEATHER, 0, 0.59, 0.08);
  const man = k.rider(b, 0, 0.6, 0.06, BLACK);
  k.cyl(man, 0.05, 0.05, 0.1, 8, BLACK, 0, 0.38, -0.005);
  k.cyl(man, 0.075, 0.075, 0.01, 8, BLACK, 0, 0.33, -0.005);
  for (const sx of [-1, 1]) k.box(b, 0.008, 0.008, 0.46, LEATHER, sx * 0.07, 0.62, 0.32).rotation.x = 0.18;
  // the lamps either side of the box
  for (const sx of [-1, 1]) {
    k.box(b, 0.04, 0.06, 0.04, BRASS, sx * 0.17, 0.6, 0.14);
    k.box(b, 0.03, 0.035, 0.03, k.lamp(), sx * 0.17, 0.6, 0.165);
  }
  wheel(k, b, 0.13, -0.21, 0.04, true);
  wheel(k, b, 0.13, 0.21, 0.04, true);
  wheel(k, b, 0.19, -0.22, -0.42, false);
  wheel(k, b, 0.19, 0.22, -0.42, false);
  x.legs = legs;
};
