import { hex, scale, type RGB } from '../../../world/biomes';
import type { RegionBuildingKind } from '../../../world/tiles';
import { Vis } from '../../nightLights';
import { COOL_GLOW, DARK, GLASS, METAL, PINE, TAU, WARM_GLOW, WHITE, win, type Draw, type Kit, type P3 } from '../kit';

/**
 * The Heights: the mountain hut, the funicular's valley station, the alpine dairy, the monastery on
 * its crag, and the wonder, the dam, a curved concrete wall with a road along its crest.
 */

const STONE = hex(0xa8a49a), STONE_DK = hex(0x8a867c), LARCH = hex(0x7a4e2e), LARCH_DK = hex(0x5a3a22);
const SHINGLE = hex(0x5a4a44), SLATE = hex(0x4f555c), FLOWER = [0xd8322a, 0xf2a0c0, 0xf4f2ec].map(hex);
const RED = hex(0xd8322a), CONCRETE = hex(0xc9c6bc), CONCRETE_DK = hex(0xa9a69c);

/** A chalet block: a stone ground floor, a timber storey above, deep eaves and a balcony. */
function chalet(k: Kit, b: Parameters<Draw>[3], r: Parameters<Draw>[4], x: number, z: number, w: number, d: number, roof: RGB): number {
  k.box(x, 0, z, w, 0.22, d, STONE);
  k.box(x, 0.22, z, w, 0.2, d, LARCH);
  k.gable(x, 0.42, z, w + 0.24, 0.2, d + 0.2, roof, LARCH_DK, false);
  for (const f of [1, 3]) {
    const fz = z + (f === 1 ? d / 2 : -d / 2);
    const n = Math.max(1, Math.round(w / 0.36));
    for (let i = 0; i < n; i++) {
      const wx = x - w / 2 + (w / n) * (i + 0.5);
      win(k, b, r, wx, 0.06, fz, 0.1, 0.1, f);
      win(k, b, r, wx, 0.27, fz, 0.1, 0.1, f);
    }
  }
  // the balcony along the front with its flower box
  k.box(x, 0.22, z + d / 2 + 0.07, w + 0.04, 0.02, 0.14, LARCH_DK);
  k.box(x, 0.3, z + d / 2 + 0.14, w + 0.04, 0.06, 0.012, LARCH);
  k.tagged(Vis.NotWinter, () => k.box(x, 0.36, z + d / 2 + 0.14, w * 0.8, 0.03, 0.03, FLOWER[Math.floor(r() * 3)]));
  return 0.62;
}

// ---- 1. mountain hut ---------------------------------------------------------------------------

const mountainHut: Draw = (k, W, D, b, r) => {
  const hx = -0.15, hz = -0.25, w = 1.2, d = 0.8;
  chalet(k, b, r, hx, hz, w, d, SHINGLE);
  // stones holding the roof down and a chimney
  for (let i = 0; i < 4; i++) k.box(hx - 0.45 + i * 0.3, 0.52, hz + 0.25, 0.06, 0.04, 0.06, STONE_DK);
  k.box(hx - 0.35, 0.45, hz - 0.18, 0.12, 0.34, 0.12, STONE);
  // the solar panel on the sunny slope
  const py = 0.47, pz0 = hz + 0.12, pz1 = hz + 0.44, ty = 0.42 + 0.2 * (1 - (pz1 - hz) / 0.5);
  k.quad([hx + 0.08, py + 0.06, pz0], [hx + 0.48, py + 0.06, pz0], [hx + 0.48, ty + 0.03, pz1], [hx + 0.08, ty + 0.03, pz1], hex(0x2a3f66), [hx + 0.28, 0, hz]);
  // the flag
  const fx = W / 2 - 0.3, fz = D / 2 - 0.35;
  k.box(fx, 0, fz, 0.025, 0.9, 0.025, WHITE);
  k.box(fx + 0.12, 0.72, fz, 0.22, 0.14, 0.01, RED);
  k.box(fx + 0.12, 0.775, fz + 0.009, 0.08, 0.03, 0.004, WHITE);
  k.box(fx + 0.12, 0.745, fz + 0.009, 0.03, 0.09, 0.004, WHITE);
  // benches and a table on the terrace
  for (let i = 0; i < 2; i++) {
    const tx = -0.55 + i * 0.6, tz = D / 2 - 0.4;
    k.box(tx, 0.1, tz, 0.4, 0.03, 0.16, LARCH);
    for (const s of [-1, 1]) k.box(tx, 0.06, tz + s * 0.16, 0.4, 0.02, 0.06, LARCH_DK);
    for (const s of [-0.16, 0.16]) k.box(tx + s, 0, tz, 0.03, 0.1, 0.12, LARCH_DK);
  }
  k.box(-0.7, 0, 0.3, 0.3, 0.02, 0.14, hex(0xe8e2d4));
  // a woodpile, rucksacks and a lamp over the door
  for (let i = 0; i < 3; i++) k.box(hx + w / 2 + 0.1, i * 0.05, hz, 0.14, 0.05, 0.6 - i * 0.1, i % 2 ? LARCH : hex(0x9a6a42));
  k.box(0.2, 0, D / 2 - 0.62, 0.07, 0.1, 0.05, RED);
  k.box(0.3, 0, D / 2 - 0.62, 0.07, 0.1, 0.05, hex(0x2f7fb5));
  k.glowBox(hx, 0.17, hz + d / 2 + 0.02, 0.05, 0.05, 0.03, DARK, [17.5, 23, 1.6], WARM_GLOW);
  for (let i = 0; i < 5; i++) k.box(-W / 2 + 0.2 + r() * 0.3, 0, -D / 2 + 0.2 + r() * 1.4, 0.1 + r() * 0.1, 0.06, 0.1, STONE_DK);
};

// ---- 2. funicular (valley station) -------------------------------------------------------------

const funicular: Draw = (k, W, D, b, r) => {
  const grade = 0.42, z0 = 0.15, z1 = -D / 2 - 1.8;
  /** The height of the track at z: an incline from the station, never below the ground. */
  const trackY = (z: number) => Math.max(0.18 + (z0 - z) * grade, k.ground(0, z) + 0.08);
  // sleepers, rails and trestle legs
  const n = 12;
  for (let i = 0; i <= n; i++) {
    const z = z0 + ((z1 - z0) * i) / n, y = trackY(z);
    k.box(0, y - 0.03, z, 0.42, 0.03, 0.06, LARCH_DK);
    if (i < n) {
      const za = z, zb = z0 + ((z1 - z0) * (i + 1)) / n;
      for (const sx of [-0.12, 0.12]) k.bar([sx, trackY(za) + 0.01, za], [sx, trackY(zb) + 0.01, zb], 0.012, METAL);
    }
    if (i % 2 === 0 && i > 0) {
      const g = k.ground(0, z);
      for (const sx of [-0.16, 0.16]) k.box(sx, g, z, 0.05, y - 0.03 - g, 0.05, CONCRETE_DK);
    }
  }
  // the car: stepped compartments on a sloped chassis, glazed, bright red
  const cz = -0.75, len = 0.9, steps = 3;
  for (let s = 0; s < steps; s++) {
    const zz = cz + len / 2 - (len / steps) * (s + 0.5), y = trackY(zz);
    k.box(0, y + 0.02, zz, 0.3, 0.22, len / steps - 0.01, RED, hex(0xf4f2ec));
    for (const f of [0, 2]) k.pane(f === 0 ? 0.15 : -0.15, y + 0.11, zz, len / steps - 0.08, 0.09, f, GLASS, [17, 22, 1.4], COOL_GLOW);
  }
  // the station house over the foot of the line
  const sw = 1.3, sd = 0.75, sz = D / 2 - sd / 2 - 0.1;
  k.box(0, 0, sz, sw, 0.3, sd, STONE);
  k.box(0, 0.3, sz, sw, 0.18, sd, hex(0xe8e2d4));
  k.gable(0, 0.48, sz, sw + 0.2, 0.24, sd + 0.24, SLATE, hex(0xe8e2d4), true);
  // the arch the track leaves by
  k.box(0, 0.02, sz - sd / 2 - 0.005, 0.46, 0.34, 0.01, hex(0x2a2e33));
  // big glazed front, door, sign and clock
  k.box(0, 0, sz + sd / 2 + 0.005, 0.26, 0.24, 0.01, LARCH_DK);
  for (const sx of [-1, 1]) win(k, b, r, sx * 0.38, 0.06, sz + sd / 2, 0.3, 0.2, 1);
  for (const sx of [-1, 1]) win(k, b, r, sx * sw / 2, 0.08, sz, 0.4, 0.16, sx > 0 ? 0 : 2);
  k.box(0, 0.33, sz + sd / 2 + 0.015, 0.7, 0.1, 0.02, RED);
  k.box(0, 0.36, sz + sd / 2 + 0.028, 0.5, 0.04, 0.005, WHITE);
  k.face(0, 0.62, sz + sd / 2 + 0.13, 0.06, WHITE, 10);
  // the winding wheel turning in the attic window
  k.spin(0, 0.62, sz - 0.1, 'x', 1.2, (s) => { s.hoop(0, 0, 0, 0.1, 0.012, DARK, 10, 'zy'); s.bar([0, -0.1, 0], [0, 0.1, 0], 0.008, DARK); s.bar([0, 0, -0.1], [0, 0, 0.1], 0.008, DARK); });
  k.glowBox(0.5, 0.26, sz + sd / 2 + 0.03, 0.04, 0.04, 0.03, DARK, [17, 23.5, 1.6], WARM_GLOW);
  // a bench and a pine
  k.box(-0.62, 0, D / 2 - 0.04, 0.3, 0.07, 0.06, LARCH);
  k.cone(W / 2 - 0.18, 0, -0.4, 0.2, 0.6, PINE, 7);
  k.cone(W / 2 - 0.18, 0.3, -0.4, 0.14, 0.45, PINE, 7);
};

// ---- 3. dairy ----------------------------------------------------------------------------------

const dairy: Draw = (k, W, D, b, r) => {
  // the barn: stone below, timber above, a hay door and big deep eaves
  const bz = -0.3, bw = 1.4, bd = 0.9;
  k.box(0, 0, bz, bw, 0.26, bd, STONE);
  k.box(0, 0.26, bz, bw, 0.26, bd, LARCH);
  k.gable(0, 0.52, bz, bw + 0.28, 0.28, bd + 0.24, SHINGLE, LARCH_DK, true);
  k.box(0, 0.28, bz + bd / 2 + 0.005, 0.28, 0.22, 0.01, LARCH_DK);
  k.box(0, 0.32, bz + bd / 2 + 0.01, 0.2, 0.16, 0.01, hex(0xd8b85a));
  for (let i = 0; i < 4; i++) k.box(-0.52 + i * 0.35, 0.08, bz + bd / 2 + 0.005, 0.14, 0.1, 0.01, i === 1 ? LARCH_DK : DARK);
  win(k, b, r, -bw / 2, 0.1, bz, 0.14, 0.1, 2);
  win(k, b, r, bw / 2, 0.1, bz + 0.2, 0.14, 0.1, 0);
  // a painted gable board
  k.face(0, 0.66, bz + bd / 2 + 0.126, 0.07, RED, 8);
  // the cheese store: a squat stone cellar with an arched door and wheels on a rack outside
  const cx = W / 2 - 0.35, cz = D / 2 - 0.35;
  k.box(cx, 0, cz, 0.5, 0.26, 0.44, hex(0xe8e2d4));
  k.hip(cx, 0.26, cz, 0.6, 0.16, 0.54, SLATE);
  k.box(cx - 0.251, 0, cz, 0.01, 0.16, 0.14, LARCH_DK);
  k.face(cx, 0.16, cz + 0.226, 0.06, LARCH_DK, 8);
  const cheese = hex(0xe8b84a);
  for (let i = 0; i < 3; i++) for (let s = 0; s < 2; s++) k.cyl(cx - 0.45, 0.02 + s * 0.08, cz - 0.12 + i * 0.12, 0.05, 0.05, cheese, 8, hex(0xf2d27a));
  k.box(cx - 0.45, 0, cz, 0.12, 0.02, 0.4, LARCH);
  // milk churns on their stand by the lane
  const mx = -W / 2 + 0.35, mz = D / 2 - 0.25;
  k.box(mx, 0, mz, 0.4, 0.1, 0.22, LARCH_DK);
  for (let i = 0; i < 3; i++) {
    k.cyl(mx - 0.12 + i * 0.12, 0.1, mz, 0.045, 0.1, METAL, 8);
    k.cyl(mx - 0.12 + i * 0.12, 0.2, mz, 0.025, 0.03, METAL, 6);
  }
  k.cyl(mx + 0.3, 0, mz + 0.05, 0.045, 0.1, METAL, 8);
  // a haystack and a cow at the gate
  k.tagged(Vis.NotWinter, () => {
    k.cyl(-0.2, 0, 0.55, 0.16, 0.16, hex(0xd8b85a), 8);
    k.cone(-0.2, 0.16, 0.55, 0.16, 0.14, hex(0xc9a84a), 8);
    const cow = hex(0x8a5a3a);
    k.box(0.3, 0.08, 0.5, 0.26, 0.12, 0.12, cow);
    k.box(0.46, 0.14, 0.5, 0.08, 0.08, 0.08, cow);
    for (const [u, v] of [[-0.1, -0.04], [-0.1, 0.04], [0.1, -0.04], [0.1, 0.04]]) k.box(0.3 + u, 0, 0.5 + v, 0.03, 0.08, 0.03, scale(cow, 0.8));
    k.box(0.5, 0.1, 0.5, 0.02, 0.03, 0.03, hex(0xd8b04a));
  });
};

// ---- 4. monastery ------------------------------------------------------------------------------

const monastery: Draw = (k, W, D, b, r) => {
  const wall = hex(0xece6d6), rock = hex(0x746e64), roof = hex(0x6a5a50), crag = 0.18;
  // the crag the compound stands on
  for (let i = 0; i < 14; i++) {
    const a = (i / 14) * TAU, rr = W / 2 - 0.05, x = Math.cos(a) * rr * 0.95, z = Math.sin(a) * rr * 0.95;
    const g = Math.min(0, k.ground(x, z));
    k.box(x, g - 0.2, z, 0.5 + r() * 0.3, crag + 0.2 - g, 0.5 + r() * 0.3, scale(rock, 0.9 + r() * 0.2));
  }
  k.box(0, 0, 0, W - 0.3, crag, D - 0.3, rock, hex(0xb8b09a));
  // the enclosing wall with a gate at the front
  const h = 0.28, e = W / 2 - 0.22;
  for (const s of [-1, 1]) {
    k.box(s * e, crag, 0, 0.08, h, 2 * e, wall);
    k.box(-e / 2 - 0.2, crag, s * e, e - 0.4, h, 0.08, wall);
    k.box(e / 2 + 0.2, crag, s * e, e - 0.4, h, 0.08, wall);
  }
  k.box(0, crag, -e, 0.44, h, 0.08, wall);
  for (const sx of [-0.22, 0.22]) k.box(sx, crag, e, 0.1, h + 0.12, 0.12, wall);
  k.gable(0, crag + h + 0.12, e, 0.56, 0.1, 0.18, roof, wall);
  // steps from the lane up to the gate
  for (let i = 0; i < 3; i++) k.box(0, 0, D / 2 - 0.06 - i * 0.05, 0.36, (crag / 3) * (i + 1), 0.08, hex(0xb8b09a));
  // the church along the back, a bell tower at its corner
  const cz = -0.55;
  k.box(-0.2, crag, cz, 1.5, 0.5, 0.6, wall);
  k.gable(-0.2, crag + 0.5, cz, 1.6, 0.28, 0.7, roof, wall);
  for (let i = 0; i < 4; i++) win(k, b, r, -0.8 + i * 0.4, crag + 0.2, cz + 0.3, 0.07, 0.18, 1, hex(0x5d6f8a));
  k.box(-1.0, crag, cz, 0.02, 0.1, 0.02, wall);
  k.face(-0.96, crag + 0.36, cz, 0.08, hex(0x5d6f8a), 8);
  const tx = 0.75, tz = -0.75;
  k.box(tx, crag, tz, 0.36, 1.2, 0.36, wall);
  for (let f = 0; f < 4; f++) k.pane(tx + [0.18, 0, -0.18, 0][f], crag + 0.92, tz + [0, 0.18, 0, -0.18][f], 0.14, 0.16, f, DARK, [18.5, 21.5, 1.2], WARM_GLOW);
  k.box(tx, crag + 1.2, tz, 0.4, 0.04, 0.4, hex(0xd8d0bc));
  k.hip(tx, crag + 1.24, tz, 0.4, 0.14, 0.4, hex(0x3f5a4a));
  k.cyl(tx, crag + 1.38, tz, 0.1, 0.12, hex(0x3f5a4a), 8);
  k.cone(tx, crag + 1.5, tz, 0.08, 0.34, hex(0x3f5a4a), 8);
  k.bar([tx, crag + 1.8, tz], [tx, crag + 1.96, tz], 0.008, hex(0xd8b04a));
  k.face(tx, crag + 0.72, tz + 0.186, 0.08, WHITE, 10);
  // the bell swinging in the belfry
  k.spin(tx, crag + 1.12, tz, 'x', 0.5, (s) => { s.cone(0, -0.1, 0, 0.06, 0.1, hex(0xb8903a), 8); }, 'turn');
  // the cloister: a roofed walk round a garden
  const gx = -0.3, gz = 0.55, gs = 1.2;
  k.box(gx, crag, gz, gs - 0.3, 0.01, gs - 0.3, hex(0x6fa85a));
  k.cyl(gx, crag, gz, 0.05, 0.12, hex(0xb8b09a), 6);
  for (let i = 0; i < 4; i++) {
    const a = (i * TAU) / 4, ox = Math.round(Math.cos(a)) * (gs / 2 - 0.08), oz = Math.round(Math.sin(a)) * (gs / 2 - 0.08);
    const along = i % 2 === 0;
    k.hip(gx + ox, crag + 0.22, gz + oz, along ? 0.2 : gs, 0.08, along ? gs : 0.2, roof);
    for (let c = 0; c < 4; c++) {
      const t = -gs / 2 + 0.15 + c * ((gs - 0.3) / 3);
      k.box(gx + (along ? ox - Math.sign(ox) * 0.06 : t), crag, gz + (along ? t : oz - Math.sign(oz) * 0.06), 0.03, 0.22, 0.03, wall);
    }
  }
  // the range of cells along the east wall
  k.box(e - 0.25, crag, 0.4, 0.38, 0.34, 1.4, wall);
  k.gable(e - 0.25, crag + 0.34, 0.4, 0.46, 0.16, 1.5, roof, wall, true);
  for (let i = 0; i < 4; i++) win(k, b, r, e - 0.44, crag + 0.14, -0.1 + i * 0.33, 0.07, 0.1, 2);
  k.cone(-e + 0.2, crag, e - 0.2, 0.14, 0.5, PINE, 6);
};

// ---- 5. the dam (wonder) -----------------------------------------------------------------------

const dam: Draw = (k, W, D) => {
  const half = W / 2, bow = 0.4, seg = 16, drop = 0.5, run = 0.24, steps = 12, deep = -steps * drop;
  const zc = (x: number) => -bow * (x / half) ** 2;
  const zd = (x: number) => zc(x) - D / 2, zu = (x: number) => zc(x) + D / 2;
  const foot = (x: number) => zd(x) - steps * run;
  const yb = (x: number) => Math.max(-8, Math.min(deep, k.ground(x, foot(x) - 0.3) - 0.2));
  const spill = 1.1;
  const xs = Array.from({ length: seg + 1 }, (_, i) => -half + (W * i) / seg);
  /** A slab following the curve between x0 and x1, offset `off` from the crest's centre line. */
  const curved = (x0: number, x1: number, off: number, t: number, y0: number, y1: number, col: RGB) => {
    const a0 = zc(x0) + off, a1 = zc(x1) + off, I: P3 = [(x0 + x1) / 2, (y0 + y1) / 2, (a0 + a1) / 2];
    k.quad([x0, y1, a0 - t / 2], [x1, y1, a1 - t / 2], [x1, y1, a1 + t / 2], [x0, y1, a0 + t / 2], col, I);
    k.quad([x0, y0, a0 - t / 2], [x1, y0, a1 - t / 2], [x1, y1, a1 - t / 2], [x0, y1, a0 - t / 2], col, I);
    k.quad([x0, y0, a0 + t / 2], [x1, y0, a1 + t / 2], [x1, y1, a1 + t / 2], [x0, y1, a0 + t / 2], col, I);
  };
  for (let i = 0; i < seg; i++) {
    const x0 = xs[i], x1 = xs[i + 1], xm = (x0 + x1) / 2, inSpill = Math.abs(xm) < spill;
    // the concrete walks outside the road, and the kerbs on the road's edge
    k.quad([x0, 0.02, zd(x0)], [x1, 0.02, zd(x1)], [x1, 0.02, -2], [x0, 0.02, -2], CONCRETE, [xm, -1, -2.5]);
    k.quad([x0, 0.02, 2], [x1, 0.02, 2], [x1, 0.02, zu(x1)], [x0, 0.02, zu(x0)], CONCRETE, [xm, -1, 2.5]);
    // the parapets
    curved(x0, x1, -D / 2 + 0.08, 0.14, 0, 0.18, CONCRETE_DK);
    curved(x0, x1, D / 2 - 0.08, 0.14, 0, 0.18, CONCRETE_DK);
    // the reservoir face: straight down under the water
    const b0 = yb(x0), b1 = yb(x1);
    k.quad([x0, Math.min(b0, deep), zu(x0)], [x1, Math.min(b1, deep), zu(x1)], [x1, 0, zu(x1)], [x0, 0, zu(x0)], CONCRETE_DK, [xm, -3, zc(xm)]);
    // the valley face, in steps, or the spillway chute down the middle
    if (!inSpill) {
      for (let s = 0; s < steps; s++) {
        const n0 = zd(x0) - s * run, n1 = zd(x1) - s * run, ya = -s * drop, yc = -(s + 1) * drop;
        const I: P3 = [xm, ya - drop, zc(xm)];
        k.quad([x0, yc, n0], [x1, yc, n1], [x1, ya, n1], [x0, ya, n0], s % 2 ? CONCRETE : scale(CONCRETE, 0.95), I);
        k.quad([x0, yc, n0], [x1, yc, n1], [x1, yc, n1 - run], [x0, yc, n0 - run], scale(CONCRETE, 1.05), I);
      }
    } else {
      k.quad([x0, -0.9, zd(x0)], [x1, -0.9, zd(x1)], [x1, 0, zd(x1)], [x0, 0, zd(x0)], CONCRETE, [xm, -1, zc(xm)]);
      k.quad([x0, deep, foot(x0)], [x1, deep, foot(x1)], [x1, -0.9, zd(x1)], [x0, -0.9, zd(x0)], hex(0xbcdce6), [xm, deep - 1, zc(xm)]);
      for (let w = 0; w < 3; w++) {
        const u0 = x0 + (x1 - x0) * (w * 0.33 + 0.05), u1 = u0 + (x1 - x0) * 0.16;
        k.quad([u0, deep + 0.02, foot(xm) - 0.03], [u1, deep + 0.02, foot(xm) - 0.03], [u1, -0.88, zd(xm) - 0.03], [u0, -0.88, zd(xm) - 0.03], WHITE, [xm, deep - 1, zc(xm)]);
      }
      // the dark mouths the water pours out of
      k.box(xm, -0.9, zd(xm) - 0.01, (x1 - x0) * 0.7, 0.55, 0.02, hex(0x2a3238));
    }
    const lo = Math.min(b0, b1);
    if (lo < deep - 0.01) k.quad([x0, b0, foot(x0)], [x1, b1, foot(x1)], [x1, deep, foot(x1)], [x0, deep, foot(x0)], CONCRETE_DK, [xm, deep, zc(xm)]);
  }
  // the kerbs along the road, straight where the dam is curved
  for (const s of [-1, 1]) k.box(0, 0, s * 2.03, W, 0.05, 0.06, CONCRETE_DK, hex(0xe8e6e0));
  // training walls either side of the chute
  for (const sx of [-spill, spill]) {
    const za = zd(sx), zf = foot(sx);
    for (const side of [-1, 1]) {
      k.quad([sx, -0.9, za], [sx, deep, zf], [sx, deep + 0.45, zf], [sx, 0, za], CONCRETE_DK, [sx + side * 0.1, -3, zc(sx)]);
    }
    k.bar([sx, 0, za], [sx, deep + 0.45, zf], 0.06, CONCRETE);
  }
  // buttresses down the valley face
  for (const bx of [-6.5, -4.5, -2.5, 2.5, 4.5, 6.5]) {
    const za = zd(bx) + 0.02, zf = foot(bx) - 0.35, yf = deep;
    for (const s of [-1, 1]) k.tri([bx + s * 0.18, 0.18, za], [bx + s * 0.18, yf, zf], [bx + s * 0.18, yf, za], CONCRETE_DK, [bx, -3, za + 0.5]);
    k.quad([bx - 0.18, 0.18, za], [bx + 0.18, 0.18, za], [bx + 0.18, yf, zf], [bx - 0.18, yf, zf], scale(CONCRETE, 0.92), [bx, -3, za + 0.5]);
  }
  // the stilling basin and the powerhouse at the foot
  const bz = foot(0) - 0.8, by = Math.max(deep, Math.min(-1, yb(0)));
  k.box(0, by, bz, 3.2, 0.05, 1.2, hex(0x7ab8c8));
  for (let i = 0; i < 7; i++) k.box(-1.2 + i * 0.4, by + 0.05, foot(0) - 0.35 - (i % 2) * 0.2, 0.3, 0.04, 0.22, WHITE);
  const phx = 3.2, phz = foot(phx) - 0.8;
  k.box(phx, by, phz, 2.4, 0.8, 1.1, hex(0xd8d4c8));
  k.box(phx, by + 0.8, phz, 2.5, 0.06, 1.2, CONCRETE_DK);
  for (let i = 0; i < 5; i++) k.pane(phx - 1 + i * 0.5, by + 0.3, phz + 0.55, 0.3, 0.36, 1, GLASS, [17, 30, 1.4], COOL_GLOW);
  for (let i = 0; i < 3; i++) k.box(phx - 0.7 + i * 0.7, by, phz - 0.85, 0.3, 0.34, 0.3, METAL);
  // spillway piers and gates on the reservoir side
  for (let i = 0; i < 4; i++) {
    const px = -spill + (i * 2 * spill) / 3, pz = zu(px);
    k.box(px, -1.8, pz + 0.3, 0.14, 1.9, 0.6, CONCRETE, CONCRETE_DK);
    if (i < 3) k.box(px + spill / 3, -1.4, pz + 0.42, (2 * spill) / 3 - 0.14, 0.5, 0.06, hex(0x5a6b72));
  }
  // the valve tower standing in the water, and its footbridge
  const vx = -4.6, vz = zu(vx) + 1.5;
  k.cyl(vx, deep, vz, 0.45, -deep + 0.55, CONCRETE, 10);
  k.cyl(vx, 0.55, vz, 0.52, 0.06, CONCRETE_DK, 10);
  k.cyl(vx, 0.61, vz, 0.36, 0.38, hex(0xe8e4d8), 10);
  k.cone(vx, 0.99, vz, 0.44, 0.24, hex(0x3f5a6b), 10);
  for (let f = 0; f < 4; f++) k.pane(vx + [0.36, 0, -0.36, 0][f], 0.72, vz + [0, 0.36, 0, -0.36][f], 0.12, 0.14, f, GLASS, [17, 30, 1.3], WARM_GLOW);
  const bzA = zu(vx) - 0.02, bzB = vz - 0.44;
  k.box(vx, 0.14, (bzA + bzB) / 2, 0.3, 0.05, bzB - bzA, CONCRETE_DK);
  for (const sx of [-0.14, 0.14]) k.box(vx + sx, 0.19, (bzA + bzB) / 2, 0.02, 0.12, bzB - bzA, METAL);
  // lamps along both parapets
  for (let x = -7; x <= 7; x += 2) {
    for (const s of [-1, 1]) {
      const lz = zc(x) + s * (D / 2 - 0.08);
      k.box(x, 0.18, lz, 0.03, 0.34, 0.03, DARK);
      k.box(x, 0.5, lz - s * 0.06, 0.02, 0.02, 0.14, DARK);
      k.glowBox(x, 0.46, lz - s * 0.12, 0.07, 0.04, 0.07, hex(0xe8e6e0), [17.5, 30.5, 1.8], WARM_GLOW);
    }
  }
  // a gatehouse kiosk at each end, clear of the road
  for (const s of [-1, 1]) {
    const gx = s * 6.9, gz = -2.45 + (s > 0 ? 0 : 0);
    k.box(gx, 0.02, Math.max(gz, zd(gx) + 0.45), 0.7, 0.34, 0.5, hex(0xe8e4d8));
    k.box(gx, 0.36, Math.max(gz, zd(gx) + 0.45), 0.8, 0.05, 0.6, hex(0x3f5a6b));
    k.pane(gx, 0.14, Math.max(gz, zd(gx) + 0.45) + 0.25, 0.4, 0.14, 1, GLASS, [17, 30, 1.3], WARM_GLOW);
  }
};

