/**
 * The soundtrack: the a.o.huge and Attention tracks from Space Train Tycoon, streamed from that
 * game's repository on GitHub rather than bundled, in the order Space Train Tycoon plays them.
 *
 * The files are served with `Access-Control-Allow-Origin: *`, so a plain audio element can stream
 * and seek them from any origin. Space Train Tycoon's own list names two of them by an older
 * numbering (02 and 07 were swapped when the files were renamed); the names here are the files
 * actually on the branch, so every track loads.
 */

const BASE = 'https://raw.githubusercontent.com/jhart90/spacetraintycoon/v0.4.6-dev/assets/';

export interface Track { file: string; title: string; artist: string }

export const TRACKS: readonly Track[] = [
  { file: '01_a.o.huge_last_train_home.mp3', title: 'Last Train Home', artist: 'a.o.huge' },
  { file: '07_a.o.huge_interstellar_segment.mp3', title: 'Interstellar Segment', artist: 'a.o.huge' },
  { file: '03_a.o.huge_star_depot_groove.mp3', title: 'Star Depot Groove', artist: 'a.o.huge' },
  { file: '04_a.o.huge_neon_katsu_sandwich.mp3', title: 'Neon Katsu Sandwich', artist: 'a.o.huge' },
  { file: '05_attention_junction.mp3', title: 'Junction', artist: 'Attention' },
  { file: '06_attention_fast_track.mp3', title: 'Fast Track', artist: 'Attention' },
  { file: '02_a.o.huge_lunar_save_point.mp3', title: 'Lunar Save Point', artist: 'a.o.huge' },
  { file: '08_a.o.huge_nebulosa_amistosa.mp3', title: 'Nebulosa Amistosa', artist: 'a.o.huge' },
  { file: '09_a.o.huge_midnight_cargo_run.mp3', title: 'Midnight Cargo Run', artist: 'a.o.huge' },
  { file: '10_attention_cosmos.mp3', title: 'Cosmos', artist: 'Attention' },
];

/** Where the listener's choices are kept: not in the save, so a new world keeps the same settings. */
const KEY = 'pocket-roads-settings';
/** A press of "previous" this far into a track starts it again rather than going back one. */
const RESTART_AFTER = 5;

/** What happens at the end of a track: stop after the last one, wrap round, or play it again. */
export type Loop = 'none' | 'all' | 'one';
const LOOPS: readonly Loop[] = ['none', 'all', 'one'];

/** One track's listening this page load: starts, seconds heard, skipped (next before its end), played through. */
export type TrackStats = [number, number, number, number];
/**
 * What the listener did this page load, for the play reports (the dev page's Analytics → Music): seconds the
 * music was heard, paused by choice, and playing but muted; presses; and each track's starts and seconds.
 */
export interface MusicStats {
  heard: number; paused: number; muted: number;
  pauses: number; resumes: number; skips: number; backs: number; picks: number; mutes: number;
  tracks: Record<string, TrackStats>;
  now: { playing: boolean; paused: boolean; muted: boolean; volume: number; shuffle: boolean; loop: Loop };
}

interface Stored { volume: number; muted: boolean; paused: boolean; track: number; loop: Loop; shuffle: boolean }

/**
 * One audio element walking the playlist, in order or shuffled, and at the end of it stopping,
 * wrapping round or repeating the one track. Browsers only allow sound after the player has done
 * something, so it waits for the first key or click before starting, and then remembers whether the
 * player paused it, so it stays paused next time too.
 */
export class Soundtrack {
  readonly audio = new Audio();
  index = 0;
  volume = 0.35;
  muted = false;
  /** The player's own choice to pause, as opposed to not having started yet. */
  paused = false;
  loop: Loop = 'all';
  shuffle = false;
  /** Shuffled: the tracks still to come this time round, so none repeats until all have played. */
  private upcoming: number[] = [];
  /** Shuffled: the tracks already played, most recent last, for "previous" to walk back through. */
  private history: number[] = [];
  private started = false;
  private listeners = new Set<() => void>();
  private tally: Omit<MusicStats, 'now'> = { heard: 0, paused: 0, muted: 0, pauses: 0, resumes: 0, skips: 0, backs: 0, picks: 0, mutes: 0, tracks: {} };
  private trackListeners = new Set<(t: Track) => void>();
  /** The file last announced as starting, so a pause and play again isn't a new track. */
  private heard = '';

  constructor() {
    this.audio.preload = 'metadata';
    try {
      const s = JSON.parse(localStorage.getItem(KEY) ?? 'null') as Partial<Stored> | null;
      if (s) {
        if (typeof s.volume === 'number') this.volume = Math.min(1, Math.max(0, s.volume));
        this.muted = !!s.muted;
        this.paused = !!s.paused;
        if (typeof s.track === 'number') this.index = ((s.track % TRACKS.length) + TRACKS.length) % TRACKS.length;
        if (s.loop && LOOPS.includes(s.loop)) this.loop = s.loop;
        this.shuffle = !!s.shuffle;
      }
    } catch { /* no stored settings: the defaults stand */ }
    this.apply();
    if (this.shuffle) this.deal();
    // loop-one never ends: the element loops itself (see apply)
    this.audio.addEventListener('ended', () => { this.trackTally()[3]++; this.advance(false); });
    // a new track has really started (not paused and resumed): told once, for the now-playing card
    this.audio.addEventListener('playing', () => {
      if (this.audio.src === this.heard) return;
      this.heard = this.audio.src;
      for (const fn of this.trackListeners) fn(this.track);
    });
    for (const ev of ['play', 'pause', 'timeupdate', 'loadedmetadata', 'durationchange']) {
      this.audio.addEventListener(ev, () => this.emit());
    }
    // the first key or click anywhere is the gesture that lets the music start
    // (a controller's presses arrive as keys too, but a browser doesn't count them as a gesture)
    const begin = (e: Event) => {
      if (!e.isTrusted) return;
      window.removeEventListener('keydown', begin, true);
      window.removeEventListener('mousedown', begin, true);
      this.start();
    };
    window.addEventListener('keydown', begin, true);
    window.addEventListener('mousedown', begin, true);
    // a second at a time while the page is in view and the music has begun: heard, muted, or paused
    window.setInterval(() => {
      if (!this.started || document.hidden) return;
      if (this.audio.paused) { if (this.paused) this.tally.paused++; return; }
      if (this.muted || this.volume === 0) { this.tally.muted++; return; }
      this.tally.heard++;
      this.trackTally()[1]++;
    }, 1000);
    this.onTrack(() => { this.trackTally()[0]++; });
  }

  private trackTally(): TrackStats {
    return (this.tally.tracks[this.track.title] ??= [0, 0, 0, 0]);
  }

  /** This page load's listening so far, and how the player has it set now. */
  stats(): MusicStats {
    return {
      ...this.tally, tracks: Object.fromEntries(Object.entries(this.tally.tracks).map(([k, v]) => [k, [...v] as TrackStats])),
      now: { playing: this.playing, paused: this.paused, muted: this.muted, volume: Math.round(this.volume * 100) / 100, shuffle: this.shuffle, loop: this.loop },
    };
  }

  get track(): Track { return TRACKS[this.index]; }
  get playing(): boolean { return !this.audio.paused; }

  /** Called whenever anything the menu shows has changed. */
  onChange(fn: () => void): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  /** Called each time a different track starts playing. */
  onTrack(fn: (t: Track) => void): () => void {
    this.trackListeners.add(fn);
    return () => this.trackListeners.delete(fn);
  }

  private emit(): void { for (const fn of this.listeners) fn(); }

  private start(): void {
    if (this.started) return;
    this.started = true;
    this.load(this.index);
    if (!this.paused) this.play();
  }

  private load(i: number): void {
    this.index = ((i % TRACKS.length) + TRACKS.length) % TRACKS.length;
    this.audio.src = BASE + TRACKS[this.index].file;
    this.store();
    this.emit();
  }

  private play(): void {
    this.audio.play().catch(() => { /* blocked or offline: the next gesture tries again */ });
  }

  togglePause(): void {
    if (!this.started) { this.started = true; this.load(this.index); }
    if (this.audio.paused) { this.paused = false; this.play(); this.tally.resumes++; }
    else { this.paused = true; this.audio.pause(); this.tally.pauses++; }
    this.store();
    this.emit();
  }

  next(): void {
    // skipped: moved on before the track ran out
    if (this.audio.src && !this.audio.ended) { this.tally.skips++; this.trackTally()[2]++; }
    this.advance(true);
  }

  /** Straight to track `i` of the list, playing (a shuffle carries on from it afterwards). */
  choose(i: number): void {
    this.started = true;
    this.tally.picks++;
    if (i === this.index && this.audio.src) {
      if (this.audio.paused) this.togglePause();
      return;
    }
    if (this.shuffle) {
      this.history.push(this.index);
      this.upcoming = this.upcoming.filter((u) => u !== i);
    }
    this.paused = false;
    this.load(i);
    this.play();
  }

  /**
   * On to the next track, in order or from the shuffle. Pressing "next" always moves on, wrapping at
   * the end; a track running out with the loop off stops at the end of the list instead, back on the
   * first track (or a fresh shuffle) and ready to play.
   */
  private advance(pressed: boolean): void {
    this.started = true;
    let stop = false;
    if (this.shuffle) {
      if (!this.upcoming.length) {
        stop = !pressed && this.loop === 'none';
        this.deal();
      }
      this.history.push(this.index);
      this.load(this.upcoming.shift()!);
    } else {
      stop = !pressed && this.loop === 'none' && this.index === TRACKS.length - 1;
      this.load(this.index + 1);
    }
    if (!stop && !this.paused) this.play();
  }

  previous(): void {
    this.started = true;
    this.tally.backs++;
    if (this.audio.src && this.audio.currentTime > RESTART_AFTER) this.audio.currentTime = 0;
    else if (this.shuffle) {
      // back through what the shuffle played, putting this one back at the head of what's to come
      if (this.history.length) { this.upcoming.unshift(this.index); this.load(this.history.pop()!); }
      else this.audio.currentTime = 0;
    } else this.load(this.index - 1);
    if (!this.paused) this.play();
    this.emit();
  }

  /** Off, all, one, and round again. */
  cycleLoop(): void {
    this.loop = LOOPS[(LOOPS.indexOf(this.loop) + 1) % LOOPS.length];
    this.apply();
    this.store();
    this.emit();
  }

  toggleShuffle(): void {
    this.shuffle = !this.shuffle;
    this.history = [];
    this.upcoming = [];
    if (this.shuffle) this.deal();
    this.store();
    this.emit();
  }

  /** A fresh shuffled round of every track but the one playing (Fisher–Yates). */
  private deal(): void {
    const a = TRACKS.map((_, i) => i).filter((i) => i !== this.index);
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    this.upcoming = a;
  }

  /** Seek to a share (0..1) of the way through the current track. */
  seek(share: number): void {
    const d = this.audio.duration;
    if (Number.isFinite(d) && d > 0) this.audio.currentTime = Math.min(d - 0.05, Math.max(0, share * d));
    this.emit();
  }

  setVolume(v: number): void {
    this.volume = Math.min(1, Math.max(0, v));
    if (this.volume > 0 && this.muted) this.muted = false;
    this.apply();
    this.store();
    this.emit();
  }

  toggleMute(): void {
    this.muted = !this.muted;
    if (this.muted) this.tally.mutes++;
    this.apply();
    this.store();
    this.emit();
  }

  private apply(): void {
    this.audio.volume = this.volume;
    this.audio.muted = this.muted;
    this.audio.loop = this.loop === 'one';
  }

  private store(): void {
    try {
      const s: Stored = {
        volume: this.volume, muted: this.muted, paused: this.paused, track: this.index,
        loop: this.loop, shuffle: this.shuffle,
      };
      localStorage.setItem(KEY, JSON.stringify(s));
    } catch { /* storage blocked: settings just won't outlive the tab */ }
  }
}
