import { hex, scale, type RGB } from '../../../world/biomes';
import type { Rng } from '../../../world/rng';
import type { BuildingKind } from '../../../world/tiles';
import { FLOOR } from '../../../world/towns';
import type { Sched } from '../../nightLights';
import {
  DARK, GLASS_LIGHT, ROOF_GREY, STONE, WHITE, balcony, corners, cur, doorcase, engawa, flatTop, pick, porch, roofOver,
  styleRoof, styleTrim, styleWall, veranda, win, type Draw, type Kit, type P3,
} from '../kit';

/**
 * Alternatives to the two commonest homes in any town: the little house (about fifty to a cell) and
 * the townhouse that stands shoulder to shoulder in the city rows. Each keeps the original's lot, its
 * height class and its style (the same `cur` branches as `styledHouse` and `styledBlock`), and changes
 * the plan and the roofline, so a street of them reads as a street and not one house over and over.
 */

const DOORS = [0x5a3a28, 0x2f4d7a, 0x8a3a34, 0x3f5a3f];
const DRIVE = hex(0xbdb6a8);

/** The porch lamp by a front door: on through the evening, some all night. */
const lamp = (r: Rng): Sched => [17.3 + r() * 0.8, r() < 0.5 ? 30 : 23 + r(), 2.2];

/** A front door on the wall facing +z at `z`, with the style's doorcase round it and a lamp beside it (on the `s` side). */
function frontDoor(k: Kit, r: Rng, x: number, z: number, s: number): void {
  k.box(x, 0, z + 0.01, 0.1, 0.19, 0.02, pick(r, cur.doors ?? DOORS));
  if (cur.doorcase !== undefined) doorcase(k, x, z + 0.02, 0.1, 0.19, hex(cur.doorcase));
  k.glowBox(x + s * 0.08, 0.16, z + 0.02, 0.03, 0.04, 0.03, WHITE, lamp(r), hex(cur.glow ?? 0xffc978));
}

/** The roof form a house takes: the style's own, or half the time its second form. */
const houseForm = (r: Rng) => (cur.form && cur.alt && r() < 0.5 ? cur.alt : cur.form);

/** Which way a side wall faces: +x (0) or -x (2). */
const side = (sx: number) => (sx > 0 ? 0 : 2);

// ---- house ------------------------------------------------------------------------------------

/**
 * An L-plan house: a block across the back of the lot, a gabled wing stepping out toward the street on
 * one side with its gable end to the road, and a porch in the angle between them over the front door.
 */
const crossGable: Draw = (k, _W, _D, b, r) => {
  // drawn in the order styledHouse rolls, so this is two storeys (or flat) wherever the original would be
  const wall = styleWall(r), roof = styleRoof(r);
  const two = r() < (cur.balcony ? 0.45 : 0.3), h = two ? 0.5 : 0.3, form = houseForm(r);
  const s = r() < 0.5 ? 1 : -1;
  const mz = -0.18, mw = 0.72, md = 0.3, mf = mz + md / 2;
  const wx = -s * 0.2, wz = -0.06, ww = 0.3, wd = 0.5, wf = wz + wd / 2;
  // under a flat roof the wing is a terrace off the main block's parapet (a second parapet and its beams cost too much)
  const wtop = form === 'flat' ? scale(roof, 0.96) : wall;
  if (cur.plinth && two) {
    const stone = pick(r, cur.plinth);
    k.box(0, 0, mz, mw, FLOOR, md, stone);
    k.box(wx, 0, wz, ww, FLOOR, wd, stone);
    k.box(0, FLOOR, mz, mw, h - FLOOR, md, wall);
    k.box(wx, FLOOR, wz, ww, h - FLOOR, wd, wall, wtop);
  } else {
    k.box(0, 0, mz, mw, h, md, wall);
    k.box(wx, 0, wz, ww, h, wd, wall, wtop);
  }
  if (form && cur.massing === 'ribbed') corners(k, wx, wz, ww, wd, h);
  let top: number;
  if (form) {
    top = roofOver(k, r, 0, h, mz, mw, md, wall, roof, form);
    if (form !== 'flat') top = Math.max(top, roofOver(k, r, wx, h, wz, ww, wd, wall, roof, form));
  } else {
    const rh = cur.pitch * 0.9, ov = cur.eaves;
    if (cur.pitch <= 0.4 && r() < 0.3) {
      k.hip(0, h, mz, mw + ov, rh * 0.85, md + ov + 0.02, roof);
      k.hip(wx, h, wz, ww + ov, rh * 0.85, wd + ov, roof);
    } else {
      k.gable(0, h, mz, mw + ov, rh, md + ov + 0.02, roof, wall);
      k.gable(wx, h, wz, ww + ov, rh, wd + ov, roof, wall, true);
    }
    if (cur.course > 0.45) k.box(wx, h - 0.02, wz, ww + 0.035, 0.022, wd + 0.035, styleTrim());
    top = h + rh;
  }
  // the angle between the wing and the back block: the front door, under a porch
  const px = s * 0.155, pw = 0.39, dx = s * 0.07;
  if (cur.massing === 'veranda') veranda(k, r, 0, 0, mz, mw, md, 0.24);
  else if (cur.massing === 'porch') porch(k, r, px, 0, mz, pw, md, 0.24);
  else if (cur.engawa !== undefined) engawa(k, 0, mz, mw, md, two, roof);
  else {
    k.box(px, 0.22, mf + 0.09, pw + 0.02, 0.025, 0.2, roof);
    k.box(s * 0.33, 0.03, mf + 0.16, 0.025, 0.19, 0.025, styleTrim());
  }
  frontDoor(k, r, dx, mf, s);
  win(k, b, r, s * 0.25, 0.1, mf, 0.13, 0.1, 1);
  win(k, b, r, wx, 0.1, wf, 0.14, 0.1, 1);
  if (two) {
    win(k, b, r, wx, 0.33, wf, 0.14, 0.1, 1);
    win(k, b, r, s * 0.2, 0.33, mf, 0.14, 0.1, 1);
    if (cur.balcony) balcony(k, wx, FLOOR, wf, ww * 0.7, 1);
  }
  if (cur.chimney) {
    const [ch, col] = cur.chimney;
    k.box(s * 0.26, h, mz - 0.05, 0.07, Math.max(ch, top - h + 0.08), 0.07, hex(col));
  } else if (!form && r() < 0.4) k.box(s * 0.26, h, mz - 0.06, 0.07, 0.3, 0.07, hex(0x8a7d70));
};

/**
 * A tall narrow house turned gable-end to the street: two storeys under a steep roof with a little attic
 * window in the gable, a bay window beside the door, and a low wing on the other side, a garage or a
 * room with its own window.
 */
const tallGable: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r), form = houseForm(r);
  const s = r() < 0.5 ? 1 : -1;
  const h = 0.46, bx = -s * 0.13, bz = -0.07, bw = 0.4, bd = 0.54, front = bz + bd / 2;
  if (cur.plinth) {
    k.box(bx, 0, bz, bw, FLOOR, bd, pick(r, cur.plinth));
    k.box(bx, FLOOR, bz, bw, h - FLOOR, bd, wall);
  } else k.box(bx, 0, bz, bw, h, bd, wall);
  if (form && cur.massing === 'ribbed') corners(k, bx, bz, bw, bd, h);
  let top: number;
  if (form) top = roofOver(k, r, bx, h, bz, bw, bd, wall, roof, form);
  else {
    const rh = Math.max(0.22, cur.pitch * 1.05);
    k.gable(bx, h, bz, bw + cur.eaves, rh, bd + cur.eaves, roof, wall, true);
    if (cur.course > 0.45) k.box(bx, FLOOR - 0.01, bz, bw + 0.03, 0.02, bd + 0.03, styleTrim());
    top = h + rh;
  }
  // the attic window, on whatever gable end faces the street
  const attic = !form ? bz + (bd + cur.eaves) / 2 : form === 'gable' || form === 'low' ? front + cur.eaves : form === 'dutch' ? front + 0.012 : NaN;
  if (!Number.isNaN(attic)) win(k, b, r, bx, h + 0.035, attic, 0.09, 0.08, 1);
  const dx = bx + s * 0.1, bayx = bx - s * 0.08;
  frontDoor(k, r, dx, front, s);
  if (cur.plinth || form === 'flat' || cur.engawa !== undefined || r() < 0.3) win(k, b, r, bayx, 0.1, front, 0.14, 0.1, 1);
  else {
    k.box(bayx, 0, front + 0.04, 0.18, 0.2, 0.08, wall, roof);
    win(k, b, r, bayx, 0.07, front + 0.08, 0.13, 0.1, 1);
  }
  win(k, b, r, bx, 0.33, front, 0.16, 0.1, 1);
  // shutters cost as much as the window again, so a shuttered house leaves its side wall blank
  if (!cur.shutter) win(k, b, r, bx - s * bw / 2, 0.33, bz, 0.12, 0.1, side(-s));
  if (cur.balcony && r() < 0.5) balcony(k, bx, FLOOR, front, bw * 0.7, 1);
  if (cur.massing === 'veranda') veranda(k, r, bx, 0, bz, bw, bd, 0.24);
  if (cur.massing === 'porch') porch(k, r, bx, 0, bz, bw, bd, 0.24);
  if (cur.engawa !== undefined) engawa(k, bx, bz, bw, bd, true, roof);
  // the low wing: a garage onto the drive, or a room
  const ver = cur.massing === 'veranda', ww = ver ? 0.26 : 0.32, wx = s * (ver ? 0.29 : 0.26), wz = -0.08, wd = 0.42, wh = 0.24;
  const flat = form === 'flat', ow = scale(wall, 0.94), wf = wz + wd / 2;
  k.box(wx, 0, wz, ww, wh, wd, ow, flat ? scale(roof, 0.96) : roof);
  if (!flat && form !== 'dutch' && form !== 'false') k.hip(wx, wh, wz, ww + 0.04, 0.1, wd + 0.04, roof);
  if (r() < 0.5) {
    k.box(wx, 0, wf + 0.005, ww * 0.72, 0.16, 0.02, flat && cur.doors ? hex(cur.doors[0]) : WHITE);
    k.box(wx, 0.002, wf + 0.17, ww * 0.8, 0.01, 0.32, DRIVE);
  } else win(k, b, r, wx, 0.08, wf, 0.15, 0.1, 1);
  if (cur.chimney) {
    const [ch, col] = cur.chimney;
    k.box(bx, h, bz - bd / 2 + 0.08, 0.07, Math.max(ch, top - h + 0.06), 0.07, hex(col));
  } else if (!form && r() < 0.45) k.box(bx - s * (bw / 2 + 0.03), 0, bz - 0.1, 0.07, top + 0.06, 0.08, hex(0x8a7d70));
};

/**
 * A wide low house across the lot: one long storey under a side-gabled roof, either a Cape with a steep
 * roof and two dormers over a centred door, or a shallow-roofed ranch with a picture window; an
 * attached garage steps down at one end and a chimney stands at the other.
 */
const ranch: Draw = (k, _W, _D, b, r) => {
  // the Cape (the heavier of the two) is rolled where the original rolls its second storey
  const wall = styleWall(r), roof = styleRoof(r), cape = r() < 0.4, form = houseForm(r);
  const s = r() < 0.5 ? 1 : -1;
  const ver = cur.massing === 'veranda';
  const h = 0.28, bw = ver ? 0.62 : 0.56, bx = ver ? 0 : -s * 0.12, bz = -0.08, bd = 0.44, front = bz + bd / 2;
  k.box(bx, 0, bz, bw, h, bd, wall);
  if (form && cur.massing === 'ribbed') corners(k, bx, bz, bw, bd, h);
  let top: number, rh = 0, D = 0;
  if (form) {
    top = roofOver(k, r, bx, h, bz, bw, bd, wall, roof, form);
    if (form === 'gable') { rh = Math.min(0.62, bd * cur.pitch * 0.9); D = bd + 2 * cur.eaves; }
  } else {
    rh = cape ? Math.max(0.26, cur.pitch * 1.2) : Math.max(0.12, cur.pitch * 0.55);
    D = bd + cur.eaves + 0.02;
    if (cape || cur.pitch > 0.4) k.gable(bx, h, bz, bw + cur.eaves, rh, D, roof, wall);
    else { k.hip(bx, h, bz, bw + cur.eaves + 0.04, rh, bd + cur.eaves + 0.06, roof); rh = 0; }
    if (cur.course > 0.45) k.box(bx, h - 0.02, bz, bw + 0.035, 0.022, bd + 0.035, styleTrim());
    top = h + Math.max(rh, 0.12);
  }
  if (cape) {
    // a centred door between two windows, and a dormer over each window where the roof is steep enough
    frontDoor(k, r, bx, front, s);
    for (const o of [-0.17, 0.17]) {
      win(k, b, r, bx + o, 0.1, front, 0.12, 0.1, 1);
      if (rh > 0.2) {
        // its face stands where the slope is halfway up, its back buried in the roof
        const uf = D * 0.25, y0 = h + rh * 0.5 - 0.04, dz = bz + (uf + 0.04) / 2;
        k.box(bx + o, y0, dz, 0.13, 0.1, uf - 0.04, wall);
        k.gable(bx + o, y0 + 0.1, dz, 0.15, 0.045, uf - 0.03, roof, wall, true);
        win(k, b, r, bx + o, y0 + 0.045, bz + uf, 0.07, 0.045, 1);
      }
    }
  } else {
    frontDoor(k, r, bx + s * 0.16, front, -s);
    win(k, b, r, bx - s * 0.08, 0.08, front, 0.26, 0.12, 1, GLASS_LIGHT);
  }
  win(k, b, r, bx - s * bw / 2, 0.1, bz, 0.12, 0.1, side(-s));
  if (ver) veranda(k, r, bx, 0, bz, bw, bd, 0.24);
  else {
    if (cur.massing === 'porch') porch(k, r, bx, 0, bz, bw, bd, 0.24);
    // the garage, a step down from the house
    const gx = s * 0.29, gw = 0.26, gz = -0.06, gd = 0.4, gh = 0.22, gf = gz + gd / 2;
    const flat = form === 'flat', gwall = scale(wall, 0.94);
    k.box(gx, 0, gz, gw, gh, gd, gwall, flat ? scale(roof, 0.96) : roof);
    if (!form || form === 'gable' || form === 'low') k.gable(gx, gh, gz, gw + 0.04, Math.min(0.2, 0.06 + cur.pitch * 0.2), gd + 0.06, roof, gwall);
    else if (!flat && form !== 'dutch' && form !== 'false') k.hip(gx, gh, gz, gw + 0.04, 0.1, gd + 0.04, roof);
    k.box(gx, 0, gf + 0.005, 0.2, 0.16, 0.02, flat && cur.doors ? hex(cur.doors[0]) : WHITE);
    k.box(gx, 0.002, gf + 0.16, 0.22, 0.01, 0.3, DRIVE);
  }
  if (cur.engawa !== undefined) engawa(k, bx, bz, bw, bd, false, roof);
  const cx = bx - s * (bw / 2 - 0.07);
  if (cur.chimney) {
    const [ch, col] = cur.chimney;
    k.box(cx, h, bz - 0.06, 0.07, Math.max(ch, top - h + 0.08), 0.07, hex(col));
  } else if (!form && r() < 0.7) k.box(cx, h, bz - 0.06, 0.08, Math.max(rh, 0.12) + 0.1, 0.08, hex(0x8a7d70));
};

// ---- townhouse --------------------------------------------------------------------------------

/**
 * A townhouse body in one of the biomes' styles, without its roof or balconies (each front places its
 * own): the plinth, the corner ribs, a veranda, porch or engawa. The walls fill the lot's width, as the
 * row it stands in needs.
 */
function townBody(k: Kit, r: Rng, wall: RGB, h: number, floors: number, top: RGB = wall): void {
  const w = 0.84, d = 0.8, z = -0.04;
  if (cur.plinth && floors > 1) {
    k.box(0, 0, z, w, FLOOR, d, pick(r, cur.plinth));
    k.box(0, FLOOR, z, w, h - FLOOR, d, wall, top);
  } else k.box(0, 0, z, w, h, d, wall, top);
  if (cur.massing === 'ribbed') corners(k, 0, z, w, d, h);
  if (cur.massing === 'veranda') veranda(k, r, 0, 0, z, w, d, FLOOR * 0.92);
  if (cur.massing === 'porch') porch(k, r, 0, 0, z, w, d, FLOOR * 0.92);
  if (cur.engawa !== undefined) engawa(k, 0, z, w, d, floors > 1, styleRoof(r));
}

/** The ground floor is taken by a veranda, porch or engawa, so nothing may stand out from it. */
const groundTaken = () => cur.massing === 'veranda' || cur.massing === 'porch' || cur.engawa !== undefined;

/** A block whose four sides lean in by `inset` over its height: the steep lower slopes of a mansard. */
function mansard(k: Kit, x: number, y: number, z: number, w: number, d: number, h: number, inset: number, sides: RGB, top: RGB): void {
  const x0 = x - w / 2, x1 = x + w / 2, z0 = z - d / 2, z1 = z + d / 2;
  const X0 = x0 + inset, X1 = x1 - inset, Z0 = z0 + inset, Z1 = z1 - inset, yt = y + h;
  const I: P3 = [x, y + h / 2, z];
  k.quad([X0, yt, Z0], [X1, yt, Z0], [X1, yt, Z1], [X0, yt, Z1], top, I);
  k.quad([x0, y, z1], [x1, y, z1], [X1, yt, Z1], [X0, yt, Z1], sides, I);
  k.quad([x0, y, z0], [x1, y, z0], [X1, yt, Z0], [X0, yt, Z0], sides, I);
  k.quad([x1, y, z0], [x1, y, z1], [X1, yt, Z1], [X1, yt, Z0], sides, I);
  k.quad([x0, y, z0], [x0, y, z1], [X0, yt, Z1], [X0, yt, Z0], sides, I);
}

/** The style's chimney on a townhouse roof, where the style has one. */
function townChimney(k: Kit, x: number, h: number): void {
  if (cur.chimney) k.box(x, h, -0.3, 0.08, cur.chimney[0] + 0.1, 0.08, hex(cur.chimney[1]));
}

/**
 * A townhouse with a bay window running up one side of its front and, in the old styles, a mansard
 * storey on top: steep slate sides and a flat lead top, the bay carrying on up through it as a dormer.
 * Modern styles take a flat roof instead; the biomes' styles their own roof over the bay.
 */
const bayMansard: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r), floors = b.floors, h = floors * FLOOR, z = -0.04, front = 0.36;
  const s = r() < 0.5 ? 1 : -1, bx = s * 0.2, ox = -s * 0.2;
  const y0 = groundTaken() ? FLOOR : 0;
  if (cur.form) townBody(k, r, wall, h, floors);
  else k.box(0, 0, z, 0.84, h, 0.8, wall, ROOF_GREY);
  k.box(bx, y0, front + 0.04, 0.3, h - y0 - 0.02, 0.08, wall, roof);
  for (let f = 0; f < floors; f++) {
    const y = 0.08 + f * FLOOR;
    if (f * FLOOR >= y0) win(k, b, r, bx, y, front + 0.08, 0.2, 0.13, 1);
    else win(k, b, r, bx, y, front, 0.14, 0.13, 1);
    if (f === 0) k.box(ox, 0, front + 0.005, 0.14, 0.2, 0.02, cur.doors ? pick(r, cur.doors) : DARK);
    else win(k, b, r, ox, y, front, 0.14, 0.13, 1);
  }
  if (cur.form) {
    roofOver(k, r, 0, h, z, 0.84, 0.8, wall, roof);
    if (cur.balcony && floors >= cur.balcony.min) for (let f = 1; f < floors; f++) balcony(k, ox, f * FLOOR, front, 0.3, 1);
    townChimney(k, -bx * 1.5, h);
  } else if (cur.crown === 'flat') {
    k.box(0, h, front - 0.02, 0.86, 0.06, 0.06, styleTrim());
  } else {
    const slate = styleRoof(r);
    mansard(k, 0, h, z, 0.88, 0.84, 0.22, 0.09, slate, ROOF_GREY);
    k.box(bx, h, front - 0.02, 0.22, 0.15, 0.08, styleTrim(), slate);
    win(k, b, r, bx, h + 0.03, front + 0.02, 0.14, 0.1, 1);
  }
};

/**
 * A brownstone: a flat roof behind a heavy projecting cornice, three narrow windows a floor, and a stoop
 * of steps up to a door raised over the basement. Under the biomes' styles the cornice carries their
 * roof, and a stoop is still how you get in.
 */
const stoopFront: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r), floors = b.floors, h = floors * FLOOR, z = -0.04, front = 0.36;
  const s = r() < 0.5 ? 1 : -1;
  // framed and shuttered windows cost more, so those styles keep two a floor
  const xs = cur.frame !== undefined || cur.shutter ? [-0.2, 0.2] : [-0.27, 0, 0.27], dx = s * xs[xs.length - 1];
  const ww = xs.length === 3 ? 0.12 : 0.14;
  if (cur.form) townBody(k, r, wall, h, floors);
  else k.box(0, 0, z, 0.84, h, 0.8, wall, ROOF_GREY);
  const stoop = !groundTaken(), lift = stoop ? 0.08 : 0;
  if (stoop) k.wedge(dx, 0, front + 0.06, 0.17, lift, -0.12, pick(r, cur.plinth ?? STONE));
  k.box(dx, lift, front + 0.005, 0.12, 0.19, 0.02, cur.doors ? pick(r, cur.doors) : DARK);
  for (let f = 0; f < floors; f++) {
    for (const x of xs) if (f > 0 || x !== dx) win(k, b, r, x, 0.1 + f * FLOOR, front, ww, 0.14, 1);
  }
  if (cur.balcony && floors >= cur.balcony.min) for (let f = 1; f < floors; f++) balcony(k, xs.length === 3 ? 0 : -dx, f * FLOOR, front, 0.26, 1);
  const flat = !cur.form || cur.form === 'flat';
  if (cur.form === 'flat') flatTop(k, r, 0, h, z, 0.84, 0.8, wall);
  k.box(0, h - (flat ? 0.05 : 0.03), front + 0.03, 0.9, flat ? 0.07 : 0.04, 0.1, styleTrim());
  if (!flat) roofOver(k, r, 0, h, z, 0.84, 0.8, wall, roof);
  else if (r() < 0.5) k.box(-dx * 0.7, h, -0.22, 0.22, 0.14, 0.2, scale(wall, 0.9), ROOF_GREY);
  townChimney(k, -dx, h);
};

/**
 * A gable-fronted townhouse. In the old styles a steep roof turned end-on to the street behind a tall
 * front that steps in once toward the top (or rises in a narrow neck), coped in the trim colour, with an
 * attic window and now and then an iron balcony; in the biomes' styles the top storey steps back behind
 * a railed roof terrace, under the style's own roof.
 */
const gableFront: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r), floors = b.floors, z = -0.04, front = 0.36;
  const door = cur.doors ? pick(r, cur.doors) : DARK;
  if (!cur.form) {
    const h = floors * FLOOR, gh = Math.max(0.26, cur.pitch * 0.7), step = r() < 0.5, tw = step ? 0.5 : 0.3;
    k.box(0, 0, z, 0.84, h, 0.8, wall, ROOF_GREY);
    k.gable(0, h, z - 0.02, 0.84, gh, 0.76, roof, wall, true);
    k.box(0, h, front - 0.025, 0.84, gh * 0.5, 0.05, wall);
    k.box(0, h + gh * 0.5, front - 0.025, tw, gh * 0.5 + 0.06, 0.05, wall);
    k.box(0, h + gh + 0.06, front - 0.03, tw + 0.04, 0.025, 0.07, styleTrim());
    win(k, b, r, 0, h + gh * 0.5 + 0.03, front, 0.1, 0.1, 1);
    for (let f = 0; f < floors; f++) {
      for (const sx of [-0.2, 0.2]) {
        if (f === 0 && sx > 0) k.box(sx, 0, 0.365, 0.14, 0.2, 0.02, door);
        else win(k, b, r, sx, 0.08 + f * FLOOR, front, 0.14, 0.13, 1);
      }
    }
    if (r() < 0.5) k.box(0, FLOOR, front + 0.035, 0.56, 0.06, 0.07, hex(0x2c2f33));
    return;
  }
  const lower = Math.max(1, floors - 1), h1 = lower * FLOOR, tz = -0.11, td = 0.66, tf = tz + td / 2;
  townBody(k, r, wall, h1, lower, scale(pick(r, cur.plinth ?? STONE), 0.95));
  k.box(0, h1, tz, 0.84, FLOOR, td, wall);
  roofOver(k, r, 0, h1 + FLOOR, tz, 0.84, td, wall, roof);
  k.box(0, h1, front - 0.015, 0.84, 0.05, 0.03, cur.balcony ? hex(cur.balcony.rail) : styleTrim());
  for (let f = 0; f < lower; f++) {
    for (const sx of [-0.2, 0.2]) {
      if (f === 0 && sx > 0) k.box(sx, 0, 0.365, 0.14, 0.2, 0.02, door);
      else win(k, b, r, sx, 0.08 + f * FLOOR, front, 0.14, 0.13, 1);
    }
  }
  for (const sx of [-0.2, 0.2]) win(k, b, r, sx, h1 + 0.08, tf, 0.14, 0.13, 1);
  townChimney(k, 0.3, h1 + FLOOR);
};

export const HOUSE_VARIANTS: Partial<Record<BuildingKind, Draw[]>> = {
  house: [crossGable, tallGable, ranch],
  townhouse: [bayMansard, stoopFront, gableFront],
};
