import * as THREE from 'three';
import { buildVehicleMesh, disposeVehicleMesh, poseVehicleMesh, type VehicleMesh } from '../render/vehicleMeshes';
import type { World } from '../world/tiles';
import type { VehicleDef, VehicleState } from './vehicles';
import { railThumb } from './garageMenu';

/**
 * The fleet dock, beside the speedo: a square with your own vehicle in it under YOU, and a square for
 * each of the fleet's slots under YOUR FLEET. Each shows its vehicle in 3D, turned the way the camera
 * sees it, on a pastel of the fleet's colour; an empty slot stands empty. After the last slot comes one
 * more, dashed with a + in it: the next slot, not yet opened, whose tooltip says what opens it. Every vehicle out on the map
 * (anything not in the garage) takes the leftmost free slot and keeps it until it goes into the garage
 * or is sold. Click your square to come back to your own car; click a fleet square to follow that one.
 * There are as many fleet squares as the fleet has slots: one without an HQ.
 *
 * The dock is also where the fleet is run from, without putting anything more on screen until it is
 * reached for (game/fleetPanel.ts writes what is shown). Hovering a fleet square peeks at its bubble:
 * the driver, what they are doing, what they have made, and their Work/Follow pair. Clicking it follows
 * that unit and pins the bubble until the camera comes back. Hovering the YOUR FLEET label peeks at the
 * tray (the whole fleet's line and switches, the bench, where you stand); clicking the label pins it
 * until Esc or a click elsewhere. A square wears a small corner icon while its unit follows, is towed
 * or waits at a slip.
 *
 * One small renderer draws every square, each into its own viewport of one canvas laid over the row.
 *
 * Once the fleet has an HQ, one more square stands left of YOU, under HQ: a picture of the HQ building
 * (a still from the hero stage, set by main.ts) that opens the HQ window (the user, 7 Oct 2026).
 */

/** Fleet slots to begin with: one, until the fleet has an HQ (game/fleet.ts `slots`). */
const FLEET_SLOTS = 1;

/** What a square shows: the model as built for this unit, and where it is (null: standing, facing `heading`). */
export interface DockView {
  uid: number;
  name: string;
  def: VehicleDef;
  state: VehicleState | null;
  heading: number;
  w: World | null;
  /** Who is at the wheel, first name only, for the plate on the square's bottom edge (none: no plate). */
  driver?: string;
}

interface Shown {
  def: VehicleDef;
  mesh: VehicleMesh;
  /** A train's engine stood in the square (garageMenu railThumb): its cars share the trains' geometry, so never disposed. */
  rail?: boolean;
  /** The model's bounding sphere at rest: how far the camera stands back, and what it looks at. */
  radius: number;
  mid: THREE.Vector3;
}

/** A state for a vehicle standing still at the origin, for one the dock has no live state for. */
const still = (heading: number): VehicleState => ({
  x: 0, y: 0, z: 0, heading, v: 0, pitch: 0, roll: 0, bob: 0, lean: 0, wheelSpin: 0, steerVis: 0, power: 0, blocked: 0,
  trailerHeading: heading, sailAngle: 0, surfaceY: NaN, step() { /* never driven */ }, status: () => '',
});

/** Milliseconds between one float and the next from the same square: the first is well clear by then. */
const RISE_GAP = 900;

export class FleetDock {
  readonly el = document.createElement('div');
  private canvas = document.createElement('canvas');
  private renderer: THREE.WebGLRenderer | null = null;
  private scene = new THREE.Scene();
  private cam = new THREE.PerspectiveCamera(28, 1, 0.05, 200);
  /** Square 0 is you; 1.. are the fleet slots. */
  private squares: HTMLElement[] = [];
  /** Each square's corner icon. */
  private icons: HTMLElement[] = [];
  /** Each square's nameplate: the first name of whoever is driving it. */
  private plates: HTMLElement[] = [];
  private shown: (Shown | null)[] = [];
  /** The unit in each fleet slot (0 for none). */
  private slotUid: number[] = [];
  /** The fleet squares' row, rebuilt when the number of slots changes. */
  private fleetRow: HTMLElement | null = null;
  private tint = -1;
  private fwd = new THREE.Vector3();

  /** The HQ square, left of YOU: its group (hidden without an HQ) and its picture. */
  private hqGroup = document.createElement('div');
  private hqSq = document.createElement('div');
  private hqImg = document.createElement('img');
  private hqKey = '';
  /** The HQ square was clicked (main.ts opens the HQ window). */
  onHq: (() => void) | null = null;
  /** Over the empty HQ square, before there is an HQ: how to get one and what it gives, as HTML (main.ts). */
  noHqTip: (() => string) | null = null;
  private hqTip = document.createElement('div');
  private hqPlate = document.createElement('span');
  /** A square was clicked: null for your own, else the unit's uid. */
  onPick: ((uid: number | null) => void) | null = null;
  /** A fleet square was double-clicked, or its bubble's Open details pressed: that unit's details on their own (main.ts). */
  onDetails: ((uid: number) => void) | null = null;
  /** What opens the next fleet slot, as HTML for the tooltip over the + square (main.ts). */
  nextSlot: (() => string) | null = null;
  /** The + square after the last slot, and its tooltip. */
  private next = document.createElement('button');
  private tip = document.createElement('div');
  /**
   * What a fleet square's bubble says: the unit's row from the fleet window's Drivers tab (main.ts gives
   * `FleetWindow.unitCard`), null for none.
   */
  unitTip: ((uid: number, controls: boolean) => string | null) | null = null;
  /** A fleet square's corner icon (game/fleetPanel.ts `icon`), '' for none. */
  unitIcon: ((uid: number) => string) | null = null;
  /** The tray over YOUR FLEET, as HTML. */
  trayHtml: (() => string) | null = null;
  /** A button in a bubble or the tray was pressed: its data attributes. */
  onAction: ((d: DOMStringMap) => void) | null = null;
  /** The fleet unit the camera is following, if any: a pinned bubble lets go when it stops. */
  followed: (() => number | null) | null = null;
  /** The bubble over a fleet square, the square the mouse is on (-1 none), the square pinned, and when the bubble was last written. */
  private unitBubble = document.createElement('div');
  private hovered = -1;
  private pinned = -1;
  private tipAt = 0;
  private leaveT = 0;
  /** The YOUR FLEET label, its tray, whether the mouse is on it, whether it is pinned, and when it was last written. */
  private head: HTMLElement | null = null;
  private tray = document.createElement('div');
  private trayHover = false;
  private trayPin = false;
  private trayAt = 0;
  private trayLeaveT = 0;

  constructor(private anchor: HTMLElement) {
    this.el.id = 'dock';
    this.el.className = 'hud';
    const group = (title: string, n: number, cls: string, fleet = false): HTMLElement => {
      const g = document.createElement('div');
      g.className = 'dk-group';
      const h = document.createElement('div');
      h.className = 'dk-head';
      h.textContent = title;
      if (fleet) this.head = h;
      const row = document.createElement('div');
      row.className = 'dk-row';
      for (let k = 0; k < n; k++) this.square(row, cls);
      if (fleet) this.fleetRow = row;
      g.append(h, row);
      return g;
    };
    // the HQ square: a picture of the building, not a model, so it is no viewport of the canvas
    this.hqGroup.className = 'dk-group dk-hqgroup';
    this.hqGroup.hidden = true;
    const hqHead = document.createElement('div');
    hqHead.className = 'dk-head';
    hqHead.textContent = 'HQ';
    const hqRow = document.createElement('div');
    hqRow.className = 'dk-row';
    this.hqSq.setAttribute('role', 'button');
    this.hqSq.tabIndex = -1;
    this.hqSq.className = 'dk-sq hq';
    this.hqImg.alt = '';
    this.hqImg.draggable = false;
    this.hqImg.hidden = true;
    const hqPlate = this.hqPlate;
    hqPlate.className = 'dk-name';
    hqPlate.textContent = 'HQ';
    // the picture is clipped to the square's rounded corners; the plate hangs over its bottom edge, as YOU's does
    const pic = document.createElement('span');
    pic.className = 'dk-hqpic';
    pic.append(this.hqImg);
    // before there is an HQ the square stands empty with a +, and hovering it says how to get one and why
    this.hqTip.className = 'dk-tip';
    this.hqTip.hidden = true;
    this.hqSq.append(pic, hqPlate, this.hqTip);
    this.hqSq.addEventListener('click', () => this.onHq?.());
    this.hqSq.addEventListener('mouseenter', () => this.showHqTip(true));
    this.hqSq.addEventListener('mouseleave', () => this.showHqTip(false));
    hqRow.append(this.hqSq);
    this.hqGroup.append(hqHead, hqRow);
    this.el.append(this.hqGroup, group('You', 1, 'me'), group('Your fleet', 0, 'slot empty', true));
    this.next.type = 'button';
    this.next.tabIndex = -1;
    this.next.className = 'dk-sq next';
    this.next.setAttribute('aria-label', 'The next fleet slot');
    this.tip.className = 'dk-tip';
    this.tip.hidden = true;
    this.next.append(this.tip);
    this.unitBubble.className = 'dk-tip dk-unit';
    this.unitBubble.hidden = true;
    // the bubble's buttons: on pointerdown, as it is written again a few times a second; and a click in it is not a click on the square
    this.unitBubble.addEventListener('pointerdown', (e) => this.pressed(e, () => this.showUnit(true)));
    this.unitBubble.addEventListener('click', (e) => e.stopPropagation());
    this.tray.className = 'dk-tip dk-unit dk-tray';
    this.tray.hidden = true;
    this.tray.addEventListener('pointerdown', (e) => this.pressed(e, () => this.showTray(true)));
    this.tray.addEventListener('click', (e) => e.stopPropagation());
    if (this.head) {
      const h = this.head;
      h.classList.add('fleet');
      h.append(this.tray);
      h.addEventListener('mouseenter', () => { clearTimeout(this.trayLeaveT); this.trayHover = true; this.showTray(true); });
      h.addEventListener('mouseleave', () => {
        clearTimeout(this.trayLeaveT);
        this.trayLeaveT = window.setTimeout(() => { this.trayHover = false; this.showTray(); }, 250);
      });
      h.addEventListener('click', () => { this.trayPin = !this.trayPin; this.trayHover = this.trayPin; this.showTray(true); });
    }
    // a click anywhere else lets go of a pinned tray
    document.addEventListener('pointerdown', (e) => {
      if (this.trayPin && this.head && !this.head.contains(e.target as Node)) this.closeTray();
    }, true);
    this.next.addEventListener('mouseenter', () => this.showTip(true));
    this.next.addEventListener('mouseleave', () => this.showTip(false));
    this.next.addEventListener('focus', () => this.showTip(true));
    this.next.addEventListener('blur', () => this.showTip(false));
    this.fleetRow?.append(this.next);
    this.setSlots(FLEET_SLOTS);
    this.canvas.className = 'dk-canvas';
    this.el.append(this.canvas);
    document.body.append(this.el);
    this.scene.add(new THREE.HemisphereLight(0xfff4dc, 0x7a6a50, 1.2));
    const sun = new THREE.DirectionalLight(0xfff1d6, 2.2);
    sun.position.set(3, 6, 2);
    this.scene.add(sun);
  }

  private square(row: HTMLElement, cls: string): void {
    // a div, not a button: its bubble holds buttons of its own
    const b = document.createElement('div');
    b.setAttribute('role', 'button');
    b.tabIndex = -1;
    b.className = `dk-sq ${cls}`;
    const i = this.squares.length;
    b.addEventListener('click', () => this.pick(i));
    const ic = document.createElement('span');
    ic.className = 'dk-ic';
    // the driver's first name, on a plate across the square's bottom edge
    const plate = document.createElement('span');
    plate.className = 'dk-name';
    b.append(plate);
    this.plates.push(plate);
    if (i > 0) {
      b.append(ic);
      // a double-click opens its details (the first click has followed it already)
      b.addEventListener('dblclick', (e) => {
        if ((e.target as HTMLElement).closest('.dk-unit')) return;
        const uid = this.slotUid[i - 1];
        if (uid) this.onDetails?.(uid);
      });
      b.addEventListener('mouseenter', () => { clearTimeout(this.leaveT); this.hovered = i; this.showUnit(true); });
      // a moment's grace, so the mouse can cross the gap into the bubble
      b.addEventListener('mouseleave', () => {
        clearTimeout(this.leaveT);
        this.leaveT = window.setTimeout(() => { if (this.hovered === i) { this.hovered = -1; this.showUnit(true); } }, 250);
      });
    }
    row.append(b);
    this.squares.push(b);
    this.icons.push(ic);
    this.shown.push(null);
  }

  /**
   * A driver of yours has been paid for a delivery: "+$X" in bold green rises off their square and fades
   * (the user, 15 Oct 2026: in place of a card in the notice stack for every load). Nothing when the unit has
   * no square on the dock.
   */
  /** `colour`: a faction's standing gained, in its colours rather than the money's green. */
  earn(uid: number, text: string, colour?: string): void {
    const k = this.slotUid.indexOf(uid);
    const sq = k >= 0 ? this.squares[k + 1] : undefined;
    if (sq) this.rise(sq, text, colour);
  }

  /**
   * Rent taken at one of your doors, the HQ's or any other building's: "+$X" rises off the HQ square in
   * place of a notification (the user, 15 Oct 2026). Nothing while there is no HQ square to rise from.
   */
  earnHq(text: string): void {
    if (this.hqKey && !this.hqGroup.hidden) this.rise(this.hqSq, text);
  }

  /**
   * Bold green money (or a faction's standing, in its colour) rising off a square and fading. One after
   * another from the same square: a delivery's pay and the standing it earned rise in turn, the pay first,
   * rather than on top of each other (the user, 20 Oct 2026).
   */
  private rise(sq: HTMLElement, text: string, colour?: string): void {
    const now = performance.now();
    const at = Math.max(now, this.nextRise.get(sq) ?? 0);
    this.nextRise.set(sq, at + RISE_GAP);
    const go = () => {
      const f = document.createElement('span');
      f.className = colour ? 'dk-earn rep' : 'dk-earn';
      f.textContent = text;
      if (colour) f.style.setProperty('--dk-rep', colour);
      f.addEventListener('animationend', () => f.remove());
      sq.append(f);
    };
    if (at <= now) go(); else window.setTimeout(go, at - now);
  }
  /** When each square may next start a float (rise). */
  private nextRise = new WeakMap<HTMLElement, number>();

  /** A press in a bubble or the tray: one of its buttons does its thing, and the card is written again at once. */
  private pressed(e: PointerEvent, again: () => void): void {
    e.stopPropagation();
    const b = (e.target as HTMLElement).closest('[data-mode],[data-over],[data-standings],[data-hq],[data-details]') as HTMLElement | null;
    if (!b) return;
    e.preventDefault();
    if (b.dataset.details) { this.onDetails?.(Number(b.dataset.details)); return; }
    this.onAction?.(b.dataset);
    again();
  }

  /** Is the tray pinned open (Esc lets go of it first). */
  get trayPinned(): boolean { return this.trayPin; }
  /** Is a bubble pinned over a followed unit. */
  get unitPinned(): boolean { return this.pinned > 0; }

  closeTray(): void { this.trayPin = false; this.trayHover = false; this.showTray(); }
  unpin(): void { if (this.pinned < 0) return; this.pinned = -1; this.showUnit(true); }

  /** With a bubble or the tray out, the dock stands over the panels that share the bottom of the screen (the controls card). */
  private lift(): void {
    const on = !this.unitBubble.hidden || !this.tray.hidden;
    if (this.el.classList.contains('lift') !== on) this.el.classList.toggle('lift', on);
  }

  /** The tray over YOUR FLEET, shown while hovered or pinned. */
  private showTray(now = false): void {
    const on = (this.trayHover || this.trayPin) && !this.el.hidden;
    const t = this.tray;
    if (this.head) {
      if (this.head.classList.contains('open') !== on) this.head.classList.toggle('open', on);
      if (this.head.classList.contains('pinned') !== (on && this.trayPin)) this.head.classList.toggle('pinned', on && this.trayPin);
    }
    if (!on) { if (!t.hidden) { t.hidden = true; this.lift(); this.showUnit(true); } return; }
    if (!now && !t.hidden && performance.now() - this.trayAt < 400) return;
    this.trayAt = performance.now();
    const html = `${this.trayHtml?.() ?? ''}<small class="hint">${this.trayPin ? '<kbd>Esc</kbd> or click the label to close' : 'Click the label to keep this open'}</small>`;
    if (t.innerHTML !== html) t.innerHTML = html;
    if (t.hidden) {
      t.hidden = false;
      this.lift();
      // kept on the screen: slid back in from the right edge if it would cross it
      t.style.setProperty('--dx', '0px');
      const r = t.getBoundingClientRect(), pad = 8;
      t.style.setProperty('--dx', `${Math.round(r.right > innerWidth - pad ? innerWidth - pad - r.right : 0)}px`);
      // a pinned bubble steps aside for the tray
      this.showUnit(true);
    }
  }

  /** A unit's square on the dock, or null when it has none (the first drive's tour points at it). */
  squareOf(uid: number): HTMLElement | null {
    const k = this.slotUid.indexOf(uid);
    return k >= 0 ? this.squares[k + 1] ?? null : null;
  }

  /** As many fleet squares as the fleet has slots (an HQ, and each bay bought at it, adds one). */
  setSlots(n: number): void {
    if (!this.fleetRow || n === this.slotUid.length) return;
    while (this.slotUid.length > n) {
      this.slotUid.pop();
      this.squares.pop()?.remove();
      this.icons.pop();
      this.plates.pop();
      if (this.pinned >= this.squares.length) this.pinned = -1;
      if (this.hovered >= this.squares.length) this.hovered = -1;
      const s = this.shown.pop();
      if (s) { this.scene.remove(s.mesh.holder); if (!s.rail) disposeVehicleMesh(s.mesh); }
    }
    while (this.slotUid.length < n) {
      this.square(this.fleetRow, 'slot empty');
      this.slotUid.push(0);
    }
    // the next slot always comes last
    this.fleetRow.append(this.next);
    // measured again with the new squares in it (a square the layout doesn't know would be drawn from nothing)
    this.layout = null;
    if (this.ro) for (const sq of this.squares) this.ro.observe(sq);
  }

  /** The tooltip over the + square: what opens the next slot, worked out as it is shown. */
  private showTip(on: boolean): void {
    if (on) this.tip.innerHTML = this.nextSlot?.() ?? 'Another fleet slot comes with a grander HQ';
    this.tip.hidden = !on;
    if (!on) return;
    // kept on the screen: slid back in from whichever edge it would cross, its arrow still on the +
    this.tip.style.setProperty('--dx', '0px');
    const r = this.tip.getBoundingClientRect(), pad = 8;
    const dx = r.right > innerWidth - pad ? innerWidth - pad - r.right : r.left < pad ? pad - r.left : 0;
    this.tip.style.setProperty('--dx', `${Math.round(dx)}px`);
  }

  /**
   * The bubble over the hovered fleet square, or else the pinned one (unless the tray is open): the
   * unit's driver, vehicle, what it is doing and what it earns, with its buttons, pointing down at the
   * square. Written again a few times a second while it stays.
   */
  private showUnit(now = false): void {
    // only while the mouse is on the square or in the bubble itself (the user, 8 Oct 2026): following a unit
    // selects its square, it no longer keeps the bubble open
    const i = this.hovered > 0 ? this.hovered : -1;
    const uid = i > 0 ? this.slotUid[i - 1] : 0;
    const b = this.unitBubble;
    if (!now && !b.hidden && performance.now() - this.tipAt < 400) return;
    this.tipAt = performance.now();
    const html = uid ? this.unitTip?.(uid, true) ?? null : null;
    if (!html) { b.hidden = true; this.lift(); return; }
    const sq = this.squares[i];
    const moved = b.parentElement !== sq;
    if (moved) sq.append(b);
    const hint = i === this.pinned ? 'Following · <kbd>Esc</kbd> or click YOU to come back · double-click for its details' : 'Click to follow · double-click for its details';
    const full = `${html}<small class="hint">${hint}</small>`;
    if (b.innerHTML !== full) b.innerHTML = full;
    const was = b.hidden;
    b.hidden = false;
    this.lift();
    if (!was && !moved) return;
    // kept on the screen, as the + square's is: slid back in from an edge, its point still on the square
    b.style.setProperty('--dx', '0px');
    const r = b.getBoundingClientRect(), pad = 8;
    const dx = r.right > innerWidth - pad ? innerWidth - pad - r.right : r.left < pad ? pad - r.left : 0;
    b.style.setProperty('--dx', `${Math.round(dx)}px`);
  }

  private pick(i: number): void {
    if (i === 0) { this.unpin(); this.onPick?.(null); return; }
    const uid = this.slotUid[i - 1];
    if (!uid) return;
    // already followed: it stays selected
    if (this.pinned === i) return;
    this.onPick?.(uid);
    this.pinned = i;
    this.showUnit(true);
  }

  /** The fleet's body colour, as a pastel for the squares. */
  setColour(primary: number): void {
    if (primary === this.tint) return;
    this.tint = primary;
    const rgba = (toWhite: number, alpha: number) => {
      const c = new THREE.Color(primary).lerp(new THREE.Color(0xffffff), toWhite);
      return `rgba(${Math.round(c.r * 255)}, ${Math.round(c.g * 255)}, ${Math.round(c.b * 255)}, ${alpha})`;
    };
    this.el.style.setProperty('--dk-bg', rgba(0.62, 0.82));
    // your own square in a stronger, more solid wash of the colour, so it reads apart from the fleet's
    this.el.style.setProperty('--dk-me', rgba(0.3, 0.94));
    // the selected square's ring, in the colour itself
    this.el.style.setProperty('--dk-sel', rgba(0, 1));
  }

  /**
   * The HQ square: shown once the fleet has an HQ (`key` its address, '' for none), its title the HQ's name,
   * its picture the building (null: not drawn yet, the square stands with its HQ plate only).
   */
  setHq(key: string, title: string, picture: string | null): void {
    if (this.hqGroup.hidden) { this.hqGroup.hidden = false; this.layout = null; }
    const none = !key;
    if (this.hqSq.classList.contains('none') !== none) {
      this.hqSq.classList.toggle('none', none);
      this.hqPlate.hidden = none;
      if (!this.hqTip.hidden) this.showHqTip(true);
    }
    if (none) {
      if (this.hqKey) { this.hqKey = ''; this.hqImg.hidden = true; this.hqImg.removeAttribute('src'); }
      if (this.hqSq.title) this.hqSq.title = '';
      return;
    }
    if (this.hqSq.title !== title) this.hqSq.title = title;
    const src = picture ?? '';
    if (key !== this.hqKey || (src && this.hqImg.getAttribute('src') !== src)) {
      this.hqKey = key;
      if (src) this.hqImg.src = src; else this.hqImg.removeAttribute('src');
      this.hqImg.hidden = !src;
    }
  }

  /** The tip over the empty HQ square, kept on the screen as the + square's is. */
  private showHqTip(on: boolean): void {
    const show = on && this.hqSq.classList.contains('none');
    if (show) this.hqTip.innerHTML = this.noHqTip?.() ?? 'Buy a building and make it your HQ';
    this.hqTip.hidden = !show;
    if (!show) return;
    this.hqTip.style.setProperty('--dx', '0px');
    const r = this.hqTip.getBoundingClientRect(), pad = 8;
    const dx = r.right > innerWidth - pad ? innerWidth - pad - r.right : r.left < pad ? pad - r.left : 0;
    this.hqTip.style.setProperty('--dx', `${Math.round(dx)}px`);
  }

  show(on: boolean): void {
    this.el.hidden = !on;
    if (!on) { this.trayPin = this.trayHover = false; this.pinned = this.hovered = -1; this.tray.hidden = this.unitBubble.hidden = true; }
  }

  /** The world behind the dock is dark (night, deep gloom): the headers go light, without their glow. */
  setDark(on: boolean): void { if (this.el.classList.contains('dark') !== on) this.el.classList.toggle('dark', on); }

  /**
   * Every frame: seat newly out vehicles in the leftmost free slots, free the slots of any parked up,
   * pose each model and draw the row from the camera's angle.
   */
  update(camera: THREE.Camera, me: DockView | null, out: DockView[]): void {
    if (this.el.hidden) return;
    // stand the dock just right of the speedo, whatever width it has grown to. Measured only when
    // something has resized: reading a box every frame, after the HUD has written to the page, made
    // the browser lay the whole page out again each frame.
    if (!this.layout) this.measure();
    const L = this.layout!;
    const left = `${Math.round(L.right + 10)}px`;
    if (this.el.style.left !== left) { this.el.style.left = left; this.layout = null; }
    const byUid = new Map(out.map((v) => [v.uid, v]));
    for (let k = 0; k < this.slotUid.length; k++) if (this.slotUid[k] && !byUid.has(this.slotUid[k])) this.slotUid[k] = 0;
    for (const v of out) {
      if (this.slotUid.includes(v.uid)) continue;
      const free = this.slotUid.indexOf(0);
      if (free < 0) break;
      this.slotUid[free] = v.uid;
    }
    const views = [me, ...this.slotUid.map((uid) => (uid ? byUid.get(uid) ?? null : null))];
    // a pinned bubble lets go once the camera is no longer on its unit (Esc, You, the unit gone)
    if (this.pinned > 0) {
      const uid = this.slotUid[this.pinned - 1];
      if (!uid || this.followed?.() !== uid) this.unpin();
    }
    views.forEach((v, i) => {
      const sq = this.squares[i];
      // a fleet square with a vehicle in it has its bubble instead of a title
      const title = i === 0 ? 'Back to your own car' : v ? '' : 'An empty fleet slot: bring a vehicle out of the garage in your HQ window (H), or buy one at a dealer';
      if (i > 0 && sq.classList.contains('empty') !== !v) sq.classList.toggle('empty', !v);
      if (sq.title !== title) sq.title = title;
      this.sync(i, v?.def ?? null);
      const name = v?.driver ?? '';
      if (this.plates[i] && this.plates[i].textContent !== name) this.plates[i].textContent = name;
      if (i > 0) {
        const ic = v ? this.unitIcon?.(v.uid) ?? '' : '';
        if (this.icons[i].textContent !== ic) this.icons[i].textContent = ic;
      }
    });
    // the square the camera is on is marked: the unit followed, else YOU
    const sel = this.pinned > 0 ? this.pinned : 0;
    this.squares.forEach((sq, k) => { if (sq.classList.contains('sel') !== (k === sel)) sq.classList.toggle('sel', k === sel); });
    if (this.hovered > 0) this.showUnit();
    if (this.trayHover || this.trayPin) this.showTray();

    const r = this.ensure();
    const W = Math.max(1, Math.round(L.w)), H = Math.max(1, Math.round(L.h));
    const size = r.getSize(new THREE.Vector2());
    if (size.x !== W || size.y !== H) r.setSize(W, H, false);
    r.setScissorTest(false);
    r.clear();
    r.setScissorTest(true);
    // the camera's own turn and tilt, so each model is seen the way it is on screen
    this.cam.quaternion.copy(camera.quaternion);
    this.fwd.set(0, 0, -1).applyQuaternion(this.cam.quaternion);
    for (let i = 0; i < views.length; i++) {
      const v = views[i], s = this.shown[i];
      if (!v || !s) continue;
      const st = v.state ?? still(v.heading);
      poseVehicleMesh(s.mesh, st, v.def, v.w as World);
      // the model at the middle of its square: undo where it stands in the world
      s.mesh.holder.position.set(-st.x, -st.y, -st.z);
      const at = L.squares[i];
      if (!at) { this.layout = null; continue; }
      const [x, y, w, h] = at;
      if (w < 2 || h < 2) continue;
      this.cam.aspect = w / h;
      const dist = s.radius / Math.sin(THREE.MathUtils.degToRad(this.cam.fov) / 2) * 1.05;
      this.cam.position.copy(s.mid).addScaledVector(this.fwd, -dist);
      this.cam.updateProjectionMatrix();
      for (const o of this.shown) if (o) o.mesh.holder.visible = o === s;
      r.setViewport(x, y, w, h);
      r.setScissor(x, y, w, h);
      r.render(this.scene, this.cam);
    }
  }

  /** Where the speedo ends, the dock's size and each square within it: read again only after a resize. */
  private layout: { right: number; w: number; h: number; squares: [number, number, number, number][] } | null = null;
  private watching = false;
  private ro: ResizeObserver | null = null;

  private measure(): void {
    if (!this.watching) {
      this.watching = true;
      const stale = () => { this.layout = null; };
      const ro = this.ro = new ResizeObserver(stale);
      ro.observe(this.anchor);
      ro.observe(this.el);
      for (const sq of this.squares) ro.observe(sq);
      addEventListener('resize', stale);
    }
    const a = this.anchor.getBoundingClientRect(), box = this.el.getBoundingClientRect();
    this.layout = {
      right: a.right, w: box.width, h: box.height,
      squares: this.squares.map((s) => { const q = s.getBoundingClientRect(); return [q.left - box.left, box.bottom - q.bottom, q.width, q.height]; }),
    };
  }

  /** Build (or rebuild) the model a square shows when what it shows changes. */
  private sync(i: number, def: VehicleDef | null): void {
    const s = this.shown[i];
    if (s && s.def === def) return;
    if (s) { this.scene.remove(s.mesh.holder); if (!s.rail) disposeVehicleMesh(s.mesh); this.shown[i] = null; }
    if (!def) return;
    const mesh = buildVehicleMesh(def);
    // a train: its engine alone, in its toppers, as the garage and the toppers tab show it (the user, 6 Nov 2026: a train's square was empty)
    const rail = def.kind === 'rail';
    if (rail) mesh.body.add(railThumb(def.id, def, 1).holder);
    const sphere = new THREE.Box3().setFromObject(mesh.holder).getBoundingSphere(new THREE.Sphere());
    this.scene.add(mesh.holder);
    this.shown[i] = { def, mesh, radius: Math.max(0.2, sphere.radius), mid: sphere.center.clone(), rail };
  }

  private ensure(): THREE.WebGLRenderer {
    if (!this.renderer) {
      this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: true, alpha: true });
      this.renderer.setPixelRatio(Math.min(2, window.devicePixelRatio || 1));
      this.renderer.setClearColor(0x000000, 0);
      this.renderer.autoClear = false;
      this.renderer.toneMapping = THREE.NeutralToneMapping;
      this.renderer.toneMappingExposure = 1.05;
    }
    return this.renderer;
  }
}
