import * as THREE from 'three';
import type { World } from '../world/tiles';
import { buildVehicleMesh, disposeVehicleMesh, poseVehicleMesh, type VehicleMesh } from './vehicleMeshes';
import { FULL_HIT, MIN_HIT, halfSize, reportImpact, type VehicleDef, type VehicleState } from '../game/vehicles';
import { spawnState } from '../game/placement';
import { AirState, groundY } from '../game/air';
import { defOf, type Fleet, type Unit } from '../game/fleet';

/**
 * The player's parked vehicles, drawn where they were left. Each is one static mesh in its island's
 * group, built when that island is in the scene and thrown away when it goes; nothing about a parked
 * unit changes per frame except how see-through it is. The same list gives traffic its obstacles, the
 * walk-up prompt its nearest unit, and the overview its fleet dots.
 */

interface Parked { uid: number; key: string; w: World; def: VehicleDef; state: VehicleState; mesh: VehicleMesh; fade: number; mats: THREE.Material[] }

/** How near the player must be to take the wheel of a parked unit, by kind. */
export function walkUpReach(def: VehicleDef): number {
  return def.kind === 'water' ? 2.5 + def.halfLen : def.kind === 'air' ? 3 : 2.5;
}

export class FleetLayer {
  private parked = new Map<number, Parked>();
  private labelRoot = document.createElement('div');
  private labels = new Map<number, HTMLElement>();
  private v = new THREE.Vector3();
  private fwd = new THREE.Vector3();

  constructor(private fleet: Fleet) {
    this.labelRoot.id = 'fleet-labels';
    this.labelRoot.hidden = true;
    document.body.append(this.labelRoot);
  }

  /**
   * Match the meshes to the fleet: a mesh for every parked unit on an island in the scene, in that
   * island's group, rebuilt when the unit has moved; gone for everything else.
   */
  sync(worldAt: (cx: number, cz: number) => World | null, groupOf: (w: World) => THREE.Group | null): void {
    const want = new Set<number>();
    for (const u of this.fleet.units) {
      if (u.where !== 'parked') continue;
      const def = this.fleet.defFor(u);
      if (def.kind === 'rail') continue;
      const w = worldAt(u.cx, u.cz);
      const g = w ? groupOf(w) : null;
      if (!w || !g) continue;
      want.add(u.uid);
      const key = `${u.cx},${u.cz},${u.x.toFixed(2)},${u.z.toFixed(2)},${u.heading.toFixed(2)},${u.model},${def.looks?.key ?? ''}`;
      const have = this.parked.get(u.uid);
      if (have && have.key === key && have.w === w) continue;
      // only moved (a jet riding a carrier's deck, game/carrier.ts): pose the mesh it has, rather than build another
      if (have && have.w === w && have.def === def) {
        const state = parkedState(def, w, u);
        u.x = state.x; u.z = state.z; u.y = state.y;
        poseVehicleMesh(have.mesh, state, def, w);
        have.state = state;
        have.key = `${u.cx},${u.cz},${u.x.toFixed(2)},${u.z.toFixed(2)},${u.heading.toFixed(2)},${u.model},${def.looks?.key ?? ''}`;
        continue;
      }
      if (have) this.drop(have);
      const state = parkedState(def, w, u);
      // the ground may have moved it a little: the record follows the mesh
      u.x = state.x; u.z = state.z; u.y = state.y;
      const mesh = buildVehicleMesh(def);
      poseVehicleMesh(mesh, state, def, w);
      const mats: THREE.Material[] = [];
      mesh.holder.traverse((o) => {
        const m = o as THREE.Mesh;
        if (!m.isMesh) return;
        // its own materials, so it can fade without fading every vehicle that shares them
        m.material = Array.isArray(m.material) ? m.material.map((x) => x.clone()) : m.material.clone();
        for (const x of Array.isArray(m.material) ? m.material : [m.material]) mats.push(x);
      });
      g.add(mesh.holder);
      this.parked.set(u.uid, { uid: u.uid, key: `${u.cx},${u.cz},${u.x.toFixed(2)},${u.z.toFixed(2)},${u.heading.toFixed(2)},${u.model},${def.looks?.key ?? ''}`, w, def, state, mesh, fade: 1, mats });
    }
    for (const p of [...this.parked.values()]) if (!want.has(p.uid)) this.drop(p);
  }

  private drop(p: Parked): void {
    p.mesh.holder.removeFromParent();
    for (const m of p.mats) m.dispose();
    disposeVehicleMesh(p.mesh);
    this.parked.delete(p.uid);
  }

  clear(): void { for (const p of [...this.parked.values()]) this.drop(p); }

  /** Every parked unit's place in world tiles and its mesh, for the fleet badges. */
  *spots(): Generator<{ uid: number; x: number; y: number; z: number; mesh: VehicleMesh }> {
    for (const p of this.parked.values()) yield { uid: p.uid, x: p.w.ox + p.state.x, y: p.state.y, z: p.w.oz + p.state.z, mesh: p.mesh };
  }

  /** Parked units as traffic on island `w` sees them: in its frame. */
  obstaclesFor(w: World): { state: VehicleState; def: VehicleDef }[] {
    const out: { state: VehicleState; def: VehicleDef }[] = [];
    for (const p of this.parked.values()) {
      if (Math.abs(p.w.cx - w.cx) > 1 || Math.abs(p.w.cz - w.cz) > 1) continue;
      const s = p.w === w ? p.state : { ...p.state, x: p.state.x + p.w.ox - w.ox, z: p.state.z + p.w.oz - w.oz } as VehicleState;
      out.push({ state: s, def: p.def });
    }
    return out;
  }

  /** The parked unit nearest the player on their island, within walking reach, or null. */
  nearest(home: World, x: number, z: number, y: number): Unit | null {
    let best: Unit | null = null, bestD = Infinity;
    for (const p of this.parked.values()) {
      if (p.w !== home) continue;
      const d = Math.hypot(p.state.x - x, p.state.z - z);
      if (d > walkUpReach(p.def) || d >= bestD) continue;
      bestD = d;
      best = this.fleet.unit(p.uid);
    }
    // a flyer overhead is not walking up to anything
    return best && y - (this.parked.get(best.uid)?.state.y ?? y) < 2 ? best : null;
  }

  /** A parked unit that sits in the player's way: push back the way a wall does. */
  bump(home: World, s: VehicleState, def: VehicleDef): void {
    const [hl, hw] = halfSize(def);
    for (const p of this.parked.values()) {
      if (p.w !== home || (p.def.kind === 'air') !== (def.kind === 'air') || (p.def.kind === 'water') !== (def.kind === 'water')) continue;
      const [ol, ow] = halfSize(p.def);
      const dx = s.x - p.state.x, dz = s.z - p.state.z;
      const d = Math.hypot(dx, dz), min = (Math.max(hl, hw) + Math.max(ol, ow)) * 0.75;
      if (d >= min || d < 1e-4) continue;
      // only when heading into it
      const into = Math.sin(s.heading) * -dx + Math.cos(s.heading) * -dz;
      if (into * Math.sign(s.v || 1) <= 0) continue;
      s.x = p.state.x + (dx / d) * min;
      s.z = p.state.z + (dz / d) * min;
      // one knock per bump, as hard as the speed into it
      const speedInto = Math.abs(into / d * s.v);
      if (s.blocked <= 0 && speedInto > MIN_HIT) {
        reportImpact(s, { kind: 'hard', strength: Math.min(1, speedInto / FULL_HIT), nx: dx / d, nz: dz / d, px: s.x - (dx / d) * hl, pz: s.z - (dz / d) * hl });
      }
      s.v *= -0.25;
      s.blocked = 0.35;
    }
  }

  /** Parked units between the camera and the car fade, like buildings do. */
  fadeFor(dt: number, camera: THREE.Camera, car: THREE.Vector3): void {
    const cam = camera.position;
    const dx = car.x - cam.x, dy = car.y - cam.y, dz = car.z - cam.z, len = Math.hypot(dx, dy, dz) || 1;
    for (const p of this.parked.values()) {
      const px = p.w.ox + p.state.x, py = p.state.y + 0.2, pz = p.w.oz + p.state.z;
      const t = ((px - cam.x) * dx + (py - cam.y) * dy + (pz - cam.z) * dz) / len;
      let target = 1;
      if (t > 0 && t < len - 0.3) {
        const cx = cam.x + (dx / len) * t, cy = cam.y + (dy / len) * t, cz = cam.z + (dz / len) * t;
        const r = Math.max(...halfSize(p.def)) + 0.25;
        if (Math.hypot(px - cx, py - cy, pz - cz) < r) target = 0.25;
      }
      const next = p.fade + (target - p.fade) * Math.min(1, dt * 9);
      if (Math.abs(next - p.fade) < 1e-3 && next === target) continue;
      p.fade = Math.abs(next - target) < 0.01 ? target : next;
      for (const m of p.mats) {
        m.transparent = p.fade < 0.999;
        m.opacity = p.fade;
        m.depthWrite = p.fade > 0.999;
      }
    }
  }

  /**
   * The fleet on the overview: a filled dot in the model's colour for every unit out working, a
   * hollow one for every parked unit, each with its name.
   */
  updateLabels(camera: THREE.Camera, show: boolean, worldAt: (cx: number, cz: number) => World | null): void {
    this.labelRoot.hidden = !show;
    if (!show) return;
    camera.getWorldDirection(this.fwd);
    const seen = new Set<number>();
    for (const u of this.fleet.units) {
      let gx: number, gy: number, gz: number;
      if (u.where === 'working' && u.agent) {
        gx = u.agent.w.ox + u.agent.state.x; gy = u.agent.state.y; gz = u.agent.w.oz + u.agent.state.z;
      } else if (u.where === 'parked') {
        const w = worldAt(u.cx, u.cz);
        if (!w) continue;
        gx = w.ox + u.x; gy = u.y; gz = w.oz + u.z;
      } else continue;
      let el = this.labels.get(u.uid);
      if (!el) {
        el = document.createElement('div');
        el.className = 'fdot';
        el.append(document.createElement('i'), document.createElement('b'));
        this.labelRoot.append(el);
        this.labels.set(u.uid, el);
      }
      seen.add(u.uid);
      const def = defOf(u.model);
      const colour = `#${def.color.toString(16).padStart(6, '0')}`;
      const dot = el.firstChild as HTMLElement, name = el.lastChild as HTMLElement;
      const cls = `fdot ${u.where === 'working' ? 'working' : 'parked'}`;
      if (el.className !== cls) el.className = cls;
      if (dot.style.getPropertyValue('--c') !== colour) dot.style.setProperty('--c', colour);
      if (name.textContent !== u.name) name.textContent = u.name;
      this.v.set(gx - camera.position.x, gy - camera.position.y, gz - camera.position.z);
      if (this.v.dot(this.fwd) <= 0.5) { el.hidden = true; continue; }
      this.v.set(gx, gy + 0.6, gz).project(camera);
      const x = ((this.v.x + 1) / 2) * window.innerWidth, y = ((1 - this.v.y) / 2) * window.innerHeight;
      el.hidden = this.v.z > 1 || x < 10 || y < 10 || x > window.innerWidth - 10 || y > window.innerHeight - 10;
      if (!el.hidden) el.style.transform = `translate(${Math.round(x)}px, ${Math.round(y)}px) translate(-7px, -50%)`;
    }
    for (const [uid, el] of [...this.labels]) {
      if (seen.has(uid)) continue;
      el.remove();
      this.labels.delete(uid);
    }
  }
}

/** A still state for a parked unit, placed where it can stand. */
function parkedState(def: VehicleDef, w: World, u: Unit): VehicleState {
  if (def.kind === 'air') return new AirState(def, u.x, u.z, u.heading, groundY(w, u.x, u.z), w);
  const s = spawnState(def, w, u.x, u.z, u.heading, -Infinity);
  s.v = 0;
  return s;
}
