const LARCH = hex(0x9a6a3e), LARCH_DARK = hex(0x6e4a2c), SLATE = hex(0x4a4e54), SNOWSTONE = hex(0x9a968c);
const DECKCHAIR = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0xf4f2ec];

/** A summit restaurant (Zermatt's, Saint-Moritz's): a stone base, a glass storey under a timber frame and a mono-pitch roof, a viewing terrace round it. */
const summitRestaurant: Draw = (k, W, D, b, r) => {
  const w = W - 0.5, d = D - 0.9, z = -0.25, g = FLOOR + 0.04, up = FLOOR + 0.12;
  k.box(0, 0, z, w + 0.1, g, d + 0.1, SNOWSTONE);
  for (let i = 0; i < 6; i++) win(k, b, r, -w / 2 + 0.25 + (i * (w - 0.5)) / 5, 0.08, z + (d + 0.1) / 2, 0.1, 0.1, 1);
  // the glass storey: lit at night, timber posts at every bay
  k.glowBox(0, g, z, w, up, d, GLASS, [16, 30, 1.6], WARM_GLOW);
  const bays = Math.max(4, Math.round(w / 0.45));
  for (let i = 0; i <= bays; i++) for (const sz of [-1, 1]) k.box(-w / 2 + (w * i) / bays, g, z + sz * d / 2, 0.04, up, 0.04, LARCH_DARK);
  // the roof: one slope up toward the view, overhanging it, edged in larch
  const y0 = g + up, I: P3 = [0, y0 - 0.5, z];
  const x0 = -w / 2 - 0.15, x1 = w / 2 + 0.15, zb = z - d / 2 - 0.1, zf = z + d / 2 + 0.35;
  k.quad([x0, y0 + 0.02, zb], [x1, y0 + 0.02, zb], [x1, y0 + 0.24, zf], [x0, y0 + 0.24, zf], SLATE, I);
  k.quad([x0, y0, zb], [x0, y0 + 0.22, zf], [x1, y0 + 0.22, zf], [x1, y0, zb], LARCH, [0, y0 + 1, z]);
  k.box(0, y0 + 0.2, zf, x1 - x0, 0.05, 0.04, LARCH_DARK);
  // the terrace out front: a deck, a glass balustrade, tables under umbrellas, the coin telescope
  const tz = z + d / 2 + 0.35;
  k.box(0, g - 0.04, tz, w + 0.3, 0.04, 0.6, LARCH);
  for (let i = 0; i <= 8; i++) k.box(-w / 2 - 0.15 + ((w + 0.3) * i) / 8, g, tz + 0.29, 0.02, 0.1, 0.02, METAL);
  k.box(0, g + 0.09, tz + 0.29, w + 0.3, 0.012, 0.012, METAL);
  for (let i = 0; i < 3; i++) {
    const x = -w / 2 + 0.3 + (i * (w - 0.6)) / 2;
    k.cyl(x, g, tz, 0.08, 0.04, LARCH_DARK, 6);
    k.cyl(x, g, tz, 0.008, 0.22, METAL, 4);
    k.cone(x, g + 0.22, tz, 0.16, 0.06, hex(pickOf(r, DECKCHAIR)), 8);
  }
  k.cyl(w / 2, g, tz + 0.2, 0.012, 0.1, METAL, 4);
  k.box(w / 2, g + 0.1, tz + 0.2, 0.05, 0.03, 0.07, DARK);
  // the stair down from the terrace, and the flag
  for (let i = 0; i < 4; i++) k.box(-w / 2 - 0.05, g - 0.08 - i * 0.07, tz + 0.36 + i * 0.07, 0.24, 0.03, 0.08, LARCH);
  k.cyl(-w / 2 - 0.12, y0, z, 0.008, 0.4, METAL, 4);
  k.box(-w / 2 - 0.04, y0 + 0.3, z, 0.14, 0.08, 0.005, hex(0xe2412f));
};

/** A mid-mountain hut: a log ground floor on stone, a shingle gable, and a sun deck of deckchairs and umbrellas before it. */
export const mountainHut: Draw = (k, W, D, b, r) => {
  const w = Math.min(1.6, W - 1.2), d = D - 1.2, x = -W / 2 + w / 2 + 0.3, z = -0.35, h = FLOOR + 0.08;
  k.box(x, 0, z, w + 0.06, 0.1, d + 0.06, SNOWSTONE);
  k.box(x, 0.1, z, w, h, d, LARCH);
  k.detail(() => { for (let y = 0.14; y < h + 0.1; y += 0.05) k.box(x, y, z + d / 2 + 0.003, w, 0.012, 0.004, LARCH_DARK); });
  k.gable(x, h + 0.1, z, w + 0.2, 0.3, d + 0.2, hex(0x5a4a44), LARCH, true);
  for (const sx of [-0.3, 0.3]) win(k, b, r, x + sx * w, 0.18, z + d / 2, 0.12, 0.12, 1);
  k.glowBox(x, 0.14, z + d / 2 + 0.005, 0.14, 0.2, 0.01, hex(0x6a4a30), [16, 23, 1.4], WARM_GLOW);
  k.box(x - w / 2 + 0.1, h + 0.1, z - 0.1, 0.1, 0.36, 0.1, SNOWSTONE);
  // the sun deck: boards, a rail, rows of deckchairs facing the view, umbrellas, the skis in their rack
  const dx = W / 2 - 0.9, dz = 0.1;
  k.box(dx, 0, dz, 1.3, 0.06, D - 0.7, LARCH);
  for (let i = 0; i <= 6; i++) k.box(dx - 0.65 + (1.3 * i) / 6, 0.06, dz + (D - 0.7) / 2, 0.02, 0.09, 0.02, LARCH_DARK);
  k.box(dx, 0.14, dz + (D - 0.7) / 2, 1.3, 0.012, 0.012, LARCH_DARK);
  for (let j = 0; j < 2; j++) for (let i = 0; i < 4; i++) {
    const cx = dx - 0.45 + i * 0.3, cz = dz - 0.2 + j * 0.45, ch = hex(pickOf(r, DECKCHAIR));
    k.box(cx, 0.06, cz, 0.1, 0.02, 0.2, ch);
    k.wedge(cx, 0.06, cz - 0.08, 0.1, 0.1, 0.06, ch);
  }
  for (const ux of [-0.3, 0.35]) { k.cyl(dx + ux, 0.06, dz + 0.05, 0.008, 0.26, METAL, 4); k.cone(dx + ux, 0.32, dz + 0.05, 0.2, 0.06, hex(pickOf(r, DECKCHAIR)), 8); }
  for (let i = 0; i < 5; i++) k.bar([x + w / 2 + 0.1 + i * 0.05, 0, z + d / 2 + 0.05], [x + w / 2 + 0.12 + i * 0.05, 0.26, z + d / 2 - 0.02], 0.008, hex(pickOf(r, DECKCHAIR)));
};

/** A base lodge for a big resort: a timber-and-glass gable to the slopes, a stone flank, a canopy over the doors and the ski racks. */
const baseLodge070: Draw = (k, W, D, b, r) => {
  const w = W - 0.6, d = D - 0.7, z = -0.1, H = Math.max(2, b.floors) * FLOOR + 0.1;
  k.box(0, 0, z, w + 0.1, 0.2, d + 0.1, SNOWSTONE);
  k.box(0, 0.2, z, w, H, d, LARCH);
  k.box(-w / 2 + 0.25, 0.2, z, 0.5, H + 0.1, d + 0.04, SNOWSTONE);
  // the glass gable end to the front, its timber king-post truss
  const fz = z + d / 2 + 0.005, top = 0.2 + H + 0.7;
  k.gable(0.1, 0.2 + H, z, w - 0.1, 0.7, d + 0.3, hex(0x4a4442), LARCH, true);
  k.glowTri([-w / 2 + 0.6, 0.2 + H, fz + 0.15], [w / 2 - 0.4, 0.2 + H, fz + 0.15], [0.1, top - 0.04, fz + 0.15], [0.1, H, z], GLASS, [16, 30, 1.6], WARM_GLOW);
  k.bar([0.1, 0.2 + H, fz + 0.16], [0.1, top - 0.06, fz + 0.16], 0.02, LARCH_DARK);
  for (let f = 0; f < Math.max(2, b.floors); f++) row(k, b, r, 0.2, 0.28 + f * FLOOR, fz, w - 1.0, 0.18, 5, 1, GLASS);
  // the entrance canopy on two trunks, the racks of skis either side, the fire in the chimney
  k.box(0.3, H * 0.45, fz + 0.3, 1.0, 0.05, 0.5, LARCH_DARK);
  for (const sx of [-1, 1]) k.cyl(0.3 + sx * 0.42, 0.2, fz + 0.5, 0.04, H * 0.45 - 0.2, LARCH, 6);
  for (const sx of [-1, 1]) for (let i = 0; i < 6; i++) k.bar([0.3 + sx * 0.75 + i * 0.04, 0.2, fz + 0.3], [0.3 + sx * 0.75 + i * 0.04, 0.48, fz + 0.24], 0.008, hex(pickOf(r, DECKCHAIR)));
  k.box(-w / 2 + 0.25, 0.2 + H, z - 0.2, 0.18, 0.5, 0.18, SNOWSTONE);
};

