const LIMESTONE = hex(0xe0d2b0), TIN = hex(0xa8acaa), CEDAR = hex(0x8a6a4a), PORCH = hex(0xb08a5e);

/** A Texas ranch house: limestone and painted board, a deep wraparound porch, a standing-seam tin roof, the chimney. */
