  for (const s of [1, -1]) for (let i = 0; i <= 5; i++) k.box(x - w / 2 - 0.12 + ((w + 0.24) * i) / 5, 0, z + s * (d / 2 + 0.12), 0.02, h - 0.02, 0.02, CEDAR);
