  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(x + sx * (w / 2 + 0.02), 0, z + sz * (d / 2 + 0.02), 0.05, h, 0.05, scale(log, 1.15));
  k.gable(x, h, z, w + 0.16, 0.32, d + 0.16, hex(0x3f5a46), log, false);
  k.box(x + w / 2 + 0.06, 0, z, 0.14, h + 0.5, 0.2, FIELDSTONE);
