  for (let i = 0; i <= 4; i++) k.box(cx - cw / 2 + (cw * i) / 4, 0, cz + 0.56, 0.02, FLOOR - 0.04, 0.02, PLANK_DARK);
  for (const sx of [-0.3, 0.3]) win(k, b, r, cx + sx * cw, 0.08, cz + 0.35, 0.1, 0.1, 1);
