/** The canyon ranch's mule corral (its stables): the tack shed along the back, a rail pen, hay, and the mules at the rail. */
const muleCorral: Draw = (k, W, D) => {
  const w = W - 0.3, d = D - 0.3, rail = PLANK_DARK, mule = hex(0x6a5040);
  k.box(0, 0, -D / 2 + 0.35, w, FLOOR, 0.5, hex(0x9a7650));
  k.box(0, FLOOR, -D / 2 + 0.35, w + 0.08, 0.03, 0.6, hex(0x7e8280));
  for (const [x0, z0, x1, z1] of [[-w / 2, -0.1, -w / 2, d / 2], [w / 2, -0.1, w / 2, d / 2], [-w / 2, d / 2, w / 2, d / 2]] as const) {
    for (const y of [0.06, 0.14]) k.bar([x0, y, z0], [x1, y, z1], 0.008, rail);
    const n = Math.round(Math.hypot(x1 - x0, z1 - z0) / 0.3);
    for (let i = 0; i <= n; i++) k.box(x0 + ((x1 - x0) * i) / n, 0, z0 + ((z1 - z0) * i) / n, 0.02, 0.17, 0.02, rail);
  }
  for (let i = 0; i < 4; i++) {
    const x = -w / 2 + 0.25 + i * ((w - 0.5) / 3), z = 0.25;
    k.box(x, 0.07, z, 0.08, 0.07, 0.2, mule);
    k.box(x, 0.12, z + 0.12, 0.05, 0.06, 0.07, mule);
    for (const s of [-1, 1]) k.box(x + s * 0.015, 0.18, z + 0.14, 0.012, 0.05, 0.012, mule);
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(x + sx * 0.03, 0, z + sz * 0.07, 0.015, 0.07, 0.015, mule);
  }
  k.box(w / 2 - 0.2, 0, d / 2 - 0.2, 0.16, 0.08, 0.1, hex(0xd9b85a));
};

// ---- the Adriatic -----------------------------------------------------------------------------------------------

const ISTRIAN = hex(0xf0ebe0), MARBLE = hex(0xe6e0d6);
/**
 * A Venetian-gothic palazzo (Rovinj's, Piran's, the Grand Canal's): three or four floors of stucco over a stone ground
 * floor of arched openings; the piano nobile's three-light pointed window over a stone balcony; single pointed windows
 * either side and above; a dentil cornice and a low terracotta roof.
 */
export const palazzo: Draw = (k, W, D, b, r) => {
  const floors = Math.max(3, Math.min(4, b.floors)), wall = pick(r, cur.walls), w = W - 0.16, d = D - 0.2, z = -0.02;
  const front = z + d / 2, H = floors * FLOOR + 0.06;
  k.box(0, 0, z, w, H, d, wall);
  k.box(0, 0, z, w + 0.01, FLOOR, d + 0.01, ISTRIAN);
  const bays = Math.max(3, Math.round(w / 0.28)), bw = w / bays;
  for (let i = 0; i < bays; i++) archWin(k, -w / 2 + bw * (i + 0.5), 0.02, front + 0.006, bw * 0.7, FLOOR - 0.06, MARBLE, false, [16.5, 23.5, 1.6], hex(0x3a3430));
  const y1 = FLOOR + 0.05, wh = FLOOR - 0.08;
  for (let j = -1; j <= 1; j++) archWin(k, j * 0.09, y1, front, 0.07, wh, MARBLE, true, [17, 23.5, 1.5]);
  k.box(0, FLOOR, front + 0.04, 0.36, 0.02, 0.08, MARBLE);
  for (let j = 0; j <= 8; j++) k.box(-0.17 + j * 0.0425, FLOOR + 0.02, front + 0.075, 0.01, 0.06, 0.01, MARBLE);
  k.box(0, FLOOR + 0.08, front + 0.075, 0.36, 0.012, 0.014, MARBLE);
  for (let f = 1; f < floors; f++) for (let i = 0; i < bays; i++) {
    const x = -w / 2 + bw * (i + 0.5);
    if (f === 1 && Math.abs(x) < 0.2) continue;
    archWin(k, x, f * FLOOR + 0.05, front, 0.08, wh, MARBLE, true, [17, 23.5, 1.5]);
  }
  k.box(0, H, z, w + 0.06, 0.03, d + 0.06, MARBLE);
  k.detail(() => { for (let i = 0; i < bays * 3; i++) k.box(-w / 2 + (w * (i + 0.5)) / (bays * 3), H - 0.02, front + 0.02, 0.02, 0.02, 0.012, MARBLE); });
  k.hip(0, H + 0.03, z, w + 0.04, 0.12, d + 0.04, hex(0xb85a36));
  if (r() < 0.5) k.box(w / 2 - 0.12, H + 0.06, z - 0.1, 0.06, 0.16, 0.06, hex(0xe0d4bc));
};

/** An Adriatic old-town shop: the narrow house pair over a ground floor opened in stone arches, lit as shopfronts. */
const adriaticShop: Draw = (k, W, D, b, r, t) => {
  adriaticHouse(k, W, D, b, r, t);
  const front = -0.04 + 0.4;
  for (const side of [-1, 1]) {
    const x = side * 0.21;
    archWin(k, x, 0.02, front + 0.02, 0.26, FLOOR - 0.06, ISTRIAN, false, [9, 21, 1.8], hex(0x5a5048));
    k.box(x, FLOOR - 0.03, front + 0.06, 0.3, 0.012, 0.08, hex(pickOf(r, [0x2f5a3a, 0x7a2f2a, 0x2f4a6a])));
  }
};

