  k.box(0, h, z, w + 0.1, 0.05, d + 0.1, hex(0x3a3f45));
  k.glowBox(0, 0.06, z + d / 2 + 0.004, 0.3, 0.3, 0.01, GLASS, [16, 30, 1.4], hex(0xf4f8ff));
  k.glowBox(0, h - 0.1, z + d / 2 + 0.03, 0.07, 0.07, 0.07, hex(0xe2412f), [0, 30, 1], hex(0xff4030));
  k.box(0.26, h - 0.14, z + d / 2 + 0.006, 0.08, 0.08, 0.008, hex(0xd9a441));
  signboard(k, -0.18, h - 0.13, z + d / 2 + 0.012, '交番', 0.06, hex(0x2f3f6a));
  for (const x of [-0.32, 0.32]) win(k, b, r, x, 0.14, z + d / 2, 0.12, 0.16, 1);
