/**
 * A sukiya inn, an onsen town's second ryokan build: one or two low storeys of pale timber and paper behind a plastered
 * wall with a roofed gate, a raked-gravel garden with a pine and a stone lantern in front, a deep irimoya roof.
 */
const sukiyaInn: Draw = (k, W, D, b, r) => {
  const w = W - 0.4, d = D - 1.0, z = -0.35, two = b.floors >= 3, g = FLOOR + 0.06;
  k.box(0, 0, z, w, 0.06, d, STONE);
  k.box(0, 0.06, z, w - 0.1, g, d - 0.1, TIMBER_OLD);
  for (let i = 0; i < 5; i++) k.pane(-w / 2 + 0.25 + (i * (w - 0.5)) / 4, 0.1, z + (d - 0.1) / 2 + 0.004, 0.2, g - 0.1, 1, PAPER, ROOMS, PAPER_GLOW);
  let top = 0.06 + g;
  if (two) {
    eastRoof(k, 0, top, z, w + 0.1, d + 0.1, 0.1, KAWARA, 0.04);
    k.box(0, top + 0.06, z, w * 0.6, g * 0.9, d * 0.6, TIMBER_OLD);
    for (let i = 0; i < 3; i++) k.pane(-w * 0.2 + i * w * 0.2, top + 0.1, z + d * 0.3 + 0.004, 0.16, g * 0.7, 1, PAPER, ROOMS, PAPER_GLOW);
    top += 0.06 + g * 0.9;
    irimoya(k, 0, top, z, w * 0.72, d * 0.72, 0.3, KAWARA_DARK);
  } else irimoya(k, 0, top, z, w + 0.16, d + 0.16, 0.34, KAWARA_DARK);
  // the plastered wall along the front with its roofed gate, the garden behind it
  const fz = D / 2 - 0.12;
  for (const sx of [-1, 1]) {
    k.box(sx * (w / 4 + 0.12), 0, fz, w / 2 - 0.24, 0.22, 0.06, PLASTER);
    k.box(sx * (w / 4 + 0.12), 0.22, fz, w / 2 - 0.2, 0.03, 0.1, KAWARA);
  }
  for (const sx of [-1, 1]) k.box(sx * 0.12, 0, fz, 0.04, 0.3, 0.04, TIMBER_DARK);
  eastRoof(k, 0, 0.3, fz, 0.34, 0.18, 0.08, KAWARA, 0.03);
  k.box(0, 0.004, (fz + z + d / 2) / 2, w - 0.2, 0.004, fz - z - d / 2 - 0.1, hex(0xe6e0d2));
  stoneLantern(k, -w / 2 + 0.3, 0, (fz + z + d / 2) / 2, 0.8);
  k.cyl(w / 2 - 0.3, 0, (fz + z + d / 2) / 2, 0.025, 0.24, TIMBER_DARK, 5);
  k.dome(w / 2 - 0.3, 0.24, (fz + z + d / 2) / 2, 0.16, hex(0x3f6a3a), 8, 2);
  noren(k, 0, g + 0.02, z + (d - 0.1) / 2 + 0.014, 0.24, 0.1, pick(r, NOREN));
};

