/** The western water tank (themes.ts) where a ranch's yard has its silo. */
const ranchTank: Draw = (k, _W, _D, _b, r) => woodTank(k, r);

/** Is this building in a ranch's homestead yard? */
const inRanch = (w: World | null | undefined, b: Building): boolean =>
  !!w?.ranches.some((q) => b.x >= q.yard.x && b.x < q.yard.x + q.yard.w && b.z >= q.yard.z && b.z < q.yard.z + q.yard.d);

/** The kinds' own models (render/townMesh.ts DRAW, set there: importing it here would be a cycle), for a swap to another kind's. */
export const BASE: { draw: Partial<Record<BuildingKind, Draw>> } = { draw: {} };
const as = (kind: BuildingKind): Draw | null => BASE.draw[kind] ?? null;
const JAPAN = new Set(['onsen', 'tokyo', 'osaka']);
const workOf = (w: World | null | undefined, b: Building, kind: string) => w?.works.find((q) => q.kind === kind && q.buildings.includes(b));

/** A canyon cable car's rim terminal: the lift station's own model, and a viewing deck out over the rim in front of it, telescopes on its rail. */
const rimTerminal: Draw = (k, W, D, b, r, t) => {
  as('liftStation')?.(k, W, D, b, r, t);
  const dz = D / 2 - 0.35, w = W - 0.6;
  k.box(0, 0, dz, w, 0.05, 0.6, hex(0xb8a888));
  for (let i = 0; i <= 8; i++) k.box(-w / 2 + (w * i) / 8, 0.05, dz + 0.29, 0.02, 0.14, 0.02, DARK);
  k.box(0, 0.18, dz + 0.29, w, 0.014, 0.014, DARK);
  for (const x of [-w / 4, w / 4]) { k.cyl(x, 0.05, dz + 0.18, 0.012, 0.14, METAL, 4); k.box(x, 0.19, dz + 0.2, 0.05, 0.035, 0.08, DARK); }
};

/** What each kind draws in a 0.7.0 place, if not its own; asked by render/townMesh.ts drawOf before the variants. */
export function swap070(b: Building, t: Town | null, w?: World | null): Draw | null {
  const a = curArch;
  switch (b.kind) {
    case 'police': return JAPAN.has(a) ? koban : null;
    case 'store': case 'grocery': return JAPAN.has(a) ? konbini : null;
    case 'postOffice': return JAPAN.has(a) ? japanPost : null;
    case 'ryokan': return seedPick(b, 2, 17) ? sukiyaInn : null;
    case 'shrine': return seedPick(b, 2, 19) ? toriiShrine : null;
    case 'pagoda': return seedPick(b, 3, 23) === 0 ? pagoda3 : null;
    case 'cityHall': return t?.plan === 'spiral' ? tenshu : null;
    case 'watchtower': return t?.plan === 'medina' ? kasbahTower : t?.plan === 'chessboard' ? cornerPavilion : null;
    case 'controlTower': return b.floors >= 4 && seedPick(b, 2, 29) ? tallTower : null;
    case 'fire': return workOf(w, b, 'airfield') ? airportFire : null;
    case 'liftStation': return workOf(w, b, 'cableCar') ? rimTerminal : null;
    case 'chippy': return a === 'lakeside' ? as('diner') : null;
    case 'deli': return a === 'lakeside' ? as('icecreamParlour' as BuildingKind) : null;
    case 'lodge': {
      // a resort's lodges up the mountain (world/skiFields.ts: summit two floors, mid one), and its base, by where it stands
      const g = w?.works.find((q) => q.kind === 'ski' && q.buildings.includes(b));
      if (g && b.level > g.level + 2) return b.floors >= 2 ? summitRestaurant : mountainHut;
      return b.floors >= 3 || seedPick(b, 2, 11) ? baseLodge070 : null;
    }
    case 'ranchHouse': {
      if (b.remote) return phantomRanch;
      const reg = w?.region ?? null;
      if (reg === 'goldhills' || reg === 'redrock') return null;
      return reg === 'steppe' ? montanaRanchHouse : texasRanchHouse;
    }
    case 'stables': return b.remote ? muleCorral : null;
    case 'barn': return inRanch(w, b) ? horseBarn : null;
    case 'silo': return inRanch(w, b) ? ranchTank : null;
    case 'apartment': return a === 'adriatic' || a === 'como' || a === 'venice' ? palazzo : null;
    case 'shop': return a === 'adriatic' ? adriaticShop : null;
    case 'hotel': return a === 'adriatic' ? LAKE_SHORE_DRAW.grandHotel : null;
    case 'townhouse':
      if (a === 'onsen') return machiya;
      // Léman's own: the style's mansard townhouse, never a Western variant
      if (a === 'leman') return as('townhouse');
      if (a === 'como') return adriaticHouse;
      if (t?.lake === LAKE_AFTER.geneva) return queenAnne;
      return null;
    case 'house':
      if (t?.lake === LAKE_AFTER.geneva) return queenAnne;
      if (a === 'onsen') return machiya;
      return null;
    case 'bathhouse': return a === 'onsen' || t?.onsen ? sotoyu : null;
    case 'lakeCottage': return seedPick(b, 5, 9) === 0 ? null : cottage070;
    default: return null;
  }
}

