import type { Building, World } from '../world/tiles';
import type { Estate } from './estate';
import type { Fleet, Hq } from './fleet';
import { gradeOf, type HqGrade } from './hqGrade';
import { deeds } from './deeds';

/**
 * The fleet's headquarters (docs/hq.html). Any building the player owns with an HQ grade may be made the
 * HQ, for its grade's charter in diamonds less the charter credit already paid; the grade is the fleet's
 * slots. Scenery (parks, plazas, fields, masts and windmills) has no grade. The HQ is a deed like any
 * other: sold or razed, the fleet has no slots until another is made; boarded up, it runs one short.
 */

/** A building's grade as an HQ: its harbour's, for one in a harbour. */
function hqGradeOf(estate: Estate, w: World, b: Building): HqGrade {
  const q = estate.quote(w, b);
  return gradeOf(b, !!q.harbour);
}

/** Why this building can't be an HQ at all, or null when it can (ownership, diamonds and repair aside). */
function hqWhyNot(b: Building): string | null {
  return gradeOf(b).grade ? null : 'Scenery can’t house a fleet';
}

/** The HQ record for a building (its harbour, for one in a harbour). */
export function hqFor(estate: Estate, w: World, b: Building): Hq {
  const q = estate.quote(w, b);
  const g = gradeOf(b, !!q.harbour);
  const all = q.harbour ? q.harbour.buildings.filter((x) => !x.gone) : [b];
  const x = all.reduce((s, o) => s + o.x + o.w / 2, 0) / all.length, z = all.reduce((s, o) => s + o.z + o.d / 2, 0) / all.length;
  const t = q.harbour ? null : w.towns.find((tw) => tw.buildings.includes(b));
  return { key: q.key, name: q.name, town: q.harbour ? '' : q.town, cx: w.cx, cz: w.cz, x, z, grade: g.grade, plus: g.plus, slots: g.slots, kind: q.harbour ? 'harbour' : b.kind, townKind: t?.kind ?? null };
}

/** What making this building the HQ would take: its grade, the diamonds due after the credit, and why it can't be, if it can't. */
interface HqOffer { g: HqGrade; due: number; why: string | null; isHq: boolean }

export function hqOffer(fleet: Fleet, estate: Estate, w: World, b: Building, diamonds: number): HqOffer {
  const q = estate.quote(w, b);
  const g = gradeOf(b, !!q.harbour);
  const due = fleet.charterDue(g.charter);
  const isHq = fleet.hq?.key === q.key;
  let why: string | null = null;
  if (!g.grade) why = 'Scenery can’t house a fleet';
  else if (isHq) why = 'Already your HQ';
  else if (!q.harbour && b.derelict) why = 'Mend it first: a boarded-up building can’t be chartered';
  else if (diamonds < due) why = `The charter costs ◆ ${due} · you have ◆ ${Math.floor(diamonds)}`;
  return { g, due, why, isHq };
}

/**
 * Make an owned building the fleet's HQ, paying the charter from `spend` (false: not enough diamonds).
 * A message when it can't be.
 */
export function makeHq(fleet: Fleet, estate: Estate, w: World, b: Building, diamonds: number, spend: (n: number) => boolean): string | null {
  if (!estate.owns(w, b)) return 'Buy the deed first';
  const o = hqOffer(fleet, estate, w, b, diamonds);
  if (o.why) return o.why;
  if (o.due > 0 && !spend(o.due)) return `The charter costs ◆ ${o.due}`;
  fleet.charter = Math.max(fleet.charter, o.g.charter);
  fleet.setHq(hqFor(estate, w, b));
  deeds.best('hqGrade', o.g.grade);
  return null;
}

/** The HQ's lot has been sold or razed: no HQ; boarded up: a slot short. Once a frame is plenty. */
export function checkHq(fleet: Fleet, estate: Estate): void {
  if (!fleet.hq) return;
  if (!estate.deeds.has(fleet.hq.key)) { fleet.setHq(null); return; }
  const r = estate.resolve(fleet.hq.key);
  if (!r) return; // its cell isn't in memory: as it was
  const down = !r.port && !!r.b.derelict;
  if (down !== fleet.hqDown) {
    fleet.hqDown = down;
    fleet.settle();
    fleet.onChange();
  }
}

/** A grander building than the HQ, near: what the garage's Addresses list shows (docs/hq.html). */
export interface Address { w: World; b: Building; key: string; name: string; town: string; grade: number; slots: number; price: number; due: number; dist: number }

/**
 * The nearest building of each HQ grade that opens more slots than the fleet has, among the islands in
 * memory: not the player's, not a rival's (`held`), standing. Only the few picked are quoted.
 */
export function addresses(fleet: Fleet, estate: Estate, worlds: World[], at: { x: number; z: number }, held: (key: string) => boolean): Address[] {
  const best = new Map<number, { w: World; b: Building; dist: number }>();
  for (const w of worlds) {
    for (const b of w.allBuildings) {
      if (b.gone || b.derelict || b.uid < 0) continue;
      const g = gradeOf(b);
      if (!g.grade || g.slots <= fleet.slots) continue;
      const dist = Math.hypot(w.ox + b.x + b.w / 2 - at.x, w.oz + b.z + b.d / 2 - at.z);
      const was = best.get(g.slots);
      if (was && was.dist <= dist) continue;
      const key = estate.keyOf(w, b);
      if (key.includes('#p') || estate.taken(key) || held(key)) continue;
      best.set(g.slots, { w, b, dist });
    }
  }
  return [...best.entries()].sort((a, b) => a[0] - b[0]).map(([, { w, b, dist }]) => {
    const q = estate.quote(w, b);
    return { w, b, key: q.key, name: q.name, town: q.harbour ? '' : q.town, grade: q.grade.grade, slots: q.grade.slots, price: q.hqPrice, due: fleet.charterDue(q.grade.charter), dist };
  });
}
