/**
 * Achievements, called deeds (docs/achievements.html): one number the game keeps for a player — a
 * count, a high-water mark or a set of distinct things — and a ladder of five tiers on it, Bronze to
 * Diamond. Deeds belong to the player, not the save, so they live beside the roster in their own
 * record. Counters are bumped where the event already happens, through three verbs that do nothing
 * but write a number down; once a second `tick` looks at what changed and stamps any tier crossed.
 */

type DeedGroup = 'Exploration' | 'Haulage' | 'Towns' | 'Roads' | 'Vehicles' | 'Company' | 'Factions' | 'Rail' | 'After Dark' | 'Estate' | 'Earthworks' | 'Community';
// the Factions shelf comes with the next world (world/nextWorld.ts, docs/deeds070.html)
export const DEED_GROUPS: DeedGroup[] = ['Exploration', 'Haulage', 'Towns', 'Roads', 'Vehicles', 'Company', ...(NEXT_WORLD ? ['Factions' as const] : []), 'Rail', 'After Dark', 'Estate', 'Earthworks', 'Community'];

/** Every number a deed can watch. */
export type Stat =
  | 'odo.all' | 'odo.land' | 'odo.water' | 'odo.air' | 'odo.rail'
  | 'cells' | 'landforms' | 'biomes' | 'wonders' | 'weathers'
  // range (docs/exploration.html): tiles from home and from the origin, models taken far, discovery pay
  | 'range' | 'rangeModels' | 'frontier' | 'discoverPay' | 'firsts'
  | 'loads' | 'cash' | 'cargoTypes' | 'urgent' | 'across' | 'payday'
  | 'graduations' | 'mayors' | 'razed' | 'chains' | 'helped' | 'civicPride' | 'erected' | 'annexed'
  | 'roadTiles' | 'bridges' | 'longSpan' | 'highway' | 'surfaces' | 'borderRoads' | 'townsLinked' | 'climb' | 'roadSpend' | 'tolls' | 'overpasses' | 'roundabouts'
  | 'models' | 'topSpeed' | 'fences' | 'tuner' | 'fullWorks' | 'shove' | 'drift'
  | 'topDown' | 'tarmac' | 'takeoffs' | 'greasers' | 'redEye'
  | 'drivers' | 'cut' | 'aces' | 'motorPool' | 'convoys' | 'allPresent' | 'convoyCells' | 'fullLoad' | 'milkRound' | 'nothingWasted'
  // delivery missions finished inside a medal time, and inside gold (missions/medals.ts)
  | 'medals' | 'golds'

  | 'stations' | 'railLoads' | 'tunnels' | 'ferries'
  // loads delivered at the regulator of your own train (the rail lesson's cue, game/coach.ts)
  | 'trainLoads'
  // the 28 Oct 2026 deeds: weight and hold, long and ultra hauls, acts; track laid; trains high and far; subs, jumps, pads, laps, straits
  | 'tonnage' | 'freightLoads' | 'bulkLoads' | 'containerLoads' | 'heaviest' | 'longHauls' | 'farthest' | 'ultraLoads' | 'roadie'
  | 'trackTiles' | 'stationsBuilt' | 'townsLinked' | 'junctions' | 'parallelTracks' | 'trainHeight' | 'cogClimb' | 'nonStop'
  | 'deepLoads' | 'deepestDive' | 'jumpsLanded' | 'padsHit' | 'lapsHeld' | 'straits'
  // the Passport's pages sealed (game/passportRewards.ts), each a page, a visa group or the whole book
  | 'seals'
  | 'nightRuns' | 'cleanHands' | 'closeShave' | 'dawnChorus'
  // the tails (game/tail): followed to the end, and followed to the end without ever being made
  | 'tails' | 'ghostTails'
  // the convoys led home (missions/convoyTemplates.ts), by template
  | 'convoys'
  // rush kinds won gold on (game/rushes, docs/rushes.html)
  | 'rushGolds'
  | 'lotsHeld' | 'rent' | 'mended' | 'blueChip' | 'estateTowns' | 'monopoly' | 'hqGrade' | 'blueprints'
  | 'lifts' | 'landSpend' | 'reclaimed' | 'navvy' | 'lakes' | 'summit'
  | 'altitude' | 'perches' | 'perchKinds'
  | 'loved' | 'crossed' | 'blazed' | 'gaveTo' | 'listedWorks'
  // the social window (docs/social.html phase 4): standings metrics led among five or more friends; titles held
  | 'bigFish' | 'titles'
  | 'postcards' | 'cardOpens' | 'cardRides'
  // the Passport's sights and a home town's culture (docs/passport.html)
  | 'styles' | 'sizes' | 'kinds' | 'imports' | 'farFetched' | 'cultured'
  // the in-world events (docs/events.html): kinds seen while they were on
  | 'events'
  // the city plans (docs/cityplans.html, GEN 53): kinds of plan driven into
  | 'plans'
  // the Factions shelf (docs/deeds070.html): rungs ever reached, the Oaths and leaders, their work, their vehicles' tricks
  | 'facMet' | 'facFriend' | 'facHonoured' | 'facSworn' | 'bothSides' | 'burned' | 'oathSteps' | 'leaders'
  | 'facLoads' | 'facCargo' | 'greyActs' | 'facUnlocks' | 'tricks' | 'beamed' | 'onAir' | 'hauls'
  // the next world's places (docs/deeds070.html, GEN 53)
  | 'ancient' | 'colossus' | 'harbours' | 'schoolRun' | 'fieldTrips' | 'ranches' | 'cattleDrive' | 'cattleGrids'
  | 'planEconomy' | 'onsenFlavours' | 'bathers' | 'fukuzumiro' | 'lakeTowns' | 'lakeSeason' | 'dawn'
  // toppers (docs/toppers.html, game/toppers.ts): the ones kept, and each knack job done, by job
  | 'toppers' | `knack.${string}`
  // the culture toppers and mascots (docs/toppers.html phase 3): blueprint copies finished by style, deliveries by model
  | `bp.${string}` | `del.${string}`
  // phase 4: runs of each event kind and the occurrences counted, wild things of each kind visited and the sites, story
  // chains finished, night ops done, meteorites brought home, seasons played through and the ones begun
  | `ev.${string}` | 'evRuns' | `wd.${string}` | 'wildSeen' | 'tales' | 'nightOps' | 'meteors' | 'seasons' | 'seasonBegun'
  // the world's records (shared/records.ts): the longest jump, in tenths of a tile
  | 'longestJump';

export interface Deed {
  id: string;
  group: DeedGroup;
  name: string;
  icon: string;
  /** What counts, in one sentence. */
  blurb: string;
  stat: Stat;
  kind: 'count' | 'best' | 'set';
  /** Bronze, silver, gold, platinum, diamond. */
  ladder: [number, number, number, number, number];
  /** The word after the number ("tiles", "loads"); '$' writes it as money. */
  unit: string;
  /** For a set: how many there are to find. */
  of?: number;
}

