/** The Passport's treats and the topper a vehicle wears, for its card: what it is and what earned it (game/passportRewards.ts). */
function treatLine(p: Parts | undefined): string {
  if (!p) return '';
  const bits: string[] = [];
  if (p.g) bits.push(`👑 ${p.g === 2 ? 'Gilded' : 'Gold trim'}: every stamp in the Passport`);
  const tp = topperOf(p), t = tp ? TOPPER_BY_ID.get(tp) : undefined;
  if (t) bits.push(`${t.icon} ${esc(t.name)}: ${esc(t.how.charAt(0).toLowerCase() + t.how.slice(1))}`);
  if (p.l) bits.push('🔦 Explorer’s lantern: every landform stamped');
  if (p.h === 'fanfare') bits.push('🎺 Fanfare horn: every signature building stamped');
  if (p.h === 'confetti') bits.push('🎉 Confetti horn: every event stamped');
  if (p.j === 'job:expedition') bits.push('🧭 Expedition livery: every biome stamped');
  if (p.j === 'job:skyline') bits.push('🏙️ Skyline decals: every town size stamped');
  return bits.join('<br>');
}
