/** How long the camera waits at a county border for a followed vehicle of yours to come on in the next county. */
const CROSS_WAIT = 8;

/**
 * Click to inspect. A click on the canvas that isn't on goods selects whatever is under the pointer:
 * a CPU vehicle (or a hired driver's), a train, or a building. A card on the right says what it is —
 * where a vehicle came from and is going, how a building's trade is doing — and a vehicle or a train
 * can be followed by the camera until Esc. The selection wears a yellow outline drawn over everything.
 */

/** What is selected. Vehicles are held by reference and let go of when their traffic drops them. */
export type Selection =
  | { kind: 'agent'; agent: Agent; traffic: Traffic }
  | { kind: 'train'; train: Train }
  /** A jet of the sky's own traffic (docs/rides.html): on an apron, on a runway or overhead. */
  | { kind: 'flight'; flight: Flight }
  | { kind: 'building'; w: World; b: Building }
  /** A whole town (docs/towns.html), by key; its island and town while they are in memory. */
  | { kind: 'town'; key: string }
  /** Online: another player's vehicle (uid null: the one they drive), by their id and its unit's number. */
  | { kind: 'remote'; pid: string; uid: number | null };

/**
 * Online (src/net): the other players' vehicles, to click on, follow and list (the user, 23 Oct 2026: following a
 * player's car, it couldn't be picked for a card; their HQ had no way to their fleet).
 */
interface RemoteHost {
  drawn(): RemoteSeen[];
  vehicle(pid: string, uid: number | null): RemoteSeen | null;
  /** Their vehicles out on the map, theirs first; null when they aren't signed in. */
  fleetOf(pid: string): RemoteSeen[] | null;
  /** Who they are: their name, their fleet's, and its brand; null once they have signed out. */
  who(pid: string): { name: string; fleet: string; brand: { logo: string; primary: number; accent: number } | null } | null;
  /** Their HQ's lot and name, when the server has told of one. */
  hqOf(pid: string): { key: string; name: string } | null;
  /** Fly the camera to a lot (an HQ), as the Friends tab's View HQ does. */
  viewHq(key: string, name: string): void;
}

