/** "bigBox" → "Big box": a label for a building kind nobody wrote one for. */
function pretty(kind: string): string {
  const words = kind.replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase();
  return words[0].toUpperCase() + words.slice(1);
}

export const buildingLabel = (b: Building): string =>
  b.storefront === 'shop' ? 'Auto Shop' : b.storefront === 'dealer' ? 'Car Dealership' : SITE_LABEL[b.kind as SiteKind] ?? pretty(b.kind);

/** A town's name as a link that selects the whole town, on any card (main.ts listens for `data-town`). */
export function townLink(key: string, name: string): string {
  return `<button type="button" class="townlink" data-town="${esc(key)}">${esc(name)} ›</button>`;
}

/** What the deed card needs from the game: the inspector's host, or the HQ window's Estate tab. */
export type DeedCtx = Pick<InspectHost, 'estate' | 'fleet' | 'firms' | 'buyout' | 'diamonds' | 'spendDiamonds' | 'openHq' | 'player'>;

/** A payback for a narrow tile: days under two years, whole years to ten, then ∞. */
function paybackText(days: number): string {
  const years = days / DAYS_PER_YEAR;
  if (years > 10) return '∞';
  if (years >= 2) { const y = Math.round(years); return `${y} year${y === 1 ? '' : 's'}`; }
  const d = Math.round(days);
  return `${d} day${d === 1 ? '' : 's'}`;
}

/**
 * The deed card for a building: what it is as an HQ (its tier, and the slots it opens beside yours), three
 * tiles (cost, earnings, payback; once yours, paid, taken, earns), notes and buttons. Shared by the
 * inspector's footer and the HQ window's Estate pane (docs/hqwindow.html), so both say and do the same.
 * `selling`: the deed key whose Sell has been pressed once (the second press sells); `door:` or `firm:` and
 * the key, a rival's door or the whole rival whose Buy has been pressed once (the second press buys).
 */
export function deedCardHtml(host: DeedCtx, w: World, b: Building, selling: string): string {
  let html = '';
  const est = host.estate;
  const q = est.quote(w, b);
  const d = q.owned;
  const fleet = host.fleet;
  const o = hqOffer(fleet, est, w, b, host.diamonds());
  const notHq = !o.g.grade;
  const isHq = o.isHq;
  const rival = !d ? host.firms?.ownerOf(q.key) ?? null : null;
  // whoever else holds it, if not you: a rival firm, another player's fleet or a faction outright. Nothing to buy then
  const other = !d && !rival ? host.player?.(q.key) ?? null : null;
  const fac = !d && !rival && !other && q.faction ? buildingFactions(b.kind)[0] : undefined;
  const holder = rival ? { badge: chip(rival.livery, rival.logo), name: rival.name, hq: rival.hq.key === q.key, outright: false }
    : other ? { badge: other.brand ? chip([other.brand.primary, other.brand.accent], other.brand.logo) : '', name: other.name, hq: !!other.hq, outright: false }
      : fac ? { badge: chip([FACTIONS[fac].colour, FACTIONS[fac].accent], FACTIONS[fac].glyph), name: FACTIONS[fac].name, hq: false, outright: true }
        : null;
  const word = `<span class="word w-${q.word.replace(/\s/g, '').toLowerCase()}">${q.word}</span>`;

  // the tier: grade, name, and the slots it opens beside the ones you have
  let tier = '';
  if (!notHq) {
    const g = o.g;
    const boxes = Array.from({ length: g.slots }, (_, k) => `<i class="${k < fleet.slots ? 'have' : 'more'}"></i>`).join('');
    const diff = g.slots - fleet.slots;
    const vs = isHq ? `your HQ${fleet.hqDown ? ' · one short while boarded up' : ''}`
      : fleet.hq ? `you have ${fleet.slots} at ${esc(fleet.hq.name)} · <b class="${diff > 0 ? 'up' : diff < 0 ? 'down' : ''}">${diff > 0 ? `+${diff}` : diff < 0 ? `${diff}` : 'same'}</b>`
        : `you have no HQ · <b class="up">+${g.slots}</b>`;
    // HQs cost no diamonds now (4 Oct 2026): a line only if a charter ever comes back
    const charter = isHq || rival || o.due <= 0 ? '' : `<div class="charter">HQ charter <b class="dia">◆ ${o.due}</b></div>`;
    tier = `<div class="tier t${g.grade}">`
      + `<div class="tb"><b>${g.grade}${g.plus ? '<sup>+</sup>' : ''}</b><span>${gradePips(g.grade)}</span></div>`
      + `<div class="tn"><small>HQ tier ${g.grade} of 7</small><b>${esc(g.name)}</b><small>${vs}</small></div>`
      + `<div class="ts"><b>${g.slots}</b><small>fleet slot${g.slots === 1 ? '' : 's'}</small><span class="boxes">${boxes}</span></div>`
      + `</div>${charter}`;
  } else {
    tier = '<div class="tier none"><div class="tn"><small>Not an HQ</small><b>Scenery</b><small>it can’t house a fleet</small></div></div>';
  }

  // the three tiles: cost, earnings, payback (or, once yours: paid, taken, worth)
  const tile = (k: string, v: string, sub: string, cls = '') => `<div class="tile ${cls}"><small>${k}</small><b>${v}</b><span>${sub}</span></div>`;
  const perDay = q.perDay > 0.5 ? money(q.perDay) : '$0';
  // days while short, years once two or more, ∞ past ten years (the tile is narrow: six digits ran off it)
  const back = !Number.isFinite(q.days) ? 'never' : paybackText(q.days);
  const notes: string[] = [];
  let btns = '';
  let why: string | null = null;
  if (d) {
    const r = est.resolve(q.key);
    const down = !!r && !r.port && !!r.b.derelict;
    const sale = est.saleValue(q.key) ?? 0;
    html = tier + `<div class="tiles">`
      + tile('Paid', money(d.paid), `day ${d.day + 1}`)
      + tile('Taken', money(d.took), `${d.ins} in · ${d.outs} out`, d.took > 0 ? 'earn' : 'dim')
      + tile('Earns', `${perDay}<small>/day</small>`, `today ${money(d.today)} of ${money(d.ceil)}`, q.perDay > 0.5 ? 'earn' : 'dim')
      + `</div>`
      + `<div class="verdict">Sells for <b>${money(sale)}</b> · ${word}</div>`;
    if (q.perk) notes.push(`<span class="perk">${esc(q.perk)}</span>`);
    if (d.tax) notes.push(`${money(d.tax)} paid in levy`);
    if (down) notes.push('<em class="bad">Boarded up</em>: it pays nothing until it is mended');
    if (!notHq && !isHq && fleet.hq && o.g.slots < fleet.deployed.length) notes.push(garageNote(o.g.slots, fleet.deployed.length));
    btns = (isHq && host.openHq ? '<button type="button" data-act="hqwin" class="buy main">Open HQ</button>' : '')
      + (down ? `<button type="button" data-act="mend">Mend · ${money(est.mendCost(b))}</button>` : '')
      + (notHq || isHq ? '' : `<button type="button" data-act="hq" class="buy${o.why ? ' off' : ''}"${o.why ? ` title="${esc(o.why)}"` : ''}>Make it your HQ${o.due > 0 ? ` · ◆ ${o.due}` : ''}</button>`)
      + `<button type="button" data-act="sell" class="sell${selling === q.key ? ' armed' : ''}">${selling === q.key ? `Sure? Sell for ${money(sale)}` : `Sell for ${money(sale)}`}</button>`;
    if (!notHq && !isHq && o.why && o.why !== 'Already your HQ') why = o.why;
  } else {
    const whyBuy = est.whyNot(q);
    html = tier + `<div class="tiles">`
      + tile(holder ? 'Value' : 'Price', money(q.price), q.held ? `+${Math.round((holdingMul(q.held) - 1) * 100)}% for lots held here` : q.prestiged ? '' : 'by its trade')
      + tile('Earns', `${perDay}<small>/day</small>`, q.trades ? 'at today’s trade' : 'no goods come or go', q.perDay > 0.5 ? 'earn' : 'dim')
      + tile('Pays back', back, word, Number.isFinite(q.days) ? '' : 'dim')
      + `</div>`;
    if (q.harbour) notes.push(`Buying this buys ${esc(q.harbour.name)}: ${q.harbour.buildings.length} buildings, one set of books`);
    if (q.perk) notes.push(`<span class="perk">${esc(q.perk)}</span>`);
    if (q.derelict) notes.push('<em class="bad">Boarded up</em>: it pays nothing until it is mended');
    if (q.held) notes.push(`You hold ${q.held} lot${q.held === 1 ? '' : 's'} in ${esc(q.town)}. Each makes the next +${Math.round(ESTATE.holding * 100)}% more expensive${holdingCapped(q.held) ? ` (cap +${Math.round(ESTATE.holdingCap * 100)}%)` : ''}.`);
    if (!notHq && fleet.hq && o.g.slots < fleet.deployed.length) notes.push(garageNote(o.g.slots, fleet.deployed.length));
    if (holder) {
      // someone else's: nothing to buy, only whose it is
      btns = '';
      notes.unshift(`${holder.badge} <b>${esc(holder.name)}</b> hold${/s$/.test(holder.name) ? '' : 's'} this${holder.hq ? ' as their HQ' : holder.outright ? ' outright: not for sale' : ''}`);
      // a rival firm's (game/buyout.ts): the door off them at four times its price, or the whole firm
      if (rival && host.buyout) {
        const off = (x: string | null) => (x ? ` off" title="${esc(x)}` : '');
        const door = host.buyout.doorOffer(w, b);
        const all = host.buyout.firmOffer(rival);
        if (door && !door.whole) {
          const armed = selling === `door:${q.key}`;
          btns += `<button type="button" data-act="buyfrom" class="buy main${armed ? ' armed' : ''}${off(door.why)}"><span>${armed ? `Sure? Pay ${money(door.price)}` : `Buy from ${esc(rival.name)}`}</span><small>${money(door.price)} · ${BUYOUT.door}× its price, to their bank</small></button>`;
          why = door.why;
        }
        const armed = selling === `firm:${q.key}`;
        btns += `<button type="button" data-act="buyfirm" class="buy${door?.whole ? ' main' : ' alt'}${armed ? ' armed' : ''}${off(all.why)}"><span>${armed ? `Sure? Pay ${money(all.price)}` : 'Buy the whole fleet'}</span><small>${money(all.price)} · ${BUYOUT.firm}× their worth</small></button>`;
        notes.push(firmOfferLine(rival, all));
        why ??= all.why;
      }
    } else {
      const off = (x: string | null) => (x ? ` off" title="${esc(x)}` : '');
      const whyHq = est.whyNot(q, true);
      btns = (notHq ? '' : `<button type="button" data-act="buyhq" class="buy main${off(whyHq ?? o.why)}"><span>Buy as your HQ</span><small>${money(q.hqPrice)}${o.due > 0 ? ` + ◆ ${o.due}` : ''}</small></button>`)
        + `<button type="button" data-act="buy" class="buy${notHq ? ' main' : ' alt'}${off(whyBuy)}"><span>Buy the deed</span><small>${money(q.price)}</small></button>`;
      why = notHq ? whyBuy : whyHq ?? o.why;
    }
  }
  html += (notes.length ? `<ul class="notes">${notes.map((n) => `<li>${n}</li>`).join('')}</ul>` : '')
    + (btns ? `<div class="btns">${btns}</div>` : '')
    + (why ? `<p class="why">${esc(why)}</p>` : '');
  return html;
}

/**
 * A deed card's button, pressed: buy, buy as the HQ, make it the HQ, mend, or sell (two presses). Returns
 * what went wrong (or null) and the deed now armed to sell.
 */
export function deedAct(host: DeedCtx, w: World, b: Building, act: string, selling: string): { why: string | null; selling: string } {
  const est = host.estate;
  const key = est.keyOf(w, b);
  let why: string | null = null;
  if (act === 'hqwin') { host.openHq?.(); return { why: null, selling }; }
  // a rival's door, or the whole rival: the first press asks, the second pays
  if (act === 'buyfrom' || act === 'buyfirm') {
    const arm = `${act === 'buyfrom' ? 'door' : 'firm'}:${key}`;
    if (selling !== arm) return { why: null, selling: arm };
    const f = host.firms?.ownerOf(key);
    why = !host.buyout || !f ? 'Nobody holds it to sell' : act === 'buyfrom' ? host.buyout.buyDoor(w, b) : host.buyout.buyFirm(f);
    return { why, selling: '' };
  }
  if (act === 'buy') why = est.buy(w, b);
  else if (act === 'hq') why = makeHq(host.fleet, est, w, b, host.diamonds(), (n) => host.spendDiamonds(n, `HQ charter: ${buildingLabel(b)}`));
  else if (act === 'buyhq') {
    // the deed and the charter together, or neither: both are checked before either is paid
    const o = hqOffer(host.fleet, est, w, b, host.diamonds());
    why = est.whyNot(est.quote(w, b), true) ?? o.why ?? est.buy(w, b, true) ?? makeHq(host.fleet, est, w, b, host.diamonds(), (n) => host.spendDiamonds(n, `HQ charter: ${buildingLabel(b)}`));
  } else if (act === 'mend') why = est.mend(key);
  else if (act === 'sell') {
    if (selling !== key) return { why: null, selling: key };
    why = est.sell(key);
    return { why, selling: '' };
  }
  return { why, selling };
}

/**
 * A site's progress (the user, 5 Nov 2026): a bar in the build's three phases as they show on screen (render/construction.ts):
 * the lot cleared and the cranes going up, the frame rising in the building's shape, then topping out, when the scaffold
 * comes away and the building stands. The share done, and the time left in game hours and real time.
 */
function buildProgress(b: Building, built: number, hours: number): string {
  const total = b.buildHours ?? BUILD_HOURS;
  const left = Math.max(0, (1 - built) * total), secs = left / HOURS_PER_SECOND;
  const game = left >= 1 ? `${Math.floor(left)} h ${Math.round((left % 1) * 60)} min` : `${Math.max(1, Math.round(left * 60))} min`;
  const real = secs >= 90 ? `about ${Math.round(secs / 60)} real min` : `about ${Math.max(5, Math.round(secs / 5) * 5)} real s`;
  const phases = [
    { name: 'Clearing the lot', from: 0, to: SETUP },
    { name: 'Frame rising', from: SETUP, to: TOPPED },
    { name: 'Topping out', from: TOPPED, to: 1 },
  ];
  const now = phases.findIndex((p) => built < p.to);
  const segs = phases.map((p, i) => {
    const fill = Math.max(0, Math.min(1, (built - p.from) / (p.to - p.from)));
    return `<i class="ph${i < now ? ' done' : i === now ? ' now' : ''}" style="flex-grow:${Math.max(0.12, p.to - p.from)}" title="${p.name}"><s style="width:${Math.round(fill * 100)}%"></s></i>`;
  }).join('');
  void hours;
  return `<div class="buildbar"><div class="row"><b>Under construction</b><span>${Math.floor(built * 100)}%</span></div>`
    + `<div class="phases">${segs}</div>`
    // the real time only on hover, so the line under the bar fits on one line (the user, 6 Nov 2026)
    + `<div class="phnow"><span>Phase ${now + 1} of 3 · ${phases[now].name}</span><span title="${real}">${game} left</span></div></div>`;
}

export class Inspector {
  selected: Selection | null = null;
  /** Whether the camera is on the selected vehicle. */
  following = false;
  /** The camera has just started following one of another player's vehicles. */
  onRemoteFollow: () => void = () => {};
  /** Seconds a followed vehicle of yours has been between counties, waiting for its agent in the next one. */
  private crossWait = 0;
  /** Set when a followed vehicle has gone, for the host to say so. */
  onLost: ((what: string) => void) | null = null;
  /** A town has just been selected: the host may bring the overview round to it. */
  onTown: ((key: string) => void) | null = null;
  /**
   * A followed train has come off the line (at the end of its journey, or given up): the host may
   * offer another train near where it was to carry on watching, so the camera can ride the railway
   * for as long as anyone likes.
   */
  handOff: ((near: { x: number; z: number }, gone: Train) => Train | null) | null = null;
  /** Said when the camera has moved on from a train that went to another. */
  onHandOff: ((gone: string, next: string) => void) | null = null;
  /** Where the followed vehicle was last frame. */
  private last: { x: number; z: number } | null = null;
  /** The camera mode is up (game/photoMode.ts): the selection ring and a building's outline stay out of the picture. */
  quiet = false;
  /** More for a building's card (online: a heart for another player's HQ, net/community.ts), and a press on it. */
  buildingExtra: ((w: World, b: Building) => string) | null = null;
  /** Something small after a building's name in the header (the bookmark star); pressed, it goes to extraPress too. */
  buildingHead: ((w: World, b: Building) => string) | null = null;
  /** A card for a vehicle some other system answers for (a faction's: docs/factions.html), or null. */
  agentHook: ((a: Agent) => [string, string] | null) | null = null;
  extraPress: ((target: HTMLElement) => boolean) | null = null;

  private panel = document.createElement('div');
  private head = document.createElement('header');
  private body = document.createElement('div');
  private foot = document.createElement('footer');
  /** The deed footer on a building's card: for sale, or yours. */
  private deed = document.createElement('div');
  private deedHtml = '';
  /** The key of a lot whose Sell button has been pressed once: the second press sells. */
  private selling = '';
  private followBtn = document.createElement('button');
  /** On one of your own vehicles: its page in the HQ window. */
  private hqBtn = document.createElement('button');
  private timer = 0;
  private bodyHtml = '';
  private outline: THREE.LineSegments | null = null;
  /** The seat the pointer is over, outlined, with its tag. */
  private hoverOutline: THREE.LineSegments | null = null;
  private hoverSeat: Building | null = null;
  private hoverTag = document.createElement('div');
  private hoverAt = { x: NaN, y: NaN };
  /** The town card, which takes over from this one while a town is selected. */
  private town: TownCard | null = null;
  private ring: THREE.Mesh;
  /** Each occluding vehicle's box in its own frame, measured from its meshes (see boxOf). */
  private boxes = new WeakMap<THREE.Object3D, { box: THREE.Box3; at: number }>();
  private eye = new THREE.Vector3();
  private inv = new THREE.Matrix4();
  private ray = new THREE.Raycaster();
  private ndc = new THREE.Vector2();
  private v = new THREE.Vector3();

  constructor(private scene: THREE.Scene, private host: InspectHost) {
    this.panel.id = 'inspect';
    this.panel.className = 'hud chip';
    this.panel.hidden = true;
    const close = document.createElement('button');
    close.className = 'x';
    close.type = 'button';
    close.title = 'Close';
    close.textContent = '×';
    close.addEventListener('click', () => this.clear());
    this.followBtn.type = 'button';
    this.followBtn.className = 'follow';
    this.followBtn.addEventListener('click', () => this.setFollow(!this.following));
    this.hqBtn.type = 'button';
    this.hqBtn.className = 'follow';
    this.hqBtn.textContent = '🏢 Open in HQ';
    this.hqBtn.hidden = true;
    this.hqBtn.addEventListener('click', () => {
      const s = this.selected;
      if (s?.kind === 'agent' && s.agent.owner) this.host.openHqUnit?.(s.agent.owner);
    });
    this.foot.append(this.followBtn, this.hqBtn);
    this.deed.className = 'deed';
    this.deed.hidden = true;
    // pointerdown, not click: the footer is drawn again as its numbers move, and a click could land on a new button
    this.deed.addEventListener('pointerdown', (e) => {
      const btn = (e.target as HTMLElement).closest('button[data-act]') as HTMLElement | null;
      const s = this.selected;
      if (!btn || s?.kind !== 'building' || btn.classList.contains('off')) return;
      e.preventDefault();
      const r = deedAct(this.host, s.w, s.b, btn.dataset.act!, this.selling);
      this.selling = r.selling;
      const why = r.why;
      if (why) this.host.say(btn.dataset.act === 'buy' || btn.dataset.act === 'buyhq' || btn.dataset.act === 'buyfrom' ? 'Can’t buy it' : btn.dataset.act === 'buyfirm' ? 'Can’t buy them' : 'Not now', why);
      this.renderDeed(true);
    });
    this.head.addEventListener('pointerdown', (e) => {
      if ((e.target as HTMLElement).closest('button') && this.extraPress?.(e.target as HTMLElement)) { e.preventDefault(); this.bodyHtml = ''; this.render(); }
    });
    this.body.addEventListener('pointerdown', (e) => {
      // another player's: follow one of their vehicles (their HQ's fleet list), or go to their HQ
      const rf = (e.target as HTMLElement).closest('[data-rfollow]') as HTMLElement | null;
      if (rf) {
        e.preventDefault();
        const [pid, u] = rf.dataset.rfollow!.split('|');
        this.select({ kind: 'remote', pid, uid: u === 'own' ? null : Number(u) });
        this.setFollow(true);
        return;
      }
      const hq = (e.target as HTMLElement).closest('[data-rhq]') as HTMLElement | null;
      if (hq) { e.preventDefault(); this.host.remotes?.viewHq(hq.dataset.rhq!, hq.dataset.name ?? 'their HQ'); return; }
      // a rival's vehicle: buy the whole firm (game/buyout.ts), the first press asking, the second paying
      const bf = (e.target as HTMLElement).closest('[data-buyfirm]') as HTMLElement | null;
      if (bf) {
        e.preventDefault();
        const arm = `unit:${bf.dataset.buyfirm}`;
        const f = this.host.firms?.firm(bf.dataset.buyfirm!);
        if (bf.classList.contains('off') || !f || !this.host.buyout) return;
        if (this.selling !== arm) this.selling = arm;
        else {
          this.selling = '';
          const why = this.host.buyout.buyFirm(f);
          if (why) this.host.say('Can’t buy them', why);
        }
        this.bodyHtml = '';
        this.render();
        return;
      }
      // a stadium card's Season / History / Tours tabs (game/stadiumCard.ts)
      if (stadiumPress(e.target as HTMLElement)) { e.preventDefault(); this.bodyHtml = ''; this.render(); return; }
      if (this.extraPress?.(e.target as HTMLElement)) { e.preventDefault(); this.bodyHtml = ''; this.render(); }
    });
    // the deed first: what it is as an HQ, what it costs and what it earns, then the town's books under it
    this.panel.append(close, this.head, this.deed, this.body, this.foot);
    document.body.append(this.panel);

    // drawn over everything, so the ground never hides it; each vertex carries its own opacity, which
    // shade() drops wherever the selected vehicle stands between that part of the ring and the camera
    const ringMat = new THREE.MeshBasicMaterial({ color: HIGHLIGHT, transparent: true, vertexColors: true, depthTest: false, depthWrite: false, side: THREE.DoubleSide });
    const ringGeo = new THREE.RingGeometry(0.82, 1, RING_SEGMENTS).rotateX(-Math.PI / 2);
    const rgba = new Float32Array(ringGeo.attributes.position.count * 4).fill(1);
    for (let k = 3; k < rgba.length; k += 4) rgba[k] = RING_SEEN;
    ringGeo.setAttribute('color', new THREE.BufferAttribute(rgba, 4));
    this.ring = new THREE.Mesh(ringGeo, ringMat);
    this.ring.renderOrder = 999;
    this.ring.visible = false;
    scene.add(this.ring);
    this.hoverTag.id = 'seat-tag';
    this.hoverTag.hidden = true;
    document.body.append(this.hoverTag);
  }

  get open(): boolean { return !!this.selected; }

  /** The town card: a town selection shows it instead of this card. */
  attachTown(card: TownCard): void { this.town = card; }

  /**
   * Picked from a menu, a list or a link rather than clicked in the world: select it and put the camera
   * on it (Esc comes back to your car), since it may be anywhere.
   */
  show(sel: Selection): void {
    if (sel.kind === 'town') { this.selectTown(sel.key); this.setFollow(true); return; }
    this.select(sel);
    this.setFollow(true);
  }

  /** Select a whole town by its key, `cx,cz#id`; its island needn't be in memory. */
  selectTown(key: string): void {
    // the same town again: the camera goes to it, as a second click on a vehicle does
    if (this.selected?.kind === 'town' && this.selected.key === key) { this.setFollow(true); return; }
    this.select({ kind: 'town', key });
  }

  // ---- picking ----

  /**
   * A click on the canvas: select what is under it, or let go of the selection. Returns whether it hit something.
   * `stay` (the camera is on something else, not your car): the camera moves on to what was hit, and a click
   * that misses keeps it where it is. Before, selecting anything new stopped the follow, so a click on another
   * car while following one threw the camera back to yours (the user, 19 Oct 2026); Esc is the way home.
   */
  click(mx: number, my: number, camera: THREE.PerspectiveCamera, stay = false): boolean {
    let hit = this.pickVehicle(mx, my, camera) ?? this.pickBuilding(mx, my, camera);
    if (!hit) { if (!stay) this.clear(); return false; }
    // a town's hall stands for the whole town
    if (hit.kind === 'building') {
      const t = this.seatTown(hit.w, hit.b);
      if (t) hit = { kind: 'town', key: townKey(hit.w, t) };
    }
    // the same town again: the camera goes to it
    if (hit.kind === 'town' && this.selected?.kind === 'town' && this.selected.key === hit.key) { this.setFollow(true); return true; }
    this.select(hit);
    if (stay) this.setFollow(true);
    return true;
  }

  /** The town whose seat this building is, if it is one. */
  private seatTown(w: World, b: Building) {
    return w.towns.find((t) => t.buildings.includes(b) && seatOf(t) === b) ?? null;
  }

  /**
   * The pointer over a town's seat: the hall outlined and a tag over its roof, so it reads as the way
   * in to the whole town. Only looked for when the pointer has moved. Returns whether it is over one.
   */
  hover(mx: number, my: number, camera: THREE.PerspectiveCamera, on: boolean): boolean {
    if (!on) { this.setHover(null, null); this.hoverAt = { x: NaN, y: NaN }; return false; }
    if (mx !== this.hoverAt.x || my !== this.hoverAt.y) {
      this.hoverAt = { x: mx, y: my };
      const hit = this.pickBuilding(mx, my, camera);
      const t = hit?.kind === 'building' ? this.seatTown(hit.w, hit.b) : null;
      if (t && hit?.kind === 'building') this.setHover(hit.w, hit.b, t.name);
      else this.setHover(null, null);
    }
    if (this.hoverSeat && this.hoverOutline) {
      // the tag rides over the roof
      const top = this.hoverOutline.geometry.boundingBox?.max.y ?? 1;
      this.v.set(this.hoverOutline.position.x, this.hoverOutline.position.y + top, this.hoverOutline.position.z).project(camera);
      const x = ((this.v.x + 1) / 2) * window.innerWidth, y = ((1 - this.v.y) / 2) * window.innerHeight;
      this.hoverTag.style.transform = `translate(${Math.round(x)}px, ${Math.round(y - 8)}px) translate(-50%, -100%)`;
    }
    return !!this.hoverSeat;
  }

  private setHover(w: World | null, b: Building | null, name = ''): void {
    if (b === this.hoverSeat) return;
    this.hoverSeat = b;
    if (this.hoverOutline) {
      this.scene.remove(this.hoverOutline);
      this.hoverOutline.geometry.dispose();
      (this.hoverOutline.material as THREE.Material).dispose();
      this.hoverOutline = null;
    }
    this.hoverTag.hidden = !b;
    if (!w || !b) return;
    this.hoverOutline = this.boxOutline(w, b, 0.6);
    this.hoverOutline.geometry.computeBoundingBox();
    this.scene.add(this.hoverOutline);
    this.hoverTag.innerHTML = `<b>${esc(name)}</b><span>${esc(seatLabel(b))} · click for the whole town</span>`;
  }

  private boxOutline(w: World, b: Building, opacity: number): THREE.LineSegments {
    const [y0, y1] = this.span(w, b);
    const geo = new THREE.EdgesGeometry(new THREE.BoxGeometry(b.w + 0.08, y1 - y0, b.d + 0.08));
    const mat = new THREE.LineBasicMaterial({ color: HIGHLIGHT, depthTest: false, transparent: true, opacity });
    const line = new THREE.LineSegments(geo, mat);
    line.renderOrder = 999;
    line.position.set(w.ox + b.x + b.w / 2, (y0 + y1) / 2, w.oz + b.z + b.d / 2);
    return line;
  }

  /** Whether a vehicle is under the pointer, for the hand cursor. */
  hovering(mx: number, my: number, camera: THREE.PerspectiveCamera): boolean {
    return !!this.pickVehicle(mx, my, camera);
  }

  private pickVehicle(mx: number, my: number, camera: THREE.PerspectiveCamera): Selection | null {
    const W = window.innerWidth, H = window.innerHeight;
    // pixels per world unit at distance 1
    const scale = H / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov) / 2));
    let best: Selection | null = null, bestD = Infinity;
    const consider = (x: number, y: number, z: number, reach: number, sel: () => Selection) => {
      this.v.set(x, y, z);
      const dist = this.v.distanceTo(camera.position);
      this.v.project(camera);
      if (this.v.z > 1 || this.v.z < -1) return;
      const d = Math.hypot(((this.v.x + 1) / 2) * W - mx, ((1 - this.v.y) / 2) * H - my);
      const r = Math.max(PICK_PX, (reach * scale) / Math.max(1, dist));
      if (d < r && d < bestD) { bestD = d; best = sel(); }
    };
    for (const traffic of this.host.traffic()) {
      for (const agent of traffic.agents) {
        if (!agent.mesh.holder.visible) continue;
        const s = agent.state;
        consider(agent.w.ox + s.x, s.y + 0.15, agent.w.oz + s.z, halfSize(agent.def)[0] * 1.2, () => ({ kind: 'agent', agent, traffic }));
      }
    }
    for (const train of this.host.trains.trains) {
      if (train.player) continue;
      for (const c of train.cars) {
        if (!c.mesh || !c.mesh.group.visible) continue;
        const p = c.mesh.group.position;
        consider(p.x, p.y + 0.2, p.z, 0.7, () => ({ kind: 'train', train }));
      }
    }
    for (const flight of this.host.sky?.flights ?? []) {
      if (!flight.mesh.holder.visible) continue;
      const st = flight.st;
      consider(st.x, st.y + 0.3, st.z, flight.def.halfLen * 1.2, () => ({ kind: 'flight', flight }));
    }
    // other players: the vehicle each drives, and their fleet out on the map
    for (const r of this.host.remotes?.drawn() ?? []) {
      consider(r.x, r.y + 0.15, r.z, halfSize(r.def)[0] * 1.2, () => ({ kind: 'remote', pid: r.pid, uid: r.uid }));
    }
    return best;
  }

  /** The nearest standing building whose box the pointer's ray passes through, on any island in memory. */
  private pickBuilding(mx: number, my: number, camera: THREE.Camera): Selection | null {
    this.ndc.set((mx / window.innerWidth) * 2 - 1, -(my / window.innerHeight) * 2 + 1);
    this.ray.setFromCamera(this.ndc, camera);
    const { origin: o, direction: d } = this.ray.ray;
    let best: Selection | null = null, bestT = Infinity;
    for (const w of this.host.worlds()) {
      // the ray in this island's frame
      const ox = o.x - w.ox, oz = o.z - w.oz;
      // skip an island the ray never comes near
      if (slab(ox, o.y, oz, d, -2, -4, -2, N + 2, 80, N + 2, bestT) === null) continue;
      for (const b of w.allBuildings) {
        if (b.gone) continue;
        const [y0, y1] = this.span(w, b);
        const t = slab(ox, o.y, oz, d, b.x, y0, b.z, b.x + b.w, y1, b.z + b.d, bestT);
        if (t !== null && t < bestT) { bestT = t; best = { kind: 'building', w, b }; }
      }
    }
    return best;
  }

  /** A building's box from its pad up to its roof, in world units. */
  private span(w: World, b: Building): [number, number] {
    const ground = heightAt(w, Math.min(N - 0.01, b.x + b.w / 2), Math.min(N - 0.01, b.z + b.d / 2));
    const y0 = b.level > 0 ? Math.min(b.level * STEP, ground) : ground;
    return [y0 - 0.05, Math.max(b.level * STEP, ground) + Math.max(0.3, buildingHeight(b))];
  }

  // ---- the selection ----

  select(sel: Selection): void {
    const same = this.selected && sameThing(this.selected, sel);
    if (!same) this.setFollow(false);
    this.selected = sel;
    if (sel.kind === 'town') {
      // the town has a card of its own; this one steps aside
      this.panel.hidden = true;
      this.ring.visible = false;
      this.dropOutline();
      this.town?.show(sel.key, null, null);
      this.onTown?.(sel.key);
      return;
    }
    this.town?.hide();
    this.panel.hidden = false;
    this.panel.dataset.kind = sel.kind;
    this.foot.hidden = sel.kind === 'building';
    this.bodyHtml = '';
    this.selling = '';
    this.timer = 0;
    this.drawOutline();
    this.render();
  }

  clear(): void {
    this.selected = null;
    this.setFollow(false);
    this.town?.hide();
    this.panel.hidden = true;
    this.ring.visible = false;
    this.dropOutline();
  }

  setFollow(on: boolean): void {
    const was = this.following;
    this.following = on && !!this.selected;
    if (this.following && !was && this.selected?.kind === 'remote') this.onRemoteFollow();
    this.followBtn.textContent = this.following ? '■ Stop following' : '🎥 Follow with camera';
    this.followBtn.classList.toggle('on', this.following);
  }

  /** Where the selected vehicle is, in world units, and which way it faces; null for a building or one gone. */
  focus(): { x: number; y: number; z: number; heading: number } | null {
    const s = this.selected;
    if (s?.kind === 'agent') {
      const a = s.agent;
      return { x: a.w.ox + a.state.x, y: a.state.y, z: a.w.oz + a.state.z, heading: a.state.heading };
    }
    if (s?.kind === 'train') {
      const m = this.host.trains.middle(s.train);
      const eng = s.train.cars[0]?.mesh?.group;
      return m ? { ...m, heading: eng ? eng.rotation.y : 0 } : null;
    }
    if (s?.kind === 'flight') {
      const st = s.flight.st;
      return { x: st.x, y: st.y, z: st.z, heading: st.heading };
    }
    if (s?.kind === 'remote') {
      // not heard of yet (just picked from an HQ's list): round its owner, until the server sends where it is
      const r = this.host.remotes?.vehicle(s.pid, s.uid);
      return r ? { x: r.x, y: r.y, z: r.z, heading: r.known ? r.heading : NaN } : null;
    }
    if (s?.kind === 'building') {
      // a building faces nowhere either: the camera just goes to it
      const b = s.b, w = s.w;
      const x = b.x + b.w / 2, z = b.z + b.d / 2;
      return { x: w.ox + x, y: heightAt(w, Math.min(N - 0.01, Math.max(0, x)), Math.min(N - 0.01, Math.max(0, z))), z: w.oz + z, heading: NaN };
    }
    if (s?.kind === 'town') {
      // a town faces nowhere: NaN leaves a locked camera turned the way it was
      const c = this.town?.centre();
      if (!c) return null;
      const w = this.town?.w;
      const y = w ? heightAt(w, Math.min(N - 0.01, Math.max(0, c.x - w.ox)), Math.min(N - 0.01, Math.max(0, c.z - w.oz))) : 0;
      return { x: c.x, y, z: c.z, heading: NaN };
    }
    return null;
  }

  /** Every frame: let go of anything gone, keep the ring on a moving vehicle, and refresh the card now and then. */
  update(dt: number): void {
    const s = this.selected;
    if (!s || s.kind === 'town') return;
    const gone = s.kind === 'agent' ? !s.traffic.agents.includes(s.agent)
      : s.kind === 'train' ? !this.host.trains.trains.includes(s.train)
        : s.kind === 'flight' ? !this.host.sky?.flights.includes(s.flight)
          : s.kind === 'remote' ? !this.host.remotes?.vehicle(s.pid, s.uid)
            : !!s.b.gone || !this.host.worlds().includes(s.w);
    if (gone && s.kind === 'agent' && s.agent.owner && this.following) {
      // one of your vehicles over a county border: it drives on as a new agent in the next county's traffic
      // (game/convoy.ts). The camera stays with it; while the next county is still being made, it waits where
      // the vehicle was, a few seconds at most
      const u = this.host.fleet.unit(s.agent.owner);
      const na = u?.agent && u.agent !== s.agent ? u.agent : null;
      const nt = na ? (u?.traffic && u.traffic.agents.includes(na) ? u.traffic : this.host.traffic().find((t) => t.agents.includes(na)) ?? null) : null;
      if (na && nt) { this.crossWait = 0; this.select({ kind: 'agent', agent: na, traffic: nt }); this.setFollow(true); return; }
      if (u && this.crossWait < CROSS_WAIT) { this.crossWait += dt; return; }
    }
    if (gone) {
      this.crossWait = 0;
      const what = s.kind === 'agent' ? s.agent.def.name : s.kind === 'train' ? s.train.name
        : s.kind === 'flight' ? `${s.flight.def.name} ${s.flight.no}` : s.kind === 'remote' ? this.remoteName(s.pid, s.uid) : buildingLabel(s.b);
      const followed = this.following;
      const next = followed && s.kind === 'train' && this.last ? this.handOff?.(this.last, s.train) ?? null : null;
      if (next) {
        this.select({ kind: 'train', train: next });
        this.setFollow(true);
        this.onHandOff?.(what, next.name);
        return;
      }
      this.clear();
      if (followed || s.kind === 'building') this.onLost?.(what);
      return;
    }
    const f = this.focus();
    this.last = f ? { x: f.x, z: f.z } : this.last;
    if (this.outline) this.outline.visible = !this.quiet;
    if (this.quiet) this.ring.visible = false;
    // another player's vehicle not drawn (its county not in memory yet): no ring on the empty ground
    const rv = s.kind === 'remote' ? this.host.remotes?.vehicle(s.pid, s.uid) ?? null : null;
    if (s.kind === 'remote' && !rv?.shown) this.ring.visible = false;
    else if (f && s.kind !== 'building') {
      const r = s.kind === 'agent' ? Math.max(0.35, halfSize(s.agent.def)[0] * 1.3) : s.kind === 'flight' ? s.flight.def.halfLen * 1.3
        : rv ? Math.max(0.35, halfSize(rv.def)[0] * 1.3) : 1.6;
      this.ring.visible = !this.quiet;
      this.ring.scale.setScalar(r);
      this.ring.position.set(f.x, f.y + 0.04, f.z);
    }
    this.timer -= dt;
    if (this.timer <= 0) { this.timer = REFRESH; this.render(); }
  }

  /**
   * Just before the frame is drawn: fade the part of the selection ring the selected vehicle hides from
   * this camera. Each vertex of the ring is sighted from the camera; where the line passes through the
   * vehicle's box (every carriage near it, for a train) that vertex is drawn faint, so the ring reads as
   * lying on the ground round the vehicle rather than painted over it.
   */
  shade(camera: THREE.Camera): void {
    if (!this.ring.visible) return;
    const s = this.selected;
    const roots: THREE.Object3D[] = [];
    if (s?.kind === 'agent') roots.push(s.agent.mesh.holder);
    else if (s?.kind === 'flight') roots.push(s.flight.mesh.holder);
    else if (s?.kind === 'remote') { const r = this.host.remotes?.vehicle(s.pid, s.uid)?.root; if (r) roots.push(r); }
    else if (s?.kind === 'train') {
      // the carriages whose length reaches the ring
      const reach = this.ring.scale.x + 4;
      for (const c of s.train.cars) {
        const g = c.mesh?.group;
        if (!g) continue;
        g.getWorldPosition(this.v);
        if (Math.hypot(this.v.x - this.ring.position.x, this.v.z - this.ring.position.z) < reach + c.length / 2) roots.push(g);
      }
    }
    camera.updateMatrixWorld();
    const eye = camera.getWorldPosition(this.eye);
    const now = performance.now() / 1000;
    const tests = roots.map((r) => {
      r.updateWorldMatrix(true, true);
      const inv = new THREE.Matrix4().copy(r.matrixWorld).invert();
      return { box: this.boxOf(r, now), inv, eye: eye.clone().applyMatrix4(inv) };
    });
    this.ring.updateMatrixWorld();
    const pos = this.ring.geometry.attributes.position as THREE.BufferAttribute;
    const col = this.ring.geometry.attributes.color as THREE.BufferAttribute;
    const p = this.v, q = new THREE.Vector3();
    let changed = false;
    for (let k = 0; k < pos.count; k++) {
      p.fromBufferAttribute(pos, k).applyMatrix4(this.ring.matrixWorld);
      let hid = false;
      for (const t of tests) if ((hid = sightBlocked(t.eye, q.copy(p).applyMatrix4(t.inv), t.box))) break;
      const a = hid ? RING_HIDDEN : RING_SEEN;
      if (col.getW(k) !== a) { col.setW(k, a); changed = true; }
    }
    if (changed) col.needsUpdate = true;
  }

  /** A vehicle's bounding box in its own frame, from the meshes drawn for it, measured now and then. */
  private boxOf(root: THREE.Object3D, now: number): THREE.Box3 {
    const had = this.boxes.get(root);
    if (had && now - had.at < BOX_LIFE) return had.box;
    const box = new THREE.Box3();
    this.inv.copy(root.matrixWorld).invert();
    const m = new THREE.Matrix4();
    root.traverseVisible((o) => {
      const mesh = o as THREE.Mesh;
      if (!mesh.isMesh || !mesh.geometry) return;
      if (!mesh.geometry.boundingBox) mesh.geometry.computeBoundingBox();
      box.union(mesh.geometry.boundingBox!.clone().applyMatrix4(m.multiplyMatrices(this.inv, mesh.matrixWorld)));
    });
    this.boxes.set(root, { box, at: now });
    return box;
  }

  private drawOutline(): void {
    this.dropOutline();
    this.ring.visible = false;
    const s = this.selected;
    if (s?.kind !== 'building') return;
    this.outline = this.boxOutline(s.w, s.b, 0.95);
    this.scene.add(this.outline);
  }

  private dropOutline(): void {
    if (!this.outline) return;
    this.scene.remove(this.outline);
    this.outline.geometry.dispose();
    (this.outline.material as THREE.Material).dispose();
    this.outline = null;
  }

  // ---- the card ----

  private render(): void {
    const s = this.selected;
    if (!s) return;
    if (s.kind === 'town') return;
    const [head, card] = s.kind === 'agent' ? this.agentCard(s.agent) : s.kind === 'train' ? this.trainCard(s.train)
      : s.kind === 'flight' ? this.flightCard(s.flight) : s.kind === 'remote' ? this.remoteCard(s.pid, s.uid) : this.buildingCard(s.w, s.b);
    const body = card + (s.kind === 'building' ? this.buildingExtra?.(s.w, s.b) ?? '' : '');
    if (head !== this.head.innerHTML) this.head.innerHTML = head;
    if (body !== this.bodyHtml) { this.bodyHtml = body; this.body.innerHTML = body; }
    // a building a fleet owns wears that fleet's colour round the whole card
    this.hqBtn.hidden = !(s.kind === 'agent' && s.agent.owner && this.host.openHqUnit);
    const owner = s.kind === 'building' ? this.ownerOf(s.w, s.b) : null;
    const edge = owner ? hex(owner.look.primary) : '';
    if (this.panel.dataset.owner !== edge) {
      this.panel.dataset.owner = edge;
      this.panel.classList.toggle('owned', !!owner);
      if (owner) this.panel.style.setProperty('--owner', edge);
      else this.panel.style.removeProperty('--owner');
    }
    this.renderDeed();
  }

  /**
   * Who owns this building, if anyone does: you, another player's fleet or a rival firm, with the look of its badge
   * (and its HQ's stars, if it is one); else a faction that holds its kind outright, under its crest.
   */
  private ownerOf(w: World, b: Building): { name: string; you: boolean; look: BadgeLook; hq: boolean } | null {
    const est = this.host.estate;
    const key = est.keyOf(w, b);
    if (est.deeds.has(key)) {
      const brand = this.host.fleet.brand;
      const hq = this.host.fleet.hq?.key === key;
      const look: BadgeLook = brand ? { logo: brand.logo, primary: brand.primary, accent: brand.accent } : { logo: '★', primary: 0xd49a12, accent: 0xffffff };
      return { name: brand?.name ?? 'You', you: true, look: hq ? { ...look, stars: this.host.fleet.hq!.grade } : look, hq };
    }
    // another player's fleet: its shield and name, the same as a rival firm's, whether they are signed in or not
    const p = this.host.player?.(key);
    if (p) {
      const look: BadgeLook = p.brand ? { logo: p.brand.logo, primary: p.brand.primary, accent: p.brand.accent } : { logo: '★', primary: 0x7d8a92, accent: 0xffffff };
      return { name: p.name, you: false, look: p.hq ? { ...look, stars: p.hq } : look, hq: !!p.hq };
    }
    const f = this.host.firms?.ownerOf(key);
    if (!f) {
      // as the deed book has it (Estate.quote): a faction's kind at a port is the harbour's, not theirs
      const fac = OWNED_OUTRIGHT.has(b.kind) && !w.ports.some((p) => p.buildings.includes(b)) ? buildingFactions(b.kind)[0] : undefined;
      if (!fac) return null;
      const d = FACTIONS[fac];
      // the same shield as the faction's crest (factions/factionsTab.ts crestUrl)
      return { name: d.name, you: false, look: { logo: d.glyph, primary: d.colour, accent: d.accent }, hq: false };
    }
    const hq = f.hq.key === key;
    const look: BadgeLook = { logo: f.logo, primary: f.livery[0], accent: f.livery[1] };
    return { name: f.name, you: false, look: hq ? { ...look, stars: f.hq.grade } : look, hq };
  }

  /**
   * The deed footer. First what the building is as an HQ (its tier, and the fleet slots it opens, set
   * beside yours), then three tiles: what it costs, what it earns a day and how soon it pays for itself
   * (or, once yours, what was paid, what it has taken and what it would sell for). Notes and buttons last.
   */
  private renderDeed(force = false): void {
    const s = this.selected;
    let html = '';
    if (s?.kind === 'building') {
      if (this.selling && this.selling.slice(this.selling.indexOf(':') + 1) !== this.host.estate.keyOf(s.w, s.b)) this.selling = '';
      html = deedCardHtml(this.host, s.w, s.b, this.selling);
    }
    if (!force && html === this.deedHtml) return;
    this.deedHtml = html;
    this.deed.innerHTML = html;
    this.deed.hidden = !html;
  }

  private agentCard(a: Agent): [string, string] {
    // a touring act's bus or truck: whose tour, and where it is headed
    const tour = tourAgentCard(a);
    if (tour) return tour;
    const other = this.agentHook?.(a);
    if (other) return other;
    const rival = a.firm ? this.host.firms?.of(a) : null;
    if (rival) return this.rivalCard(a, rival.f, rival.u);
    const fleet = this.host.fleet;
    const unit = a.owner ? fleet.unit(a.owner) : null;
    const driver = unit ? fleet.driverOf(unit) : null;
    const who = unit ? `Yours · ${driver ? `driven by ${driver.name}` : 'hired driver'}` : a.run || a.hauler ? 'CPU hauler' : 'CPU traffic';
    const head = `<span class="ic">${KIND_ICON[a.def.kind]}</span><b>${esc(unit?.name ?? a.def.name)}</b><small>${esc(unit ? a.def.name : who)}</small>`;
    const rows: [string, string][] = [];
    if (unit) rows.push(['Owner', esc(who)]);
    const run = a.run, next = run?.stops[run.k];
    // one of yours carries its whole manifest, drawn under the rows
    if (unit && run) {
      rows.push(['Aboard', run.aboard.length ? `${run.aboard.map((it) => it.type.icon).join(' ')} · ${run.used}/${a.def.capacity} units` : `nothing yet · ${a.def.capacity} units free`]);
    } else if (next) {
      const it = next.item;
      rows.push(['Cargo', `${it.type.icon} ${esc(it.type.name)} · <b>${money(it.value0)}</b>`]);
      rows.push(['From', esc(it.from?.name ?? 'the roadside')]);
      rows.push(['To', esc(it.to.name)]);
    } else if (a.homing) {
      rows.push(['To', 'Back to base']);
    } else if (!unit) {
      rows.push(['From', esc(this.placeName(a.w, a.from))]);
      rows.push(['To', esc(this.placeName(a.w, a.to))]);
    }
    rows.push(['Doing', esc(this.doing(a))]);
    rows.push(['Speed', speedText(Math.abs(a.state.v) * 12)]);
    rows.push(['Where', esc(this.whereIs(a.w, a.state.x, a.state.z))]);
    if (unit) rows.push(['Status', esc(fleet.stateLine(unit))]);
    const far = unit ? this.host.furthest?.(unit.model) ?? 0 : 0;
    if (far >= 1) rows.push(['Furthest', `${esc(tilesText(far))} from home in a ${esc(a.def.name)}`]);
    if (unit?.parts?.spent) rows.push(['Parts', esc(partsLine(defOf(unit.model), unit.parts))]);
    if (treatLine(unit?.parts)) rows.push(['Passport', treatLine(unit?.parts)]);
    return [head, dl(rows) + (unit && run ? manifestList(run, a.def.capacity) : '')];
  }

  /** One of a rival firm's vehicles: whose it is, who is driving, and what it is going for — the load to beat it to. */
  private rivalCard(a: Agent, f: Firm, u: FirmUnit): [string, string] {
    const head = `<span class="ic">${KIND_ICON[a.def.kind]}</span><b>${chip(f.livery, f.logo)}${esc(f.name)}</b><small>${esc(a.def.name)} · ${esc(TRADE_LABEL[f.trade])}</small>`;
    const rows: [string, string][] = [];
    rows.push(['Owner', `${esc(f.name)} · ${esc(STAGE_LABEL[f.stage])}, ${f.units.length} ${unitWord(f, f.units.length)} · <kbd>I</kbd> Rivals`]);
    rows.push(['Driver', `${esc(u.driver.name)} · ${rankOf(u.driver)}`]);
    const run = a.run, next = run?.stops[run.k];
    if (run?.aboard.length) rows.push(['Aboard', `${run.aboard.map((it) => it.type.icon).join(' ')} · ${run.used}/${a.def.capacity} units`]);
    if (next) {
      const it = next.item;
      rows.push([next.kind === 'pickup' ? 'Going for' : 'Delivering', `${it.type.icon} ${esc(it.type.name)} · <b>${money(it.value)}</b>`]);
      rows.push([next.kind === 'pickup' ? 'At' : 'To', esc(next.kind === 'pickup' ? it.from?.name ?? 'the roadside' : it.to.name)]);
    }
    rows.push(['Doing', esc(this.doing(a))]);
    rows.push(['Speed', speedText(Math.abs(a.state.v) * 12)]);
    rows.push(['Where', esc(this.whereIs(a.w, a.state.x, a.state.z))]);
    if (u.parts.spent) rows.push(['Parts', esc(partsLine(defOf(u.model), u.parts))]);
    let buy = '';
    if (this.host.buyout) {
      const o = this.host.buyout.firmOffer(f);
      const armed = this.selling === `unit:${f.id}`;
      buy = `<p class="buyfirm"><button type="button" class="link${o.why ? ' off' : ''}" data-buyfirm="${esc(f.id)}"${o.why ? ` title="${esc(o.why)}"` : ''}>${armed ? `Sure? Pay ${money(o.price)} for ${esc(f.name)}` : `Buy the whole fleet · ${money(o.price)}`}</button>`
        + `<small>${esc(o.why ?? firmOfferLine(f, o))}</small></p>`;
    }
    return [head, dl(rows) + buy];
  }

  /**
   * One of the player's vehicles at a glance, as its card shows it: what is aboard, what it is doing and
   * the stops still to make with what each drop pays — for the fleet dock's hover bubble as well.
   */
  runHtml(a: Agent): string {
    const run = a.run;
    const rows: [string, string][] = [];
    if (run) rows.push(['Aboard', run.aboard.length ? `${run.aboard.map((it) => it.type.icon).join(' ')} · ${run.used}/${a.def.capacity} units` : `nothing yet · ${a.def.capacity} units free`]);
    rows.push(['Doing', esc(this.doing(a))]);
    return `<div class="dk-run">${dl(rows)}${run ? manifestList(run, a.def.capacity) : ''}</div>`;
  }

  private doing(a: Agent): string {
    const run = a.run, next = run?.stops[run.k];
    // one of yours on a journey of several counties (game/convoy.ts): the whole way, not just this county's leg
    const u = a.owner ? this.host.fleet.unit(a.owner) : null;
    const road = u?.road;
    const far = !!road && road.leg < road.cells.length - 1;
    const left = far && u && road ? Math.max(remaining(a), journeyLeft(u, road)) : remaining(a);
    if (far && road && a.phase !== 'parked') return `${road.to ? `On the way to ${road.to}` : 'On the way'} · ${Math.round(left).toLocaleString('en-US')} tiles to go · ${road.cells.length - 1 - road.leg} more ${road.cells.length - 1 - road.leg === 1 ? 'county' : 'counties'}`;
    if (a.phase === 'loading') return run ? (run.k > 0 ? 'Loading up' : 'Setting off to collect') : 'Setting off';
    if (a.phase === 'parked') return a.owner ? 'Waiting for work' : 'Parked, trip done';
    const tiles = left > 1 ? ` · ${Math.round(left)} tiles to go` : '';
    if (next) return `${next.kind === 'pickup' ? 'On the way to collect' : 'Delivering'}${tiles}`;
    return `On the way${tiles}`;
  }

  private trainCard(tr: Train): [string, string] {
    const d = this.host.trains.describe(tr);
    const head = `<span class="ic">🚂</span><b>${esc(tr.name)}</b><small>${esc(d.what)}</small>`;
    const rows: [string, string][] = [];
    if (tr.from) rows.push(['From', esc(tr.from)]);
    if (tr.to) rows.push([tr.freight ? 'Bound for' : 'To', esc(tr.to)]);
    if (d.line) rows.push(['Line', esc(d.line)]);
    rows.push(['Doing', esc(d.doing)]);
    rows.push(['Speed', speedText(Math.abs(tr.v) * 12)]);
    rows.push(['Cars', `${tr.cars.length}`]);
    return [head, dl(rows)];
  }

  /** A jet of the sky's traffic: its flight number, where it has come from and is bound for, and what it is doing. */
  private flightCard(f: Flight): [string, string] {
    const d = this.host.sky!.describe(f);
    // one of your hired jets: yours, with what it carries, where to and what it pays, as a road vehicle's card
    const mine = f.crew ? this.host.jet?.(f) : null;
    if (mine) {
      const head = `<span class="ic">✈️</span><b>${esc(mine.name)}</b><small>${esc(mine.model)} · your fleet</small>`;
      const rows: [string, string][] = [];
      if (d.feet > 0) rows.push(['Altitude', altText(d.feet)]);
      rows.push(['Speed', speedText(Math.abs(f.st.v) * 12)]);
      return [head, dl(rows) + jetRunHtml(mine.run)];
    }
    const head = `<span class="ic">✈️</span><b>${esc(f.no)}</b><small>${esc(f.def.name)} · CPU airliner</small>`;
    const rows: [string, string][] = [];
    rows.push(['From', esc(f.from || 'Overseas')]);
    rows.push(['To', esc(f.to || 'Overseas')]);
    rows.push(['Doing', esc(d.doing)]);
    if (d.feet > 0) rows.push(['Altitude', altText(d.feet)]);
    rows.push(['Speed', speedText(Math.abs(f.st.v) * 12)]);
    return [head, dl(rows)];
  }

  private buildingCard(w: World, b: Building): [string, string] {
    const { economy, cargo } = this.host;
    const r = economy.report(w, b);
    const port = w.ports.find((p) => p.buildings.includes(b));
    const work = w.works.find((g) => g.buildings.includes(b));
    const station = w.stations.find((st) => st.building === b);
    const home = r.via === 'town' ? r.town : w.towns.find((t) => t.buildings.includes(b));
    // an airport names the town it serves (world/airportTowns.ts)
    const airTown = work?.kind === 'airfield' && work.town !== undefined && work.town >= 0 ? w.towns[work.town] : undefined;
    const place = station ? station.name : port ? port.name : work ? (airTown ? `${work.name} · ${airTown.name}` : work.name) : home ? home.name : `Countryside · ${w.name}`;
    // owned by a fleet: its shield in the corner, and whose it is under the name
    const owner = this.ownerOf(w, b);
    const ic = owner
      ? `<img class="shield" src="${badgeUrl(owner.look, 'shield')}" alt="${esc(owner.name)}">`
      : `<span class="ic">${b.derelict ? '🏚️' : '🏢'}</span>`;
    const whose = owner ? `<small class="owner">${owner.you ? 'Yours' : `Owned by ${esc(owner.name)}`}${owner.hq ? ' · HQ' : ''}</small>` : '';
    const head = `${ic}<b>${esc(buildingLabel(b))}${this.buildingHead?.(w, b) ?? ''}</b><small>${esc(place)}</small>${whose}`;

    const rows: [string, string][] = [];
    const size = `${b.w}×${b.d} tiles${b.floors > 1 ? ` · ${b.floors} floors` : ''}`;
    const built = builtShare(b, this.host.hours());
    rows.push(['Lot', `${size}${b.derelict ? ' · <em class="bad">boarded up</em>' : built < 1 ? ` · going up${b.erected ? ' · a fleet’s own' : ''}` : b.erected ? ' · put up by a fleet' : ''}`]);
    if (home) rows.push(['Town', `${townLink(townKey(w, home), home.name)} <small>${esc(TOWN_INFO[home.kind].label)}</small>`]);
    if (b.kind === 'stadium' && home) {
      // its team, and what is on (world/stadiums.ts, game/stadiums.ts)
      const team = teamOf(home.name, undefined, home.accent), sport = SPORT_OF[stadiumDesignOf(b)];
      rows.push(['Home of', `the ${esc(team.name)} <small>${SPORT_NAME[sport]}</small>`]);
      const on = stadiumNow(w, b);
      if (on) rows.push(['On', esc(on)]);
    }
    else if (r.town) rows.push([r.via === 'harbour' ? 'Serves' : 'Near', `${townLink(townKey(w, r.town), r.town.name)} <small>${esc(TOWN_INFO[r.town.kind].label)}</small>`]);
    // a ski resort's runs, by grade (world/skiFields.ts planResort, 0.7.0)
    if (work?.resort && (b.kind === 'lodge' || b.kind === 'liftStation')) {
      const dot = { green: '🟢', blue: '🟦', black: '◆' } as const;
      const runs = (work.lifts ?? []).flatMap((l) => (l.names ?? []).map((n, k) => `${dot[l.grades![k]]} ${esc(n)}`));
      if (runs.length) rows.push(['Runs', runs.join(' · ')]);
    }

    // only what is this building's own (the user, 5 Nov 2026): its town's trade and mood ("Booming") are the town's,
    // for a town card, not this one's. Still going up: the build's progress by its phases instead.
    let econ = built < 1 && !b.derelict ? buildProgress(b, built, this.host.hours()) : '';
    if (r.trades) {
      const er: [string, string][] = [];
      {
        const l = r.lot;
        const own = l && (l.ins || l.outs || l.lost)
          ? `${perHour(r.lotRate)} · ${l.ins} in · ${l.outs} out${l.mine ? ` · ${l.mine} by you` : ''}${l.lost ? ` · <em class="bad">${l.lost} spoiled</em>` : ''}`
          : 'No deliveries or pickups here yet';
        er.push([port ? 'Harbour trade' : 'Own trade', own]);
        er.push(['Own effect', `×${r.ownFactor.toFixed(2)}${l?.value ? ` · ${money(l.value)} through the door` : ''}`]);
        if (r.tax) er.push(['Levy', `${r.tax}% on your deliveries here`]);
        const makes = icons(CARGO.filter((t) => t.from.includes(b.kind as SiteKind)).map((t) => t.icon));
        const takes = icons(CARGO.filter((t) => t.to.includes(b.kind as SiteKind)).map((t) => t.icon));
        if (makes) er.push(['Sends', makes]);
        if (takes) er.push(['Takes', takes]);
        const here = (site: { b?: Building; port: number; w: World } | null) => !!site && site.w === w && (port ? site.port === port.id : site.b === b);
        const waiting = cargo.items.filter((it) => here(it.from) && it.ttl > 0).length;
        const bound = [...cargo.items, ...cargo.hold].filter((it) => here(it.to)).length;
        if (waiting || bound) er.push(['Now', `${waiting} load${waiting === 1 ? '' : 's'} waiting · ${bound} on the way here`]);
      }
      econ += `<h4 class="own-h">This building’s trade</h4>${dl(er)}`;
    } else {
      econ += r.town ? '<p class="note">Sends and takes no goods: what it earns rides on its town’s trade.</p>' : '<p class="note">Out on its own: no town’s books, and no goods come or go.</p>';
    }
    return [head, dl(rows) + (owner?.hq && !owner.you ? this.theirFleet(w, b) : '') + (b.kind === 'stadium' && home ? stadiumSection(w, b) : '') + econ];
  }

  /** Another player's HQ: their vehicles out on the map, each with Follow (the user, 23 Oct 2026). */
  private theirFleet(w: World, b: Building): string {
    const p = this.host.player?.(this.host.estate.keyOf(w, b));
    const R = this.host.remotes;
    if (!p?.pid || !R) return '';
    const list = R.fleetOf(p.pid);
    if (!list) return `<div class="rfleet"><h4>Their fleet</h4><p class="note">${esc(p.name)} isn’t signed in: their vehicles are off the map until they are.</p></div>`;
    if (!list.length) return '';
    const rows = list.map((r) => {
      const what = r.uid === null ? 'at the wheel' : r.parked ? 'parked' : r.known && Math.abs(r.v) > 0.05 ? 'on the move' : r.known ? 'stopped' : 'out on the map';
      const where = r.known ? this.remoteWhere(r) : '';
      return `<li><span class="ic">${KIND_ICON[r.def.kind]}</span><span class="what"><b>${esc(r.def.name)}</b><small>${esc(what)}${where ? ` · ${esc(where)}` : ''}</small></span>`
        + `<button type="button" class="rf" data-rfollow="${esc(r.pid)}|${r.uid === null ? 'own' : r.uid}">🎥 Follow</button></li>`;
    }).join('');
    return `<div class="rfleet"><h4>Their fleet <small>${list.length} out</small></h4><ul>${rows}</ul></div>`;
  }

  /** Another player's vehicle: whose it is, what it is doing, how fast and where, its parts, and their HQ. */
  private remoteCard(pid: string, uid: number | null): [string, string] {
    const R = this.host.remotes;
    const r = R?.vehicle(pid, uid);
    const who = R?.who(pid);
    if (!R || !r || !who) return ['<b>Gone</b>', ''];
    const shield = who.brand ? `<img class="shield" src="${badgeUrl({ logo: who.brand.logo, primary: who.brand.primary, accent: who.brand.accent }, 'shield')}" alt="">` : `<span class="ic">${KIND_ICON[r.def.kind]}</span>`;
    const head = `${shield}<b data-pid="${esc(pid)}">${esc(who.fleet)}</b><small>${esc(r.def.name)} · ${uid === null ? `driven by ${esc(who.name)}` : 'in their fleet'}</small>`;
    const rows: [string, string][] = [];
    rows.push(['Player', `<span data-pid="${esc(pid)}" title="Right-click to add them as a friend">${esc(who.name)}</span>`]);
    rows.push(['Doing', esc(uid === null ? (r.shown && Math.abs(r.v) > 0.05 ? 'Driving' : 'At the wheel') : r.parked ? 'Parked' : !r.known ? 'Out on the map, too far off to see' : Math.abs(r.v) > 0.05 ? 'On the move' : 'Stopped')]);
    if (r.shown) rows.push(['Speed', speedText(Math.abs(r.v) * 12)]);
    if (r.known) rows.push(['Where', esc(this.remoteWhere(r))]);
    if (r.parts?.spent) rows.push(['Parts', esc(partsLine(defOf(r.def.id), r.parts))]);
    if (treatLine(r.parts)) rows.push(['Passport', treatLine(r.parts)]);
    const hq = R.hqOf(pid);
    if (hq) rows.push(['HQ', `<button type="button" class="link" data-rhq="${esc(hq.key)}" data-name="${esc(hq.name)}">${esc(hq.name)}</button>`]);
    // the rest of their fleet out, to hop to
    const others = (R.fleetOf(pid) ?? []).filter((q) => q.uid !== uid);
    const list = others.length ? `<div class="rfleet"><h4>Also out <small>${others.length}</small></h4><ul>${others.map((q) =>
      `<li><span class="ic">${KIND_ICON[q.def.kind]}</span><span class="what"><b>${esc(q.def.name)}</b><small>${q.uid === null ? 'at the wheel' : q.parked ? 'parked' : q.known ? 'out' : 'out on the map'}</small></span>`
      + `<button type="button" class="rf" data-rfollow="${esc(pid)}|${q.uid === null ? 'own' : q.uid}">🎥 Follow</button></li>`).join('')}</ul></div>` : '';
    return [head, dl(rows) + list];
  }

  /** Where another player's vehicle is, in words: the place on a county in memory, else the county's name if known. */
  remoteWhere(r: RemoteSeen): string {
    const cx = Math.floor(r.x / N), cz = Math.floor(r.z / N);
    const w = this.host.worlds().find((q) => q.cx === cx && q.cz === cz);
    return w ? this.whereIs(w, r.x - w.ox, r.z - w.oz) : `out of view (${cx}, ${cz})`;
  }

  /** "Ada's Wasabi": a player's vehicle by name, for the camera's chip and the line when it goes. */
  remoteName(pid: string, uid: number | null): string {
    const r = this.host.remotes?.vehicle(pid, uid), who = this.host.remotes?.who(pid);
    return `${who?.name ?? 'A player'}’s ${r?.def.name ?? 'vehicle'}`;
  }

  // ---- words for places ----

  /** A trip's end in words: the building and its town, a harbour, a sight, or the open sea. */
  private placeName(w: World, spot: Spot): string {
    if (spot.b) {
      const b = spot.b;
      for (const q of this.host.worlds()) {
        const t = q.towns.find((tt) => tt.buildings.includes(b));
        if (t) return `${buildingLabel(b)} · ${t.name}`;
        const p = q.ports.find((pp) => pp.buildings.includes(b));
        if (p) return `${buildingLabel(b)} · ${p.name}`;
      }
      return buildingLabel(b);
    }
    if (spot.label) return spot.label;
    if (spot.tag === 'sea') return 'The open sea';
    if (spot.offMap) return 'Beyond the horizon';
    if (spot.tag === 'beach') return `The beach · ${this.whereIs(w, spot.x, spot.z)}`;
    return this.whereIs(w, spot.x, spot.z);
  }

  /** The town a point is in or nearest, or the island's name. */
  private whereIs(w: World, x: number, z: number): string {
    const tx = Math.floor(x), tz = Math.floor(z);
    if (tx >= 0 && tz >= 0 && tx < N && tz < N) {
      const id = w.townId[tz * N + tx];
      if (id >= 0 && w.towns[id]) return w.towns[id].name;
    }
    let best = '', bestD = 40;
    for (const t of w.towns) {
      const d = Math.hypot(t.x0 + t.size / 2 - x, t.z0 + t.size / 2 - z) - t.size / 2;
      if (d < bestD) { bestD = d; best = t.name; }
    }
    return best ? `Near ${best}` : w.name || 'Open country';
  }
}

// ---------------------------------------------------------------------------------------------

function sameThing(a: Selection, b: Selection): boolean {
  if (a.kind === 'agent' && b.kind === 'agent') return a.agent === b.agent;
  if (a.kind === 'train' && b.kind === 'train') return a.train === b.train;
  if (a.kind === 'flight' && b.kind === 'flight') return a.flight === b.flight;
  if (a.kind === 'building' && b.kind === 'building') return a.b === b.b;
  if (a.kind === 'town' && b.kind === 'town') return a.key === b.key;
  if (a.kind === 'remote' && b.kind === 'remote') return a.pid === b.pid && a.uid === b.uid;
  return false;
}

function dl(rows: [string, string][]): string {
  return `<dl>${rows.map(([k, v]) => `<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl>`;
}

/**
 * A manifest as a stop list: the calls still to make in order, a pickup ▲ and a drop ▼, the hold level
 * after each, and what each drop is expected to pay. The one being driven to is highlighted.
 */
/** A hired jet's run (game/jetPilots.ts run), with each load's pay at the drop (Fleet.dropPays). */
export interface JetRun { aboard: { type: { icon: string; name: string; units: number } }[]; capacity: number; doing: string; to: string | null; pays: number[] }

/**
 * A hired jet's run as a road vehicle's reads (runHtml): what is aboard, what it is doing, and its drops with their
 * pay and the total. All its loads go to the one place, so the stops are that place's drops, the hold emptying.
 */
export function jetRunHtml(j: JetRun): string {
  const used = j.aboard.reduce((s, it) => s + it.type.units, 0);
  const rows: [string, string][] = [
    ['Aboard', j.aboard.length ? `${j.aboard.map((it) => it.type.icon).join(' ')} · ${used}/${j.capacity} units` : `nothing yet · ${j.capacity} units free`],
    ['Doing', esc(j.doing.charAt(0).toUpperCase() + j.doing.slice(1))],
  ];
  if (!j.aboard.length || !j.to) return `<div class="dk-run">${dl(rows)}</div>`;
  const place = j.to.split(' · ').slice(0, 2).join(' · ');
  let held = used;
  const items = j.aboard.map((it, n) => {
    held -= it.type.units;
    return `<li class="drop${n === 0 ? ' now' : ''}"><span class="n">${n === 0 ? 'next' : n + 1}</span><span class="k">▼</span>`
      + `<span class="w">${it.type.icon} ${esc(it.type.name)} · ${esc(place)}</span><span class="h">${held}/${j.capacity}</span>`
      + `<span class="p">${money(j.pays[n] ?? 0)}</span></li>`;
  }).join('');
  const total = j.pays.reduce((s, p) => s + p, 0);
  return `<div class="dk-run">${dl(rows)}<div class="manifest"><ol>${items}</ol><p>${j.aboard.length} drop${j.aboard.length === 1 ? '' : 's'} at ${esc(place)} · about ${money(total)} after the levy, before your cut</p></div></div>`;
}

function manifestList(r: Run, capacity: number): string {
  const left = r.stops.slice(r.k);
  if (!left.length) return '';
  const rows = left.map((st, n) => {
    const place = (st.kind === 'pickup' ? st.item.from?.name ?? 'the roadside' : st.item.to.name).split(' · ').slice(0, 2).join(' · ');
    return `<li class="${st.kind}${n === 0 ? ' now' : ''}"><span class="n">${n === 0 ? 'now' : n + 1}</span><span class="k">${st.kind === 'pickup' ? '▲' : '▼'}</span>`
      + `<span class="w">${st.item.type.icon} ${esc(st.item.type.name)} · ${esc(place)}</span><span class="h">${st.held}/${capacity}</span>`
      + `<span class="p">${st.kind === 'drop' ? money(st.pays) : ''}</span></li>`;
  }).join('');
  const total = left.reduce((s, st) => s + (st.kind === 'drop' ? st.pays : 0), 0);
  return `<div class="manifest"><ol>${rows}</ol><p>${left.length} stop${left.length === 1 ? '' : 's'} · about ${money(total)} after the levy, before your cut</p></div>`;
}

function icons(list: string[]): string {
  return [...new Set(list)].slice(0, 10).join(' ');
}

/** Tiles left along a vehicle's path, from where it is. */
function remaining(a: Agent): number {
  const p = a.path;
  if (!p.length) return 0;
  const k = Math.min(a.wp + 1, p.length - 1);
  let d = Math.hypot(p[k].x - a.state.x, p[k].z - a.state.z);
  for (let i = k; i < p.length - 1; i++) d += Math.hypot(p[i + 1].x - p[i].x, p[i + 1].z - p[i].z);
  // a leg planned ahead (a CPU hauler's run on from the goods) counts too
  for (const st of a.run?.stops.slice(a.run.k) ?? []) {
    const q = st.path;
    if (q) for (let i = 0; i < q.length - 1; i++) d += Math.hypot(q[i + 1].x - q[i].x, q[i + 1].z - q[i].z);
  }
  return d;
}

/**
 * Where a ray (origin o, direction d) enters an axis-aligned box, if it does before `maxT`: the slab test.
 * Returns the entry distance (0 when starting inside), or null for a miss.
 */
function slab(ox: number, oy: number, oz: number, d: THREE.Vector3, x0: number, y0: number, z0: number, x1: number, y1: number, z1: number, maxT: number): number | null {
  let lo = 0, hi = maxT;
  const axis = (o: number, dir: number, a: number, b: number): boolean => {
    if (Math.abs(dir) < 1e-9) return o >= a && o <= b;
    let t0 = (a - o) / dir, t1 = (b - o) / dir;
    if (t0 > t1) { const t = t0; t0 = t1; t1 = t; }
    if (t0 > lo) lo = t0;
    if (t1 < hi) hi = t1;
    return lo <= hi;
  };
  if (!axis(ox, d.x, x0, x1) || !axis(oy, d.y, y0, y1) || !axis(oz, d.z, z0, z1)) return null;
  return lo;
}

/** Dollars an hour, to the cent's tenth below ten dollars so a quiet building doesn't read $0. */
function perHour(n: number): string {
  return n < 9.95 ? `$${n.toFixed(1)}/h` : `${money(n)}/h`;
}

/** Does the line of sight from `eye` to `p` (both in the box's frame) pass through the box before reaching p? */
function sightBlocked(eye: THREE.Vector3, p: THREE.Vector3, box: THREE.Box3): boolean {
  if (box.isEmpty()) return false;
  let t0 = 0, t1 = 1;
  for (const ax of ['x', 'y', 'z'] as const) {
    const o = eye[ax], d = p[ax] - o;
    if (Math.abs(d) < 1e-9) {
      if (o < box.min[ax] || o > box.max[ax]) return false;
      continue;
    }
    let a = (box.min[ax] - o) / d, b = (box.max[ax] - o) / d;
    if (a > b) [a, b] = [b, a];
    t0 = Math.max(t0, a);
    t1 = Math.min(t1, b);
    if (t0 > t1) return false;
  }
  return t0 < 1 - 1e-4;
}

/** The fleet slots an HQ here would give, against the vehicles out on the road now: the rest are put away. */
function garageNote(slots: number, out: number): string {
  const extra = out - slots;
  return `<em class="bad">As your HQ it gives ${slots} fleet slot${slots === 1 ? '' : 's'}, and you have ${out} vehicles out: ${extra} would be parked in your garage</em>`;
}
